# ═══════════════════════════════════════════════════════════════════════════
#  SMALL UTILITIES
# ═══════════════════════════════════════════════════════════════════════════

def _n(x, default=0.0) -> float:
    """Float or default for None / NaN / inf / junk."""
    try:
        v = float(x)
        if math.isnan(v) or math.isinf(v):
            return default
        return v
    except Exception:
        return default


def et_offset_hours(utc: datetime) -> int:
    """Hours Eastern time is behind UTC at that instant (4 in daylight time, 5 in standard), by the US rule (second
    Sunday of March to the first Sunday of November, switching at 2:00 local). Only used when the time zone database
    isn't installed."""
    y = utc.year
    mar = datetime(y, 3, 8) + timedelta(days=(6 - datetime(y, 3, 8).weekday()) % 7)
    nov = datetime(y, 11, 1) + timedelta(days=(6 - datetime(y, 11, 1).weekday()) % 7)
    naive = utc.replace(tzinfo=None)
    return 4 if mar + timedelta(hours=7) <= naive < nov + timedelta(hours=6) else 5


def now_et() -> datetime:
    if _ET:
        return datetime.now(_ET)
    u = datetime.utcnow()
    return u - timedelta(hours=et_offset_hours(u))


_HOLIDAY_YEARS: Dict[int, set] = {}


def is_market_holiday(d: date) -> bool:
    """A full-day NYSE holiday (nyse_holidays' rules; half days count as sessions)."""
    if d.year not in _HOLIDAY_YEARS:
        try:
            _HOLIDAY_YEARS[d.year] = {x.date() for x in nyse_holidays(date(d.year, 1, 1), date(d.year, 12, 31))}
        except Exception:
            _HOLIDAY_YEARS[d.year] = set()
    return d in _HOLIDAY_YEARS[d.year]


def session_phase() -> str:
    """'post' after 16:15 ET on a session day, and at any time on a weekend or a market holiday; else 'intra'."""
    t = now_et()
    if t.weekday() >= 5 or is_market_holiday(t.date()):
        return "post"
    return "post" if (t.hour, t.minute) >= (16, 15) else "intra"


def last_completed_session() -> date:
    t = now_et()
    d = t.date()
    if t.weekday() < 5 and (t.hour, t.minute) < (16, 15):
        d -= timedelta(days=1)
    while d.weekday() >= 5 or is_market_holiday(d):
        d -= timedelta(days=1)
    return d


def _ncdf(x):
    """Standard normal CDF, vectorised (Abramowitz-Stegun 7.1.26, |err| < 1.5e-7)."""
    x = np.asarray(x, dtype=float)
    z = np.abs(x) / math.sqrt(2.0)
    t = 1.0 / (1.0 + 0.3275911 * z)
    y = 1.0 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t
                - 0.284496736) * t + 0.254829592) * t * np.exp(-z * z)
    return 0.5 * (1.0 + np.sign(x) * y)


def bs_call(S, K, T, sig, r=0.0):
    S, K, T, sig = (np.asarray(v, dtype=float) for v in (S, K, T, sig))
    T = np.maximum(T, 1e-6)
    sig = np.maximum(sig, 1e-6)
    d1 = (np.log(S / K) + (r + 0.5 * sig ** 2) * T) / (sig * np.sqrt(T))
    d2 = d1 - sig * np.sqrt(T)
    return S * _ncdf(d1) - K * np.exp(-r * T) * _ncdf(d2)


def bs_delta(S, K, T, sig, call=True):
    T = max(float(T), 1e-6)
    sig = max(float(sig), 1e-6)
    d1 = (math.log(S / K) + 0.5 * sig ** 2 * T) / (sig * math.sqrt(T))
    c = float(_ncdf(d1))
    return c if call else c - 1.0


def atomic_write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, indent=2, default=str), encoding="utf-8")
    os.replace(tmp, path)


def wilson(k: float, n: float, z: float = 1.96) -> Tuple[float, float]:
    if n <= 0:
        return (float("nan"), float("nan"))
    p = k / n
    den = 1 + z * z / n
    c = (p + z * z / (2 * n)) / den
    h = z * math.sqrt(p * (1 - p) / n + z * z / (4 * n * n)) / den
    return (max(0.0, c - h), min(1.0, c + h))


# ═══════════════════════════════════════════════════════════════════════════
#  HTTP (shared backoff)
# ═══════════════════════════════════════════════════════════════════════════

class PlanError(Exception):
    """401/403 — the key or plan does not cover this endpoint."""


def http_json(url: str, params: Optional[dict] = None, retries: int = 6,
              max_delay: float = 30.0, headers: Optional[dict] = None) -> Optional[dict]:
    last: Optional[str] = None
    for attempt in range(retries):
        try:
            r = requests.get(url, params=params, timeout=30, headers=headers)
        except requests.RequestException as e:
            last = f"{type(e).__name__}"
            if attempt >= 2:                 # network down or blocked: fail fast, let the fallback run
                break
            time.sleep(0.5 * (attempt + 1))
            continue
        if r.status_code in (401, 403):
            raise PlanError(f"HTTP {r.status_code}")
        if r.status_code == 404:
            return None
        if r.status_code == 429 or r.status_code >= 500:
            last = f"HTTP {r.status_code}"
            time.sleep(min(max_delay, 1.0 * 2 ** attempt) * random.uniform(0.8, 1.2))
            continue
        if r.status_code >= 400:                # not raise_for_status(): its message carries the URL, and the key with it
            raise RuntimeError(f"HTTP {r.status_code}")
        return r.json() if r.content else {}
    raise RuntimeError(f"retries exhausted ({last})")


