BAR_COLS = ["open", "high", "low", "close", "volume", "vwap"]
BAR_RETRY_S = 600.0       # a name whose download failed is tried again after this many seconds


def _massive_daily(tk: str, start: str, end: str, key: str) -> Optional[pd.DataFrame]:
    for base in MASSIVE_BASES:
        try:
            js = http_json(f"{base}/v2/aggs/ticker/{tk}/range/1/day/{start}/{end}",
                           {"adjusted": "true", "sort": "asc", "limit": 50000, "apiKey": key})
        except PlanError:
            continue
        rows = (js or {}).get("results") or []
        if not rows:
            continue
        df = pd.DataFrame(rows)
        dt = (pd.to_datetime(df["t"], unit="ms", utc=True)
              .dt.tz_convert("America/New_York").dt.tz_localize(None).dt.normalize())
        out = pd.DataFrame({
            "open": df.get("o"), "high": df.get("h"), "low": df.get("l"),
            "close": df.get("c"), "volume": df.get("v"),
            "vwap": df["vw"] if "vw" in df.columns else np.nan,
        })
        out.index = dt.values
        out = out[~out.index.duplicated(keep="last")].sort_index().astype(float)
        return out[out["close"] > 0]
    return None


def _yahoo_daily(tk: str, days: int) -> Optional[pd.DataFrame]:
    """Yahoo chart API. Uses the split-adjusted quote fields (NOT adjclose) so the
    series matches Massive's split-only adjustment; VWAP is unavailable (NaN)."""
    if "=" in tk or tk.startswith("^") or tk.endswith(".NYB"):
        sym = tk                                  # futures / index symbols pass through
    else:
        sym = tk.replace(".", "-") if "." in tk else tk
    rng = "5y" if days <= 1830 else "10y"
    try:
        r = requests.get(f"https://query1.finance.yahoo.com/v8/finance/chart/{sym}",
                         params={"interval": "1d", "range": rng},
                         headers={"User-Agent": "Mozilla/5.0 alpha-options-lab/1.0"}, timeout=25)
        r.raise_for_status()
        res = (r.json().get("chart") or {}).get("result") or []
        if not res:
            return None
        node = res[0]
        q0 = ((node.get("indicators") or {}).get("quote") or [{}])[0]
        idx = (pd.to_datetime(node.get("timestamp") or [], unit="s", utc=True)
               .tz_convert("America/New_York").tz_localize(None).normalize())
        df = pd.DataFrame({k: q0.get(k) for k in ("open", "high", "low", "close", "volume")}, index=idx)
        df["vwap"] = np.nan
        df = df.dropna(subset=["close"]).astype(float)
        df = df[~df.index.duplicated(keep="last")].sort_index()
        cutoff = pd.Timestamp(date.today() - timedelta(days=days))
        return df[df.index >= cutoff]
    except Exception:
        return None


_DEMO_LEN = 3200


@st.cache_resource(show_spinner=False)
def _demo_market_full(end_iso: str) -> Tuple[pd.DatetimeIndex, np.ndarray, np.ndarray]:
    """Shared GARCH-ish market factor so clusters / regimes have structure.
    Generated once at full length and sliced, so every ticker sees the same days."""
    n_days = _DEMO_LEN
    rng = np.random.default_rng(20240501)
    idx = pd.bdate_range(end=pd.Timestamp(end_iso), periods=n_days)
    var = np.empty(n_days)
    r = np.empty(n_days)
    v = 0.0001
    for t in range(n_days):
        shock = rng.standard_t(5) / math.sqrt(5 / 3)
        r[t] = math.sqrt(v) * shock + 0.0003
        v = 0.000002 + 0.10 * r[t] ** 2 + 0.88 * v
        var[t] = v
    rate = np.cumsum(rng.normal(0, 0.004, n_days))   # slow rates factor
    return idx, r, rate


def _demo_market(n: int) -> Tuple[pd.DatetimeIndex, np.ndarray, np.ndarray]:
    idx, r, rate = _demo_market_full(last_completed_session().isoformat())
    n = min(n, _DEMO_LEN)
    return idx[-n:], r[-n:], rate[-n:]


def _demo_daily(tk: str, days: int) -> pd.DataFrame:
    n = int(days * 252 / 365) + 5
    idx, mkt, rate = _demo_market(n)
    seed = zlib.crc32(tk.encode())
    rng = np.random.default_rng(seed)
    special = {
        "SPY": (1.0, 0.002, 560), "QQQ": (1.2, 0.003, 480), "IWM": (1.2, 0.006, 210),
        "DIA": (0.9, 0.003, 420), "SMH": (1.6, 0.008, 240), "XLK": (1.3, 0.004, 220),
        "XLF": (1.0, 0.005, 45), "XLE": (0.7, 0.010, 90), "TLT": (-0.25, 0.006, 92),
        "IEF": (-0.10, 0.003, 95), "SHY": (-0.01, 0.001, 82), "TIP": (-0.05, 0.003, 108),
        "HYG": (0.35, 0.002, 78), "LQD": (0.10, 0.003, 108), "UUP": (-0.10, 0.004, 28),
        "VIXY": (-4.0, 0.020, 14), "UVXY": (-6.0, 0.030, 22), "GLD": (0.05, 0.009, 230),
        "USO": (0.4, 0.018, 75), "DBC": (0.3, 0.009, 23), "EFA": (0.8, 0.005, 82),
        "EEM": (0.9, 0.007, 44), "MTUM": (1.1, 0.004, 200), "QUAL": (0.95, 0.003, 175),
        "VLUE": (0.9, 0.004, 105), "USMV": (0.65, 0.003, 90),
    }
    if tk in special:
        beta, idio, p0 = special[tk]
    else:
        beta = rng.uniform(0.6, 1.6)
        idio = rng.uniform(0.008, 0.024)
        p0 = float(np.exp(rng.uniform(np.log(20), np.log(700))))
    drift = rng.normal(0.0001, 0.0003)
    idr = rng.standard_t(4, n) * idio / math.sqrt(2)
    rate_beta = {"TLT": -1.2, "IEF": -0.5, "TIP": -0.4, "LQD": -0.6, "UUP": 0.3}.get(tk, 0.0)
    ret = beta * mkt + idr + drift + rate_beta * np.diff(np.r_[0.0, rate])
    if tk in ("VIXY", "UVXY"):
        ret = ret - 0.003                                   # contango decay
    lc = np.log(p0) + np.cumsum(ret)
    gap = rng.normal(0, 0.35, n) * np.abs(ret)
    c = np.exp(lc)
    o = np.exp(lc - ret + gap)
    ext = np.abs(rng.normal(0, 0.45, (n, 2))) * (np.abs(ret)[:, None] + idio * 0.6)
    h = np.maximum(o, c) * np.exp(ext[:, 0])
    l = np.minimum(o, c) * np.exp(-ext[:, 1])
    w = rng.dirichlet([2, 1, 1, 2], n)
    vw = w[:, 0] * o + w[:, 1] * h + w[:, 2] * l + w[:, 3] * c
    base_vol = float(np.exp(rng.uniform(np.log(4e5), np.log(4e7))))
    vol = base_vol * np.exp(rng.normal(0, 0.45, n) + 3.0 * np.abs(ret))
    return pd.DataFrame({"open": o, "high": h, "low": l, "close": c, "volume": vol, "vwap": vw},
                        index=idx).astype(float)


@st.cache_resource(show_spinner=False)
def _bar_store() -> dict:
    return {"lock": threading.Lock(), "bars": {}}


def _fetch_one(tk: str, days: int, source: str, key: Optional[str]) -> Tuple[Optional[pd.DataFrame], str]:
    end = date.today()
    start = end - timedelta(days=days)
    if source == "demo":
        return _demo_daily(tk, days), "demo"
    if source == "massive" and key:
        df = _massive_daily(tk, start.isoformat(), end.isoformat(), key)
        if df is not None and len(df) >= 60:
            return df, "massive"
    df = _yahoo_daily(tk, days)
    if df is not None and len(df) >= 60:
        return df, "yahoo"
    return None, "miss"


def get_bars(tickers: List[str], days: int, source: str, key: Optional[str],
             drop_partial: bool, progress=None, label: str = "") -> Tuple[Dict[str, pd.DataFrame], Dict[str, str]]:
    """Fetch (or reuse) daily bars. Store key includes the calendar date and
    whether the session had closed, so an intraday fetch is refetched after 16:15 ET."""
    store = _bar_store()
    stamp = (date.today().isoformat(), session_phase())
    want = [(tk, (tk, days, source, stamp)) for tk in tickers]
    with store["lock"]:                                     # bars from an earlier day or phase are never read again
        for k_old in [k for k in store["bars"] if k[3] != stamp]:
            del store["bars"][k_old]
        miss = store.setdefault("miss", {})
        for k_old in [k for k in miss if k[3] != stamp]:
            del miss[k_old]
    now_ = time.time()                                      # a failed download is tried again after BAR_RETRY_S, not kept
    need = [(tk, k) for tk, k in want if k not in store["bars"] and now_ - miss.get(k, 0.0) >= BAR_RETRY_S]
    done = len(want) - len(need)
    if need:
        workers = 1 if source == "demo" else (6 if source == "massive" else 4)
        with ThreadPoolExecutor(max_workers=workers) as ex:
            futs = {ex.submit(_fetch_one, tk, days, source, key): (tk, k) for tk, k in need}
            for f in as_completed(futs):
                tk, k = futs[f]
                try:
                    res = f.result()
                except Exception:
                    res = (None, "miss")
                with store["lock"]:
                    if res[0] is None or res[0].empty:
                        miss[k] = time.time()
                    else:
                        store["bars"][k] = res
                        miss.pop(k, None)
                done += 1
                if progress is not None:
                    progress.progress(min(1.0, done / max(1, len(want))), text=f"{label} {done}/{len(want)}")
    bars, src = {}, {}
    last_sess = pd.Timestamp(last_completed_session())
    for tk, k in want:
        df, s = store["bars"].get(k, (None, "miss"))
        src[tk] = s
        if df is None or df.empty:
            continue
        if drop_partial and df.index[-1] > last_sess:
            df = df[df.index <= last_sess]
        bars[tk] = df
    return bars, src


def clear_bar_store() -> None:
    store = _bar_store()
    with store["lock"]:
        store["bars"].clear()
        store.get("miss", {}).clear()


def panel_from_bars(bars: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    tickers = sorted(bars)
    P = {}
    for f in BAR_COLS:
        P[f] = pd.DataFrame({tk: bars[tk][f] for tk in tickers}).sort_index()
    return P


