def _clean_ticker(raw: Any) -> Optional[str]:
    if raw is None or (isinstance(raw, float) and math.isnan(raw)):
        return None
    s = str(raw).strip().upper().replace("$", "").replace('"', "").replace("'", "")
    if not s or s.startswith("#") or s.startswith("DOWNLOADED") or s in {
            "SYMBOL", "TICKER", "NAN", "NONE", "NULL"}:      # not "SYM": that's Symbotic
        return None
    if "." in s and not s.startswith("BRK"):
        head, tail = s.split(".", 1)
        if len(tail) <= 2 and tail.isalpha() and tail not in {"A", "B", "C"}:
            s = head
    s = s.split()[0].strip(",")
    if not s or not any(ch.isalpha() for ch in s) or len(s) > 8:
        return None
    return s


def _norm(h: str) -> str:
    return str(h or "").strip().lower().replace(" ", "_").replace("-", "_")


def _mcap_dollars(s: pd.Series, header: str = "", price: Optional[pd.Series] = None,
                  volume: Optional[pd.Series] = None) -> pd.Series:
    """Market cap in dollars. Handles 1.2B / 850M / 3.1T suffixes and Barchart's plain numbers in $ thousands.
    Plain numbers are read as thousands when the header says $K; else, with price and average volume, when reading them
    as dollars would mean more than half the company's shares trade every day; else when the median is under $100M or
    the 10th percentile under $10M (sizes that only make sense in thousands)."""
    t = s.astype(str).str.strip().str.upper().str.replace(r"[$,\s]", "", regex=True)
    mult = t.str[-1:].map({"K": 1e3, "M": 1e6, "B": 1e9, "T": 1e12})
    num = pd.to_numeric(t.where(mult.isna(), t.str[:-1]), errors="coerce")
    v = num * mult.fillna(1.0)
    plain = mult.isna() & num.notna()
    if plain.any():
        h = str(header).lower()
        if "$k" in h or "(k)" in h or "thousand" in h:
            thousands = True
        else:
            thousands = None
            if price is not None and volume is not None:
                turn = (volume / (num / price)).where(plain & (num > 0) & (price > 0)).replace([np.inf, -np.inf], np.nan).dropna()
                if len(turn):
                    thousands = bool(turn.median() > 0.5)
            if thousands is None:
                thousands = float(num[plain].median()) < 1e8 or float(num[plain].quantile(0.1)) < 1e7
        if thousands:
            v[plain] = num[plain] * 1e3
    return v


def read_universe(raw: bytes, name: str = "universe.csv") -> pd.DataFrame:
    """-> DataFrame[ticker, name, industry, theme, last, mcap] (one row per ticker)."""
    df = pd.read_csv(io.BytesIO(raw), dtype=str, on_bad_lines="skip", engine="python")
    cols = {_norm(c): c for c in df.columns}
    tcol = next((cols[c] for c in ("symbol", "ticker", "tickers", "sym") if c in cols), df.columns[0])
    out = pd.DataFrame({"ticker": df[tcol].map(_clean_ticker)})

    def col(*names):
        for n_ in names:
            if n_ in cols:
                return df[cols[n_]]
        return pd.Series([None] * len(df))

    out["name"] = col("name", "company", "description").fillna("").astype(str)
    out["industry"] = col("industry", "indclass", "gics_industry", "sector").fillna("").astype(str).str.strip()
    out["theme"] = col("theme").fillna("").astype(str).str.strip()
    out["last"] = _num(col("last", "price", "close"))
    mc = next((cols[c] for c in cols if c.startswith("market_cap") or c in ("mkt_cap", "marketcap", "mktcap")), None)
    vcol = next((cols[c] for c in ("20_day_average_volume", "20_day_avg_volume", "average_volume", "avg_volume", "volume")
                 if c in cols), None)
    out["avg_vol"] = _num(df[vcol]) if vcol is not None else np.nan
    out["mcap"] = (_mcap_dollars(df[mc], mc, out["last"], out["avg_vol"] if vcol is not None else None)
                   if mc is not None else np.nan)
    out["theme_rank"] = pd.to_numeric(col("themerank", "theme_rank"), errors="coerce")
    try:
        out = out.join(parse_barchart_columns(df, cols))
    except Exception:
        pass
    out = out.dropna(subset=["ticker"]).drop_duplicates("ticker").reset_index(drop=True)
    return out


def combine_universes(parts: List[pd.DataFrame]) -> pd.DataFrame:
    """Several screener exports -> one universe: each ticker once (first file wins), gaps filled from later files."""
    parts = [p_ for p_ in parts if p_ is not None and len(p_)]
    if not parts:
        return pd.DataFrame(columns=["ticker", "name", "industry", "theme", "last", "mcap"])
    if len(parts) == 1:
        return parts[0]
    allp = pd.concat(parts, ignore_index=True)
    txt = [c for c in ("name", "industry", "theme") if c in allp]
    allp[txt] = allp[txt].replace("", np.nan)
    out = allp.groupby("ticker", sort=False).first().reset_index()
    out[txt] = out[txt].fillna("")
    return out


def merge_barchart(uni: pd.DataFrame, extra: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    """Fill bc_* (Barchart options-view) columns from an extra export: the sidebar upload,
    or barchart_view.csv sitting next to the app."""
    src = extra
    if src is None:
        for base in (HERE, HERE / "data", Path.cwd()):
            p = base / "barchart_view.csv"
            if p.exists():
                src = read_universe(p.read_bytes(), p.name)
                break
    if src is None or src.empty:
        return uni
    bc = src.set_index("ticker")[[c for c in src.columns if c.startswith("bc_")]]
    if bc.empty:
        return uni
    for c in bc.columns:
        fill = uni["ticker"].map(bc[c])
        uni[c] = fill if c not in uni else uni[c].where(uni[c].notna(), fill)
    return uni


def find_default_universe() -> Optional[Path]:
    env = os.getenv("LAB_UNIVERSE")
    if env and Path(env).exists():
        return Path(env)
    for base in (HERE, HERE / "data", Path.cwd()):
        for fn in ("Tickers.csv", "sector_themes.csv", "watchlist_input.csv"):
            p = base / fn
            if p.exists():
                return p
    return None


def merge_themes(uni: pd.DataFrame) -> pd.DataFrame:
    """Fill missing Industry/Theme from sector_themes.csv when it sits nearby."""
    if uni["theme"].astype(bool).any() and uni["industry"].astype(bool).any():
        return uni
    for base in (HERE, HERE / "data", Path.cwd()):
        p = base / "sector_themes.csv"
        if p.exists():
            st_ = read_universe(p.read_bytes(), p.name).set_index("ticker")
            for c in ("industry", "theme"):
                fill = uni["ticker"].map(st_[c]) if c in st_.columns else None
                if fill is not None:
                    uni[c] = np.where(uni[c].astype(bool), uni[c], fill.fillna(""))
            break
    return uni


def demo_universe() -> pd.DataFrame:
    return pd.DataFrame([{"ticker": t, "name": t, "industry": i, "theme": th, "last": np.nan, "mcap": np.nan}
                         for t, i, th in DEMO_UNIVERSE])


def resolve_groups(uni: pd.DataFrame, min_group: int) -> Tuple[Dict[str, str], Dict[str, int]]:
    """Industry when it has >= min_group names; leftovers pooled by Theme (counted
    among leftovers only); anything else is ungrouped (its IND alphas are NaN)."""
    ind = {r.ticker: r.industry for r in uni.itertuples() if r.industry}
    th = {r.ticker: r.theme for r in uni.itertuples() if r.theme and r.theme.lower() != "unclassified"}
    ind_n = pd.Series(list(ind.values())).value_counts().to_dict() if ind else {}
    groups = {tk: g for tk, g in ind.items() if ind_n.get(g, 0) >= min_group}
    left = [tk for tk in uni["ticker"] if tk not in groups and tk in th]
    th_n = pd.Series([th[tk] for tk in left]).value_counts().to_dict() if left else {}
    for tk in left:
        if th_n.get(th[tk], 0) >= min_group:
            groups[tk] = f"theme:{th[tk]}"
    n_ind = sum(1 for g in groups.values() if not g.startswith("theme:"))
    return groups, {"industry": n_ind, "theme": len(groups) - n_ind,
                    "ungrouped": len(uni) - len(groups)}


UC_TECH = r"semicond|software|internet|electronics|computer|technology serv|communications comp"
UC_TARGET = {"names": 800, "grouped": 0.80, "top3": 0.35, "dv_m": 20.0, "above50_hot": 0.75, "near_hi_hot": 0.85}


def universe_check(uni: pd.DataFrame, bars: Dict[str, pd.DataFrame], min_group: int) -> Dict[str, Any]:
    """Is the list broad enough for cross-sectional ranks (RS rating, alpha percentiles, industry-neutral alphas, breadth)?"""
    _, ginfo = resolve_groups(uni, min_group)
    n = len(uni)
    ind = uni["industry"].astype(str).str.strip()
    vc = ind[ind != ""].value_counts()
    rows = []
    for tk, df in bars.items():
        c, v = df["close"].dropna(), df["volume"]
        if len(c) < 20:
            continue
        rows.append({"ticker": tk, "close": float(c.iloc[-1]), "dv_m": float((c * v).iloc[-20:].median() / 1e6),
                     "above50": float(c.iloc[-1] > c.iloc[-50:].mean()) if len(c) >= 50 else np.nan,
                     "from_hi": float(c.iloc[-1] / c.iloc[-252:].max() - 1)})
    T = pd.DataFrame(rows, columns=["ticker", "close", "dv_m", "above50", "from_hi"])
    grouped = (ginfo["industry"] + ginfo["theme"]) / max(n, 1)
    top3 = float(vc.head(3).sum() / max(n, 1))
    tech = float(ind.str.lower().str.contains(UC_TECH, regex=True).mean()) if n else np.nan
    liquid = float((T["dv_m"] >= UC_TARGET["dv_m"]).mean()) if len(T) else np.nan
    above50 = float(T["above50"].mean()) if len(T) else np.nan
    near_hi = float((T["from_hi"] >= -0.25).mean()) if len(T) else np.nan
    mc = pd.to_numeric(uni["mcap"], errors="coerce") if "mcap" in uni else pd.Series(dtype=float)
    why = []
    if n < UC_TARGET["names"]:
        why.append(f"{n} names: RS ratings and alpha percentiles rank you against a small, hand-picked field (aim for "
                   f"{UC_TARGET['names']:,}+)")
    if grouped < UC_TARGET["grouped"]:
        why.append(f"only {grouped:.0%} of names sit in a peer group (an industry or Theme with {min_group}+ names), so the "
                   "rest get no industry-neutral alphas")
    if top3 > UC_TARGET["top3"]:
        why.append(f"the three biggest industries hold {top3:.0%} of the list")
    if np.isfinite(above50) and (above50 >= UC_TARGET["above50_hot"] or near_hi >= UC_TARGET["near_hi_hot"]):
        why.append(f"{above50:.0%} of names are above their 50-day and {near_hi:.0%} within 25% of a 52-week high: the list "
                   "looks pre-filtered for strength, so breadth reads hot and the ledger's 'list' mode carries selection bias")
    if np.isfinite(liquid) and liquid < 0.6:
        why.append(f"only {liquid:.0%} trade $20M a day or more")
    verdict = "BROAD" if not why else ("NARROW" if len(why) >= 2 else "OK, ONE GAP")
    return {"n": n, "with_bars": len(T), "grouped": grouped, "grouped_ind": ginfo["industry"] / max(n, 1), "n_ind": int(len(vc)), "n_ind_ok": int((vc >= min_group).sum()),
            "top3": top3, "tech": tech, "liquid": liquid, "above50": above50, "near_hi": near_hi, "verdict": verdict,
            "why": why, "industries": vc, "ginfo": ginfo, "mcap_known": int(mc.notna().sum()),
            "mcap_med": float(mc.median()) if mc.notna().any() else np.nan, "T": T}


