def rank(df): return df.rank(axis=1, pct=True)
def delay(df, d): return df.shift(int(d))
def delta(df, d): return df - df.shift(int(d))
def ts_min(df, d): return df.rolling(int(d)).min()
def ts_max(df, d): return df.rolling(int(d)).max()
def sum_(df, d): return df.rolling(int(d)).sum()
def stddev(df, d): return df.rolling(int(d)).std()
def signedpower(df, a): return np.sign(df) * np.abs(df) ** a


def correlation(x, y, d):
    out = x.rolling(int(d)).corr(y)
    return out.replace([np.inf, -np.inf], np.nan).clip(-1.0, 1.0)


def scale(df, a=1.0):
    return df.div(df.abs().sum(axis=1).replace(0, np.nan), axis=0) * a


def ts_rank(df, d):
    """Share of the other d-1 values in the window strictly below today (0..1).
    Same definition as the original rolling.apply, at C speed."""
    d = int(d)
    return (df.rolling(d).rank(method="min") - 1.0) / (d - 1)


def _window_reduce(df: pd.DataFrame, d: int, fn, chunk: int = 128) -> pd.DataFrame:
    """Apply fn(windows[T-d+1, n, d]) -> [T-d+1, n] over column chunks; NaN if the
    window contains any NaN (matches rolling(d) min_periods=d)."""
    a = df.to_numpy(dtype=float)
    out = np.full(a.shape, np.nan)
    if len(a) >= d:
        for j in range(0, a.shape[1], chunk):
            w = np.lib.stride_tricks.sliding_window_view(a[:, j:j + chunk], d, axis=0)
            bad = np.isnan(w).any(axis=2)
            res = fn(w).astype(float)
            res[bad] = np.nan
            out[d - 1:, j:j + chunk] = res
    return pd.DataFrame(out, index=df.index, columns=df.columns)


def ts_argmax(df, d):
    """Days since the window maximum (0 = today)."""
    d = int(d)
    return _window_reduce(df, d, lambda w: (d - 1 - np.argmax(np.nan_to_num(w, nan=-np.inf), axis=2)))


def decay_linear(df, d):
    d = int(d)
    wts = np.arange(1, d + 1, dtype=float)
    wts /= wts.sum()
    return _window_reduce(df, d, lambda w: np.einsum("tnd,d->tn", np.nan_to_num(w), wts))


def cond(mask, *operands):
    """Boolean -> 1.0/0.0, NaN wherever an operand is NaN (warm-up)."""
    out = mask.astype(float)
    for o in operands:
        if isinstance(o, pd.DataFrame):
            out = out.mask(o.isna())
    return out


def iif(c, a, b):
    a_df = a if isinstance(a, pd.DataFrame) else pd.DataFrame(float(a), index=c.index, columns=c.columns)
    b_df = b if isinstance(b, pd.DataFrame) else pd.DataFrame(float(b), index=c.index, columns=c.columns)
    cf = c.astype(float)
    return a_df.where(cf == 1.0, b_df).mask(cf.isna())


class AlphaCtx:
    def __init__(self, P: Dict[str, pd.DataFrame], groups: Dict[str, str],
                 price_neutral: bool = True, min_group: int = 5):
        self.P, self.groups, self.pn, self.min_group = P, groups, price_neutral, min_group
        self.o, self.h, self.l, self.c = P["open"], P["high"], P["low"], P["close"]
        self.v, self.vw = P["volume"], P["vwap"]
        self.ret = self.c / self.c.shift(1) - 1.0
        self.adv20_sh = self.v.rolling(20).mean()
        self.adv40 = (self.c * self.v).rolling(40).mean()

    def pdelta(self, df, d):
        return (df / df.shift(int(d)) - 1.0) if self.pn else delta(df, d)

    def pgap(self, a, b):
        return (a / b - 1.0) if self.pn else (a - b)

    def indneutralize(self, df):
        gm = pd.Series({tk: self.groups.get(tk) for tk in df.columns}, dtype=object).dropna()
        out = pd.DataFrame(np.nan, index=df.index, columns=df.columns)
        for _, cols in gm.groupby(gm).groups.items():
            cols = [c for c in cols if c in df.columns]
            if len(cols) < self.min_group:
                continue
            sub = df[cols]
            out[cols] = sub.sub(sub.mean(axis=1), axis=0)
        return out


def _a1(x):
    v = iif(cond(x.ret < 0, x.ret), stddev(x.ret, 20), x.c)
    return rank(ts_argmax(signedpower(v, 2.0), 5)) - 0.5
def _a2(x):
    a = rank(delta(np.log(x.v.replace(0, np.nan)), 2))
    return -1 * correlation(a, rank((x.c - x.o) / x.o), 6)
def _a4(x): return -1 * ts_rank(rank(x.l), 9)
def _a5(x):
    return rank(x.pgap(x.o, sum_(x.vw, 10) / 10)) * (-1 * rank(x.pgap(x.c, x.vw)).abs())
def _a6(x): return -1 * correlation(x.o, x.v, 10)
def _a7(x):
    a = (-1 * ts_rank(delta(x.c, 7).abs(), 60)) * np.sign(delta(x.c, 7))
    return iif(cond(x.adv20_sh < x.v, x.adv20_sh, x.v), a, -1.0)
def _a8(x):
    s = sum_(x.o, 5) * sum_(x.ret, 5)
    return -1 * rank(s - delay(s, 10))
def _a9(x):
    d1 = x.pdelta(x.c, 1)
    lo, hi = ts_min(d1, 5), ts_max(d1, 5)
    return iif(cond(0 < lo, lo), d1, iif(cond(hi < 0, hi), d1, -1 * d1))
def _a10(x):
    d1 = x.pdelta(x.c, 1)
    lo, hi = ts_min(d1, 4), ts_max(d1, 4)
    return rank(iif(cond(0 < lo, lo), d1, iif(cond(hi < 0, hi), d1, -1 * d1)))
def _a11(x):
    g = x.pgap(x.vw, x.c)
    return (rank(ts_max(g, 3)) + rank(ts_min(g, 3))) * rank(delta(x.v, 3))
def _a12(x): return np.sign(delta(x.v, 1)) * (-1 * x.pdelta(x.c, 1))
def _a18(x):
    oc = (x.c - x.o).abs()
    return -1 * rank(stddev(oc, 5) + (x.c - x.o) + correlation(x.c, x.o, 10))
def _a19(x):
    a = -1 * np.sign((x.c - delay(x.c, 7)) + delta(x.c, 7))
    return a * (1 + rank(1 + sum_(x.ret, 250)))
def _a20(x):
    return ((-1 * rank(x.pgap(x.o, delay(x.h, 1)))) * rank(x.pgap(x.o, delay(x.c, 1)))
            * rank(x.pgap(x.o, delay(x.l, 1))))
def _a23(x):
    m20 = sum_(x.h, 20) / 20
    return iif(cond(m20 < x.h, m20), -1 * x.pdelta(x.h, 2), 0.0)
def _a24(x):
    m100 = sum_(x.c, 100) / 100
    chg = delta(m100, 100) / delay(x.c, 100)
    return iif(cond(chg <= 0.05, chg), -1 * x.pgap(x.c, ts_min(x.c, 100)), -1 * x.pdelta(x.c, 3))
def _a30(x):
    s = (np.sign(x.c - delay(x.c, 1)) + np.sign(delay(x.c, 1) - delay(x.c, 2))
         + np.sign(delay(x.c, 2) - delay(x.c, 3)))
    return ((1.0 - rank(s)) * sum_(x.v, 5)) / sum_(x.v, 20)
def _a32(x):
    return scale((sum_(x.c, 7) / 7) - x.c) + 20 * scale(correlation(x.vw, delay(x.c, 5), 230))
def _a33(x): return rank(-1 * (1 - (x.o / x.c)))
def _a34(x):
    return rank((1 - rank(stddev(x.ret, 2) / stddev(x.ret, 5))) + (1 - rank(x.pdelta(x.c, 1))))
def _a41(x): return x.pgap((x.h * x.l) ** 0.5, x.vw)
def _a42(x):
    if x.pn:
        return rank(x.pgap(x.vw, x.c))
    return rank(x.vw - x.c) / rank(x.vw + x.c)
def _a43(x): return ts_rank(x.v / x.adv20_sh, 20) * ts_rank(-1 * delta(x.c, 7), 8)
def _a48(x):
    d1, dd1 = delta(x.c, 1), delta(delay(x.c, 1), 1)
    num = x.indneutralize((correlation(d1, dd1, 250) * d1) / x.c)
    return num / sum_((delta(x.c, 1) / delay(x.c, 1)) ** 2, 250)
def _a52(x):
    m5 = ts_min(x.l, 5)
    a = x.pgap(delay(m5, 5), m5)
    b = rank((sum_(x.ret, 240) - sum_(x.ret, 20)) / 220)
    return a * b * ts_rank(x.v, 5)
def _a53(x):
    return -1 * delta(((x.c - x.l) - (x.h - x.c)) / (x.c - x.l).replace(0, np.nan), 9)
def _a57(x): return -1 * ((x.c - x.vw) / decay_linear(rank(ts_argmax(x.c, 30)), 2))
def _a82(x):
    a = rank(decay_linear(x.pdelta(x.o, 1), 14))
    b = ts_rank(decay_linear(correlation(x.indneutralize(x.v), x.o, 17), 6), 13)
    return np.minimum(a, b) * -1
def _a90(x):
    a = rank(x.pgap(x.c, ts_max(x.c, 4)))
    b = ts_rank(correlation(x.indneutralize(x.adv40), x.l, 5), 3)
    return (a ** b) * -1
def _a101(x): return (x.c - x.o) / ((x.h - x.l) + 0.001)


ALPHA_FUNCS = {1: _a1, 2: _a2, 4: _a4, 5: _a5, 6: _a6, 7: _a7, 8: _a8, 9: _a9, 10: _a10,
               11: _a11, 12: _a12, 18: _a18, 19: _a19, 20: _a20, 23: _a23, 24: _a24,
               30: _a30, 32: _a32, 33: _a33, 34: _a34, 41: _a41, 42: _a42, 43: _a43,
               48: _a48, 52: _a52, 53: _a53, 57: _a57, 82: _a82, 90: _a90, 101: _a101}


def compute_alphas(P, groups, price_neutral=True, min_group=5, ids=None) -> Dict[int, pd.DataFrame]:
    x = AlphaCtx(P, groups, price_neutral, min_group)
    out = {}
    for aid in (ids or sorted(ID_TO_CAT)):
        try:
            out[aid] = ALPHA_FUNCS[aid](x).replace([np.inf, -np.inf], np.nan)
        except Exception as e:  # keep the app alive if one alpha breaks
            out[aid] = pd.DataFrame(np.nan, index=P["close"].index, columns=P["close"].columns)
            print(f"alpha #{aid} failed: {e}")
    return out


def composite_frames(A: Dict[int, pd.DataFrame]) -> Dict[str, Any]:
    """Vectorised composite over all dates (identical per date to the scripts'
    score_ticker): category = mean of selected alpha percentiles, MRV inverted,
    raw = weighted mean over present categories, pct = daily cross-sectional rank."""
    pct = {aid: A[aid].rank(axis=1, pct=True) * 100.0 for aid in SELECTED if aid in A}
    ref = next(iter(pct.values()))
    cats = {}
    for cat, ids in SELECTED_IDS.items():
        frames = [pct[i].to_numpy() for i in ids if i in pct]
        if frames:
            with np.errstate(all="ignore"):
                m = np.nanmean(np.stack(frames), axis=0)
            cats[cat] = pd.DataFrame(m, index=ref.index, columns=ref.columns)
    num = pd.DataFrame(0.0, index=ref.index, columns=ref.columns)
    den = pd.DataFrame(0.0, index=ref.index, columns=ref.columns)
    for cat, w in CATEGORY_WEIGHTS.items():
        if cat not in cats:
            continue
        v = cats[cat]
        sup = (100.0 - v) if cat == "MRV" else v
        num += (w * sup).fillna(0.0)
        den += v.notna() * w
    raw = num / den.replace(0.0, np.nan)
    comp = raw.rank(axis=1, pct=True) * 100.0
    return {"pct": pct, "cats": cats, "raw": raw, "composite": comp}


def alpha_snapshot(A, frames) -> pd.DataFrame:
    """Last-date features per ticker -> table."""
    last = frames["composite"].index[-1]
    df = pd.DataFrame(index=frames["composite"].columns)
    df["composite"] = frames["composite"].loc[last]
    df["raw"] = frames["raw"].loc[last]
    for cat in CAT_ORDER:
        df[f"cat_{cat}"] = frames["cats"][cat].loc[last] if cat in frames["cats"] else np.nan
    for aid in sorted(A):
        row = A[aid].loc[last]
        df[f"a{aid}"] = row
        df[f"a{aid}_pct"] = row.rank(pct=True) * 100.0
    return df


# ═══════════════════════════════════════════════════════════════════════════
#  CALIBRATION  (composite -> forward path statistics)
# ═══════════════════════════════════════════════════════════════════════════

CAL_BUCKETS = [(0, 40, "0-40 fade"), (40, 50, "40-50 below mid"), (50, 60, "50-60 mid"),
               (60, 70, "60-70 B-setup"), (70, 80, "70-80 A-setup"), (80, 101, "80-100 top tape")]
CAL_WIDTHS = (0.5, 2.0, 3.0, 5.0)


def _fwd_extreme(df: pd.DataFrame, h: int, how: str) -> pd.DataFrame:
    """max/min over t+1..t+h (skips NaN inside the window)."""
    rev = df.iloc[::-1].rolling(h, min_periods=1)
    agg = rev.max() if how == "max" else rev.min()
    return agg.iloc[::-1].shift(-1)


def calibrate(comp: pd.DataFrame, P: Dict[str, pd.DataFrame], horizon: int = 5,
              warmup: int = 260, entry: str = "next_open", barrier: float = 0.03) -> Dict[str, Any]:
    c, hi, lo, op = P["close"], P["high"], P["low"], P["open"]
    comp = comp.reindex(index=c.index, columns=c.columns)
    E = op.shift(-1) if entry == "next_open" else c
    fh, fl = _fwd_extreme(hi, horizon, "max"), _fwd_extreme(lo, horizon, "min")
    end = c.shift(-horizon)
    ret = (end / E - 1.0) * 100.0
    mfe = (fh / E - 1.0) * 100.0
    mae = (1.0 - fl / E) * 100.0
    rngp = (fh - fl) / E * 100.0
    sig20 = np.log(c).diff().rolling(20).std()
    mfe_sig = (fh / E - 1.0) / (sig20 * math.sqrt(horizon))
    up_first = pd.DataFrame(np.inf, index=c.index, columns=c.columns)
    dn_first = up_first.copy()
    for k in range(1, horizon + 1):
        up_k = (hi.shift(-k) >= E * (1 + barrier)).to_numpy()
        dn_k = (lo.shift(-k) <= E * (1 - barrier)).to_numpy()
        u, d = up_first.to_numpy(), dn_first.to_numpy()
        up_first = pd.DataFrame(np.where(np.isinf(u) & up_k, k, u), index=c.index, columns=c.columns)
        dn_first = pd.DataFrame(np.where(np.isinf(d) & dn_k, k, d), index=c.index, columns=c.columns)
    # a same-day double touch counts as down-first (conservative)
    up_before = (up_first < dn_first).astype(float)

    n = len(c.index)
    lo_i, hi_i = warmup, n - horizon - 1
    if hi_i <= lo_i:
        return {"error": f"Need more history: {n} sessions, warm-up {warmup}, horizon {horizon}."}
    sl = slice(lo_i, hi_i)
    M = {"composite": comp, "fwd_ret_pct": ret, "range_pct": rngp, "mfe_pct": mfe,
         "mae_pct": mae, "mfe_sigma": mfe_sig, "up_first": up_before}
    arr = {k: v.iloc[sl].to_numpy(dtype=float) for k, v in M.items()}
    mask = np.isfinite(arr["composite"]) & np.isfinite(arr["fwd_ret_pct"]) & np.isfinite(arr["mfe_pct"])
    ri, ci = np.nonzero(mask)
    dates = c.index[sl][ri]
    df = pd.DataFrame({"date": dates, "ticker": c.columns[ci]})
    for k, v in arr.items():
        df[k] = v[ri, ci]
    df["close_up"] = (df["fwd_ret_pct"] > 0).astype(float)
    for w in CAL_WIDTHS:
        df[f"mfe_ge_{w:g}"] = (df["mfe_pct"] >= w).astype(float)
    df["bucket"] = pd.cut(df["composite"], [b[0] for b in CAL_BUCKETS] + [101],
                          labels=[b[2] for b in CAL_BUCKETS], right=False)
    df["xs_up"] = df["close_up"] - df.groupby("date")["close_up"].transform("mean")
    df["xs_ret"] = df["fwd_ret_pct"] - df.groupby("date")["fwd_ret_pct"].transform("mean")
    step_dates = set(c.index[sl][::horizon])
    return {
        "overlap": _cal_summary(df, "overlapping"),
        "nonoverlap": _cal_summary(df[df["date"].isin(step_dates)], "non-overlapping"),
        "daily": df.groupby(["date", "bucket"], observed=True).agg(
            n=("ticker", "size"), close_up=("close_up", "mean"), median_mfe=("mfe_pct", "median")
        ).reset_index(),
        "meta": {"score_start": str(c.index[lo_i].date()), "score_end": str(c.index[hi_i - 1].date()),
                 "n_dates": int(hi_i - lo_i), "n_name_days": int(len(df)), "horizon": horizon,
                 "warmup": warmup, "entry": entry, "barrier": barrier},
    }


def _cal_summary(df: pd.DataFrame, label: str) -> pd.DataFrame:
    out = []
    for lo, hi, name in CAL_BUCKETS:
        sub = df[df["bucket"] == name]
        n = int(len(sub))
        rec = {"sample": label, "bucket": name, "n": n,
               "n_names": int(sub["ticker"].nunique()) if n else 0,
               "n_dates": int(sub["date"].nunique()) if n else 0}
        if n >= 30:
            rec["close_up"] = float(sub["close_up"].mean())
            per_day = sub.groupby("date")["xs_up"].mean()
            rec["excess_up"] = float(per_day.mean())
            rec["t_excess"] = float(per_day.mean() / (per_day.std(ddof=1) / math.sqrt(len(per_day)))) \
                if len(per_day) > 2 and per_day.std(ddof=1) > 0 else np.nan
            per_ret = sub.groupby("date")["xs_ret"].mean()
            rec["excess_ret_pct"] = float(per_ret.mean())
            rec["excess_ret_se"] = float(per_ret.std(ddof=1) / math.sqrt(len(per_ret))) if len(per_ret) > 2 else np.nan
            rec["median_fwd_ret_pct"] = float(sub["fwd_ret_pct"].median())
            rec["median_range_pct"] = float(sub["range_pct"].median())
            rec["median_mfe_pct"] = float(sub["mfe_pct"].median())
            rec["median_mae_pct"] = float(sub["mae_pct"].median())
            rec["median_mfe_sigma"] = float(sub["mfe_sigma"].median())
            rec["p_up_first"] = float(sub["up_first"].mean())
            for w in CAL_WIDTHS:
                rec[f"p_mfe_ge_{w:g}"] = float(sub[f"mfe_ge_{w:g}"].mean())
            up, hit3 = rec["close_up"], rec.get("p_mfe_ge_3", 0)
            if up >= 0.55 and hit3 >= 0.55:
                rec["size_vs_unit"], rec["size_note"] = 1.0, "A - full unit"
            elif up >= 0.52 and hit3 >= 0.45:
                rec["size_vs_unit"], rec["size_note"] = 0.6, "B - 0.6x unit"
            else:
                rec["size_vs_unit"], rec["size_note"] = 0.0, "skip / research only"
        out.append(rec)
    return pd.DataFrame(out)


# ═══════════════════════════════════════════════════════════════════════════
#  MANDELBROT CLUSTER (shared by index page, name stack, strike/hit)
# ═══════════════════════════════════════════════════════════════════════════

def _walk(raw: np.ndarray, cool: np.ndarray, hyst: int = 3) -> Tuple[np.ndarray, np.ndarray]:
    """Sticky QUIET(0)/ACTIVE(1): enter ACTIVE after 2 raw days, return to QUIET
    after `hyst` cool days; anything in between keeps the current state."""
    cur = pending = pending_to = state = age = 0
    states = np.zeros(len(raw), dtype=np.int8)
    ages = np.zeros(len(raw), dtype=np.int32)
    for i in range(len(raw)):
        want = 1 if raw[i] else (0 if cool[i] else cur)
        if want != cur:
            if want == pending_to:
                pending += 1
            else:
                pending_to, pending = want, 1
            if pending >= (2 if want == 1 else hyst):
                cur, pending = want, 0
        else:
            pending = 0
        age = age + 1 if state == cur else 1
        state = cur
        states[i], ages[i] = state, age
    return states, ages


def cluster_frame(px: pd.Series, large_k: float, hv_on: float, hv_off: float,
                  on_n: int = 3, off_n: int = 1, hyst: int = 3,
                  vol_gate: str = "absolute") -> pd.DataFrame:
    """Large-move clustering on one price series. vol_gate='relative' swaps the
    absolute HV20 cut-offs for the name's own 1y HV20 percentile (on >= 90th,
    cool < 60th)."""
    px = px.dropna().astype(float)
    r = np.log(px).diff()
    sig = r.rolling(252, min_periods=80).std().shift(1)      # lagged: today's move can't shrink its own z
    z = r / sig.replace(0, np.nan)
    large = (z.abs() >= large_k).astype(float)
    n20 = large.rolling(20, min_periods=10).sum()
    n60 = large.rolling(60, min_periods=20).sum()
    hv = r.rolling(20).std() * math.sqrt(252)
    f = pd.DataFrame({"px": px, "r": r, "z": z, "large": large, "n20": n20, "n60": n60, "hv20": hv})
    if vol_gate == "relative":
        hv_pct = hv.rolling(252, min_periods=126).rank(pct=True)
        f["hv_pct"] = hv_pct
        f = f.dropna(subset=["n20", "hv20", "z", "hv_pct"])
        raw = (f["n20"].to_numpy() >= on_n) | (f["hv_pct"].to_numpy() >= 0.90)
        cool = (f["n20"].to_numpy() <= off_n) & (f["hv_pct"].to_numpy() < 0.60)
    else:
        f = f.dropna(subset=["n20", "hv20", "z"])
        raw = (f["n20"].to_numpy() >= on_n) | (f["hv20"].to_numpy() >= hv_on)
        cool = (f["n20"].to_numpy() <= off_n) & (f["hv20"].to_numpy() < hv_off)
    s, a = _walk(raw, cool, hyst)
    f["cluster"] = np.where(s == 1, "ACTIVE", "QUIET")
    f["age"] = a
    return f


def robust_z_series(r: pd.Series) -> pd.Series:
    x = r.dropna()
    med = float(np.median(x)) if len(x) else 0.0
    mad = float(np.median(np.abs(x - med))) if len(x) else 0.0
    sd = 1.4826 * mad if mad > 0 else float(x.std() or 1e-8)
    return ((x - med) / sd)


def gaussian_compare(r: pd.Series) -> Dict[str, Any]:
    x = r.dropna().astype(float)
    x = x[np.isfinite(x)]
    if len(x) < 100:
        return {"n": 0}
    z = robust_z_series(x)
    emp = {k: float((z.abs() >= t).mean()) for k, t in (("gt2", 2), ("gt3", 3), ("gt4", 4))}
    g = {"gt2": 2 * (1 - 0.97725), "gt3": 2 * (1 - 0.99865), "gt4": 2 * 3.17e-5}
    bins = np.linspace(-5, 5, 31)
    hist, edges = np.histogram(z.clip(-5, 5), bins=bins, density=True)
    mid = 0.5 * (edges[:-1] + edges[1:])
    return {"n": int(len(x)), "emp": emp, "gauss": g,
            "ratio2": emp["gt2"] / g["gt2"], "ratio3": emp["gt3"] / g["gt3"], "ratio4": emp["gt4"] / g["gt4"],
            "hist": pd.DataFrame({"z": mid, "empirical": hist,
                                  "normal": np.exp(-0.5 * mid ** 2) / math.sqrt(2 * math.pi)}),
            "kurt": float(pd.Series(z).kurtosis())}


