#  MANDELBROT INDEX PAGE (Hedgeye companions)
# ═══════════════════════════════════════════════════════════════════════════

def _ls_index(c: pd.DataFrame, longs: List[str], shorts: List[str]) -> Optional[pd.Series]:
    have_l = [t for t in longs if t in c.columns]
    have_s = [t for t in shorts if t in c.columns]
    if not have_l or not have_s:
        return None
    lr = pd.concat([np.log(c[t]).diff() for t in have_l], axis=1).mean(axis=1)
    sr = pd.concat([np.log(c[t]).diff() for t in have_s], axis=1).mean(axis=1)
    return (lr - sr).cumsum()


BASKETS = [
    ("Flight to quality", "ftq", ["TLT", "GLD", "USMV", "LQD"], ["SPY", "HYG"],
     "Should rise in 2008-style stress. Flat with offered TLT is the 2022 fork."),
    ("Melt-up / WOI", "woi_b", ["QQQ", "SMH", "MTUM", "IWM"], ["USMV", "TLT"],
     "Leads in fragile risk-on. A lead with loud HV20 is WOI-shaped."),
    ("1970s inflation", "infl70", ["DBC", "TIP", "USO"], ["UUP", "TLT"],
     "Confirm only with a weak dollar. Not a Quad name."),
    ("Oil bid / rates", "oilbid", ["USO", "XLE"], ["UUP", "TLT"],
     "Crude and energy equity versus dollar and duration."),
    ("2022 rates", "rates22", ["UUP"], ["TLT", "TIP"],
     "Strong USD and a duration dump. Same inflation tell, opposite dollar."),
    ("Slow leak", "leak", ["SPY", "QUAL"], ["IWM", "MTUM"],
     "Narrow quality tape: index holds, size and momentum lag, vol quiet."),
]


def build_baskets(c: pd.DataFrame) -> Tuple[pd.DataFrame, List[Dict[str, Any]]]:
    series, rows = {}, []
    for name, key, longs, shorts, read in BASKETS:
        s = _ls_index(c, longs, shorts)
        if s is None:
            continue
        series[name] = s
        rows.append({"basket": name, "legs": f"long {'+'.join(longs)} / short {'+'.join(shorts)}",
                     "r20": _n(s.iloc[-1] - s.iloc[-21]) if len(s.dropna()) > 21 else 0.0, "read": read})
    return pd.DataFrame(series), rows


def mandelbrot_page(c: pd.DataFrame) -> Dict[str, Any]:
    spy = c["SPY"].dropna()
    f = cluster_frame(spy, large_k=2.0, hv_on=0.22, hv_off=0.16)
    f["dd"] = f["px"] / f["px"].cummax() - 1.0
    absr = f["r"].abs()
    f["abs_ac1"] = absr.rolling(60, min_periods=30).corr(absr.shift(1))
    for n_ in (10, 15, 20, 63, 252):
        f[f"sma{n_}"] = spy.rolling(n_).mean().reindex(f.index)
    f["trade"] = np.where(f["px"] >= f["sma15"], "BULL", "BEAR")
    f["trend"] = np.where(f["px"] >= f["sma63"], "BULL", "BEAR")
    f["tail"] = np.where(f["px"] >= f["sma252"], "BULL", "BEAR")

    def r20(t):
        return float(np.log(c[t]).diff(20).reindex(f.index).iloc[-1]) if t in c.columns else 0.0

    def rel_z(num, den):
        if num not in c.columns or den not in c.columns:
            return 0.0
        x = np.log(c[num] / c[den]).diff(20)
        med = x.rolling(252, min_periods=80).median()
        mad = (x - med).abs().rolling(252, min_periods=80).median()
        return _n(((x - med) / (1.4826 * mad.replace(0, np.nan))).iloc[-1])

    row = f.iloc[-1]
    last = {"cluster": row["cluster"], "age": int(row["age"]), "n20": _n(row["n20"]), "n60": _n(row["n60"]),
            "hv20": _n(row["hv20"]), "abs_ac1": _n(row["abs_ac1"]), "dd": _n(row["dd"]),
            "trade": row["trade"], "trend": row["trend"], "tail": row["tail"],
            "spy_r20": r20("SPY"), "spy_r126": float(np.log(spy).diff(126).iloc[-1]),
            "tlt_r20": r20("TLT"), "uup_r20": r20("UUP"), "uso_r20": r20("USO"),
            "hyg_tlt_r20": (r20("HYG") - r20("TLT")) if "HYG" in c.columns else 0.0,
            "sma10": _n(row["sma10"]), "sma20": _n(row["sma20"]),
            "z_qual": rel_z("QUAL", "SPY"), "z_mtum": rel_z("MTUM", "SPY"), "z_vlue": rel_z("VLUE", "SPY")}
    cl = last["cluster"]
    if cl == "ACTIVE":
        dip, why = "NO", "Cluster is ACTIVE: the package of time is still open."
    elif last["trade"] == "BEAR" and last["trend"] == "BEAR":
        dip, why = "NO", "Trade and Trend both offered. The dip is not three-duration bullish."
    elif last["trade"] == "BEAR" and last["trend"] == "BULL" and last["tail"] == "BULL":
        dip, why = "MAYBE", "Trend and Tail still up. Trade is the only broken duration."
    elif last["trade"] == last["trend"] == last["tail"] == "BULL":
        dip, why = "ALLOWED", "All three durations bullish and cluster QUIET. Still not a ticket."
    else:
        dip, why = "NO", "Mixed durations. Sit."
    if cl == "ACTIVE":
        sentence = (f"ACTIVE cluster, day {last['age']}. {last['n20']:.0f} |z|>=2 days in the last 20, "
                    f"HV20 {last['hv20']*100:.1f}%. Extremes are arriving in a package; don't treat the last red day as an average dip.")
    else:
        sentence = (f"QUIET cluster, day {last['age']}. {last['n20']:.0f} large days in 20, HV20 {last['hv20']*100:.1f}%. "
                    "Quiet weeks also cluster; that is when short premium gets paid, until it doesn't.")
    if last["uso_r20"] >= 0.08:
        sentence += " Oil is bid over 20 days: a supply/geopolitics clause, not a Quad name."
    g126, oil, tlt = last["spy_r126"], last["uso_r20"], last["tlt_r20"]
    quad = {
        "growth": ("Growth impulse strong" if g126 >= 0.08 else "Growth impulse weak" if g126 <= -0.08
                   else "Growth impulse mixed") + " (equity 126d, not GDP)",
        "inflation": ("Inflation tell bid (oil and/or duration offered)" if (oil >= 0.08 or tlt <= -0.04)
                      else "Inflation tell cooling" if (oil <= -0.06 and tlt >= 0.03) else "Inflation tell quiet"),
    }
    q, m, v = last["z_qual"], last["z_mtum"], last["z_vlue"]
    garp = ("GARP-ok" if (q >= 0.3 and m < 1.2 and v < 1.2) else "MOM-only" if (m >= 0.9 and q < 0)
            else "VALUE-only" if (v >= 0.9 and q < 0.2) else "NONE")
    bser, brows = build_baskets(c)
    return {"frame": f, "last": last, "dip": dip, "dip_why": why, "sentence": sentence,
            "quad": quad, "garp": garp, "gauss": gaussian_compare(f["r"]),
            "cards": hedgeye_cards(last), "baskets": brows, "basket_series": bser}


def hedgeye_cards(L: Dict[str, Any]) -> List[Dict[str, str]]:
    """Plain-English dialects vs the SPY cluster. Every sentence is conditional
    on the data it describes (the old page had fixed text on three cards)."""
    quiet = L["cluster"] == "QUIET"
    spy20, hv, tlt20, hyg, uup = L["spy_r20"], L["hv20"], L["tlt_r20"], L["hyg_tlt_r20"], L["uup_r20"]
    sma10, sma20 = L["sma10"], L["sma20"]
    gap = ((sma10 / sma20) - 1) * 100 if sma10 and sma20 else 0.0

    def v(rhyme: bool, collide: bool) -> str:
        return "rhymes" if rhyme else ("collides" if collide else "neutral")

    eq_state = "Soft pullback" if -0.02 <= spy20 < 0 else ("Bear path" if spy20 < -0.02 else "Bull path")
    eq_mean = ("Essentially flat over 20 days: no longer an uptrend, not risk-off." if -0.02 <= spy20 < 0 else
               "SPY paid over 20 days, which fits a QUIET cluster." if spy20 >= 0 else
               "SPY has lost enough over 20 days to read bearish. It confirms ACTIVE only if vol is loud too.")
    vol_mean = ("Compressed realized vol is a QUIET signature." if hv < 0.16 else
                "Realized vol is elevated: the GARCH half of Mandelbrot clustering." if hv >= 0.22 else
                "Realized vol is in the middle band; it does not settle the cluster either way.")
    dur_mean = ("Duration is not being dumped; stress episodes like 2008 usually see TLT bid." if tlt20 > -0.02 else
                "Long bonds are offered. With a firm dollar that is the 2022 rates fork, not flight-to-quality.")
    cr_mean = ("High yield is holding versus Treasuries; a Crisis package would want this tile breaking." if hyg > -0.01 else
               "High yield is lagging Treasuries: credit is confirming stress.")
    usd_mean = ("A firm dollar is the 2022 rates analogue, not the 1970s one." if uup >= 0.01 else
                "A soft dollar is what a 1970s-style inflation read would need." if uup <= -0.01 else
                "The dollar is not taking a side.")
    tr_mean = ("The 10-day average has lost the 20-day. Inside a quiet cluster that is a leak, not a crash."
               if sma10 < sma20 else "Short-term trend still up, which fits a quiet package.")
    return [
        {"title": "Equity path", "state": eq_state, "now": f"SPY 20d {spy20*100:+.1f}%", "meaning": eq_mean,
         "verdict": v((quiet and spy20 >= 0) or (not quiet and spy20 < -0.02), quiet and spy20 < 0)},
        {"title": "Realized vol", "state": f"HV20 {hv*100:.1f}%", "now": "ACTIVE wants HV20 >= 22% or 3 large days in 20",
         "meaning": vol_mean, "verdict": v((quiet and hv < 0.16) or (not quiet and hv >= 0.22), quiet and hv >= 0.22)},
        {"title": "Treasuries", "state": "Duration bid" if tlt20 > -0.02 else "Duration offered",
         "now": f"TLT 20d {tlt20*100:+.1f}%", "meaning": dur_mean,
         "verdict": "collides" if (tlt20 <= -0.02 and not quiet) else ("rhymes" if (tlt20 > -0.01 and quiet) else "neutral")},
        {"title": "Credit", "state": "Credit quiet" if hyg > -0.01 else "Credit stress",
         "now": f"HYG vs TLT 20d {hyg*100:+.1f}%", "meaning": cr_mean,
         "verdict": v((quiet and hyg > -0.01) or (not quiet and hyg <= -0.01), not quiet and hyg > -0.01)},
        {"title": "Dollar", "state": "Dollar firm" if uup >= 0.01 else ("Dollar soft" if uup <= -0.01 else "Dollar mixed"),
         "now": f"UUP 20d {uup*100:+.1f}%", "meaning": usd_mean, "verdict": "neutral"},
        {"title": "Trend rule", "state": "10d below 20d" if sma10 < sma20 else "10d above 20d",
         "now": f"SMA10 vs SMA20 {gap:+.2f}%", "meaning": tr_mean,
         "verdict": v(quiet and sma10 >= sma20, quiet and sma10 < sma20)},
    ]


# ═══════════════════════════════════════════════════════════════════════════
#  NAME STACK
# ═══════════════════════════════════════════════════════════════════════════

def score_name(px: pd.Series, vol_gate: str) -> Optional[Dict[str, Any]]:
    px = px.dropna()
    if len(px) < 280:
        return None
    f = cluster_frame(px, large_k=3.0, hv_on=0.55, hv_off=0.40, vol_gate=vol_gate)
    if f.empty:
        return None
    last_px = float(px.iloc[-1])
    sma = {n_: float(px.rolling(n_).mean().iloc[-1]) for n_ in (15, 63, 252)}
    row = f.iloc[-1]
    return {
        "last": px.index[-1], "px": last_px, "z": _n(row["z"]), "n20": _n(row["n20"]), "n60": _n(row["n60"]),
        "hv20": _n(row["hv20"]), "r20": float(np.log(px.iloc[-1] / px.iloc[-21])),
        "r63": float(np.log(px.iloc[-1] / px.iloc[-64])),
        "trade": "BULL" if last_px >= sma[15] else "BEAR", "trend": "BULL" if last_px >= sma[63] else "BEAR",
        "tail": "BULL" if last_px >= sma[252] else "BEAR",
        "cluster": row["cluster"], "age": int(row["age"]), "frame": f,
    }


def garp_proxy(rec: Dict[str, Any], bench_r63: Dict[str, float]) -> str:
    hv, r63 = rec["hv20"], rec["r63"]
    spy63 = bench_r63.get("SPY", 0.0)
    vs_spy = r63 - spy63
    vs_qual = r63 - bench_r63.get("QUAL", spy63)
    vs_mtum = r63 - bench_r63.get("MTUM", spy63)
    if hv >= 0.70:
        return "MOM-only" if vs_spy > 0.04 else "NONE"
    if vs_qual >= -0.02 and vs_mtum < 0.08 and vs_spy > -0.04 and hv < 0.45:
        return "GARP-ok"
    if vs_mtum >= 0.06 and vs_qual < -0.03:
        return "MOM-only"
    if vs_spy < -0.06 and hv < 0.35:
        return "VALUE-only"
    return "NONE"


def dip_flag(rec: Dict[str, Any]) -> str:
    if rec.get("status") != "OK" or rec.get("cluster") == "ACTIVE":
        return "NO"
    if rec["trade"] == rec["trend"] == rec["tail"] == "BULL":
        return "ALLOWED"
    if rec["trade"] == "BEAR" and rec["trend"] == "BULL" and rec["tail"] == "BULL":
        return "MAYBE"
    return "NO"


def build_name_stack(uni: pd.DataFrame, bars: Dict[str, pd.DataFrame], bench_bars: Dict[str, pd.DataFrame],
                     refuse: set, px_min: float, px_max: float, mcap_min: float,
                     vol_gate: str) -> Tuple[pd.DataFrame, Dict[str, pd.DataFrame]]:
    bench_r63 = {t: float(np.log(df["close"].iloc[-1] / df["close"].iloc[-64]))
                 for t, df in bench_bars.items() if len(df) > 64}
    rows, frames = [], {}
    for r in uni.itertuples():
        t = r.ticker
        base = {"ticker": t, "name": r.name, "industry": r.industry, "theme": r.theme, "status": "OK", "why": ""}
        if t in refuse:
            base.update(status="REFUSE", why="Refuse list. Do not express.")
        elif _n(r.last, 0) and not (px_min <= _n(r.last) <= px_max):
            base.update(status="SKIP", why=f"Last {_n(r.last):.2f} outside ${px_min:.0f}-{px_max:.0f}")
        elif _n(r.mcap, 0) and _n(r.mcap) < mcap_min:
            base.update(status="SKIP", why="Market cap under the floor")
        elif t not in bars:
            base.update(status="MISS", why="No daily history")
        else:
            sc = score_name(bars[t]["close"], vol_gate)
            if sc is None:
                base.update(status="MISS", why="Under 280 sessions of history")
            else:
                frames[t] = sc.pop("frame")
                base.update(sc)
                base["garp"] = garp_proxy(base, bench_r63)
        base["dip"] = dip_flag(base)
        rows.append(base)
    df = pd.DataFrame(rows)
    for col in ("cluster", "trade", "trend", "tail", "garp"):
        if col not in df.columns:
            df[col] = ""
    ud = {"BULL": "U", "BEAR": "D"}
    df["ttt"] = ["".join(ud.get(str(x), "") for x in (a, b, c)) for a, b, c in
                 zip(df["trade"].fillna(""), df["trend"].fillna(""), df["tail"].fillna(""))]
    order = {"OK": 0, "REFUSE": 1, "SKIP": 2, "MISS": 3}
    df["_o"] = df["status"].map(order)
    df = df.sort_values(["_o", "cluster", "ticker"], ascending=[True, True, True]).drop(columns="_o")
    return df.reset_index(drop=True), frames


# ═══════════════════════════════════════════════════════════════════════════
#  STRIKE / HIT  (per-name physical-measure touch vs finish)
# ═══════════════════════════════════════════════════════════════════════════

HIT_H = [5, 10, 21, 45]
HIT_K = [0.01, 0.02, 0.03, 0.05]
HIT_STEP = 5

SEMI_KEYS = ("semiconductor", "semi ", "semi-", "electronics products")
ENERGY_KEYS = ("oil", "gas", "energy", "pipeline", "refining", "exploration", "coal")
FIN_KEYS = ("bank", "finance", "insurance", "broker", "capital market", "financial", "reit")
SOFT_KEYS = ("software", "internet", "cloud", "security", "technology services", "computer -")


def proto_of(ticker: str, industry: str) -> str:
    hard = {"SPY": "SPY", "DIA": "SPY", "QQQ": "QQQ", "IWM": "IWM", "SMH": "SMH", "NVDA": "SMH",
            "AVGO": "SMH", "AMD": "SMH", "TSM": "SMH", "XLE": "XLE", "XOM": "XLE", "CVX": "XLE",
            "XLF": "XLF", "JPM": "XLF", "GS": "XLF", "MS": "XLF", "AAPL": "QQQ", "MSFT": "QQQ",
            "AMZN": "QQQ", "META": "QQQ", "GOOGL": "QQQ", "GOOG": "QQQ"}
    if ticker in hard:
        return hard[ticker]
    ind = (industry or "").lower()
    for keys, p in ((SEMI_KEYS, "SMH"), (ENERGY_KEYS, "XLE"), (FIN_KEYS, "XLF"), (SOFT_KEYS, "QQQ")):
        if any(k in ind for k in keys):
            return p
    return "SPY"


def gbm_term(b: float, side: str, nu: float, sig: float, h: int) -> float:
    """P(close at h beyond the barrier) with log drift nu (not arithmetic mu)."""
    T = h / 252.0
    if sig <= 0:
        return float("nan")
    k = math.log(1 + b) if side == "UP" else math.log(1 - b)
    x = (k - nu * T) / (sig * math.sqrt(T))
    return float(1 - _ncdf(x)) if side == "UP" else float(_ncdf(x))


def gbm_hit(b: float, side: str, nu: float, sig: float, h: int) -> float:
    """P(touch the barrier within h days), Brownian motion with log drift nu."""
    T = h / 252.0
    if sig <= 0:
        return float("nan")
    B = math.log(1 + b) if side == "UP" else math.log(1 - b)
    sT = sig * math.sqrt(T)
    try:
        e = math.exp(2 * nu * B / sig ** 2)
    except OverflowError:
        e = float("inf")
    if B > 0:
        surv = _ncdf((B - nu * T) / sT) - e * _ncdf((-B - nu * T) / sT)
    else:
        surv = _ncdf((-B + nu * T) / sT) - e * _ncdf((B + nu * T) / sT)
    return float(np.clip(1 - surv, 0, 1))


def hit_cards(tk: str, ohlc: pd.DataFrame, frame: pd.DataFrame, drift: str = "zero") -> Optional[Dict[str, Any]]:
    close = ohlc["close"]
    sma252 = close.rolling(252).mean()
    idx = frame.index[sma252.reindex(frame.index).notna().to_numpy()]
    if len(idx) < 200:
        return None
    c = close.reindex(idx).to_numpy(float)
    hi = ohlc["high"].reindex(idx).to_numpy(float)
    lo = ohlc["low"].reindex(idx).to_numpy(float)
    clus = frame["cluster"].reindex(idx).to_numpy()
    now = clus[-1]
    L, maxh = len(idx), max(HIT_H)
    starts = np.arange(0, L - maxh - 1, HIT_STEP)
    match = clus[starts] == now
    r = np.log(pd.Series(c)).diff().dropna()
    hv = float(frame["hv20"].iloc[-1])
    rs = np.log(hi[-20:] / lo[-20:]) ** 2
    park = float(np.sqrt(np.nanmean(rs) / (4 * math.log(2))) * math.sqrt(252))
    nu = float(r.mean() * 252) if drift == "historical" else 0.0
    cards = []
    for h in HIT_H:
        W_hi = np.lib.stride_tricks.sliding_window_view(hi[1:], h)
        W_lo = np.lib.stride_tricks.sliding_window_view(lo[1:], h)
        fmax = np.nanmax(W_hi[starts], axis=1)
        fmin = np.nanmin(W_lo[starts], axis=1)
        s0 = c[starts]
        up, dn, term = fmax / s0 - 1, 1 - fmin / s0, c[starts + h] / s0 - 1
        for regime, m in (("ALL", np.ones_like(match, dtype=bool)), ("MATCH", match)):
            n = int(m.sum())
            if n < 12:
                continue
            for b in HIT_K:
                for side, hit, trm in (("UP", up[m] >= b, term[m] >= b), ("DN", dn[m] >= b, term[m] <= -b)):
                    n_eff = max(1.0, n * min(1.0, HIT_STEP / h))
                    ph = float(hit.mean())
                    ci = wilson(ph * n_eff, n_eff)
                    cards.append({"t": tk, "regime": regime, "h": h, "k": b, "side": side, "n": n,
                                  "n_eff": round(n_eff, 1), "p_hit": ph, "p_term": float(trm.mean()),
                                  "ci_lo": ci[0], "ci_hi": ci[1],
                                  "gbm_hit": gbm_hit(b, side, nu, hv, h), "gbm_term": gbm_term(b, side, nu, hv, h),
                                  "gbm_park": gbm_hit(b, side, nu, park, h)})
    return {"t": tk, "cluster": now, "hv20": hv, "park": park, "nu": nu, "cards": cards}


def build_hits(tickers: List[str], bars: Dict[str, pd.DataFrame], frames: Dict[str, pd.DataFrame],
               drift: str) -> pd.DataFrame:
    rows = []
    for tk in tickers:
        if tk not in bars or tk not in frames:
            continue
        res = hit_cards(tk, bars[tk], frames[tk], drift)
        if res:
            rows.extend(res["cards"])
    return pd.DataFrame(rows)


# ═══════════════════════════════════════════════════════════════════════════
#  CLIMATE STRIP (regime chip, factor weather, lab)
# ═══════════════════════════════════════════════════════════════════════════

LABELS = ("STEADY", "WOI", "CRISIS", "INFLATION")
Z_WIN, HV_WIN, HYST, CRISIS_FAST = 252, 20, 3, 2
GMM_COLS = ["z_equity", "z_size", "z_growth", "z_tech", "z_rates", "z_credit", "z_dollar", "z_vol"]


def _nn(v, default=np.nan) -> float:
    return _n(v, default)


def robust_z(s: pd.Series, win: int = Z_WIN) -> pd.Series:
    med = s.rolling(win, min_periods=win // 2).median()
    mad = (s - med).abs().rolling(win, min_periods=win // 2).median()
    return (s - med) / (1.4826 * mad.replace(0, np.nan))


def _ret_n(x: pd.Series, n: int) -> pd.Series:
    return x / x.shift(n) - 1.0


def climate_features(closes: pd.DataFrame) -> pd.DataFrame:
    need = ["SPY", "QQQ", "IWM", "SMH", "TLT", "HYG", "IEF", "UUP"]
    missing = [t for t in need if t not in closes.columns]
    if missing:
        raise ValueError(f"Climate strip needs {need}; missing {missing}")
    c = closes.dropna(subset=need).copy()
    f = pd.DataFrame(index=c.index)
    f["SPY"] = c["SPY"]
    for n_ in (1, 5, 20, 60, 126):
        f[f"spy_r{n_}"] = _ret_n(c["SPY"], n_)
    f["tlt_r5"], f["tlt_r20"], f["uup_r20"] = _ret_n(c["TLT"], 5), _ret_n(c["TLT"], 20), _ret_n(c["UUP"], 20)
    f["hv20"] = np.log(c["SPY"]).diff().rolling(HV_WIN).std() * math.sqrt(252)
    f["sma10"], f["sma20"] = c["SPY"].rolling(10).mean(), c["SPY"].rolling(20).mean()
    for key, num, den in (("size", "IWM", "SPY"), ("growth", "QQQ", "SPY"), ("tech", "SMH", "QQQ"),
                          ("credit", "HYG", "IEF")):
        f[f"{key}_r20"] = _ret_n(c[num] / c[den], 20)
    if "VIXY" in c.columns:
        f["vixy_r20"] = _ret_n(c["VIXY"], 20)
        f["z_vixy"] = robust_z(f["vixy_r20"])
    f["z_equity"], f["z_size"] = robust_z(f["spy_r20"]), robust_z(f["size_r20"])
    f["z_growth"], f["z_tech"] = robust_z(f["growth_r20"]), robust_z(f["tech_r20"])
    f["z_rates"], f["z_credit"] = robust_z(f["tlt_r20"]), robust_z(f["credit_r20"])
    f["z_dollar"], f["z_vol"] = robust_z(f["uup_r20"]), robust_z(f["hv20"])
    f["cross_15"] = (f["sma10"] > f["sma20"]).astype(int).diff().abs().rolling(15).sum()
    for num, den, key in (("MTUM", "SPY", "mom"), ("QUAL", "SPY", "qual"), ("VLUE", "SPY", "value"),
                          ("USMV", "SPY", "lowvol"), ("LQD", "HYG", "igjunk"), ("IEF", "TLT", "curve"),
                          ("TIP", "IEF", "breakeven"), ("EFA", "SPY", "intl"), ("EEM", "EFA", "em"),
                          ("IWM", "QUAL", "sizequal"), ("VLUE", "MTUM", "valmom"), ("QUAL", "USMV", "qualdef"),
                          ("MTUM", "USMV", "momdef")):
        if num in c.columns and den in c.columns:
            f[f"{key}_r20"] = _ret_n(c[num] / c[den], 20)
            f[f"z_{key}"] = robust_z(f[f"{key}_r20"])
    if "mom_r20" in f and "value_r20" in f:
        f["vm_gap"] = f["value_r20"] - f["mom_r20"]
        f["z_vm_gap"] = robust_z(f["vm_gap"])
    if "qual_r20" in f and "size_r20" in f:
        f["qs_gap"] = f["qual_r20"] - f["size_r20"]
        f["z_qs_gap"] = robust_z(f["qs_gap"])
    for t, k in (("DBC", "dbc"), ("GLD", "gld"), ("USO", "uso")):
        if t in c.columns:
            f[f"{k}_r20"] = _ret_n(c[t], 20)
            f[f"z_{k}"] = robust_z(f[f"{k}_r20"])
    return f


def raw_scores(row: pd.Series) -> Dict[str, float]:
    spy5, spy20 = _nn(row.get("spy_r5")), _nn(row.get("spy_r20"))
    tlt5, tlt20 = _nn(row.get("tlt_r5")), _nn(row.get("tlt_r20"))
    z_vol, z_credit, z_size = _nn(row.get("z_vol")), _nn(row.get("z_credit")), _nn(row.get("z_size"))
    z_growth, z_tech, z_dollar = _nn(row.get("z_growth")), _nn(row.get("z_tech")), _nn(row.get("z_dollar"))
    vol_proxy = max(z_vol, _n(row.get("z_vixy"), 0.0))
    zs = [_nn(row.get("z_equity")), z_size, z_growth, z_tech, _nn(row.get("z_rates")), z_credit, z_dollar, z_vol]
    max_abs = np.nanmax(np.abs(zs)) if np.isfinite(zs).any() else np.nan
    crisis = 0.0
    crisis += 2 if spy5 <= -0.03 else (1 if spy5 <= -0.015 else 0)
    crisis += 2 if vol_proxy >= 1.5 else (1 if vol_proxy >= 0.8 else 0)
    crisis += 1 if z_credit <= -1 else 0
    crisis += 1 if z_size <= -1 else 0
    crisis += 1 if (tlt5 > 0 and spy5 < 0) else 0
    woi = 0.0
    woi += 2 if (spy20 >= 0 and vol_proxy >= 0.5) else 0
    woi += 1 if (z_growth >= 0.8 or z_tech >= 0.8) else 0
    woi += 1 if _n(row.get("cross_15")) >= 3 else 0
    hv = _n(row.get("hv20"))
    woi += 1 if 0.15 <= hv <= 0.25 else 0
    woi -= 2 if spy5 <= -0.03 else 0
    woi += 1 if (_n(row.get("z_mom")) >= 0.8 and vol_proxy >= 0.5) else 0
    infl = 0.0
    infl += 2 if tlt20 <= -0.04 else 0
    infl += 1 if (spy20 <= 0 and tlt20 <= 0) else 0
    infl += 1 if abs(z_dollar) >= 1 else 0
    infl += 1 if (_n(row.get("z_breakeven")) >= 1 or _n(row.get("z_dbc")) >= 1) else 0
    steady = 0.0
    steady += 2 if (z_vol <= 0 and abs(z_credit) < 0.7) else 0
    steady += 1 if max_abs < 2 else 0
    steady += 1 if z_vol <= 0 else 0
    steady -= 2 if crisis >= 2 else 0
    return {"STEADY": max(steady, 0.0), "WOI": max(woi, 0.0), "CRISIS": max(crisis, 0.0), "INFLATION": max(infl, 0.0)}


def score_share(raw: Dict[str, float], tau: float = 1.0) -> Dict[str, float]:
    """Softmax of integer checklist points. Displayed as score share, not probability."""
    xs = np.array([raw[k] for k in LABELS], dtype=float)
    if np.nansum(xs) <= 0:
        return {k: 0.25 for k in LABELS}
    xs = xs / max(tau, 1e-6)
    e = np.exp(np.clip(xs - np.nanmax(xs), -20, 20))
    e /= e.sum()
    return {k: float(e[i]) for i, k in enumerate(LABELS)}


def annotations(row: pd.Series) -> Dict[str, str]:
    spy20, z_vol, tlt20 = _n(row.get("spy_r20")), _n(row.get("z_vol")), _n(row.get("tlt_r20"))
    sma10, sma20 = _nn(row.get("sma10")), _nn(row.get("sma20"))
    if _n(row.get("spy_r5")) <= -0.03 or spy20 < -0.02:
        eq = "EQ-BEAR"
    else:
        eq = "EQ-BULL" if spy20 >= 0 else "EQ-BEAR"
    zd = _n(row.get("z_dollar"))
    if _n(row.get("cross_15")) >= 3:
        trend = "TR-CHOP"
    elif sma10 == sma10 and sma20 == sma20:
        trend = "TR-UP" if sma10 > sma20 else "TR-DOWN"
    else:
        trend = "TR-CHOP"
    return {"eq": eq, "vol": "VOL-HIGH" if z_vol >= 0.8 else "VOL-LOW",
            "dur": "DUR-OFF" if tlt20 <= -0.02 else "DUR-BID",
            "credit": "CR-STRESS" if _n(row.get("z_credit")) <= -0.8 else "CR-QUIET",
            "usd": "USD-UP" if zd >= 0.4 else ("USD-DOWN" if zd <= -0.4 else "USD-FLAT"), "trend": trend}


def climate_cards(row: pd.Series, ann: Dict[str, str], sticky: str) -> List[Dict[str, str]]:
    spy20, spy5, hv = _n(row.get("spy_r20")), _n(row.get("spy_r5")), _n(row.get("hv20"))
    z_vol, tlt20, cr20 = _n(row.get("z_vol")), _n(row.get("tlt_r20")), _n(row.get("credit_r20"))
    uup20, zd = _n(row.get("uup_r20")), _n(row.get("z_dollar"))
    sma10, sma20 = _n(row.get("sma10")), _n(row.get("sma20"))
    gap = ((sma10 / sma20) - 1) * 100 if sma10 and sma20 else 0.0

    def verdict(rh, co):
        return "rhymes" if rh else ("collides" if co else "neutral")

    return [
        {"title": "Equity path",
         "state": "Soft pullback" if -0.02 <= spy20 < 0 else ("Bear path" if ann["eq"] == "EQ-BEAR" else "Bull path"),
         "now": f"SPY 20d {spy20*100:+.1f}%, 5d {spy5*100:+.1f}%",
         "meaning": ("Essentially flat over 20 days: read it as no longer an uptrend, not as risk-off."
                     if -0.02 < spy20 < 0 else
                     "SPY is up over 20 days." if spy20 >= 0 else
                     "SPY has lost enough to read as the weaker equity state; it rhymes with Crisis only if vol and credit also break."),
         "verdict": verdict((sticky == "STEADY" and ann["eq"] == "EQ-BULL") or (sticky == "CRISIS" and ann["eq"] == "EQ-BEAR")
                            or (sticky == "WOI" and ann["eq"] == "EQ-BULL"), sticky == "STEADY" and ann["eq"] == "EQ-BEAR")},
        {"title": "Realized vol",
         "state": ("Quiet tape" if ann["vol"] == "VOL-LOW" else "Loud tape") + f", HV20 {hv*100:.1f}%",
         "now": f"HV20 z {z_vol:+.2f}; VOL-HIGH needs z >= +0.8",
         "meaning": (f"Realized vol ({hv*100:.0f}% annualized) is not elevated versus the last year, a Steady signature."
                     if ann["vol"] == "VOL-LOW" else
                     f"Realized vol ({hv*100:.0f}% annualized) is elevated versus the last year; necessary for Crisis or WOI, not sufficient."),
         "verdict": verdict((sticky == "STEADY" and ann["vol"] == "VOL-LOW") or (sticky in ("WOI", "CRISIS") and ann["vol"] == "VOL-HIGH"),
                            sticky == "STEADY" and ann["vol"] == "VOL-HIGH")},
        {"title": "Treasuries", "state": "Duration bid" if ann["dur"] == "DUR-BID" else "Duration offered",
         "now": f"TLT 20d {tlt20*100:+.1f}%",
         "meaning": ("Bonds have not been dumped; a 2008-style Crisis usually sees TLT bid." if ann["dur"] == "DUR-BID" else
                     "Long bonds are selling off. With heavy equity and a firm dollar that is the 2022 fork."),
         "verdict": verdict((sticky == "CRISIS" and ann["dur"] == "DUR-BID") or (sticky == "INFLATION" and ann["dur"] == "DUR-OFF"),
                            sticky == "CRISIS" and ann["dur"] == "DUR-OFF")},
        {"title": "Credit", "state": "Credit quiet" if ann["credit"] == "CR-QUIET" else "Credit stress",
         "now": f"HYG vs IEF 20d {cr20*100:+.1f}%",
         "meaning": ("High yield is holding versus duration; a Crisis chip without this tile breaking is unconfirmed."
                     if ann["credit"] == "CR-QUIET" else "High yield is breaking versus duration: credit confirms stress."),
         "verdict": verdict(sticky == "STEADY" and ann["credit"] == "CR-QUIET", sticky == "CRISIS" and ann["credit"] == "CR-QUIET")},
        {"title": "Dollar",
         "state": {"USD-UP": "Dollar firm", "USD-DOWN": "Dollar soft"}.get(ann["usd"], "Dollar mixed"),
         "now": f"UUP 20d {uup20*100:+.1f}%, z {zd:+.2f}",
         "meaning": ("A firm dollar is the 2022 rates analogue, not the 1970s one." if ann["usd"] == "USD-UP" else
                     "A soft dollar is what a 1970s-style inflation read needs." if ann["usd"] == "USD-DOWN" else
                     "The dollar is not taking a side."),
         "verdict": "rhymes" if sticky == "INFLATION" else "neutral"},
        {"title": "Trend rule",
         "state": {"TR-DOWN": "10d below 20d", "TR-UP": "10d above 20d"}.get(ann["trend"], "Averages chopping"),
         "now": f"SMA10 vs SMA20 {gap:+.2f}%",
         "meaning": ("The short average has lost the longer one (a regime-aware trend flip, per Zakamulin). With quiet vol it is a leak, not a crash."
                     if ann["trend"] == "TR-DOWN" else
                     "Short-term trend still up." if ann["trend"] == "TR-UP" else "The 10/20 cross has flipped 3+ times in 15 sessions."),
         "verdict": verdict(sticky == "STEADY" and ann["trend"] == "TR-UP", sticky == "STEADY" and ann["trend"] == "TR-DOWN")},
    ]


def turbulence_pct(f: pd.DataFrame, win: int = Z_WIN) -> pd.Series:
    """Kritzman-Li Mahalanobis distance of the 8-z vector vs the trailing year,
    expressed as a trailing-year percentile."""
    x = f[GMM_COLS].replace([np.inf, -np.inf], np.nan).to_numpy(float)
    out = np.full(len(x), np.nan)
    for i in range(win // 2, len(x)):
        sl = x[max(0, i - win):i]
        sl = sl[~np.isnan(sl).any(axis=1)]
        if len(sl) < 40 or np.isnan(x[i]).any():
            continue
        d = x[i] - sl.mean(axis=0)
        out[i] = float(d @ np.linalg.pinv(np.cov(sl, rowvar=False)) @ d)
    s = pd.Series(out, index=f.index)
    return s.rolling(win, min_periods=win // 2).apply(
        lambda w: pd.Series(w).rank(pct=True).iloc[-1] if np.isfinite(w[-1]) else np.nan, raw=True)


def walk_hysteresis(f: pd.DataFrame) -> pd.DataFrame:
    recs = []
    sticky, age, pending, pending_n, prev = "MIXED", 0, None, 0, "MIXED"
    for dt, row in f.dropna(subset=["z_vol", "z_equity", "hv20", "spy_r5"]).iterrows():
        raw = raw_scores(row)
        prob = score_share(raw)
        top = max(prob, key=prob.get)
        ptop = prob[top]
        vol_proxy = max(_n(row.get("z_vol")), _n(row.get("z_vixy")))
        fast = _n(row.get("spy_r5")) <= -0.04 and vol_proxy >= 2.0
        cand = top if ptop >= 0.55 else "MIXED"
        if sticky == "MIXED":
            if cand != "MIXED":
                pending, pending_n = (cand, pending_n + 1) if pending == cand else (cand, 1)
                need = CRISIS_FAST if (cand == "CRISIS" and fast) else HYST
                if pending_n >= need:
                    prev, sticky, age, pending, pending_n = sticky, cand, 1, None, 0
                else:
                    age += 1
            else:
                pending, pending_n = None, 0
                age += 1
        else:
            p_cur = prob.get(sticky, 0.0)
            rival = cand if cand not in (sticky, "MIXED") else None
            if fast and top == "CRISIS" and sticky != "CRISIS":
                pending, pending_n = ("CRISIS", pending_n + 1) if pending == "CRISIS" else ("CRISIS", 1)
                if pending_n >= CRISIS_FAST:
                    prev, sticky, age, pending, pending_n = sticky, "CRISIS", 1, None, 0
                else:
                    age += 1
            elif rival or p_cur < 0.35:
                new = rival or "MIXED"
                pending, pending_n = (new, pending_n + 1) if pending == new else (new, 1)
                if pending_n >= HYST:
                    prev, sticky, age, pending, pending_n = sticky, new, 1, None, 0
                else:
                    age += 1
            else:
                pending, pending_n = None, 0
                age += 1
        recs.append({"date": dt, "sticky": sticky, "age": age, "raw_top": top, "ptop": ptop, "prev": prev,
                     **{f"p_{k}": prob[k] for k in LABELS}, **{f"raw_{k}": raw[k] for k in LABELS},
                     **annotations(row)})
    return pd.DataFrame(recs).set_index("date")


# ---- lab: causal GMM (Two Sigma-style 4 regimes) --------------------------

def _log_diag_mvn(X, mu, var):
    var = np.clip(var, 1e-4, 1e4)
    d = X - mu
    return -0.5 * (np.sum(np.log(2 * np.pi * var)) + np.sum(d * d / var, axis=1))


def fit_gmm_diag(X, k=4, n_iter=18):
    n, _ = X.shape
    order = np.argsort(X[:, 0])
    cuts = np.linspace(0, n - 1, k + 1).astype(int)
    mu = np.stack([X[order[cuts[i]:max(cuts[i + 1], cuts[i] + 1)]].mean(axis=0) for i in range(k)])
    var = np.tile(X.var(axis=0) + 0.15, (k, 1))
    pi = np.ones(k) / k
    for _ in range(n_iter):
        logp = np.stack([_log_diag_mvn(X, mu[j], var[j]) + np.log(pi[j] + 1e-12) for j in range(k)], axis=1)
        logp -= logp.max(axis=1, keepdims=True)
        r = np.exp(logp)
        r /= r.sum(axis=1, keepdims=True) + 1e-12
        nk = r.sum(axis=0) + 1e-6
        pi = nk / nk.sum()
        mu = (r.T @ X) / nk[:, None]
        for j in range(k):
            var[j] = (r[:, j][:, None] * (X - mu[j]) ** 2).sum(axis=0) / nk[j] + 0.12
    return pi, mu, var


def pin_gmm_labels(mu: np.ndarray) -> List[str]:
    left = set(range(len(mu)))
    labels = [""] * len(mu)
    for name, score, pick in (("CRISIS", mu[:, 0] + mu[:, 5] - 0.6 * mu[:, 7], min),
                              ("INFLATION", mu[:, 4] - 0.4 * np.abs(mu[:, 6]), min),
                              ("STEADY", mu[:, 7], min)):
        j = int(pick(left, key=lambda i: score[i]))
        labels[j] = name
        left.remove(j)
    labels[left.pop()] = "WOI"
    return labels


def gmm_predict(X, pi, mu, var, names):
    logp = np.stack([_log_diag_mvn(X, mu[j], var[j]) + np.log(pi[j] + 1e-12) for j in range(len(names))], axis=1)
    logp -= logp.max(axis=1, keepdims=True)
    r = np.exp(logp)
    r /= r.sum(axis=1, keepdims=True) + 1e-12
    return np.array([names[j] for j in r.argmax(axis=1)], dtype=object), r


def walk_gmm_causal(f: pd.DataFrame, gmm_min: int = 252, refit: int = 21) -> pd.DataFrame:
    x = f[GMM_COLS].replace([np.inf, -np.inf], np.nan).dropna()
    X, n = x.to_numpy(float), len(x)
    lab = np.array(["MIXED"] * n, dtype=object)
    pmax = np.full(n, np.nan)
    peek = np.array(["MIXED"] * n, dtype=object)
    if n < gmm_min + 10:
        return pd.DataFrame({"gmm": lab, "gmm_peek": peek, "gmm_p": pmax}, index=x.index)
    pi_p, mu_p, var_p = fit_gmm_diag(X)
    peek, _ = gmm_predict(X, pi_p, mu_p, var_p, pin_gmm_labels(mu_p))
    model, last = None, -10 ** 9
    for t in range(gmm_min, n):
        if model is None or t - last >= refit:
            pi, mu, var = fit_gmm_diag(X[:t])
            model, last = (pi, mu, var, pin_gmm_labels(mu)), t
        labs, r = gmm_predict(X[t:t + 1], *model)
        lab[t], pmax[t] = labs[0], float(r.max())
    return pd.DataFrame({"gmm": lab, "gmm_peek": peek, "gmm_p": pmax}, index=x.index)


# ---- lab: Hamilton 2-state HMM (pure-Python scaled recursions) -------------

def _emis(y, mu, sig):
    b0 = np.exp(-0.5 * ((y - mu[0]) / sig[0]) ** 2) / sig[0]
    b1 = np.exp(-0.5 * ((y - mu[1]) / sig[1]) ** 2) / sig[1]
    m = np.maximum(np.maximum(b0, b1), 1e-300)
    return (b0 / m).tolist(), (b1 / m).tolist()


def fit_hmm2(y: np.ndarray, n_iter: int = 16) -> Dict[str, Any]:
    y = np.asarray(y, float)
    m = np.nanmedian(y)
    mu = np.array([np.nanmean(y[y <= m]), np.nanmean(y[y > m])])
    sig = np.clip(np.nan_to_num(np.array([np.nanstd(y[y <= m]), np.nanstd(y[y > m])]), nan=np.nanstd(y) or 0.01), 1e-5, 10)
    P = [[0.94, 0.06], [0.06, 0.94]]
    n = len(y)
    for _ in range(n_iter):
        b0, b1 = _emis(y, mu, sig)
        a0, a1, sc = [0.0] * n, [0.0] * n, [1.0] * n
        x0, x1 = 0.5 * b0[0], 0.5 * b1[0]
        s = x0 + x1 or 1e-300
        a0[0], a1[0], sc[0] = x0 / s, x1 / s, s
        for t in range(1, n):
            p0 = a0[t - 1] * P[0][0] + a1[t - 1] * P[1][0]
            p1 = a0[t - 1] * P[0][1] + a1[t - 1] * P[1][1]
            x0, x1 = p0 * b0[t], p1 * b1[t]
            s = x0 + x1 or 1e-300
            a0[t], a1[t], sc[t] = x0 / s, x1 / s, s
        be0, be1 = [1.0] * n, [1.0] * n
        xi = [[0.0, 0.0], [0.0, 0.0]]
        for t in range(n - 2, -1, -1):
            u0, u1 = b0[t + 1] * be0[t + 1], b1[t + 1] * be1[t + 1]
            c = sc[t + 1]
            be0[t] = (P[0][0] * u0 + P[0][1] * u1) / c
            be1[t] = (P[1][0] * u0 + P[1][1] * u1) / c
            e00, e01 = a0[t] * P[0][0] * u0, a0[t] * P[0][1] * u1
            e10, e11 = a1[t] * P[1][0] * u0, a1[t] * P[1][1] * u1
            tot = e00 + e01 + e10 + e11 or 1e-300
            xi[0][0] += e00 / tot; xi[0][1] += e01 / tot
            xi[1][0] += e10 / tot; xi[1][1] += e11 / tot
        g0 = np.array(a0) * np.array(be0)
        g1 = np.array(a1) * np.array(be1)
        tot = g0 + g1
        g0, g1 = g0 / tot, g1 / tot
        for i in (0, 1):
            rs = xi[i][0] + xi[i][1] or 1e-300
            P[i] = [min(max(xi[i][0] / rs, 0.02), 0.98), 0.0]
            P[i][1] = 1 - P[i][0]
        for s_, w in ((0, g0), (1, g1)):
            sw = w.sum() + 1e-8
            mu[s_] = float((w * y).sum() / sw)
            sig[s_] = float(np.sqrt((w * (y - mu[s_]) ** 2).sum() / sw) + 1e-5)
    return {"mu": mu.copy(), "sig": sig.copy(), "P": [row[:] for row in P]}


def walk_hmm2(series: pd.Series, low_name: str, high_name: str, pin: str,
              hmm_min: int = 252, refit: int = 21, tail: int = 300) -> pd.DataFrame:
    """Causal walk: refit every `refit` sessions on data up to t-1, filter forward.
    Labels are only produced for the last `tail` sessions (all the lab uses);
    the refit schedule keeps the same phase as a full walk."""
    s = series.replace([np.inf, -np.inf], np.nan).dropna()
    y, n = s.to_numpy(float), len(s)
    lab = np.array(["NA"] * n, dtype=object)
    p_hi = np.full(n, np.nan)
    if n < hmm_min + 10:
        return pd.DataFrame({"state": lab, "p_high": p_hi}, index=s.index)
    t_start = max(hmm_min, n - tail)
    t_fit = hmm_min + ((t_start - hmm_min) // refit) * refit
    mdl, a = None, None
    for t in range(t_fit, n):
        if mdl is None or (t - t_fit) % refit == 0:
            mdl = fit_hmm2(y[:t])
            b0, b1 = _emis(y[:t + 1], mdl["mu"], mdl["sig"])
            P = mdl["P"]
            a = [0.5 * b0[0], 0.5 * b1[0]]
            tot = sum(a) or 1e-300
            a = [a[0] / tot, a[1] / tot]
            for k in range(1, t + 1):
                p0 = a[0] * P[0][0] + a[1] * P[1][0]
                p1 = a[0] * P[0][1] + a[1] * P[1][1]
                x0, x1 = p0 * b0[k], p1 * b1[k]
                tot = x0 + x1 or 1e-300
                a = [x0 / tot, x1 / tot]
        else:
            b0, b1 = _emis(y[t:t + 1], mdl["mu"], mdl["sig"])
            P = mdl["P"]
            p0 = a[0] * P[0][0] + a[1] * P[1][0]
            p1 = a[0] * P[0][1] + a[1] * P[1][1]
            x0, x1 = p0 * b0[0], p1 * b1[0]
            tot = x0 + x1 or 1e-300
            a = [x0 / tot, x1 / tot]
        if t < t_start:
            continue
        if pin == "mean_low_is_bad":
            bad = int(np.argmin(mdl["mu"]))
            lab[t] = low_name if a[bad] >= 0.55 else high_name
            p_hi[t] = 1.0 - a[bad]
        else:
            hi = int(np.argmax(mdl["mu"]))
            lab[t] = high_name if a[hi] >= 0.55 else low_name
            p_hi[t] = a[hi]
    return pd.DataFrame({"state": lab, "p_high": p_hi}, index=s.index)


def walk_kritzman(f: pd.DataFrame) -> pd.DataFrame:
    recs, turb, infl, growth = [], "NORMAL", "NORMAL", "NORMAL"
    pt = pi = pg = 0
    for dt, row in f.iterrows():
        tp = _n(row.get("turb_pct"))
        i_on = _n(row.get("tlt_r20")) <= -0.04 or _n(row.get("z_breakeven")) >= 1.0 or _n(row.get("z_dbc")) >= 1.2
        i_off = _n(row.get("tlt_r20")) > -0.02 and _n(row.get("z_breakeven")) < 0.5 and _n(row.get("z_dbc")) < 0.6
        g126 = _n(row.get("spy_r126"))
        g_tgt = "WEAK" if g126 <= -0.08 else ("STRONG" if g126 >= 0.12 else "NORMAL")
        if turb == "NORMAL":
            pt = pt + 1 if tp >= 0.90 else 0
            if pt >= 2:
                turb, pt = "EVENT", 0
        else:
            pt = pt + 1 if tp < 0.75 else 0
            if pt >= 2:
                turb, pt = "NORMAL", 0
        if infl == "NORMAL":
            pi = pi + 1 if i_on else 0
            if pi >= 2:
                infl, pi = "EVENT", 0
        else:
            pi = pi + 1 if i_off else 0
            if pi >= 2:
                infl, pi = "NORMAL", 0
        if g_tgt == growth:
            pg = 0
        else:
            pg += 1
            if pg >= 2:
                growth, pg = g_tgt, 0
        recs.append({"date": dt, "k_turb": turb, "k_infl": infl, "k_growth": growth})
    return pd.DataFrame(recs).set_index("date")


def _flips(s: pd.Series) -> int:
    x = s.dropna().astype(str)
    return int((x != x.shift(1)).sum() - 1) if len(x) > 1 else 0


def climate_sentence(sticky, age, prev, row, ann, turb_on, term) -> Tuple[str, str]:
    mom, qual = _n(row.get("z_mom")), _n(row.get("z_qual"))
    eq, vol, dur, cr, usd, trend = (ann[k] for k in ("eq", "vol", "dur", "credit", "usd", "trend"))
    rhyme, clause = "collision", "checklist label in force; annotations are mixed. Read the two loudest tiles."
    if sticky == "STEADY" and eq == "EQ-BULL" and vol == "VOL-LOW" and cr == "CR-QUIET" and trend == "TR-UP":
        rhyme, clause = "rhyme", "quiet uptrend: no factor in a large drawdown."
        if age <= 5 and prev == "CRISIS":
            clause = "rebound inside a Steady chip right after Crisis. Treat it as early."
    elif sticky == "STEADY" and vol == "VOL-LOW" and trend == "TR-DOWN":
        clause = "Steady chip under a 10/20 breakdown with contained vol. Not a high-vol bear; don't rename it Crisis."
        if mom < -0.5:
            clause += " Momentum is lagging SPY too, so the leak has a style witness."
        if qual > 0.3 and _n(row.get("z_size")) < -0.8:
            clause += " Quality holding while size fades is a narrow tape, not a crash."
    elif sticky == "STEADY" and eq == "EQ-BEAR" and vol == "VOL-LOW":
        clause = "slow leak: contained vol, equity state flipped. Not Crisis."
    elif sticky == "STEADY" and turb_on:
        clause = "turbulence event inside a Steady label. Uncharacteristic cross-section; wait for hysteresis."
    elif sticky == "WOI" and eq == "EQ-BULL" and vol == "VOL-HIGH":
        rhyme = "rhyme"
        clause = ("WOI right after Crisis: rebound fragility." if prev == "CRISIS"
                  else "fragile melt-up: equity paying with elevated vol.")
    elif sticky == "WOI" and eq == "EQ-BEAR":
        clause = "WOI with bear equity should not last; WOI has a positive equity mean."
    elif sticky == "CRISIS" and dur == "DUR-OFF" and usd == "USD-UP":
        clause = "Crisis mechanics on a rates shock. Duration is not the hedge (2022 texture)."
    elif sticky == "CRISIS" and cr == "CR-QUIET":
        clause = "Crisis chip without credit confirmation. Name the miss."
    elif sticky == "CRISIS":
        rhyme, clause = "rhyme", "flight-to-quality cluster: equity, credit and size failing together."
    elif sticky == "INFLATION":
        rhyme, clause = (("rhyme", "2022-style rates shock with a strong dollar.") if usd == "USD-UP" else
                         ("rhyme", "1970s-style joint with a weak dollar; commodities should confirm.") if usd == "USD-DOWN" else
                         ("collision", "rates-up tape without a clean dollar fork."))
    elif sticky == "MIXED":
        clause = "no label has held three days."
    extra = []
    if term:
        extra.append(f"SPY term {term.replace('TERM-', '').lower()}")
    if turb_on:
        extra.append("turbulence event on")
    tail = (" (" + "; ".join(extra) + ")") if extra else ""
    return clause[0].upper() + clause[1:] + tail, rhyme


FACTOR_BOOK = [
    ("Market", "SPY 20d", "z_equity", "spy_r20", "Broad beta; everything else is relative to it."),
    ("Size", "IWM / SPY", "z_size", "size_r20", "Offered in Crisis; can lead in WOI and early recoveries."),
    ("Growth", "QQQ / SPY", "z_growth", "growth_r20", "Leads in Steady expansions and WOI melt-ups."),
    ("Momentum", "MTUM / SPY", "z_mom", "mom_r20", "Strongest long-run premium; dies at reversals."),
    ("Quality", "QUAL / SPY", "z_qual", "qual_r20", "Usually bid in Crisis; lags junk rallies."),
    ("Value", "VLUE / SPY", "z_value", "value_r20", "Long droughts; often the other side of momentum."),
    ("Low vol", "USMV / SPY", "z_lowvol", "lowvol_r20", "Flight-to-quality cousin; offered in melt-ups."),
    ("Tech", "SMH / QQQ", "z_tech", "tech_r20", "Chip residual; inheritance for NVDA-class names."),
]
OTHER_TILES = [
    ("IG vs junk", "LQD / HYG", "z_igjunk", "igjunk_r20"), ("Curve", "IEF / TLT", "z_curve", "curve_r20"),
    ("Breakeven", "TIP / IEF", "z_breakeven", "breakeven_r20"), ("International", "EFA / SPY", "z_intl", "intl_r20"),
    ("EM", "EEM / EFA", "z_em", "em_r20"), ("Commodities", "DBC 20d", "z_dbc", "dbc_r20"),
    ("Gold", "GLD 20d", "z_gld", "gld_r20"), ("Oil", "USO 20d", "z_uso", "uso_r20"),
]
EXPECTED = {
    "STEADY": "Momentum and quality in-line or leading; size not crashing; low vol not desperately bid.",
    "WOI": "Momentum, growth and often size lead; quality and low vol lag.",
    "CRISIS": "Quality and low vol lead; momentum and size lag hard; credit quality bid.",
    "INFLATION": "Value can lead; growth and long-duration defensives lag.",
    "MIXED": "No textbook leadership until one climate holds three days.",
}


def climate_page(closes: pd.DataFrame, term: Optional[str]) -> Dict[str, Any]:
    f = climate_features(closes)
    f["turb_pct"] = turbulence_pct(f)
    hist = walk_hysteresis(f)
    gmm = walk_gmm_causal(f)
    hmm_eq = walk_hmm2(f["spy_r1"], "EQ-BEAR", "EQ-BULL", "mean_low_is_bad")
    hmm_vol = walk_hmm2(np.log(f["hv20"].clip(lower=0.04)), "VOL-LOW", "VOL-HIGH", "mean_high_is_high")
    krt = walk_kritzman(f)
    lab = (hist.join(gmm, how="left")
           .join(hmm_eq.rename(columns={"state": "hmm_eq", "p_high": "hmm_eq_p"}), how="left")
           .join(hmm_vol.rename(columns={"state": "hmm_vol", "p_high": "hmm_vol_p"}), how="left")
           .join(krt, how="left"))
    last_dt = hist.index[-1]
    row, h = f.loc[last_dt], hist.loc[last_dt]
    ann = {k: h[k] for k in ("eq", "vol", "dur", "credit", "usd", "trend")}
    turb_on = _n(row.get("turb_pct")) >= 0.90
    sentence, rhyme = climate_sentence(h["sticky"], int(h["age"]), str(h["prev"]), row, ann, turb_on, term)
    book = []
    for name, proxy, zk, rk, job in FACTOR_BOOK:
        if zk in f.columns:
            z = _n(row.get(zk))
            book.append({"factor": name, "proxy": proxy, "z": z, "r20": _n(row.get(rk)), "job": job,
                         "status": "leading" if z >= 0.7 else ("lagging" if z <= -0.7 else "in-line")})
    other = [{"tile": a, "proxy": b, "z": _n(row.get(zk)), "r20": _n(row.get(rk))}
             for a, b, zk, rk in OTHER_TILES if zk in f.columns]
    tl = lab.tail(252)

    def agree(a, b):
        z = tl.dropna(subset=[a, b])
        z = z[(z[a] != "NA") & (z[b] != "NA")]
        return float((z[a].astype(str) == z[b].astype(str)).mean()) if len(z) else None

    labstats = {
        "gmm_vs_chip": agree("gmm", "sticky"), "gmm_vs_raw": agree("gmm", "raw_top"),
        "gmm_vs_peek": agree("gmm", "gmm_peek"),
        "flips": {"chip": _flips(tl["sticky"]), "raw": _flips(tl["raw_top"]), "gmm": _flips(tl["gmm"]),
                  "gmm_peek": _flips(tl["gmm_peek"]), "hmm_eq": _flips(tl["hmm_eq"][tl["hmm_eq"] != "NA"]),
                  "hmm_vol": _flips(tl["hmm_vol"][tl["hmm_vol"] != "NA"])},
    }
    return {"f": f, "hist": hist, "lab": lab, "row": row, "h": h, "ann": ann, "turb_on": turb_on,
            "sentence": sentence, "rhyme": rhyme, "cards": climate_cards(row, ann, str(h["sticky"])),
            "book": book, "other": other, "labstats": labstats, "term": term,
            "expected": EXPECTED.get(str(h["sticky"]), EXPECTED["MIXED"]),
            "events": {"turbulence": krt.loc[last_dt, "k_turb"], "inflation": krt.loc[last_dt, "k_infl"],
                       "growth": krt.loc[last_dt, "k_growth"], "turb_pct": _n(row.get("turb_pct"))}}


# ═══════════════════════════════════════════════════════════════════════════
#  EXPECTED-RETURNS LENS (Ilmanen 2011)  —  non-voting clauses on the climate chip (Market > Climate; ledger; ranker)
#  Ilmanen, Expected Returns (Wiley 2011): returns come from asset-class premia (equity, term, credit), style premia
#    (value, momentum, carry, defensive/quality) and the factors under them (growth, inflation, liquidity, tail risk).
#  1. Style clauses on the tape: size, quality vs junk, value vs momentum, defensive, credit, carry.
#  2. Slow condition variables that confirm or contradict the fast chip: drawdown depth and price vs its 5-year trend
#     (price stand-ins for valuation; CAPE isn't in Massive or FRED), the credit level, and with FRED the high-yield
#     spread, the 10y-2y slope and the 10y real yield.
#  3. Signature check: how many of the book's conditions for each climate hold today.
#  4. History check: what each style did over the next 20 sessions in each climate, on the loaded history.
#  All causal (rolling windows only); none of it votes on the chip.
# ═══════════════════════════════════════════════════════════════════════════

ILM_STYLES = [("size", "Size", "IWM", "SPY"), ("qmj", "Quality vs junk", "QUAL", "SPHB"),
              ("vm", "Value vs momentum", "VLUE", "MTUM"), ("def", "Defensive", "USMV", "SPY"),
              ("mom", "Momentum", "MTUM", "SPY"), ("credit", "Credit", "HYG", "IEF")]
ILM_EXPECT = {  # +1 = the book expects it to beat its benchmark in that climate, -1 to lag, 0 = no strong prior
    "size": {"STEADY": 1, "WOI": 1, "CRISIS": -1, "INFLATION": 0},
    "qmj": {"STEADY": -1, "WOI": -1, "CRISIS": 1, "INFLATION": 0},
    "vm": {"STEADY": -1, "WOI": -1, "CRISIS": 0, "INFLATION": 1},
    "def": {"STEADY": 0, "WOI": -1, "CRISIS": 1, "INFLATION": -1},
    "mom": {"STEADY": 1, "WOI": 1, "CRISIS": -1, "INFLATION": 0},
    "credit": {"STEADY": 1, "WOI": 0, "CRISIS": -1, "INFLATION": 0},
    "carry": {"STEADY": 1, "WOI": 0, "CRISIS": -1, "INFLATION": 0}}
ILM_CLAUSE = {"size": ("SIZE-ON", "SIZE-OFF", "SIZE-FLAT"), "qmj": ("QUALITY-BID", "JUNK-RALLY", "QMJ-FLAT"),
              "vm": ("VALUE-LEADS", "MOMENTUM-LEADS", "VM-FLAT"), "def": ("DEFENSIVE-BID", "DEFENSIVE-OFFERED", "DEF-FLAT"),
              "credit": ("CREDIT-ON", "CREDIT-OFF", "CREDIT-FLAT"), "carry": ("CARRY-ON", "CARRY-OFF", "CARRY-FLAT")}
ILM_LEDGER_NUM = ["z_qmj", "z_vm", "z_def", "z_carry", "spy_dd", "trend_pct", "credit_pct", "vm_pct"]
ILM_LEDGER_CAT = ["style_tape", "ilm_sig", "ilm_confirm"]
ILM_H = 20


def _cnd(mask: pd.Series, *inputs: pd.Series) -> pd.Series:
    """1/0 where at least one input is known, NaN where none is."""
    known = pd.concat(inputs, axis=1).notna().any(axis=1)
    return mask.astype(float).where(known)


def _cmax(a: pd.Series, b: pd.Series) -> pd.Series:
    return pd.concat([a, b], axis=1).max(axis=1)


ILM_SIGNATURE = {
    "STEADY": [("SPY up over 20 sessions", lambda D: _cnd(D["spy_r20"] > 0, D["spy_r20"])),
               ("Small caps keeping up (IWM / SPY)", lambda D: _cnd(D["z_size"] >= 0, D["z_size"])),
               ("Credit firm (HYG / IEF)", lambda D: _cnd(D["z_credit"] >= 0, D["z_credit"])),
               ("Realized vol moderate", lambda D: _cnd(D["z_vol"] <= 0.5, D["z_vol"])),
               ("Growth or tech supportive", lambda D: _cnd((D["z_growth"] >= 0) | (D["z_tech"] >= 0), D["z_growth"], D["z_tech"])),
               ("Momentum or junk favored", lambda D: _cnd((D["z_mom"] >= 0) | (D["z_qmj"] <= 0), D["z_mom"], D["z_qmj"]))],
    "CRISIS": [("SPY stressed", lambda D: _cnd((D["spy_r5"] <= -0.02) | (D["z_equity"] <= -1), D["spy_r5"], D["z_equity"])),
               ("Small caps lagging", lambda D: _cnd(D["z_size"] <= -0.5, D["z_size"])),
               ("Credit widening", lambda D: _cnd(D["z_credit"] <= -0.7, D["z_credit"])),
               ("Volatility rising", lambda D: _cnd(_cmax(D["z_vol"], D["z_vixy"]) >= 0.8, D["z_vol"], D["z_vixy"])),
               ("Treasuries bid (TLT)", lambda D: _cnd(D["z_rates"] >= 0.5, D["z_rates"])),
               ("Quality or defensive outperforming", lambda D: _cnd((D["z_qmj"] >= 0.5) | (D["z_def"] >= 0.5), D["z_qmj"], D["z_def"]))],
    "WOI": [("SPY still up over 20 sessions", lambda D: _cnd(D["spy_r20"] >= 0, D["spy_r20"])),
            ("Volatility elevated", lambda D: _cnd(_cmax(D["z_vol"], D["z_vixy"]) >= 0.5, D["z_vol"], D["z_vixy"])),
            ("Choppy: 10/20-day crosses", lambda D: _cnd(D["cross_15"] >= 3, D["cross_15"])),
            ("Style reversals (value vs momentum swinging)", lambda D: _cnd(D["z_vm"].abs() >= 1, D["z_vm"]))],
    "INFLATION": [("Long bonds weak (TLT)", lambda D: _cnd((D["tlt_r20"] <= -0.02) | (D["z_rates"] <= -0.7), D["tlt_r20"], D["z_rates"])),
                  ("Dollar or commodities confirming", lambda D: _cnd((D["z_dollar"].abs() >= 0.7) | (D["z_dbc"] >= 0.7), D["z_dollar"], D["z_dbc"])),
                  ("Equities under pressure", lambda D: _cnd(D["spy_r20"] <= 0, D["spy_r20"])),
                  ("Not a credit shock", lambda D: _cnd(D["z_credit"] > -0.7, D["z_credit"])),
                  ("Value beating momentum", lambda D: _cnd(D["z_vm"] >= 0.3, D["z_vm"]))],
}


def _clause(z: pd.Series, labels: Tuple[str, str, str], th: float = 0.5) -> List[str]:
    v = z.to_numpy(float)
    return ["" if not np.isfinite(x) else labels[0] if x >= th else labels[1] if x <= -th else labels[2] for x in v]


def ilmanen_features(closes: pd.DataFrame, clim: Dict[str, Any]) -> pd.DataFrame:
    f = clim["f"]
    c = closes.reindex(f.index)
    g = pd.DataFrame(index=f.index)
    for key, _, a, b in ILM_STYLES:
        g[f"z_{key}"] = robust_z(_ret_n(c[a] / c[b], 20)) if a in c and b in c else np.nan
    g["z_carry"] = -robust_z(_ret_n(c["FXY"], 20)) if "FXY" in c else np.nan      # yen falling = carry paying
    g["fxy_5"] = _ret_n(c["FXY"], 5) * 100 if "FXY" in c else np.nan
    for key in ILM_CLAUSE:
        g[f"cl_{key}"] = _clause(g[f"z_{key}"], ILM_CLAUSE[key])
    g.loc[g["fxy_5"] >= 1.5, "cl_carry"] = "UNWIND"
    on = ((g["cl_qmj"] == "JUNK-RALLY").astype(int) + (g["cl_def"] == "DEFENSIVE-OFFERED") + (g["cl_size"] == "SIZE-ON")
          + (g["cl_credit"] == "CREDIT-ON") + (g["cl_carry"] == "CARRY-ON"))
    off = ((g["cl_qmj"] == "QUALITY-BID").astype(int) + (g["cl_def"] == "DEFENSIVE-BID") + (g["cl_size"] == "SIZE-OFF")
           + (g["cl_credit"] == "CREDIT-OFF") + g["cl_carry"].isin(["CARRY-OFF", "UNWIND"]))
    known = g[["z_qmj", "z_def", "z_size", "z_credit"]].notna().any(axis=1)
    g["style_net"] = (on - off).astype(float).where(known)
    g["style_tape"] = np.where(~known, "", np.where(g["style_net"] >= 2, "RISK-ON STYLES",
                                                     np.where(g["style_net"] <= -2, "DEFENSIVE STYLES", "MIXED STYLES")))
    # slow condition variables
    spy = c["SPY"]
    g["spy_dd"] = spy / spy.rolling(252, min_periods=60).max() - 1
    ls = np.log(spy)
    g["trend5"] = ls - ls.rolling(1260, min_periods=504).mean()
    g["trend_pct"] = g["trend5"].rolling(2520, min_periods=252).rank(pct=True)
    if "HYG" in c and "IEF" in c:
        g["credit_pct"] = (c["HYG"] / c["IEF"]).rolling(756, min_periods=252).rank(pct=True)
    else:
        g["credit_pct"] = np.nan
    if "VLUE" in c and "MTUM" in c:
        g["vm3y"] = _ret_n(c["VLUE"] / c["MTUM"], 756)
        g["vm_pct"] = g["vm3y"].rolling(1260, min_periods=252).rank(pct=True)
    else:
        g["vm3y"] = g["vm_pct"] = np.nan
    # signature check against the chip
    D = f.join(g[["z_qmj", "z_vm", "z_def"]], how="left")
    for col in ("spy_r5", "spy_r20", "tlt_r20", "z_equity", "z_size", "z_credit", "z_vol", "z_vixy", "z_growth", "z_tech",
                "z_mom", "z_rates", "z_dollar", "z_dbc", "cross_15"):
        if col not in D:
            D[col] = np.nan
    for reg, conds in ILM_SIGNATURE.items():
        M = pd.concat([fn(D) for _, fn in conds], axis=1)
        g[f"sig_{reg}"] = M.mean(axis=1)                    # share of the book's conditions that hold (known ones)
    S = g[[f"sig_{r}" for r in ILM_SIGNATURE]].to_numpy(float)
    chip = clim["hist"]["sticky"].reindex(g.index).fillna("").astype(str).to_numpy()
    sig, conf = [], []
    regs = list(ILM_SIGNATURE)
    for s_row, ch in zip(S, chip):
        if not np.isfinite(s_row).any():
            sig.append("")
            conf.append("")
            continue
        top = np.nanmax(s_row)
        tops = [regs[j] for j in range(len(regs)) if np.isfinite(s_row[j]) and s_row[j] == top]
        best = tops[0] if (len(tops) == 1 and top >= 0.6) else "MIXED"
        sig.append(best)
        if ch not in ILM_SIGNATURE:
            conf.append("NO CHIP")
        else:
            mine = s_row[regs.index(ch)]
            conf.append("CONFIRMS" if mine >= 0.6 else
                        "CONTRADICTS" if (mine <= 0.34 and best not in (ch, "MIXED")) else "PARTIAL")
    g["ilm_sig"], g["ilm_confirm"] = sig, conf
    return g


def ilmanen_history(closes: pd.DataFrame, sticky: pd.Series, h: int = ILM_H) -> pd.DataFrame:
    """Next-`h`-session log return of each style ratio, grouped by the climate chip on the start day (descriptive)."""
    rows = []
    reg_order = list(LABELS) + ["MIXED"]
    for key, name, a, b in ILM_STYLES:
        if a not in closes or b not in closes:
            continue
        x = (closes[a] / closes[b]).dropna()
        fwd = (np.log(x.shift(-h) / x) * 100).rename("fwd")
        d = pd.concat([fwd, sticky.reindex(fwd.index).rename("reg")], axis=1).dropna()
        base = float(d["fwd"].mean()) if len(d) else np.nan
        for reg in reg_order:
            v = d.loc[d["reg"] == reg, "fwd"].to_numpy(float)
            if len(v) < 40:
                rows.append({"key": key, "style": name, "legs": f"{a}/{b}", "climate": reg, "sessions": len(v),
                             "mean": np.nan, "t": np.nan, "hit": np.nan, "all_days": base,
                             "expected": ILM_EXPECT[key].get(reg, 0)})
                continue
            mu, se = lg_nw(v, h - 1)
            rows.append({"key": key, "style": name, "legs": f"{a}/{b}", "climate": reg, "sessions": len(v), "mean": mu,
                         "t": mu / se if se and np.isfinite(se) and se > 0 else np.nan, "hit": float((v > 0).mean()),
                         "all_days": base, "expected": ILM_EXPECT[key].get(reg, 0)})
    out = pd.DataFrame(rows)
    if len(out):
        def verdict(r):
            if not np.isfinite(r["t"]) or r["expected"] == 0:
                return "no prior" if r["expected"] == 0 and np.isfinite(r["t"]) else "thin"
            if abs(r["t"]) < 2:
                return "unclear"
            return "agrees" if np.sign(r["mean"]) == r["expected"] else "disagrees"
        out["check"] = out.apply(verdict, axis=1)
    return out


def ilmanen_fred(series: Optional[Dict[str, pd.Series]]) -> Dict[str, Any]:
    """Latest level, 1-month change and 3-year percentile of the FRED slow variables, when FRED is loaded."""
    out: Dict[str, Any] = {}
    for sid in ("BAMLH0A0HYM2", "T10Y2Y", "DFII10"):
        s = (series or {}).get(sid)
        if s is None or s.dropna().empty:
            continue
        s = s.dropna()
        last = float(s.iloc[-1])
        prev = s[s.index <= s.index[-1] - pd.Timedelta(days=30)]
        w = s[s.index >= s.index[-1] - pd.Timedelta(days=3 * 365)]
        out[sid] = {"last": last, "chg_1m": last - float(prev.iloc[-1]) if len(prev) else np.nan,
                    "pct_3y": float((w <= last).mean()), "asof": s.index[-1].date().isoformat()}
    return out


def ilmanen_page(closes: pd.DataFrame, clim: Dict[str, Any]) -> Dict[str, Any]:
    g = ilmanen_features(closes, clim)
    row = g.iloc[-1]
    chip = str(clim["h"]["sticky"])
    D = clim["f"].join(g[["z_qmj", "z_vm", "z_def"]], how="left").iloc[[-1]]
    for col in ("spy_r5", "spy_r20", "tlt_r20", "z_equity", "z_size", "z_credit", "z_vol", "z_vixy", "z_growth", "z_tech",
                "z_mom", "z_rates", "z_dollar", "z_dbc", "cross_15"):
        if col not in D:
            D[col] = np.nan
    checks = []
    for reg, conds in ILM_SIGNATURE.items():
        for lab_, fn in conds:
            v = float(fn(D).iloc[0])
            checks.append({"climate": reg, "condition": lab_, "holds": "yes" if v == 1 else "no" if v == 0 else "n/a"})
    ck = pd.DataFrame(checks)
    ck = ck.iloc[np.argsort((ck["climate"] != chip).to_numpy(), kind="stable")].reset_index(drop=True)   # the chip's rows first
    return {"g": g, "row": row, "chip": chip, "checks": ck, "chip_hist": clim["hist"]["sticky"],
            "history": ilmanen_history(closes, clim["hist"]["sticky"])}


# ═══════════════════════════════════════════════════════════════════════════
#  CROSS-ASSET NARRATIVES  (Market > Narratives; also feeds the Setup ledger and the Trade ranker)
#  What stocks, bonds, the dollar, credit, carry and commodities are saying together, every day, causally.
#  Shock mix: Cieslak & Pang (2021, JFE) identify four common shocks from stock returns and 2y/10y yield changes
#    with sign restrictions: growth news (stocks +, yields +, short end more), monetary (stocks -, yields +, short
#    end more), common risk premium (stocks -, yields +, long end more) and hedging premium (stocks -, yields -,
#    long end more). Here each day's sign pattern of (SPY, yield level, 10y-2y slope) is tagged with the one shock
#    and sign it matches; the 20-day size-weighted net share of each is the narrative mix. Yields come from SHY and
#    IEF returns divided by duration. This is a tagging heuristic built on their restrictions, not their VAR.
#  Stock-bond correlation: positive when inflation and rates drive both (Campbell, Pflueger & Viceira 2020, JPE;
#    Baele, Bekaert & Inghelbrecht 2010, RFS): bonds stop hedging.
#  Risk-on/risk-off: the Kansas City Fed RORO index (Chari, Dilts Stedman & Lundblad 2024) is the first principal
#    component of daily changes in credit, equity volatility, funding and currency/gold series. Here: an equal-weight
#    average of signed daily z-scores of SPY, IWM, EEM, HYG/IEF, copper/gold, VIXY (-) and the yen (-).
#  Dollar: a strong dollar tightens global financial conditions (Avdjiev, Du, Koch & Shin 2019, AER: Insights).
#  Carry: yen carry trades crash when risk appetite falls (Brunnermeier, Nagel & Pedersen 2008); the War Room's
#    unwind rule (USDJPY down 1.5%) maps to FXY up 1.5% in five sessions.
#  Credit: credit spreads lead activity and equities (Gilchrist & Zakrajsek 2012, AER); equity strength on weak
#    credit is a divergence.
#  Quadrant: market-implied growth (risk appetite, copper/gold, credit) vs inflation (breakevens, yield level),
#    after Ilmanen, Maloney & Ross (2014, JPM) on how assets behave across growth and inflation environments.
#  Leadership pairs: the War Room's 12 ratios in four buckets; industries can lead the market (Hong, Torous &
#    Valkanov 2007, JFE).
#  Persistence: a statistical jump model (Nystrup et al.; Shu & Mulvey 2024) on the narrative features, refit
#    every quarter on past data only, with each day's state read from the forward pass (no look-ahead).
# ═══════════════════════════════════════════════════════════════════════════

NAR_DUR = {"SHY": 1.9, "IEF": 7.3}
NAR_SHOCKS = ["growth", "monetary", "premium", "hedging"]
NAR_TAG = {(1, 1, -1): ("growth", 1), (-1, -1, 1): ("growth", -1), (-1, 1, -1): ("monetary", 1), (1, -1, 1): ("monetary", -1),
           (-1, 1, 1): ("premium", 1), (1, -1, -1): ("premium", -1), (-1, -1, -1): ("hedging", 1), (1, 1, 1): ("hedging", -1)}
NAR_NAME = {("growth", 1): "GROWTH NEWS", ("growth", -1): "GROWTH SCARE", ("monetary", 1): "HAWKISH",
            ("monetary", -1): "DOVISH", ("premium", 1): "RISK PREMIUM UP", ("premium", -1): "PREMIUM COMPRESSION",
            ("hedging", 1): "FLIGHT TO SAFETY", ("hedging", -1): "SAFETY UNWIND"}
NAR_READ = {
    "GROWTH NEWS": ("stocks and yields up, short end leading: better cash-flow news. Cyclicals and small caps tend to lead; "
                    "normal size."),
    "GROWTH SCARE": ("stocks and yields down, short end falling faster (bull steepener): weaker growth. Defensive and "
                     "quality leadership; cyclicals and small caps lag. Smaller size on breakouts."),
    "HAWKISH": ("stocks down, short yields up, curve flattening: policy is the story. Long-duration growth suffers most; "
                "favor tight entries near the averages."),
    "DOVISH": "stocks up, short yields down: easier policy. Tailwind for duration and growth; continuation entries work.",
    "RISK PREMIUM UP": ("stocks down while long yields rise (bear steepener): stocks and bonds are both being re-priced. The "
                        "War Room's multiple-killer. Tight MA entries only, size down."),
    "PREMIUM COMPRESSION": ("stocks up, long yields falling: risk premia compressing across assets, an everything rally. "
                            "Continuation entries; watch for stretched names."),
    "FLIGHT TO SAFETY": ("stocks down, long yields falling hardest: investors buying bonds as a hedge. Sit or size down "
                         "until credit stabilizes."),
    "SAFETY UNWIND": "stocks up while long yields rise: money rotating out of bonds into stocks. Normal size.",
    "MIXED": "no single cross-asset story dominates the last 20 sessions.",
}
NAR_QUADS ={(1, -1): "GOLDILOCKS", (1, 1): "REFLATION", (-1, 1): "STAGFLATION SCARE", (-1, -1): "DEFLATION SCARE"}
NAR_CURVE = {(-1, 1): "BULL STEEPENER", (-1, -1): "BULL FLATTENER", (1, 1): "BEAR STEEPENER", (1, -1): "BEAR FLATTENER"}
LEAD_PAIRS = {"lead_spec": ("Speculative risk-on", [("SOXX", "SPY"), ("IGV", "SPY"), ("KRE", "XLF"), ("IBB", "XLV"), ("XRT", "XLY")]),
              "lead_cyc": ("Cyclical expansion", [("ITB", "XHB"), ("OIH", "XLE"), ("IYT", "SPY")]),
              "lead_comm": ("Commodity confirmation", [("XOP", "XLE"), ("GDX", "GLD")]),
              "lead_idio": ("Idiosyncratic", [("CIBR", "XLK"), ("ITA", "XLI")])}
NAR_RORO = [("SPY", 1), ("IWM", 1), ("EEM", 1), ("HYG/IEF", 1), ("CPER/GLD", 1), ("VIXY", -1), ("FXY", -1)]
NAR_JUMP_COLS = ["roro_20", "lvl_20", "slope_20", "sb_corr2", "usd_20", "credit_20", "cg_20", "vol_z"]
NAR_JUMP_K, NAR_JUMP_LAMBDA, NAR_JUMP_REFIT, NAR_JUMP_MIN, NAR_JUMP_WIN, NAR_JUMP_WARM = 4, 60.0, 63, 504, 1260, 252
NAR_LEDGER_NUM = ["nar_growth", "nar_monetary", "nar_premium", "nar_hedging", "sb_corr", "roro_20", "roro_acc", "usd_20",
                  "usd_acc", "carry_5", "credit_div", "cg_20", "be_20", "rr_20", "lvl_20", "slope_20", "lead_spec", "lead_cyc",
                  "lead_comm", "lead_idio", "lead_all"]
NAR_LEDGER_CAT = ["nar_tag", "nar_quad", "curve_regime", "nar_jump"]


def _sticky(raw: List[str], hyst: int = HYST, empty: str = "") -> Tuple[List[str], List[int]]:
    """A label changes only after the same new raw label shows up `hyst` sessions in a row ("" = no data)."""
    out, ages = [], []
    cur, age, pend, pn = empty, 0, None, 0
    for r in raw:
        if r == empty or r is None:
            out.append(cur)
            ages.append(age)
            continue
        if cur == empty:
            cur, age, pend, pn = r, 1, None, 0
        elif r == cur:
            age, pend, pn = age + 1, None, 0
        else:
            pend, pn = (r, pn + 1) if pend == r else (r, 1)
            if pn >= hyst:
                cur, age, pend, pn = r, 1, None, 0
            else:
                age += 1
        out.append(cur)
        ages.append(age)
    return out, ages


def _jm_dp(C: np.ndarray, lam: float) -> np.ndarray:
    """State path minimizing sum of costs plus `lam` per switch (Viterbi-style dynamic programming)."""
    T, K = C.shape
    Cl = C.tolist()
    V = list(Cl[0])
    back = [[0] * K for _ in range(T)]
    rng_k = range(K)
    for t in range(1, T):
        m = min(V)
        j = V.index(m)
        m += lam
        row, bt, nv = Cl[t], back[t], [0.0] * K
        for k in rng_k:
            if V[k] <= m:
                nv[k], bt[k] = row[k] + V[k], k
            else:
                nv[k], bt[k] = row[k] + m, j
        V = nv
    s = np.empty(T, dtype=np.int64)
    s[-1] = int(np.argmin(V))
    for t in range(T - 1, 0, -1):
        s[t - 1] = back[t][s[t]]
    return s


def jm_fit(X: np.ndarray, K: int = NAR_JUMP_K, lam: float = NAR_JUMP_LAMBDA, n_init: int = 3, iters: int = 10,
           seed: int = 0) -> Tuple[np.ndarray, np.ndarray]:
    """Statistical jump model: minimize sum 0.5*||x_t - mu_s||^2 + lam * #switches by coordinate descent
    (Nystrup et al. 2020), k-means++ starts, best of n_init."""
    rng = np.random.default_rng(seed)
    T = len(X)
    best = (np.inf, None, None)
    for _ in range(n_init):
        mu = [X[rng.integers(T)]]
        for _k in range(1, K):
            d2 = np.min(((X[:, None, :] - np.array(mu)[None]) ** 2).sum(-1), axis=1)
            mu.append(X[rng.choice(T, p=d2 / d2.sum())] if d2.sum() > 0 else X[rng.integers(T)])
        mu = np.array(mu, dtype=float)
        prev = None
        for _it in range(iters):
            C = 0.5 * ((X[:, None, :] - mu[None]) ** 2).sum(-1)
            s = _jm_dp(C, lam)
            if prev is not None and np.array_equal(s, prev):
                break
            prev = s
            for k in range(K):
                if (s == k).any():
                    mu[k] = X[s == k].mean(axis=0)
        C = 0.5 * ((X[:, None, :] - mu[None]) ** 2).sum(-1)
        obj = float(C[np.arange(T), s].sum() + lam * (np.diff(s) != 0).sum())
        if obj < best[0]:
            best = (obj, mu.copy(), s.copy())
    return best[1], best[2]


def jm_names(mu: np.ndarray, cols: List[str]) -> List[str]:
    """Readable names from each state's centre: risk appetite and the direction of yields."""
    ix = {c_: i for i, c_ in enumerate(cols)}
    names = []
    for m in mu:
        risk = np.nanmean([m[ix[c_]] for c_ in ("roro_20", "credit_20", "cg_20") if c_ in ix])
        names.append(("Risk-on" if risk > 0 else "Risk-off") + (", yields up" if m[ix["lvl_20"]] > 0 else ", yields down"))
    seen: Dict[str, int] = {}
    out = []
    for nm in names:                                   # two states can share a description
        seen[nm] = seen.get(nm, 0) + 1
        out.append(nm if seen[nm] == 1 else f"{nm} ({seen[nm]})")
    return out


def jm_walk(X: pd.DataFrame, K: int = NAR_JUMP_K, lam: float = NAR_JUMP_LAMBDA, refit: int = NAR_JUMP_REFIT,
            min_train: int = NAR_JUMP_MIN, win: int = NAR_JUMP_WIN, warm: int = NAR_JUMP_WARM) -> pd.Series:
    """Walk forward: refit every `refit` sessions on the last `win` sessions before the refit date; between refits each
    day's state is the argmin of the forward recursion (the last state of the DP over data up to that day)."""
    valid = X.notna().all(axis=1).to_numpy()
    Xv = X[valid].to_numpy(float)
    dates = X.index[valid]
    out = pd.Series("", index=X.index, dtype=object)
    n = len(Xv)
    for r in range(min_train, n, refit):
        mu, _ = jm_fit(Xv[max(0, r - win):r], K, lam)
        names = jm_names(mu, list(X.columns))
        a, b = max(0, r - warm), min(n, r + refit)
        C = 0.5 * ((Xv[a:b, None, :] - mu[None]) ** 2).sum(-1)
        V = C[0].copy()
        for t in range(1, len(C)):
            V = C[t] + np.minimum(V, V.min() + lam)
            if a + t >= r:
                out.loc[dates[a + t]] = names[int(np.argmin(V))]
    return out


def narrative_features(closes: pd.DataFrame, jump: bool = True) -> pd.DataFrame:
    need = ["SPY", "SHY", "IEF"]
    missing = [t for t in need if t not in closes.columns]
    if missing:
        raise ValueError(f"Narratives need {need}; missing {missing}")
    c = closes.dropna(subset=need).copy()
    f = pd.DataFrame(index=c.index)
    r = lambda t: c[t].pct_change(fill_method=None) if t in c else pd.Series(np.nan, index=c.index)
    ratio = lambda a, b: (c[a] / c[b]) if a in c and b in c else pd.Series(np.nan, index=c.index)
    sd = lambda x: x.rolling(Z_WIN, min_periods=Z_WIN // 2).std()
    s = r("SPY")
    y2, y10 = -r("SHY") / NAR_DUR["SHY"] * 100, -r("IEF") / NAR_DUR["IEF"] * 100     # approx. yield changes, % points
    lvl, slope = (y2 + y10) / 2, y10 - y2
    zs, zl, zd = s / sd(s), lvl / sd(lvl), slope / sd(slope)
    ok = zs.notna() & zl.notna() & zd.notna()
    sg = lambda z: np.where(z.to_numpy() >= 0, 1, -1)
    pat = list(zip(sg(zs), sg(zl), sg(zd)))
    w = np.sqrt(zs ** 2 + zl ** 2 + zd ** 2).where(ok, 0.0)
    tags = [NAR_TAG[p] if o else (None, 0) for p, o in zip(pat, ok.to_numpy())]
    for k in NAR_SHOCKS:
        contrib = pd.Series([sgn if kk == k else 0 for kk, sgn in tags], index=c.index, dtype=float) * w
        f[f"nar_{k}"] = contrib.rolling(20, min_periods=15).sum() / w.rolling(20, min_periods=15).sum().replace(0, np.nan)
    f["tag_day"] = [NAR_NAME[t] if t[0] else "" for t in tags]
    mix = f[[f"nar_{k}" for k in NAR_SHOCKS]].to_numpy(float)
    raw = []
    for row in mix:
        if not np.isfinite(row).all():
            raw.append("")
            continue
        j = int(np.argmax(np.abs(row)))
        raw.append(NAR_NAME[(NAR_SHOCKS[j], 1 if row[j] >= 0 else -1)] if abs(row[j]) >= 0.15 else "MIXED")
    f["nar_tag"], f["nar_age"] = _sticky(raw)
    # curve over 20 sessions
    l20, d20 = lvl.rolling(20, min_periods=15).sum(), slope.rolling(20, min_periods=15).sum()
    f["lvl_20"], f["slope_20"] = robust_z(l20), robust_z(d20)
    curve = [("" if not (np.isfinite(a) and np.isfinite(b)) else "QUIET" if max(abs(a), abs(b)) < 0.25 else
              NAR_CURVE[(1 if l_ > 0 else -1, 1 if d_ > 0 else -1)])
             for a, b, l_, d_ in zip(f["lvl_20"], f["slope_20"], l20, d20)]
    f["curve_regime"], _ = _sticky(curve)
    f["sb_corr"] = s.rolling(63, min_periods=40).corr(r("IEF"))
    f["sb_corr2"] = 2 * f["sb_corr"]
    # risk-on / risk-off
    parts = []
    for key, sgn in NAR_RORO:
        x = (ratio(*key.split("/")).pct_change(fill_method=None) if "/" in key else r(key))
        if x.notna().sum() > 60:
            parts.append(sgn * x / sd(x))
    roro_d = pd.concat(parts, axis=1).mean(axis=1) if parts else pd.Series(np.nan, index=c.index)
    f["roro"] = roro_d.fillna(0).cumsum()
    f["roro_20"] = roro_d.rolling(20, min_periods=15).sum() / math.sqrt(20)
    f["roro_acc"] = (roro_d.rolling(10, min_periods=8).mean() - roro_d.rolling(20, min_periods=15).mean()) * math.sqrt(10)
    # dollar, carry, credit, commodities, inflation
    ret_n = lambda x, n: x / x.shift(n) - 1
    if "UUP" in c:
        f["usd_20"] = robust_z(ret_n(c["UUP"], 20))
        f["usd_acc"] = (ret_n(c["UUP"], 10) / 10 - ret_n(c["UUP"], 20) / 20) * 1e4
        em = ratio("EEM", "SPY")
        f["usd_wreck"] = ((f["usd_20"] > 1) & (ret_n(em, 20) < 0)).astype(float).where(f["usd_20"].notna())
    else:
        f["usd_20"] = f["usd_acc"] = f["usd_wreck"] = np.nan
    f["carry_5"] = ret_n(c["FXY"], 5) * 100 if "FXY" in c else np.nan
    f["carry_unwind"] = (f["carry_5"] >= 1.5).astype(float).where(pd.Series(f["carry_5"]).notna())
    f["credit_20"] = robust_z(ret_n(ratio("HYG", "IEF"), 20))
    eq20 = robust_z(ret_n(c["SPY"], 20))
    f["credit_div"] = eq20 - f["credit_20"]
    near_hi = c["SPY"] >= c["SPY"].rolling(252, min_periods=120).max() * 0.97
    f["credit_div_flag"] = ((f["credit_div"] >= 1.5) & near_hi).astype(float).where(f["credit_div"].notna())
    f["cg_20"] = robust_z(ret_n(ratio("CPER", "GLD"), 20))
    f["be_20"] = robust_z(ret_n(ratio("TIP", "IEF"), 20))
    f["rr_20"] = robust_z(-ret_n(c["TIP"], 20)) if "TIP" in c else np.nan
    f["vol_z"] = robust_z(s.rolling(20, min_periods=15).std() * math.sqrt(252))
    # growth / inflation quadrant (market-implied)
    with np.errstate(all="ignore"):
        G = np.nanmean(np.vstack([f["roro_20"].to_numpy(float), f["cg_20"].to_numpy(float), f["credit_20"].to_numpy(float)]), axis=0)
        I_ = np.nanmean(np.vstack([f["be_20"].to_numpy(float), f["lvl_20"].to_numpy(float)]), axis=0)
    f["growth_axis"], f["infl_axis"] = G, I_
    quad = [("" if not (np.isfinite(g) and np.isfinite(i_)) else "" if min(abs(g), abs(i_)) < 0.25 else
             NAR_QUADS[(1 if g > 0 else -1, 1 if i_ > 0 else -1)]) for g, i_ in zip(G, I_)]
    f["nar_quad"], f["nar_quad_age"] = _sticky(quad)
    # leadership pairs (War Room buckets): share of ratios above their 50-day average
    allp = []
    for key, (_, pairs) in LEAD_PAIRS.items():
        cols_ = []
        for a, b in pairs:
            x = ratio(a, b)
            if x.notna().sum() > 60:
                sma = x.rolling(50, min_periods=40).mean()
                cols_.append((x > sma).astype(float).where(sma.notna()))
        f[key] = pd.concat(cols_, axis=1).mean(axis=1) if cols_ else np.nan
        allp += cols_
    f["lead_all"] = pd.concat(allp, axis=1).mean(axis=1) if allp else np.nan
    if jump:
        X = f[NAR_JUMP_COLS].clip(-4, 4)
        f["nar_jump"] = jm_walk(X) if X.notna().all(axis=1).sum() > NAR_JUMP_MIN + 40 else ""
    else:
        f["nar_jump"] = ""
    return f


def narrative_sentence(row: pd.Series) -> str:
    tag = str(row.get("nar_tag") or "MIXED")
    bits = [f"Over the last 20 sessions the tape traded like {tag.lower()}: {NAR_READ.get(tag, '')}"]
    cr = str(row.get("curve_regime") or "")
    if cr:
        bits.append(f"Curve: {cr.lower()}.")
    sb = _n(row.get("sb_corr"), np.nan)
    if np.isfinite(sb):
        bits.append(f"Stock-bond correlation {sb:+.2f}: " + ("bonds and stocks are moving together, so rates and inflation are "
                                                            "the story and bonds aren't a hedge." if sb > 0.2 else
                                                            "bonds are hedging stocks (a growth-driven tape)." if sb < -0.2
                                                            else "no clear link between bonds and stocks."))
    rr, ra = _n(row.get("roro_20"), np.nan), _n(row.get("roro_acc"), np.nan)
    if np.isfinite(rr):
        bits.append(f"Risk appetite (RORO) {rr:+.1f}, {'improving' if ra > 0 else 'fading'} on the 10 vs 20-day view.")
    if _n(row.get("carry_unwind"), 0) == 1:
        bits.append(f"Yen carry unwind: FXY {_n(row.get('carry_5')):+.1f}% in five sessions, so cut size 30-50%.")
    if _n(row.get("usd_wreck"), 0) == 1:
        bits.append("Dollar wrecking ball: strong dollar with emerging markets lagging.")
    if _n(row.get("credit_div_flag"), 0) == 1:
        bits.append("Credit is not confirming: SPY near its high while high yield lags Treasuries.")
    return " ".join(bits)


def narrative_page(closes: pd.DataFrame) -> Dict[str, Any]:
    f = narrative_features(closes)
    row = f.iloc[-1]
    spy = closes["SPY"].reindex(f.index)
    fwd = spy.shift(-20) / spy - 1
    hist = (pd.DataFrame({"tag": f["nar_tag"], "fwd": fwd}).dropna().query("tag != ''")
            .groupby("tag")["fwd"].agg(days="size", mean="mean", hit=lambda x: float((x > 0).mean())).reset_index())
    jm = f["nar_jump"].replace("", np.nan).dropna()
    sw = int((jm != jm.shift()).sum() - 1) if len(jm) else 0
    return {"f": f, "row": row, "sentence": narrative_sentence(row), "hist": hist,
            "jump_switches_per_year": sw / max(len(jm) / 252, 1e-9) if len(jm) else np.nan}


# ---- CMT views of the narrative ---------------------------------------------------------------------------------------
#  Pring's business cycle: bonds (TLT), stocks (SPY) and commodities (DBC) are each bullish above their 12-month moving
#    average on month-end closes; the three-way combination is the stage. Six stages run bonds -> stocks -> commodities
#    turning up, then the same order turning down; VII and VIII are off-cycle combinations (pring.com). His timing
#    ratios are bond/commodity (Stage I), stock/commodity (II) and commodity/bond (III) with the KST.
#  KST (Pring, daily set): 10-SMA of ROC10 x1 + 10-SMA of ROC15 x2 + 10-SMA of ROC20 x3 + 15-SMA of ROC30 x4; signal = 9-SMA.
#  Murphy's intermarket relationships: classic signs between bonds, stocks, commodities, the dollar and gold.
#  Dow Theory: the industrials (DIA) and transports (IYT) must confirm each other's new highs or lows.

PRING_LEGS = [("Bonds", "TLT"), ("Stocks", "SPY"), ("Commodities", "DBC")]
PRING_STAGE = {(1, 0, 0): "I", (1, 1, 0): "II", (1, 1, 1): "III", (0, 1, 1): "IV", (0, 0, 1): "V", (0, 0, 0): "VI",
               (0, 1, 0): "VII", (1, 0, 1): "VIII"}
PRING_ORDER = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII"]
PRING_READ = {
    "I": ("Bonds turn up", "Rates have peaked: bonds are bullish while stocks and commodities are still falling. Pring's first "
                           "buy of the cycle is bonds (the bond/commodity ratio)."),
    "II": ("Stocks join bonds", "Bonds and stocks bullish, commodities still bearish: the early-expansion stage, historically "
                                "the best one for equities (the stock/commodity ratio)."),
    "III": ("All three bullish", "Bonds, stocks and commodities all above their 12-month averages: mid-expansion. Commodities "
                                 "are next to lead (the commodity/bond ratio)."),
    "IV": ("Bonds roll over", "Bonds have peaked as inflation pressure builds while stocks and commodities still rise: late "
                              "expansion. Rates are now a headwind for multiples."),
    "V": ("Stocks roll over", "Only commodities are bullish: the late-cycle inflation stage. Breakouts fail more often here."),
    "VI": ("All three bearish", "Bonds, stocks and commodities all below their 12-month averages: contraction. The next turn up "
                                "comes from bonds."),
    "VII": ("Off-cycle: stocks alone", "Stocks bullish while bonds and commodities are bearish. Not one of Pring's six stages, "
                                       "so the cycle read is unconfirmed."),
    "VIII": ("Off-cycle: stocks lagging", "Bonds and commodities bullish while stocks are bearish. Not one of Pring's six stages."),
}
KST_ROC, KST_SMA, KST_W, KST_SIG = (10, 15, 20, 30), (10, 10, 10, 15), (1, 2, 3, 4), 9
PRING_RATIOS = [("TLT", "DBC", "Bonds / commodities", "Stage I timing: a KST buy says bonds are taking over from commodities. "
                 "Its mirror, commodities / bonds, is the Stage III signal."),
                ("SPY", "DBC", "Stocks / commodities", "Stage II timing: a KST buy says stocks are taking over from commodities.")]
MURPHY = [("Bonds and stocks", "TLT", "SPY", 1, "Bond prices usually trend with stocks and turn first. The link flips negative in "
           "deflation scares and flights to safety."),
          ("Commodities and bonds", "DBC", "TLT", -1, "Rising commodities mean inflation pressure, which pushes bond prices down."),
          ("Dollar and commodities", "UUP", "DBC", -1, "A rising dollar usually weighs on dollar-priced commodities."),
          ("Dollar and gold", "UUP", "GLD", -1, "Gold usually trades against the dollar."),
          ("Copper/gold and bonds", "CPER/GLD", "TLT", -1, "Copper beating gold goes with rising yields, so with falling bond prices."),
          ("Yen and stocks", "FXY", "SPY", -1, "The yen is a funding and haven currency: it rallies when stocks sell off.")]
CMT_RATIOS = [("Stocks / bonds", "SPY", "TLT", "risk"), ("Commodities / bonds", "DBC", "TLT", "inflation"),
              ("Copper / gold", "CPER", "GLD", "risk"), ("High yield / Treasuries", "HYG", "IEF", "risk"),
              ("Discretionary / staples", "XLY", "XLP", "risk"), ("Small / large", "IWM", "SPY", "risk"),
              ("Equal / cap weight", "RSP", "SPY", "risk"), ("Semis / market", "SMH", "SPY", "risk")]
# Weekly weather map: every force signed so that + = tailwind for stocks
WX_ROWS = [("Growth news", "nar_growth", 2.0), ("Policy (dovish = +)", "nar_monetary", -2.0),
           ("Risk premium (compressing = +)", "nar_premium", -2.0), ("Hedging (unwinding = +)", "nar_hedging", -2.0),
           ("Risk appetite (RORO)", "roro_20", 1.0), ("Credit (HYG / IEF)", "credit_20", 1.0), ("Copper / gold", "cg_20", 1.0),
           ("Dollar (weaker = +)", "usd_20", -1.0), ("Yen carry (FXY falling = +)", "carry_z", -1.0),
           ("Volatility (calmer = +)", "vol_z", -1.0), ("Leadership pairs", "lead_z", 1.0)]
WX_NET = "NET (average)"


def period_end_rows(df: pd.DataFrame, freq: str = "M") -> pd.DataFrame:
    """Last row of each calendar period (month 'M' or week 'W-FRI'); the final row is the latest session."""
    idx = df.index
    last = pd.Series(idx, index=idx).groupby(idx.to_period(freq)).max()
    return df.loc[last.to_numpy()]


def kst(x: pd.Series) -> pd.DataFrame:
    k = sum(w * ((x / x.shift(n) - 1) * 100).rolling(s, min_periods=s).mean() for n, s, w in zip(KST_ROC, KST_SMA, KST_W))
    return pd.DataFrame({"kst": k, "signal": k.rolling(KST_SIG, min_periods=KST_SIG).mean()}, index=x.index)


def last_cross(a: pd.Series, b: pd.Series) -> Tuple[str, Optional[pd.Timestamp]]:
    """Which side `a` is on vs `b` now, and the session it got there."""
    d = (a - b).dropna()
    if d.empty:
        return "", None
    side = np.sign(d)
    flips = side.ne(side.shift()) & side.shift().notna()
    when = d.index[flips.to_numpy()][-1] if flips.any() else None
    return ("above" if side.iloc[-1] > 0 else "below"), when


def pring_stages(closes: pd.DataFrame) -> Optional[Dict[str, Any]]:
    legs = [t for _, t in PRING_LEGS]
    if any(t not in closes.columns for t in legs):
        return None
    c = closes[legs].dropna()
    if len(c) < 300:
        return None
    m = period_end_rows(c, "M")
    ma = m.rolling(12, min_periods=12).mean()
    ok = ma.notna().all(axis=1).to_numpy()
    m, ma = m[ok], ma[ok]
    if len(m) < 2:
        return None
    bull = (m > ma).astype(int)
    out = pd.DataFrame({"stage": [PRING_STAGE[tuple(r)] for r in bull.to_numpy().tolist()]}, index=m.index)
    out["num"] = out["stage"].map({s: i + 1 for i, s in enumerate(PRING_ORDER)})
    run = lambda s: int((s.iloc[::-1] == s.iloc[-1]).astype(int).cumprod().sum())
    legs_now = []
    for nm, t in PRING_LEGS:
        out[t], out[f"{t}_ma"], out[f"{t}_bull"] = m[t], ma[t], bull[t]
        legs_now.append({"market": nm, "etf": t, "close": float(m[t].iloc[-1]), "ma12": float(ma[t].iloc[-1]),
                         "vs_ma": float(m[t].iloc[-1] / ma[t].iloc[-1] - 1),
                         "reading": "BULLISH" if bull[t].iloc[-1] else "BEARISH", "months": run(bull[t])})
    last = out.index[-1]
    return {"m": out, "stage": out["stage"].iloc[-1], "age": run(out["stage"]), "legs": pd.DataFrame(legs_now),
            "provisional": bool((last + pd.offsets.BMonthEnd(0)).normalize() != last.normalize()), "asof": last}


def narrative_weather(f: pd.DataFrame, weeks: int = 52) -> pd.DataFrame:
    """Long frame (week, force, value) of the narrative forces at each week's last session, + = tailwind for stocks."""
    g = pd.DataFrame(index=f.index)
    for col in {c_ for _, c_, _ in WX_ROWS} - {"carry_z", "lead_z"}:
        g[col] = f[col] if col in f else np.nan
    g["carry_z"] = robust_z(f["carry_5"]) if "carry_5" in f and pd.Series(f["carry_5"]).notna().sum() > 130 else np.nan
    g["lead_z"] = (f["lead_all"] - 0.5) * 4 if "lead_all" in f else np.nan
    w = period_end_rows(g, "W-FRI").iloc[-weeks:]
    rows = []
    for lab_, col, k in WX_ROWS:
        v = (w[col].astype(float) * k).clip(-2.5, 2.5)
        rows.append(pd.DataFrame({"week": w.index, "force": lab_, "value": v.to_numpy()}))
    long = pd.concat(rows, ignore_index=True)
    net = long.groupby("week")["value"].mean().reset_index().assign(force=WX_NET)
    return pd.concat([net[["week", "force", "value"]], long], ignore_index=True)


def murphy_map(closes: pd.DataFrame, win: int = 63, months: int = 36) -> Tuple[pd.DataFrame, pd.DataFrame]:
    def ret(key):
        if "/" in key:
            a, b = key.split("/")
            return (closes[a] / closes[b]).pct_change(fill_method=None) if a in closes and b in closes else None
        return closes[key].pct_change(fill_method=None) if key in closes else None
    cells, rows = [], []
    for name, a, b, sgn, why in MURPHY:
        ra, rb = ret(a), ret(b)
        if ra is None or rb is None:
            continue
        cor = ra.rolling(win, min_periods=int(win * 0.65)).corr(rb).dropna()
        if len(cor) < 60:
            continue
        me = period_end_rows(cor.to_frame("c"), "M")["c"].iloc[-months:]
        cells.append(pd.DataFrame({"month": me.index, "relationship": name, "corr": me.to_numpy(), "agree": me.to_numpy() * sgn}))
        now, yr = float(cor.iloc[-1]), float(cor.iloc[-252:].median())
        state = "holding" if now * sgn > 0.15 else "broken" if now * sgn < -0.15 else "weak"
        rows.append({"relationship": name, "legs": f"{a} vs {b}", "classic": "+" if sgn > 0 else "-", "corr now": now,
                     "1y median": yr, "status": state, "why": why})
    return (pd.concat(cells, ignore_index=True) if cells else pd.DataFrame()), pd.DataFrame(rows)


def dow_theory(closes: pd.DataFrame, look: int = 252, recent: int = 63) -> Optional[Dict[str, Any]]:
    """Simplified Dow Theory: a 52-week closing high (low) in one average must be matched by the other within `recent`
    sessions. The primary trend is the last confirmed signal and stays in force until the opposite one is confirmed."""
    if "DIA" not in closes or "IYT" not in closes:
        return None
    c = closes[["DIA", "IYT"]].dropna()
    if len(c) < look + 40:
        return None
    hi = c >= c.rolling(look, min_periods=look).max()
    lo = c <= c.rolling(look, min_periods=look).min()
    hi_r, lo_r = hi.rolling(recent, min_periods=1).max().astype(bool), lo.rolling(recent, min_periods=1).max().astype(bool)
    up, dn = hi_r.all(axis=1) & hi.any(axis=1), lo_r.all(axis=1) & lo.any(axis=1)
    sig = pd.Series(np.where(up, "UP", np.where(dn, "DOWN", None)), index=c.index, dtype=object)
    trend = sig.ffill().fillna("UNSET")
    last_sig = sig.dropna()
    since = last_sig.index[last_sig.ne(last_sig.shift()).to_numpy()][-1] if len(last_sig) else None
    h20, l20 = hi.iloc[-20:].any(), lo.iloc[-20:].any()
    flags = []
    for a, b, nm_a, nm_b in (("DIA", "IYT", "industrials", "transports"), ("IYT", "DIA", "transports", "industrials")):
        if h20[a] and not hi_r[b].iloc[-1]:
            flags.append(f"{nm_a.capitalize()} made a 52-week high that the {nm_b} haven't confirmed")
        if l20[a] and not lo_r[b].iloc[-1]:
            flags.append(f"{nm_a.capitalize()} made a 52-week low that the {nm_b} haven't confirmed")
    return {"c": c, "hi": hi, "lo": lo, "trend": trend, "now": str(trend.iloc[-1]), "since": since, "flag": "; ".join(flags)}


def ratio_trend(x: pd.Series) -> Dict[str, Any]:
    s50, s200 = x.rolling(50, min_periods=40).mean(), x.rolling(200, min_periods=150).mean()
    v, a, b = float(x.iloc[-1]), float(s50.iloc[-1]), float(s200.iloc[-1])
    if not (np.isfinite(a) and np.isfinite(b)):
        state = "n/a"
    elif v > a:
        state = "RISING" if a > b else "TURNING UP"
    else:
        state = "FALLING" if a < b else "TURNING DOWN"
    return {"state": state, "s50": s50, "s200": s200, "vs50": v / a - 1 if np.isfinite(a) else np.nan}


# ═══════════════════════════════════════════════════════════════════════════
#  OPTION CHAINS (Massive snapshot, paginated; demo chain for offline use)
# ═══════════════════════════════════════════════════════════════════════════

def _g(obj, *names, default=None):
    if obj is None:
        return default
    if isinstance(obj, dict):
        for n_ in names:
            if obj.get(n_) is not None:
                return obj[n_]
        return default
    for n_ in names:
        v = getattr(obj, n_, None)
        if v is not None:
            return v
    return default


def _fnum(v) -> Optional[float]:
    try:
        return float(v) if v is not None else None
    except (TypeError, ValueError):
        return None


def massive_chain(underlying: str, exp_gte: str, exp_lte: str, key: str, max_pages: int = 60,
                  strike_lo: Optional[float] = None, strike_hi: Optional[float] = None) -> List[dict]:
    """/v3/snapshot/options/{u}, following next_url. Raises PlanError on 401/403."""
    out: List[dict] = []
    last_err: Optional[Exception] = None
    for base in MASSIVE_BASES:
        try:
            params = {"expiration_date.gte": exp_gte, "expiration_date.lte": exp_lte,
                      "limit": 250, "order": "asc", "sort": "ticker", "apiKey": key}
            if strike_lo:
                params["strike_price.gte"] = round(strike_lo, 2)
            if strike_hi:
                params["strike_price.lte"] = round(strike_hi, 2)
            js = http_json(f"{base}/v3/snapshot/options/{underlying.upper()}", params)
            pages = 0
            while js:
                out.extend(js.get("results") or [])
                nxt = js.get("next_url")
                pages += 1
                if not nxt or pages >= max_pages:
                    break
                js = http_json(nxt + ("&" if "?" in nxt else "?") + f"apiKey={key}")
            return out
        except PlanError as e:
            last_err = e
            continue
    if last_err:
        raise last_err
    return out


def demo_chain(underlying: str, spot: float, hv: float, exp_lte_days: int, strip_quotes: bool) -> List[dict]:
    """Synthetic chain shaped like the Massive snapshot (BS prices, put skew,
    random volume / OI / last trade). strip_quotes mimics Options Starter."""
    rng = np.random.default_rng(zlib.crc32(f"{underlying}{date.today()}".encode()))
    today = date.today()
    exps, d = [], today
    while (d - today).days <= exp_lte_days:
        if d.weekday() == 4 and d >= today:
            exps.append(d)
        d += timedelta(days=1)
    step = next((x for x in (0.5, 1.0, 2.5, 5.0, 10.0, 25.0, 50.0) if x >= spot * 0.006), 100.0)
    ks = np.arange(math.floor(spot * 0.75 / step) * step, spot * 1.25 + step, step)
    base_iv = max(0.12, hv * rng.uniform(0.9, 1.35))
    etf = underlying in INDEX_SET
    h_ = zlib.crc32(underlying.encode())
    event_day = today + timedelta(days=int(5 + h_ % 40)) if (h_ % 4 == 0 and not etf) else None
    event_sd = 0.04 + (h_ % 7) / 100.0
    out = []
    for e in exps:
        T = max((e - today).days, 1) / 365.0
        for k in ks:
            m = math.log(k / spot)
            for typ in ("call", "put"):
                iv = base_iv * (1 - 0.8 * m + 2.5 * m * m)
                if event_day and e >= event_day:          # demo earnings: add event variance to later expiries
                    iv = math.sqrt(iv * iv + event_sd ** 2 / T)
                px = float(bs_call(spot, k, T, iv)) if typ == "call" else float(bs_call(spot, k, T, iv)) - spot + k
                px = max(px, 0.01)
                spr = max(0.01, min(px * rng.uniform(0.02, 0.10), spot * 0.003 * rng.uniform(0.5, 1.5)))
                bid, ask = max(0.0, round(px - spr / 2, 2)), round(px + spr / 2, 2)
                heat = math.exp(-abs(m) * 12) * (3.0 if T < 0.03 else 1.0) * (6 if etf else 1)
                vol = int(rng.poisson(150 * heat)) if rng.random() < 0.8 else 0
                oi = int(rng.poisson(120 * heat)) + int(vol * rng.uniform(0.2, 1.6))
                if abs(k / (step * 5) - round(k / (step * 5))) < 1e-9:   # demo: open interest piles up at round strikes
                    oi = int(oi * 2.2)
                if typ == "put" and k < spot:
                    oi = int(oi * 1.2)
                elif typ == "call" and k > spot:
                    oi = int(oi * 1.9)
                last = round(float(rng.choice([bid, ask, (bid + ask) / 2, ask + 0.01])), 2)
                rec = {"details": {"contract_type": typ, "expiration_date": e.isoformat(), "strike_price": float(k),
                                   "ticker": f"O:{underlying}{e:%y%m%d}{typ[0].upper()}{int(k * 1000):08d}"},
                       "greeks": {"delta": bs_delta(spot, k, T, iv, typ == "call")},
                       "implied_volatility": iv, "open_interest": oi,
                       "day": {"close": last if vol else None, "vwap": round((bid + ask) / 2, 2) if vol else None,
                               "volume": vol},
                       "underlying_asset": {"price": spot}}
                if not strip_quotes:
                    rec["last_quote"] = {"bid": bid, "ask": ask, "midpoint": round((bid + ask) / 2, 3)}
                    if vol:
                        rec["last_trade"] = {"price": last}
                out.append(rec)
    return out


def fetch_chain(underlying: str, dte_hi: int, source: str, key: Optional[str],
                spot: float, hv: float, strip_quotes: bool, band: Optional[float] = None) -> List[dict]:
    today = date.today()
    if source == "demo":
        return demo_chain(underlying, spot, hv, dte_hi, strip_quotes)
    if source != "massive" or not key:
        raise PlanError("Option chains need a Massive key (Options Starter or higher).")
    lo, hi = (spot * (1 - band), spot * (1 + band)) if (band and spot) else (None, None)
    return massive_chain(underlying, today.isoformat(), (today + timedelta(days=dte_hi)).isoformat(), key,
                         strike_lo=lo, strike_hi=hi)


def event_from_term(contracts: List[dict], spot: float, jump: float = 2.0) -> Tuple[Optional[str], Optional[float]]:
    """Find the expiry where forward variance jumps (an earnings-style event sits
    between it and the previous expiry). Returns (expiration, forward-variance multiple)."""
    pts = {}
    for c in contracts:
        if c and c["iv"] and c["strike"] and c["dte"] and spot and abs(c["strike"] - spot) / spot < 0.05:
            pts.setdefault((c["expiration"], c["dte"]), []).append((abs(c["strike"] - spot), c["iv"]))
    curve = []
    for (exp, dte), v in sorted(pts.items(), key=lambda kv: kv[0][1]):
        best = min(x[0] for x in v)
        curve.append((exp, dte / 365.0, float(np.mean([iv for d, iv in v if d == best]))))
    if len(curve) < 3:
        return None, None
    fwd = []
    for (e0, t0, v0), (e1, t1, v1) in zip(curve, curve[1:]):
        if t1 > t0:
            fwd.append((e1, max(v1 * v1 * t1 - v0 * v0 * t0, 0) / (t1 - t0)))
    base = float(np.median([f for _, f in fwd])) if fwd else 0
    hit = [(e, f / base) for e, f in fwd if base > 0 and f / base >= jump]
    if hit:
        return hit[0][0], round(hit[0][1], 2)
    return None, None


def ts_et(v) -> Optional[datetime]:
    """A Massive timestamp (nanoseconds, milliseconds or seconds since the epoch) as an Eastern time."""
    x = _fnum(v)
    if not x or x <= 0:
        return None
    x = x / 1e9 if x > 1e17 else (x / 1e6 if x > 1e14 else (x / 1e3 if x > 1e11 else x))
    try:
        dt = datetime.fromtimestamp(x, tz=timezone.utc)
    except (OverflowError, OSError, ValueError):
        return None
    return dt.astimezone(_ET) if _ET else (dt - timedelta(hours=et_offset_hours(dt))).replace(tzinfo=None)


def _pos(v) -> Optional[float]:
    x = _fnum(v)
    return x if (x is not None and x > 0) else None


def extract_contract(raw: Any, today: date) -> Optional[Dict[str, Any]]:
    """One contract from a chain snapshot. The mark is the quote midpoint, else the last trade, else the day bar's
    close, else its VWAP (Options Starter carries no quotes or trades, so it is the day bar there). mark_time is when
    that price was set (the day bar's last update on Starter): a day bar from an earlier session is the previous
    session's close, not today's 15-minute-delayed print. A zero price counts as no price."""
    det = _g(raw, "details")
    if det is None:
        return None
    lq, lt, day = _g(raw, "last_quote"), _g(raw, "last_trade"), _g(raw, "day")
    bid, ask = _fnum(_g(lq, "bid")), _fnum(_g(lq, "ask"))
    mid = _pos(_g(lq, "midpoint", "mid"))
    if mid is None and bid is not None and ask is not None and ask >= bid and ask > 0:
        mid = 0.5 * (bid + ask)
    last = _pos(_g(lt, "price"))
    dclose, dvwap = _pos(_g(day, "close", "c")), _pos(_g(day, "vwap", "vw"))
    day_t = ts_et(_g(day, "last_updated", "t"))
    if mid is not None:
        mark, src, mt = mid, "mid", ts_et(_g(lq, "last_updated", "sip_timestamp"))
    elif last is not None:
        mark, src, mt = last, "last", ts_et(_g(lt, "sip_timestamp", "last_updated", "participant_timestamp"))
    elif dclose is not None:
        mark, src, mt = dclose, "day_close", day_t
    elif dvwap is not None:
        mark, src, mt = dvwap, "day_vwap", day_t
    else:
        mark, src, mt = None, None, None
    ctype = str(_g(det, "contract_type") or "").lower() or None
    occ = str(_g(det, "ticker") or "")
    if ctype not in ("call", "put") and occ:
        tail = occ[-9:]
        ctype = "call" if ("C" in tail and "P" not in tail) else ("put" if "P" in tail else None)
    exp = _g(det, "expiration_date")
    try:
        dte = (datetime.strptime(str(exp)[:10], "%Y-%m-%d").date() - today).days if exp else None
    except ValueError:
        dte = None
    iv = _fnum(_g(raw, "implied_volatility"))
    if iv is not None and iv > 2.5:
        iv /= 100.0
    ua = _g(raw, "underlying_asset")
    return {"occ": occ, "underlying": str(_g(det, "underlying_ticker") or "").upper(), "type": ctype,
            "strike": _fnum(_g(det, "strike_price")), "expiration": str(exp)[:10] if exp else None,
            "dte": None if dte is None else max(dte, 0), "delta": _fnum(_g(_g(raw, "greeks"), "delta")),
            "iv": iv if (iv or 0) > 0 else None, "oi": _fnum(_g(raw, "open_interest")),
            "volume": _fnum(_g(day, "volume")), "bid": bid, "ask": ask, "mid": mid, "last": last,
            "mark": mark, "mark_src": src, "mark_time": mt, "mark_date": mt.date() if mt else None,
            "spot": _pos(_g(ua, "price", "value")), "spot_time": ts_et(_g(ua, "last_updated")),
            "spot_timeframe": _g(ua, "timeframe")}


def expected_session(delay_min: int = 15) -> date:
    """The session a 15-minute-delayed feed should be showing now: today from 9:30 ET plus the delay on a weekday,
    else the previous weekday (holidays aren't known here)."""
    t = now_et()
    d = t.date()
    if t.weekday() >= 5 or (t.hour * 60 + t.minute) < 9 * 60 + 30 + delay_min:
        d -= timedelta(days=1)
    while d.weekday() >= 5:
        d -= timedelta(days=1)
    return d


def chain_session(cons: List[dict]) -> Optional[date]:
    """The latest session any contract in the chain printed in: today once today's 15-minute-delayed prints arrive,
    the previous session before the open, on a holiday or for a name that hasn't traded yet today."""
    ds = [c["mark_date"] for c in cons if c and c.get("mark_date")]
    return max(ds) if ds else None


def massive_stock_spots(tickers: List[str], key: str) -> Dict[str, Dict[str, Any]]:
    """Stock prices from the snapshot, 15 minutes delayed on Stocks Starter: the latest minute bar's close when it's
    from today, else today's day-bar close, else the previous close (before the open). 100 names per request; names
    the plan doesn't cover come back with an error and are skipped."""
    out: Dict[str, Dict[str, Any]] = {}
    for i in range(0, len(tickers), 100):
        chunk = [t for t in tickers[i:i + 100] if t]
        if not chunk:
            continue
        js = None
        for base in MASSIVE_BASES:
            try:
                js = http_json(f"{base}/v2/snapshot/locale/us/markets/stocks/tickers",
                               {"tickers": ",".join(chunk), "apiKey": key})
                break
            except PlanError:
                continue
        for r_ in (js or {}).get("tickers") or []:
            if not isinstance(r_, dict) or r_.get("error") or not r_.get("ticker"):
                continue
            mn, dy, pv = r_.get("min") or {}, r_.get("day") or {}, r_.get("prevDay") or {}
            upd = ts_et(r_.get("updated"))
            mt = ts_et(mn.get("t"))
            today_ = now_et().date()
            if _pos(mn.get("c")) and mt and mt.date() == today_:
                out[r_["ticker"]] = {"price": float(mn["c"]), "time": mt, "src": "stock snapshot, latest minute"}
            elif _pos(dy.get("c")):
                out[r_["ticker"]] = {"price": float(dy["c"]), "time": upd or mt, "src": "stock snapshot, day bar"}
            elif _pos(pv.get("c")):
                out[r_["ticker"]] = {"price": float(pv["c"]), "time": None, "src": "previous close (before the open)"}
    return out


def pick_spot(cons: List[dict], live: Optional[Dict[str, Any]], bar_close: Optional[float]
              ) -> Tuple[Optional[float], str, Optional[datetime]]:
    """The freshest underlying price: the chain's own underlying, or the stock snapshot, whichever was set later;
    then the last daily bar's close, which is yesterday's during the session when the app drops today's unfinished
    bar."""
    c = next((x for x in cons if x and x.get("spot")), None)
    cands = []
    if c:
        cands.append((c.get("spot_time"), c["spot"], "chain underlying" + (f" ({str(c.get('spot_timeframe')).lower()})"
                                                                           if c.get("spot_timeframe") else "")))
    if live and live.get("price"):
        cands.append((live.get("time"), live["price"], live["src"]))
    if cands:
        dated = [x for x in cands if x[0] is not None]
        best = max(dated, key=lambda x: x[0]) if dated else cands[0]
        return float(best[1]), best[2], best[0]
    if bar_close:
        return float(bar_close), "last daily bar close", None
    return None, "none", None


def spy_term(source: str, key: Optional[str], spot: float, hv: float, strip_quotes: bool) -> Optional[Dict[str, Any]]:
    """Front (0-7 DTE) vs 21-45 DTE ATM IV for SPY, ATM = strike nearest spot."""
    try:
        raw = fetch_chain("SPY", 60, source, key, spot, hv, strip_quotes)
    except Exception:
        return None
    today = date.today()
    rows = [c for c in (extract_contract(r, today) for r in raw) if c and c["iv"] and c["strike"] and c["dte"] is not None]
    if not rows:
        return None
    s = next((c["spot"] for c in rows if c["spot"]), None) or spot

    def atm(lo, hi):
        pool = [c for c in rows if lo <= c["dte"] <= hi]
        if not pool:
            return None, None
        dte = min({c["dte"] for c in pool}, key=lambda d: (d < lo, d))
        leg = [c for c in pool if c["dte"] == dte]
        k = min({c["strike"] for c in leg}, key=lambda k: abs(k - s))
        ivs = [c["iv"] for c in leg if c["strike"] == k]
        return (float(np.mean(ivs)), dte) if ivs else (None, None)

    back, bdte = atm(21, 45)
    if back is None:
        back, bdte = atm(14, 60)
    front, fdte = atm(0, 7)
    if back is None:
        return None
    ratio = front / back if front else None
    term = ("TERM-INVERT" if ratio and ratio >= 1.08 else "TERM-CONTANGO" if ratio and ratio <= 0.92 else "TERM-FLAT")
    return {"term": term, "front_iv": front, "front_dte": fdte, "back_iv": back, "back_dte": bdte, "ratio": ratio}


# ═══════════════════════════════════════════════════════════════════════════
#  BULL CALL DEBIT SCREEN
# ═══════════════════════════════════════════════════════════════════════════

PREFERRED_DTE = [(14, 21), (8, 13), (0, 7)]
STALE_SRC = {"day_close", "day_vwap"}


def _spread_pct(c) -> Optional[float]:
    b, a, m = c.get("bid"), c.get("ask"), c.get("mark")
    if b is None or a is None or not m or a < b:
        return None
    return (a - b) / m


def _quality(spread_pct, oi, volume) -> float:
    q = 1.0
    q *= 0.7 if spread_pct is None else (0.4 if spread_pct > 0.25 else (0.7 if spread_pct > 0.12 else 1.0))
    if oi is None:
        q *= 0.85
    elif oi < 50:
        q *= 0.55
    elif oi < 200:
        q *= 0.85
    elif oi >= 1000:          # checked before 500 (the old order made this branch unreachable)
        q *= 1.12
    elif oi >= 500:
        q *= 1.08
    if volume is not None:
        q *= 1.08 if volume >= 500 else (0.85 if volume < 100 else 1.0)
    return q


def atm_iv(contracts: List[dict], spot: float) -> Tuple[Optional[float], Optional[int]]:
    """Mean of call and put IV at the strike nearest spot, same expiry, preferring 8-21 DTE."""
    pool = [c for c in contracts if c["iv"] and c["strike"] and c["dte"] is not None
            and abs(c["strike"] - spot) / spot <= 0.06]
    for lo, hi in ((8, 21), (0, 60)):
        band = [c for c in pool if lo <= c["dte"] <= hi]
        if not band:
            continue
        dte = min({c["dte"] for c in band}, key=lambda d: abs(d - 14))
        leg = [c for c in band if c["dte"] == dte]
        k = min({c["strike"] for c in leg}, key=lambda k: abs(k - spot))
        ivs = [c["iv"] for c in leg if c["strike"] == k]
        return float(np.mean(ivs)), dte
    return None, None


def _when(t: Optional[datetime]) -> str:
    return t.strftime("%b %d %H:%M ET") if t else ""


def list_debits(contracts: List[dict], spot: float, hv: float, min_oi: float, min_vol: float,
                min_rr: float, dte_lo: int, dte_hi: int, ref_date: Optional[date] = None,
                fresh_only: bool = False) -> List[Dict[str, Any]]:
    """Every nearby bull call debit that clears the filters. With ref_date (the latest session any chain printed in)
    and fresh_only, legs whose last print is from an earlier session are left out: their price is that session's
    close, not today's."""
    def old(c):
        return bool(ref_date and c.get("mark_date") and c["mark_date"] < ref_date)

    calls = [c for c in contracts if c["type"] == "call" and c["strike"] and c["mark"] is not None
             and c["dte"] is not None and dte_lo <= c["dte"] <= dte_hi and not (fresh_only and old(c))]
    bands = [b for b in PREFERRED_DTE if b[1] >= dte_lo and b[0] <= dte_hi] or [(dte_lo, dte_hi)]
    found: Dict[Tuple, Dict[str, Any]] = {}
    for lo, hi in bands:
        by_exp: Dict[str, List[dict]] = {}
        for c in calls:
            if lo <= c["dte"] <= hi:
                by_exp.setdefault(c["expiration"], []).append(c)
        for exp, legs in by_exp.items():
            legs.sort(key=lambda c: c["strike"])
            longs = [c for c in legs if (spot * 0.92 <= c["strike"] <= spot * 1.08)
                     or (c["delta"] is not None and 0.35 <= abs(c["delta"]) <= 0.70)]
            if not longs:
                longs = [c for c in legs if abs(c["strike"] - spot) / spot <= 0.12]
            for L in longs:
                for S in (c for c in legs if c["strike"] > L["strike"]):
                    oi_f = min(L["oi"] or 0.0, S["oi"] or 0.0)
                    vol_f = min(L["volume"] or 0.0, S["volume"] or 0.0)
                    if oi_f < min_oi or (min_vol > 0 and vol_f < min_vol):
                        continue
                    debit = L["mark"] - S["mark"]
                    width = S["strike"] - L["strike"]
                    if debit <= 0 or width < 1.0 or width > max(spot * 0.08, 2.5):
                        continue
                    ratio = debit / width
                    if not (0.12 <= ratio <= 0.80):
                        continue
                    rr = (width - debit) / debit
                    if rr < min_rr:
                        continue
                    atm_pen = abs(L["strike"] - spot) / spot
                    q = _quality(max(_spread_pct(L) or 0, _spread_pct(S) or 0), oi_f, vol_f)
                    T = max(L["dte"], 1) / 365.0
                    be = L["strike"] + debit
                    fair = (float(bs_call(spot, L["strike"], T, hv) - bs_call(spot, S["strike"], T, hv))
                            if hv else float("nan"))
                    p_be = float(1 - _ncdf((math.log(be / spot)) / (hv * math.sqrt(T)))) if hv else float("nan")
                    cand = {
                        "expiration": exp, "dte": L["dte"], "long_strike": L["strike"], "short_strike": S["strike"],
                        "debit": round(debit, 3), "width": round(width, 3), "debit_width": round(ratio, 3),
                        "reward_risk": round(rr, 2), "max_profit_pct": round(rr * 100, 1),
                        "pct_to_short": round((S["strike"] - spot) / spot * 100, 2),
                        "breakeven_pct": round((be / spot - 1) * 100, 2),
                        "value_at_hv": round(fair, 3), "value_minus_debit": round(fair - debit, 3),
                        "p_above_be_hv": round(p_be, 3),
                        "oi": oi_f, "volume": vol_f, "iv_long": L["iv"], "iv_short": S["iv"],
                        "pricing": f"{L['mark_src']}/{S['mark_src']}",
                        "stale": L["mark_src"] in STALE_SRC or S["mark_src"] in STALE_SRC,
                        "prior_session": old(L) or old(S),
                        "printed": " / ".join(_when(x.get("mark_time")) for x in (L, S)) if (L.get("mark_time") or S.get("mark_time")) else "",
                        "score": round(q * rr * (1 - min(atm_pen, 0.08) / 0.08 * 0.25), 4),
                    }
                    key = (exp, L["strike"], S["strike"])
                    if key not in found or cand["score"] > found[key]["score"]:
                        found[key] = cand
    return sorted(found.values(), key=lambda c: (c["max_profit_pct"], c["score"]), reverse=True)


def screen_debits(names: List[Tuple[str, float]], spots: Dict[str, float], hvs: Dict[str, float],
                  source: str, key: Optional[str], strip_quotes: bool, dte_lo: int, dte_hi: int,
                  min_oi: float, min_vol: float, min_rr: float, progress=None, fresh_only: bool = True,
                  live_spots: Optional[Dict[str, Dict[str, Any]]] = None) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """Pull every chain, then list the debits. Spot is the freshest of the chain's underlying price and the stock
    snapshot (both 15 minutes delayed on Starter plans), never the daily bars unless neither has one, because with
    today's unfinished bar dropped the last bar is yesterday's. Legs whose last print is from an earlier session
    than the latest one any chain printed in are left out when fresh_only is on."""
    today = date.today()
    if live_spots is None:
        live_spots = {}
        if source == "massive" and key:
            try:
                live_spots = massive_stock_spots([t for t, _ in names], key)
            except Exception:
                live_spots = {}

    def fetch(tk_sc):
        tk, sc = tk_sc
        try:
            raw = fetch_chain(tk, dte_hi, source, key, spots.get(tk) or 100.0, hvs.get(tk) or 0.3, strip_quotes)
        except Exception as e:
            return tk, sc, None, f"{type(e).__name__}: {e}"
        return tk, sc, [c for c in (extract_contract(r, today) for r in raw) if c], None

    got = []
    with ThreadPoolExecutor(max_workers=1 if source == "demo" else 4) as ex:
        futs = [ex.submit(fetch, x) for x in names]
        for i, f in enumerate(as_completed(futs), 1):
            got.append(f.result())
            if progress is not None:
                progress.progress(i / max(1, len(names)), text=f"Chains {i}/{len(names)}")
    sessions = [d for d in (chain_session(c) for _, _, c, _ in got if c) if d]
    ref = max(sessions) if sessions else None

    rows, verts = [], []
    for tk, sc, cons, err in got:
        row = {"ticker": tk, "score": sc, "spot": spots.get(tk), "hv20": hvs.get(tk), "atm_iv": None,
               "vrp": None, "n_contracts": 0, "n_verticals": 0, "pick": "", "error": err}
        if err is not None:
            rows.append(row)
            continue
        spot, s_src, s_t = pick_spot(cons, live_spots.get(tk), spots.get(tk))
        row["spot"], row["n_contracts"] = spot, len(cons)
        row["spot_src"], row["spot_time"] = s_src, _when(s_t)
        priced = [c for c in cons if c["mark"] is not None]
        if ref and priced:
            row["prints_this_session"] = sum(1 for c in priced if c.get("mark_date") == ref) / len(priced)
        if not cons or not spot:
            row["error"] = "empty chain" if not cons else "no spot"
            rows.append(row)
            continue
        iv, iv_dte = atm_iv(cons, spot)
        hv = hvs.get(tk)
        ev_exp, ev_mult = event_from_term(cons, spot)
        row["event_expiry"], row["event_fwdvar_x"] = ev_exp, ev_mult
        row["atm_iv"] = iv
        row["atm_iv_dte"] = iv_dte
        row["vrp"] = (iv - hv) if (iv is not None and hv) else None
        row["marked_by_quote"] = sum(1 for c in cons if c["mark_src"] == "mid")
        vs = list_debits(cons, spot, hv or 0.0, min_oi, min_vol, min_rr, dte_lo, dte_hi, ref, fresh_only)
        for v in vs:
            v.update({"ticker": tk, "score": sc, "spot": spot, "atm_iv": iv, "hv20": hv, "vrp": row["vrp"],
                      "event_inside": bool(ev_exp and v["expiration"] >= ev_exp)})
        row["n_verticals"] = len(vs)
        if vs:
            p = vs[0]
            row["pick"] = (f"{p['long_strike']:g}/{p['short_strike']:g}C {p['expiration']} ({p['dte']}d) "
                           f"debit {p['debit']:.2f} on {p['width']:g}, max profit {p['max_profit_pct']:.0f}%")
        rows.append(row)
        verts.extend(vs)
    order = {t: i for i, (t, _) in enumerate(names)}
    rows.sort(key=lambda r_: order.get(r_["ticker"], 999))
    R = pd.DataFrame(rows)
    R.attrs["session"] = ref.isoformat() if ref else None
    return R, pd.DataFrame(verts)


# ═══════════════════════════════════════════════════════════════════════════
#  FLOW TAPE  (Flowseidon taxonomy; unsigned-safe)
# ═══════════════════════════════════════════════════════════════════════════

URGENT_OTM = (0.02, 0.06)
URGENT_DTE = 7
URGENT_PREMIUM = 1_000_000
OI_STATE = HERE / "data" / "flowseidon_oi_state.json"
PROTOTYPE = {
    "NVDA": "SMH", "AVGO": "SMH", "TSM": "SMH", "AMD": "SMH", "AMAT": "SMH", "LRCX": "SMH", "KLAC": "SMH",
    "ASML": "SMH", "MU": "SMH", "QCOM": "SMH", "AAPL": "XLK", "MSFT": "XLK", "GOOGL": "QQQ", "GOOG": "QQQ",
    "META": "QQQ", "AMZN": "QQQ", "NFLX": "QQQ", "TSLA": "QQQ", "XOM": "XLE", "CVX": "XLE", "COP": "XLE",
    "SLB": "XLE", "JPM": "XLF", "BAC": "XLF", "GS": "XLF", "WFC": "XLF", "MS": "XLF",
}
FLOW_LEGEND = [
    ("BULLISH_ASK", "Call printed at or through the ask.", "Someone paid for upside now. Could be a debit's long leg or a dealer, not 'buy the stock'."),
    ("BEARISH_ASK", "Put printed at or through the ask.", "Protection or a short was paid for. On the index this is hedge demand."),
    ("PUT_SELL_STO", "Put printed at or through the bid.", "Premium being sold; the best bullish index tell when it lives in 8-45 DTE."),
    ("CALL_SELL_STO", "Call printed at or through the bid.", "Upside rented out: mildly defensive or income."),
    ("MULTI_LEG", "Same expiry has both a call and a put above the floor.", "The loud wing is probably half of a spread; don't read it as naked conviction."),
    ("URGENT", "2-6% OTM, <= 7 DTE, >= $1M on an index ETF.", "Event or dealer urgency. Look, don't copy."),
    ("UNK / UNSIGNED", "No quote or trade to compare with (Options Starter).", "Premium is unsigned. It can size heat, never direction."),
    ("O/S", "Flagged premium / stock dollar volume.", "Loud options vs the equity tape (Johnson-So use contract/share volume)."),
    ("OI vs saved", "Snapshot OI minus the OI saved on the previous run.", "OI is end-of-prior-session, so this grades the PREVIOUS run's prints."),
]


def side_guess(c) -> str:
    last, bid, ask, mid = c.get("last"), c.get("bid"), c.get("ask"), c.get("mid")
    if last is None:
        return "UNK"
    if bid is not None and ask is not None and ask >= bid:
        pad = max((ask - bid) * 0.15, 0.01)
        return "ASK" if last >= ask - pad else ("BID" if last <= bid + pad else "MID")
    if mid is not None:
        return "ASK" if last >= mid else "BID"
    return "UNK"


def _intent(ctype, side) -> str:
    return {("call", "ASK"): "CALL_BUY", ("call", "BID"): "CALL_SELL",
            ("put", "ASK"): "PUT_BUY", ("put", "BID"): "PUT_SELL"}.get((ctype, side), "UNK")


def _otm(c, spot):
    k = c.get("strike")
    if not spot or not k:
        return None
    return (k - spot) / spot if c.get("type") == "call" else ((spot - k) / spot if c.get("type") == "put" else None)


def score_contract(c, spot, cfg, oi_state) -> Optional[Dict[str, Any]]:
    vol, oi, mark, dte, tk = c.get("volume") or 0.0, c.get("oi") or 0.0, c.get("mark"), c.get("dte"), c.get("underlying") or ""
    if mark is None or mark <= 0 or vol < cfg["min_volume"]:
        return None
    if dte is None or dte < cfg["dte_lo"] or dte > cfg["dte_hi"]:
        return None
    if oi < cfg["min_oi"] and vol < cfg["min_volume"] * 3:
        return None
    prem = vol * mark * 100.0
    floor = (cfg["min_premium_index"] if tk in INDEX_CORE or tk in VOL_TAPE else
             cfg["min_premium_sector"] if tk in SECTOR_CORE or tk in METAL_TAPE else cfg["min_premium"])
    if prem < floor:
        return None
    voi = vol / max(oi, 1.0)
    if voi < (cfg["min_vol_oi_index"] if tk in INDEX_CORE or tk in VOL_TAPE else cfg["min_vol_oi"]):
        return None
    otm = _otm(c, spot)
    dw = 0.6 if dte is None else (0.35 if dte <= 7 else (1.0 if dte <= 45 else 0.55))
    ow = 0.8 if otm is None else (0.40 if otm > 0.12 else (0.75 if otm > 0.05 else 1.0))
    side = side_guess(c)
    prev = oi_state.get(c.get("occ") or "")
    chg = None if prev is None or c.get("oi") is None else c["oi"] - prev
    return {**c, "spot": spot or c.get("spot"), "premium_usd": round(prem), "vol_oi": round(voi, 3),
            "otm_pct": None if otm is None else round(otm * 100, 2), "side": side,
            "intent": _intent(c.get("type"), side), "unusual_score": round(math.log1p(prem) * min(voi, 8.0) * dw * ow, 4),
            "oi_vs_saved": chg, "oi_up_vs_saved": None if chg is None else bool(chg > 0)}


def _bucket(c, multi) -> str:
    tag = {"CALL_BUY": "BULLISH_ASK", "PUT_BUY": "BEARISH_ASK", "PUT_SELL": "PUT_SELL_STO",
           "CALL_SELL": "CALL_SELL_STO"}.get(c.get("intent"), "UNK")
    if multi:
        tag += "/MULTI_LEG"
    if c.get("underlying") in INDEX_SET:
        tag = "ETF_FLOW/" + tag
        otm = (c.get("otm_pct") or -99) / 100
        if (c.get("premium_usd") or 0) >= URGENT_PREMIUM and (c.get("dte") or 99) <= URGENT_DTE \
                and URGENT_OTM[0] <= otm <= URGENT_OTM[1]:
            tag += "/URGENT"
    return tag


def rollup(tk: str, rows: List[dict], spot, dollar_vol, is_index: bool) -> Dict[str, Any]:
    def prem(pred):
        return float(sum(r.get("premium_usd") or 0 for r in rows if pred(r)))
    bull = prem(lambda r: "BULLISH_ASK" in r["bucket"])
    bear = prem(lambda r: "BEARISH_ASK" in r["bucket"])
    ps = prem(lambda r: "PUT_SELL_STO" in r["bucket"])
    cs = prem(lambda r: "CALL_SELL_STO" in r["bucket"])
    call_u, put_u = prem(lambda r: r.get("type") == "call"), prem(lambda r: r.get("type") == "put")
    side_known = (bull + bear + ps + cs) > 0
    if not side_known and (call_u + put_u) > 0:
        bull, bear, ps, cs = call_u, put_u, 0.0, 0.0      # display only; never votes
    p07 = prem(lambda r: (r.get("dte") if r.get("dte") is not None else 99) <= 7)
    p845 = prem(lambda r: 8 <= (r.get("dte") or 0) <= 45)
    total = bull + bear + ps + cs
    if total <= 0:
        bias = "NONE"
    elif not side_known:
        bias = "UNSIGNED"
    elif (bull + ps) >= total * 0.60 and (bull + ps) > (bear + cs):
        bias = "BULLISH_TAPE"
    elif (bear + cs) >= total * 0.60 and (bear + cs) > (bull + ps):
        bias = "BEARISH_TAPE"
    elif ps >= total * 0.40 and ps > bear:
        bias = "OVERWRITE_TAPE"
    else:
        bias = "MIXED"
    top = max(rows, key=lambda r: r.get("premium_usd") or 0) if rows else {}
    return {"ticker": tk, "universe": "INDEX" if is_index else "NAME", "spot": spot,
            "prototype_etf": None if is_index else PROTOTYPE.get(tk), "n_flagged": len(rows),
            "bullish_ask": bull, "bearish_ask": bear, "put_sell_sto": ps, "call_sell_sto": cs,
            "side_available": side_known, "multi_leg_prem": prem(lambda r: "MULTI_LEG" in r["bucket"]),
            "prem_0_7": p07, "prem_8_45": p845, "share_8_45": (p845 / (p07 + p845)) if (p07 + p845) else None,
            "urgent_n": sum(1 for r in rows if "URGENT" in r["bucket"]),
            "os_ratio": (total / dollar_vol) if (dollar_vol and total) else None,
            "bias": bias, "top_contract": top.get("occ"), "top_bucket": top.get("bucket"),
            "top_premium": top.get("premium_usd"), "top_dte": top.get("dte")}


def flow_regime(tape: List[Dict[str, Any]]) -> Tuple[str, str]:
    by = {r["ticker"]: r for r in tape}
    signed = {t for t, r in by.items() if r.get("side_available")}

    def g(t, k):
        return float(by[t].get(k) or 0) if t in signed else 0.0

    put_buy = sum(g(t, "bearish_ask") for t in EQUITY_TAPE)
    put_sell = sum(g(t, "put_sell_sto") for t in EQUITY_TAPE)
    call_buy = sum(g(t, "bullish_ask") for t in EQUITY_TAPE)
    call_sell = sum(g(t, "call_sell_sto") for t in EQUITY_TAPE)
    short_dte = sum(float(r.get("prem_0_7") or 0) for r in tape)
    mid_dte = sum(float(r.get("prem_8_45") or 0) for r in tape)
    total = put_buy + put_sell + call_buy + call_sell
    vol_bid = sum(g(t, "bullish_ask") for t in VOL_TAPE)
    signed_eq = bool(signed & set(EQUITY_TAPE))
    if not tape:
        return "MIXED", "No index rows cleared the floors."
    if short_dte > 0 and short_dte / (short_dte + mid_dte + 1) >= 0.70 and mid_dte < short_dte:
        return "PIN_NOISE", f"{short_dte / max(short_dte + mid_dte, 1):.0%} of flagged index premium is 0-7 DTE. Pin or lottery; not direction."
    if not signed_eq:
        return "MIXED", ("Trade side is unavailable on the equity index tape (no quotes or trades in this snapshot), "
                         "so premium is unsigned and cannot tag a regime. Sleeves stay on ranks.")
    if total <= 0:
        return "MIXED", "Index premium below the floors."
    if vol_bid >= 150_000:
        return "VOL_BID", f"VIXY/UVXY call buying ${vol_bid:,.0f}. Sit on short premium."
    iwm, spy = g("IWM", "bearish_ask"), g("SPY", "bearish_ask")
    if "IWM" in signed and "SPY" in signed and iwm > 0 and iwm >= spy * 1.15 and iwm >= 150_000:
        return "SMALLCAP_STRESS", f"IWM put buying ${iwm:,.0f} vs SPY ${spy:,.0f}. Cut the debit sleeve first."
    if put_buy >= total * 0.45 and put_buy > put_sell:
        return "HEDGE_BID", f"Index put buying ${put_buy:,.0f} dominates. Protection is being paid for."
    if put_sell >= total * 0.40 and put_sell > put_buy and mid_dte >= short_dte:
        return "OVERWRITE", f"Index put selling ${put_sell:,.0f} dominates with 8-45 DTE present. Credit permission."
    tech = g("SMH", "bullish_ask") + g("XLK", "bullish_ask") + g("QQQ", "bullish_ask")
    if tech > g("SMH", "bearish_ask") * 1.5 and tech >= 150_000 and "IWM" in signed and iwm < 150_000:
        return "TECH_LEAD", f"SMH/XLK/QQQ call buying ${tech:,.0f} with quiet IWM puts."
    return "MIXED", "No tag can be defended in one sentence."


PAIRS = [("IWM", "SPY"), ("QQQ", "SPY"), ("SMH", "QQQ"), ("XLK", "XLF"), ("XLE", "XLF"), ("DIA", "SPY"), ("VIXY", "SPY")]


def flow_cross(tape: List[Dict[str, Any]]) -> pd.DataFrame:
    by = {r["ticker"]: r for r in tape}
    signed = {t for t, r in by.items() if r.get("side_available")}
    out = []
    for a, b in PAIRS:
        if a not in signed or b not in signed:
            out.append({"pair": f"{a} / {b}", "lead": "NONE", "read": "Unsigned on one or both legs: no divergence read."})
            continue
        g = lambda t, k: float(by[t].get(k) or 0)
        lead, read = "NONE", "No divergence worth a sentence."
        if g(a, "bearish_ask") >= 150_000 and g(a, "bearish_ask") >= max(g(b, "bearish_ask"), 1) * 1.15:
            lead, read = f"{a} put buying", f"{a} put buying leads {b}. Veto the sleeve that inherits {a}."
        elif g(b, "bearish_ask") >= 150_000 and g(b, "bearish_ask") >= max(g(a, "bearish_ask"), 1) * 1.15:
            lead, read = f"{b} put buying", f"{b} put buying leads {a}: a {b}-side hedge, not a global short."
        elif g(a, "bullish_ask") >= 150_000 and g(a, "bullish_ask") >= max(g(b, "bullish_ask"), 1) * 1.15:
            lead, read = f"{a} call buying", f"{a} call buying leads {b}. Color only unless {a} is a prototype."
        elif g(a, "put_sell_sto") >= 150_000 and g(a, "put_sell_sto") >= max(g(b, "put_sell_sto"), 1) * 1.15:
            lead, read = f"{a} put selling", f"{a} put selling leads {b}: overwrite color on the {a} side."
        out.append({"pair": f"{a} / {b}", "lead": lead, "read": read})
    return pd.DataFrame(out)


def name_family(row, regime, proto) -> Tuple[str, str]:
    if row.get("refuse"):
        return "HARD_SKIP", "Refuse list. Flow cannot override."
    top_b, dte = row.get("top_bucket") or "", row.get("top_dte")
    if dte is not None and dte <= 7 and "URGENT" not in top_b and (row.get("prem_0_7") or 0) > (row.get("prem_8_45") or 0):
        return "IGNORE_0_7_LOTTERY", "Short-dated flow is not a 22-45 structure."
    if not row.get("side_available"):
        return "WATCH_UNSIGNED", "Trade side unavailable: flow can neither confirm nor veto."
    wings = sum(row.get(k) or 0 for k in ("bullish_ask", "bearish_ask", "put_sell_sto", "call_sell_sto"))
    multi = row.get("multi_leg_prem") or 0
    if multi > 0 and wings > 0 and multi >= 0.5 * wings and \
            abs((row.get("bullish_ask") or 0) - (row.get("bearish_ask") or 0)) < 0.25 * max(wings, 1):
        return "IC_OR_SIT", "Both wings printed at similar size in one expiry. Don't invent a direction."
    conflict = bool(proto and proto.get("side_available") and (proto.get("bearish_ask") or 0) >= 150_000
                    and (proto.get("bearish_ask") or 0) > (proto.get("bullish_ask") or 0))
    bias = row.get("bias")
    if regime in ("SMALLCAP_STRESS", "VOL_BID", "HEDGE_BID") and bias == "BULLISH_TAPE":
        return "SIT", f"Name tape is bullish but the index regime is {regime}."
    if conflict and bias == "BULLISH_TAPE":
        return "SIT_INHERIT", f"Prototype {proto['ticker']} is put-bid; inheritance vetoes the debit."
    if regime == "PIN_NOISE":
        return "WATCH", "Index tape is pin. Flow does not promote."
    if bias == "BULLISH_TAPE" and "BULLISH_ASK" in top_b:
        return "CONFIRM_BULL_CALL_DEBIT", "Call buying agrees with a bullish name tape. Still needs rank + IV + refuse check."
    if bias == "OVERWRITE_TAPE" or (bias == "BULLISH_TAPE" and "PUT_SELL_STO" in top_b):
        if regime in ("OVERWRITE", "MIXED", "TECH_LEAD"):
            return "CONFIRM_BULL_PUT_CREDIT", "Put selling in 8-45 is the bullish tell."
        return "SIT", f"Put selling on the name but the regime is {regime}."
    if bias == "BEARISH_TAPE" and "BEARISH_ASK" in top_b:
        return "SIT_OR_FLATTEN", "Put buying on the name. Sit on debits and short puts."
    if bias == "MIXED":
        return "IC_OR_SIT", "Both stories present."
    return "WATCH", "Heat without a clean story."


SLEEVES = {
    "OVERWRITE": [("Credit sleeve", "ON", "Permission if the name's neutral read holds"), ("Debit sleeve", "STUB", "A-setups only"),
                  ("0DTE sleeve", "OFF", "Unfed"), ("Dry powder", "HOLD", "Keep the 40-50% band")],
    "HEDGE_BID": [("Credit sleeve", "OFF", "No new short puts"), ("Debit sleeve", "STUB", "A only if the prototype agrees"),
                  ("0DTE sleeve", "OFF", "Unfed"), ("Dry powder", "HOLD", "Do not press size")],
    "TECH_LEAD": [("Credit sleeve", "STUB", "Overwrite only if the prototype is quiet"), ("Debit sleeve", "A-OK", "Already-A tech may keep size"),
                  ("0DTE sleeve", "OFF", "Unfed"), ("Dry powder", "HOLD", "Keep the 40-50% band")],
    "SMALLCAP_STRESS": [("Credit sleeve", "STUB", "Defined risk only"), ("Debit sleeve", "CUT", "One divergence vetoes the sleeve"),
                        ("0DTE sleeve", "OFF", "Unfed"), ("Dry powder", "HOLD", "Two divergences cut size globally")],
    "VOL_BID": [("Credit sleeve", "OFF", "Sit on short premium"), ("Debit sleeve", "STUB", "Don't size up into a variance bid"),
                ("0DTE sleeve", "OFF", "Unfed"), ("Dry powder", "HOLD", "Keep the 40-50% band")],
    "PIN_NOISE": [("Credit sleeve", "WATCH", "Tape may not change temperature"), ("Debit sleeve", "WATCH", "Names follow rank"),
                  ("0DTE sleeve", "OFF", "Don't narrate the weekly pin"), ("Dry powder", "HOLD", "Keep the 40-50% band")],
    "MIXED": [("Credit sleeve", "RANKS", "Follow IV rank, not the tape"), ("Debit sleeve", "RANKS", "Follow the composite"),
              ("0DTE sleeve", "OFF", "Unfed"), ("Dry powder", "HOLD", "Keep the 40-50% band")],
}


def load_oi_state() -> Dict[str, float]:
    try:
        raw = json.loads(OI_STATE.read_text())
        return {k: float(v) for k, v in (raw.get("oi") or {}).items() if v is not None}
    except Exception:
        return {}


def run_flow(index_syms: List[str], name_syms: List[str], refuse: set, spots: Dict[str, float],
             hvs: Dict[str, float], dollar_vol: Dict[str, float], source: str, key: Optional[str],
             strip_quotes: bool, cfg: Dict[str, Any], progress=None) -> Dict[str, Any]:
    today = date.today()
    oi_state = load_oi_state()
    all_oi: Dict[str, float] = {}
    lock = threading.Lock()

    def scan(sym):
        raw = fetch_chain(sym, cfg["dte_hi"], source, key, spots.get(sym) or 100.0, hvs.get(sym) or 0.25, strip_quotes)
        cons = [c for c in (extract_contract(r, today) for r in raw) if c]
        for c in cons:
            if not c["underlying"]:
                c["underlying"] = sym
        with lock:
            all_oi.update({c["occ"]: c["oi"] for c in cons if c["occ"] and c["oi"] is not None})
        spot = next((c["spot"] for c in cons if c["spot"]), None) or spots.get(sym)
        scored = [s for s in (score_contract(c, spot, cfg, oi_state) for c in cons) if s]
        both = {}
        for s in scored:
            k = (s["underlying"], s["expiration"])
            both.setdefault(k, set()).add(s["type"])
        for s in scored:
            s["multi_leg"] = both.get((s["underlying"], s["expiration"]), set()) >= {"call", "put"}
            s["bucket"] = _bucket(s, s["multi_leg"])
        scored.sort(key=lambda s: s["unusual_score"], reverse=True)
        roll = rollup(sym, scored, spot, dollar_vol.get(sym), sym in INDEX_SET)
        roll["refuse"] = sym in refuse
        return scored[:cfg["top_n"]], roll

    tape, names, contracts, errors = [], [], [], []
    syms = [(s, True) for s in index_syms] + [(s, False) for s in name_syms]
    with ThreadPoolExecutor(max_workers=1 if source == "demo" else 4) as ex:
        futs = {ex.submit(scan, s): (s, is_idx) for s, is_idx in syms}
        for i, f in enumerate(as_completed(futs), 1):
            s, is_idx = futs[f]
            try:
                keep, roll = f.result()
                contracts.extend(keep)
                (tape if is_idx else names).append(roll)
            except Exception as e:
                errors.append(f"{s}: {type(e).__name__}: {e}")
            if progress is not None:
                progress.progress(i / len(syms), text=f"Tape {i}/{len(syms)}")
    regime, sentence = flow_regime(tape)
    tape_by = {r["ticker"]: r for r in tape}
    for r in names:
        r["family"], r["family_why"] = name_family(r, regime, tape_by.get(r.get("prototype_etf")))
    if all_oi:
        try:
            atomic_write_json(OI_STATE, {"as_of": today.isoformat(), "oi": all_oi})
        except Exception as e:
            errors.append(f"OI state not saved: {e}")
    return {"regime": regime, "sentence": sentence, "tape": pd.DataFrame(tape), "names": pd.DataFrame(names),
            "contracts": pd.DataFrame(contracts).sort_values("unusual_score", ascending=False) if contracts else pd.DataFrame(),
            "cross": flow_cross(tape), "errors": errors, "side_available": any(r.get("side_available") for r in tape + names),
            "as_of": datetime.now().isoformat(timespec="seconds"), "oi_state_rows": len(oi_state)}


# ═══════════════════════════════════════════════════════════════════════════
#  KELLY SIZING
#  Scenarios: filtered-historical-simulation style paths (each historical h-day
#  path is rescaled from the vol at its start to today's vol), drift removed,
#  then the signal drift (from calibration) added back. Kelly maximizes
#  E[log(1 + f R)] over those scenarios. Estimation risk is handled with a block
#  Bayesian bootstrap (plus draws of the signal drift) and Baker-McHale-style
#  shrinkage k = f^2 / (f^2 + Var f). Optional Busseti-Ryu-Boyd drawdown cap:
#  E[(1 + f R)^-lambda] <= 1 with lambda = log(beta) / log(alpha).
# ═══════════════════════════════════════════════════════════════════════════

F_GRID = np.unique(np.concatenate([np.linspace(0.0, 0.05, 51), np.linspace(0.05, 0.995, 190)]))


def kelly_binary(p: float, b: float) -> float:
    """Classic Kelly: win b per 1 staked with probability p, else lose the stake."""
    if b <= 0:
        return 0.0
    return max(0.0, p - (1 - p) / b)


def kelly_two_outcome(p: float, gain: float, loss: float) -> float:
    """Position size (fraction of bankroll) for +gain with prob p, -loss otherwise.
    Capital at risk is f * loss."""
    if gain <= 0 or loss <= 0:
        return 0.0
    return max(0.0, p / loss - (1 - p) / gain)


def binary_shrink(p: float, b_or_gain: float, n: float, loss: Optional[float] = None) -> Tuple[float, float, float]:
    """Raw Kelly, Baker-McHale shrink factor and shrunk Kelly when p is estimated
    from n trials (Beta posterior variance)."""
    n = max(float(n), 1.0)
    var_p = p * (1 - p) / (n + 1)
    if loss is None:
        f = kelly_binary(p, b_or_gain)
        df_dp = 1 + 1 / b_or_gain
    else:
        f = kelly_two_outcome(p, b_or_gain, loss)
        df_dp = 1 / loss + 1 / b_or_gain
    var_f = var_p * df_dp ** 2
    k = f * f / (f * f + var_f) if f > 0 else 0.0
    return f, k, f * k


def growth_curve(R: np.ndarray, grid: np.ndarray = F_GRID) -> np.ndarray:
    R = R[np.isfinite(R)]
    with np.errstate(divide="ignore", invalid="ignore"):
        g = np.log1p(np.outer(R, grid)).mean(axis=0)
    return np.where(np.isfinite(g), g, -np.inf)


def kelly_from_returns(R: np.ndarray, f_cap: float = 0.995) -> Tuple[float, float]:
    """argmax_f E[log(1 + f R)] on [0, f_cap]: grid then golden-section refine."""
    R = R[np.isfinite(R)]
    if len(R) < 20 or R.mean() <= 0:
        return 0.0, 0.0
    grid = F_GRID[F_GRID <= f_cap]
    g = growth_curve(R, grid)
    i = int(np.argmax(g))
    lo, hi = grid[max(i - 1, 0)], grid[min(i + 1, len(grid) - 1)]
    fn = lambda f: float(np.mean(np.log1p(f * R))) if np.all(1 + f * R > 0) else -np.inf
    a, b = lo, hi
    gr = (math.sqrt(5) - 1) / 2
    c, d = b - gr * (b - a), a + gr * (b - a)
    for _ in range(40):
        if fn(c) > fn(d):
            b = d
        else:
            a = c
        c, d = b - gr * (b - a), a + gr * (b - a)
    f = 0.5 * (a + b)
    return float(f), fn(f)


def drawdown_cap(R: np.ndarray, alpha: float, beta: float, f_cap: float = 0.995) -> float:
    """Largest f with E[(1+fR)^-lambda] <= 1 (Busseti, Ryu & Boyd 2016): keeps the
    probability of wealth ever falling to alpha below beta for repeated bets."""
    R = R[np.isfinite(R)]
    if len(R) < 20 or R.mean() <= 0 or not (0 < alpha < 1) or not (0 < beta < 1):
        return f_cap
    lam = math.log(beta) / math.log(alpha)
    h = lambda f: float(np.mean((1 + f * R) ** (-lam))) if np.all(1 + f * R > 0) else np.inf
    if h(f_cap) <= 1:
        return f_cap
    lo, hi = 0.0, f_cap
    for _ in range(50):
        mid = 0.5 * (lo + hi)
        if h(mid) <= 1:
            lo = mid
        else:
            hi = mid
    return lo


def path_scenarios(ohlc: pd.DataFrame, h: int, vol_now: float, mu_h: float = 0.0,
                   drift: str = "zero", frame: Optional[pd.DataFrame] = None,
                   condition: str = "ALL", min_n: int = 60) -> Optional[Dict[str, Any]]:
    """All overlapping h-session paths in the name's history, each rescaled by
    (today's daily vol / daily vol at its start). Arrays are log moves vs the
    start close, shape (n, h). drift='zero' removes the sample drift; 'historical'
    keeps it. mu_h (log return over h) is then added linearly."""
    df = ohlc.dropna(subset=["close"])
    c = df["close"].to_numpy(float)
    n = len(c)
    if n < 80 or h < 1 or vol_now <= 0:
        return None
    hi = df["high"].fillna(df["close"]).to_numpy(float)
    lo = df["low"].fillna(df["close"]).to_numpy(float)
    op = df["open"].fillna(df["close"]).to_numpy(float)
    lc = np.log(c)
    sig = pd.Series(np.r_[np.nan, np.diff(lc)]).rolling(20).std().to_numpy()
    starts = np.arange(21, n - h)
    ok = np.isfinite(sig[starts]) & (sig[starts] > 0)
    if condition == "MATCH" and frame is not None and "cluster" in frame:
        st_ = frame["cluster"].reindex(df.index).to_numpy()
        ok &= (st_[starts] == st_[-1])
    starts = starts[ok]
    if len(starts) < min_n:
        return None
    k = np.arange(1, h + 1)
    rows = starts[:, None] + k[None, :]
    base = lc[starts][:, None]
    scale = ((vol_now / math.sqrt(252)) / sig[starts])[:, None]
    C = (lc[rows] - base) * scale
    H = (np.log(hi[rows]) - base) * scale
    L = (np.log(lo[rows]) - base) * scale
    O = (np.log(op[rows]) - base) * scale
    adj = (mu_h / h) * k[None, :]
    if drift != "historical":
        adj = adj - (C[:, -1].mean() / h) * k[None, :]
    C, H, L, O = C + adj, H + adj, L + adj, O + adj
    return {"C": C, "H": H, "L": L, "O": O, "dates": df.index[starts], "blocks": (starts - starts[0]) // h,
            "n": len(starts), "n_eff": len(starts) / h, "h": h, "vol_now": vol_now, "mu_h": mu_h}


def shift_paths(sc: Dict[str, Any], dmu: float) -> Dict[str, Any]:
    """Same scenarios with the signal drift moved by dmu (log return over h)."""
    k = np.arange(1, sc["h"] + 1)[None, :] * (dmu / sc["h"])
    out = dict(sc)
    for key in ("C", "H", "L", "O"):
        out[key] = sc[key] + k
    out["mu_h"] = sc["mu_h"] + dmu
    return out


def vertical_returns(sc: Dict[str, Any], S0: float, K1: float, K2: float, debit: float) -> np.ndarray:
    """Return per $ of debit for a bull call spread held to expiry."""
    ST = S0 * np.exp(sc["C"][:, -1])
    payoff = np.clip(ST - K1, 0.0, K2 - K1)
    return payoff / debit - 1.0


def stock_trade_returns(sc: Dict[str, Any], stop: float, target: float) -> Tuple[np.ndarray, Dict[str, float]]:
    """Long from today's close with a stop and a target, exit at the horizon close
    otherwise. Gaps through a level fill at the open; a day that touches both
    levels is scored as a stop (daily bars can't order them)."""
    ls, lt = math.log(1 - stop), math.log(1 + target)
    n, h = sc["C"].shape
    out = np.full(n, np.nan)
    done = np.zeros(n, dtype=bool)
    hit_t = np.zeros(n, dtype=bool)
    hit_s = np.zeros(n, dtype=bool)
    for j in range(h):
        o, hh, ll = sc["O"][:, j], sc["H"][:, j], sc["L"][:, j]
        gap_dn = ~done & (o <= ls)
        out[gap_dn] = np.expm1(o[gap_dn]); hit_s |= gap_dn; done |= gap_dn
        gap_up = ~done & (o >= lt)
        out[gap_up] = np.expm1(o[gap_up]); hit_t |= gap_up; done |= gap_up
        s_ = ~done & (ll <= ls)
        out[s_] = -stop; hit_s |= s_; done |= s_
        t_ = ~done & (hh >= lt)
        out[t_] = target; hit_t |= t_; done |= t_
    left = ~done
    out[left] = np.expm1(sc["C"][left, -1])
    return out, {"p_target": float(hit_t.mean()), "p_stop": float(hit_s.mean()), "p_timeout": float(left.mean())}


def _block_dirichlet(blocks: np.ndarray, B: int, rng) -> np.ndarray:
    ub, inv = np.unique(blocks, return_inverse=True)
    w = rng.dirichlet(np.ones(len(ub)), size=B)[:, inv]
    counts = np.bincount(inv)[inv]
    w = w / counts
    return w / w.sum(axis=1, keepdims=True)


def kelly_with_uncertainty(make_R, sc: Dict[str, Any], mu_se: float = 0.0, f_cap: float = 0.995,
                           B: int = 120, seed: int = 7, dd: Optional[Tuple[float, float]] = None) -> Dict[str, Any]:
    """make_R(scenarios) -> per-unit returns. Point estimate on the scenarios as
    given; uncertainty from block Bayesian bootstrap weights and, when mu_se > 0,
    draws of the signal drift. Returns raw f, shrink k, drawdown cap."""
    rng = np.random.default_rng(seed)
    R0 = make_R(sc)
    f_raw, g_raw = kelly_from_returns(R0, f_cap)
    res = {"f_raw": f_raw, "growth": g_raw, "mean_R": float(np.nanmean(R0)), "R": R0,
           "p_gain": float(np.mean(R0 > 0)), "n": sc["n"], "n_eff": sc["n_eff"]}
    zs = np.array([0.0]) if mu_se <= 0 else np.array([-1.38, -0.67, 0.0, 0.67, 1.38])
    grid = F_GRID[F_GRID <= f_cap]
    fb = []
    for z in zs:
        Rz = R0 if z == 0 else make_R(shift_paths(sc, z * mu_se))
        Rz = np.where(np.isfinite(Rz), Rz, 0.0)
        with np.errstate(divide="ignore", invalid="ignore"):
            Lm = np.log1p(np.outer(Rz, grid))
        Lm = np.where(np.isfinite(Lm), Lm, -1e6)
        W = _block_dirichlet(sc["blocks"], max(B // len(zs), 10), rng)
        gb = W @ Lm
        fb.append(grid[np.argmax(gb, axis=1)])
    fb = np.concatenate(fb)
    var_f = float(np.var(fb))
    res["f_boot_sd"] = math.sqrt(var_f)
    res["shrink"] = (f_raw ** 2 / (f_raw ** 2 + var_f)) if f_raw > 0 else 0.0
    res["f_dd"] = drawdown_cap(R0, dd[0], dd[1], f_cap) if dd else f_cap
    return res


def joint_kelly(Rmat: np.ndarray, upper: np.ndarray, cap: float, iters: int = 600) -> np.ndarray:
    """max mean log(1 + R f) s.t. 0 <= f <= upper, sum f <= cap (projected gradient)."""
    m = Rmat.shape[1]
    cap = min(cap, 0.98)

    def proj(f):
        f = np.clip(f, 0, upper)
        if f.sum() <= cap:
            return f
        lo, hi = 0.0, float(f.max())
        for _ in range(60):
            t = 0.5 * (lo + hi)
            if np.clip(f - t, 0, upper).sum() > cap:
                lo = t
            else:
                hi = t
        return np.clip(f - hi, 0, upper)

    def obj(f):
        p = 1 + Rmat @ f
        return float(np.mean(np.log(p))) if np.all(p > 0) else -np.inf

    f = np.zeros(m)
    cur, eta = obj(f), 0.5
    for _ in range(iters):
        p = 1 + Rmat @ f
        g = (Rmat / p[:, None]).mean(axis=0)
        while eta > 1e-6:
            fn = proj(f + eta * g)
            v = obj(fn)
            if v > cur + 1e-12:
                f, cur = fn, v
                eta *= 1.3
                break
            eta *= 0.5
        else:
            break
    return f


def signal_drift(calib: Optional[Dict[str, Any]], composite_pct: float, h: int) -> Tuple[float, float, str]:
    """Bucket excess return from the non-overlapping calibration sample, scaled to
    h sessions. Relative (cross-sectional) edge only; market drift stays zero."""
    if not calib or "res" not in calib or "error" in calib["res"] or not np.isfinite(_n(composite_pct, np.nan)):
        return 0.0, 0.0, "none"
    res = calib["res"]
    tab = res["nonoverlap"]
    cal_h = res["meta"]["horizon"]
    lab = next((b[2] for b in CAL_BUCKETS if b[0] <= composite_pct < b[1]), None)
    row = tab[tab["bucket"] == lab]
    if row.empty or "excess_ret_pct" not in row or not np.isfinite(_n(row["excess_ret_pct"].iloc[0], np.nan)):
        return 0.0, 0.0, "none"
    scale = h / cal_h
    mu = _n(row["excess_ret_pct"].iloc[0]) / 100.0 * scale
    se = _n(row["excess_ret_se"].iloc[0], 0.0) / 100.0 * scale
    return mu, se, lab


def atr_pct(ohlc: pd.DataFrame, n: int = 20) -> float:
    c, h, l = ohlc["close"], ohlc["high"], ohlc["low"]
    tr = pd.concat([h - l, (h - c.shift(1)).abs(), (l - c.shift(1)).abs()], axis=1).max(axis=1)
    return _n(tr.iloc[-n:].mean() / c.iloc[-1], 0.03)


def size_rows(rows: List[Dict[str, Any]], bankroll: float, frac: float, max_loss_pct: float,
              regime_mult: float) -> List[Dict[str, Any]]:
    """Turn Kelly results into final fractions and dollars. Loss per unit staked
    is 1 for debits (premium) and the stop distance for stock trades."""
    out = []
    for r in rows:
        f_kelly = r["f_raw"] * r["shrink"] * frac * regime_mult
        f_dd = r.get("f_dd", 1.0)
        f_k = min(f_kelly, f_dd)
        loss_per_unit = r.get("loss_per_unit", 1.0)
        f_loss_cap = max_loss_pct / max(loss_per_unit, 1e-9)
        f_final = min(f_k, f_loss_cap)
        if r["f_raw"] <= 0:
            binding = "no edge"
        elif f_final < f_k - 1e-12:
            binding = "loss cap"
        elif f_dd < f_kelly - 1e-12:
            binding = "drawdown cap"
        else:
            binding = "kelly"
        if r.get("refuse"):
            f_final, binding = 0.0, "refuse list"
        r = dict(r)
        r.update({"f_final": f_final, "dollars": f_final * bankroll, "binding": binding,
                  "max_loss_pct_book": f_final * loss_per_unit})
        out.append(r)
    return out


# ═══════════════════════════════════════════════════════════════════════════
#  EXPECTANCY AND KELLY  (Stocks > Expectancy & Kelly; also the Price action desk and the Strategy lab)
#  A trade's value is its whole distribution of outcomes, measured in R (profit / the risk taken):
#    win rate p, average win W and average loss L, payoff ratio b = W / L, breakeven win rate 1 / (1 + b),
#    expectancy E[R] = p W - (1 - p) L.
#  Kelly (Kelly 1956; Thorp 1997, "The Kelly criterion in blackjack, sports betting and the stock market") stakes the
#  fraction f of equity on 1R that maximizes E[log(1 + f R)]: p / L - (1 - p) / W for two outcomes, or the argmax over
#  the whole sample of R. Thorp's practical points carry the design: past Kelly, growth falls fast (about zero at twice
#  Kelly when outcomes are close to normal); half Kelly keeps about three quarters of the growth for half the
#  volatility; and estimated edges are smaller than they look, hence the Baker-McHale shrink. Bets here are taken in
#  sequence; trades that overlap in time share one bankroll, so per-trade Kelly is divided across the positions open.
#  Gates, judged only on trades that had closed by the signal close (no look-ahead):
#    Parker (Unknown Market Wizards): trade a system only while its equity curve is above its own average;
#    Soreide (2019 US Investing Champion): cut risk when recent trades stop paying (last n trades' mean R below zero).
#  Drawdown ladder (Dhaliwal, Unknown Market Wizards): halve size at a 5% drawdown, halve again at 8%, stop at 15%;
#    here a stopped book restarts at quarter size when the setup's own equity curve is back above its average.
# ═══════════════════════════════════════════════════════════════════════════

EXP_LADDER = ((0.05, 0.5), (0.08, 0.25), (0.15, 0.0))     # (drawdown from peak, size multiplier)
EXP_GATES = {"parker": "Own equity curve vs its average (Parker)", "recent": "Last trades' expectancy (Soreide)"}
EXP_GATE_N = {"parker": 20, "recent": 10}
EXP_KEYS = ["n", "win", "avg_win", "avg_loss", "payoff", "be_win", "margin", "er", "kelly2", "kelly", "shrink",
            "kelly_shrunk", "half_share", "g_kelly", "g_double", "skew", "p05", "p25", "p50", "p75", "p95", "tail5", "big3"]


def growth_rate(r: np.ndarray, f: float) -> float:
    """E[log(1 + f R)] per bet; -inf if any outcome would wipe out the stake."""
    r = np.asarray(r, float)
    r = r[np.isfinite(r)]
    if not len(r):
        return np.nan
    x = 1.0 + f * r
    if np.any(x <= 0):
        return -np.inf
    return float(np.mean(np.log(x)))


def expectancy_stats(r: np.ndarray, n_eff: Optional[float] = None) -> Dict[str, float]:
    """The distribution of outcomes in R, summarized for expectancy and Kelly. n_eff = independent observations
    behind the estimate (signal dates for a setup), used by the Baker-McHale shrink."""
    r = np.asarray(r, float)
    r = r[np.isfinite(r)]
    out: Dict[str, float] = {k: np.nan for k in EXP_KEYS}
    out["n"] = float(len(r))
    if not len(r):
        return out
    win = r > 0
    p = float(win.mean())
    W = float(r[win].mean()) if win.any() else 0.0
    L = float(-r[~win].mean()) if (~win).any() else 0.0
    b = W / L if L > 0 else np.inf
    be = 1.0 / (1.0 + b) if np.isfinite(b) else 0.0
    out.update({"win": p, "avg_win": W, "avg_loss": L, "payoff": b, "be_win": be, "margin": p - be, "er": float(r.mean())})
    if W > 0 and L > 0:
        out["kelly2"] = min(kelly_two_outcome(p, W, L), 1.0)
        _, k_, _ = binary_shrink(p, W, float(n_eff or len(r)), L)
        out["shrink"] = k_
    elif W > 0:
        out["kelly2"], out["shrink"] = 1.0, 1.0
    else:
        out["kelly2"], out["shrink"] = 0.0, 0.0
    f, g = kelly_from_returns(r)
    out["kelly"], out["g_kelly"] = f, (g if f > 0 else 0.0)
    out["kelly_shrunk"] = f * _n(out["shrink"], 0.0)
    if f > 0 and g > 0:
        out["half_share"] = growth_rate(r, f / 2) / g
        out["g_double"] = growth_rate(r, min(2 * f, 0.995))
    sd = float(r.std())
    out["skew"] = float(np.mean((r - r.mean()) ** 3) / sd ** 3) if sd > 0 else np.nan
    for q, k in ((5, "p05"), (25, "p25"), (50, "p50"), (75, "p75"), (95, "p95")):
        out[k] = float(np.percentile(r, q))
    tot = float(r.sum())
    top = np.sort(r)[::-1][:max(1, int(math.ceil(0.05 * len(r))))]
    out["tail5"] = float(top.sum() / tot) if tot > 0 else np.nan
    out["big3"] = float((r >= 3).mean())
    return out


def r_path_stats(r_seq: np.ndarray) -> Dict[str, float]:
    """For trades in the order they were taken: longest run of losers and the deepest fall of the running sum of R."""
    r = np.asarray(r_seq, float)
    r = r[np.isfinite(r)]
    if not len(r):
        return {"streak": 0.0, "dd_r": np.nan}
    streak = best = 0
    for x in r:
        streak = streak + 1 if x <= 0 else 0
        best = max(best, streak)
    cum = np.cumsum(r)
    dd = float(np.max(np.maximum.accumulate(np.r_[0.0, cum]) - np.r_[0.0, cum]))
    return {"streak": float(best), "dd_r": dd}


def open_at_once(e: np.ndarray, hold: np.ndarray) -> float:
    """Average number of trades open on the sessions when at least one is open (entry index e, `hold` sessions)."""
    e = np.asarray(e, np.int64)
    hold = np.asarray(hold, np.int64)
    ok = (e >= 0) & (hold > 0)
    if not ok.any():
        return np.nan
    e, hold = e[ok], hold[ok]
    n = int((e + hold).max()) + 2
    d = np.zeros(n)
    np.add.at(d, e, 1.0)
    np.add.at(d, e + hold, -1.0)
    live = np.cumsum(d)[:-1]
    busy = live > 0
    return float(live[busy].mean()) if busy.any() else np.nan


def gate_labels(ev: pd.DataFrame, mode: str = "parker", n: Optional[int] = None) -> np.ndarray:
    """Per event: 'gate on', 'gate off' or 'warming up', judged on the same setup's trades that had closed by the
    signal-day close. parker: running sum of R at or above its n-trade average. recent: the last n closed trades'
    mean R at or above zero."""
    n = int(n or EXP_GATE_N.get(mode, 20))
    out = np.full(len(ev), "warming up", dtype=object)
    if not len(ev) or "exit_date" not in ev:
        return out
    status = ev["status"].to_numpy()
    exits = pd.to_datetime(ev["exit_date"]).to_numpy("datetime64[ns]")
    sig = pd.to_datetime(ev["date"]).to_numpy("datetime64[ns]")
    rr = ev["r"].to_numpy(float)
    done = (status == 0) & ~np.isnat(exits) & np.isfinite(rr)
    for _, pos in ev.groupby("setup", sort=False).indices.items():
        pos = np.asarray(pos)
        cl = pos[done[pos]]
        if not len(cl):
            continue
        order = np.argsort(exits[cl], kind="stable")
        ex, r_ = exits[cl][order], rr[cl][order]
        cum = np.cumsum(r_)
        k = np.searchsorted(ex, sig[pos], side="right")             # trades closed on or before the signal day
        ok = k >= n
        last = np.clip(k - 1, 0, None)
        if mode == "recent":
            cs = np.r_[0.0, cum]
            on = (cs[k] - cs[np.clip(k - n, 0, None)]) / n >= 0
        else:
            ma = pd.Series(cum).rolling(n, min_periods=n).mean().to_numpy()
            on = cum[last] >= np.where(np.isfinite(ma[last]), ma[last], np.inf)
        out[pos] = np.where(~ok, "warming up", np.where(on, "gate on", "gate off"))
    return out


def ladder_mult(dd: float, ladder=EXP_LADDER) -> float:
    m = 1.0
    for lvl, mult in ladder:
        if dd >= lvl - 1e-12:
            m = mult
    return m


def simulate_sequence(r_seq: np.ndarray, f: float, ladder=None, resume: Optional[np.ndarray] = None) -> Dict[str, Any]:
    """Equity path from staking f of equity on 1R for each trade in order. With a ladder the stake shrinks with the
    drawdown from the peak; at a zero step trading stops and restarts at the last non-zero step when resume[i] is True
    (the setup's own equity curve back above its average), with the drawdown measured from that restart."""
    r = np.asarray(r_seq, float)
    eq, peak, path, taken, stopped, floor_eq = 1.0, 1.0, [1.0], 0, False, None
    restart = min((m for _, m in ladder if m > 0), default=0.25) if ladder else 1.0
    stop_lvl = max((lvl for lvl, m in ladder if m <= 0), default=1.0) if ladder else 1.0
    for i, x in enumerate(r):
        if not np.isfinite(x):
            path.append(eq)
            continue
        m = 1.0
        if ladder:
            if stopped:
                if resume is not None and bool(resume[i]):
                    stopped, floor_eq = False, eq
                else:
                    path.append(eq)
                    continue
            m = ladder_mult(1.0 - eq / peak, ladder)
            if m <= 0:
                if floor_eq is not None and eq > floor_eq * (1.0 - stop_lvl):
                    m = restart                                 # restarted: quarter size until the drawdown heals
                else:
                    stopped, floor_eq = True, None
                    path.append(eq)
                    continue
        eq = max(eq * (1.0 + f * m * x), 0.0)
        taken += 1
        if eq >= peak:
            peak, floor_eq = eq, None
        path.append(eq)
    p = np.array(path)
    dd = float(np.max(1 - p / np.maximum.accumulate(p))) if len(p) else np.nan
    return {"path": p, "final": float(p[-1]), "maxdd": dd, "taken": taken, "skipped": int(np.isfinite(r).sum()) - taken}


def simulate_dated(entry, exit_, r: np.ndarray, f: float, ladder=None, resume: Optional[np.ndarray] = None) -> Dict[str, Any]:
    """Overlapping trades on one bankroll. Each trade risks f (times the ladder step) of equity as of its entry date
    and books f x R on its exit date; on a date, entries are sized before that date's exits are booked. With a ladder,
    a zero step stops new entries until resume[i] is True for a later signal (restart at the last non-zero step);
    a restarted book stops again if it loses the zero step's depth from the restart point."""
    ent = pd.to_datetime(pd.Series(entry)).to_numpy("datetime64[ns]")
    ex = pd.to_datetime(pd.Series(exit_)).to_numpy("datetime64[ns]")
    r = np.asarray(r, float)
    ok = np.isfinite(r) & ~np.isnat(ent) & ~np.isnat(ex)
    idx = np.flatnonzero(ok)
    empty = {"dates": pd.DatetimeIndex([]), "path": np.array([1.0]), "final": 1.0, "maxdd": 0.0, "taken": 0, "skipped": 0,
             "cagr": np.nan, "years": np.nan}
    if not len(idx):
        return empty
    dates = np.unique(np.r_[ent[idx], ex[idx]])
    e_pos, x_pos = np.searchsorted(dates, ent[idx]), np.searchsorted(dates, ex[idx])
    x_pos = np.maximum(x_pos, e_pos)
    ent_at: Dict[int, List[int]] = {}
    ex_at: Dict[int, List[int]] = {}
    for k, (a, b) in enumerate(zip(e_pos, x_pos)):
        ent_at.setdefault(int(a), []).append(k)
        ex_at.setdefault(int(b), []).append(k)
    rr = r[idx]
    rs = (np.asarray(resume, bool)[idx] if resume is not None else None)
    stake = np.zeros(len(idx))
    taken = np.zeros(len(idx), bool)
    restart = min((m for _, m in ladder if m > 0), default=0.25) if ladder else 1.0
    stop_lvl = max((lvl for lvl, m in ladder if m <= 0), default=1.0) if ladder else 1.0
    eq, peak, stopped, floor_eq = 1.0, 1.0, False, None
    path = np.empty(len(dates))
    for di in range(len(dates)):
        for k in ent_at.get(di, []):
            m = 1.0
            if ladder:
                if stopped:
                    if rs is not None and rs[k]:
                        stopped, floor_eq = False, eq
                    else:
                        continue
                m = ladder_mult(1.0 - eq / peak, ladder)
                if m <= 0:
                    if floor_eq is not None and eq > floor_eq * (1.0 - stop_lvl):
                        m = restart
                    else:
                        stopped, floor_eq = True, None
                        continue
            stake[k], taken[k] = f * m * eq, True
        for k in ex_at.get(di, []):
            if taken[k]:
                eq = max(eq + stake[k] * rr[k], 0.0)
        if eq >= peak:
            peak, floor_eq = eq, None
        path[di] = eq
    full = np.r_[1.0, path]
    dd = float(np.max(1 - full / np.maximum.accumulate(full)))
    years = (pd.Timestamp(dates[-1]) - pd.Timestamp(dates[0])).days / 365.25
    final = float(path[-1])
    cagr = final ** (1 / years) - 1 if years > 0.25 and final > 0 else np.nan
    return {"dates": pd.DatetimeIndex(dates), "path": path, "final": final, "maxdd": dd, "taken": int(taken.sum()),
            "skipped": int(len(idx) - taken.sum()), "cagr": cagr, "years": years}


def bootstrap_sequences(r: np.ndarray, fs: Dict[str, float], n_trades: int = 100, sims: int = 2000,
                        seed: int = 13) -> pd.DataFrame:
    """Resample n_trades outcomes (with replacement) and bet each stake in `fs` in sequence: the spread of ending
    equity and of the worst drawdown along the way."""
    r = np.asarray(r, float)
    r = r[np.isfinite(r)]
    rows = []
    if len(r) < 10:
        return pd.DataFrame()
    draw = np.random.default_rng(seed).choice(r, size=(sims, n_trades))
    for lab, f in fs.items():
        if not np.isfinite(f) or f <= 0:
            continue
        mult = np.maximum(1.0 + f * draw, 0.0)
        eq = np.cumprod(mult, axis=1)
        full = np.c_[np.ones(sims), eq]
        dd = np.max(1 - full / np.maximum.accumulate(full, axis=1), axis=1)
        end = eq[:, -1]
        rows.append({"stake": lab, "f": f, "median_end": float(np.median(end)), "p10_end": float(np.percentile(end, 10)),
                     "p90_end": float(np.percentile(end, 90)), "p_loss": float((end < 1).mean()),
                     "p_dd20": float((dd >= 0.20).mean()), "p_dd50": float((dd >= 0.50).mean()),
                     "med_dd": float(np.median(dd))})
    return pd.DataFrame(rows)


# ═══════════════════════════════════════════════════════════════════════════
#  LBR DESK  (educational reconstruction of Linda Bradford Raschke's public rules)
#  Ported from lbr_outlook_dashboard.py. Changes vs that script:
#    * 2-4 day rhythm labels were inverted: 2-4 days off a relative LOW is when the
#      rally "looks good" (her sell time); 2-4 days off a relative HIGH is the buy
#      time. Sell rule S1 now follows the corrected labels (and agrees with Taylor).
#    * "3 small ranges" = three ranges each under 0.75 ATR (was: under 1 ATR, which
#      fires on most quiet weeks and inflated the armed-setup count).
#    * Turtle Soup requires the prior 20-day extreme to be at least 4 sessions old
#      (Connors & Raschke, Street Smarts).
#    * 80-20 is split into "armed" (one-sided prior candle) and "triggered" (today
#      traded through the prior extreme and closed back inside).
#    * Signals score completed bars; the color board uses the live (partial) bar.
#    * Futures come from Yahoo; with Massive the desk can run on ETF proxies.
# ═══════════════════════════════════════════════════════════════════════════

