def et_today() -> date:
    return now_et().date()


def brief_phase(t: Optional[datetime] = None) -> str:
    t = t or now_et()
    if t.weekday() >= 5:
        return "closed"
    hm = (t.hour, t.minute)
    return "pre-market" if hm < (9, 30) else "intraday" if hm < (16, 0) else "after the close"


def session_volume_frac(t: datetime) -> float:
    """Share of a normal day's volume that has usually traded by time t (ET): the U-shaped intraday profile."""
    xs, ys = zip(*VOL_PROFILE)
    return float(np.interp(t.hour * 60 + t.minute + t.second / 60, xs, ys))


def massive_snapshot(key: str) -> Dict[str, Dict[str, Any]]:
    """Every US stock and ETF in one call: today's bar so far, the latest minute, and the prior day."""
    last_err: Optional[Exception] = None
    for base in MASSIVE_BASES:
        try:
            js = http_json(f"{base}/v2/snapshot/locale/us/markets/stocks/tickers", {"apiKey": key})
            return {r["ticker"]: r for r in (js or {}).get("tickers") or [] if r.get("ticker")}
        except PlanError as e:
            last_err = e
    if last_err:
        raise last_err
    return {}


def snap_asof(snap: Dict[str, Dict[str, Any]]) -> Optional[datetime]:
    """When the snapshot's data is from (its `updated` stamps, nanoseconds), in ET."""
    ts = sorted(v for v in (_n(r.get("updated"), 0.0) for r in snap.values()) if v > 0)
    if not ts:
        return None
    v = float(np.median(ts[-min(200, len(ts)):]))
    sec_ = v / 1e9 if v > 1e17 else v / 1e3 if v > 1e11 else v
    if _ET:
        return datetime.fromtimestamp(sec_, tz=_ET)
    u_ = datetime.utcfromtimestamp(sec_)
    return u_ - timedelta(hours=et_offset_hours(u_))


def _bad_symbol(t: str) -> bool:
    """Warrants, units, rights, preferreds and test symbols in the whole-market snapshot."""
    return not re.fullmatch(r"[A-Z]{1,5}", t or "") or (len(t) == 5 and t[-1] in "WUR")


def in_play_table(P: Dict[str, pd.DataFrame], snap: Optional[Dict[str, Dict[str, Any]]] = None, vol_frac: float = 1.0,
                  whole: bool = False, today: Optional[date] = None, premarket: bool = False,
                  after_close: bool = False) -> Tuple[pd.DataFrame, str]:
    """Gap, change and relative volume for every name: live from the snapshot when there is one, else the last session.
    Relative volume is paced: today's volume against the share of a normal day that has usually traded by now."""
    C, O, V, H, L = (P[k] for k in ("close", "open", "volume", "high", "low"))
    today_ts = pd.Timestamp(today or et_today())
    done = (C.index < today_ts) if snap else np.r_[np.ones(len(C) - 1, bool), False]
    Ch, Vh = C[done], V[done]
    avg50 = Vh.iloc[-50:].mean()
    dv = (Ch * Vh).iloc[-20:].median() / 1e6
    if snap:
        names = [t for t in snap if not _bad_symbol(t)] if whole else [t for t in C.columns if t in snap]
        rows = {}
        for t in names:
            s = snap[t]
            day, prev, mn = s.get("day") or {}, s.get("prevDay") or {}, s.get("min") or {}
            pc = _n(prev.get("c"), np.nan)
            last = ((_n(day.get("c"), 0.0) or _n(mn.get("c"), 0.0)) if after_close     # the regular-session close
                    else (_n(mn.get("c"), 0.0) or _n(day.get("c"), 0.0)))
            if not (pc > 0 and last > 0):
                continue
            rows[t] = {"prev_close": pc, "open": _n(day.get("o"), np.nan) or np.nan, "last": last,
                       "vwap": _n(day.get("vw"), np.nan) or np.nan,
                       "high": _n(day.get("h"), np.nan) or np.nan, "low": _n(day.get("l"), np.nan) or np.nan,
                       "volume": _n(day.get("v"), 0.0), "prev_high": _n(prev.get("h"), np.nan),
                       "prev_low": _n(prev.get("l"), np.nan), "prev_volume": _n(prev.get("v"), np.nan)}
        D = pd.DataFrame.from_dict(rows, orient="index")
        mode = "live"
    else:
        D = pd.DataFrame({"prev_close": C.iloc[-2], "open": O.iloc[-1], "last": C.iloc[-1], "high": H.iloc[-1],
                          "vwap": P["vwap"].iloc[-1] if "vwap" in P else np.nan,
                          "low": L.iloc[-1], "volume": V.iloc[-1], "prev_high": H.iloc[-2], "prev_low": L.iloc[-2],
                          "prev_volume": V.iloc[-2]}).dropna(subset=["prev_close", "last"])
        mode, vol_frac, premarket = "last session", 1.0, False
    if D.empty:
        return D, mode
    D = D.astype(float)
    D["gap"] = D["open"] / D["prev_close"] - 1
    D["chg"] = D["last"] / D["prev_close"] - 1
    use_gap = D["gap"].notna() & (D["gap"].abs() > D["chg"].abs())
    D["move"] = np.where(use_gap, D["gap"], D["chg"])
    base = avg50.reindex(D.index)
    D["vol_base"] = np.where(base.notna(), "50-day average", "yesterday")
    base = base.fillna(D["prev_volume"]).where(lambda x: x > 0)
    if premarket:
        D["pm_share"], D["rvol"] = D["volume"] / base, np.nan
    else:
        D["pm_share"], D["rvol"] = np.nan, D["volume"] / (base * max(vol_frac, 0.02))
    D["dv_m"] = dv.reindex(D.index).fillna(D["prev_close"] * D["prev_volume"] / 1e6)
    a = D["move"].abs()
    tier = pd.Series("", index=D.index, dtype=object)
    for name, mv, rv in reversed(EP_TIERS):                      # WATCH first, STRONG last so the top tier wins
        tier[(a >= mv) & (D["rvol"].isna() | (D["rvol"] >= rv))] = name
    up = D["move"] > 0
    D["ep_tier"] = tier.where(up, "")
    D["down_tier"] = tier.where(~up, "")
    # Stockbee's EP 9 million: 9M+ shares so far, above the prior close, $3+, on 3x+ the usual pace when that is known
    D["ep9m"] = ((D["volume"] >= EP9M_VOL) & (D["chg"] > 0) & (D["last"] >= EP9M_MIN_PX)
                 & (D["rvol"].isna() | (D["rvol"] >= EP9M_RVOL)))
    D["vol_pending"] = D["rvol"].isna()
    return D, mode


def in_play_context(D: pd.DataFrame, P: Dict[str, pd.DataFrame], live: bool, today: Optional[date] = None) -> pd.DataFrame:
    """Where each mover sits on its chart before today's move: 52-week range, averages, ATR, 3-month RS, and a setup label."""
    C, H, L = P["close"], P["high"], P["low"]
    today_ts = pd.Timestamp(today or et_today())
    done = (C.index < today_ts) if live else np.r_[np.ones(len(C) - 1, bool), False]
    Ch, Hh, Lh = C[done], H[done], L[done]
    names = [t for t in D.index if t in Ch.columns]
    out = pd.DataFrame(index=D.index)
    if not names or len(Ch) < 30:
        return out
    Ch, Hh, Lh = Ch[names], Hh[names], Lh[names]
    pc1 = Ch.shift(1)
    tr = np.fmax(np.fmax(Hh - Lh, (Hh - pc1).abs()), (Lh - pc1).abs())
    ret63 = Ch.iloc[-1] / Ch.iloc[-64] - 1 if len(Ch) > 64 else Ch.iloc[-1] / Ch.iloc[0] - 1
    full = C[done]
    r63_all = (full.iloc[-1] / full.iloc[-64] - 1) if len(full) > 64 else full.iloc[-1] / full.iloc[0] - 1
    rs = (r63_all.rank(pct=True) * 98 + 1).reindex(names)
    ctx = pd.DataFrame({"hi52": Hh.iloc[-252:].max(), "lo52": Lh.iloc[-252:].min(), "ma50": Ch.iloc[-50:].mean(),
                        "ma200": Ch.iloc[-200:].mean() if len(Ch) >= 200 else np.nan,
                        "ema21": Ch.ewm(span=21, adjust=False).mean().iloc[-1], "atr": tr.iloc[-20:].mean(),
                        "adr": ((Hh / Lh - 1).iloc[-20:].mean() * 100), "ret63": ret63, "rs": rs,
                        "prev_close_h": Ch.iloc[-1]})
    out = out.join(ctx)
    last, pc = D["last"], out["prev_close_h"]
    up = D["move"] > 0
    out["new_hi"] = last > out["hi52"]
    out["new_lo"] = last < out["lo52"]
    out["from_hi"] = last / out["hi52"] - 1
    out["ext50_atr"] = (last - out["ma50"]) / out["atr"]
    lab_ = pd.Series("", index=out.index, dtype=object)
    has = out["hi52"].notna()
    lab_[has & up] = "Gap up"
    lab_[has & up & (last < out["ma200"])] = "Gap up in a downtrend (a bounce until proven otherwise)"
    lab_[has & up & (last > out["ma50"]) & (out["from_hi"] >= -0.15)] = "Gap up near highs, in an uptrend"
    lab_[has & up & (pc < out["ma50"]) & (last > out["ma50"])] = "Reclaims the 50-day"
    lab_[has & up & out["new_hi"]] = "Gap to a new 52-week high"
    lab_[has & ~up] = "Gap down"
    lab_[has & ~up & (last > out["ma50"])] = "Gap down inside an uptrend (watch for a reclaim)"
    lab_[has & ~up & (pc > out["ma50"]) & (last < out["ma50"])] = "Loses the 50-day"
    lab_[has & ~up & out["new_lo"]] = "Breakdown to a new 52-week low"
    out["setup"] = lab_
    return out


def in_play_points(D: pd.DataFrame) -> pd.Series:
    """0-10 'in play' points, scored like the War Room's conviction: the size of the move, its volume, liquidity, and
    whether the chart agrees (near highs and strong RS for gappers up; under the 50-day and weak RS for gappers down)."""
    a = D["move"].abs()
    p = (a >= 0.03).astype(int) + (a >= 0.08) + (a >= 0.15) + (a >= 0.25)
    rv, pm = D["rvol"], D.get("pm_share", pd.Series(np.nan, index=D.index))
    vol_pts = np.where(rv.notna(), (rv >= 1.3).astype(int) + (rv >= 2) + (rv >= 4),
                       (pm >= 0.05).astype(int) + (pm >= 0.10) + (pm >= 0.20))
    p = p + vol_pts + (D["dv_m"] >= 20)
    up = D["move"] > 0
    g = lambda c: D[c] if c in D else pd.Series(np.nan, index=D.index)
    p = p + np.where(up, (g("from_hi") >= -0.05).astype(int) + (g("rs") >= 80),
                     (D["last"] < g("ma50")).astype(int) + (g("rs") <= 20))
    return pd.Series(p, index=D.index).astype(int)


def brief_grade(points: float) -> str:
    return next(g for cut, g in BRIEF_GRADE if points >= cut)


def market_condition(spy: pd.Series, C: pd.DataFrame, V: pd.DataFrame, chip: str = "", unwind: bool = False) -> Dict[str, Any]:
    """SPY's trend plus Stockbee-style breadth across the loaded universe (completed sessions only)."""
    s = spy.dropna()
    e21, s50 = s.ewm(span=21, adjust=False).mean(), s.rolling(50).mean()
    ma40 = C.rolling(40, min_periods=40).mean()
    known = ma40.notna().sum(axis=1).replace(0, np.nan)
    t2108 = ((C > ma40).sum(axis=1) / known * 100).dropna()
    r1 = C / C.shift(1) - 1
    vup = V > V.shift(1)
    up4 = ((r1 >= 0.04) & vup).sum(axis=1)
    dn4 = ((r1 <= -0.04) & vup).sum(axis=1)
    def _ratio(w):
        u, d_ = up4.rolling(w).sum(), dn4.rolling(w).sum()
        return (u / d_.clip(lower=1)).where((u + d_) > 0)        # no breakdowns: count each breakout against one
    rat5, rat10 = _ratio(5), _ratio(10)
    r20, r65, r34 = C / C.shift(20) - 1, C / C.shift(65) - 1, C / C.shift(34) - 1
    hist = pd.DataFrame({"up4": up4, "dn4": dn4, "rat5": rat5, "rat10": rat10,
                         "up25q": (r65 >= 0.25).sum(axis=1), "dn25q": (r65 <= -0.25).sum(axis=1),
                         "up25m": (r20 >= 0.25).sum(axis=1), "dn25m": (r20 <= -0.25).sum(axis=1),
                         "up13": (r34 >= 0.13).sum(axis=1), "dn13": (r34 <= -0.13).sum(axis=1),
                         "t2108": t2108, "spy": s}).dropna(subset=["t2108"])
    hist = hist[hist.index.isin(s.index)].iloc[-250:]
    above21, above50 = bool(s.iloc[-1] > e21.iloc[-1]), bool(s.iloc[-1] > s50.iloc[-1])
    rising21 = bool(e21.iloc[-1] > e21.iloc[-6]) if len(e21) > 6 else False
    t = float(t2108.iloc[-1])
    t_prev = float(t2108.iloc[-4]) if len(t2108) > 4 else np.nan
    t_up = bool(t > t_prev) if np.isfinite(t_prev) else False
    r5_, r10_ = _n(rat5.iloc[-1], np.nan), _n(rat10.iloc[-1], np.nan)
    if above21 and above50 and t >= 55 and (not np.isfinite(r10_) or r10_ >= 1.2):
        cond = "STRONG"
    elif above50 and not above21:
        cond = "PULLBACK"
    elif not above50:
        cond = "BOUNCING" if (t_up and _n(r5_, 0) >= 1.0) else "WEAK"
    else:
        cond = "CHOPPY"
    risk = BRIEF_RISK[cond]
    why = [f"SPY {'above' if above21 else 'below'} its 21-day EMA ({'rising' if rising21 else 'falling'}) and "
           f"{'above' if above50 else 'below'} its 50-day",
           f"{t:.0f}% of the universe above its 40-day, {'up' if t_up else 'down'} from {t_prev:.0f}% three sessions ago"
           if np.isfinite(t_prev) else f"{t:.0f}% of the universe above its 40-day"]
    if np.isfinite(r5_) and np.isfinite(r10_):
        why.append(f"4% breakouts vs breakdowns {r5_:.1f}x over 5 days, {r10_:.1f}x over 10")
    if chip == "CRISIS" and risk != "High":
        risk = "High"
        why.append("the climate chip reads CRISIS")
    if unwind:
        risk = "High"
        why.append("the yen carry trade is unwinding")
    return {"cond": cond, "risk": risk, "why": why, "t2108": t, "t_up": t_up, "rat5": r5_, "rat10": r10_,
            "above21": above21, "above50": above50, "hist": hist, "asof": s.index[-1], "n": int(known.iloc[-1] or 0)}


BRIEF_COND_ORDER = ["STRONG", "PULLBACK", "CHOPPY", "BOUNCING", "WEAK"]
BRIEF_RISK_MULT = {"Low": 1.0, "Medium": 0.5, "High": 0.25}        # BRIEF_SIZE: full, half, quarter


def brief_cond_series(spy: pd.Series, C: pd.DataFrame, V: pd.DataFrame) -> pd.Series:
    """The Brief's market condition on every date of C's index, with market_condition's rules and only data known
    at that close (the Setup ledger splits trades by it). '' before the 50-day and the 40-day breadth exist."""
    idx = C.index
    s = spy.dropna()
    e21, s50 = s.ewm(span=21, adjust=False).mean(), s.rolling(50).mean()

    def on_idx(b: pd.Series) -> pd.Series:
        return b.astype(float).reindex(idx).ffill()

    a21, a50, known50 = on_idx(s > e21), on_idx(s > s50), on_idx(s50.notna())
    ma40 = C.rolling(40, min_periods=40).mean()
    known = ma40.notna().sum(axis=1).replace(0, np.nan)
    t = (C > ma40).sum(axis=1) / known * 100
    t_up = t > t.shift(3)
    r1 = C / C.shift(1) - 1
    vup = V.reindex(index=idx, columns=C.columns) > V.reindex(index=idx, columns=C.columns).shift(1)
    up4, dn4 = ((r1 >= 0.04) & vup).sum(axis=1), ((r1 <= -0.04) & vup).sum(axis=1)

    def _ratio(w):
        u, d_ = up4.rolling(w).sum(), dn4.rolling(w).sum()
        return (u / d_.clip(lower=1)).where((u + d_) > 0)

    rat5, rat10 = _ratio(5), _ratio(10)
    above21, above50 = a21 == 1, a50 == 1
    strong = above21 & above50 & (t >= 55) & (rat10.isna() | (rat10 >= 1.2))
    pull = above50 & ~above21
    bounce = ~above50 & t_up & (rat5.fillna(0) >= 1.0)
    cond = np.select([strong, pull, ~above50 & bounce, ~above50], ["STRONG", "PULLBACK", "BOUNCING", "WEAK"], "CHOPPY")
    ok = t.notna() & (known50 == 1) & a21.notna()
    return pd.Series(np.where(ok, cond, ""), index=idx, dtype=object)


def classify_catalyst(text: str) -> str:
    t = (text or "").lower()
    for name, pat in CATALYST_WORDS:
        if re.search(pat, t):
            return name
    return "News" if t.strip() else ""


def pick_catalyst(headlines: List[Dict[str, Any]], earned: bool = False) -> Tuple[str, Optional[Dict[str, Any]]]:
    """The most specific catalyst among the headlines (earnings first when the company just reported)."""
    order = [n for n, _ in CATALYST_WORDS] + ["News"]
    tagged = [(classify_catalyst(h.get("title", "")), h) for h in headlines]
    if earned:
        hit = next((h for c, h in tagged if c == "Earnings"), headlines[0] if headlines else None)
        return "Earnings", hit
    tagged = [x for x in tagged if x[0]]
    if not tagged:
        return "", None
    best = min(tagged, key=lambda x: order.index(x[0]))
    return best


def fetch_headlines(tk: str, key: str, since: date, n: int = 4) -> List[Dict[str, Any]]:
    rows = massive_get_all("/v2/reference/news", {"ticker": tk, "limit": 10, "order": "desc", "sort": "published_utc",
                                                  "published_utc.gte": since.isoformat()}, key, max_pages=1)
    out = []
    for r in rows[:n]:
        ins = next((i for i in (r.get("insights") or []) if (i.get("ticker") or "").upper() == tk), {})
        out.append({"title": r.get("title") or "", "published": r.get("published_utc") or "",
                    "publisher": (r.get("publisher") or {}).get("name") or "", "url": r.get("article_url") or "",
                    "sentiment": ins.get("sentiment") or "", "reason": ins.get("sentiment_reasoning") or ""})
    return out


def lookup_catalysts(tickers: List[str], key: str, since: date) -> Dict[str, Dict[str, Any]]:
    """Headlines, short interest and the reference profile for each name, in parallel."""
    def one(t):
        out: Dict[str, Any] = {"headlines": [], "short": {}, "ov": {}}
        for k, fn in (("headlines", lambda: fetch_headlines(t, key, since)), ("short", lambda: fetch_short(t, key)),
                      ("ov", lambda: fetch_overview(t, key))):
            try:
                out[k] = fn()
            except Exception as e:
                out.setdefault("errors", []).append(f"{k}: {type(e).__name__}")
        return t, out
    res: Dict[str, Dict[str, Any]] = {}
    with ThreadPoolExecutor(max_workers=6) as ex:
        for fut in as_completed([ex.submit(one, t) for t in tickers]):
            t, o = fut.result()
            res[t] = o
    return res


def demo_catalysts(tickers: List[str]) -> Dict[str, Dict[str, Any]]:
    rng = np.random.default_rng(zlib.crc32(",".join(tickers).encode()))
    kinds = ["Earnings", "Analyst", "Contract", "FDA / clinical", "M&A", ""]
