def disk_json(path: Path, default=None):
    try:
        return json.loads(path.read_text())
    except Exception:
        return default


def massive_get_all(path: str, params: Dict[str, Any], key: str, max_pages: int = 20) -> List[dict]:
    """GET a Massive list endpoint and follow next_url. Returns every result row."""
    last_err: Optional[Exception] = None
    for base in MASSIVE_BASES:
        out: List[dict] = []
        try:
            js = http_json(f"{base}{path}", {**params, "apiKey": key})
            pages = 0
            while js:
                res = js.get("results")
                if isinstance(res, dict):
                    out.append(res)
                elif isinstance(res, list):
                    out.extend(res)
                nxt = js.get("next_url")
                pages += 1
                if not nxt or pages >= max_pages:
                    break
                js = http_json(nxt + ("&" if "?" in nxt else "?") + f"apiKey={key}")
            return out
        except PlanError as e:
            last_err = e
            continue
    if last_err:
        raise last_err
    return []


# ---- market breadth (grouped daily bars, every US ticker) -------------------

def _session_days(n: int, end: date) -> List[date]:
    days, d = [], end
    while len(days) < n:
        if d.weekday() < 5:
            days.append(d)
        d -= timedelta(days=1)
    return sorted(days)


def common_stock_set(key: str) -> set:
    """Active US common stocks (type CS) from /v3/reference/tickers; cached a week."""
    path = CACHE_DIR / "cs_tickers.json"
    cached = disk_json(path, {})
    if cached.get("date") and (date.today() - date.fromisoformat(cached["date"])).days < 7 and cached.get("tickers"):
        return set(cached["tickers"])
    rows = massive_get_all("/v3/reference/tickers", {"market": "stocks", "type": "CS", "active": "true", "limit": 1000},
                           key, max_pages=20)
    tks = sorted({r.get("ticker") for r in rows if r.get("ticker")})
    if tks:
        atomic_write_json(path, {"date": date.today().isoformat(), "tickers": tks})
    return set(tks)


def grouped_day(d: date, key: str) -> pd.DataFrame:
    """One session of grouped daily bars, cached on disk (today is never cached)."""
    GROUPED_DIR.mkdir(parents=True, exist_ok=True)
    f = GROUPED_DIR / f"{d.isoformat()}.csv.gz"
    if f.exists():
        try:
            return pd.read_csv(f)
        except Exception:
            pass
    rows = massive_get_all(f"/v2/aggs/grouped/locale/us/market/stocks/{d.isoformat()}", {"adjusted": "true"}, key,
                           max_pages=1)
    df = pd.DataFrame(rows)
    if not df.empty:
        df = df.rename(columns={"T": "ticker", "o": "open", "h": "high", "l": "low", "c": "close", "v": "volume", "vw": "vwap"})
        df = df[[c for c in ("ticker", "open", "high", "low", "close", "volume", "vwap") if c in df.columns]]
    else:
        df = pd.DataFrame(columns=["ticker", "open", "high", "low", "close", "volume", "vwap"])
    if d < date.today():
        tmp = f.with_suffix(".tmp")
        df.to_csv(tmp, index=False, compression="gzip")
        os.replace(tmp, f)
    return df


def grouped_panel(n_sessions: int, key: str, only: Optional[set] = None, min_price: float = 2.0,
                  progress=None, fetch: bool = True) -> Optional[Dict[str, pd.DataFrame]]:
    """close / high / low / volume panels (dates x tickers) from grouped bars.
    fetch=False uses only what is already on disk (no API calls)."""
    end = last_completed_session()
    days = _session_days(int(n_sessions * 1.05) + 10, end)
    frames = {}
    todo = [d for d in days if fetch or (GROUPED_DIR / f"{d.isoformat()}.csv.gz").exists()]
    if not todo:
        return None
    with ThreadPoolExecutor(max_workers=6) as ex:
        futs = {ex.submit(grouped_day, d, key): d for d in todo}
        for i, f in enumerate(as_completed(futs), 1):
            d = futs[f]
            try:
                df = f.result()
            except Exception:
                df = pd.DataFrame()
            if len(df):
                frames[d] = df
            if progress is not None and i % 10 == 0:
                progress.progress(i / len(todo), text=f"Grouped bars {i}/{len(todo)}")
    if len(frames) < 30:
        return None
    long = pd.concat([f.assign(date=pd.Timestamp(d)) for d, f in frames.items()], ignore_index=True)
    if only:
        long = long[long["ticker"].isin(only)]
    long = long[long["close"] >= min_price]
    out = {}
    for col in ("open", "close", "high", "low", "volume"):
        if col in long:
            out[col] = long.pivot_table(index="date", columns="ticker", values=col, aggfunc="last").sort_index().tail(n_sessions)
    return out


def breadth_series(P: Dict[str, pd.DataFrame]) -> pd.DataFrame:
    c, v = P["close"], P["volume"]
    hi = P.get("high", c)
    lo = P.get("low", c)
    chg = c.diff()
    both = c.notna() & c.shift(1).notna()
    adv = ((chg > 0) & both).sum(axis=1)
    dec = ((chg < 0) & both).sum(axis=1)
    unch = ((chg == 0) & both).sum(axis=1)
    upv = v.where((chg > 0) & both).sum(axis=1)
    dnv = v.where((chg < 0) & both).sum(axis=1)
    out = pd.DataFrame({"adv": adv, "dec": dec, "unch": unch, "up_vol": upv, "dn_vol": dnv})
    tot = (adv + dec).replace(0, np.nan)
    out["ad_line"] = (adv - dec).cumsum()
    rana = (adv - dec) / tot * 1000
    out["mcclellan"] = rana.ewm(span=19, adjust=False).mean() - rana.ewm(span=39, adjust=False).mean()
    out["summation"] = out["mcclellan"].cumsum()
    out["trin"] = (adv / dec.replace(0, np.nan)) / (upv / dnv.replace(0, np.nan))
    out["trin10"] = out["trin"].rolling(10).mean()
    out["up_vol_pct"] = upv / (upv + dnv).replace(0, np.nan)
    for n_ in (20, 50, 200):
        sma = c.rolling(n_).mean()
        ok = c.rolling(n_).count() >= n_
        out[f"pct_above_{n_}"] = ((c > sma) & ok).sum(axis=1) / ok.sum(axis=1).replace(0, np.nan)
    hmax = hi.shift(1).rolling(252, min_periods=240).max()
    lmin = lo.shift(1).rolling(252, min_periods=240).min()
    okh = hmax.notna()
    out["new_highs"] = ((hi > hmax) & okh).sum(axis=1).where(okh.sum(axis=1) > 0)
    out["new_lows"] = ((lo < lmin) & okh).sum(axis=1).where(okh.sum(axis=1) > 0)
    nh, nl = out["new_highs"], out["new_lows"]
    out["hilo_index"] = (nh / (nh + nl).replace(0, np.nan)).rolling(10).mean()
    out["thrust_ema"] = (adv / tot).ewm(span=10, adjust=False).mean()
    low_w = out["thrust_ema"].rolling(10).min()
    out["zweig_thrust"] = (out["thrust_ema"] > 0.615) & (low_w < 0.40)
    out["issues"] = both.sum(axis=1)
    return out.iloc[1:]


def breadth_read(b: pd.DataFrame, spy: Optional[pd.Series]) -> Dict[str, Any]:
    last = b.iloc[-1]
    state = "NA"
    why = ""
    if spy is not None and len(spy.dropna()) > 6 and len(b) > 6:
        s5 = float(spy.reindex(b.index).ffill().iloc[-1] / spy.reindex(b.index).ffill().iloc[-6] - 1)
        p5 = float(b["pct_above_20"].iloc[-1] - b["pct_above_20"].iloc[-6])
        prev = (float(spy.reindex(b.index).ffill().iloc[-2] / spy.reindex(b.index).ffill().iloc[-7] - 1),
                float(b["pct_above_20"].iloc[-2] - b["pct_above_20"].iloc[-7]))
        agree_now, agree_prev = np.sign(s5) == np.sign(p5), np.sign(prev[0]) == np.sign(prev[1])
        state = "CONFIRM" if agree_now or agree_prev else "DIVERGE"
        why = (f"SPY {'rose' if s5 > 0 else 'fell'} {abs(s5) * 100:.1f}% over 5 sessions while 20-day participation "
               f"{'rose' if p5 > 0 else 'fell'} {abs(p5) * 100:.0f} points. Two-session stick.")
    thrusts = b.index[b["zweig_thrust"].fillna(False)]
    return {"state": state, "why": why, "last": last,
            "last_thrust": thrusts[-1].date().isoformat() if len(thrusts) else None,
            "mcclellan_side": "positive" if _n(last.get("mcclellan")) > 0 else "negative"}


# ---- volatility & sentiment from index option chains -----------------------

def chain_vol_read(sym: str, contracts: List[dict], spot: float, hv20: float) -> Optional[Dict[str, Any]]:
    cons = [c for c in contracts if c and c["iv"] and c["strike"] and c["dte"] is not None and c["dte"] > 0]
    if not cons or not spot:
        return None
    by_exp: Dict[int, List[dict]] = {}
    for c in cons:
        by_exp.setdefault(c["dte"], []).append(c)
    atm = []
    for dte, legs in sorted(by_exp.items()):
        k = min({c["strike"] for c in legs}, key=lambda k: abs(k - spot))
        ivs = [c["iv"] for c in legs if c["strike"] == k]
        if ivs and abs(k - spot) / spot < 0.05:
            atm.append((dte, float(np.mean(ivs))))
    if not atm:
        return None

    def interp(target):
        xs = [d for d, _ in atm]
        if target <= xs[0]:
            return atm[0][1]
        if target >= xs[-1]:
            return atm[-1][1]
        for (d0, v0), (d1, v1) in zip(atm, atm[1:]):
            if d0 <= target <= d1:
                w0, w1 = v0 ** 2 * d0, v1 ** 2 * d1
                w = w0 + (w1 - w0) * (target - d0) / (d1 - d0)
                return math.sqrt(max(w, 0) / target)
        return atm[-1][1]

    iv30, iv90 = interp(30), interp(90)
    d30 = min(by_exp, key=lambda d: abs(d - 30))
    legs = by_exp[d30]
    puts = [c for c in legs if c["type"] == "put" and c["delta"] is not None]
    calls = [c for c in legs if c["type"] == "call" and c["delta"] is not None]
    skew = None
    if puts and calls:
        p25 = min(puts, key=lambda c: abs(c["delta"] + 0.25))
        c25 = min(calls, key=lambda c: abs(c["delta"] - 0.25))
        skew = p25["iv"] - c25["iv"]
    near = [c for c in cons if c["dte"] <= 45]
    pv = sum(c["volume"] or 0 for c in near if c["type"] == "put")
    cv = sum(c["volume"] or 0 for c in near if c["type"] == "call")
    po = sum(c["oi"] or 0 for c in near if c["type"] == "put")
    co = sum(c["oi"] or 0 for c in near if c["type"] == "call")
    front = atm[0]
    return {"sym": sym, "spot": spot, "iv30": iv30, "iv90": iv90, "term": iv30 / iv90 if iv90 else None,
            "skew25": skew, "pc_vol": pv / cv if cv else None, "pc_oi": po / co if co else None,
            "hv20": hv20, "vrp": iv30 - hv20 if hv20 else None, "front_dte": front[0], "front_iv": front[1],
            "move30_pct": iv30 * math.sqrt(30 / 365), "move7_pct": interp(7) * math.sqrt(7 / 365),
            "atm_curve": pd.DataFrame(atm, columns=["dte", "atm_iv"])}


def archive_vol(rows: List[Dict[str, Any]]) -> None:
    keep = ["sym", "iv30", "iv90", "term", "skew25", "pc_vol", "pc_oi", "hv20", "vrp"]
    new = pd.DataFrame([{**{k: r.get(k) for k in keep}, "date": last_completed_session().isoformat()} for r in rows])
    try:
        old = pd.read_csv(VOL_HISTORY)
    except Exception:
        old = pd.DataFrame()
    allr = pd.concat([old, new], ignore_index=True).drop_duplicates(["date", "sym"], keep="last")
    VOL_HISTORY.parent.mkdir(parents=True, exist_ok=True)
    tmp = VOL_HISTORY.with_suffix(".tmp")
    allr.to_csv(tmp, index=False)
    os.replace(tmp, VOL_HISTORY)


def vol_percentiles(sym: str, row: Dict[str, Any]) -> Dict[str, Any]:
    try:
        h = pd.read_csv(VOL_HISTORY)
        h = h[h["sym"] == sym]
    except Exception:
        h = pd.DataFrame()
    out = {"n_days": len(h)}
    for k in ("iv30", "term", "skew25", "pc_vol", "vrp"):
        if len(h) >= 20 and row.get(k) is not None:
            out[f"{k}_pct"] = float((h[k].dropna() <= row[k]).mean())
    return out


# ---- relative rotation, AVWAP, intermarket, correlation --------------------

def rrg(closes: pd.DataFrame, syms: List[str], bench: str = "SPY", smooth: int = 10, base: int = 63,
        mom: int = 5, tail: int = 8) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """JdK-style reconstruction: RS-Ratio = 100 x EMA10(RS) / its 63-day mean;
    RS-Momentum = 100 x RS-Ratio / RS-Ratio 5 sessions ago. Not the Optuma indicator."""
    rows, tails = [], []
    for s in syms:
        if s not in closes or bench not in closes:
            continue
        rs = (closes[s] / closes[bench]).dropna()
        if len(rs) < base + mom + tail:
            continue
        sm = rs.ewm(span=smooth, adjust=False).mean()
        ratio = 100 * sm / sm.rolling(base).mean()
        momentum = 100 * ratio / ratio.shift(mom)
        r, m_ = float(ratio.iloc[-1]), float(momentum.iloc[-1])
        quad = ("LEADING" if r >= 100 and m_ >= 100 else "WEAKENING" if r >= 100 else
                "LAGGING" if m_ < 100 else "IMPROVING")
        rows.append({"symbol": s, "rs_ratio": r, "rs_mom": m_, "quadrant": quad})
        t = pd.DataFrame({"rs_ratio": ratio.iloc[-tail:], "rs_mom": momentum.iloc[-tail:]})
        t["symbol"], t["step"] = s, range(len(t))
        tails.append(t)
    return pd.DataFrame(rows), (pd.concat(tails, ignore_index=True) if tails else pd.DataFrame())


def avwap_distance(df: pd.DataFrame, look: int = 63) -> Tuple[float, str]:
    """Distance from the anchored VWAP started at the more recent 63-day closing extreme."""
    d = df.dropna(subset=["close"]).iloc[-look:]
    if len(d) < 10:
        return float("nan"), ""
    i_hi, i_lo = int(np.argmax(d["close"].to_numpy())), int(np.argmin(d["close"].to_numpy()))
    a = max(i_hi, i_lo)
    seg = d.iloc[a:]
    tp = seg["vwap"].where(seg["vwap"].notna(), (seg["high"] + seg["low"] + seg["close"]) / 3)
    av = float((tp * seg["volume"]).sum() / max(seg["volume"].sum(), 1.0))
    return float(d["close"].iloc[-1] / av - 1), d.index[a].date().isoformat()


def intermarket_table(closes: pd.DataFrame) -> pd.DataFrame:
    rows = []
    for name, a, b, read in INTERMARKET:
        if a not in closes or b not in closes:
            continue
        r = (closes[a] / closes[b]).dropna()
        if len(r) < 70:
            continue
        sma50 = r.rolling(50).mean()
        ch20, ch63 = float(r.iloc[-1] / r.iloc[-21] - 1), float(r.iloc[-1] / r.iloc[-64] - 1)
        above = bool(r.iloc[-1] > sma50.iloc[-1])
        trend = ("rising" if above and ch20 > 0 else "falling" if (not above and ch20 < 0) else "mixed")
        rows.append({"ratio": name, "legs": f"{a} / {b}", "chg_20d": ch20, "chg_63d": ch63, "above_50d": above,
                     "trend": trend, "read": read})
    return pd.DataFrame(rows)


def correlation_regime(closes: pd.DataFrame, syms: List[str] = SECTOR_ETFS, win: int = 63) -> Optional[Dict[str, Any]]:
    have = [s for s in syms if s in closes]
    if len(have) < 5:
        return None
    r = np.log(closes[have]).diff().dropna(how="all")
    vals = []
    idx = r.index[win:]
    for i in range(win, len(r)):
        c = r.iloc[i - win:i].corr().to_numpy()
        m = c[np.triu_indices_from(c, 1)]
        vals.append(np.nanmean(m))
    s = pd.Series(vals, index=idx)
    if s.empty:
        return None
    pct = float((s.iloc[-504:] <= s.iloc[-1]).mean())
    label = ("HIGH: macro-driven tape, diversification thin" if pct >= 0.8 else
             "LOW: dispersion, stock selection matters more" if pct <= 0.2 else "NORMAL")
    return {"now": float(s.iloc[-1]), "pct": pct, "label": label, "series": s}


# ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════
#  INTERMARKET (Market > Intermarket): John Murphy's three questions, answered with ETFs and tested on your setups.
#    1 · What is confirming the move? Index confirmation (the leaders at highs while small caps, transports and the
#        equal-weight index lag = narrow), after Murphy, Trading with Intermarket Analysis (Wiley 2013); the lab's
#        Dow Theory (dow_theory, Market > Narrative charts) as a daily state; and SentimenTrader's test of the
#        Industrials/Transports divergence on the loaded history. Murphy's relationship map stays on Narrative charts.
#    2 · Where is capital rotating? A trend board across asset classes and sectors after AQR's time-series momentum
#        (Moskowitz, Ooi & Pedersen 2012, JFE; Hurst, Ooi & Pedersen, "A Century of Evidence on Trend-Following") with
#        12-1 month momentum beside it (Asness, Moskowitz & Pedersen 2013, "Value and Momentum Everywhere"); and whether
#        the tape matches the growth/inflation quad (Hedgeye's quads; the published playbooks summarised by Fidenza;
#        Ilmanen, Maloney & Ross 2014 on assets across growth and inflation regimes).
#    3 · Where is risk building? Mechanical positioning: a trend-follower (CTA) proxy after Macrosynergy's replication
#        (16/32/52-week momentum over 90-day volatility, capped), and a 10% vol-control fund's equity weight (target /
#        the higher of 20- and 60-day realized vol, as in Acadian's 2015 note), with what each would sell on a shock.
#    4 · Does it matter for your setups? Each read is a Setup ledger split, and the breakout-type trades are read by state.
#  All causal: rolling windows only, each day from data up to that close.
# ═══════════════════════════════════════════════════════════════════════════════════════════════════════════════════
IMK_TREND_LB = (80, 160, 252)               # ~16, 32 and 52 weeks, in sessions
IMK_VOL_LB = 90
IMK_ASSETS = [("US large caps", "SPY", "Stocks"), ("Nasdaq 100", "QQQ", "Stocks"), ("Small caps", "IWM", "Stocks"),
              ("Developed ex-US", "EFA", "Stocks"), ("Emerging markets", "EEM", "Stocks"),
              ("Long Treasuries", "TLT", "Bonds"), ("7-10y Treasuries", "IEF", "Bonds"), ("TIPS", "TIP", "Bonds"),
              ("High yield", "HYG", "Credit"), ("Investment grade", "LQD", "Credit"),
              ("US dollar", "UUP", "Currency"), ("Japanese yen", "FXY", "Currency"),
              ("Gold", "GLD", "Commodities"), ("Broad commodities", "DBC", "Commodities"), ("Crude oil", "USO", "Commodities"),
              ("Copper", "CPER", "Commodities")]
IMK_SECTORS = [("Technology", "XLK"), ("Semiconductors", "SMH"), ("Communication", "XLC"), ("Discretionary", "XLY"),
               ("Financials", "XLF"), ("Industrials", "XLI"), ("Materials", "XLB"), ("Energy", "XLE"), ("Health care", "XLV"),
               ("Staples", "XLP"), ("Utilities", "XLU"), ("Real estate", "XLRE")]
IMK_DEFENSIVE, IMK_CYCLICAL = ("XLP", "XLU", "XLV"), ("XLY", "XLK", "XLI", "XLF", "SMH")
IMK_LEADERS, IMK_LEGS = ("SPY", "QQQ"), ("IWM", "IYT", "RSP")
IMK_HI_LEAD, IMK_HI_LEG = 0.03, 0.08        # 'at the high' for a leader; 'healthy' for a breadth leg (and over its 200-day)
IMK_QUAD_PLAY = {   # what tends to lead and lag in each market-implied quad (Hedgeye's quads as published; Fidenza's table)
    "GOLDILOCKS": (("SPY", "QQQ", "HYG", "EEM", "GLD"), ("DBC", "USO", "UUP")),
    "REFLATION": (("SPY", "IWM", "DBC", "USO", "CPER", "EEM"), ("TLT", "IEF", "UUP")),
    "STAGFLATION SCARE": (("DBC", "USO", "UUP"), ("SPY", "QQQ", "IWM", "TLT")),
    "DEFLATION SCARE": (("TLT", "IEF", "UUP", "GLD", "XLP", "XLU", "XLV"), ("IWM", "QQQ", "DBC", "USO", "HYG", "EEM")),
}
IMK_QUAD_BAR = 0.30
IMK_VC_TARGET, IMK_VC_CAP = 0.10, 1.5
IMK_CONFIRM_ORDER = ["CONFIRMED", "MIXED", "NARROW", "BROAD WEAKNESS"]
IMK_FLOW_ORDER = ["STACKED", "NORMAL", "LIGHT", "UNWINDING"]
IMK_QUADTAPE_ORDER = ["CONFIRMS", "MIXED", "CONTRADICTS"]
IMK_LEDGER_CAT = ["imk_confirm", "imk_dow", "imk_flow", "imk_quad_tape", "imk_def"]
IMK_LEDGER_NUM = ["imk_cta", "imk_vc", "imk_def_gap", "imk_quad_gap"]
IMK_BURST_TYPES = ("Breakout", "Tight base / launch pad", "Gap / episodic pivot")
IMK_SHOCKS = (-0.02, -0.03, -0.05)


def imk_trend(c: pd.Series, lbs: Sequence[int] = IMK_TREND_LB, vol_lb: int = IMK_VOL_LB) -> pd.Series:
    """Trend-follower signal in [-1, 1] (after Macrosynergy's CTA replication, in daily terms): for each lookback, the
    lookback's log return in units of its own volatility (the 90-day daily vol x sqrt(lookback)), capped at +-1, then
    the average over the lookbacks. +1 = every lookback in a strong uptrend: what a trend follower would hold fully long."""
    lc = np.log(c.astype(float).where(c > 0))
    r = lc.diff()
    vol = r.rolling(vol_lb, min_periods=vol_lb // 2).std()
    parts = []
    for L in lbs:
        with np.errstate(invalid="ignore", divide="ignore"):
            parts.append(((lc - lc.shift(L)) / (vol * math.sqrt(L))).clip(-1, 1))
    return pd.concat(parts, axis=1).mean(axis=1, skipna=False)


def imk_trend_shocked(c: pd.Series, shock: float, lbs: Sequence[int] = IMK_TREND_LB, vol_lb: int = IMK_VOL_LB) -> float:
    """The trend signal after one more session that closes `shock` (e.g. -0.03) from today's close: the trend
    followers' position after a down day of that size."""
    c2 = c.astype(float).dropna()
    if len(c2) < max(lbs) + 2:
        return np.nan
    c2 = pd.concat([c2, pd.Series([c2.iloc[-1] * (1 + shock)], index=[c2.index[-1] + pd.Timedelta(days=1)])])
    return float(imk_trend(c2, lbs, vol_lb).iloc[-1])


def imk_volctl(c: pd.Series, target: float = IMK_VC_TARGET, cap: float = IMK_VC_CAP) -> pd.Series:
    """A vol-control fund's equity weight: target vol over the higher of 20- and 60-day realized vol (log returns,
    annualised by 252), capped (Acadian 2015). Falls when realized vol rises, which is when it sells."""
    r = np.log(c.astype(float)).diff()
    rv = pd.concat([r.rolling(20, min_periods=15).std(), r.rolling(60, min_periods=40).std()], axis=1).max(axis=1) * math.sqrt(252)
    return (target / rv.where(rv > 0)).clip(upper=cap)


def imk_volctl_shocked(c: pd.Series, shock: float) -> float:
    c2 = c.astype(float).dropna()
    c2 = pd.concat([c2, pd.Series([c2.iloc[-1] * (1 + shock)], index=[c2.index[-1] + pd.Timedelta(days=1)])])
    return float(imk_volctl(c2).iloc[-1])


def imk_frame(closes: pd.DataFrame, quad: Optional[pd.Series] = None) -> pd.DataFrame:
    """The daily intermarket reads, each from data up to that close."""
    c = closes.astype(float)
    f = pd.DataFrame(index=c.index)
    hi = c.rolling(252, min_periods=200).max()
    s200 = c.rolling(200, min_periods=150).mean()
    off = c / hi - 1
    # 1 · confirmation
    if all(t in c for t in IMK_LEADERS + IMK_LEGS):
        lead_hi = (off[list(IMK_LEADERS)] >= -IMK_HI_LEAD).any(axis=1)
        healthy = ((off[list(IMK_LEGS)] >= -IMK_HI_LEG) & (c[list(IMK_LEGS)] > s200[list(IMK_LEGS)])).sum(axis=1)
        below = (c[list(IMK_LEGS)] < s200[list(IMK_LEGS)]).sum(axis=1)
        spy_weak = (off["SPY"] <= -0.10) | (c["SPY"] < s200["SPY"])
        known = off[list(IMK_LEADERS + IMK_LEGS)].notna().all(axis=1) & s200[list(IMK_LEGS)].notna().all(axis=1)
        raw = np.select([spy_weak & (below >= 2), lead_hi & (healthy >= 2), lead_hi & (healthy <= 1)],
                        ["BROAD WEAKNESS", "CONFIRMED", "NARROW"], "MIXED")
        f["imk_confirm"] = np.where(known, raw, "")
        f["imk_legs_ok"] = healthy.where(known)
    dw = dow_theory(c)                                     # the lab's Dow Theory (Narrative charts), as a daily state
    if dw is not None:
        tr_ = dw["trend"].reindex(c.index)
        f["imk_dow"] = np.where(tr_.isin(["UP", "DOWN"]), "PRIMARY " + tr_.fillna("").astype(str), "")
    # 2 · rotation
    T = pd.DataFrame({t: imk_trend(c[t]) for t in set(t for _, t, _ in IMK_ASSETS) | set(t for _, t in IMK_SECTORS) if t in c})
    if all(t in T for t in IMK_DEFENSIVE + IMK_CYCLICAL):
        gap = T[list(IMK_DEFENSIVE)].mean(axis=1) - T[list(IMK_CYCLICAL)].mean(axis=1)
        f["imk_def_gap"] = gap
        f["imk_def"] = np.where(gap.isna(), "", np.where(gap >= 0.25, "DEFENSIVES LEAD", np.where(gap <= -0.25, "CYCLICALS LEAD", "MIXED")))
    if quad is not None:
        q = quad.reindex(c.index).fillna("").astype(str)
        gq = pd.Series(np.nan, index=c.index)
        for name, (lead, lag) in IMK_QUAD_PLAY.items():
            ld, lg = [t for t in lead if t in T], [t for t in lag if t in T]
            if ld and lg:
                m = (q == name).to_numpy()
                gq[m] = (T[ld].mean(axis=1) - T[lg].mean(axis=1))[m]
        f["imk_quad_gap"] = gq
        f["imk_quad_tape"] = np.where(gq.isna(), "", np.where(gq >= IMK_QUAD_BAR, "CONFIRMS",
                                                              np.where(gq <= -IMK_QUAD_BAR, "CONTRADICTS", "MIXED")))
    # 3 · risk building
    if "SPY" in c:
        cta, vc = imk_trend(c["SPY"]), imk_volctl(c["SPY"])
        f["imk_cta"], f["imk_vc"] = cta, vc
        vc_pct = vc.rolling(756, min_periods=252).rank(pct=True)
        f["imk_vc_pct"] = vc_pct
        unwind = (cta - cta.shift(10) <= -0.5) | (vc / vc.shift(10) - 1 <= -0.30)
        stacked = (cta >= 0.75) & (vc_pct >= 0.80)
        light = (cta <= 0.0) | (vc_pct <= 0.20)
        f["imk_flow"] = np.where(cta.isna() | vc_pct.isna(), "", np.select([unwind, stacked, light], ["UNWINDING", "STACKED", "LIGHT"], "NORMAL"))
    return f


def imk_board(closes: pd.DataFrame, items: Sequence[Tuple[str, str, str]], look_back: int = 20) -> pd.DataFrame:
    """One row per market: trend now and `look_back` sessions ago, the change (rotation), 12-1 month momentum (AQR's
    cross-sectional measure: the 12-month return skipping the last month), and their rank."""
    rows = []
    for name, t, grp in items:
        if t not in closes:
            continue
        x = closes[t].astype(float).dropna()
        if len(x) < max(IMK_TREND_LB) + look_back + 5:
            continue
        tr = imk_trend(x)
        m121 = float(x.iloc[-22] / x.iloc[-253] - 1) if len(x) > 253 else np.nan
        rows.append({"market": name, "etf": t, "group": grp, "trend": float(tr.iloc[-1]), "trend_before": float(tr.iloc[-1 - look_back]),
                     "change": float(tr.iloc[-1] - tr.iloc[-1 - look_back]), "mom_12_1": m121,
                     "r_1m": float(x.iloc[-1] / x.iloc[-22] - 1)})
    B = pd.DataFrame(rows)
    if len(B):
        B["rank"] = B["mom_12_1"].rank(ascending=False, method="min")
        B = B.sort_values("trend", ascending=False).reset_index(drop=True)
    return B


def imk_dow_record(closes: pd.DataFrame, horizon: int = 63) -> pd.DataFrame:
    """SentimenTrader's test on this history: after a Dow Industrials close at a 52-week high while the Transports sit
    8%+ under theirs (first day of each episode), what SPY did over the next `horizon` sessions, against every day."""
    if "DIA" not in closes or "IYT" not in closes or "SPY" not in closes:
        return pd.DataFrame()
    c = closes[["DIA", "IYT", "SPY"]].astype(float).dropna()
    off = c / c.rolling(252, min_periods=200).max() - 1
    sig = (off["DIA"] >= -0.01) & (off["IYT"] <= -IMK_HI_LEG)
    first = sig & ~sig.shift(1, fill_value=False).rolling(20, min_periods=1).max().astype(bool)
    fwd = c["SPY"].shift(-horizon) / c["SPY"] - 1
    rows = []
    for lab_, m in (("Transports not confirming (first day)", first), ("Every day", off["DIA"].notna())):
        x = fwd[m].dropna()
        rows.append({"when": lab_, "cases": len(x), "spy_fwd": float(x.mean()) if len(x) else np.nan,
                     "up_share": float((x > 0).mean()) if len(x) else np.nan})
    return pd.DataFrame(rows)


def imk_setups(ev: Optional[pd.DataFrame], f: pd.DataFrame, horizon: int = 10) -> pd.DataFrame:
    """The ledger's breakout-type trades (Breakout, tight base, gap / episodic pivot), read by each intermarket state on
    the signal day: trades, E[R] averaged by date with a Newey-West t, win rate, against all of them."""
    if ev is None or not len(ev) or not len(f):
        return pd.DataFrame()
    d = ev[(ev["status"] == 0) & ev["setup"].map(lambda s_: AM_TYPES.get(str(s_), "") in IMK_BURST_TYPES)]
    if not len(d):
        return pd.DataFrame()
    dt = pd.DatetimeIndex(d["date"])
    rows = []
    def add(read, state, g):
        if len(g) < 5:
            return
        x = g.groupby("date")["r"].mean().sort_index().to_numpy()
        mu, se = lg_nw(x, horizon)
        rows.append({"read": read, "state": state, "trades": len(g), "dates": len(x), "er": mu,
                     "t": mu / se if se and np.isfinite(se) and se > 0 else np.nan, "win": float((g["r"] > 0).mean())})
    add("All breakout-type trades", "all", d)
    for col, lab_ in (("imk_confirm", "Index confirmation"), ("imk_flow", "Mechanical positioning"),
                      ("imk_quad_tape", "Tape vs the quad"), ("imk_def", "Defensive vs cyclical leadership"),
                      ("imk_dow", "Dow Theory")):
        if col not in f:
            continue
        st_ = f[col].reindex(dt, method="ffill").fillna("").to_numpy()
        for s_ in [v for v in pd.unique(st_) if v]:
            add(lab_, s_, d[st_ == s_])
    return pd.DataFrame(rows)


def imk_page(closes: pd.DataFrame, nar_f: Optional[pd.DataFrame] = None) -> Dict[str, Any]:
    quad = nar_f["nar_quad"] if nar_f is not None and "nar_quad" in nar_f else None
    f = imk_frame(closes, quad)
    row = f.iloc[-1] if len(f) else pd.Series(dtype=object)
    spy = closes["SPY"].astype(float).dropna() if "SPY" in closes else None
    shocks = []
    if spy is not None and len(spy) > max(IMK_TREND_LB) + 5:
        cta0, vc0 = float(f["imk_cta"].iloc[-1]), float(f["imk_vc"].iloc[-1])
        for s_ in IMK_SHOCKS:
            c1, v1 = imk_trend_shocked(spy, s_), imk_volctl_shocked(spy, s_)
            shocks.append({"shock": s_, "cta_after": c1, "cta_change": c1 - cta0, "vc_after": v1, "vc_change": v1 / vc0 - 1 if vc0 > 0 else np.nan})
    q_now = str(quad.iloc[-1]) if quad is not None and len(quad) else ""
    off = (closes / closes.rolling(252, min_periods=200).max() - 1).iloc[-1]
    s200 = closes.rolling(200, min_periods=150).mean().iloc[-1]
    legs = pd.DataFrame([{"index": nm, "etf": t, "role": role, "off_high": float(off[t]), "over_200d": bool(closes[t].iloc[-1] > s200[t]),
                          "r_1m": float(closes[t].iloc[-1] / closes[t].iloc[-22] - 1)}
                         for nm, t, role in (("S&P 500", "SPY", "leader"), ("Nasdaq 100", "QQQ", "leader"), ("Russell 2000", "IWM", "breadth leg"),
                                             ("Transports", "IYT", "breadth leg"), ("Equal-weight S&P", "RSP", "breadth leg"),
                                             ("Dow Industrials", "DIA", "Dow Theory")) if t in closes and np.isfinite(off.get(t, np.nan))])
    return {"f": f, "row": row, "legs": legs, "dow_now": dow_theory(closes), "assets": imk_board(closes, IMK_ASSETS),
            "sectors": imk_board(closes, [(n_, t, "Sector") for n_, t in IMK_SECTORS]), "shocks": pd.DataFrame(shocks),
            "quad": q_now, "dow": imk_dow_record(closes), "asof": closes.index[-1]}


IMK_GUIDE = """
**Where it comes from.** John Murphy's *Trading with Intermarket Analysis* (2013): bonds, the dollar, commodities and
stocks move together in recognisable ways, so look past the one chart and ask what confirms the move, where capital
is rotating and where risk is building. AQR's trend research, Hedgeye's quads and the work on systematic flows give
those questions numbers.

**1 · Confirmation.**
- *Index confirmation.* CONFIRMED: SPY or QQQ within 3% of its 52-week high, and at least two of IWM, IYT (transports)
  and RSP (equal weight) within 8% of theirs and over their 200-day. NARROW: a leader at its high with one or none of
  them healthy, the pattern Murphy and others warn about. BROAD WEAKNESS: SPY 10%+ off its high or under its 200-day,
  with two of them under their 200-day.
- *Dow Theory* is the lab's own (Market > Narrative charts): the primary trend is the last 52-week high or low that
  Industrials and Transports confirmed together. Here it becomes a daily state the ledger can split on. Beside it,
  SentimenTrader's test: Industrials at a 52-week high with Transports 8%+ under theirs. Their decades of data found
  that divergence was *not* reliably bearish; the table shows what it did on the loaded history.
- *Murphy's relationships* (dollar vs commodities, bonds vs stocks...) are mapped month by month on Narrative charts.

**2 · Rotation.** A trend score from -1 to +1 per market, the way a trend follower would hold it: the return over
16, 32 and 52 weeks, each in units of its own volatility, capped, then averaged (after Macrosynergy's CTA
replication; AQR's time-series momentum underneath). The change over 20 sessions is the rotation. 12-1 month momentum
(AQR's cross-sectional measure) ranks them. *Tape vs the quad*: the lab's market-implied quad (Market > Narratives)
names what should lead (e.g. bonds, the dollar, gold and defensives in a deflation scare); CONFIRMS when those trend
0.3 or more above what should lag.

**3 · Risk building.** Two kinds of investor sell because of price and volatility, not news.
- *Trend followers (CTA proxy).* The same trend score on SPY: +1 is fully long. The table shows the position after a
  2%, 3% and 5% down day, which is how much a trend book would sell.
- *Vol-control funds.* Equity weight = 10% target / the higher of 20- and 60-day realized vol (Acadian's example),
  capped at 1.5. One violent day lifts realized vol and cuts the weight: the table shows by how much.
- STACKED = trend followers near fully long and vol-control weight in its top fifth (quiet markets). Little room to
  buy more and a lot to sell on a shock. UNWINDING = either has dropped sharply in 10 sessions. LIGHT = little left to
  sell. These are proxies from prices, not anyone's actual book.

**4 · Your setups.** Every read is a Setup ledger split (Market > Intermarket in the split list), and the table at
the end reads the ledger's breakout-type trades (breakouts, tight bases, gaps and episodic pivots) by each state.
That is the test: if the breakouts' E[R] doesn't change with a read, the read is commentary, not a filter.
"""


def _imk_board_chart(B: pd.DataFrame, title: str):
    d = B.copy()
    order = list(d["market"])
    y = alt.Y("market:N", sort=order, title=None, axis=alt.Axis(labelLimit=200, labelOverlap=False))
    xs = alt.Scale(domain=[-1, 1])
    rule = alt.Chart(d).mark_rule(color=C_MUTED, strokeWidth=1.5).encode(x=alt.X("trend_before:Q", scale=xs, title="trend score (-1 to +1)"), x2="trend:Q", y=y)
    before = alt.Chart(d).mark_circle(size=55, color=C_MUTED, opacity=0.8).encode(x=alt.X("trend_before:Q", scale=xs), y=y)
    now = alt.Chart(d).mark_circle(size=150, opacity=1).encode(
        x=alt.X("trend:Q", scale=xs), y=y,
        color=alt.Color("trend:Q", scale=alt.Scale(domain=[-1, 0, 1], range=[C_RED, "#5b5a55", C_GREEN]), legend=None),
        tooltip=["market", "etf", alt.Tooltip("trend:Q", format="+.2f"), alt.Tooltip("trend_before:Q", title="20 sessions ago", format="+.2f"),
                 alt.Tooltip("mom_12_1:Q", title="12-1 month", format="+.1%"), alt.Tooltip("r_1m:Q", title="last month", format="+.1%")])
    zero = alt.Chart(pd.DataFrame({"x": [0]})).mark_rule(color=C_MUTED, strokeDash=[3, 3]).encode(x="x:Q")
    return alt.layer(zero, rule, before, now).properties(title=title)


def render_imk(cfg, imk: Optional[Dict[str, Any]], err: Optional[str]) -> None:
    ss = st.session_state
    P_ = st.column_config.NumberColumn
    sec("Intermarket: what confirms the move, where capital is rotating, where risk is building (Murphy)")
    if imk is None:
        warnbox(f"Intermarket: {err or 'no benchmark history loaded'}")
        return
    r, f = imk["row"], imk["f"]
    tone = {"CONFIRMED": "good", "NARROW": "bad", "BROAD WEAKNESS": "bad", "STACKED": "bad", "UNWINDING": "bad", "CONFIRMS": "good",
            "CONTRADICTS": "bad", "LIGHT": "good"}
    conf, flow, qt = str(r.get("imk_confirm") or "n/a"), str(r.get("imk_flow") or "n/a"), str(r.get("imk_quad_tape") or "n/a")
    kpi_row([kpi_html("Is the move confirmed?", conf, f"{int(_n(r.get('imk_legs_ok'), 0))} of 3 breadth legs healthy (IWM, IYT, RSP)", tone.get(conf, "")),
             kpi_html("Dow Theory", str(r.get("imk_dow") or "n/a"), ((imk.get("dow_now") or {}).get("flag") or "Industrials and Transports confirm each other")[:90]),
             kpi_html("Rotation", str(r.get("imk_def") or "n/a"), f"defensives minus cyclicals {_n(r.get('imk_def_gap'), np.nan):+.2f}"),
             kpi_html("Tape vs the quad", qt, f"{imk['quad'].lower() or 'no quad'}; gap {_n(r.get('imk_quad_gap'), np.nan):+.2f}", tone.get(qt, "")),
             kpi_html("Mechanical positioning", flow, f"trend followers {_n(r.get('imk_cta'), np.nan):+.2f}; vol-control weight "
                      f"{_n(r.get('imk_vc'), np.nan):.2f} ({_n(r.get('imk_vc_pct'), np.nan):.0%} pct)", tone.get(flow, ""))])
    sec("1 · What is confirming the move?")
    c = st.columns([1.2, 1.0])
    with c[0]:
        Lg = imk["legs"]
        if len(Lg):
            show_df(Lg.assign(off_high=Lg["off_high"] * 100, r_1m=Lg["r_1m"] * 100),
                    column_config={"off_high": P_("from 52-week high", format="%+.1f%%"), "over_200d": st.column_config.CheckboxColumn("over its 200-day"),
                                   "r_1m": P_("last month", format="%+.1f%%")})
        cf = f[["imk_confirm"]].iloc[-504:].reset_index() if "imk_confirm" in f else pd.DataFrame()
        if len(cf):
            cf = cf.rename(columns={cf.columns[0]: "date"})
            cf = cf[cf["imk_confirm"] != ""]
            show_chart(_alt(alt.Chart(cf).mark_tick(thickness=3, size=34, opacity=0.9).encode(
                x=alt.X("date:T", title=None),
                color=alt.Color("imk_confirm:N", scale=alt.Scale(domain=IMK_CONFIRM_ORDER, range=[C_GREEN, C_MUTED, C_ACCENT, C_RED]),
                                legend=alt.Legend(orient="bottom", title=None)),
                tooltip=[alt.Tooltip("date:T"), "imk_confirm"]).properties(title="Index confirmation, last two years"), 90))
    with c[1]:
        dw = imk.get("dow_now")
        if dw is not None:
            note(f"Dow Theory primary trend: {dw['now']}" + (f", confirmed {dw['since'].date()}" if dw.get("since") is not None else "")
                 + (f". {dw['flag']}." if dw.get("flag") else ". No unconfirmed high or low in the last 20 sessions.")
                 + " The full read and chart are on Market > Narrative charts.")
        D = imk["dow"]
        if len(D):
            show_df(D.assign(spy_fwd=D["spy_fwd"] * 100, up_share=D["up_share"] * 100),
                    column_config={"when": st.column_config.TextColumn("SPY over the next 63 sessions", width="medium"),
                                   "cases": P_("cases", format="%d"), "spy_fwd": P_("average", format="%+.1f%%"), "up_share": P_("up", format="%.0f%%")})
            note("SentimenTrader's test (Industrials at a 52-week high, Transports 8%+ under theirs). Over decades it was not "
                 "reliably bearish; this is the loaded history only, so few cases.")
        note("Murphy's relationships (dollar vs commodities, bonds vs stocks and the rest) are mapped month by month on "
             "Market > Narrative charts.")
    sec("2 · Where is capital rotating?")
    c = st.columns(2)
    A, Sx = imk["assets"], imk["sectors"]
    with c[0]:
        if len(A):
            show_chart(_alt(_imk_board_chart(A, "Asset classes: grey = 20 sessions ago, colour = now"), 34 * len(A) + 40))
    with c[1]:
        if len(Sx):
            show_chart(_alt(_imk_board_chart(Sx, "Sectors: grey = 20 sessions ago, colour = now"), 34 * len(Sx) + 40))
    if imk["quad"] and imk["quad"] in IMK_QUAD_PLAY and len(A):
        lead, lag = IMK_QUAD_PLAY[imk["quad"]]
        tr = pd.concat([A.set_index("etf")["trend"], Sx.set_index("etf")["trend"]]) if len(Sx) else A.set_index("etf")["trend"]
        fmt = lambda ts: ", ".join(f"{t} {tr[t]:+.2f}" for t in ts if t in tr)
        note(f"The market-implied quad is {imk['quad'].lower()}. Should lead: {fmt(lead)}. Should lag: {fmt(lag)}. "
             f"The tape {qt.lower()} it.")
    with st.expander("The trend board as a table"):
        if len(A):
            show_df(pd.concat([A, Sx], ignore_index=True)[["market", "etf", "group", "trend", "trend_before", "change", "mom_12_1", "r_1m", "rank"]],
                    column_config={"trend": P_("trend", format="%+.2f"), "trend_before": P_("20 sessions ago", format="%+.2f"),
                                   "change": P_("change", format="%+.2f"), "mom_12_1": P_("12-1 month", format="%+.1%"),
                                   "r_1m": P_("last month", format="%+.1%"), "rank": P_("12-1 rank", format="%d")})
    sec("3 · Where is risk building?")
    c = st.columns([1.0, 1.2])
    with c[0]:
        Sh = imk["shocks"]
        if len(Sh):
            Sh = Sh.assign(shock=Sh["shock"] * 100, vc_change=Sh["vc_change"] * 100)
            show_df(Sh, column_config={"shock": P_("SPY down day", format="%.0f%%"), "cta_after": P_("trend followers after", format="%+.2f"),
                                       "cta_change": P_("their change", format="%+.2f"), "vc_after": P_("vol-control weight after", format="%.2f"),
                                       "vc_change": P_("their change", format="%+.0f%%")})
            note("What the price-driven books would hold after one more down day of that size, from today's close. A large "
                 "change means mechanical selling is waiting below; a small one means it's mostly done. When realized vol is "
                 "already high, a small down day can lower it, so the vol-control weight can rise.")
    with c[1]:
        g = f[["imk_cta", "imk_vc"]].iloc[-504:].dropna().reset_index()
        if len(g):
            g = g.rename(columns={g.columns[0]: "date"}).melt("date", var_name="book", value_name="v")
            g["book"] = g["book"].map({"imk_cta": "Trend followers (-1 to +1)", "imk_vc": "Vol-control weight (0 to 1.5)"})
            show_chart(_alt(alt.Chart(g).mark_line(strokeWidth=1.6).encode(
                x=alt.X("date:T", title=None), y=alt.Y("v:Q", title=None),
                color=alt.Color("book:N", scale=alt.Scale(range=[C_ACCENT, C_BLUE]), legend=alt.Legend(orient="bottom", title=None)),
                tooltip=[alt.Tooltip("date:T"), "book", alt.Tooltip("v:Q", format=".2f")]).properties(title="Mechanical equity positioning, last two years"), 230))
    note("Credit (Market > Climate, credit canary), the correlation regime (Market > CMT) and carry (Market > Narratives) "
         "are the other places risk shows up first; they aren't repeated here.")
    if lab_cloud():
        with st.expander("How the intermarket tab works"):
            st.markdown(IMK_GUIDE)
        return
    sec("4 · Does it matter for your setups?")
    res = ss.get("lg_res")
    run = (res or {}).get("runs", {}).get("list") if res else None
    if run is None or run.get("ev") is None or not len(run["ev"]):
        note("Build the Setup ledger (Stocks > Setup ledger) and this reads its breakout-type trades by each state here. "
             "The ledger's split list also has every read under 'Intermarket'.")
    else:
        T = imk_setups(run["ev"], f, int(run.get("prm", {}).get("horizon", 10)))
        if len(T):
            show_df(T, height=min(520, 40 + 35 * len(T)),
                    column_config={"read": st.column_config.TextColumn("read", width="medium"), "state": st.column_config.TextColumn("state on the signal day"),
                                   "trades": P_("trades", format="%d"), "dates": P_("dates", format="%d"), "er": P_("E[R]", format="%+.2f"),
                                   "t": P_("t", format="%+.1f"), "win": P_("win rate", format="percent")})
            note("Breakouts, tight bases, gaps and episodic pivots from the ledger, E[R] averaged by date with a Newey-West t. "
                 "A read earns a place as a filter only if its states differ by more than noise; for a proper test with "
                 "the multiple-testing bar, split the ledger by it.")
        else:
            note("The ledger has no breakout-type trades yet: add the Trend, TraderLion, Zanger, Gap or EP families.")
    with st.expander("How the intermarket tab works"):
        st.markdown(IMK_GUIDE)


