# ---- filings & flows (all included in Massive Stocks Starter) --------------

def _latest(rows: List[dict], datekey: str) -> List[dict]:
    return sorted([r for r in rows if r.get(datekey)], key=lambda r: r[datekey], reverse=True)


def fetch_short(tk: str, key: str) -> Dict[str, Any]:
    si = _latest(massive_get_all("/stocks/v1/short-interest",
                                 {"ticker": tk, "sort": "settlement_date.desc", "limit": 6}, key, max_pages=1),
                 "settlement_date")
    sv = _latest(massive_get_all("/stocks/v1/short-volume",
                                 {"ticker": tk, "date.gte": (date.today() - timedelta(days=45)).isoformat(),
                                  "limit": 1000}, key, max_pages=2), "date")
    out: Dict[str, Any] = {}
    if si:
        out.update({"short_interest": si[0].get("short_interest"), "days_to_cover": si[0].get("days_to_cover"),
                    "si_date": si[0].get("settlement_date")})
        if len(si) > 1 and si[1].get("short_interest"):
            out["si_change"] = _n(si[0].get("short_interest")) / _n(si[1].get("short_interest"), np.nan) - 1
    if sv:
        ratios = [_n(r.get("short_volume_ratio"), np.nan) for r in sv]
        out["short_vol_ratio_5d"] = float(np.nanmean(ratios[:5])) / 100.0
        out["short_vol_ratio_20d"] = float(np.nanmean(ratios[:20])) / 100.0
    return out


def fetch_overview(tk: str, key: str) -> Dict[str, Any]:
    rows = massive_get_all(f"/v3/reference/tickers/{tk}", {}, key, max_pages=1)
    r = rows[0] if rows else {}
    return {"market_cap": r.get("market_cap"), "shares_out": r.get("share_class_shares_outstanding")
            or r.get("weighted_shares_outstanding"), "sic": r.get("sic_description"), "cik": r.get("cik"),
            "exchange": r.get("primary_exchange"), "list_date": r.get("list_date")}


def fetch_news(tk: str, key: str, days: int = 14) -> Dict[str, Any]:
    rows = massive_get_all("/v2/reference/news", {"ticker": tk, "limit": 50, "order": "desc", "sort": "published_utc",
                                                  "published_utc.gte": (date.today() - timedelta(days=days)).isoformat()},
                           key, max_pages=1)
    pos = neg = neu = 0
    for r in rows:
        for ins in r.get("insights") or []:
            if (ins.get("ticker") or "").upper() == tk:
                s = (ins.get("sentiment") or "").lower()
                pos += s == "positive"
                neg += s == "negative"
                neu += s == "neutral"
    n = pos + neg + neu
    return {"news_n": len(rows), "news_net": (pos - neg) / n if n else None,
            "news_latest": rows[0].get("title") if rows else None}


def fetch_8k(tk: str, key: str, days: int = 45) -> Dict[str, Any]:
    rows = massive_get_all("/stocks/filings/8-K/vX/disclosures",
                           {"tickers": tk, "filing_date.gte": (date.today() - timedelta(days=days)).isoformat(),
                            "limit": 100}, key, max_pages=1)
    rows = _latest(rows, "filing_date")
    cats = [r.get("tertiary_category") for r in rows if r.get("tertiary_category")]
    earn = [r for r in rows if any(w in (r.get("tertiary_category") or "") for w in ("earning", "results", "guidance"))]
    return {"events_n": len(rows), "events": ", ".join(dict.fromkeys(cats))[:160] if cats else "",
            "last_event_date": rows[0].get("filing_date") if rows else None,
            "earnings_8k_date": earn[0].get("filing_date") if earn else None}


def insider_purchases(universe: set, key: str, days: int = 90, max_owner_checks: int = 150) -> pd.DataFrame:
    """Open-market purchases (Form 4, code P) in the window, split into routine vs
    opportunistic per Cohen, Malloy & Pomorski: routine = the insider also traded in
    the same calendar month in each of the three prior years."""
    since = (date.today() - timedelta(days=days)).isoformat()
    rows = massive_get_all("/stocks/filings/vX/form-4", {"transaction_code": "P", "filing_date.gte": since,
                                                         "limit": 1000, "sort": "filing_date.desc"}, key, max_pages=15)
    recs = []
    for r in rows:
        tks = [t for t in (r.get("tickers") or []) if t in universe]
        if not tks or r.get("security_type", "non_derivative") != "non_derivative":
            continue
        recs.append({"ticker": tks[0], "owner": r.get("owner_name"), "owner_cik": r.get("owner_cik"),
                     "date": r.get("transaction_date") or r.get("filing_date"),
                     "value": _n(r.get("transaction_value"), _n(r.get("transaction_shares")) * _n(r.get("transaction_price_per_share"))),
                     "officer": bool(r.get("is_officer")), "director": bool(r.get("is_director")),
                     "plan_10b5_1": bool(r.get("aff_10b5_one"))})
    df = pd.DataFrame(recs)
    if df.empty:
        return df
    df["routine"] = False
    pairs = df.drop_duplicates(["ticker", "owner"]).head(max_owner_checks)
    for p in pairs.itertuples():
        params = {"tickers": p.ticker, "filing_date.gte": (date.today() - timedelta(days=4 * 366)).isoformat(),
                  "limit": 1000}
        if p.owner_cik:
            params["owner_cik"] = p.owner_cik
        try:
            hist = massive_get_all("/stocks/filings/vX/form-4", params, key, max_pages=2)
        except Exception:
            continue
        if not p.owner_cik:
            hist = [h for h in hist if h.get("owner_name") == p.owner]
        traded = {(int(str(h.get("transaction_date") or h.get("filing_date"))[:4]),
                   int(str(h.get("transaction_date") or h.get("filing_date"))[5:7]))
                  for h in hist if (h.get("transaction_date") or h.get("filing_date"))}
        for i in df.index[(df["ticker"] == p.ticker) & (df["owner"] == p.owner)]:
            y, m = int(str(df.at[i, "date"])[:4]), int(str(df.at[i, "date"])[5:7])
            df.at[i, "routine"] = all((y - k, m) in traded for k in (1, 2, 3))
    return df


def insider_summary(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return pd.DataFrame(columns=["opp_buys", "opp_buy_value", "routine_buys", "last_opp_buy"])
    opp = df[~df["routine"] & ~df["plan_10b5_1"]]
    g = pd.DataFrame({"opp_buys": opp.groupby("ticker").size(), "opp_buy_value": opp.groupby("ticker")["value"].sum(),
                      "routine_buys": df[df["routine"]].groupby("ticker").size(),
                      "last_opp_buy": opp.groupby("ticker")["date"].max()})
    return g.fillna({"opp_buys": 0, "routine_buys": 0, "opp_buy_value": 0.0})


def demo_flows(tickers: List[str]) -> Tuple[pd.DataFrame, pd.DataFrame]:
    rng = np.random.default_rng(zlib.crc32(f"flows{date.today()}".encode()))
    rows = []
    for t in tickers:
        dtc = float(rng.lognormal(0.6, 0.7))
        rows.append({"ticker": t, "short_interest": int(rng.uniform(1e6, 4e7)), "days_to_cover": dtc,
                     "si_change": float(rng.normal(0, 0.12)), "short_vol_ratio_5d": float(rng.uniform(0.3, 0.6)),
                     "short_vol_ratio_20d": float(rng.uniform(0.35, 0.55)), "shares_out": float(rng.uniform(5e7, 2e9)),
                     "market_cap": float(rng.uniform(1e9, 5e11)), "sic": "DEMO", "news_n": int(rng.integers(0, 30)),
                     "news_net": float(rng.uniform(-0.6, 0.8)), "events_n": int(rng.integers(0, 4)),
                     "events": rng.choice(["", "ceo_departure", "guidance_issuance_or_update", "material_agreement"]),
                     "earnings_8k_date": None})
    ins = []
    for t in rng.choice(tickers, size=max(1, len(tickers) // 12), replace=False):
        for _ in range(int(rng.integers(1, 3))):
            ins.append({"ticker": t, "owner": f"Insider {rng.integers(1, 99)}", "owner_cik": None,
                        "date": (date.today() - timedelta(days=int(rng.integers(1, 80)))).isoformat(),
                        "value": float(rng.uniform(5e4, 2e6)), "officer": bool(rng.random() < 0.5),
                        "director": bool(rng.random() < 0.6), "plan_10b5_1": False, "routine": bool(rng.random() < 0.3)})
    return pd.DataFrame(rows).set_index("ticker"), pd.DataFrame(ins)


def load_flows(tickers: List[str], source: str, key: Optional[str], parts: Tuple[str, ...], progress=None) -> Dict[str, Any]:
    if source == "demo":
        f, ins = demo_flows(tickers)
        return {"table": f, "insiders": ins, "errors": [], "as_of": datetime.now().isoformat(timespec="seconds")}
    if source != "massive" or not key:
        raise PlanError("Filings and flows need a Massive key.")
    errors: List[str] = []
    cache_path = CACHE_DIR / f"flows_{date.today().isoformat()}.json"
    cache = disk_json(cache_path, {}) or {}

    def one(t):
        rec = dict(cache.get(t, {}))
        for part, fn in (("short", fetch_short), ("overview", fetch_overview), ("news", fetch_news), ("8k", fetch_8k)):
            if part in parts and f"_{part}" not in rec:
                try:
                    rec.update(fn(t, key))
                    rec[f"_{part}"] = True
                except Exception as e:
                    errors.append(f"{t} {part}: {type(e).__name__}")
        return t, rec

    out = {}
    with ThreadPoolExecutor(max_workers=6) as ex:
        futs = [ex.submit(one, t) for t in tickers]
        for i, f in enumerate(as_completed(futs), 1):
            t, rec = f.result()
            out[t] = rec
            if progress is not None:
                progress.progress(i / len(tickers), text=f"Filings and flows {i}/{len(tickers)}")
    cache.update(out)
    try:
        atomic_write_json(cache_path, cache)
    except Exception:
        pass
    ins = pd.DataFrame()
    if "insiders" in parts:
        try:
            ins = insider_purchases(set(tickers), key)
        except Exception as e:
            errors.append(f"Form 4: {type(e).__name__}: {e}")
    table = pd.DataFrame({t: {k: v for k, v in r.items() if not k.startswith("_")} for t, r in out.items()}).T
    return {"table": table, "insiders": ins, "errors": errors[:30], "as_of": datetime.now().isoformat(timespec="seconds")}


