# ═══════════════════════════════════════════════════════════════════════════
#  THESIS CARD
#  Variant perception (Mauboussin & Rappaport), source of edge "who is on the other
#  side" (BAIT), base rates (outside view), a stated probability that gets scored
#  (Tetlock), pre-mortem (Klein) and kill criteria as a state and a date (Duke).
#  The tab pre-fills every field it can from the rest of the dashboard; judgment
#  fields stay with the trader. Saved cards are scored later against the bars.
# ═══════════════════════════════════════════════════════════════════════════

THESIS_FILE = HERE / "data" / "theses.csv"
THESIS_COLS = ["id", "created", "ticker", "direction", "setup", "vehicle", "horizon_sessions", "due_date", "entry",
               "stop", "target", "p_stated", "p_model", "edge_types", "variant", "base_rate", "catalyst", "kill_state",
               "kill_date", "premortem", "status", "outcome", "scored_on", "notes"]


def _business_days_ahead(d: date, n: int) -> date:
    out = d
    while n > 0:
        out += timedelta(days=1)
        if out.weekday() < 5:
            n -= 1
    return out


def gather_evidence(tk: str, cfg, ab, bars, bench_bars, stack, hits, frames, fm, clim, mand, horizon: int,
                    stop_mult: float, tgt_mult: float, direction: str, with_chain: bool = True) -> Dict[str, Any]:
    src = cfg["source"]
    df = bars.get(tk) if tk in bars else bench_bars.get(tk)
    if df is None:
        got, _ = get_bars([tk], UNIVERSE_DAYS, src, cfg["key"], cfg["drop_partial"])
        df = got.get(tk)
    if df is None or len(df) < 120:
        return {"error": f"No usable daily history for {tk}."}
    ev: Dict[str, Any] = {"ticker": tk, "direction": direction, "horizon": horizon, "df": df}
    spot = float(df["close"].iloc[-1])
    a = atr_pct(df)
    hv = _n(np.log(df["close"]).diff().iloc[-21:].std() * math.sqrt(252), 0.3)
    sgn = 1 if direction == "long" else -1
    ev.update({"spot": spot, "atr": a, "hv": hv, "stop": spot * (1 - sgn * stop_mult * a), "target": spot * (1 + sgn * tgt_mult * a),
               "due": _business_days_ahead(last_completed_session(), horizon)})
    snap = ab["snap"] if ab else pd.DataFrame()
    comp = _n(snap["composite"].get(tk), np.nan) if len(snap) else np.nan
    ev["composite"] = comp
    ev["cats"] = {c: _n(snap.loc[tk, f"cat_{c}"], np.nan) for c in CAT_ORDER} if (len(snap) and tk in snap.index) else {}
    calib = st.session_state.get("calib")
    mu, se, bucket = signal_drift(calib, comp, horizon) if np.isfinite(comp) else (0.0, 0.0, "")
    ev.update({"mu": mu, "mu_se": se, "bucket": "" if bucket in ("none", None) else bucket})
    if calib and "res" in calib and "error" not in calib["res"] and bucket:
        row = calib["res"]["nonoverlap"]
        row = row[row["bucket"] == bucket]
        if len(row):
            r = row.iloc[0]
            ev["cal"] = {"horizon": calib["res"]["meta"]["horizon"], "close_up": _n(r.get("close_up"), np.nan),
                         "excess_up": _n(r.get("excess_up"), np.nan), "t_excess": _n(r.get("t_excess"), np.nan),
                         "p_up_first": _n(r.get("p_up_first"), np.nan), "n": int(_n(r.get("n"), 0))}
    if ab is not None and tk in ab["P"]["close"].columns:
        m = memo(("thesis_sm", str(ab["asof"]), ab["P"]["close"].shape[1]), lambda: screen_metrics(ab["P"]))
        fl = fip_flags(m)
        if tk in m.index:
            ev["fip"] = bool(fl.get(tk, False))
            ev["fip_id"] = _n(m.at[tk, "fip_id"], np.nan)
            ev["pct_52w"] = _n(m.at[tk, "pct_of_52w_high"], np.nan)
            ev["quiet_acc"] = int(_n(m.at[tk, "quiet_acc_days"], 0))
            ev["dollar_vol_m"] = _n(m.at[tk, "dollar_vol_m"], np.nan)
    spy = bench_bars.get("SPY")
    if spy is not None:
        try:
            out = rs8_one(tk, df, spy["close"])
            if out:
                ev["rs"] = out[0]
        except Exception:
            pass
    try:
        P1 = {k: df[[k]].rename(columns={k: tk}) for k in ("open", "high", "low", "close", "volume")}
        tm = tl_metrics(P1)
        if tk in tm.index:
            r_ = tm.loc[tk]
            ev["lp"] = {"type": r_["lp_type"], "full_age": r_["tl_full_age"], "short_age": r_["tl_short_age"],
                        "deepvue_age": r_["tl_deepvue_age"], "power3_age": r_["tl_power3_age"], "risk_to_pad": r_["risk_to_pad"],
                        "spread6": r_["lp_spread6"], "late": bool(r_["late_cycle"]), "r200": bool(r_["sma200_rising"])}
            T1 = tl_panels(P1)
            ev["lp"]["pad_low"] = float(min(T1["mas"]["SMA10"][tk].iloc[-1], T1["mas"]["SMA21"][tk].iloc[-1],
                                            T1["mas"]["EMA23"][tk].iloc[-1]))
    except Exception:
        pass
    if stack is not None and len(stack) and tk in set(stack["ticker"]):
        r = stack.set_index("ticker").loc[tk]
        ev["stack"] = {k: r.get(k) for k in ("status", "cluster", "age", "ttt", "garp", "dip", "hv20")}
    hp = pick_hits(hits, 21, 0.03, "UP" if direction == "long" else "DN")
    if tk in hp.index:
        ev["p_touch_3_21"] = _n(hp.at[tk, "p_hit"], np.nan)
    if fm is not None and tk in fm.index:
        ev["beta"] = _n(fm.at[tk, "beta"], np.nan)
        ev["resid_mom_pct"] = _n(fm.at[tk, "resid_mom_pct"], np.nan)
    ff = flows_frame()
    if ff is not None and tk in ff.index:
        ev["flows"] = {k: ff.at[tk, k] for k in ("days_to_cover", "short_vol_ratio_5d", "opp_buys", "news_net", "events",
                                                   "earnings_8k_date") if k in ff.columns}
    q = st.session_state.get("quality_res")
    if q is not None and tk in q.index:
        ev["quality"] = {"f_score": _n(q.at[tk, "f_score"], np.nan), "gross_prof": _n(q.at[tk, "gross_prof"], np.nan)}
    try:
        lb = lbr_snapshot(tk, tk, "stock", "RS", df.iloc[-320:])
        ev["lbr"] = {k: lb[k] for k in ("env", "taylor", "sma5_state", "sma_streak", "setups", "pc")}
    except Exception:
        pass
    sc = path_scenarios(df, horizon, hv, mu, "zero", frames.get(tk) if frames else None)
    if sc is not None:
        if direction == "short":
            sc = {**sc, **{k: -sc[k] for k in ("C", "O")}, "H": -sc["L"], "L": -sc["H"]}
        stop_d, tgt_d = stop_mult * a, tgt_mult * a
        res = kelly_with_uncertainty(lambda s: stock_trade_returns(s, stop_d, tgt_d)[0], sc, se)
        _, info = stock_trade_returns(sc, stop_d, tgt_d)
        ev["model"] = {**info, "exp_ret": res["mean_R"], "kelly": res["f_raw"] * res["shrink"], "n_eff": res["n_eff"]}
    if with_chain and src in ("massive", "demo"):
        try:
            raw = fetch_chain(tk, 120, src, cfg["key"], spot, hv, cfg["strip"], band=0.30)
            cons = [x for x in (extract_contract(r, date.today()) for r in raw) if x]
            sp = next((x["spot"] for x in cons if x["spot"]), None) or spot
            vd = vol_desk_name(tk, cons, sp, df["close"])
            if vd:
                iv = vd["iv1m"]
                ev["vol"] = {"iv1m": iv, "rv21": vd["rv21"], "vrp": vd["vrp_log"], "rv_pct": vd["rv21_pct"],
                             "move_h": iv * math.sqrt(horizon / 252) if np.isfinite(iv) else np.nan,
                             "event_exp": vd["event_exp"], "event_move": vd["event_move"], "put_skew": vd["put_skew"],
                             "term": vd["term_6m_1m"]}
            dr = dealer_read(tk, cons, sp)
            if dr:
                ev["dealer"] = {k: dr[k] for k in ("regime", "flip", "call_wall", "put_wall", "max_pain", "net_gex")}
            eh = earnings_history(tk, df["close"], src, cfg["key"])
            if len(eh):
                ev["earn_realized"] = float(eh["abs_move"].tail(4).mean())
        except Exception as e:
            ev["chain_error"] = f"{type(e).__name__}: {e}"
    ev["market"] = {"climate": str(clim["h"]["sticky"]) if clim else "n/a",
                    "spy_cluster": mand["last"]["cluster"] if mand else "n/a"}
    br = st.session_state.get("breadth_res")
    if br is not None and spy is not None:
        ev["market"]["breadth"] = breadth_read(br["b"], spy["close"])["state"]
    return ev


def suggest(ev: Dict[str, Any], setup: str) -> Dict[str, Any]:
    long_ = ev["direction"] == "long"
    rs, fl, vol, dl = ev.get("rs", {}), ev.get("flows", {}), ev.get("vol", {}), ev.get("dealer", {})
    edges = []
    if ev.get("fip") or rs.get("rs_nh_252") or _n(ev.get("resid_mom_pct"), 0) >= 70:
        edges.append(("behavioral", "Underreaction: smooth trend (FIP), RS-line leadership or strong residual momentum."))
    cal = ev.get("cal", {})
    if _n(ev.get("composite"), 0) >= 70 and _n(cal.get("t_excess"), 0) >= 2:
        edges.append(("analytical", f"Composite bucket {ev['bucket']} has beaten the same-day universe (t {cal['t_excess']:.1f})."))
    if _n(fl.get("opp_buys"), 0) > 0 or (fl.get("events") or ""):
        edges.append(("informational", "Opportunistic insider buying or a recent tagged 8-K event."))
    lp = ev.get("lp", {})
    lp_recent = min(_n(lp.get("full_age"), 999), _n(lp.get("short_age"), 999), _n(lp.get("deepvue_age"), 999)) <= 5
    if lp_recent and long_:
        edges.append(("behavioral", "TraderLion LaunchPad: holders across timeframes at a similar cost basis just beneath "
                                    "price, the footprint of demand Haber describes."))
    if _n(fl.get("days_to_cover"), 0) >= 5 or ev.get("quiet_acc", 0) > 0 or dl.get("regime") == "NEGATIVE":
        edges.append(("technical", "Forced or mechanical flows: crowded shorts, quiet accumulation, or negative dealer gamma."))
    vrp = _n(vol.get("vrp"), np.nan)
    vol_state = "fair" if not np.isfinite(vrp) else ("cheap" if vrp < 0 else ("rich" if vrp > 0.15 else "fair"))
    row = next((r for r in PLAYBOOK if r[0] == setup), PLAYBOOK[1])
    vehicle = row[{"cheap": 1, "fair": 2, "rich": 3}[vol_state]]
    risks = []
    mk = ev.get("market", {})
    if mk.get("climate") == "CRISIS" or mk.get("spy_cluster") == "ACTIVE":
        risks.append(f"Market regime: climate {mk.get('climate')}, SPY cluster {mk.get('spy_cluster')}: extremes come in packages.")
    if mk.get("breadth") == "DIVERGE":
        risks.append("Breadth diverges from SPY: the average stock is not confirming.")
    if (ev.get("stack") or {}).get("cluster") == "ACTIVE":
        risks.append("The name's own volatility is bunched (ACTIVE): stops get run.")
    if vol.get("event_exp") and str(vol["event_exp"]) <= ev["due"].isoformat():
        risks.append(f"Event priced into {vol['event_exp']} falls inside the horizon: a gap can go through the stop.")
    if _n(rs.get("ext_8w"), 0) > 15:
        risks.append(f"Extended {rs['ext_8w']:.0f}% above the 8-week EMA: a breakout mark, not a pullback entry.")
    if _n(fl.get("days_to_cover"), 0) >= 5:
        risks.append(f"Crowded short (days to cover {fl['days_to_cover']:.1f}): violent both ways.")
    if dl.get("regime") == "NEGATIVE":
        risks.append("Dealers short gamma: hedging amplifies moves in both directions.")
    if long_ and dl.get("call_wall") and ev["target"] > dl["call_wall"] > ev["spot"]:
        risks.append(f"Target sits beyond the call wall {dl['call_wall']:,.2f}: dealer hedging leans against it.")
    if lp_recent and _n(lp.get("risk_to_pad"), 0) > 3:
        risks.append(f"Risk to the pad is {lp['risk_to_pad']:.1f}%: more than 3%, so the entry isn't there yet (Haber).")
    if lp_recent and lp.get("late"):
        risks.append("Late-cycle LaunchPad: the stock has already doubled off its 52-week low, so the pad carries less weight.")
    if _n(ev.get("beta"), 1) > 1.6:
        risks.append(f"High beta ({ev['beta']:.1f}): this is partly a market bet.")
    if vol_state == "rich" and "call" in vehicle.lower() and "credit" not in vehicle.lower():
        risks.append("Vol is rich: long option premium needs the move to come quickly.")
    vtxt = []
    if vol:
        vtxt.append(f"Market prices about ±{_n(vol.get('move_h')) * 100:.1f}% over {ev['horizon']} sessions "
                    f"(IV 1m {_n(vol.get('iv1m')) * 100:.0f}% vs realized {_n(vol.get('rv21')) * 100:.0f}%, VRP {vrp:+.2f}).")
        if vol.get("event_exp"):
            vtxt.append(f"An event is priced into {vol['event_exp']}: about ±{_n(vol.get('event_move')) * 100:.1f}%"
                        + (f" vs ±{ev['earn_realized'] * 100:.1f}% average over the last four reports." if ev.get("earn_realized") else "."))
    vtxt.append(f"My {'upside' if long_ else 'downside'} target {ev['target']:,.2f} is {abs(ev['target'] / ev['spot'] - 1) * 100:.1f}% away; "
                "the market's price implies [say why your distribution differs].")
    bt = []
    if cal:
        bt.append(f"Composite bucket {ev['bucket']} ({cal['horizon']}-session calibration, non-overlapping): up {cal['close_up']:.0%}, "
                  f"excess vs same day {cal['excess_up']:+.1%} (t {cal['t_excess']:.1f}), up-first {cal['p_up_first']:.0%}.")
    if np.isfinite(_n(ev.get("p_touch_3_21"), np.nan)):
        bt.append(f"This name has touched {'+' if long_ else '-'}3% within 21 sessions {ev['p_touch_3_21']:.0%} of the time in its current state.")
    mdl = ev.get("model", {})
    if mdl:
        bt.append(f"Own-history paths: target before stop {mdl['p_target']:.0%}, stop first {mdl['p_stop']:.0%}, neither {mdl['p_timeout']:.0%}.")
    kill_state = [f"Close {'below' if long_ else 'above'} {ev['stop']:,.2f} (stop, {abs(ev['stop'] / ev['spot'] - 1) * 100:.1f}% away)"]
    e8 = rs.get("close", np.nan) / (1 + _n(rs.get("ext_8w"), 0) / 100) if rs else np.nan
    if long_ and np.isfinite(e8):
        if ev["spot"] > e8:
            kill_state.append(f"Weekly close below the 8-week EMA (~{e8:,.2f})")
        else:
            risks.append(f"Price is already below the 8-week EMA (~{e8:,.2f}): the pullback thesis needs a reclaim first.")
    if long_ and dl.get("put_wall") and dl["put_wall"] < ev["spot"]:
        kill_state.append(f"Loses the put wall {dl['put_wall']:,.2f}")
    if long_ and lp_recent and np.isfinite(_n(lp.get("pad_low"), np.nan)):
        if ev["spot"] > lp["pad_low"]:
            kill_state.append(f"Two closes below the pad (lowest of the 10 SMA, 21 SMA, 23 EMA, ~{lp['pad_low']:,.2f})")
        else:
            risks.append(f"Price is already below the pad (~{lp['pad_low']:,.2f}): the LaunchPad has failed for now.")
    kill_state.append("SPY cluster turns ACTIVE or the climate flips to CRISIS")
    cat = []
    if vol.get("event_exp"):
        cat.append(f"Priced event before {vol['event_exp']}")
    if (ev.get("flows") or {}).get("events"):
        cat.append(f"Recent 8-K: {ev['flows']['events']}")
    if ev.get("lbr", {}).get("setups"):
        cat.append(f"LBR: {ev['lbr']['setups'][0]}")
    if lp_recent:
        cat.append(f"TraderLion LaunchPad ({lp.get('type') or 'recent'}): expansion off the converged averages")
    if _n(lp.get("power3_age"), 999) <= 5:
        cat.append("Power of 3: reclaimed the 10, 21 and 50-day SMAs in one session on volume")
    if rs.get("chartmaster_pullback"):
        cat.append("ChartMaster pocket with an RS-line high")
    p_model = mdl.get("p_target") if mdl else np.nan
    return {"edges": edges, "vol_state": vol_state, "vehicle": vehicle, "risk_style": row[4], "risks": risks,
            "variant": " ".join(vtxt), "base_rate": " ".join(bt), "kill_state": "; ".join(kill_state),
            "kill_date": ev["due"].isoformat(), "catalyst": "; ".join(cat), "p_model": p_model}


def evidence_scores(ev: Dict[str, Any]) -> pd.DataFrame:
    """Each item scored -1..+1 for the chosen direction (positive = supports the thesis)."""
    s = 1 if ev["direction"] == "long" else -1
    rs, vol, mk = ev.get("rs", {}), ev.get("vol", {}), ev.get("market", {})
    rows = []
    add = lambda name, v, why: rows.append({"evidence": name, "score": float(np.clip(v, -1, 1)), "why": why}) if np.isfinite(v) else None
    add("Composite rank", s * (_n(ev.get("composite"), np.nan) - 50) / 50, f"{_n(ev.get('composite'), np.nan):.0f} pct")
    if "fip" in ev:
        add("Frog in the pan", s * (0.8 if ev["fip"] else -0.2), "FIP yes" if ev["fip"] else "FIP no")
    if rs:
        add("RS-line high", s * (0.8 if rs.get("rs_nh_252") else -0.3), "252-day RS high" if rs.get("rs_nh_252") else "no RS high")
        add("8-week location", (0.7 if rs.get("in_8w_pocket") else (-0.6 if _n(rs.get("ext_8w"), 0) > 15 else 0.0)) * (1 if s > 0 else -1),
            f"{_n(rs.get('ext_8w'), 0):+.1f}% vs 8-week EMA")
    if np.isfinite(_n(ev.get("resid_mom_pct"), np.nan)):
        add("Residual momentum", s * (ev["resid_mom_pct"] - 50) / 50, f"{ev['resid_mom_pct']:.0f} pct")
    stck = ev.get("stack") or {}
    if stck:
        add("Name cluster", 0.5 if stck.get("cluster") == "QUIET" else -0.7, str(stck.get("cluster")))
        add("Trade / trend / tail", s * ((str(stck.get("ttt")).count("U") - 1.5) / 1.5), str(stck.get("ttt")))
    cal = ev.get("cal", {})
    if cal:
        add("Calibrated bucket edge", s * _n(cal.get("t_excess"), 0) / 3, f"t {cal.get('t_excess', 0):.1f}")
    mdl = ev.get("model", {})
    if mdl:
        add("Target before stop", (mdl["p_target"] - mdl["p_stop"]) * 2, f"{mdl['p_target']:.0%} vs {mdl['p_stop']:.0%}")
    if mk:
        add("Market regime", -0.8 if (mk.get("climate") == "CRISIS" or mk.get("spy_cluster") == "ACTIVE") else 0.4,
            f"{mk.get('climate')}, {mk.get('spy_cluster')}")
        if mk.get("breadth") in ("CONFIRM", "DIVERGE"):
            add("Breadth", s * (0.5 if mk["breadth"] == "CONFIRM" else -0.5), mk["breadth"])
    if vol and np.isfinite(_n(vol.get("vrp"), np.nan)):
        add("Option pricing (VRP)", float(-np.clip(vol["vrp"] / 0.3, -1, 1)), f"VRP {vol['vrp']:+.2f}: + cheap to own, - rich")
    lp = ev.get("lp", {})
    if lp:
        age = min(_n(lp.get("full_age"), 999), _n(lp.get("short_age"), 999), _n(lp.get("deepvue_age"), 999))
        add("TraderLion LaunchPad", s * (0.8 if age <= 5 and not lp.get("late") else (0.3 if age <= 20 else -0.1)),
            f"{lp.get('type') or 'none today'}; last {age:.0f} sessions ago" if age < 999 else "no pad in 60 sessions")
    fl = ev.get("flows", {})
    if fl:
        add("Insider buying", 0.7 * s if _n(fl.get("opp_buys"), 0) > 0 else 0.0, f"{int(_n(fl.get('opp_buys'), 0))} opportunistic")
    return pd.DataFrame(rows)


def load_theses() -> pd.DataFrame:
    try:
        return pd.read_csv(THESIS_FILE, dtype=str)
    except Exception:
        return pd.DataFrame(columns=THESIS_COLS)


def save_theses(df: pd.DataFrame) -> None:
    THESIS_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = THESIS_FILE.with_suffix(".tmp")
    df[[c for c in THESIS_COLS if c in df.columns]].to_csv(tmp, index=False)
    os.replace(tmp, THESIS_FILE)


def score_thesis(row: pd.Series, df: pd.DataFrame) -> Tuple[str, Optional[int]]:
    """Outcome = 1 if the target traded before the stop and by the due date (a day that
    touches both counts as a stop), 0 if the stop came first or the date passed."""
    try:
        created = pd.Timestamp(str(row["created"])[:10])
        due = pd.Timestamp(str(row["due_date"])[:10])
        stop, tgt = float(row["stop"]), float(row["target"])
    except Exception:
        return "invalid", None
    long_ = str(row.get("direction", "long")) == "long"
    d = df[(df.index > created) & (df.index <= due)]
    for _, b in d.iterrows():
        hit_s = b["low"] <= stop if long_ else b["high"] >= stop
        hit_t = b["high"] >= tgt if long_ else b["low"] <= tgt
        if hit_s:
            return "resolved", 0
        if hit_t:
            return "resolved", 1
    if len(df) and df.index[-1] >= due:
        return "expired", 0
    return "open", None


def thesis_markdown(card: Dict[str, Any]) -> str:
    f = lambda k: card.get(k, "") or ""
    return "\n".join([
        f"# Thesis: {f('ticker')} ({f('direction')}), {f('created')[:10]}",
        f"**Setup:** {f('setup')}  \n**Vehicle:** {f('vehicle')}  \n**Horizon:** {f('horizon_sessions')} sessions, due {f('due_date')}",
        f"**Entry / stop / target:** {f('entry')} / {f('stop')} / {f('target')}",
        f"**Stated probability (target before stop):** {f('p_stated')}  (model {f('p_model')})",
        "", "## Edge (who is on the other side?)", f("edge_types"),
        "", "## Variant perception", f("variant"),
        "", "## Base rates (outside view)", f("base_rate"),
        "", "## Catalyst", f("catalyst"),
        "", "## Kill criteria", f"**State:** {f('kill_state')}  \n**Date:** {f('kill_date')}",
        "", "## Pre-mortem", f("premortem"),
        "", "## Notes", f("notes")])


# ═══════════════════════════════════════════════════════════════════════════
#  CREDIT CANARY
#  Evidence: credit spreads carry real information about the economy (Gilchrist &
#  Zakrajsek 2012), very tight spreads predict a later reversal and slowdown
#  (Lopez-Salido, Stein & Zakrajsek 2017), but at daily and weekly horizons stocks
#  lead credit, not the reverse (Hilscher, Pollet & Wilson 2015), and widening
#  alone gives many false alarms. So credit is a slow confirming input here, never
#  a standalone trigger.
#  Stress index: the ICE BofA high-yield OAS from FRED when a key is set (points);
#  otherwise -100 x ln(HYG / IEF), a duration-closer price proxy (no TLT: its long
#  duration makes the ratio a rate bet).
#  Flags: WIDENING  = index above its 63-day mean and its 63-day change >= +0.5 z
#         STRESS    = 20-day change >= +1 z (the size that confirms CRISIS)
#         DIVERGENCE= WIDENING while SPY is within 3% of its 52-week high
#         COMPLACENT= OAS in the tightest 10% of its trailing five years (OAS only)
# ═══════════════════════════════════════════════════════════════════════════

CREDIT_FLAGS = ["STRESS", "DIVERGENCE", "WIDENING", "COMPLACENT"]


def credit_canary(closes: pd.DataFrame, oas: Optional[pd.Series] = None, near_high: float = 0.03,
                  complacent_q: float = 0.10) -> Optional[Dict[str, Any]]:
    if "SPY" not in closes:
        return None
    spy = closes["SPY"].dropna()
    pct_lvl = None
    if oas is not None and len(oas.dropna()) > 300:
        o = oas.dropna().astype(float)
        o.index = pd.to_datetime(o.index)
        q10 = o.rolling(1260, min_periods=252).quantile(complacent_q)
        pct = o.rolling(1260, min_periods=252).apply(lambda w: (w <= w[-1]).mean(), raw=True)
        idx = spy.index
        S = o.reindex(o.index.union(idx)).ffill().reindex(idx)
        comp = (o <= q10).reindex(o.index.union(idx)).ffill().reindex(idx).fillna(False).astype(bool)
        pct_lvl = pct.reindex(o.index.union(idx)).ffill().reindex(idx)
        source, unit = "High-yield OAS (FRED)", "pts"
    elif "HYG" in closes and "IEF" in closes:
        r = (closes["HYG"] / closes["IEF"]).reindex(spy.index)
        S = -100 * np.log(r)
        comp = pd.Series(False, index=spy.index)
        source, unit = "HYG / IEF price proxy", "%"
    else:
        return None
    df = pd.DataFrame({"spy": spy, "stress": S})
    df["chg20"] = df["stress"] - df["stress"].shift(20)
    df["chg63"] = df["stress"] - df["stress"].shift(63)
    df["z20"], df["z63"] = robust_z(df["chg20"]), robust_z(df["chg63"])
    df["sma63"] = df["stress"].rolling(63, min_periods=40).mean()
    df["spy_high"] = df["spy"].rolling(252, min_periods=120).max()
    df["WIDENING"] = (df["stress"] > df["sma63"]) & (df["z63"] >= 0.5)
    df["STRESS"] = df["z20"] >= 1.0
    df["DIVERGENCE"] = df["WIDENING"] & (df["spy"] >= df["spy_high"] * (1 - near_high))
    df["COMPLACENT"] = comp.reindex(df.index).fillna(False).astype(bool)
    if pct_lvl is not None:
        df["level_pct"] = pct_lvl
    last = df.iloc[-1]
    state = next((f for f in CREDIT_FLAGS if bool(last[f])), "CALM")
    return {"df": df, "source": source, "unit": unit, "state": state, "last": last,
            "spy_off_high": float(last["spy"] / last["spy_high"] - 1) if np.isfinite(_n(last["spy_high"], np.nan)) else np.nan,
            "is_oas": pct_lvl is not None}


def credit_event_study(df: pd.DataFrame, horizon: int = 63, cooldown: int = 20) -> pd.DataFrame:
    """For each flag's first day (cooldown between events): SPY's worst drawdown and its return
    over the next `horizon` sessions, against every day. Few events: read it as a sanity check."""
    spy = df["spy"]
    fut_min = spy[::-1].rolling(horizon, min_periods=horizon).min()[::-1].shift(-1)
    mdd = fut_min / spy - 1
    fwd = spy.shift(-horizon) / spy - 1
    ok = mdd.notna() & fwd.notna()
    rows = [{"flag": "every day", "events": int(ok.sum()), "fwd_ret": float(fwd[ok].mean()),
             "median_max_dd": float(mdd[ok].median()), "p_dd_10": float((mdd[ok] <= -0.10).mean()),
             "p_dd_5": float((mdd[ok] <= -0.05).mean())}]
    for f in CREDIT_FLAGS:
        sig = df[f].fillna(False).astype(bool)
        first = sig & ~sig.shift(1, fill_value=False)
        recent = first.astype(int).rolling(cooldown, min_periods=1).sum().shift(1).fillna(0)
        ev = first & (recent == 0) & ok
        n = int(ev.sum())
        rows.append({"flag": f, "events": n, "fwd_ret": float(fwd[ev].mean()) if n else np.nan,
                     "median_max_dd": float(mdd[ev].median()) if n else np.nan,
                     "p_dd_10": float((mdd[ev] <= -0.10).mean()) if n else np.nan,
                     "p_dd_5": float((mdd[ev] <= -0.05).mean()) if n else np.nan})
    return pd.DataFrame(rows)


