def _esc(s: Any) -> str:
    t = "" if s is None else str(s)
    return (t.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
             .replace('"', "&quot;").replace("'", "&#x27;"))


def md(html_str: str, target=None) -> None:
    (target or st).markdown(html_str, unsafe_allow_html=True)


def sec(title: str) -> None:
    md(f"<div class='sec'>{_esc(title)}</div>")


def note(text: str, target=None) -> None:
    md(f"<div class='note'>{_esc(text)}</div>", target)


def warnbox(text: str, target=None) -> None:
    md(f"<div class='warnbox'>{_esc(text)}</div>", target)


def kpi_html(label: str, value: Any, sub: str = "", tone: str = "") -> str:
    return (f"<div class='kpi {tone}'><div class='kpi-lbl'>{_esc(label)}</div>"
            f"<div class='kpi-val'>{_esc(value)}</div><div class='kpi-sub'>{_esc(sub)}</div></div>")


def kpi_row(items: List[str]) -> None:
    """Items are finished HTML strings; built before entering the column context."""
    cols = st.columns(len(items))
    for col, h in zip(cols, items):
        col.markdown(h, unsafe_allow_html=True)


def hero_html(chip: str, color: str, age: str, text: str) -> str:
    return (f"<div class='hero' style='--hc:{color}'><div class='hero-chip'>{_esc(chip)}</div>"
            f"<div class='hero-age'>{_esc(age)}</div><div class='hero-text'>{_esc(text)}</div></div>")


def card_html(c: Dict[str, str]) -> str:
    v = c.get("verdict", "neutral")
    return (f"<div class='acard {v}'><div class='acard-hd'><span>{_esc(c['title'])}</span><span>{_esc(v)}</span></div>"
            f"<div class='acard-st'>{_esc(c['state'])}</div><div class='acard-now'>{_esc(c['now'])}</div>"
            f"<div class='acard-mean'>{_esc(c['meaning'])}</div></div>")


def card_grid(cards: List[Dict[str, str]], ncol: int = 3) -> None:
    htmls = [card_html(c) for c in cards]
    cols = st.columns(ncol)
    for i, h in enumerate(htmls):
        cols[i % ncol].markdown(h, unsafe_allow_html=True)


def sleeve_html(n: str, v: str, s: str) -> str:
    return (f"<div class='sleeve'><div class='sleeve-n'>{_esc(n)}</div><div class='sleeve-v'>{_esc(v)}</div>"
            f"<div class='sleeve-s'>{_esc(s)}</div></div>")


def pct(x, d: int = 0) -> str:
    return "—" if x is None or not np.isfinite(_n(x, np.nan)) else f"{float(x) * 100:.{d}f}%"


def show_df(df: pd.DataFrame, height: Optional[int] = None, **kw) -> None:
    args = {"hide_index": True, **kw}
    if height:
        args["height"] = height
    try:
        st.dataframe(df, width="stretch", **args)
    except TypeError:
        st.dataframe(df, use_container_width=True, **args)


def show_chart(ch) -> None:
    try:
        st.altair_chart(ch, width="stretch")
    except TypeError:
        st.altair_chart(ch, use_container_width=True)


def _alt(ch, height: int = 220):
    return (ch.properties(height=height, background="transparent")
            .configure_view(strokeWidth=0)
            .configure_axis(labelColor=C_MUTED, titleColor=C_MUTED, gridColor="rgba(245,166,35,0.08)",
                            domainColor="rgba(245,166,35,0.22)", labelFont="Fira Code, monospace", titleFont="Fira Code, monospace",
                            labelFontSize=10, titleFontSize=10)
            .configure_legend(labelColor=C_MUTED, titleColor=C_MUTED, labelFont="Fira Code, monospace", titleFont="Fira Code, monospace")
            .configure_title(color=C_ACCENT, font="Orbitron, sans-serif", fontSize=11, anchor="start"))


def line_chart(df: pd.DataFrame, x: str, ys: List[str], height: int = 200, title: str = "",
               colors: Optional[List[str]] = None, y_fmt: str = "") -> None:
    long = df[[x] + ys].melt(x, var_name="series", value_name="value").dropna()
    enc_y = alt.Y("value:Q", title=None, axis=alt.Axis(format=y_fmt) if y_fmt else alt.Axis())
    ch = alt.Chart(long, title=title).mark_line(strokeWidth=1.6).encode(
        x=alt.X(f"{x}:{'T' if np.issubdtype(df[x].dtype, np.datetime64) else 'Q'}", title=None),
        y=enc_y,
        color=alt.Color("series:N", scale=alt.Scale(domain=ys, range=(colors or [C_ACCENT, C_BLUE, C_GREEN, C_RED, C_MUTED, C_ACCENT2])[:len(ys)]),
                        legend=alt.Legend(orient="top", title=None) if len(ys) > 1 else None),
        tooltip=[x, "series", alt.Tooltip("value:Q", format=".3f")])
    show_chart(_alt(ch, height))


def rail_chart(dates: pd.Series, states: pd.Series, flags: Optional[pd.Series] = None, height: int = 124,
               title: str = "") -> None:
    """One cell per session, colored by state (ordinal x avoids temporal x2 quirks)."""
    d = pd.DataFrame({"date": pd.to_datetime(pd.Series(dates)).dt.strftime("%Y-%m-%d").values,
                      "state": pd.Series(states).astype(str).values})
    d["i"] = np.arange(len(d))
    if flags is not None:
        d.loc[np.asarray(flags, dtype=float) > 0, "state"] = "LARGE DAY"
    cmap = {**REGIME_COLOR, "LARGE DAY": C_RED, "ACTIVE": "#5a2a24", "QUIET": "#1e3a2f"}
    doms = [s for s in cmap if s in set(d["state"])]
    ticks = d["i"][:: max(1, len(d) // 6)].tolist()
    ch = alt.Chart(d, title=title).mark_rect().encode(
        x=alt.X("i:O", title=None, axis=alt.Axis(values=ticks, labelExpr=f"{json.dumps(dict(zip(d['i'].astype(str), d['date'])))}[datum.value]",
                                                  labelAngle=0, ticks=False)),
        color=alt.Color("state:N", scale=alt.Scale(domain=doms, range=[cmap[s] for s in doms]),
                        legend=alt.Legend(orient="right", title=None)),
        tooltip=["date", "state"])
    show_chart(_alt(ch, height))


def zbar_chart(df: pd.DataFrame, label: str, value: str, height: int = 240, title: str = "") -> None:
    d = df[[label, value]].copy()
    d["sign"] = np.where(d[value] >= 0, "up", "down")
    ch = alt.Chart(d, title=title).mark_bar().encode(
        y=alt.Y(f"{label}:N", sort=None, title=None), x=alt.X(f"{value}:Q", title=None),
        color=alt.Color("sign:N", scale=alt.Scale(domain=["up", "down"], range=[C_GREEN, C_RED]), legend=None),
        tooltip=[label, alt.Tooltip(f"{value}:Q", format="+.2f")])
    rule = alt.Chart(pd.DataFrame({"x": [0]})).mark_rule(color=C_MUTED).encode(x="x:Q")
    show_chart(_alt(ch + rule, height))


