    sb.markdown("---")
    drop_partial = sb.checkbox("Drop today's unfinished bar before 16:15 ET", value=True)
    literal = sb.checkbox("Paper-literal alpha formulas (dollar terms)", value=False,
                          help="Off = price-neutral restatement (v2). On = the formulas exactly as published.")
    min_group = int(sb.number_input("Min names per industry group", min_value=2, value=5, step=1))
    vol_gate = sb.radio("Name cluster vol gate", ["absolute", "relative"], horizontal=True,
                        help="absolute: HV20 >= 55% on / < 40% cool (original). relative: own 1y HV20 percentile >= 90th on / < 60th cool.")
    drift = sb.radio("Strike/hit GBM drift", ["zero", "historical"], horizontal=True,
                     help="zero log drift is the neutral baseline; historical uses the 5y mean log return.")
    with sb.expander("Name filters and refuse list"):
        px_min = st.number_input("Min price", value=15.0, step=1.0)
        px_max = st.number_input("Max price", value=800.0, step=10.0)
