def _board_color(pct_: float) -> str:
    if pct_ >= 0.80:
        return "#2f7a52"
    if pct_ >= 0.25:
        return "#24503b"
    if pct_ > -0.25:
        return "#22242c"
    if pct_ > -0.80:
        return "#5a2a30"
    return "#8a2f3a"


def _env_kind(env: str) -> str:
    return {"TREND UP": "up", "TREND DOWN": "dn", "BALANCE": "bal"}.get(env, "")


def _lbr_card(r: Dict[str, Any], board_pct: float) -> str:
    chips = "".join(f"<span class='lchip {k}'>{_esc(t)}</span>" for t, k in
                    ((r["env"], _env_kind(r["env"])), (r["pc"], "pc"), (r["sma5_state"], ""), (r["osc_state"], "")))
    rows = [("Taylor", r["taylor"]), ("Rhythm", r["rhythm"]), ("5-SMA", f"{r['sma_streak']:+d} closes, 2d ROC {r['roc2']:+.2f}%"),
            ("Sell", r["sells"][0]), ("Weekly", r["weekly"]),
            ("ADX 14", f"{r['adx']:.1f} {'rising' if r['adx_rising'] else 'falling'}, +DI {r['pdi']:.0f} / -DI {r['mdi']:.0f}"),
            ("Pivots", f"yday H {r['prev_high']:,.2f}, L {r['prev_low']:,.2f}"), ("Gap", f"{r['gap_pct']:+.2f}%"),
            ("Carry", r["carry"]), ("Play", r["play"])]
    dl = "".join(f"<dt>{_esc(a)}</dt><dd>{_esc(b)}</dd>" for a, b in rows)
    ul = "".join(f"<li>{_esc(s)}</li>" for s in r["setups"]) or "<li>none armed</li>"
    return (f"<div class='lcard'><div class='lcard-hd'><div><div class='lcard-t'>{_esc(r['name'])} "
            f"<span class='lcard-m'>{_esc(r['symbol'])}</span></div><div class='lcard-m'>{_esc(r['date'])}, close {r['close']:,.2f}</div></div>"
            f"<div class='lcard-p' style='background:{_board_color(board_pct)}'>{board_pct:+.2f}%</div></div>"
            f"<div class='lchips'>{chips}</div><div class='lcard-s'>{_esc(r['sentence'])}</div><dl>{dl}</dl><ul>{ul}</ul></div>")


def render_lbr(cfg, uni_bars: Dict[str, pd.DataFrame], snap: Optional[pd.DataFrame]) -> None:
    md(LBR_CSS)
    src = cfg["source"]
    opts = ["futures", "proxies"]
    mode = st.radio("Desk instruments", opts, index=0 if src != "massive" else 1, horizontal=True, key="lbr_mode",
                    format_func={"futures": "Futures (Yahoo continuous front month)",
                                 "proxies": f"ETF proxies ({src})"}.get)
    if mode == "futures":
        desk = [(fut, name, grp, pc) for fut, _, name, grp, pc in LBR_DESK]
        fsrc = "demo" if src == "demo" else "yahoo"
    else:
        desk = [(etf, name, grp, pc) for _, etf, name, grp, pc in LBR_DESK if etf]
        fsrc = src
    rs = [(t, t, "etf" if t not in ("IBM", "DE") else "stock", "RS") for t in LBR_RS]
    syms = list(dict.fromkeys([d[0] for d in desk] + [r[0] for r in rs]))
    prog = st.progress(0.0, text="Desk")
    done_bars, _ = get_bars(syms, 600, fsrc, cfg["key"], True, prog, "Desk")
    live_bars, _ = get_bars(syms, 600, fsrc, cfg["key"], False, None, "")
    prog.empty()
    rows, boards = [], {}
    for sym, name, grp, pc in desk + rs:
        if sym not in done_bars or len(done_bars[sym]) < 140:
            continue
        try:
            rows.append(memo(("lbr", sym, str(done_bars[sym].index[-1]), len(done_bars[sym])),
                             lambda s=sym, n=name, g=grp, p=pc: lbr_snapshot(s, n, g, p, done_bars[s])))
            boards[sym] = lbr_board_cell(live_bars.get(sym, done_bars[sym]))
        except Exception as e:
            st.caption(f"{sym}: {type(e).__name__}: {e}")
    if not rows:
        warnbox("No desk data. Futures need Yahoo (internet); proxies need the main data source.")
        return
    desk_rows = [r for r in rows if r["sleeve"] != "RS"]
    n_trend = sum(r["env"].startswith("TREND") for r in desk_rows)
    n_bal = sum(r["env"] == "BALANCE" for r in desk_rows)
    n_armed = sum(bool(r["setups"]) for r in desk_rows)
    es = next((r for r in desk_rows if r["sleeve"] == "PC1"), None)
    if es:
        md(hero_html(es["env"], {"TREND UP": C_GREEN, "TREND DOWN": C_RED, "BALANCE": C_ACCENT}.get(es["env"], C_MUTED),
                     f"S&P, the only day-trade market. Route {es['pc']}.", es["sentence"]))
    kpi_row([kpi_html("In trend", n_trend, "ADX >= 30 rising, DI and 20 EMA agree"),
             kpi_html("In balance", n_bal, "ADX under 20: fade the extremes"),
             kpi_html("Armed", n_armed, "instruments with at least one setup"),
             kpi_html("Bar date", desk_rows[0]["date"], "signals use completed bars; the board uses the live bar")])
    if mode == "futures" and src == "massive":
        note("Futures come from Yahoo (Massive Starter has no futures). Continuous front-month series carry roll gaps "
             "that can distort ADX, ATR and swings around expiries.")

    sec("Color board: % off today's open")
    cells = []
    for r in sorted(rows, key=lambda x: boards.get(x["symbol"], (0, ""))[0], reverse=True):
        pct_, _ = boards.get(r["symbol"], (0.0, ""))
        cells.append(f"<div class='lbr-sq' style='background:{_board_color(pct_)}'><b>{_esc(r['name'])}</b>"
                     f"<span>{pct_:+.2f}%</span><em>{_esc(r['sma5_state'])}</em></div>")
    md("<div class='lbr-board'>" + "".join(cells) + "</div>")

    sec("Outlook")
    flt = st.radio("Show", ["armed", "all"], horizontal=True, key="lbr_flt",
                   format_func={"armed": "Armed or routed", "all": "Every instrument"}.get)
    show = [r for r in desk_rows if flt == "all" or r["setups"] or not r["pc"].startswith("SIT")]
    htmls = [_lbr_card(r, boards.get(r["symbol"], (0.0, ""))[0]) for r in show]
    cols = st.columns(2)
    for i, h in enumerate(htmls):
        cols[i % 2].markdown(h, unsafe_allow_html=True)

    c1, c2 = st.columns(2)
    with c1:
        sec("5-SMA night sheet")
        def night(r):
            if r["sma_flip"]:
                return "Model flipped " + ("up: long candidate at the open" if r["sma_streak"] > 0 else "down: short or stand aside")
            if abs(r["sma_streak"]) >= 3:
                return "Persistence " + ("long" if r["sma_streak"] > 0 else "short") + ": leave it, check tonight"
            return "No persistence yet"
        ns = pd.DataFrame([{"name": r["name"], "streak": r["sma_streak"], "state": r["sma5_state"], "night action": night(r)}
                           for r in sorted(rows, key=lambda x: x["sma_streak"])])
        show_df(ns, height=360)
    with c2:
        sec("Relative strength 1 / 20 / 120 vs SPY")
        spy = next((r for r in rows if r["symbol"] in ("SPY", "ES=F")), None)
        rsr = []
        for r in rows:
            if not np.isfinite(r["ret_120"]) or spy is None:
                continue
            e20, e120 = r["ret_20"] - spy["ret_20"], r["ret_120"] - spy["ret_120"]
            job = ("momentum leader" if e120 > 0 and e20 > 0 else "leader on a pullback: 5-SMA check" if e120 > 0 else
                   "laggard bounce: not the RS book" if e20 > 0 else "laggard")
            rsr.append({"name": r["name"], "1d %": r["ret_1"], "20d excess %": e20, "120d excess %": e120, "job": job})
        show_df(pd.DataFrame(rsr).sort_values("120d excess %", ascending=False), height=360,
                column_config={k: st.column_config.NumberColumn(format="%+.2f") for k in ("1d %", "20d excess %", "120d excess %")})

    sec("Setup scoreboard: do these rules carry an edge here?")
    c = st.columns(5)
    scope = c[0].radio("Scope", ["desk", "universe"], key="lbr_scope",
                       format_func={"desk": "Desk instruments", "universe": "Stock universe (top composite)"}.get)
    n_u = c[1].slider("Universe names", 20, 300, 100, 20, key="lbr_nu", disabled=scope == "desk")
    hz = c[2].selectbox("Horizon (sessions)", [1, 2, 3, 5], index=2, key="lbr_h")
    bar = c[3].selectbox("Target / stop (ATR)", [0.5, 1.0, 1.5], index=1, key="lbr_b")
    ent = c[4].radio("Entry", ["next_open", "signal_close"], key="lbr_e",
                     format_func={"next_open": "Next open", "signal_close": "Signal close"}.get)
    if st.button("Score the setups"):
        if scope == "desk":
            frames = {s: done_bars[s] for s, *_ in desk if s in done_bars}
        else:
            names = (list(snap["composite"].dropna().sort_values(ascending=False).index[:n_u]) if snap is not None
                     else list(uni_bars)[:n_u])
            frames = {s: uni_bars[s] for s in names if s in uni_bars}
        with st.spinner(f"Scoring {len(frames)} instruments"):
            st.session_state["lbr_score"] = {"tab": lbr_scoreboard(frames, int(hz), float(bar), ent),
                                             "meta": f"{scope}, {len(frames)} instruments, {hz}-session horizon, "
                                                     f"{bar} ATR target and stop, entry {ent.replace('_', ' ')}"}
    sc = st.session_state.get("lbr_score")
    if sc and len(sc["tab"]):
        note(sc["meta"])
        P = st.column_config.NumberColumn
        show_df(sc["tab"], column_config={
            "p_target_first": P("P(target first)", format="percent"), "ci_lo": P("95% lo", format="percent"),
            "ci_hi": P("95% hi", format="percent"), "p_neither": P("neither", format="percent"),
            "mean_ret_atr": P("mean close-out (ATR)", format="%+.3f"), "lift_vs_baseline": P("lift", format="%+.3f"),
            "kelly_risk": P("Kelly risk (shrunk)", format="percent"), "kelly_shrink": P("shrink", format="%.2f")})
        note("Each setup's hit rate is compared with taking the same side on every day. Lift near zero means the rule "
             "adds nothing over a random entry here. Kelly risk is the share of bankroll to risk per trade for a "
             "symmetric 1:1 bracket, after the Baker-McHale shrink; most rules will not earn one. Events overlap and "
             "eight rules are tested at once, so treat small lifts as noise.")
    else:
        note("Runs every rule on history and measures whether price reached the target before the stop. "
             "This is the step the original desk skipped: it turns the rules into numbers Kelly can size.")

    with st.expander("How a day is read (her public rules)"):
        md("<ol class='note'>" + "".join(f"<li>{_esc(x)}</li>" for x in LBR_RULES) + "</ol>")
    with st.expander("Five sell rules, every desk instrument"):
        show_df(pd.DataFrame([{"name": r["name"], "box position": r["box_pos"], "sell rules": " | ".join(r["sells"])}
                              for r in desk_rows]),
                column_config={"box position": st.column_config.NumberColumn(format="percent")})
    with st.expander("Public tape: your notes on her posts"):
        tape = load_lbr_tape()
        if tape.empty:
            tape = pd.DataFrame(LBR_SEED_TAPE, columns=["date", "market", "note"])
        edited = st.data_editor(tape, num_rows="dynamic", key="lbr_tape_ed", hide_index=True)
        if st.button("Save tape"):
            save_lbr_tape(edited)
            st.caption(f"Saved {len(edited)} rows to {LBR_TAPE_FILE.name}.")
    note("Educational reconstruction of Linda Raschke's public framework (Street Smarts; The New Market Wizards; "
         "TraderLion sessions). Not her book, not a live signal, not affiliated.")


TREND_POINT_VALUE = {"ES=F": 50, "NQ=F": 20, "RTY=F": 50, "YM=F": 5, "GC=F": 100, "SI=F": 5000, "HG=F": 25000, "CL=F": 1000,
                     "RB=F": 42000, "NG=F": 10000, "ZB=F": 1000, "ZN=F": 1000, "ZC=F": 50, "ZW=F": 50, "6E=F": 125000,
                     "6J=F": 12500000, "6M=F": 500000, "DX-Y.NYB": 1000}     # standard contracts; Yahoo grain prices are in cents
TREND_SYS_COLOR = {"Turtle S1": "#5b8dee", "Turtle S2": "#9085e9", "EMA cross": "#c97d1e"}
TREND_GUIDE = """
#### What runs here
* **Turtle System 1 (Richard Dennis)**: buy when price trades above the prior 20-day high; sell when it trades below
  the prior 10-day low; the stop starts 2N under the entry (N = 20-day Wilder average true range). A breakout is skipped
  when the previous System 1 breakout, taken or not, made money: the published filter.
* **Turtle System 2**: 55-day breakout, 20-day exit, same 2N stop, no filter.
* **EMA crossover (Seykota-style)**: buy at the next open after the fast EMA closes above the slow one; sell at the next
  open after it closes back under, or at a stop k ATR under the entry. Seykota describes exponential-average systems;
  the lengths here are inputs, not his settings.
* **Shorts** run the same rules on the price series turned upside down.

#### How to read it
Trend following wins rarely and big: the expectancy map puts these systems bottom right, and the R histogram shows a
long right tail. The whole edge sits in a few trades, so the share of net R from the best 5% is often above 100%,
losing runs are long, and Kelly with the shrink is small. That is Seykota's "keep bets small" in numbers. The desk
runs on the futures (or ETF proxies) the LBR desk uses; the universe runs on stocks, long only by default. Breakouts in
the Setup ledger (the Trend family) use the same entries with the ledger's own stop, target and time limit, so the two
can be compared.

#### Limits
One unit per signal (no pyramiding), daily bars (a level touched intraday fills there), continuous front-month futures
carry roll gaps, and the stock universe is today's list, so survivorship lifts it.
"""


def _trend_frames(cfg, scope: str, uni_bars: Dict[str, pd.DataFrame], snap: Optional[pd.DataFrame], n_u: int
                  ) -> Tuple[Dict[str, pd.DataFrame], Dict[str, str], str]:
    if scope == "desk":
        src = cfg["source"]
        mode = st.session_state.get("lbr_mode", "futures" if src != "massive" else "proxies")
        if mode == "futures":
            pairs, fsrc = [(fut, name) for fut, _, name, _, _ in LBR_DESK], ("demo" if src == "demo" else "yahoo")
        else:
            pairs, fsrc = [(etf, name) for _, etf, name, _, _ in LBR_DESK if etf], src
        got, _ = get_bars([p_[0] for p_ in pairs], UNIVERSE_DAYS, fsrc, cfg["key"], True)
        names = {p_[0]: p_[1] for p_ in pairs}
        return {t: got[t] for t, _ in pairs if t in got}, names, f"desk {mode} ({fsrc})"
    order = (list(snap["composite"].dropna().sort_values(ascending=False).index) if snap is not None and len(snap) else list(uni_bars))
    pick = [t for t in order if t in uni_bars][:int(n_u)]
    return {t: uni_bars[t] for t in pick}, {t: t for t in pick}, f"stock universe, {len(pick)} names"


def trend_summary(T: pd.DataFrame, calendar: pd.DatetimeIndex) -> pd.DataFrame:
    """One row per system x side: the distribution of closed, taken trades in R, Kelly, path and overlap."""
    rows = []
    done = T[~T["open"].astype(bool) & T["taken"].astype(bool)] if len(T) else T
    for (sysk, sd), g in done.groupby(["system", "side"], sort=False):
        g = g.sort_values("entry_date")
        r = g["r"].to_numpy(float)
        e = calendar.searchsorted(pd.DatetimeIndex(g["entry_date"]))
        x = calendar.searchsorted(pd.DatetimeIndex(g["exit_date"]))
        rows.append({"key": sysk, "side": sd, "setup": f"{TREND_SHORT[sysk]} {'long' if sd > 0 else 'short'}",
                     "family": TREND_SHORT[sysk], **expectancy_stats(r, n_eff=g["entry_date"].nunique()), **r_path_stats(r),
                     "open": open_at_once(e, x - e + 1), "hold_med": float(np.median(g["exit_i"] - g["entry_i"] + 1)),
                     "names": g["ticker"].nunique()})
    S = pd.DataFrame(rows)
    if len(S):
        S["kelly_trade"] = S["kelly_shrunk"] / S["open"].clip(lower=1).fillna(1)
    return S


def render_trend(cfg, uni_bars: Dict[str, pd.DataFrame], snap: Optional[pd.DataFrame]) -> None:
    sec("Trend systems: Dennis's Turtles and a Seykota-style crossover, each traded with its own exits")
    for k_, v_ in TREND_DEFAULTS.items():
        st.session_state.setdefault(k_, v_)
    c = st.columns([1.6, 1, 1.8, 1.2])
    scope = c[0].radio("Instruments", ["desk", "universe"], key="tr_scope",
                       format_func={"desk": "Desk (as on the LBR desk)", "universe": "Stock universe"}.get)
    n_u = int(c[1].number_input("Universe names", 20, 2000, 200, 20, key="tr_nu", disabled=scope == "desk"))
    systems = c[2].multiselect("Systems", list(TREND_SYSTEMS), default=list(TREND_SYSTEMS), key="tr_sys",
                               format_func=TREND_SYSTEMS.get)
    sides_txt = c[3].radio("Sides", ["long", "both"], key="tr_sides", index=1 if scope == "desk" else 0,
                           format_func={"long": "Long only", "both": "Long and short"}.get)
    with st.expander("System settings"):
        c2 = st.columns(5)
        c2[0].number_input("Fast EMA", 5, 100, step=1, key="tr_fast")
        c2[1].number_input("Slow EMA", 50, 400, step=10, key="tr_slow")
        c2[2].number_input("Crossover stop (ATR)", 1.0, 10.0, step=0.5, key="tr_k")
        c2[3].number_input("Costs (bp per side)", 0.0, 100.0, step=1.0, key="tr_cost")
        c2[4].checkbox("System 1 last-breakout filter", key="tr_filter")
    prm = {k: st.session_state[k] for k in TREND_DEFAULTS}
    if st.button("Run the systems", key="tr_go"):
        if not systems:
            warnbox("Pick at least one system.")
        else:
            frames, names, lab = _trend_frames(cfg, scope, uni_bars, snap, n_u)
            if not frames:
                warnbox(f"No bars loaded for the {lab}. Check the data source in the sidebar, or switch the instruments.")
            sides = [1] if sides_txt == "long" else [1, -1]
            with st.spinner(f"Running {len(systems)} systems on {len(frames)} instruments"):
                T = trend_run(frames, systems, sides, prm)
            cal = pd.DatetimeIndex(sorted(set().union(*[set(df.index) for df in frames.values()]))) if frames else pd.DatetimeIndex([])
            st.session_state["tr_res"] = {"T": T, "frames": frames, "names": names, "label": lab, "prm": dict(prm),
                                          "sides": sides, "systems": list(systems), "cal": cal,
                                          "S": trend_summary(T, cal) if len(T) else pd.DataFrame()}
    res = st.session_state.get("tr_res")
    if not res or res["T"] is None or not len(res["T"]):
        note("Runs each system on every instrument with its own entries and exits (no target, no time limit), one unit "
             "per signal, and scores the trades in R the way the Expectancy & Kelly tab scores ledger setups.")
        with st.expander("How the systems work"):
            st.markdown(TREND_GUIDE)
        return
    T, S = res["T"], res["S"]
    if S.empty:
        warnbox("No closed trades yet: load more history.")
        return
    kc = cfg.get("kelly") or {}
    cal = res["cal"]
    yrs = (cal[-1] - cal[0]).days / 365.25 if len(cal) > 1 else np.nan
    best = S.sort_values("er", ascending=False).iloc[0]
    kpi_row([kpi_html("Instruments", len(res["frames"]), res["label"]),
             kpi_html("Closed trades", f"{int(S['n'].sum()):,}", f"over {yrs:.1f} years" if np.isfinite(yrs) else ""),
             kpi_html("Best expectancy", f"{_n(best['er']):+.2f}R", str(best["setup"]), "good" if _n(best["er"]) > 0 else "bad"),
             kpi_html("Its win rate", pct(best["win"]), f"payoff {_n(best['payoff'], np.nan):.1f}; breakeven {pct(best['be_win'])}"),
             kpi_html("Top 5% of its trades", pct(best["tail5"]) if np.isfinite(_n(best["tail5"], np.nan)) else "n/a",
                      "share of the net R", "warn" if _n(best["tail5"], 0) > 1 else ""),
             kpi_html("Open now", int(T["open"].sum()), "trades running at the last bar")])
    doms = [k for k in TREND_SYS_COLOR if k in set(S["family"])]
    ch = expectancy_map(S, "family", doms, [TREND_SYS_COLOR[k] for k in doms],
                        f"{int((S['margin'] > 0).sum())} of {len(S)} system and side pairs sit above breakeven",
                        "setup", pd.Series(True, index=S.index), 380)
    if ch is not None:
        show_chart(ch)
    P_ = st.column_config.NumberColumn
    cols = {"setup": "System", "n": "Trades", "names": "Instruments", "win": "Win rate", "be_win": "Breakeven win rate",
            "avg_win": "Avg win (R)", "avg_loss": "Avg loss (R)", "payoff": "Payoff ratio", "er": "E[R]", "kelly": "Kelly, full",
            "kelly_shrunk": "Kelly, shrunk", "open": "Open at once", "kelly_trade": "Shrunk Kelly per open trade",
            "tail5": "Top 5% / net R", "big3": "Trades >= 3R", "streak": "Longest losing run", "dd_r": "Worst drawdown (R)",
            "hold_med": "Median hold"}
    show_df(S[list(cols)].rename(columns=cols), column_config={
        "Trades": P_(format="%d"), "Instruments": P_(format="%d"), "Win rate": P_(format="percent"),
        "Breakeven win rate": P_(format="percent"), "Avg win (R)": P_(format="%.2f"), "Avg loss (R)": P_(format="%.2f"),
        "Payoff ratio": P_(format="%.2f"), "E[R]": P_(format="%+.2f"), "Kelly, full": P_(format="percent"),
        "Kelly, shrunk": P_(format="percent"), "Open at once": P_(format="%.1f"), "Shrunk Kelly per open trade": P_(format="percent"),
        "Top 5% / net R": P_(format="percent"), "Trades >= 3R": P_(format="percent"), "Longest losing run": P_(format="%d"),
        "Worst drawdown (R)": P_(format="%.1f"), "Median hold": P_(format="%d")})
    note("R is profit over the initial risk (2N for the Turtles, the ATR stop for the crossover), after costs. Trend systems "
         "should sit bottom right on the map: low win rate, high payoff. Shrunk Kelly per open trade is the stake per "
         "unit when the usual number of positions run together.")

    sec("One system: its distribution of outcomes and its bankroll")
    pick = st.selectbox("System", list(S["setup"]), key="tr_pick")
    row = S[S["setup"] == pick].iloc[0]
    g = T[(T["system"] == row["key"]) & (T["side"] == row["side"]) & ~T["open"].astype(bool) & T["taken"].astype(bool)]
    g = g.sort_values("entry_date")
    r = g["r"].to_numpy(float)
    kf, kt = _n(row["kelly"], 0.0), _n(row["kelly_trade"], 0.0)
    c = st.columns([1, 1, 3])
    f_in = c[0].number_input("Stake per trade, % of equity at the initial stop", 0.01, 25.0,
                             round(max(min(kt if kt > 0 else 0.005, 0.25), 0.0001) * 100, 2), 0.05, key=f"tr_f_{pick}") / 100.0
    lad_on = c[1].checkbox("Drawdown ladder (5% / 8% / 15%)", False, key="tr_lad")
    c1, c2 = st.columns(2)
    with c1:
        show_chart(_exp_hist(g, f"{pick}: wins {pct(row['win'])} of {len(g):,} trades, {_n(row['avg_win']):.2f}R won vs "
                                f"{_n(row['avg_loss']):.2f}R lost"))
    with c2:
        ch = _exp_growth(r, {"full Kelly": kf, "half Kelly": kf / 2, "2x Kelly": 2 * kf, "your stake": f_in},
                         "Growth peaks at Kelly and falls fast past it (Thorp)")
        if ch is not None:
            show_chart(ch)
    sim = simulate_dated(g["entry_date"], g["exit_date"], r, f_in, EXP_LADDER if lad_on else None)
    kpi_row([kpi_html("Compound return", f"{pct(sim['cagr'], 1)} a year" if np.isfinite(_n(sim["cagr"], np.nan)) else f"{sim['final']:.2f}x",
                      f"{sim['final']:.2f}x over {_n(sim['years'], 0):.1f} years"),
             kpi_html("Worst drawdown", pct(sim["maxdd"]), "on one bankroll, marked at exits", "bad" if sim["maxdd"] >= 0.2 else ""),
             kpi_html("Risk open at once", pct(f_in * _n(row["open"], 1), 1), f"stake x {_n(row['open'], 1):.1f} open on average",
                      "bad" if f_in * _n(row["open"], 1) > 0.10 else ""),
             kpi_html("Trades skipped", f"{sim['skipped']:,}", "by the ladder" if lad_on else "ladder off")])
    if len(sim["dates"]):
        eqd = pd.DataFrame({"date": sim["dates"], "equity": sim["path"]})
        ch = alt.Chart(eqd, title="Equity on one bankroll (log scale)").mark_line(color=C_ACCENT, strokeWidth=1.6).encode(
            x=alt.X("date:T", title=None),
            y=alt.Y("equity:Q", title="equity (start = 1)", scale=alt.Scale(type="log", domain=[max(1e-3, float(eqd["equity"].min()) * 0.97),
                                                                                                float(eqd["equity"].max()) * 1.03], nice=False)),
            tooltip=[alt.Tooltip("date:T", format="%Y-%m-%d"), alt.Tooltip("equity:Q", format=".3f")])
        show_chart(_alt(ch, 240))

    sec("Today: where each instrument stands")
    eq_ = float(kc.get("bankroll", 100000.0))
    risk_u = st.columns([1, 4])[0].number_input("Risk per unit at the stop, % of equity", 0.1, 5.0, 1.0, 0.1, key="tr_risk_u") / 100.0
    rows = []
    for tk, df in res["frames"].items():
        tt = T[T["ticker"] == tk]
        st_ = trend_now(df, tt, row["key"], int(row["side"]), res["prm"])
        if not np.isfinite(_n(st_["N"], np.nan)):
            continue
        risk_pts = 2.0 * st_["N"] if row["key"] != "seykota" else float(res["prm"]["tr_k"]) * st_["N"]
        pv = TREND_POINT_VALUE.get(tk, 1.0)
        units = eq_ * risk_u / (risk_pts * pv) if risk_pts > 0 else np.nan
        lvl = st_["trigger"] if st_["state"] == "flat" else st_["exit_lvl"]
        rows.append({"instrument": res["names"].get(tk, tk), "symbol": tk, "state": st_["state"],
                     "since": pd.Timestamp(st_["since"]).date() if st_["since"] is not None else None,
                     "close": st_["close"], "entry": st_["entry"], "level": lvl,
                     "level_is": "entry trigger" if st_["state"] == "flat" and row["key"] != "seykota" else
                                 ("EMA cross" if st_["state"] == "flat" else "exit / stop"),
                     "dist": (lvl / st_["close"] - 1) if np.isfinite(_n(lvl, np.nan)) and st_["close"] else np.nan,
                     "R_now": st_["r_now"], "N": st_["N"], "units": units})
    if rows:
        now = pd.DataFrame(rows)
        now["_o"] = now["state"].map({"LONG": 0, "SHORT": 0}).fillna(1)
        now = now.sort_values(["_o", "dist"], key=lambda x: x.abs() if x.name == "dist" else x).drop(columns="_o")
        show_df(now, height=min(560, 40 + 35 * len(now)), column_config={
            "close": P_(format="%.4g"), "entry": P_(format="%.4g"), "level": P_(format="%.4g"), "dist": P_("distance", format="percent"),
            "R_now": P_("open R", format="%+.2f"), "N": P_(format="%.4g"), "units": P_("units (shares or contracts)", format="%.3g"),
            "level_is": st.column_config.TextColumn("level is")})
        note(f"Units risk {risk_u * 100:.1f}% of ${eq_:,.0f} (the sidebar bankroll) at the initial stop: shares for stocks and "
             "ETFs, standard contracts for futures (point values: ES 50, GC 100, CL 1,000, ...; Yahoo quotes grains in cents; "
             "a fraction of a contract means the micro contract or a smaller unit). "
             "The original Turtles sized one unit so a 1N move was 1% of equity, which puts 2% at the 2N stop.")
    with st.expander("How the systems work"):
        st.markdown(TREND_GUIDE)


def render_rs8(cfg, uni_bars: Dict[str, pd.DataFrame], bench_bars: Dict[str, pd.DataFrame]) -> None:
    c = st.columns([1.2, 2.2, 1, 1, 1])
    src_list = c[0].radio("List", ["custom", "universe"], key="rs8_src",
                          format_func={"custom": "Watchlist", "universe": "Whole universe"}.get)
    st.session_state.setdefault("rs8_txt", ", ".join(RS8_DEFAULT_LIST))
    txt = c[1].text_area("Watchlist tickers", height=80, key="rs8_txt", disabled=src_list == "universe")
    near_band = c[2].number_input("Near 10/20/50, +/- %", 1.0, 10.0, 4.5, 0.5, key="rs8_near")
    p_lo = c[3].number_input("Pocket low %", -10.0, 0.0, -3.0, 0.5, key="rs8_plo")
    p_hi = c[4].number_input("Pocket high %", 1.0, 15.0, 6.0, 0.5, key="rs8_phi")
    if src_list == "universe":
        bars = uni_bars
    else:
        names = [t for t in (_clean_ticker(x) for x in txt.replace("\n", ",").split(",")) if t]
        have = {t: uni_bars[t] for t in names if t in uni_bars}
        need = [t for t in names if t not in have]
        if need:
            fetched, _ = get_bars(need, UNIVERSE_DAYS, cfg["source"], cfg["key"], cfg["drop_partial"])
            have.update(fetched)
        bars = have
    spy = (bench_bars.get("SPY") if "SPY" in bench_bars else uni_bars.get("SPY"))
    if spy is None or not bars:
        warnbox("Needs SPY and at least one name with a year of daily bars.")
        return
    key = ("rs8", tuple(sorted(bars)), str(spy.index[-1]), near_band, p_lo, p_hi)
    tab, charts = memo(key, lambda: rs8_table(bars, spy["close"], near_band, (p_lo, p_hi)))
    if tab.empty:
        warnbox("No name has the 260 sessions the RS-line high needs.")
        return
    counts = {k: int(fn(tab).sum()) for k, (_, fn) in RS8_PRESETS.items()}
    preset = st.radio("Preset", list(RS8_PRESETS), horizontal=True, key="rs8_preset",
                      format_func=lambda k: f"{RS8_PRESETS[k][0]} ({counts[k]})")
    view = tab[RS8_PRESETS[preset][1](tab).astype(bool)]
    kpi_row([kpi_html("RS-line high", counts["blue"], "RS line at its 252-day high vs SPY", "info"),
             kpi_html("On breakout", counts["break"], "RS-line high with price at a 252-day high", "info"),
             kpi_html("8-week pocket", counts["pocket"], f"{p_lo:+.0f}% to {p_hi:+.0f}% vs a rising 8-week EMA", "warn"),
             kpi_html("ChartMaster", counts["cm"], "pocket plus an RS-line high", "warn"),
             kpi_html("BoxTrader", counts["box"], "near an average, 10 > 20, broke yesterday", "good"),
             kpi_html("Showing", len(view), f"of {len(tab)} names")])
    if view.empty:
        note("No names match this preset.")
        return
    c1, c2 = st.columns([1, 1])
    with c1:
        d = view.reset_index()
        d["group"] = np.where(d["rs_nh_252"], "RS-line high", np.where(d["in_8w_pocket"], "8-week pocket",
                              np.where(d["boxtrader_trigger"], "BoxTrader trigger", "neither")))
        dom = ["RS-line high", "8-week pocket", "BoxTrader trigger", "neither"]
        pts = alt.Chart(d, title="Extension vs the 8-week EMA (x) and RS excess vs SPY (y)").mark_circle(size=70, opacity=0.9).encode(
            x=alt.X("ext_8w:Q", title="% vs 8-week EMA"), y=alt.Y("rs_excess:Q", title="RS excess vs SPY"),
            color=alt.Color("group:N", scale=alt.Scale(domain=dom, range=[C_BLUE, C_ACCENT, C_GREEN, C_MUTED]),
                            legend=alt.Legend(orient="top", title=None)),
            tooltip=["symbol", alt.Tooltip("ext_8w:Q", format="+.1f"), alt.Tooltip("rs_excess:Q", format="+.1f"), "peer_rs"])
        lbl = alt.Chart(d[d["rs_nh_252"] | d["chartmaster_pullback"]]).mark_text(dx=7, dy=-7, color=C_TEXT, fontSize=10).encode(
            x="ext_8w:Q", y="rs_excess:Q", text="symbol")
        rules = alt.Chart(pd.DataFrame({"x": [p_hi, 15.0], "edge": ["pocket edge", "extended"]})).mark_rule(
            strokeDash=[4, 3], color=C_ACCENT, opacity=0.7).encode(x="x:Q", tooltip=["edge"])
        show_chart(_alt(pts + lbl + rules, 330))
    with c2:
        pick = st.selectbox("Name", list(view.sort_values("peer_rs", ascending=False).index), key="rs8_pick")
        r = tab.loc[pick]
        md(f"<div class='note' style='color:var(--text)'>{_esc(rs8_sentence(r))}</div>")
        ch = charts.get(pick)
        if ch is not None:
            long = ch.melt("date", ["close", "21 EMA", "8-week EMA", "40 EMA", "50 SMA"], var_name="line", value_name="price")
            ln = alt.Chart(long).mark_line(strokeWidth=1.4).encode(
                x=alt.X("date:T", title=None), y=alt.Y("price:Q", title=None, scale=alt.Scale(zero=False)),
                color=alt.Color("line:N", scale=alt.Scale(domain=["close", "21 EMA", "8-week EMA", "40 EMA", "50 SMA"],
                                                          range=[C_TEXT, C_ACCENT2, C_BLUE, C_RED, C_GREEN]),
                                legend=alt.Legend(orient="top", title=None)))
            dots = alt.Chart(ch[ch["rs_nh"]]).mark_circle(size=40, color=C_BLUE).encode(x="date:T", y="close:Q")
            show_chart(_alt(ln + dots, 290))
            note("Blue dots: RS line at a 252-day high that day.")
    cols = ["close", "peer_rs", "rs_excess", "rs_nh_252", "rs_nh_on_breakout", "rs_nh_weekly", "rs_nh_week_forming",
            "ext_8w", "ext_40", "ext_21", "ext_10", "ext_20", "ext_50", "ext21_atr", "ext50_atr", "rsi2", "ibs",
            "st_oversold", "st_stretched", "in_8w_pocket", "chartmaster_pullback",
            "near_10_20_50", "boxtrader_trigger", "hv1_15d", "ud50", "adr20", "sma10_gt_20", "overhead_200"]
    P = st.column_config.NumberColumn
    B = st.column_config.CheckboxColumn
    blabels = {"rs_nh_252": "RS NH 252", "rs_nh_on_breakout": "NH on breakout", "rs_nh_weekly": "RS NH weekly",
               "rs_nh_week_forming": "NH week forming", "in_8w_pocket": "8w pocket", "chartmaster_pullback": "ChartMaster",
               "near_10_20_50": "Near 10/20/50", "boxtrader_trigger": "BoxTrader", "hv1_15d": "HV1 15d",
               "sma10_gt_20": "10 > 20", "overhead_200": "200 overhead", "st_oversold": "Short-term oversold",
               "st_stretched": "Stretched (wait)"}
    show_df(view.sort_values("peer_rs", ascending=False)[cols].reset_index(), height=min(420, 40 + 35 * len(view)),
            column_config={**{k: B(v) for k, v in blabels.items()},
        "close": P(format="%.2f"), "peer_rs": P("Peer RS", format="%.0f"), "rs_excess": P("RS excess %", format="%+.1f"),
        **{k: P(k.replace("ext_", "Ext ").replace("8w", "8w %"), format="%+.1f") for k in cols if k.startswith("ext_")},
        "ud50": P("U/D 50", format="%.2f"), "adr20": P("ADR %", format="%.1f"),
        "ext21_atr": P("21-day, in ATRs", format="%+.1f", help="(close - 21-day EMA) / ATR14: distance measured in the "
                                                                "stock's own daily moves, so names of different volatility compare."),
        "ext50_atr": P("50-day, in ATRs", format="%+.1f"), "rsi2": P("RSI(2)", format="%.0f"),
        "ibs": P("IBS", format="%.2f", help="Where the close sits in the day's range: 0 = the low, 1 = the high.")})
    note("Extension in ATRs: within about 1 ATR of a rising 10/21-day is a buyable zone; 2-3 is stretched (a starter, or "
         "wait); beyond that, and 20%+ over the 50-day (TraderLion's first sell signal), don't initiate. Short-term "
         "oversold (RSI(2) under 10 or IBS under 0.2) in a leader is the Pullback family's setup in the Setup ledger.")
    st.download_button("Download table (CSV)", view.reset_index().to_csv(index=False), "rs_8week.csv", "text/csv",
                       key="rs8_dl")
    note("ChartMaster's buy is the 8-week pocket, not the 50-day; BoxTrader buys a prior-close or prior-high break only "
         "near the 10, 20 or 50. Peer RS ranks inside the list on screen, not an IBD 98. Daily bars only: the first-30-minute "
         "trigger and 30-minute pivot need intraday data. HV1 = highest volume in 252 sessions. Watchlist annotation, not a ticket.")


RSX_SHOW = {"all": "Everything that passes the liquidity gate", "tf5": "All-timeframe leaders (5 of 5 in the top 20%)",
            "held": "Held up: up during the SPY pullback", "first": "First out: 52-week high before SPY recovered",
            "leads": "RS line at a 252-day high before price", "new": "Emerging or accelerating",
            "resil": "Most resilient fifth on down days"}
RSX_SORT = {"leader": "Leader score (time frames + resilience)", "resilience": "Resilience", "IBD": "IBD-style RS rating",
            "tf": "Time frames in the top 20%", "1M": "1-month RS", "corr_rel": "Pullback vs SPY"}
RSX_GUIDE = """
#### What this tab measures
**Relative strength on five time frames.** Each name's return over 1 week, 1 month, 3, 6 and 12 months is ranked
against the whole loaded universe every day, 1 to 99, the way IBD ranks its RS rating; the IBD-style rating
(0.4 x 3-month + 0.2 x each of the 6, 9 and 12-month changes) is the summary. "Time frames in the top 20%" counts how many
of the five horizons rank 80 or better: a 5 is a leader on every clock, a stock with only the 1-week and 1-month boxes
lit is a bounce, not a leader. Trend labels: *emerging* (top 20% over 1 and 3 months, not yet over 12), *accelerating*
(rank rising from 6 months to 3 to 1), *fading* (a 12-month leader below the median this month).

**RS line.** Stock divided by SPY. A 252-day RS-line high while price is still below its own high is O'Neil's leading
tell. Mansfield RS (Weinstein) is the RS line against its 52-week average: above zero and rising belongs in Stage 2.

**Resilience.** On every day SPY fell over the last 63 sessions, how much better the stock did than its *up-day* beta
implies, summed. Up-day and down-day betas come from the prior 252 sessions (SPY up days and down days separately). A
name that rises like a 1.5-beta stock and falls like a 0.5-beta one scores high; a utility that falls as little as it
rises scores about zero. That is the point: a raw "held up" list is mostly low-beta defensives, and stocks with low
downside beta have earned less, not more, on average (Ang, Chen & Xing 2006). What you want is upside participation with
downside that the market's selling can't shake out. Down-day capture is the raw version (under 1 = falls less than SPY). The resilience score averages the ranks of the beta-adjusted read, down-day
capture and the stock's change through the latest SPY pullback against SPY's.

**The pullback window.** By default the deepest SPY decline of the last six months: its peak, then the low after it. *Held
up* means up over that stretch; *first out* means a 52-week closing high after the low while SPY was still below its
peak (leaders come out of corrections first). Pick custom dates to study a specific correction.

**History check.** Each read's rank correlation with the next month's return across your universe at each month-end
(Spearman IC), with a Newey-West t, the top-minus-bottom fifth, and the IC after months when SPY had fallen 3% or more.
Your list was chosen today, so a positive number here is flattered by hindsight; the Setup ledger's whole-market mode
records both "RS time frames" and "resilience" for every trade without that bias (split by them there).

**Caveats.** After sharp declines the first leg of a rebound is often led by the biggest losers (momentum crashes,
Daniel & Moskowitz 2016), so resilient leaders can lag right at the turn and then take over. Momentum itself is the
best-documented anomaly (Jegadeesh & Titman 1993), and nearness to the 52-week high carries much of it (George & Hwang
2004).

#### Sources
William O'Neil, *How to Make Money in Stocks* · Stan Weinstein, *Secrets for Profiting in Bull and Bear Markets* ·
Jegadeesh & Titman (1993), Returns to Buying Winners and Selling Losers, *Journal of Finance* · George & Hwang (2004),
The 52-Week High and Momentum Investing, *Journal of Finance* · Ang, Chen & Xing (2006), Downside Risk, *Review of
Financial Studies* · Daniel & Moskowitz (2016), Momentum Crashes, *Journal of Financial Economics* · Frazzini & Pedersen
(2014), Betting Against Beta, *Journal of Financial Economics* · Blitz, Huij & Martens (2011), Residual Momentum,
*Journal of Empirical Finance*
"""


def render_rs_leaders(cfg, uni: pd.DataFrame, ab, bench_bars: Dict[str, pd.DataFrame]) -> None:
    if ab is None or "SPY" not in bench_bars:
        warnbox("RS leaders needs the universe panel (10+ names) and SPY.")
        return
    C, V = ab["P"]["close"], ab["P"]["volume"]
    spy = bench_bars["SPY"]["close"]
    c = st.columns([1.6, 1.6, 1, 1, 1.6])
    wmode = c[0].radio("Pullback window", ["auto", "custom"], horizontal=True, key="rsx_wmode",
                       format_func={"auto": "Auto (deepest in 6 months)", "custom": "Custom dates"}.get)
    window = None
    if wmode == "custom":
        d1 = C.index[-1].date()
        rng = c[1].date_input("From / to", value=(C.index[-64].date(), d1), min_value=C.index[0].date(), max_value=d1,
                              key="rsx_dates")
        if isinstance(rng, (list, tuple)) and len(rng) == 2:
            window = {"start": rng[0], "end": rng[1]}
    px_min = c[2].number_input("Min price", 0.0, 1000.0, 10.0, 1.0, key="rsx_px")
    dv_min = c[3].number_input("Min $ vol (M)", 0.0, 1000.0, 10.0, 1.0, key="rsx_dv")
    show = c[4].selectbox("Show", list(RSX_SHOW), format_func=RSX_SHOW.get, key="rsx_show")
    wkey = (str(window["start"]), str(window["end"])) if window else ("auto",)
    R = memo(("rsx", str(ab["asof"]), C.shape, str(spy.index[-1])) + wkey, lambda: rs_leaders(C, V, spy, uni, window))
    ic = memo(("rsx_ic", str(ab["asof"]), C.shape, str(spy.index[-1])) + wkey, lambda: rs_ic_test(R))
    T, cw = R["T"], R["cw"]
    liq = T[(T["close"] >= px_min) & (T["dv_m"].fillna(0) >= dv_min)]
    masks = {"all": pd.Series(True, index=liq.index), "tf5": liq["tf"] >= 5,
             "held": liq["corr_chg"] > 0 if "corr_chg" in liq else pd.Series(False, index=liq.index),
             "first": liq["first_out"].astype(bool) if "first_out" in liq else pd.Series(False, index=liq.index),
             "leads": liq["rs_leads"].astype(bool), "new": liq["trend"].isin(["EMERGING", "ACCELERATING"]),
             "resil": liq["resilience"] >= liq["resilience"].quantile(0.8)}
    # ---- headline
    if cw:
        still = cw["trough"] == R["asof"]
        cw_sub = (f"{cw['peak']:%b %d} to {cw['trough']:%b %d} ({cw['sessions']} sessions); "
                  + ("still at its low" if still else f"{cw['since']:+.1%} since" + (", back at the high" if cw["recovered"] else "")))
        k0 = kpi_html("SPY pullback" + (" (custom)" if cw["custom"] else ""), f"{cw['depth']:+.1%}", cw_sub, "bad" if cw["depth"] <= -0.08 else "warn")
    else:
        k0 = kpi_html("SPY pullback", "none", "no decline deeper than 3% in six months; resilience uses down days only", "good")
    ric = ic.set_index("signal").reindex(["Resilience on down days"]) if len(ic) else pd.DataFrame()
    ic_v = _n(ric["mean IC"].iloc[0], np.nan) if len(ric) and "mean IC" in ric else np.nan
    ic_t = _n(ric["t"].iloc[0], np.nan) if len(ric) and "t" in ric else np.nan
    n_liq = len(liq)
    kpi_row([k0,
             kpi_html("All-timeframe leaders", int((liq["tf"] >= 5).sum()), f"5 of 5 horizons in the top 20%, of {n_liq:,} liquid names", "good"),
             kpi_html("RS line at a 252-day high", int(liq["rs_nh252"].sum()), f"{int(liq['rs_leads'].sum())} before price (the leading tell)", "info"),
             kpi_html("Held up", int(masks["held"].sum()) if cw else "n/a", "up while SPY pulled back" if cw else "no pullback to test", ""),
             kpi_html("First out", int(masks["first"].sum()) if cw else "n/a",
                      "52-week high before SPY got back to its peak" if cw else "no pullback to test", "good" if cw and masks["first"].sum() else ""),
             kpi_html("Does resilience predict here?", f"IC {ic_v:+.3f}" if np.isfinite(ic_v) else "n/a",
                      f"t {ic_t:+.1f} over {int(_n(ric['months'].iloc[0], 0)) if len(ric) else 0} months (next-month rank correlation)",
                      "good" if ic_t >= 2 else "warn" if np.isfinite(ic_t) and ic_t <= -2 else "")])
    sort = st.selectbox("Sort by", [k for k in RSX_SORT if k in T], format_func=RSX_SORT.get, key="rsx_sort")
    view = liq[masks[show].reindex(liq.index).fillna(False).astype(bool)].sort_values(sort, ascending=False)
    if view.empty:
        note("No names match. Loosen the liquidity gate or pick another view.")
        return
    # ---- 1. leaders across time frames (heat grid)
    sec("Leaders across time frames")
    top = view.head(30)
    cols_g = RSX_KEYS + ["IBD", "resilience"]
    lab_g = {**{k: k for k in RSX_KEYS}, "IBD": "IBD-style", "resilience": "Resilience"}
    G = top[cols_g].rename(columns=lab_g).reset_index().rename(columns={"index": "symbol"})
    G = G.rename(columns={G.columns[0]: "symbol"}).melt("symbol", var_name="frame", value_name="rank")
    G["txt"] = G["rank"].map(lambda v: "" if not np.isfinite(v) else f"{v:.0f}")
    G["industry"] = G["symbol"].map(T["industry"])
    G["trend"] = G["symbol"].map(T["trend"])
    order_s, order_f = list(top.index), [lab_g[k] for k in cols_g]
    base = alt.Chart(G).encode(x=alt.X("frame:N", sort=order_f, title=None, axis=alt.Axis(orient="top", labelAngle=0)),
                               y=alt.Y("symbol:N", sort=order_s, title=None, axis=alt.Axis(labelOverlap=False)))
    cells = base.mark_rect(stroke=C_BG, strokeWidth=1.5).encode(
        color=alt.Color("rank:Q", scale=alt.Scale(domain=[1, 50, 99], range=["#16223a", "#2f5ea8", "#86b6ef"], interpolate="lab"),
                        legend=alt.Legend(orient="bottom", title="rank across the universe, 1-99", direction="horizontal",
                                          gradientLength=220, titleLimit=400, labelFontSize=10, titleFontSize=11)),
        tooltip=["symbol", "industry", "trend", "frame", alt.Tooltip("rank:Q", format=".0f")])
    txt = base.mark_text(fontSize=10, font="Fira Code, monospace").encode(
        text="txt:N", color=alt.condition(alt.datum.rank >= 70, alt.value(C_BG), alt.value(C_TEXT)))
    c1, c2 = st.columns([3, 2])
    with c1:
        show_chart(_alt(cells + txt, 22 * len(top) + 90))
    with c2:
        tt = top[["trend", "tf", "industry"]].copy()
        tt["trend"] = tt["trend"].replace("", "·")
        show_df(tt.reset_index().rename(columns={"index": "symbol"}), height=22 * len(top) + 90,
                column_config={"tf": st.column_config.NumberColumn("frames ≥ 80", format="%.0f"),
                               "trend": st.column_config.TextColumn("trend", width="medium")})
    # ---- 2. resilience map
    sec("Who held up, and who leads now")
    xcol, xt = (("corr_rel", "change through the SPY pullback minus SPY's, points") if cw else
                ("down_alpha", "down-day return beyond what its up-day beta implies, last 63 sessions, %"))
    M = liq.dropna(subset=[xcol, "IBD"]).copy()
    fo_ = M["first_out"].astype(bool) if "first_out" in M else pd.Series(False, index=M.index)
    M["group"] = np.where(fo_, "first out", np.where(M["rs_leads"].astype(bool), "RS line leads price", "other"))
    M["sym"] = M.index
    dom = ["first out", "RS line leads price", "other"]
    pts = alt.Chart(M).mark_circle(stroke=C_BG, strokeWidth=0.8).encode(
        x=alt.X(f"{xcol}:Q", title=xt, scale=alt.Scale(zero=False)), y=alt.Y("IBD:Q", title="IBD-style RS rating", scale=alt.Scale(domain=[0, 100])),
        color=alt.Color("group:N", scale=alt.Scale(domain=dom, range=[NC_B, NC_A, "#3a3a4a"]),
                        legend=alt.Legend(orient="top", title=None, labelFontSize=11, labelLimit=200)),
        size=alt.Size("tf:Q", scale=alt.Scale(domain=[0, 5], range=[18, 170]),
                      legend=alt.Legend(orient="top", title="frames ≥ 80", labelFontSize=11, titleFontSize=11,
                                        symbolFillColor=C_MUTED, symbolStrokeColor=C_MUTED)),
        opacity=alt.condition(alt.datum.group == "other", alt.value(0.55), alt.value(0.95)),
        tooltip=["sym", "industry", "trend", alt.Tooltip(f"{xcol}:Q", format="+.1f"), alt.Tooltip("IBD:Q", format=".0f"),
                 alt.Tooltip("resilience:Q", format=".0f"), alt.Tooltip("beta:Q", format=".2f"), alt.Tooltip("tf:Q", format=".0f")])
    lbl = alt.Chart(M.sort_values("leader", ascending=False).head(14)).mark_text(dx=8, dy=-7, fontSize=10, color=C_TEXT,
                                                                                  align="left").encode(x=f"{xcol}:Q", y="IBD:Q", text="sym:N")
    rules = (alt.Chart(pd.DataFrame({"v": [0]})).mark_rule(color=C_MUTED, strokeDash=[3, 3]).encode(x="v:Q") +
             alt.Chart(pd.DataFrame({"v": [RSX_LEAD]})).mark_rule(color=C_MUTED, strokeDash=[3, 3]).encode(y="v:Q"))
    show_chart(_alt(alt.layer(pts, lbl, rules), 380))
    note("Right of zero = did better than SPY through the pullback (or beat its beta on down days); above 80 = top fifth "
         "on the IBD-style rating. Bigger dots lead on more time frames. Labels: the top 14 by leader score.")
    # ---- 3. one name
    sec("One name: price, RS line and rank history")
    pick = st.selectbox("Name", list(view.index[:200]), key="rsx_pick")
    n_ = 252
    cp = R["C"][pick].iloc[-n_:]
    sp = R["spy"].iloc[-n_:]
    dd_ = pd.DataFrame({"close": cp, "50-day": R["C"][pick].rolling(50).mean().iloc[-n_:]})
    rsl = (cp / sp)
    rsl = rsl / rsl.iloc[0] * 100
    rk = pd.DataFrame({"1M": R["ranks"]["1M"][pick].iloc[-n_:], "3M": R["ranks"]["3M"][pick].iloc[-n_:],
                       "12M": R["ranks"]["12M"][pick].iloc[-n_:]}).astype(float)
    dom_ = (cp.index[0], cp.index[-1])
    shade = []
    if cw and cw["peak"] >= cp.index[0]:
        shade = [alt.Chart(pd.DataFrame({"start": [cw["peak"]], "end": [cw["trough"]]})).mark_rect(color=C_RED, opacity=0.13).encode(
            x=alt.X("start:T", scale=_nc_xscale()), x2="end:T")]
    r_ = T.loc[pick]
    head = (f"{pick} · {r_['industry'] or 'no industry'} · {r_['trend'].lower() or 'no trend label'} · IBD-style {r_['IBD']:.0f}, "
            f"{r_['tf']:.0f} of 5 time frames in the top 20%, resilience {r_['resilience']:.0f}, beta {r_['beta']:.2f}")
    md(f"<div class='note' style='color:var(--text)'>{_esc(head)}</div>")
    show_chart(_alt(alt.layer(*shade, _nc_lines(dd_, ["close", "50-day"], [C_TEXT, NC_MA50], "Price (log) with the 50-day; red band = SPY pullback",
                                                 dom=dom_, log=True, legend=True)), 230))
    rdf = pd.DataFrame({"RS line": rsl})
    nh = (R["rs"][pick] >= R["rs"][pick].rolling(252, min_periods=200).max() * 0.99999).iloc[-n_:]
    dots = pd.DataFrame({"date": rsl.index[nh.to_numpy()], "value": rsl[nh].to_numpy()})
    rs_layers = [*shade, _nc_lines(rdf, ["RS line"], [NC_A], "RS line vs SPY (rebased to 100); dots = 252-day RS-line highs", dom=dom_, fmt=".1f")]
    if len(dots):
        rs_layers.append(alt.Chart(dots).mark_circle(size=34, color=NC_A, stroke=C_BG, strokeWidth=1).encode(
            x=alt.X("date:T", scale=_nc_xscale()), y="value:Q"))
    show_chart(_alt(alt.layer(*rs_layers), 170))
    show_chart(_alt(_nc_lines(rk, ["1M", "3M", "12M"], [NC_A, NC_B, "#199e70"], "RS rank history, 1-99 (dashed line = 80)",
                              dom=dom_, rules=[(RSX_LEAD, False)], fmt=".0f", legend=True), 190))
    # ---- 4. groups
    Gr = R["groups"]
    if len(Gr):
        sec("Industry groups (median member, 3+ names)")
        gg = Gr.head(15).reset_index()
        bars_ = alt.Chart(gg, title="Strongest groups by median IBD-style rating").mark_bar(color=NC_B, cornerRadiusEnd=3, size=13).encode(
            y=alt.Y("industry:N", sort=None, title=None, axis=alt.Axis(labelLimit=260, labelOverlap=False)),
            x=alt.X("ibd:Q", title=None, scale=alt.Scale(domain=[0, 100])),
            tooltip=["industry", "n", alt.Tooltip("ibd:Q", format=".0f", title="median IBD-style"),
                     alt.Tooltip("resilience:Q", format=".0f", title="median resilience"), "leaders"])
        gl = alt.Chart(gg).mark_text(align="left", dx=4, color=C_TEXT, fontSize=10).encode(
            y=alt.Y("industry:N", sort=None), x="ibd:Q", text=alt.Text("ibd:Q", format=".0f"))
        c1, c2 = st.columns([3, 2])
        with c1:
            show_chart(_alt(bars_ + gl, 24 * len(gg) + 50))
        with c2:
            show_df(gg[["industry", "n", "ibd", "resilience", "leaders"]], height=24 * len(gg) + 50,
                    column_config={"ibd": st.column_config.NumberColumn("IBD", format="%.0f"),
                                   "resilience": st.column_config.NumberColumn("resil.", format="%.0f")})
    # ---- 5. table
    sec(f"Table: {RSX_SHOW[show].lower()} ({len(view):,} names)")
    keep = ["name", "industry", "trend", *RSX_KEYS, "IBD", "tf", "resilience", "leader", "beta", "beta_up", "beta_down",
            "down_alpha", "down_capture",
            "corr_chg", "corr_rel", "corr_dd", "since_low", "first_out", "first_out_date", "rs_nh252", "rs_leads", "mansfield",
            "mansfield_up", "above50", "above200", "from_hi", "close", "dv_m"]
    keep = [k for k in keep if k in view and not (k == "name" and not view["name"].astype(bool).any())]
    tab = view[keep].reset_index().rename(columns={"index": "symbol"})
    tab = tab.rename(columns={tab.columns[0]: "symbol"})
    N_, B_ = st.column_config.NumberColumn, st.column_config.CheckboxColumn
    show_df(tab, height=min(520, 40 + 35 * len(tab)), column_config={"trend": st.column_config.TextColumn("trend", width="medium"),
        **{k: N_(k, format="%.0f") for k in RSX_KEYS}, "IBD": N_("IBD-style", format="%.0f"), "tf": N_("frames ≥ 80", format="%.0f"),
        "resilience": N_("resilience", format="%.0f"), "leader": N_("leader", format="%.0f"), "beta": N_(format="%.2f"),
        "beta_up": N_("up-day beta", format="%.2f"), "beta_down": N_("down-day beta", format="%.2f"),
        "down_alpha": N_("down-day excess vs up beta %", format="%+.1f"), "down_capture": N_("down capture", format="%.2f"),
        "corr_chg": N_("pullback %", format="%+.1f"), "corr_rel": N_("vs SPY, pts", format="%+.1f"),
        "corr_dd": N_("max drawdown %", format="%+.1f"), "since_low": N_("since SPY low %", format="%+.1f"),
        "first_out": B_("first out"), "first_out_date": "first-out date", "rs_nh252": B_("RS NH 252"), "rs_leads": B_("RS leads price"),
        "mansfield": N_("Mansfield RS", format="%+.1f"), "mansfield_up": B_("Mansfield rising"), "above50": B_("> 50d"),
        "above200": B_("> 200d"), "from_hi": N_("from 52w high %", format="%+.1f"), "close": N_(format="%.2f"),
        "dv_m": N_("$ vol (M)", format="%.0f")})
    a_, b_, _ = st.columns([1, 1, 2])
    a_.download_button("Download table (CSV)", tab.to_csv(index=False), "rs_leaders.csv", "text/csv", key="rsx_dl")
    b_.download_button(f"Watchlist ({min(len(view), 100)})", "\n".join(view.index[:100]), "rs_leaders.txt", "text/plain",
                       key="rsx_wl", help="Top 100 in the current sort, one symbol per line: paste into a Barchart watchlist.")
    # ---- 6. history check
    sec("Does it work in your universe? (next-month rank correlation at each month-end)")
    if len(ic):
        show_df(ic, column_config={"mean IC": N_(format="%+.3f"), "t": N_(format="%+.1f"), "IC above 0": N_(format="percent"),
                                   "top minus bottom fifth, %": N_(format="%+.2f"), "IC after SPY fell": N_(format="%+.3f"),
                                   "down months": N_(format="%d")})
        note("An IC of +0.03 to +0.05 held for years is a useful signal in equities; |t| under 2 is noise. Your list was "
             "picked today, which flatters these numbers; the Setup ledger's whole-market mode records 'RS time frames' "
             "and 'resilience' for every trade without that hindsight, so split it by them for the honest test.")
    with st.expander("What the RS leaders tab measures, how to read it, and the sources"):
        st.markdown(RSX_GUIDE)


IPO_GROUP = {"BREAKOUT (buy zone)": "buy zone", "IN BASE": "in base", "FORMING": "in base", "EXTENDED": "extended"}
IPO_GROUP_COLOR = {"buy zone": "#5b8dee", "in base": "#c97d1e", "extended": "#199e70", "other": "#3a3a4a"}
IPO_SHOW = {"all": "Every IPO that passes the liquidity gate", "setup": "In an IPO base or in the buy zone",
            "leaders": "Leaders (score 70+)", "lockup": "Lockup in the next 30 days", "growth": "Sales growth 25%+ (needs SEC data)"}
IPO_GUIDE = """
#### What this tab does
IBD's IPO Leaders page lists new issues that have traded for less than three years, with strong recent sales and
earnings growth and sponsorship from top-rated mutual funds. This tab builds the same cohort from your data and adds what
the newspaper page can't: where each name sits in its first base, when its lockup ends, and how the cohort has actually
done.

**Where the list comes from.** Massive's IPO list (listing date and final issue price) when your plan includes it; names
in your universe whose first daily bar falls inside the loaded history; and the tickers typed in the box (prefilled with
the names on IBD's page). Shell companies (SPACs) and warrants are dropped. Sales and EPS growth come from SEC company
facts: the latest quarter against the same quarter a year earlier, and the quarter before (acceleration). Fund
sponsorship needs 13F holdings data, which isn't wired in, so that part of IBD's screen is missing.

**The IPO base** (IBD's rules): it starts within about 25 sessions of the debut, usually corrects less than 20% (up to 50%
in rough markets), usually lasts under five weeks and can be as short as seven sessions. The buy point is the base's high,
on a volume pickup; the buy zone runs to 5% above it. Statuses: *forming* (under seven sessions since the high), *in base*,
*breakout (buy zone)* (within 20 sessions of the breakout and within 5% of the pivot), *extended*, *back at pivot*, *failed
breakout* (8% under the pivot), *no valid base* (it broke out too fast or the base was too deep or too long), *below debut
high* (never got back above its first-month high).

**Calendar risk.** Insider lockups usually end 180 days after the IPO. Field & Hanka (2001) measured a -1.5% three-day
abnormal return around expiry and a lasting 40% jump in volume, larger for venture-backed companies. Treat the week of a
lockup like earnings: size down or wait. The analysts' quiet period ends about 25 days after the IPO, when the underwriters'
analysts start coverage.

**Pinned.** 20-day volatility under 8% and a 20-day range under 4%: the chart looks pinned to a price, usually a pending
takeover (IBD's page notes two this week: Accelerant to Thoma Bravo, Bowhead to American Family). Pinned names get no
score.

**Score.** The average rank inside the IPO cohort of: return since the IPO against SPY, 3-month RS against your whole
universe, distance from the post-IPO high, and sales and EPS growth once SEC data is loaded.

**Base rate.** IPOs as a group have lagged similar stocks for years after listing (Ritter 1991; Loughran & Ritter 1995),
so a new issue needs to earn its place. The cohort charts at the bottom show how the IPOs loaded here have done by age and
what their IPO-base breakouts did next; only survivors are loaded, so both read better than reality.

#### Sources
IBD, IPO Leaders (weekly page) and *How To Find The First Buy Point In IPO Stocks* · William O'Neil, *How to Make Money in
Stocks* · [Field & Hanka (2001), The Expiration of IPO Share Lockups, *Journal of Finance*](https://ideas.repec.org/a/bla/jfinan/v56y2001i2p471-500.html) ·
Ritter (1991), The Long-Run Performance of Initial Public Offerings, *Journal of Finance* · Loughran & Ritter (1995), The New
Issues Puzzle, *Journal of Finance* · Bradley, Jordan & Ritter (2003), The Quiet Period Goes Out with a Bang, *Journal of
Finance* · Massive reference data: /vX/reference/ipos
"""


def render_ipos(cfg, uni: pd.DataFrame, ab, bars: Dict[str, pd.DataFrame], bench_bars: Dict[str, pd.DataFrame]) -> None:
    if "SPY" not in bench_bars:
        warnbox("IPO leaders needs SPY.")
        return
    spy = bench_bars["SPY"]["close"]
    src = cfg["source"]
    st.session_state.setdefault("ipo_manual", ", ".join(IPO_IBD_DEFAULT))
    c = st.columns([2.4, 1, 1, 1.8])
    manual_txt = c[0].text_input("Also track (tickers)", key="ipo_manual", help="Prefilled with IBD's IPO Leaders page.")
    px_min = c[1].number_input("Min price", 0.0, 1000.0, 10.0, 1.0, key="ipo_px")
    dv_min = c[2].number_input("Min $ vol (M)", 0.0, 1000.0, 5.0, 1.0, key="ipo_dv")
    show = c[3].selectbox("Show", list(IPO_SHOW), format_func=IPO_SHOW.get, key="ipo_show")
    # ---- the list
    frames, notes = [], []
    if src == "demo":
        frames.append(memo(("ipo_demo", tuple(uni["ticker"][:400])), lambda: ipo_demo(list(uni["ticker"]))))
    elif src == "massive" and cfg.get("key"):
        b1, b2 = st.columns([1, 3])
        if b1.button("Load the IPO list (Massive)", key="ipo_go") or st.session_state.get("ipo_loaded"):
            st.session_state["ipo_loaded"] = True
            try:
                frames.append(memo(("ipo_ep", date.today().isoformat()), lambda: ipo_endpoint(cfg["key"])))
            except Exception as e:
                notes.append(f"Massive's IPO list isn't available ({type(e).__name__}); using first-bar dates instead.")
        else:
            b2.caption("Without the IPO list, IPOs are found from the first daily bar of each name in your universe.")
    fb = ipo_from_first_bar(bars)
    frames.append(fb)
    manual = [t for t in (_clean_ticker(x) for x in manual_txt.replace("\n", ",").split(",")) if t]
    E = pd.concat([f for f in frames if f is not None and len(f)], ignore_index=True) if any(len(f) for f in frames) else \
        pd.DataFrame(columns=["ticker", "list_date", "source"])
    pending = E[E.get("status", pd.Series("", index=E.index)).astype(str) == "pending"] if "status" in E else E.iloc[0:0]
    E = E[~E.index.isin(pending.index)]
    E = E.drop_duplicates("ticker", keep="first")
    extra = [t for t in manual if t not in set(E["ticker"])]
    need = sorted({t for t in list(E["ticker"]) + extra if t not in bars})
    ib = dict(bars)
    if need:
        with st.spinner(f"Daily bars for {len(need)} IPOs"):
            got, _ = get_bars(need, UNIVERSE_DAYS, src, cfg["key"], cfg["drop_partial"])
        ib.update(got)
    if extra:
        rows_ = []
        cut = pd.Timestamp(last_completed_session()) - pd.Timedelta(days=int(365.25 * IPO_YEARS))
        w0 = pd.Series({t: df.index[0] for t, df in bars.items() if len(df)}).quantile(0.05) if len(bars) >= 20 else None
        for t in extra:
            df = ib.get(t)
            if df is None or df.empty:
                notes.append(f"No bars for {t}.")
                continue
            if w0 is not None and df.index[0] <= w0 + pd.Timedelta(days=30) and src != "demo":
                notes.append(f"{t} has traded since before the loaded history, so it isn't a recent IPO here.")
                continue
            if df.index[0] >= cut or src == "demo":
                rows_.append({"ticker": t, "list_date": df.index[0], "source": "your list (first bar)"})
        if rows_:
            E = pd.concat([E, pd.DataFrame(rows_)], ignore_index=True)
    cut = pd.Timestamp(last_completed_session()) - pd.Timedelta(days=int(365.25 * IPO_YEARS))
    E = E[pd.to_datetime(E["list_date"]) >= cut]
    if E.empty:
        warnbox("No IPOs from the last three years in the data. Load the IPO list, or type tickers in the box.")
        for n_ in notes:
            note(n_)
        return
    names = uni.drop_duplicates("ticker").set_index("ticker")["name"].to_dict() if "name" in uni else {}
    growth = st.session_state.get("ipo_growth")
    key_ = ("ipo_tab", tuple(sorted(E["ticker"])), str(spy.index[-1]), len(growth) if growth is not None else 0,
            ab["P"]["close"].shape if ab is not None else 0)
    T = memo(key_, lambda: ipo_table(E, ib, spy, ab["P"]["close"] if ab is not None else None, growth, names))
    if T.empty:
        warnbox("None of the IPOs had usable bars.")
        return
    liq = T[(T["close"] >= px_min) & (T["dv_m"].fillna(0) >= dv_min)]
    T_src = E.drop_duplicates("ticker").set_index("ticker")["source"].value_counts().to_dict()
    in_setup = liq["b_status"].isin(["IN BASE", "FORMING", "BREAKOUT (buy zone)"])
    brk20 = liq["b_brk_date"].notna() & (liq["b_since_brk"].fillna(999) <= 20) & ~liq["b_status"].isin(["NO VALID BASE"])
    lock30 = liq["to_lockup"].between(0, 30)
    med_ex = float(liq["ex_spy"].median()) if len(liq) else np.nan
    kpi_row([kpi_html("IPOs tracked", f"{len(liq):,}", " · ".join(f"{v} {k}" for k, v in T_src.items())[:110], "info"),
             kpi_html("In base or buy zone", int(in_setup.sum()), "IBD-style first base after the debut", "good" if in_setup.any() else ""),
             kpi_html("Breakouts, last 20 sessions", int(brk20.sum()), f"{int((brk20 & liq['b_brk_vol_ok'].fillna(False).astype(bool)).sum())} on "
                      f"{IPO_VOL_MULT:.1f}x volume", ""),
             kpi_html("Lockups in 30 days", int(lock30.sum()), "180 days after the IPO: -1.5% around expiry on average", "warn" if lock30.any() else ""),
             kpi_html("Pinned (deal pending?)", int(liq["pinned"].sum()), "tight, quiet chart: usually a takeover", ""),
             kpi_html("Cohort vs SPY", pct(med_ex, 0) if np.isfinite(med_ex) else "n/a", "median return since IPO minus SPY's",
                      "good" if med_ex > 0 else "bad" if med_ex < 0 else "")])
    for n_ in notes[:4]:
        note(n_)
    masks = {"all": pd.Series(True, index=liq.index), "setup": in_setup, "leaders": liq["score"] >= 70, "lockup": lock30,
             "growth": liq["rev_g"] >= 0.25 if "rev_g" in liq else pd.Series(False, index=liq.index)}
    view = liq[masks[show].reindex(liq.index).fillna(False).astype(bool)]
    # SEC growth loader
    g1, g2 = st.columns([1.5, 3])
    if src == "demo" or cfg.get("sec_ua"):
        if g1.button("Load sales and EPS growth (SEC)", key="ipo_sec"):
            tk_ = list(liq.sort_values("score", ascending=False).index[:150])
            if src == "demo":
                st.session_state["ipo_growth"] = demo_growth(tk_)
            else:
                prog = st.progress(0.0, text="SEC company facts")
                try:
                    st.session_state["ipo_growth"] = sec_growth(tk_, cfg["sec_ua"], prog)
                except Exception as e:
                    warnbox(f"SEC: {type(e).__name__}: {e}")
                prog.empty()
            st.rerun()
        g2.caption("Latest quarter vs the same quarter a year ago, from SEC filings (up to 150 names, cached for the day)."
                   if growth is None else f"SEC growth loaded for {int(growth['rev_g'].notna().sum())} names.")
    else:
        g2.caption("Add an SEC contact under 'Optional outside data' in the sidebar to load sales and EPS growth.")
    if view.empty:
        note("No IPOs match this view.")
        return
    view = view.sort_values("score", ascending=False, na_position="last")
    # ---- 1. map
    sec("The IPO cohort: age, relative strength and first-base status")
    M = view.copy()
    M["setup"] = M["b_status"].map(IPO_GROUP).fillna("other")
    M["sym"] = M.index
    M["months_c"] = M["months"].clip(0, 37)
    dom = list(IPO_GROUP_COLOR)
    y_col = "rs3m" if M["rs3m"].notna().sum() >= 3 else "rs1m"
    pts = alt.Chart(M.dropna(subset=[y_col])).mark_circle(stroke=C_BG, strokeWidth=0.8).encode(
        x=alt.X("months_c:Q", title="months since the IPO", scale=alt.Scale(domain=[0, 37])),
        y=alt.Y(f"{y_col}:Q", title=("3-month" if y_col == "rs3m" else "1-month") + " RS vs your universe (1-99)",
                scale=alt.Scale(domain=[0, 100])),
        color=alt.Color("setup:N", scale=alt.Scale(domain=dom, range=[IPO_GROUP_COLOR[k] for k in dom]),
                        legend=alt.Legend(orient="top", title=None, labelFontSize=11)),
        size=alt.Size("dv_m:Q", scale=alt.Scale(type="sqrt", range=[20, 320]), legend=None),
        tooltip=["sym", "name", alt.Tooltip("list_date:T", format="%Y-%m-%d", title="listed"), "b_status",
                 alt.Tooltip("ex_spy:Q", format="+.0%", title="vs SPY since IPO"), alt.Tooltip(f"{y_col}:Q", format=".0f"),
                 alt.Tooltip("score:Q", format=".0f"), alt.Tooltip("dv_m:Q", format=",.0f", title="$ vol (M)")])
    lbl = alt.Chart(M.dropna(subset=[y_col]).head(14)).mark_text(dx=8, dy=-7, fontSize=10, color=C_TEXT, align="left").encode(
        x="months_c:Q", y=f"{y_col}:Q", text="sym:N")
    rule = alt.Chart(pd.DataFrame({"v": [RSX_LEAD]})).mark_rule(color=C_MUTED, strokeDash=[3, 3]).encode(y="v:Q")
    show_chart(_alt(alt.layer(pts, lbl, rule), 360))
    note("Dot size = dollar volume. Labels: the top 14 by score. Blue = breakout in the buy zone; copper = in its first base; "
         "aqua = extended past the buy zone; gray = no live IPO base.")
    # ---- 2. one name
    sec("One IPO: price since the debut, its first base and its calendar")
    pick = st.selectbox("Name", list(view.index[:250]), key="ipo_pick")
    r_ = T.loc[pick]
    df = ib[pick]
    d = df[df.index >= r_["list_date"] - pd.Timedelta(days=3)].copy()
    d.index.name = "date"
    gtxt = ""
    if "rev_g" in T and np.isfinite(_n(r_.get("rev_g"), np.nan)):
        gtxt = f" Sales {r_['rev_g']:+.0%} and EPS {_n(r_.get('eps_g'), np.nan):+.0%} last quarter ({r_.get('fin_q', '')})."
    head = (f"{pick} {('· ' + str(r_['name'])) if r_['name'] else ''} · listed {r_['list_date']:%b %d, %Y} "
            f"({r_['months']:.0f} months) at {r_['ipo_price']:.2f} ({r_['ipo_px_src']}); now {r_['close']:.2f}, "
            f"{r_['vs_ipo']:+.0%} vs the IPO price and {r_['ex_spy']:+.0%} vs SPY. First base: {r_['b_status'].lower()}"
            + (f", pivot {r_['b_pivot']:.2f}, {r_['b_depth']:.0%} deep, {int(r_['b_base_len'])} sessions" if np.isfinite(_n(r_['b_pivot'], np.nan)) else "")
            + (f"; broke out {pd.Timestamp(r_['b_brk_date']):%b %d} on {'heavy' if r_['b_brk_vol_ok'] else 'light'} volume"
               if _has_date(r_['b_brk_date']) else "")
            + f". Lockup {'ends' if r_['to_lockup'] >= 0 else 'ended'} {r_['lockup']:%b %d, %Y}"
            + (f" (in {r_['to_lockup']} days)." if r_['to_lockup'] >= 0 else ".") + gtxt
            + (" PINNED: looks like a pending deal." if r_["pinned"] else ""))
    md(f"<div class='note' style='color:var(--text)'>{_esc(head)}</div>")
    lines = _nc_lines(d[["close"]], ["close"], [C_TEXT], "Daily close since the IPO (log); dashed = IPO price, copper box = first base",
                      log=True, fmt=",.2f")
    layers = []
    if np.isfinite(_n(r_["b_pivot"], np.nan)) and _has_date(r_["b_hi_date"]):
        b_end = r_["b_brk_date"] if _has_date(r_["b_brk_date"]) else d.index[-1]
        layers.append(alt.Chart(pd.DataFrame({"start": [r_["b_hi_date"]], "end": [b_end], "lo": [r_["b_base_lo"]],
                                              "hi": [r_["b_pivot"]]})).mark_rect(color=NC_B, opacity=0.18).encode(
            x=alt.X("start:T", scale=_nc_xscale()), x2="end:T", y="lo:Q", y2="hi:Q"))
    layers.append(lines)
    refs = pd.DataFrame({"v": [r_["ipo_price"]], "what": ["IPO price"]})
    layers.append(alt.Chart(refs).mark_rule(color=C_MUTED, strokeDash=[4, 3]).encode(y="v:Q", tooltip=["what", alt.Tooltip("v:Q", format=",.2f")]))
    ev = [("lockup ends", r_["lockup"]), ("quiet period ends", r_["quiet_end"])]
    ev = pd.DataFrame([{"date": t_, "what": w_} for w_, t_ in ev if d.index[0] <= t_ <= d.index[-1]])
    if len(ev):
        layers.append(alt.Chart(ev).mark_rule(strokeDash=[2, 3]).encode(
            x=alt.X("date:T", scale=_nc_xscale()), color=alt.Color("what:N", scale=alt.Scale(domain=["lockup ends", "quiet period ends"],
                                                                                         range=[C_RED, C_MUTED]),
                                                                    legend=alt.Legend(orient="top", title=None, labelFontSize=11)),
            tooltip=["what", alt.Tooltip("date:T", format="%Y-%m-%d")]))
    if _has_date(r_["b_brk_date"]) and r_["b_brk_date"] in d.index:
        layers.append(alt.Chart(pd.DataFrame({"date": [r_["b_brk_date"]], "v": [float(d.loc[r_["b_brk_date"], "close"])]})).mark_point(
            shape="triangle-up", filled=True, size=120, color=NC_A, stroke=C_BG, strokeWidth=1).encode(
            x=alt.X("date:T", scale=_nc_xscale()), y="v:Q", tooltip=[alt.Tooltip("date:T", format="%Y-%m-%d", title="breakout")]))
    show_chart(_alt(alt.layer(*layers).resolve_scale(color="independent"), 300))
    vv = d[["volume"]].reset_index()
    vch = alt.Chart(vv, title="Volume").mark_bar(color="#3a3a4a").encode(
        x=alt.X("date:T", title=None, axis=alt.Axis(format="%b %y", labelAngle=0, grid=False)),
        y=alt.Y("volume:Q", title=None, axis=alt.Axis(format="~s", minExtent=NC_YEXT, maxExtent=NC_YEXT)),
        tooltip=[alt.Tooltip("date:T", format="%Y-%m-%d"), alt.Tooltip("volume:Q", format=",.0f")])
    show_chart(_alt(vch, 120))
    # ---- 3. lockup calendar + pending
    L = liq[liq["to_lockup"].between(-10, 75)].copy()
    sec("Lockup calendar (10 days back to 75 days ahead)")
    if len(L):
        L["sym"], L["when"] = L.index, np.where(L["to_lockup"] < 0, "ended", "ahead")
        order_l = list(L.sort_values("lockup").index)
        dots = alt.Chart(L).mark_circle(size=90, stroke=C_BG, strokeWidth=1).encode(
            x=alt.X("lockup:T", title=None, axis=alt.Axis(format="%b %d", labelAngle=0)),
            y=alt.Y("sym:N", sort=order_l, title=None, axis=alt.Axis(labelOverlap=False)),
            color=alt.Color("when:N", scale=alt.Scale(domain=["ahead", "ended"], range=[NC_B, "#3a3a4a"]),
                            legend=alt.Legend(orient="top", title=None, labelFontSize=11)),
            tooltip=["sym", alt.Tooltip("lockup:T", format="%Y-%m-%d"), "to_lockup", "b_status",
                     alt.Tooltip("offer_m:Q", format=",.0f", title="offer size ($M)")])
        today_ = alt.Chart(pd.DataFrame({"d": [pd.Timestamp(last_completed_session())]})).mark_rule(color=C_MUTED).encode(x="d:T")
        show_chart(_alt(dots + today_, 30 * len(L) + 110))
        note("Lockups usually end 180 days after the IPO (some deals use 90 or 365 days; check the prospectus). Around expiry "
             "the average IPO has dropped about 1.5% over three days on 40% more volume, more for venture-backed names.")
    else:
        note("No lockup ends in this window.")
    if len(pending):
        sec("Upcoming IPOs (Massive)")
        pp = pending[[c_ for c_ in ("ticker", "issuer", "list_date", "price_lo", "price_hi", "offer_m", "exchange") if c_ in pending]]
        show_df(pp.sort_values("list_date"), column_config={"list_date": st.column_config.DateColumn("expected"),
                                                             "offer_m": st.column_config.NumberColumn("offer ($M)", format="%.0f")})
    # ---- 4. table
    sec(f"Table: {IPO_SHOW[show].lower()} ({len(view):,} names)")
    keep = ["name", "list_date", "months", "ipo_price", "close", "vs_ipo", "ex_spy", "from_high", "rs1m", "rs3m", "score",
            "b_status", "b_pivot", "b_depth", "b_base_len", "b_brk_date", "b_brk_vol_ok", "b_vs_pivot", "rev_g", "rev_g_prev",
            "eps_g", "eps_g_prev", "accel", "fin_q", "lockup", "to_lockup", "pinned", "dv_m", "hv20", "offer_m", "source"]
    keep = [k for k in keep if k in view and not (k == "name" and not view["name"].astype(bool).any())]
    tab = view[keep].reset_index().rename(columns={"index": "ticker"})
    tab = tab.rename(columns={tab.columns[0]: "ticker"})
    N_, B_ = st.column_config.NumberColumn, st.column_config.CheckboxColumn
    show_df(tab, height=min(520, 40 + 35 * len(tab)), column_config={
        "list_date": st.column_config.DateColumn("listed"), "months": N_(format="%.0f"), "ipo_price": N_("IPO price", format="%.2f"),
        "close": N_(format="%.2f"), "vs_ipo": N_("vs IPO price", format="percent"), "ex_spy": N_("vs SPY since IPO", format="percent"),
        "from_high": N_("from high", format="percent"), "rs1m": N_("RS 1M", format="%.0f"), "rs3m": N_("RS 3M", format="%.0f"),
        "score": N_(format="%.0f"), "b_status": st.column_config.TextColumn("first base", width="medium"),
        "b_pivot": N_("pivot", format="%.2f"), "b_depth": N_("depth", format="percent"), "b_base_len": N_("base sessions", format="%.0f"),
        "b_brk_date": st.column_config.DateColumn("breakout"), "b_brk_vol_ok": B_("volume ok"), "b_vs_pivot": N_("vs pivot", format="percent"),
        "rev_g": N_("sales growth", format="percent"), "rev_g_prev": N_("prior qtr", format="percent"),
        "eps_g": N_("EPS growth", format="percent"), "eps_g_prev": N_("prior qtr EPS", format="percent"), "accel": B_("accelerating"),
        "fin_q": "quarter", "lockup": st.column_config.DateColumn("lockup ends"), "to_lockup": N_("days to lockup", format="%d"),
        "pinned": B_("pinned"), "dv_m": N_("$ vol (M)", format="%.0f"), "hv20": N_("HV20", format="percent"),
        "offer_m": N_("offer ($M)", format="%.0f")})
    a_, b_, _ = st.columns([1, 1, 2])
    a_.download_button("Download table (CSV)", tab.to_csv(index=False), "ipo_leaders.csv", "text/csv", key="ipo_dl")
    b_.download_button(f"Watchlist ({min(len(view), 100)})", "\n".join(view.index[:100]), "ipo_leaders.txt", "text/plain", key="ipo_wl")
    # ---- 5. the cohort's own record
    sec("The cohort's record (IPOs loaded here, survivors only)")
    A = memo(("ipo_age",) + key_, lambda: ipo_age_curve(T, ib, spy))
    Bk = memo(("ipo_brk",) + key_, lambda: ipo_breakout_study(T, ib, spy))
    c1, c2 = st.columns([3, 2])
    with c1:
        if len(A):
            A["med"], A["lo"], A["hi"] = A["median"] * 100, A["q25"] * 100, A["q75"] * 100
            band = alt.Chart(A).mark_area(color=NC_A, opacity=0.18).encode(x=alt.X("months:Q", title="months since the IPO"),
                                                                           y=alt.Y("lo:Q", title="return minus SPY's, %"), y2="hi:Q")
            ln = alt.Chart(A).mark_line(color=NC_A, strokeWidth=2).encode(
                x="months:Q", y="med:Q", tooltip=["months", alt.Tooltip("med:Q", format="+.1f", title="median %"),
                                                  alt.Tooltip("lo:Q", format="+.1f", title="25th pct"), alt.Tooltip("hi:Q", format="+.1f", title="75th pct"), "n"])
            zero = alt.Chart(pd.DataFrame({"v": [0]})).mark_rule(color=C_MUTED).encode(y="v:Q")
            show_chart(_alt((band + ln + zero).properties(title="Median IPO vs SPY by age (band = middle half)"), 260))
    with c2:
        if len(Bk):
            show_df(Bk, column_config={"mean": N_(format="percent"), "median": N_(format="percent"),
                                       "beat_spy": N_("beat SPY", format="percent")})
            note("What IPO-base breakouts did next, against SPY. A few dozen events at most: read the direction, not the decimals.")
    with st.expander("How the IPO tab works, and the sources"):
        st.markdown(IPO_GUIDE)


