def render_universe_check(cfg, uni, bars) -> None:
    uc = memo(("ucheck", tuple(sorted(bars)), len(uni), cfg["min_group"], cfg.get("uni_name", "")),
              lambda: universe_check(uni, bars, cfg["min_group"]))
    tone = {"BROAD": "good", "OK, ONE GAP": "warn", "NARROW": "bad"}[uc["verdict"]]
    items = [kpi_html("Universe", uc["verdict"], f"{uc['n']:,} names, {uc['with_bars']:,} with bars", tone),
             kpi_html("In a peer group", f"{uc['grouped']:.0%}", f"{uc['grouped_ind']:.0%} by industry alone ({uc['n_ind_ok']} of "
                      f"{uc['n_ind']} industries have {cfg['min_group']}+), the rest by Theme",
                      "good" if uc["grouped"] >= UC_TARGET["grouped"] else "warn"),
             kpi_html("Top 3 industries", f"{uc['top3']:.0%}", f"tech-type industries {uc['tech']:.0%} of the list",
                      "warn" if uc["top3"] > UC_TARGET["top3"] else ""),
             kpi_html("Above 50-day / near high", f"{uc['above50']:.0%} / {uc['near_hi']:.0%}",
                      "a broad list sits near market breadth; 75%+ / 85%+ means pre-filtered for strength",
                      "warn" if uc["above50"] >= UC_TARGET["above50_hot"] or uc["near_hi"] >= UC_TARGET["near_hi_hot"] else ""),
             kpi_html("$20M+ a day", f"{uc['liquid']:.0%}", "20-session median dollar volume", ""),
             kpi_html("Market cap column", f"{uc['mcap_known']:,} names", f"median ${uc['mcap_med'] / 1e9:,.1f}B" if np.isfinite(uc["mcap_med"])
                      else "none: the name stack's market-cap gate is skipped", "")]
    why_html = ("<div class='note'>" + ("Why: " + "; ".join(_esc(w) for w in uc["why"]) + "." if uc["why"] else
                                        "Broad enough for cross-sectional ranks.") +
                " Build a better one with Barchart screen 0 below (all the recipes sit under 'Shares or options?' further down this tab).</div>"
                ).replace("$", "&#36;")
    top = uc["industries"].head(20).rename_axis("industry").reset_index(name="names")
    thin = uc["industries"][uc["industries"] < cfg["min_group"]]
    with st.expander(f"Universe check: {uc['verdict']} · {uc['n']:,} names · {uc['grouped_ind']:.0%} in industry groups"):
        kpi_row(items)
        md(why_html)
        c1, c2 = st.columns([3, 2])
        with c1:
            if len(top):
                ch = alt.Chart(top, title="Largest industries in the list").mark_bar(color=C_ACCENT2, cornerRadiusEnd=3, size=12).encode(
                    y=alt.Y("industry:N", sort=None, title=None, axis=alt.Axis(labelLimit=260, labelOverlap=False)),
                    x=alt.X("names:Q", title=None), tooltip=["industry", "names"])
                lab_ = alt.Chart(top).mark_text(align="left", dx=4, color=C_TEXT, fontSize=10).encode(
                    y=alt.Y("industry:N", sort=None), x="names:Q", text="names:Q")
                show_chart(_alt(ch + lab_, 22 * len(top) + 40))
        with c2:
            show_df(thin.rename_axis("industry").reset_index(name="names"), height=22 * min(len(thin), 14) + 60)
            note(f"{len(thin)} industries have fewer than {cfg['min_group']} names; their names get no industry-neutral "
                 "alphas unless their Theme group is big enough.")
        st.markdown(UNIVERSE_GUIDE)


UNIVERSE_GUIDE = """
**Why the universe matters here.** RS rating, the alpha composite, LaunchPad counts and breadth are all ranked across
whatever list is loaded, and the industry-neutral alphas need five or more names per industry. A list that came out of a
momentum screen makes everyone look like a leader, leaves most industries with one or two names, runs breadth hot,
and gives the Setup ledger's "list" mode selection bias (names picked today for being strong are tested on their past).
So let Barchart pick the pond and the dashboard pick the fish: screen for listing and liquidity only, then let the
Screener, RS 8-week and LaunchPad tabs do the selecting.

**Barchart screen 0, investable universe** (Stock Screener, save it as "Lab universe"):
1. Exchange: NYSE, Nasdaq, NYSE American
2. Last Price greater than 10
3. Market Cap greater than \\$500 million
4. 20-Day Average Volume greater than 500,000
5. Has Options = Yes
6. Nothing else (no moving averages, Weighted Alpha or % From High)

Export it with a custom view that has Symbol, Name, Last, Sector / Industry, Market Cap and 20-Day Average Volume (add
Implied Volatility, IV Percentile, IV/HV, Total Options Volume and Earnings Date to drive the shares-or-options call), and
upload it as the Universe CSV, or save it as Tickers.csv next to the app. If the export is capped, split by market cap
and upload both files at once. The name stack still applies its own tradeable gates (price \\$15+, market cap \\$2B+ by
default) to what you actually trade; the smaller names stay in for ranking and breadth.
"""


def render_screener(cfg, uni, ab, bars, bench_bars, stack, hits, fm=None, vc=None, clim=None) -> None:
    try:
        render_universe_check(cfg, uni, bars)
    except Exception as e:
        st.caption(f"Universe check: {type(e).__name__}: {e}")
    if ab is None:
        warnbox("The screener needs the alpha panel. Load a universe of at least 10 names.")
        return
    spy = bench_bars.get("SPY")
    rs8 = None
    if spy is not None:
        rs8, _ = memo(("rs8", tuple(sorted(bars)), str(spy.index[-1]), 4.5, -3.0, 6.0),
                      lambda: rs8_table(bars, spy["close"], 4.5, (-3.0, 6.0)))
    st.session_state.setdefault("sc_lp_tight", 3.0)
    tight = float(st.session_state["sc_lp_tight"])
    df = memo(("screen", tuple(sorted(bars)), str(ab["asof"]), len(stack) if stack is not None else 0,
               len(hits) if hits is not None else 0, tuple(sorted(cfg["refuse"])), tight),
              lambda: build_screen(uni, ab, rs8, stack, hits, cfg["refuse"], fm, vc, tight))
    df = df.copy()
    ff = flows_frame()
    if ff is not None and len(ff):
        keepc = [c for c in ("days_to_cover", "short_vol_ratio_5d", "opp_buys", "opp_buy_value", "news_net",
                             "events_n", "shares_out") if c in ff.columns]
        df = df.join(ff[keepc].apply(pd.to_numeric, errors="coerce"), how="left")
        if "shares_out" in df and "dollar_vol_m" in df and "close" in df:
            df["turnover"] = (df["dollar_vol_m"] * 1e6 / df["close"]) / df["shares_out"]
            df["turnover_regime"] = turnover_regime(df)
    qq = st.session_state.get("quality_res")
    if qq is not None and len(qq):
        df = df.join(qq[["f_score", "gross_prof", "accruals"]], how="left")
    bc_cols = [c for c in uni.columns if c.startswith("bc_")]
    if bc_cols:
        df = df.join(uni.set_index("ticker")[bc_cols], how="left")
    vd_ = st.session_state.get("vd_res")
    if vd_ and vd_.get("rows"):
        df["vd_vrp"] = pd.Series({r["sym"]: r.get("vrp_log") for r in vd_["rows"]})
    for k_, v_ in (("sc_veh_opt", 1000), ("sc_veh_earn", 30), ("sc_veh_adr", 8.0)):
        st.session_state.setdefault(k_, v_)
    veh = vehicle_verdict(df, float(st.session_state["sc_veh_opt"]), int(st.session_state["sc_veh_earn"]),
                          float(st.session_state["sc_veh_adr"]))
    df = df.join(veh, how="left")
    st.session_state["vehicle_map"] = df["vehicle"].to_dict()
    mset = st.session_state.get("sc_mc_set", "12/26/9")
    mcB = None
    try:
        mcB = mc_block(ab, mset if mset in MC_SETTINGS else "12/26/9")
        df = df.join(mcB["snap"], how="left")
    except Exception as e:
        warnbox(f"MACD: {type(e).__name__}: {e}")
    try:                                                 # anchored VWAPs (Stocks > VWAP)
        awS = aw_block(ab)["snap"]
        df = df.join(awS[[c_ for c_ in AW_SCREEN_COLS if c_ in awS]], how="left")
    except Exception as e:
        warnbox(f"VWAP: {type(e).__name__}: {e}")
    lev_p = lev_prefs()
    try:                                                 # leveraged funds (Stocks > Leveraged)
        lvM = lev_map(lev_catalog(), list(df.index), lev_p)
        if len(lvM):
            df = df.join(lvM[["lev_txt", "lev_long", "lev_long_dv"]], how="left")
    except Exception as e:
        warnbox(f"Leveraged: {type(e).__name__}: {e}")
    mc_post = mc_posture(clim)
    mc_fav, _ = mc_favored(mc_post)
    rk_now = st.session_state.get("ranker_today") or {}
    if rk_now:                                           # Stocks > Trade ranker's latest scores, for names with a live setup
        rkd = pd.DataFrame.from_dict(rk_now, orient="index")
        df["rk_p"] = rkd["p"].reindex(df.index).astype(float)
        df["rk_cons"] = rkd["cons"].reindex(df.index).astype(float)

    c = st.columns([2, 1, 1, 3])
    preset = c[0].selectbox("Start from a preset", ["(keep current filters)"] + list(SCREEN_PRESETS), key="sc_preset")
    if c[1].button("Apply preset") and preset in SCREEN_PRESETS:
        st.session_state.update(SCREEN_DEFAULTS)
        st.session_state.update(SCREEN_PRESETS[preset])
        st.rerun()
    if c[2].button("Clear filters"):
        st.session_state.update(SCREEN_DEFAULTS)
        st.rerun()
    for k, v in SCREEN_DEFAULTS.items():
        st.session_state.setdefault(k, v)

    sec("Core filters")
    c = st.columns([1.1, 1.2, 1.3, 1, 1.2])
    fip_mode = c[0].radio("Frog in the pan", ["any", "yes", "no"], horizontal=True, key="sc_fip")
    fip_share = c[1].slider("FIP = lowest % of ID among 12-1 winners", 10, 50, key="sc_fip_share")
    near8_on = c[2].checkbox("Near the 8-week average", key="sc_near8_on")
    near8 = c[2].slider("within +/- %", 0.5, 15.0, step=0.5, key="sc_near8", disabled=not near8_on)
    ma = c[3].radio("8-week average", ["EMA", "SMA"], horizontal=True, key="sc_ma")
    comp_min = c[4].slider("Min composite pct", 0, 100, key="sc_comp")

    with st.expander("Alpha categories (minimum category percentile)"):
        cc = st.columns(len(CAT_ORDER))
        cat_min = {cat: cc[i].slider(cat, 0, 100, key=f"sc_cat_{cat}", help=CAT_LABEL[cat]) for i, cat in enumerate(CAT_ORDER)}
    with st.expander("Relative strength and setups"):
        cc = st.columns(4)
        rs_mode = cc[0].selectbox("RS-line high", ["any", "252-day", "252-day or weekly", "252-day on breakout"], key="sc_rs")
        peer_min = cc[0].slider("Min peer RS (universe rank)", 0, 99, key="sc_peer")
        pct52 = cc[1].slider("Min % of 52-week high", 0, 100, key="sc_52w")
        e8up = cc[1].checkbox("8-week EMA rising", key="sc_e8up")
        pocket = cc[2].checkbox("In the 8-week pocket (-3% to +6%)", key="sc_pocket")
        cmp_ = cc[2].checkbox("ChartMaster (pocket + RS-line high)", key="sc_cm")
        box = cc[2].checkbox("BoxTrader trigger", key="sc_box")
        near1020 = cc[3].checkbox("Near the 10/20/50", key="sc_near1020")
        tengt = cc[3].checkbox("10-day above 20-day", key="sc_10gt20")
        no200 = cc[3].checkbox("Exclude 200-day overhead", key="sc_no200")
    with st.expander("State and style"):
        cc = st.columns(4)
        cluster = cc[0].radio("Name cluster", ["any", "QUIET", "ACTIVE"], horizontal=True, key="sc_cluster")
        ttt = cc[1].checkbox("Trade / trend / tail all up (UUU)", key="sc_ttt")
        garp = cc[2].multiselect("GARP proxy", ["GARP-ok", "MOM-only", "VALUE-only", "NONE"], key="sc_garp")
        dip = cc[3].multiselect("Dip flag", ["ALLOWED", "MAYBE", "NO"], key="sc_dip")
        ptouch = cc[0].slider("Min P(touch +3% in 21d), %", 0, 100, key="sc_ptouch")
    with st.expander("Volume, range and liquidity"):
        cc = st.columns(4)
        px_rng = cc[0].slider("Price", 0.0, float(max(10.0, np.ceil(np.nanmax(df["close"]) if "close" in df else 1000))),
                              (0.0, float(max(10.0, np.ceil(np.nanmax(df["close"]) if "close" in df else 1000)))), key="sc_px")
        adr_rng = cc[1].slider("ADR %", 0.0, 20.0, (0.0, 20.0), 0.5, key="sc_adr")
        ud_min = cc[2].number_input("Min U/D volume (50d)", 0.0, 5.0, step=0.1, key="sc_ud")
        rvol_min = cc[2].number_input("Min RVOL (today vs 50d)", 0.0, 10.0, step=0.1, key="sc_rvol")
        dvol_min = cc[3].number_input("Min $ volume, millions/day", 0.0, 10000.0, step=5.0, key="sc_dvol")
        hv1 = cc[3].checkbox("Highest volume in a year within 15 days", key="sc_hv1")
        quiet = cc[3].checkbox("Quiet accumulation in the last 10 days", key="sc_quiet")
    with st.expander("TraderLion setups: LaunchPad, Power of 3, HVE", expanded=st.session_state.get("sc_lp") != "off"):
        cc = st.columns(4)
        lp_mode = cc[0].selectbox("LaunchPad", ["off", "any LaunchPad", "Full pad (six averages)", "Short pad (10/21/23)",
                                                "Deepvue 1-3% rule"], key="sc_lp",
                                  help="Full: 10/21/50/200 SMA and 23/65 EMA bunched tight beneath price and turning up "
                                       "(Ross Haber). Short: 10/21 SMA and 23 EMA only. Deepvue: close within the band "
                                       "of the 21 SMA, 50 SMA and 65 EMA, rising and aligned 21 > 50 > 65.")
        lp_recent = cc[0].slider("Fired within the last N sessions", 0, 20, key="sc_lp_recent")
        cc[1].slider("Deepvue band (+/- %)", 1.0, 5.0, step=0.5, key="sc_lp_tight",
                     help="Deepvue's default flags a close within 1-3% of the three averages.")
        lp_risk_on = cc[1].checkbox("Max risk to the pad", key="sc_lp_risk_on",
                                    help="Distance from the close to the lowest of the 10 SMA, 21 SMA and 23 EMA. "
                                         "Haber: if the stop is more than 3% away, the entry isn't there yet.")
        lp_risk = cc[1].slider("risk %", 0.5, 10.0, step=0.5, key="sc_lp_risk", disabled=not lp_risk_on)
        lp_late = cc[2].checkbox("Exclude late cycle (doubled off the 52-week low)", key="sc_lp_late")
        lp_r200 = cc[2].checkbox("Require a rising 200-day", key="sc_lp_r200")
        lp_group = cc[2].slider("Min LaunchPads among the group's top-10 RS", 0, 10, key="sc_lp_group",
                                help="Haber: four or more in one group's top ten is the signal worth acting on.")
        p3_on = cc[3].checkbox("Power of 3 within N sessions", key="sc_p3",
                               help="Close goes from below the 10, 21 and 50-day SMAs to above all three in one session "
                                    "on above-average volume, with the 50-day not falling.")
        hve_on = cc[3].checkbox("HVE within 15 sessions", key="sc_hve",
                                help="Highest volume in the loaded history (about five years on Massive Starter).")
    mcf = mc_filter_ui()
    with st.expander("Anchored VWAP (Shannon)", expanded=bool(st.session_state.get("sc_vw_state")) or bool(st.session_state.get("sc_vw_setup"))):
        cc = st.columns(3)
        vw_state = cc[0].multiselect("AVWAP state", AW_STATES[::-1], key="sc_vw_state",
                                     help="Close vs the anchored VWAPs from the last 52-week high and the last 63-day low. "
                                          "ABOVE BOTH: everyone who bought since either is in profit (Stocks > VWAP).")
        vw_setup = cc[1].checkbox(f"A VWAP setup in the last {AW_RECENT} sessions", key="sc_vw_setup",
                                  help="Reclaim of the high's line, a pullback that held the low's or the gap's line, or a pinch.")
        vw_hi_min = cc[2].slider("Min % vs the AVWAP from the 52-week high", -50.0, 20.0, step=1.0, key="sc_vw_hi",
                                 help="-50 = off. 0 = only names over the line: the supply since the high has cleared.")
    with st.expander("Shares or options? (vehicle call)", expanded=bool(st.session_state.get("sc_veh"))):
        cc = st.columns(4)
        veh_sel = cc[0].multiselect("Vehicle", VEHICLES, key="sc_veh")
        lev_only = cc[0].checkbox("Has a leveraged fund", key="sc_lev",
                                  help="A daily 2x or 3x long fund on the name at your liquidity floor (Stocks > Leveraged).")
        cc[1].number_input("Min daily options volume", 0, 1_000_000, step=500, key="sc_veh_opt",
                           help="From the Barchart export's options-volume column. Without it, liquidity is assumed "
                                "from stock dollar volume (>= $50M a day and price >= $15).")
        cc[2].number_input("Earnings window (days)", 0, 90, step=5, key="sc_veh_earn",
                           help="Earnings inside this window = WAIT: a gap goes through a share stop, and IV crush hits long premium.")
        cc[3].number_input("Wide and loose above ADR %", 3.0, 20.0, step=0.5, key="sc_veh_adr",
                           help="Haber: wide, loose stocks give no clean stop; shares are a pass, defined-risk options only.")
        have_bc = any(c.startswith("bc_") for c in df.columns)
        st.caption("Barchart options columns: " + ("found." if have_bc else
                   "not found; vol state comes from Vol desk scans and liquidity is estimated. Add them via the sidebar."))
    with st.expander("Factors, flows, filings and quality"):
        cc = st.columns(4)
        rm_min = cc[0].slider("Min residual momentum pct", 0, 100, key="sc_rm")
        beta_rng = cc[0].slider("Market beta", -1.0, 4.0, step=0.1, key="sc_beta")
        obv_up = cc[1].checkbox("OBV rising (20d)", key="sc_obv")
        cmf_pos = cc[1].checkbox("Chaikin money flow > 0", key="sc_cmf")
        have_flows = "days_to_cover" in df.columns or "opp_buys" in df.columns
        dtc_max = cc[2].number_input("Max days to cover", 0.0, 100.0, step=0.5, key="sc_dtc", disabled=not have_flows)
        svr_max = cc[2].slider("Max short-volume ratio (5d)", 0.0, 1.0, step=0.05, key="sc_svr", disabled=not have_flows)
        insider = cc[3].checkbox("Opportunistic insider buy (90d)", key="sc_ins", disabled=not have_flows)
        news_min = cc[3].slider("Min news net sentiment", -1.0, 1.0, step=0.1, key="sc_news", disabled=not have_flows)
        have_q = "f_score" in df.columns
        f_min = cc[0].slider("Min F-score", 0, 9, key="sc_f", disabled=not have_q)
        gp_min = cc[1].slider("Min gross profit / assets", -0.2, 1.0, step=0.05, key="sc_gp", disabled=not have_q)
        tr_sel = cc[2].multiselect("Turnover regime", ["ST momentum (high turnover winner)", "ST momentum (high turnover loser)",
                                                       "ST reversal (low turnover loser)", "ST reversal (low turnover winner)"],
                                   key="sc_tr", disabled="turnover_regime" not in df.columns)
        if not have_flows:
            cc[3].caption("Load Stocks > Filings & flows to enable the flow filters.")
        if not have_q:
            cc[3].caption("Load Stocks > Quality to enable F-score and profitability.")
    with st.expander("Groups, lists and LBR"):
        cc = st.columns(3)
        themes = cc[0].multiselect("Theme", sorted(t for t in df["theme"].dropna().unique() if t), key="sc_theme")
        inds = cc[1].multiselect("Industry", sorted(t for t in df["industry"].dropna().unique() if t), key="sc_ind")
        excl_refuse = cc[2].checkbox("Exclude the refuse list", key="sc_refuse")
        lbr_on = cc[2].checkbox("Attach LBR setups (about 15 s the first time)", key="sc_lbr")
        lbr_env, lbr_need = [], False
        if lbr_on:
            lbr_env = cc[0].multiselect("LBR environment", ["TREND UP", "TREND DOWN", "LEAN TREND", "TRANSITION", "BALANCE"],
                                        key="sc_lbr_env")
            lbr_need = cc[1].checkbox("Has an LBR setup armed", key="sc_lbr_need")

    if lbr_on:
        def _all_lbr():
            out, names = {}, list(df.index)
            prog = st.progress(0.0, text="LBR")
            for i, t in enumerate(names):
                d = bars.get(t)
                if d is not None and len(d) >= 160:
                    try:
                        out[t] = lbr_snapshot(t, t, "stock", "RS", d.iloc[-320:])
                    except Exception:
                        pass
                if i % 25 == 0:
                    prog.progress(i / max(1, len(names)), text=f"LBR {i}/{len(names)}")
            prog.empty()
            return out
        lb = memo(("lbr_all", tuple(df.index), str(ab["asof"])), _all_lbr)
        df["lbr_env"] = pd.Series({t: r["env"] for t, r in lb.items()})
        df["lbr_route"] = pd.Series({t: r["pc"] for t, r in lb.items()})
        df["lbr_setup"] = pd.Series({t: (r["setups"][0] if r["setups"] else "") for t, r in lb.items()})
        df["lbr_5sma"] = pd.Series({t: r["sma_streak"] for t, r in lb.items()})

    df["fip"] = fip_flags(df, fip_share / 100.0)
    ext_col = "ext_8w" if ma == "EMA" else "ext_8w_sma"
    m = pd.Series(True, index=df.index)

    def need(col):
        return col in df.columns

    if fip_mode != "any":
        m &= df["fip"] if fip_mode == "yes" else ~df["fip"]
    if near8_on and need(ext_col):
        m &= df[ext_col].abs() <= near8
    m &= df["composite"].fillna(-1) >= comp_min
    for cat, v in cat_min.items():
        if v > 0:
            m &= df[f"cat_{cat}"].fillna(-1) >= v
    if rs_mode != "any" and need("rs_nh_252"):
        rs_ok = {"252-day": df["rs_nh_252"], "252-day on breakout": df["rs_nh_on_breakout"],
                 "252-day or weekly": df["rs_nh_252"] | df["rs_nh_weekly"] | df["rs_nh_week_forming"]}[rs_mode]
        m &= rs_ok.fillna(False).astype(bool)
    if peer_min and need("peer_rs"):
        m &= df["peer_rs"].fillna(-1) >= peer_min
    if pct52:
        m &= df["pct_of_52w_high"].fillna(0) >= pct52
    for flag, col in ((e8up, "e8_rising"), (pocket, "in_8w_pocket"), (cmp_, "chartmaster_pullback"),
                      (box, "boxtrader_trigger"), (near1020, "near_10_20_50"), (tengt, "sma10_gt_20"), (hv1, "hv1_15d")):
        if flag and need(col):
            m &= df[col].fillna(False).astype(bool)
    if no200 and need("overhead_200"):
        m &= ~df["overhead_200"].fillna(True).astype(bool)
    if cluster != "any" and need("cluster"):
        m &= df["cluster"] == cluster
    if ttt and need("ttt"):
        m &= df["ttt"] == "UUU"
    if garp and need("garp"):
        m &= df["garp"].isin(garp)
    if dip and need("dip"):
        m &= df["dip"].isin(dip)
    if ptouch and need("p_touch_3_21"):
        m &= df["p_touch_3_21"].fillna(0) * 100 >= ptouch
    if need("close"):
        m &= df["close"].between(*px_rng) | df["close"].isna() & (px_rng[0] == 0)
    if need("adr20"):
        m &= df["adr20"].fillna(0).between(*adr_rng)
    if ud_min and need("ud50"):
        m &= df["ud50"].fillna(0) >= ud_min
    if rvol_min:
        m &= df["rvol"].fillna(0) >= rvol_min
    if dvol_min:
        m &= df["dollar_vol_m"].fillna(0) >= dvol_min
    if quiet:
        m &= df["quiet_acc_days"].fillna(0) > 0
    if themes:
        m &= df["theme"].isin(themes)
    if inds:
        m &= df["industry"].isin(inds)
    if excl_refuse:
        m &= ~df["refuse"]
    if lbr_on and lbr_env:
        m &= df["lbr_env"].isin(lbr_env)
    if lbr_on and lbr_need:
        m &= df["lbr_setup"].fillna("").astype(bool)
    if rm_min and "resid_mom_pct" in df:
        m &= df["resid_mom_pct"].fillna(0) >= rm_min
    if "beta" in df and beta_rng != (-1.0, 4.0):
        m &= df["beta"].between(*beta_rng)
    if obv_up and "obv_slope" in df:
        m &= df["obv_slope"].fillna(0) > 0
    if cmf_pos and "cmf20" in df:
        m &= df["cmf20"].fillna(0) > 0
    if have_flows and dtc_max < 100 and "days_to_cover" in df:
        m &= df["days_to_cover"].fillna(0) <= dtc_max
    if have_flows and svr_max < 1 and "short_vol_ratio_5d" in df:
        m &= df["short_vol_ratio_5d"].fillna(0) <= svr_max
    if have_flows and insider and "opp_buys" in df:
        m &= df["opp_buys"].fillna(0) > 0
    if have_flows and news_min > -1 and "news_net" in df:
        m &= df["news_net"].fillna(-1) >= news_min
    if have_q and f_min:
        m &= df["f_score"].fillna(0) >= f_min
    if have_q and gp_min > -0.2:
        m &= df["gross_prof"].fillna(-1) >= gp_min
    if tr_sel and "turnover_regime" in df:
        m &= df["turnover_regime"].isin(tr_sel)
    if lp_mode != "off" and "tl_full_age" in df:
        n_ = max(lp_recent, 0)
        cols_ = {"any LaunchPad": ["tl_full_age", "tl_short_age", "tl_deepvue_age"], "Full pad (six averages)": ["tl_full_age"],
                 "Short pad (10/21/23)": ["tl_short_age"], "Deepvue 1-3% rule": ["tl_deepvue_age"]}[lp_mode]
        hit_ = pd.Series(False, index=df.index)
        for c_ in cols_:
            hit_ |= df[c_].fillna(999) <= n_
        m &= hit_
    if lp_risk_on and "risk_to_pad" in df:
        m &= df["risk_to_pad"].between(0, lp_risk)
    if lp_late and "late_cycle" in df:
        m &= ~df["late_cycle"].fillna(False).astype(bool)
    if lp_r200 and "sma200_rising" in df:
        m &= df["sma200_rising"].fillna(False).astype(bool)
    if lp_group and "group_lp" in df:
        m &= df["group_lp"].fillna(0) >= lp_group
    if p3_on and "tl_power3_age" in df:
        m &= df["tl_power3_age"].fillna(999) <= max(lp_recent, 0)
    if hve_on and "tl_hve_age" in df:
        m &= df["tl_hve_age"].fillna(999) <= 15
    if veh_sel and "vehicle" in df:
        m &= df["vehicle"].isin(veh_sel)
    if lev_only and "lev_long" in df:
        m &= df["lev_long"].fillna("").astype(str) != ""
    if vw_state and "vw_state" in df:
        m &= df["vw_state"].isin(vw_state)
    if vw_setup and "vw_setup_key" in df:
        m &= df["vw_setup_key"].fillna("").astype(str) != ""
    if vw_hi_min > -50 and "vw_pos_hi" in df:
        m &= df["vw_pos_hi"] >= vw_hi_min
    if mcB is not None:
        m &= mc_mask(df, mcf, mc_fav)
    res = df[m.fillna(False)].copy()

    sort_col = st.selectbox("Sort by", ["composite", "fip_id", ext_col, "peer_rs", "rs_excess", "pret_12_1", "ret_1m",
                                        "pct_of_52w_high", "rvol", "p_touch_3_21", "mc_setup_age", "mc_macdv", "mc_risk_pct",
                                        "vw_setup_age", "vw_pos_hi", "rk_p", "rk_cons"],
                            key="sc_sort",
                            format_func=lambda k: {"fip_id": "FIP ID (lowest = smoothest)", ext_col: "Distance to 8-week (abs)",
                                                   "mc_setup_age": "MACD setup (freshest first)", "mc_macdv": "MACD-V",
                                                   "mc_risk_pct": "MACD plan risk % (tightest first)",
                                                   "vw_setup_age": "VWAP setup (freshest first)",
                                                   "vw_pos_hi": "vs the AVWAP from the 52-week high",
                                                   "rk_p": "Trade ranker P(win)", "rk_cons": "Trade ranker consensus"}.get(k, k))
    if sort_col == "fip_id":
        res = res.sort_values("fip_id")
    elif sort_col in ("mc_setup_age", "mc_risk_pct", "vw_setup_age") and sort_col in res:
        res = res.sort_values([sort_col, "composite"], ascending=[True, False])
    elif sort_col == ext_col:
        res = res.reindex(res[ext_col].abs().sort_values().index)
    elif sort_col in res:
        res = res.sort_values(sort_col, ascending=False)
    st.session_state["screener_names"] = list(res.index)

    kpi_row([kpi_html("Matches", len(res), f"of {len(df)} names in the universe", "good" if len(res) else "bad"),
             kpi_html("FIP yes (universe)", int(df["fip"].sum()), f"lowest {fip_share}% of ID among 12-1 winners"),
             kpi_html(f"Within +/-{near8:g}% of 8-week {ma}", int((df[ext_col].abs() <= near8).sum()) if need(ext_col) else 0,
                      "universe count"),
             kpi_html("Median composite (matches)", f"{res['composite'].median():.0f}" if len(res) else "—", "cross-sectional pct")])
    if res.empty:
        note("No names pass every filter. Loosen one at a time; the counts above show where the universe sits.")
        render_macd_panel(df, res, mcB, mc_post)
        render_tl_panel(ab, df, res, bars, tight)
        return

    c1, c2 = st.columns([3, 2])
    with c1:
        mc_cols = ["mc_setup", "mc_setup_age", "mc_risk_pct", "mc_state", "mc_macdv", "mc_imp", "mc_tide"]
        vw_cols = ["vw_state", "vw_setup", "vw_setup_age", "vw_pos_hi", "vw_pos_lo"]
        vw_on = bool(vw_state) or bool(vw_setup) or vw_hi_min > -50 or sort_col in ("vw_setup_age", "vw_pos_hi")
        lev_cols = ["lev_txt"] if (lev_p.get("lev_prefer") or lev_only) else []
        cols = ["name", "theme", "composite", "rk_p", "rk_cons"] + lev_cols + (mc_cols if mc_active(mcf) else []) + (vw_cols if vw_on else []) + [f"cat_{c}" for c in CAT_ORDER] + [
            "fip", "fip_id", "pret_12_1", ext_col, "e8_rising", "peer_rs", "rs_nh_252", "in_8w_pocket",
            "chartmaster_pullback", "boxtrader_trigger", "pct_of_52w_high", "ret_1m", "rvol", "quiet_acc_days",
            "ep9_age", "adr20", "spread_bp", "ud50", "cluster", "ttt", "garp", "dip", "p_touch_3_21", "resid_mom_pct", "beta", "obv_slope", "cmf20",
            "days_to_cover", "short_vol_ratio_5d", "opp_buys", "news_net", "turnover_regime", "f_score", "gross_prof",
            "vehicle", "vol_state", "bc_iv_pctl", "days_to_earn",
            "lp_type", "tl_full_age", "tl_short_age", "tl_deepvue_age", "risk_to_pad", "lp_spread6", "group_lp",
            "tl_power3_age", "tl_hve_age", "lbr_env", "lbr_route", "lbr_setup", "close"] + ([] if mc_active(mcf) else mc_cols) + ([] if vw_on else vw_cols)
        cols = [c_ for c_ in cols if c_ in res.columns]
        cols = [c_ for c_ in cols if not (res[c_].dtype == object and res[c_].fillna("").astype(str).str.strip().eq("").all())]
        P, B = st.column_config.NumberColumn, st.column_config.CheckboxColumn
        show_df(res[cols].reset_index().rename(columns={"index": "ticker"}), height=min(560, 40 + 35 * len(res)),
                column_config={"composite": st.column_config.ProgressColumn("Composite", min_value=0, max_value=100, format="%.0f"),
                               "rk_p": st.column_config.ProgressColumn("Ranker P(win)", min_value=0.0, max_value=1.0, format="%.2f"),
                               "rk_cons": P("Ranker consensus", format="%.0f"),
                               **{f"cat_{c}": P(c, format="%.0f") for c in CAT_ORDER},
                               "fip": B("FIP"), "fip_id": P("FIP ID", format="%+.3f"), "pret_12_1": P("12-1 ret %", format="%+.1f"),
                               ext_col: P(f"vs 8w {ma} %", format="%+.1f"), "e8_rising": B("8w rising"),
                               "peer_rs": P("Peer RS", format="%.0f"), "rs_nh_252": B("RS NH"), "in_8w_pocket": B("Pocket"),
                               "chartmaster_pullback": B("ChartMaster"), "boxtrader_trigger": B("BoxTrader"),
                               "pct_of_52w_high": P("% of 52w hi", format="%.0f"), "ret_1m": P("1m %", format="%+.1f"),
                               "rvol": P("RVOL", format="%.2f"), "quiet_acc_days": P("Quiet acc", format="%.0f"),
                               "adr20": P("ADR %", format="%.1f"), "ud50": P("U/D 50", format="%.2f"),
                               "ep9_age": P("EP 9M (sessions ago)", format="%.0f",
                                            help="Stockbee's EP 9 million: 9M+ shares on 3x+ its usual volume, up on the "
                                                 "day, price $3+. Sessions since the last one (0 = the last bar), within 20."),
                               "spread_bp": P("est. spread bp", format="%.0f",
                                              help="Round-trip bid-ask spread estimated from daily bars (Abdi-Ranaldo, last 21 sessions). "
                                                   "Noisy for one name on one day, with a floor near 30 bp on volatile names; good for ranking which names cost more to trade."),
                               "p_touch_3_21": P("P touch +3% 21d", format="percent"), "close": P(format="%.2f"),
                               "resid_mom_pct": P("resid mom pct", format="%.0f"), "beta": P(format="%.2f"),
                               "obv_slope": P("OBV slope", format="%+.2f"), "cmf20": P("CMF", format="%+.2f"),
                               "days_to_cover": P("DTC", format="%.1f"), "short_vol_ratio_5d": P("short vol", format="percent"),
                               "opp_buys": P("opp buys", format="%.0f"), "news_net": P("news", format="%+.2f"),
                               "gross_prof": P("GP/A", format="percent"),
                               "lp_type": st.column_config.TextColumn("LaunchPad"),
                               "vehicle": st.column_config.TextColumn("vehicle", width="medium"),
                               "vol_state": st.column_config.TextColumn("vol"), "bc_iv_pctl": P("IV pctl", format="percent"),
                               "days_to_earn": P("days to earnings", format="%.0f"),
                               "tl_full_age": P("full pad age", format="%.0f"), "tl_short_age": P("short pad age", format="%.0f"),
                               "tl_deepvue_age": P("Deepvue age", format="%.0f"), "risk_to_pad": P("risk to pad %", format="%.1f"),
                               "lp_spread6": P("6-MA spread %", format="%.1f"), "group_lp": P("group pads", format="%.0f"),
                               "tl_power3_age": P("Power of 3 age", format="%.0f"), "tl_hve_age": P("HVE age", format="%.0f"),
                               "mc_setup": st.column_config.TextColumn("MACD setup", width="medium"),
                               "mc_setup_age": P("MACD age", format="%.0f"), "mc_risk_pct": P("MACD risk %", format="%.1f"),
                               "mc_state": st.column_config.TextColumn("MACD-V state"), "mc_macdv": P("MACD-V", format="%+.0f"),
                               "mc_imp": st.column_config.TextColumn("impulse"), "mc_tide": st.column_config.TextColumn("weekly tide"),
                               "vw_state": st.column_config.TextColumn("AVWAP state"),
                               "lev_txt": st.column_config.TextColumn("Leveraged fund", help="The daily long fund the lab would use (Stocks > Leveraged)."),
                               "vw_setup": st.column_config.TextColumn("VWAP setup", width="medium"),
                               "vw_setup_age": P("VWAP age", format="%.0f"),
                               "vw_pos_hi": P("vs AVWAP from high %", format="%+.1f"), "vw_pos_lo": P("vs AVWAP from low %", format="%+.1f")})
    with c2:
        d = res.reset_index().rename(columns={"index": "ticker"})
        d["FIP"] = np.where(d["fip"], "FIP yes", "FIP no")
        if ext_col in d:
            ch = alt.Chart(d, title=f"Composite vs distance to the 8-week {ma}").mark_circle(size=60, opacity=0.9).encode(
                x=alt.X(f"{ext_col}:Q", title=f"% vs 8-week {ma}"), y=alt.Y("composite:Q", title="composite pct"),
                color=alt.Color("FIP:N", scale=alt.Scale(domain=["FIP yes", "FIP no"], range=[C_GREEN, C_MUTED]),
                                legend=alt.Legend(orient="top", title=None)),
                tooltip=["ticker", alt.Tooltip(f"{ext_col}:Q", format="+.1f"), alt.Tooltip("composite:Q", format=".0f"),
                         alt.Tooltip("fip_id:Q", format="+.3f")])
            band = alt.Chart(pd.DataFrame({"x": [-near8, near8]})).mark_rule(strokeDash=[4, 3], color=C_ACCENT).encode(x="x:Q")
            show_chart(_alt(ch + band if near8_on else ch, 360))
        note("FIP ID runs from -1 (every formation day moved with the trend) to +1. The paper's stronger momentum sits "
             "at the low end among winners.")

    if mc_active(mcf):
        render_macd_panel(df, res, mcB, mc_post)
        render_tl_panel(ab, df, res, bars, tight)
    else:
        render_tl_panel(ab, df, res, bars, tight)
        render_macd_panel(df, res, mcB, mc_post)
    render_vehicle_panel(df, res)
    sec("Send these names")
    a, b, c_, d_, e = st.columns(5)
    a.download_button("Download CSV", res.reset_index().rename(columns={"index": "ticker"}).to_csv(index=False),
                      "screener.csv", "text/csv")
    ranked_ok = [t for t in res.index if pd.notna(res.at[t, "composite"]) and t not in cfg["refuse"]]
    if b.button("To Debit screen"):
        st.session_state["deb_names"] = ranked_ok[:60]
        st.caption(f"{len(ranked_ok[:60])} names sent to Options > Debit screen.")
    if c_.button("To Flow tape"):
        st.session_state["flow_names"] = ranked_ok[:30]
        st.caption(f"{len(ranked_ok[:30])} names sent to Options > Flow tape.")
    if d_.button("To RS 8-week watchlist"):
        st.session_state["rs8_src"] = "custom"
        st.session_state["rs8_txt"] = ", ".join(list(res.index)[:150])
        st.caption("Sent to Stocks > RS 8-week.")
    e.caption("Kelly: stock trades can size these directly ('Names from: Screener results').")


