def _cached_grouped_days() -> int:
    try:
        return len(list(GROUPED_DIR.glob("*.csv.gz")))
    except Exception:
        return 0


def render_breadth(cfg, ab, bench_bars) -> None:
    src = cfg["source"]
    c = st.columns([1, 1, 2])
    n_sess = int(c[0].number_input("Sessions", 260, 1260, 420, 20, key="br_n",
                                   help="New 52-week highs and lows need 252 sessions of warm-up."))
    min_px = c[1].number_input("Min price ($)", 0.0, 50.0, 2.0, 0.5, key="br_px")
    spy = bench_bars["SPY"]["close"] if "SPY" in bench_bars else None
    res = None
    if src == "massive" and cfg["key"]:
        have = _cached_grouped_days()
        need_backfill = have < int(n_sess * 0.95)
        c[2].caption(f"{have} sessions of grouped bars on disk. Every US common stock, one request per session; "
                     f"only missing sessions are fetched.")
        go = st.button(f"Backfill {n_sess} sessions" if need_backfill else "Refresh market breadth",
                       key="br_go") if need_backfill else True
        if go:
            def build():
                prog = st.progress(0.0, text="Grouped bars")
                try:
                    cs = common_stock_set(cfg["key"])
                except Exception:
                    cs = set()
                P = grouped_panel(n_sess, cfg["key"], cs or None, min_px, prog, fetch=True)
                prog.empty()
                return P, ("All US common stocks (Massive grouped daily)" if cs else "All US tickers (grouped daily)")
            P, label = memo(("breadth_P", date.today().isoformat(), session_phase(), n_sess, min_px), build)
            if P is not None:
                res = (breadth_series(P), label)
        else:
            note("Click the button once to backfill; afterwards only the newest session is fetched each day.")
    elif ab is not None:
        keep = ab["P"]["close"] >= min_px
        P = {k: ab["P"][k].where(keep) for k in ("close", "high", "low", "volume")}
        res = (breadth_series(P), f"Your universe ({P['close'].shape[1]} names), not the whole market")
    if not res:
        warnbox("No breadth data yet.")
        return
    b, label = res
    st.session_state["breadth_res"] = {"b": b, "label": label}
    rd = breadth_read(b, spy)
    last = rd["last"]
    md(hero_html(rd["state"], {"CONFIRM": C_GREEN, "DIVERGE": C_RED}.get(rd["state"], C_MUTED),
                 f"Breadth of {label}. Last session {b.index[-1].date()}.", rd["why"] or "Needs SPY to compare."))
    nh, nl = _n(last.get("new_highs"), np.nan), _n(last.get("new_lows"), np.nan)
    kpi_row([
        kpi_html("Advancers / decliners", f"{int(last['adv'])} / {int(last['dec'])}", f"{int(last['issues'])} issues"),
        kpi_html("McClellan oscillator", f"{_n(last['mcclellan']):+.0f}", f"summation {_n(last['summation']):+,.0f}",
                 "good" if _n(last["mcclellan"]) > 0 else "bad"),
        kpi_html("Above 50-day / 200-day", f"{pct(last['pct_above_50'])} / {pct(last['pct_above_200'])}",
                 f"20-day {pct(last['pct_above_20'])}"),
        kpi_html("New highs - lows", "n/a" if not np.isfinite(nh) else f"{int(nh)} - {int(nl)}",
                 f"hi-lo index {pct(last.get('hilo_index'))}"),
        kpi_html("TRIN (10-day)", f"{_n(last['trin10']):.2f}", "above 1 = volume favors decliners",
                 "bad" if _n(last["trin10"]) > 1.2 else ("good" if _n(last["trin10"]) < 0.9 else "")),
        kpi_html("Zweig thrust", rd["last_thrust"] or "none in window", "10-day A/(A+D) from < 40% to > 61.5%",
                 "good" if rd["last_thrust"] else ""),
    ])
    t = b.tail(252).reset_index().rename(columns={"index": "date"})
    if spy is not None:
        sp = spy.reindex(b.index).ffill().tail(252)
        t["SPY (rebased)"] = (sp / sp.iloc[0]).to_numpy()
        t["A/D line (rebased)"] = ((t["ad_line"] - t["ad_line"].iloc[0]) / max(abs(t["ad_line"]).max(), 1) + 1).to_numpy()
    c1, c2 = st.columns(2)
    with c1:
        if spy is not None:
            line_chart(t, "date", ["SPY (rebased)", "A/D line (rebased)"], 240, "SPY vs advance/decline line")
        line_chart(t, "date", ["pct_above_20", "pct_above_50", "pct_above_200"], 240, "Share of stocks above their averages",
                   colors=[C_MUTED, C_ACCENT, C_BLUE], y_fmt="%")
    with c2:
        mc = t[["date", "mcclellan"]].copy()
        mc["sign"] = np.where(mc["mcclellan"] >= 0, "pos", "neg")
        ch = alt.Chart(mc, title="McClellan oscillator").mark_bar().encode(
            x=alt.X("date:T", title=None), y=alt.Y("mcclellan:Q", title=None),
            color=alt.Color("sign:N", scale=alt.Scale(domain=["pos", "neg"], range=[C_GREEN, C_RED]), legend=None))
        show_chart(_alt(ch, 240))
        if t["new_highs"].notna().any():
            hl = t[["date", "new_highs", "new_lows"]].dropna()
            hl["new_lows"] = -hl["new_lows"]
            long = hl.melt("date", var_name="side", value_name="n")
            ch = alt.Chart(long, title="New 52-week highs (up) and lows (down)").mark_bar().encode(
                x="date:T", y=alt.Y("n:Q", title=None),
                color=alt.Color("side:N", scale=alt.Scale(domain=["new_highs", "new_lows"], range=[C_GREEN, C_RED]), legend=None))
            show_chart(_alt(ch, 240))
    with st.expander("Last 15 sessions"):
        show_df(b.tail(15).iloc[::-1].reset_index().rename(columns={"index": "date"})[
            ["date", "adv", "dec", "mcclellan", "summation", "pct_above_20", "pct_above_50", "pct_above_200",
             "new_highs", "new_lows", "trin", "up_vol_pct"]],
            column_config={k: st.column_config.NumberColumn(format="percent") for k in
                           ("pct_above_20", "pct_above_50", "pct_above_200", "up_vol_pct")})
    note("Breadth asks whether the average stock agrees with the index. Neely, Rapach, Tu and Zhou found price and volume "
         "indicators forecast the equity premium as well as macro data, and caught declines near cycle peaks better. "
         "DIVERGE is a reason to sit on new risk, not a sell signal; Zweig thrusts are rare and historically bullish.")


def render_volsent(cfg, bench_bars, hvs) -> None:
    src = cfg["source"]
    if src not in ("massive", "demo"):
        warnbox("Needs option chains: choose Massive or Demo.")
        return
    syms = ["SPY", "QQQ", "IWM"]
    if st.button("Read SPY / QQQ / IWM chains", key="vs_go") or "vol_res" in st.session_state:
        def build():
            rows, prog = [], st.progress(0.0, text="Chains")
            for i, s in enumerate(syms, 1):
                spot = float(bench_bars[s]["close"].iloc[-1]) if s in bench_bars else None
                try:
                    raw = fetch_chain(s, 130, src, cfg["key"], spot or 100.0, hvs.get(s, 0.18), cfg["strip"], band=0.20)
                    cons = [x for x in (extract_contract(r, date.today()) for r in raw) if x]
                    sp = next((x["spot"] for x in cons if x["spot"]), None) or spot
                    r = chain_vol_read(s, cons, sp, hvs.get(s, np.nan))
                    if r:
                        rows.append(r)
                except Exception as e:
                    st.caption(f"{s}: {type(e).__name__}: {e}")
                prog.progress(i / len(syms), text=f"Chains {i}/{len(syms)}")
            prog.empty()
            if rows and src == "massive":
                try:
                    archive_vol(rows)
                except Exception:
                    pass
            return rows
        rows = memo(("vol_rows", date.today().isoformat(), session_phase(), src, cfg["strip"]), build)
        st.session_state["vol_res"] = rows
    rows = st.session_state.get("vol_res")
    if not rows:
        note("Reads 30- and 90-day ATM implied vol (variance-interpolated), 25-delta skew and put/call ratios from the "
             "index chains. This replaces the Yahoo ^VIX proxy. Each run is archived so percentiles build over time.")
        return
    for r in rows:
        pc = vol_percentiles(r["sym"], r) if src == "massive" else {"n_days": 0}
        sub = (lambda k: f"{pc[k + '_pct']:.0%} pct" if k + "_pct" in pc else f"history {pc['n_days']} days")
        sec(f"{r['sym']} at {r['spot']:.2f}")
        kpi_row([
            kpi_html("IV 30-day", pct(r["iv30"], 1), sub("iv30")),
            kpi_html("IV 90-day / term", f"{pct(r['iv90'], 1)} / {r['term']:.2f}" if r["term"] else pct(r["iv90"], 1),
                     "term > 1 = near-term fear priced above later", "bad" if (r["term"] or 0) > 1.0 else ""),
            kpi_html("25-delta skew", f"{r['skew25'] * 100:+.1f} vol pts" if r["skew25"] is not None else "n/a", sub("skew25")),
            kpi_html("Put/call volume / OI", f"{_n(r['pc_vol']):.2f} / {_n(r['pc_oi']):.2f}", sub("pc_vol")),
            kpi_html("VRP (IV30 - HV20)", pct(r["vrp"], 1) if r["vrp"] is not None else "n/a",
                     f"HV20 {pct(r['hv20'], 1)}", "warn" if _n(r["vrp"]) > 0.04 else ""),
            kpi_html("Expected move", f"±{pct(r['move7_pct'], 1)} 1w / ±{pct(r['move30_pct'], 1)} 1m",
                     "one standard deviation from ATM IV"),
        ])
    curves = pd.concat([r["atm_curve"].assign(sym=r["sym"]) for r in rows if len(r["atm_curve"])], ignore_index=True)
    if len(curves):
        ch = alt.Chart(curves, title="ATM implied vol by days to expiry").mark_line(point=True).encode(
            x=alt.X("dte:Q", title="days to expiry"), y=alt.Y("atm_iv:Q", title=None, axis=alt.Axis(format="%")),
            color=alt.Color("sym:N", scale=alt.Scale(range=[C_ACCENT, C_BLUE, C_GREEN]), legend=alt.Legend(orient="top", title=None)))
        show_chart(_alt(ch, 260))
    spy = next((r for r in rows if r["sym"] == "SPY"), None)
    if spy:
        fear = [("put/call volume above 1.0", _n(spy["pc_vol"]) > 1.0), ("term structure inverted", _n(spy["term"]) > 1.0),
                ("implied vol below realized", _n(spy["vrp"], 1) < 0), ("skew above 6 vol points", _n(spy["skew25"]) > 0.06)]
        n = sum(f for _, f in fear)
        md(hero_html(f"FEAR {n}/4", C_RED if n >= 3 else (C_ACCENT if n >= 2 else C_GREEN), "SPY contrarian sentiment",
                     "; ".join(t for t, f in fear if f) or "No fear extremes."))
        note("Simon and Wiggins found VIX, put/call and TRIN worked as contrarian indicators for S&P futures: extreme fear "
             "preceded better returns. A rich VRP is a clause on the vol map, not a credit signal.")
    if src == "massive":
        try:
            h = pd.read_csv(VOL_HISTORY)
            if len(h) >= 2:
                h["date"] = pd.to_datetime(h["date"])
                hs = h[h["sym"] == "SPY"].sort_values("date")
                if len(hs) >= 2:
                    line_chart(hs, "date", ["iv30", "hv20"], 220, "SPY archive: IV30 vs HV20", colors=[C_ACCENT, C_BLUE], y_fmt="%")
        except Exception:
            pass


def render_cmt(cfg, bench_bars) -> None:
    closes = pd.DataFrame({t: df["close"] for t, df in bench_bars.items()}).sort_index()
    if "SPY" not in closes:
        warnbox("Needs SPY and the sector ETFs.")
        return
    tail_n = st.slider("Tail length (sessions)", 4, 20, 8, key="cmt_tail")
    clauses = []
    br = st.session_state.get("breadth_res")
    if br:
        rd = breadth_read(br["b"], closes["SPY"])
        clauses.append(kpi_html("Breadth clause", rd["state"], rd["why"][:120], "good" if rd["state"] == "CONFIRM" else "bad"))
    vr = st.session_state.get("vol_res")
    if vr:
        s = next((r for r in vr if r["sym"] == "SPY"), None)
        if s:
            lab = "VRP_RICH" if _n(s["vrp"]) > 0.03 else ("VRP_CHEAP" if _n(s["vrp"]) < 0 else "VRP_FAIR")
            clauses.append(kpi_html("VRP clause", lab, f"IV30 {pct(s['iv30'], 1)} vs HV20 {pct(s['hv20'], 1)}; term "
                                    f"{'INVERTED' if _n(s['term']) > 1 else 'CONTANGO'}"))
    dp = (st.session_state.get("dp_last") or {}).get("SPY")
    if dp:
        clauses.append(kpi_html("Dealer gamma (SPY)", dp["regime"], (f"flip {dp['flip']:,.2f}; " if dp["flip"] else "") +
                                f"put wall {dp['put_wall'] or 0:,.0f}, call wall {dp['call_wall'] or 0:,.0f}",
                                "good" if dp["regime"] == "POSITIVE" else "bad"))
    cr = correlation_regime(closes)
    if cr:
        clauses.append(kpi_html("Sector correlation (63d)", f"{cr['now']:.2f}", f"{cr['pct']:.0%} percentile: {cr['label']}",
                                "warn" if cr["pct"] >= 0.8 else ""))
    im = intermarket_table(closes)
    if len(im):
        score = int((im["trend"] == "rising").sum() - (im["trend"] == "falling").sum())
        clauses.append(kpi_html("Intermarket score", f"{score:+d}", f"of {len(im)} risk-on ratios (rising minus falling)",
                                "good" if score > 1 else ("bad" if score < -1 else "")))
    if clauses:
        kpi_row(clauses)
    if not br or not vr:
        note("Breadth and VRP clauses appear after the Breadth and Vol & sentiment tabs have been run this session.")

    def rrg_block(syms, names, title):
        table, tails = rrg(closes, syms, tail=tail_n)
        if table.empty:
            return
        table["name"] = table["symbol"].map(names)
        av = {s: avwap_distance(bench_bars[s]) for s in table["symbol"] if s in bench_bars}
        table["avwap_dist"] = table["symbol"].map(lambda s: av.get(s, (np.nan, ""))[0])
        table["anchor"] = table["symbol"].map(lambda s: av.get(s, (np.nan, ""))[1])
        qcol = {"LEADING": C_GREEN, "WEAKENING": C_ACCENT, "LAGGING": C_RED, "IMPROVING": C_BLUE}
        dom = list(qcol)
        tails = tails.merge(table[["symbol", "quadrant"]], on="symbol")
        lines = alt.Chart(tails).mark_line(strokeWidth=1.3, opacity=0.65).encode(
            x=alt.X("rs_ratio:Q", title="RS-Ratio (100 = SPY)", scale=alt.Scale(zero=False)),
            y=alt.Y("rs_mom:Q", title="RS-Momentum", scale=alt.Scale(zero=False)), detail="symbol:N", order="step:Q",
            color=alt.Color("quadrant:N", scale=alt.Scale(domain=dom, range=[qcol[q] for q in dom]), legend=alt.Legend(orient="top", title=None)))
        heads = alt.Chart(table).mark_circle(size=90).encode(
            x="rs_ratio:Q", y="rs_mom:Q", color=alt.Color("quadrant:N", scale=alt.Scale(domain=dom, range=[qcol[q] for q in dom]), legend=None),
            tooltip=["symbol", "name", alt.Tooltip("rs_ratio:Q", format=".2f"), alt.Tooltip("rs_mom:Q", format=".2f"), "quadrant"])
        labels = alt.Chart(table).mark_text(dx=8, dy=-8, color=C_TEXT, fontSize=10).encode(x="rs_ratio:Q", y="rs_mom:Q", text="symbol")
        rules = (alt.Chart(pd.DataFrame({"v": [100]})).mark_rule(color=C_MUTED, strokeDash=[3, 3]).encode(x="v:Q") +
                 alt.Chart(pd.DataFrame({"v": [100]})).mark_rule(color=C_MUTED, strokeDash=[3, 3]).encode(y="v:Q"))
        c1, c2 = st.columns([3, 2])
        with c1:
            show_chart(_alt(lines + heads + labels + rules, 380))
        with c2:
            show_df(table.sort_values("rs_ratio", ascending=False)[["symbol", "name", "rs_ratio", "rs_mom", "quadrant",
                                                                    "avwap_dist", "anchor"]], height=380,
                    column_config={"rs_ratio": st.column_config.NumberColumn("RS-Ratio", format="%.2f"),
                                   "rs_mom": st.column_config.NumberColumn("RS-Mom", format="%.2f"),
                                   "avwap_dist": st.column_config.NumberColumn("AVWAP dist", format="percent")})

    sec("Sectors vs SPY (relative rotation)")
    rrg_block(SECTOR_ETFS, SECTOR_NAMES, "Sectors")
    sec("Climate cross-section vs SPY")
    rrg_block(list(CROSS_ETFS), CROSS_ETFS, "Cross-section")
    sec("Intermarket ratios (rising = risk-on)")
    if len(im):
        show_df(im, column_config={"chg_20d": st.column_config.NumberColumn("20d", format="percent"),
                                   "chg_63d": st.column_config.NumberColumn("63d", format="percent"),
                                   "above_50d": st.column_config.CheckboxColumn("above 50d")})
    if cr:
        s = cr["series"].tail(504).reset_index()
        s.columns = ["date", "avg_corr"]
        line_chart(s, "date", ["avg_corr"], 200, "Average pairwise sector correlation (63-day)")
    note("Leading = high relative level and rising; weakening = high but rolling over; lagging = low and falling; improving = low "
         "but turning up. RS-Ratio is a JdK-style reconstruction (EMA10 of the ratio vs its 63-day mean), not the Optuma "
         "indicator. AVWAP is anchored at the more recent 63-day closing extreme. All of this annotates; none of it votes.")


def fred_bundle(cfg, force: bool = False) -> Optional[Dict[str, pd.Series]]:
    """FRED series for the day: synthetic in demo; otherwise only once the Macro tab has loaded them (or `force`)."""
    if cfg["source"] == "demo":
        return demo_macro()
    if not cfg.get("fred_key") or not (force or st.session_state.get("macro_res")):
        return None

    def build():
        out = {}
        start = (date.today() - timedelta(days=5 * 365)).isoformat()
        for sid, *_ in FRED_SERIES:
            try:
                out[sid] = fred_series(sid, cfg["fred_key"], start)
            except Exception as e:
                st.caption(f"{sid}: {type(e).__name__}")
        return out
    return memo(("fred", date.today().isoformat(), len(FRED_SERIES)), build)


def render_macro(cfg) -> None:
    src = cfg["source"]
    if src == "demo":
        series = demo_macro()
    elif not cfg.get("fred_key"):
        note("Add a free FRED API key under 'Optional outside data' in the sidebar to see credit spreads, the yield curve, "
             "financial conditions and claims here. Everything else in the dashboard runs on Massive alone.")
        return
    else:
        if not (st.button("Load FRED macro", key="fred_go") or "macro_res" in st.session_state):
            note("One request per series, cached for the day.")
            return

        series = fred_bundle(cfg, force=True)
        st.session_state["macro_res"] = True
    tab = macro_table(series)
    if tab.empty:
        warnbox("No macro series loaded.")
        return
    hy = series.get("BAMLH0A0HYM2")
    stress = []
    if hy is not None and len(hy.dropna()) > 25:
        d = float(hy.dropna().iloc[-1] - hy.dropna().iloc[-22])
        stress.append(("HY spreads widened > 0.5 pt in a month", d > 0.5))
    nf = series.get("NFCI")
    if nf is not None and len(nf.dropna()):
        stress.append(("financial conditions tighter than average", float(nf.dropna().iloc[-1]) > 0))
    c3 = series.get("T10Y3M")
    if c3 is not None and len(c3.dropna()):
        stress.append(("10y-3m inverted", float(c3.dropna().iloc[-1]) < 0))
    n = sum(f for _, f in stress)
    md(hero_html(f"MACRO {n}/{len(stress)}", C_RED if n >= 2 else (C_ACCENT if n == 1 else C_GREEN), "Credit, conditions, curve",
                 "; ".join(t for t, f in stress if f) or "No macro stress flags."))
    show_df(tab, column_config={"latest": st.column_config.NumberColumn(format="%.2f"),
                                "chg_1m": st.column_config.NumberColumn("1m change", format="%+.2f"),
                                "pct_3y": st.column_config.NumberColumn("3y pct", format="percent")})
    c1, c2 = st.columns(2)
    for col, sid, title in ((c1, "BAMLH0A0HYM2", "High-yield OAS"), (c2, "T10Y3M", "10y minus 3m")):
        s = series.get(sid)
        if s is not None and len(s.dropna()):
            d = s.dropna().tail(756).reset_index()
            d.columns = ["date", "level"]
            with col:
                line_chart(d, "date", ["level"], 220, title)
    note("Neely and coauthors found technical indicators and macro variables are complementary: technicals catch the decline in "
         "expected returns near cycle peaks, macro catches the rise near troughs. Use this page to label the backdrop.")


