    got = q["f_signals"].fillna(0) >= 6
    kpi_row([kpi_html("Names with data", int(got.sum()), f"of {len(q)}; fiscal year {int(q['fiscal_year'].iloc[0])}"),
             kpi_html("F-score 8-9", int((q["f_score"] >= 8).sum()), "strong across the nine signals", "good"),
             kpi_html("F-score 0-2", int((q["f_score"] <= 2).sum()), "weak fundamentals", "bad"),
             kpi_html("Median gross profitability", pct(q["gross_prof"].median()), "gross profit / assets")])
