BR_DEFAULTS = {"uni": "list", "h": 5, "tgt": 1.5, "mode": "next_open", "cd": 5, "ivm": 1.15, "skew": 0.5, "cost": 3.0,
               "stock_bp": 10.0, "mrv": 15.0, "hold": 0.4, "split": "none", "px": 10.0, "dv": 10.0, "cc": "stop",
               "pricer": "flat", "hs_n": 15, "au_n": 120}
BR_FADE = {"conv_atr": 1.0, "bounce_atr": 1.0, "touch": 0.01, "pb_off": 0.03}   # Luk's fade (see br_fade_parts)
BR_FL_RS = 90.0          # a former leader: RS rating 90+ at some point in the last 252 sessions
