def _gordinal(n: float) -> str:
    k = _jr(n)
    v = k % 100
    suf = "th" if 11 <= v <= 13 else {1: "st", 2: "nd", 3: "rd"}.get(k % 10, "th")
    return f"{k}{suf}"


def gr_regime_state(i: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    posture = i.get("posture") if i else None
    if not posture:
        return None
    dr = {"BUY_RIP": "risk_on", "BUY_DIP": "recovery", "AVOID": "risk_off"}.get(posture, "chop")
    vix, pctl, ratio, spy_hv = (_gnum(i.get(x)) for x in ("vix", "vixPct", "vixRatio", "spyHv"))
    why = [f"Posture {posture}{', entry mode ' + i['mode'] if i.get('mode') else ''} → {GR_DIRS[dr]['label'].lower()}"]
    notes: List[str] = []
    vol_known = True
    if ratio is not None and ratio >= 1:
        vol = "stressed"
        why.append(f"VIX/VIX3M {ratio:.2f}: the curve is inverted (backwardation)")
    elif pctl is not None:
        vol = "cheap" if pctl <= 35 else "rich" if pctl >= 65 else "fair"
        why.append(f"VIX {'—' if vix is None else f'{vix:g}'} sits at the {_gordinal(pctl)} percentile of 5 years")
    elif vix is not None:
        vol = "cheap" if vix <= 14 else "rich" if vix > 20 else "fair"
        why.append(f"VIX {vix:g} (no percentile, so level bands: 14 and below cheap, above 20 rich)")
    else:
        vol, vol_known = "fair", False
        why.append("No VIX data: vol assumed fair")
    if ratio is not None and ratio < 1:
        why.append(f"VIX/VIX3M {ratio:.2f}: contango{', steep' if ratio <= 0.9 else ''}")
    flat = ratio is not None and 0.95 <= ratio < 1
    if flat:
        notes.append("The VIX curve is nearly flat (0.95–1.0). Short-vol trades are treated as one step closer to stressed: none is a first choice.")
    vrp = None
    if vix is not None and spy_hv:
        vrp = math.log(vix / spy_hv)
        if vrp < 0 and vol != "stressed":
            notes.append(f"SPY is realizing {spy_hv:.1f}% against a VIX of {vix:g}: implied is below realized, so owning options is cheap and selling them is not paid.")
        elif vrp > 0.5:
            notes.append(f"VIX is {_jr((vix / spy_hv - 1) * 100)}% above SPY's realized vol ({spy_hv:.1f}%). A wide variance premium pays premium sellers, "
                         "and it has predicted better index returns over the next quarter (Bollerslev, Tauchen & Zhou).")
    cell = GR_PLAYBOOK[dr][vol]
    size = cell["size"]
    carry_unwind = i.get("carry") == "UNWIND"
    if carry_unwind:
        size *= 0.6
        notes.append("Carry unwind (USDJPY): size cut 40%, inside your Capital Flows rule of 30–50%.")
    bear_steep = i.get("curve") == "BEAR_STEEPENER"
    if bear_steep:
        notes.append("Bear steepener: multiple compression hits long-duration growth hardest. Outright calls drop to \"allowed\"; prefer spreads and tight MA entries.")
    if cell.get("note"):
        notes.append(cell["note"])
    return {"dir": dr, "vol": vol, "flat": flat, "vrp": vrp, "vol_known": vol_known, "carry_unwind": carry_unwind,
            "bear_steep": bear_steep, "posture": posture, "mode": i.get("mode") or None,
            "label": f"{GR_DIRS[dr]['label']} · {GR_VOLS[vol]['label']}", "cell": cell, "size": size, "why": why, "notes": notes}


def gr_role_of(rg: Dict[str, Any], sid: str) -> Dict[str, str]:
    c = rg["cell"]
    for role in ("primary", "ok", "avoid"):
        hit = next((x for x in c.get(role, []) if x[0] == sid), None)
        if hit:
            r = role
            if r == "primary" and rg.get("flat") and sid in GR_SHORT_VOL:
                r = "ok"
            if r == "primary" and rg.get("bear_steep") and sid == "long_call":
                r = "ok"
            return {"role": r, "why": hit[1]}
    d = GR_STRUCTS[sid]["dir"] if sid in GR_STRUCTS else None
    if rg["dir"] == "risk_off" and d == "bull":
        return {"role": "avoid", "why": "Posture AVOID: no new longs."}
    if rg["dir"] in ("risk_on", "recovery") and d == "bear":
        return {"role": "avoid", "why": "Shorts fight the tape."}
    if rg["vol"] == "stressed" and sid in GR_SHORT_VOL:
        return {"role": "avoid", "why": _NO_SHORT_VOL}
    return {"role": "neutral", "why": "Not on this cell's list: graded on its own merits."}


def gr_primary_names(rg: Dict[str, Any]) -> str:
    return ", ".join(GR_SNAME[x[0]].lower() for x in rg["cell"]["primary"])


def gr_iv_at(expiries: List[Dict[str, Any]], D: float) -> Optional[float]:
    """Total-variance interpolation of ATM IV at D days; None beyond the listed range (+25%)."""
    pts = sorted((e["dte"], e["atm"]) for e in (expiries or []) if e.get("atm") and e["dte"] > 0)
    if not pts:
        return None
    if D <= pts[0][0]:
        return pts[0][1]
    if D >= pts[-1][0]:
        return pts[-1][1] if D <= pts[-1][0] * 1.25 else None
    for (t1, v1), (t2, v2) in zip(pts, pts[1:]):
        if t2 >= D:
            w = v1 * v1 * t1 + (v2 * v2 * t2 - v1 * v1 * t1) * (D - t1) / (t2 - t1)
            return math.sqrt(max(w, 1e-8) / D)
    return None


def gr_name_vol(src: Optional[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
    """A name's own vol: level against realized and its own history, term slope, skew."""
    if not src:
        return None
    c25 = p25 = None
    if src.get("expiries"):
        iv30 = src.get("iv30") or gr_iv_at(src["expiries"], 30)
        iv60 = gr_iv_at(src["expiries"], 60)
        es = [x for x in src["expiries"] if x.get("atm")]
        if es:
            e = min(es, key=lambda x: abs(x["dte"] - 30))
            c25, p25 = e.get("c25"), e.get("p25")
    else:
        iv30 = _gnum(src.get("iv")) / 100 if _gnum(src.get("iv")) is not None else None
        iv60 = _gnum(src.get("iv2")) / 100 if _gnum(src.get("iv2")) is not None else None
        c25, p25 = _gnum(src.get("callSkew")), _gnum(src.get("putSkew"))
    hv = _gnum(src.get("hv20") if src.get("hv20") is not None else src.get("hv"))
    ivr = _gnum(src.get("ivr"))
    vr = math.log(iv30 * 100 / hv) if (iv30 and hv) else None
    # IV usually sits ~15% (log) above realized, so 0.15 is "fair"; IV rank 50 is mid-range.
    rs = ws = 0.0
    if vr is not None:
        rs += 0.7 * _gclamp((vr - 0.15) / 0.30, -1, 1)
        ws += 0.7
    if ivr is not None:
        rs += 0.3 * _gclamp((ivr - 50) / 40, -1, 1)
        ws += 0.3
    rich = rs / ws if ws else None
    level = None if rich is None else "rich" if rich >= 0.35 else "cheap" if rich <= -0.35 else "fair"
    slope = iv30 / iv60 - 1 if (iv30 and iv60) else None
    term = None if slope is None else "inverted" if slope >= 0.05 else "steep" if slope <= -0.08 else "normal"
    return {"iv30": iv30, "iv60": iv60, "hv": hv, "ivr": ivr, "vr": vr, "rich": rich, "level": level, "slope": slope, "term": term,
            "c25": c25, "p25": p25}


def gr_name_fit(sid: str, nv: Optional[Dict[str, Any]], o: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    o = o or {}
    s, w = 0.0, []
    if not nv:
        return {"score": 0.0, "why": w}
    rich, cheap = nv["level"] == "rich", nv["level"] == "cheap"
    inv, steep = nv["term"] == "inverted", nv["term"] == "steep"
    vol_txt = ", ".join(x for x in ((f"IV/HV {math.exp(nv['vr']):.2f}" if nv["vr"] is not None else ""),
                                    (f"IV rank {_jr(nv['ivr'])}" if nv["ivr"] is not None else "")) if x)
    ed = o.get("earnings_days")
    e_soon = ed is not None and 0 <= ed <= 30
    calls_bid = nv["c25"] is not None and nv["c25"] >= 0
    put_skew = nv["p25"] is not None and nv["p25"] >= 12
    R, C = f"Rich vol ({vol_txt})", f"Cheap vol ({vol_txt})"

    def add(d, t):
        nonlocal s
        s += d
        w.append(t)
    if sid == "long_call":
        if cheap: add(2, f"{C}: convexity costs little")
        if rich: add(-2, f"{R}: a spread sells part of it back")
        if calls_bid: add(-0.5, "Calls are bid over ATM: upside is expensive")
    elif sid == "debit_call":
        if rich: add(1, f"{R}: the short call sells it back")
        if calls_bid: add(0.5, "Calls bid over ATM: the short leg collects that")
    elif sid == "credit_put":
        if rich: add(2, f"{R}: you are paid to be long")
        if cheap: add(-2, f"{C}: a thin credit for the gap risk")
        if put_skew: add(1, f"Puts carry {nv['p25']:.0f}% skew: the risk-reversal premium")
        if e_soon: add(-1.5, "Earnings inside 30 days: gap risk through the short put")
    elif sid == "long_put":
        if cheap: add(2, f"{C}: protection is cheap")
        if rich: add(-2, f"{R}: a put spread sells part of it back")
        if put_skew: add(-0.5, "Steep put skew: outright puts pay the most premium")
    elif sid == "debit_put":
        if put_skew: add(1, "Steep put skew makes the put you sell rich")
        if rich: add(0.5, f"{R}: the short put sells some back")
    elif sid == "credit_call":
        if rich: add(2, f"{R}: rich calls to sell")
        if cheap: add(-2, f"{C}: a thin credit")
        if calls_bid: add(1, "Calls bid over ATM: rich to sell")
        if e_soon: add(-1.5, "Earnings inside 30 days: gap risk through the short call")
    elif sid == "long_straddle":
        if cheap: add(2, f"{C}: owning the move is cheap")
        if rich: add(-2, f"{R}: you would pay up for the move")
        if steep: add(1, "Front IV well below the back month: short-dated vol is the cheap part (Vasquez)")
        if inv: add(-1, "Front IV above the back month: short-dated vol is the expensive part")
        if o.get("bbuw") is not None and o["bbuw"] >= 75: add(1, f"Daily BBUW {_jr(o['bbuw'])}: compression before expansion")
    elif sid == "iron_condor":
        if rich: add(2, f"{R}: premium worth selling")
        if cheap: add(-1.5, f"{C}: a thin credit")
        if e_soon: add(-2, "Earnings inside 30 days: a condor sells the event cheap")
        if inv: add(-0.5, "An inverted front month often means an event or stress")
    elif sid == "calendar":
        if inv: add(2, f"Front IV {nv['slope'] * 100:.0f}% over the back month: sell the rich front")
        if steep: add(-2, "Steep contango: the back month you buy is the expensive one")
        if nv["ivr"] is not None and nv["ivr"] <= 35: add(1, f"IV rank {_jr(nv['ivr'])}: back-month vega is cheap")
        if e_soon: add(-1, "Earnings inside the front month: the short leg holds the event")
    elif sid == "diagonal":
        if inv: add(1, "Inverted term: the short front call is rich")
        if rich: add(0.5, f"{R}: the short call sells it back")
    return {"score": s, "why": w}


def gr_name_advice(rg: Optional[Dict[str, Any]], nv: Optional[Dict[str, Any]], o: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    """Rank every gradeable structure for one name in today's cell: the cell's role first, then the name's own vol."""
    o = o or {}
    if not rg:
        return []
    W = {"primary": 3.0, "ok": 1.5, "neutral": -1.5, "avoid": -5.0}   # off-list needs a strong name fit to show
    out = []
    for sid in GR_STRUCTS:
        fit, f, d = gr_role_of(rg, sid), gr_name_fit(sid, nv, o), GR_STRUCTS[sid]["dir"]
        score = W[fit["role"]] + f["score"]
        why = ([] if fit["role"] == "neutral" else [fit["why"]]) + f["why"]
        if o.get("dir_hint") and d in ("bull", "bear"):
            if d == o["dir_hint"]:
                score += 1
            else:
                score -= 1.5
                why.append(f"The War Room trigger on this name is {'bullish' if o['dir_hint'] == 'bull' else 'bearish'}")
        if rg.get("mode") == "CASH" and d == "bull":
            score = -99.0
            why.insert(0, "Entry mode CASH: no new longs")
        out.append({"sid": sid, "label": GR_SNAME[sid], "role": fit["role"], "score": score, "why": why})
    return sorted(out, key=lambda a: -a["score"])



# ---------- grader data: the lab's chains and bars, plus War Room files when present ----------
def _gr_interp(x: float, pts: List[Tuple[float, float]]) -> Optional[float]:
    pts = sorted(p for p in pts if p[0] is not None and p[1] is not None)
    if not pts:
        return None
    if x <= pts[0][0]:
        return pts[0][1]
    if x >= pts[-1][0]:
        return pts[-1][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x0 <= x <= x1:
            return y0 if x1 == x0 else y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    return None


def gr_expiries(cons: List[dict], spot: float) -> List[Dict[str, Any]]:
    """Chain contracts (extract_contract rows) -> per expiry: ATM IV at spot, Moontower 25-delta skew
    (25d IV / ATM IV - 1, in %), and compact strike rows [k, call[mid,bid,ask,iv,delta,oi], put[...]]."""
    by_exp: Dict[Tuple[str, int], List[dict]] = {}
    for c in cons:
        if c and c.get("strike") and c.get("expiration") and c.get("dte") is not None and c["dte"] > 0 and c.get("type") in ("call", "put"):
            by_exp.setdefault((c["expiration"], c["dte"]), []).append(c)
    out = []
    for (exp, dte), legs in sorted(by_exp.items(), key=lambda kv: kv[0][1]):
        by_k: Dict[float, List[float]] = {}
        for c in legs:
            if c.get("iv"):
                by_k.setdefault(c["strike"], []).append(c["iv"])
        atm = _gr_interp(spot, [(k, sum(v) / len(v)) for k, v in by_k.items()])
        c25 = _gr_interp(0.25, [(c["delta"], c["iv"]) for c in legs if c["type"] == "call" and c.get("iv") and c.get("delta") is not None])
        p25 = _gr_interp(-0.25, [(c["delta"], c["iv"]) for c in legs if c["type"] == "put" and c.get("iv") and c.get("delta") is not None])
        sk = (lambda v: round((v / atm - 1) * 100, 2) if (v and atm) else None)

        def leg(c):
            if not c:
                return None
            mid = c.get("mid")
            return [mid, c.get("bid"), c.get("ask"), c.get("iv"), c.get("delta"), None if c.get("oi") is None else int(c["oi"])]
        rows: Dict[float, Dict[str, dict]] = {}
        for c in legs:
            rows.setdefault(c["strike"], {})[c["type"]] = c
        out.append({"exp": exp, "dte": int(dte), "atm": atm, "c25": sk(c25), "p25": sk(p25),
                    "strikes": [[k, leg(v.get("call")), leg(v.get("put"))] for k, v in sorted(rows.items())]})
    return out


def _gr_py(v: Any) -> Any:
    """numpy / pandas scalars -> plain values (np.bool_ is not a bool; NaN becomes None)."""
    if v is None:
        return None
    if hasattr(v, "item") and not isinstance(v, (list, dict, str)):
        try:
            v = v.item()
        except Exception:
            pass
    if isinstance(v, float) and not math.isfinite(v):
        return None
    return v


def _gr_last_row(path: Path) -> Dict[str, Any]:
    try:
        df = pd.read_parquet(path)
        return {k: _gr_py(v) for k, v in df.iloc[-1].to_dict().items()} if len(df) else {}
    except Exception:
        return {}


def _gr_json(path: Path) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return None


def _gr_stamp(d: Path, names: Tuple[str, ...]) -> Tuple:
    out = []
    for n_ in names:
        try:
            out.append((n_, (d / n_).stat().st_mtime))
        except OSError:
            out.append((n_, None))
    return tuple(out)


def gr_load_macro(d: Path) -> Dict[str, Any]:
    """The War Room's macro read: posture and entry mode, VIX, its 5-year percentile, VIX/VIX3M, SPY trend,
    credit and carry. Empty when the War Room files are not in the folder."""
    nr = _gr_last_row(d / "narrative_regime.parquet")
    tm = _gr_last_row(d / "tactical_macro_state.parquet")
    vc = _gr_json(d / "vol_compression.json") or {}
    ir = _gr_json(d / "index_read.json") or {}
    if not (nr or tm or vc or ir):
        return {}
    m: Dict[str, Any] = {k: nr.get(k) for k in (
        "posture", "entry_mode", "entry_mode_reason", "regime_score", "current_state_name", "current_class",
        "acceleration_label", "real_rate_10y", "real_rate_label", "carry_signal", "carry_jpy_5d", "curve_regime",
        "spread_2s10s", "fed_stance", "dxy_signal", "generated_at")}
    m["tactical_label"] = tm.get("regime_label")
    m["vix"] = tm.get("headline_vix_level") if tm.get("headline_vix_level") is not None else vc.get("vix")
    m["vix_term_ratio"] = tm.get("headline_vix_term_ratio")
    m["vix_pct_5y"] = vc.get("vix_pct_5y")
    m["credit_impulse"] = tm.get("stress_credit_impulse_signal")
    m["hyg_lqd_above_50"] = tm.get("stress_hyg_lqd_above_50")
    m["rsp_spy_above_50"] = tm.get("participation_rsp_spy_above_sma")
    m["iwm_spy_above_50"] = tm.get("participation_iwm_spy_above_sma")
    spy = next((x for x in ir.get("indices", []) if x.get("ticker") == "SPY"), None)
    if spy:
        dd, ww = spy.get("daily") or {}, spy.get("weekly") or {}
        m["spy"] = {"above_50": dd.get("above_50sma"), "above_200": dd.get("above_200sma"),
                    "pct_from_52w_high": ww.get("pct_from_52w_high"), "weekly_trend": ww.get("trend")}
    warnings = []
    if tm and tm.get("headline_spy_close") is None:
        warnings.append("tactical_macro_state has no SPY close, so its SPY 50/200-day flags and sector breadth read False/0. "
                        "SPY trend here comes from index_read.json instead.")
    m["warnings"] = warnings
    return m


def gr_conviction_points(e: Dict[str, Any]) -> int:
    """Same points as daily_screener.assign_conviction (HIGH >= 7, MED >= 4)."""
    wb, db_, tt, ir = (e.get("weekly_bbuw") or 0), (e.get("daily_bbuw") or 0), (e.get("trend_template") or 0), (e.get("industry_rank") or 99)
    p = int(wb >= 60) + int(wb >= 75) + int(db_ >= 60) + int(db_ >= 75) + int(tt >= 6) + int(tt == 8) + int(ir <= 10) + int(ir <= 3)
    p += {"STANDARD": 1, "STRONG": 2}.get(e.get("pivot_8w_tier") or "", 0)
    p += {"WATCH": 1, "STANDARD": 2, "STRONG": 3}.get(e.get("ep_tier") or "", 0)
    return int(p)


def gr_load_warroom(d: Path) -> Dict[str, Any]:
    wl = _gr_json(d / "daily_watchlist.json") or {}
    trig = _gr_json(d / "latest_triggers.json") or {}
    entries = {e["ticker"]: e for e in wl.get("entries", []) if e.get("ticker")}
    triggers: Dict[str, dict] = {}
    for t in trig.get("triggers", []):
        tk = t.get("ticker")
        if tk and (tk not in triggers or str(t.get("trigger_time") or "") > str(triggers[tk].get("trigger_time") or "")):
            triggers[tk] = t
    return {"entries": entries, "triggers": triggers}


def gr_warroom_fields(tk: str, wr: Dict[str, Any]) -> Dict[str, Any]:
    e = (wr or {}).get("entries", {}).get(tk)
    out: Dict[str, Any] = {}
    if e:
        out = {k: e.get(k) for k in ("conviction", "theme", "theme_rank", "daily_bbuw", "pivot_8w_tier", "ep_tier", "high_20d")}
        out["conviction_points"] = gr_conviction_points(e)
    t = (wr or {}).get("triggers", {}).get(tk)
    if t:
        bull = (t.get("direction") or "bullish") == "bullish"
        out["trigger"] = {"price": t.get("pivot_high") if bull else t.get("pivot_low"), "stop": t.get("stop_level"),
                          "direction": "bull" if bull else "bear",
                          "src": f"{t.get('trigger_type', 'trigger')} {t.get('timeframe', '')} {str(t.get('trigger_time', ''))[:16]}".strip()}
    elif e and e.get("high_20d"):
        out["trigger"] = {"price": e.get("high_20d"), "stop": None, "direction": "bull", "src": "20-day high"}
    return out


def gr_warroom(d: Path) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    files = ("narrative_regime.parquet", "tactical_macro_state.parquet", "vol_compression.json", "index_read.json",
             "daily_watchlist.json", "latest_triggers.json")
    stamp = _gr_stamp(d, files)
    return memo(("gr_wr", str(d), stamp), lambda: (gr_load_macro(d), gr_load_warroom(d)))


def gr_posture_from_climate(clim: Optional[Dict[str, Any]]) -> Tuple[Optional[str], str]:
    """No War Room posture: suggest one from the lab's climate chip (a judgment call, labeled as such)."""
    if not clim or clim.get("h") is None:
        return None, ""
    sticky = str(clim["h"].get("sticky"))
    trend = str((clim.get("ann") or {}).get("trend"))
    if sticky == "STEADY":
        p = "BUY_RIP" if trend == "TR-UP" else "NEUTRAL"
    else:
        p = {"WOI": "BUY_DIP", "CRISIS": "AVOID"}.get(sticky, "NEUTRAL")
    return p, f"Climate {sticky}{' with ' + trend if trend and trend != 'None' else ''} → {p} (suggested; the War Room posture overrides it)"


def gr_spy_read(cfg: Dict[str, Any], bench_bars: Dict[str, pd.DataFrame], hvs: Dict[str, float]) -> Optional[Dict[str, Any]]:
    """SPY 30- and 90-day ATM IV from one chain: a VIX and VIX/VIX3M proxy when the War Room files are absent."""
    rows = st.session_state.get("vol_res") or []
    hit = next((r for r in rows if r.get("sym") == "SPY"), None)
    if hit:
        return hit
    if cfg["source"] not in ("massive", "demo") or "SPY" not in bench_bars:
        return None
    spot = float(bench_bars["SPY"]["close"].iloc[-1])

    def build():
        raw = fetch_chain("SPY", 100, cfg["source"], cfg["key"], spot, hvs.get("SPY", 0.15), cfg["strip"], band=0.06)
        cons = [x for x in (extract_contract(r, date.today()) for r in raw) if x]
        sp = next((x["spot"] for x in cons if x["spot"]), None) or spot
        return chain_vol_read("SPY", cons, sp, hvs.get("SPY", np.nan))
    return memo(("gr_spy", date.today().isoformat(), session_phase(), cfg["source"], cfg["strip"]), build)


def gr_ticker(tk: str, cfg: Dict[str, Any], uni: pd.DataFrame, bars: Dict[str, pd.DataFrame],
              bench_bars: Dict[str, pd.DataFrame], wr: Dict[str, Any]) -> Dict[str, Any]:
    """Everything the grader fills for one ticker: spot, HV20, ADR, the chain by expiry, IV rank, earnings, War Room fields."""
    df = bars.get(tk) if tk in bars else bench_bars.get(tk)
    if df is None:
        got, _ = get_bars([tk], UNIVERSE_DAYS, cfg["source"], cfg["key"], cfg["drop_partial"])
        df = got.get(tk)
    if df is None or len(df) < 25:
        raise PlanError(f"No daily bars for {tk}.")
    close = df["close"].astype(float)
    spot = float(close.iloc[-1])
    hv = float(np.log(close).diff().iloc[-20:].std() * math.sqrt(252))
    adr = float(((df["high"] / df["low"] - 1) * 100).iloc[-20:].mean())

    def build():
        raw = fetch_chain(tk, 95, cfg["source"], cfg["key"], spot, hv, cfg["strip"], band=0.30)
        return [x for x in (extract_contract(r, date.today()) for r in raw) if x]
    cons = memo(("gr_chain", tk, date.today().isoformat(), session_phase(), cfg["source"], cfg["strip"]), build)
    sp = next((x["spot"] for x in cons if x.get("spot")), None) or spot
    exps = gr_expiries(cons, sp)
    iv30 = gr_iv_at(exps, 30)
    row = uni.set_index("ticker").loc[tk] if (len(uni) and tk in set(uni["ticker"])) else None
    ivr, ivr_src = None, None
    if row is not None and "bc_iv_rank" in row.index and pd.notna(row.get("bc_iv_rank")):
        ivr, ivr_src = float(row["bc_iv_rank"]) * 100, "Barchart"
    elif iv30:
        rk, _, n_ = iv_rank(tk, iv30)
        if rk is not None:
            ivr, ivr_src = rk * 100, f"Vol desk archive (n={n_})"
    earn = None
    if row is not None and "bc_earn" in row.index and pd.notna(row.get("bc_earn")):
        earn = pd.Timestamp(row["bc_earn"]).date().isoformat()
    theme = (str(row["theme"]) if (row is not None and row.get("theme")) else None)
    trank = _gnum(row.get("theme_rank")) if (row is not None and "theme_rank" in row.index) else None
    w = gr_warroom_fields(tk, wr)
    return {"t": tk, "spot": sp, "hv20": hv * 100, "adr": adr, "iv30": iv30, "ivr": ivr, "ivr_src": ivr_src, "earnings": earn,
            "theme": theme or w.get("theme"), "theme_rank": trank if trank is not None else _gnum(w.get("theme_rank")),
            "quotes": any(c.get("bid") is not None for c in cons), "warroom": w, "expiries": exps,
            "asof": datetime.now().isoformat(timespec="minutes"), "n_contracts": len(cons)}


def gr_quote(T: Dict[str, Any], E: Dict[str, Any], structure: str, strikes: Dict[str, Any],
             B: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
    """Price a structure from the chain: mid (or IV-implied mid without quotes), and the natural bid/ask from the legs."""
    meta = GR_STRUCTS[structure]
    if meta.get("two") and not B:
        return None

    def snap(X, K, ty):
        li = 1 if ty == "C" else 2
        rows = [r for r in X["strikes"] if r[li] and (r[li][0] is not None or r[li][3] is not None)]
        return min(rows, key=lambda r: abs(r[0] - K)) if rows else None
    tmp = gr_build({"structure": structure, "price": 0.01, **strikes, "dte": E["dte"], "dte2": B["dte"] if B else ""})
    if tmp["errs"]:
        return None
    legs = []
    for ty, K, q, dT in tmp["legs"]:
        X = B if dT else E
        r = snap(X, K, ty)
        if not r:
            return None
        lg = r[1] if ty == "C" else r[2]
        mid = lg[0] if lg[0] is not None else _gbs(T["spot"], r[0], max(X["dte"], 1) / 365, lg[3], ty)
        legs.append({"ty": ty, "K": r[0], "q": q, "mid": float(mid), "bid": lg[1], "ask": lg[2], "back": bool(dT)})
    if structure == "calendar" and legs[0]["K"] != legs[1]["K"]:
        return None
    net = sum(l_["q"] * l_["mid"] for l_ in legs)
    has_q = all(l_["bid"] is not None and l_["ask"] is not None for l_ in legs)
    pay = sum(l_["q"] * (l_["ask"] if l_["q"] > 0 else l_["bid"]) for l_ in legs) if has_q else None
    get = sum(l_["q"] * (l_["bid"] if l_["q"] > 0 else l_["ask"]) for l_ in legs) if has_q else None
    debit = meta["kind"] == "debit"
    price = net if debit else -net
    bid = (get if debit else -pay) if has_q else None
    ask = (pay if debit else -get) if has_q else None
    ks = [l_["K"] for l_ in legs]
    if structure == "diagonal":
        snapped = {"lo": next(l_["K"] for l_ in legs if l_["back"]), "hi": next(l_["K"] for l_ in legs if not l_["back"])}
    elif len(meta["strikes"]) == 2:
        snapped = {"lo": min(ks), "hi": max(ks)}
    elif len(meta["strikes"]) == 4:
        s4 = sorted(ks)
        snapped = {"pl": s4[0], "ps": s4[1], "cs": s4[2], "cl": s4[3]}
    else:
        snapped = {"k": ks[0]}
    return {"price": price, "bid": bid, "ask": ask, "has_q": has_q, "snapped": snapped}


def gr_fill(T: Dict[str, Any], E: Dict[str, Any], vals: Dict[str, Any], fresh: bool = False,
            keep_setup: bool = False) -> Tuple[Dict[str, Any], List[str], str]:
    """Port of the artifact's Fill from feed: returns field updates, what was filled, and the price hint."""
    up: Dict[str, Any] = {}
    filled: List[str] = []
    up.update({"spot": round(T["spot"], 2), "dte": float(E["dte"]), "hv": round(T["hv20"], 1), "adr": round(T["adr"], 2)})
    if E.get("atm"):
        up["iv"] = round(E["atm"] * 100, 1)
    filled.append("price, IV, DTE, HV20, ADR")
    up["ivr"] = float(_jr(T["ivr"])) if T.get("ivr") is not None else None
    if T.get("ivr") is not None:
        filled.append(f"IV rank ({T['ivr_src']})")
    if E.get("c25") is not None:
        up["callSkew"] = float(E["c25"])
    if E.get("p25") is not None:
        up["putSkew"] = float(E["p25"])
    up["earnings"] = bool(T.get("earnings") and T["earnings"] <= E["exp"])
    if T.get("earnings"):
        filled.append(f"earnings {T['earnings']}")
    w = T.get("warroom") or {}
    up["conv"] = float(w["conviction_points"]) if w.get("conviction_points") is not None else None
    if w.get("conviction_points") is not None:
        filled.append(f"conviction {w['conviction_points']} ({w.get('conviction')})")
    else:
        filled.append("not on the War Room watchlist: conviction blank")
    up["themeRank"] = float(T["theme_rank"]) if T.get("theme_rank") is not None else None
    if w.get("daily_bbuw") is not None:
        up["bbuw"] = float(_jr(w["daily_bbuw"]))
    trig = w.get("trigger") or {}
    if trig.get("price"):
        up["pivot"] = round(float(trig["price"]), 2)
        filled.append(f"trigger {float(trig['price']):.2f} ({trig.get('src')})")
        up["stop"] = round(float(trig["stop"]), 2) if trig.get("stop") else None
    else:
        up["pivot"], up["stop"] = None, None
    up["resist"] = None
    structure = vals.get("structure")
    meta = GR_STRUCTS[structure]
    if not keep_setup and meta["mode"] == "dir" and vals.get("setup") != "bear":
        if w.get("pivot_8w_tier") in ("STRONG", "STANDARD", "PROXIMITY"):
            up["setup"] = "pivot8w"
        elif w.get("ep_tier") in ("WATCH", "STANDARD", "STRONG"):
            up["setup"] = "ep"
    B = None
    if meta.get("two"):
        cands = [e for e in T["expiries"] if e["dte"] >= E["dte"] + 21 and e.get("atm")]
        B = min(cands, key=lambda e: abs(e["dte"] - E["dte"] - 28)) if cands else None
        if B:
            up.update({"dte2": float(B["dte"]), "iv2": round(B["atm"] * 100, 1)})
            filled.append(f"back month {B['exp']} (IV {B['atm'] * 100:.1f}%)")
        else:
            filled.append("no back month 3+ weeks after this expiry: pick an earlier front month")
        up["ivx"] = None
    hold = _gnum(vals.get("hold")) or 5
    Hx = _gnum(vals.get("hurst")) or 0.6
    sigH = ((T["hv20"] or (E.get("atm") or 0.4) * 100) / 100) / math.sqrt(252) * hold ** Hx

    def listed_in(X, ty):
        li = 1 if ty == "C" else 2
        return [r[0] for r in X["strikes"] if r[li] and (r[li][0] is not None or r[li][3] is not None)] if X else []

    def near_in(ks, x, not_=None):
        ks = [k for k in ks if k != not_]
        return min(ks, key=lambda k: abs(k - x)) if ks else None

    def near(x, ty, not_=None):
        return near_in(listed_in(E, ty), x, not_)
    S0 = T["spot"]
    ks = listed_in(E, "C") + listed_in(E, "P")
    k_min, k_max = (min(ks), max(ks)) if ks else (0, 0)
    in_range = lambda v: _gnum(v) is not None and k_min <= _gnum(v) <= k_max  # noqa: E731
    back_c = listed_in(B, "C")
    fits = (not fresh and all(in_range(vals.get(f)) for f in meta["strikes"])
            and (len(meta["strikes"]) != 2 or (_gnum(vals.get("lo")) or 0) < (_gnum(vals.get("hi")) or 0))
            and (structure != "calendar" or _gnum(vals.get("k")) in back_c)
            and (structure != "diagonal" or _gnum(vals.get("lo")) in back_c))
    strikes = {f: _gnum(vals.get(f)) for f in ("lo", "hi", "k", "pl", "ps", "cs", "cl")}
    if not fits and ks:
        upm = lambda m: S0 * math.exp(m * sigH)  # noqa: E731
        if structure == "debit_call":
            a = near(S0, "C")
            strikes.update(lo=a, hi=near(max(upm(1), a * 1.001), "C", a))
        elif structure == "debit_put":
            a = near(S0, "P")
            strikes.update(hi=a, lo=near(min(upm(-1), a * 0.999), "P", a))
        elif structure == "credit_put":
            a = near(upm(-0.5), "P")
            strikes.update(hi=a, lo=near(upm(-1.5), "P", a))
        elif structure == "credit_call":
            a = near(upm(0.5), "C")
            strikes.update(lo=a, hi=near(upm(1.5), "C", a))
        elif structure == "iron_condor":
            ps_ = near(upm(-1), "P")
            cs_ = near(upm(1), "C")
            strikes.update(ps=ps_, pl=near(upm(-1.5), "P", ps_), cs=cs_, cl=near(upm(1.5), "C", cs_))
        elif structure == "calendar":
            both = [k for k in listed_in(E, "C") if k in back_c]
            strikes.update(k=near_in(both or listed_in(E, "C"), S0))
        elif structure == "diagonal":
            a = near_in(back_c or listed_in(E, "C"), S0)
            strikes.update(lo=a, hi=near_in([k for k in listed_in(E, "C") if a is not None and k > a], upm(1)))
        else:
            strikes.update(k=near(S0, "P" if structure == "long_put" else "C"))
        filled.append(("strike at the money, listed in both months" if structure == "calendar" else
                       "long call at the money (back month), short call near T1 (front)" if structure == "diagonal" else
                       "strikes set from ATM to the T1 move"))
    tg = _gnum(vals.get("target"))
    sgn = 1 if meta["dir"] == "bull" else -1
    stale = tg is None or tg <= 0 or sgn * math.log(tg / S0) <= 0 or abs(math.log(tg / S0)) > 4 * sigH
    if meta["mode"] == "dir" and stale:
        up["target"] = round(S0 * math.exp(sgn * sigH), 2)
        filled.append("target set to T1: set your probability")
    q = gr_quote(T, E, structure, strikes, B)
    hint = "Your limit, per share"
    for f in meta["strikes"]:
        up[f] = strikes.get(f)
    if q:
        up.update({k: float(v) for k, v in q["snapped"].items()})
        up["price"] = round(q["price"], 2)
        up["bid"] = round(q["bid"], 2) if q["bid"] is not None else None
        up["ask"] = round(q["ask"], 2) if q["ask"] is not None else None
        if q["has_q"]:
            hint = ("Mid from the chain. Bid/ask is the legs' natural, the worst case: a package order usually fills inside it, "
                    "so enter your broker's package quote." if structure not in ("long_call", "long_put") else "Mid from the chain.")
        else:
            hint = "IV-implied mid (no quotes on Options Starter). Add bid/ask from your broker."
        if fits:
            filled.append("strikes snapped to listed strikes")
    return up, filled, hint



