def _gr_vals() -> Dict[str, Any]:
    return st.session_state.setdefault("gr_vals", dict(GR_DEFAULTS))


def _gr_coerce(f: str, v: Any) -> Any:
    if f in GR_NUM:
        x = _gnum(v)
        return None if x is None else float(x)
    if f in GR_BOOL:
        return bool(v)
    if f in ("burstDay", "h_trims"):
        x = _gnum(v)
        return int(x) if x is not None else (1 if f == "burstDay" else 0)
    return "" if v is None else str(v)


def _gr_set(f: str, v: Any) -> None:
    """Set a field and its widget. Only call before the widget is drawn in this run (callbacks, or the top of the tab)."""
    v = _gr_coerce(f, v)
    _gr_vals()[f] = v
    st.session_state["grw_" + f] = v


def _gr_seed(f: str) -> str:
    k = "grw_" + f
    if k not in st.session_state:
        st.session_state[k] = _gr_coerce(f, _gr_vals().get(f, GR_DEFAULTS.get(f)))
    return k


def gw_num(ct, label: str, f: str, step: float = 0.01, fmt: str = "%.2f", help: Optional[str] = None,
           minv: Optional[float] = None, maxv: Optional[float] = None) -> Optional[float]:
    k = _gr_seed(f)
    v = ct.number_input(label, key=k, step=float(step), format=fmt, help=help,
                        min_value=None if minv is None else float(minv), max_value=None if maxv is None else float(maxv))
    _gr_vals()[f] = v
    return v


def gw_sel(ct, label: str, f: str, options: List[Any], fmt=None, help: Optional[str] = None, horizontal: bool = False, radio: bool = False):
    k = _gr_seed(f)
    if st.session_state[k] not in options:
        st.session_state[k] = options[0]
    if radio:
        v = ct.radio(label, options, key=k, format_func=fmt or str, help=help, horizontal=horizontal)
    else:
        v = ct.selectbox(label, options, key=k, format_func=fmt or str, help=help)
    _gr_vals()[f] = v
    return v


def gw_chk(ct, label: str, f: str, help: Optional[str] = None, disabled: bool = False) -> bool:
    k = _gr_seed(f)
    v = ct.checkbox(label, key=k, help=help, disabled=disabled)
    _gr_vals()[f] = v
    return v


def gw_txt(ct, label: str, f: str, help: Optional[str] = None, placeholder: Optional[str] = None) -> str:
    k = _gr_seed(f)
    v = ct.text_input(label, key=k, help=help, placeholder=placeholder)
    _gr_vals()[f] = v
    return v


def _gr_setups_for(structure: str) -> List[str]:
    mode = GR_STRUCTS[structure]["mode"]
    return [k for k, v in GR_SETUPS.items() if v["mode"] in (mode, "any")]


def _gr_setup_for(sid: str, T: Optional[Dict[str, Any]], cur: Optional[str]) -> str:
    d, w = GR_STRUCTS[sid]["dir"], ((T or {}).get("warroom") or {})
    if sid == "calendar":
        return "term"
    if sid == "iron_condor":
        return "rich"
    if sid == "long_straddle":
        b = w.get("daily_bbuw") if w.get("daily_bbuw") is not None else _gnum(_gr_vals().get("bbuw"))
        return "compress" if (b is not None and b >= 60) else "cheap"
    if d == "bear":
        return "bear"
    if w.get("pivot_8w_tier") in ("STRONG", "STANDARD", "PROXIMITY"):
        return "pivot8w"
    if w.get("ep_tier") in ("WATCH", "STANDARD", "STRONG"):
        return "ep"
    return cur if (cur in GR_SETUPS and GR_SETUPS[cur]["mode"] == "dir" and cur not in ("bear", "none")) else "breakout"


def _gr_sync() -> Dict[str, Any]:
    """Start of every run: pick up widget edits, then keep the setup consistent with the structure."""
    vals = _gr_vals()
    for k in list(st.session_state.keys()):
        if isinstance(k, str) and k.startswith("grw_"):
            vals[k[4:]] = st.session_state[k]
    ex = st.session_state.get("gr_example")
    if ex in GR_EXAMPLES:   # any edit to the trade itself means these are no longer example inputs
        for k, v in GR_EXAMPLES[ex].items():
            if k in GR_REGIME_KEYS:
                continue
            a_, b_ = _gr_coerce(k, v), _gr_coerce(k, vals.get(k))
            if (a_ != b_) and not (isinstance(a_, float) and isinstance(b_, float) and abs(a_ - b_) < 1e-9):
                st.session_state.pop("gr_example", None)
                break
    s = vals.get("structure") if vals.get("structure") in GR_STRUCTS else "debit_call"
    vals["structure"] = s
    meta, cur = GR_STRUCTS[s], vals.get("setup")
    ok = _gr_setups_for(s)
    if cur not in ok or (meta["mode"] == "vol" and GR_SETUPS[cur].get("side") not in (None, meta["dir"])) or \
            (meta["mode"] == "dir" and (meta["dir"] == "bear") != (cur == "bear") and cur != "none"):
        _gr_set("setup", _gr_setup_for(s, None, cur) if meta["mode"] == "dir" else
                next(k for k in ok if GR_SETUPS[k].get("side") == meta["dir"]))
    return vals


def _gr_regime_from_sources(cfg, clim, bench_bars, hvs) -> Tuple[Dict[str, Any], List[str], Dict[str, Any]]:
    """Regime inputs from the War Room files first, then the lab (SPY chain read, climate). Returns values, sources, macro."""
    d = Path(_gr_vals().get("wrdir") or GR_WARROOM_DIR)
    m, _ = gr_warroom(d)
    out: Dict[str, Any] = {}
    src: List[str] = []
    if m.get("posture"):
        out.update(posture=m["posture"], mode=m.get("entry_mode") or "", carry=m.get("carry_signal") or "", curve=m.get("curve_regime") or "")
        src.append(f"Posture and entry mode from the War Room ({d.name}/narrative_regime.parquet)")
    else:
        p, why = gr_posture_from_climate(clim)
        if p:
            out.update(posture=p, mode="")
            src.append(why)
    if m.get("vix") is not None:
        out.update(vix=round(float(m["vix"]), 2), vixPct=m.get("vix_pct_5y"),
                   vixRatio=round(float(m["vix_term_ratio"]), 3) if m.get("vix_term_ratio") is not None else None)
        src.append("VIX, its 5-year percentile and VIX/VIX3M from the War Room tactical files")
    else:
        try:
            spy = gr_spy_read(cfg, bench_bars, hvs)
        except Exception:
            spy = None
        if spy and spy.get("iv30"):
            pc = vol_percentiles("SPY", spy) if cfg["source"] == "massive" else {}
            out.update(vix=round(spy["iv30"] * 100, 2), vixRatio=round(spy["term"], 3) if spy.get("term") else None,
                       vixPct=round(pc["iv30_pct"] * 100, 1) if pc.get("iv30_pct") is not None else None)
            src.append("VIX proxy: SPY 30-day ATM IV; VIX/VIX3M proxy: SPY 30- over 90-day IV"
                       + (" (percentile from the lab's vol archive)" if out.get("vixPct") is not None else " (no percentile yet: level bands)"))
    if hvs.get("SPY"):
        out["spyHv"] = round(hvs["SPY"] * 100, 1)
        src.append("SPY HV20 from the lab's bars")
    return out, src, m


def _gr_init(cfg, clim, bench_bars, hvs) -> Dict[str, Any]:
    vals = _gr_vals()
    if not st.session_state.get("gr_regime_seeded"):
        reg, src, _ = _gr_regime_from_sources(cfg, clim, bench_bars, hvs)
        for k, v in reg.items():
            _gr_set(k, v)
        st.session_state["gr_regime_src"] = src
        st.session_state["gr_regime_seeded"] = True
        if not vals.get("spot"):
            for k, v in GR_EXAMPLES["Clean pullback"].items():
                if k not in GR_REGIME_KEYS:
                    _gr_set(k, v)
            st.session_state["gr_example"] = "Clean pullback"
            st.session_state["gr_msg"] = ("Example trade loaded with today's regime. Type a ticker and Load chain & fill, "
                                          "or start from the Regime tab's first choices.")
    return _gr_sync()


# ---------- callbacks (run before the next rerun draws widgets) ----------
def _gr_cb_example(name: str) -> None:
    for k, v in GR_EXAMPLES[name].items():
        _gr_set(k, v)
    for f in ("lo", "hi", "k", "pl", "ps", "cs", "cl", "dte2", "iv2", "ivx", "pivot", "stop", "resist", "target", "p", "volf",
              "conv", "themeRank", "bbuw", "histMove", "timeStop"):
        if f not in GR_EXAMPLES[name]:
            _gr_set(f, None)
    st.session_state["gr_example"] = name
    st.session_state["gr_msg"] = f"Loaded the {name.lower()} example (its own regime included). Reset regime on the Regime tab to go back to today."


def _gr_cb_clear() -> None:
    keep = {k: _gr_vals().get(k) for k in GR_REGIME_KEYS + GR_BOOK_KEYS + ("wrdir",)}
    for f in list(GR_NUM | GR_TXT | GR_SEL | GR_BOOL):
        _gr_set(f, keep.get(f, GR_DEFAULTS.get(f)))
    st.session_state.pop("gr_example", None)
    st.session_state["gr_msg"] = "Cleared. Your regime and book settings were kept."


def _gr_cb_regime_reset(cfg, clim, bench_bars, hvs) -> None:
    reg, src, _ = _gr_regime_from_sources(cfg, clim, bench_bars, hvs)
    for k in GR_REGIME_KEYS:
        _gr_set(k, reg.get(k, GR_DEFAULTS.get(k)))
    st.session_state["gr_regime_src"] = src
    st.session_state["gr_preview"] = "today"


def _gr_load_ticker(tk: str, cfg, uni, bars, bench_bars) -> Optional[Dict[str, Any]]:
    d = Path(_gr_vals().get("wrdir") or GR_WARROOM_DIR)
    _, wr = gr_warroom(d)
    try:
        T = gr_ticker(tk, cfg, uni, bars, bench_bars, wr)
    except Exception as e:
        st.session_state["gr_msg"] = f"{tk}: {type(e).__name__}: {e}"
        return None
    st.session_state.setdefault("gr_tk", {})[tk] = T
    return T


def _gr_cb_fill(cfg, uni, bars, bench_bars, fresh: bool = False, keep_setup: bool = False) -> None:
    vals = _gr_vals()
    tk = _clean_ticker(st.session_state.get("grw_ticker", vals.get("ticker")))
    if not tk:
        st.session_state["gr_msg"] = "Type a ticker first."
        return
    if cfg["source"] not in ("massive", "demo"):
        st.session_state["gr_msg"] = "Filling from a chain needs Massive (Options Starter) or Demo as the data source."
        return
    T = _gr_load_ticker(tk, cfg, uni, bars, bench_bars)
    if not T or not T["expiries"]:
        if T is not None:
            st.session_state["gr_msg"] = f"{tk}: the chain came back empty."
        return
    want = st.session_state.get("gr_exp_pick")
    E = next((e for e in T["expiries"] if e["exp"] == want), None) or min(T["expiries"], key=lambda e: abs(e["dte"] - (_gnum(vals.get("dte")) or 35)))
    _gr_set("ticker", tk)
    up, filled, hint = gr_fill(T, E, {**vals, "ticker": tk}, fresh=fresh, keep_setup=keep_setup)
    for k, v in up.items():
        _gr_set(k, v)
    st.session_state["gr_exp_pick"] = E["exp"]
    st.session_state["gr_hint"] = hint
    st.session_state.pop("gr_example", None)
    st.session_state["gr_msg"] = f"{tk} {E['exp']}: filled " + " · ".join(filled) + "."


def _gr_cb_use(sid: str, tk: Optional[str], cfg, uni, bars, bench_bars) -> None:
    """Regime 'Grade this': switch structure and setup, then fill strikes and prices from the chain."""
    if tk:
        _gr_set("ticker", tk)
    tk = _clean_ticker(_gr_vals().get("ticker"))
    T = (st.session_state.get("gr_tk") or {}).get(tk)
    _gr_set("structure", sid)
    _gr_set("setup", _gr_setup_for(sid, T, _gr_vals().get("setup")))
    _gr_set("style", "")
    if tk and cfg["source"] in ("massive", "demo"):
        _gr_set("dte", GR_PREF_DTE.get(sid, 35))
        st.session_state["gr_exp_pick"] = None
        _gr_cb_fill(cfg, uni, bars, bench_bars, fresh=True, keep_setup=True)
        st.session_state["gr_msg"] = f"{GR_SNAME[sid]} on {tk}: open the Grade tab. " + st.session_state.get("gr_msg", "")
    else:
        st.session_state["gr_msg"] = f"Switched to {GR_SNAME[sid].lower()}. Open the Grade tab and enter strikes and prices."


def _gr_cb_target(price: float) -> None:
    _gr_set("target", round(price, 2))


def _gr_cb_ivx(v: Optional[float]) -> None:
    _gr_set("ivx", None if v is None else round(v, 1))


def _gr_cb_pair(L: float, H: float, cost: float, q: Optional[Dict[str, Any]]) -> None:
    bull = GR_STRUCTS[_gr_vals().get("structure")]["dir"] == "bull"
    _gr_set("structure", "debit_call" if bull else "debit_put")
    _gr_set("lo", L)
    _gr_set("hi", H)
    if q:
        _gr_set("price", round(q["price"], 2))
        _gr_set("bid", round(q["bid"], 2) if q.get("bid") is not None else None)
        _gr_set("ask", round(q["ask"], 2) if q.get("ask") is not None else None)
        st.session_state["gr_hint"] = "Mid from the chain." if q.get("has_q") else "IV-implied mid from the chain. Add bid/ask from your broker."
    else:
        _gr_set("price", _jr(cost * 20) / 20)
        _gr_set("bid", None)
        _gr_set("ask", None)
        st.session_state["gr_hint"] = "Model estimate from Strikes. Enter the real quote and bid/ask."
    st.session_state["gr_msg"] = f"Strikes {L:g}/{H:g} copied to the Grade tab."


# ---------- the log (data/grader_log.csv) ----------
def gr_load_log() -> pd.DataFrame:
    try:
        df = pd.read_csv(GR_LOG, dtype={"ticker": str, "why": str, "note": str, "plan": str, "inputs": str})
    except Exception:
        df = pd.DataFrame(columns=GR_LOG_COLS)
    for c in GR_LOG_COLS:
        if c not in df.columns:
            df[c] = np.nan
    return df[GR_LOG_COLS]


def gr_save_log(df: pd.DataFrame) -> None:
    GR_LOG.parent.mkdir(parents=True, exist_ok=True)
    tmp = GR_LOG.with_suffix(".tmp")
    df[GR_LOG_COLS].to_csv(tmp, index=False)
    os.replace(tmp, GR_LOG)


def _gr_bool(v) -> Optional[bool]:
    if isinstance(v, (bool, np.bool_)):
        return bool(v)
    s = str(v).strip().lower()
    return True if s in ("true", "yes", "1", "1.0") else False if s in ("false", "no", "0", "0.0") else None


def _gr_r(row) -> Optional[float]:
    pnl, ml = _gnum(row.get("pnl")), _gnum(row.get("max_loss"))
    c = _gnum(row.get("contracts_filled")) or _gnum(row.get("contracts")) or 1
    return pnl / (c * ml * 100) if (pnl is not None and ml) else None


def _gr_clv(row) -> Optional[float]:
    m3, px, ml = _gnum(row.get("mark3")), _gnum(row.get("price")), _gnum(row.get("max_loss"))
    if m3 is None or px is None or not ml:
        return None
    return (m3 - px) / ml if row.get("kind") == "debit" else (px - m3) / ml


def _gr_ctx(vals: Dict[str, Any], log: pd.DataFrame, uni: pd.DataFrame) -> Dict[str, Any]:
    themes = dict(zip(uni["ticker"], uni["theme"])) if len(uni) else {}
    rows = log.to_dict("records")
    resolved = [r for r in rows if _gr_bool(r.get("target_hit")) is not None and r.get("status") in ("closed", "passed")]
    cal = gr_calibration([{"target_hit": _gr_bool(r.get("target_hit")), "p_user_raw": _gnum(r.get("p_user_raw")), "p_mkt": _gnum(r.get("p_mkt"))}
                          for r in resolved])
    open_ = []
    for r in rows:
        if r.get("status") == "open" and _gnum(r.get("max_loss")):
            tk = str(r.get("ticker") or "").upper()
            c = _gnum(r.get("contracts_filled"))
            c = c if c is not None else (_gnum(r.get("contracts")) or 0)
            open_.append({"ticker": tk, "theme": themes.get(tk) or "Unclassified", "risk": c * _gnum(r["max_loss"]) * 100})
    tk = _clean_ticker(vals.get("ticker")) or ""
    book = {"open": open_, "ticker": tk, "theme": themes.get(tk) or ("Unclassified" if tk and tk != "DEMO" else None),
            "heat_cap": (_gnum(vals.get("heatCap")) or 30) / 100, "rho_same": _gnum(vals.get("rhoSame")) or 0.6,
            "rho_cross": _gnum(vals.get("rhoCross")) or 0.2}
    return {"cap_until_calibrated": bool(vals.get("capCal")), "use_cal": bool(vals.get("useCal")), "closed_count": len(resolved),
            "calibration": cal, "book": book}


# ---------- small HTML pieces (built before entering columns) ----------
def _gr_money(x: Optional[float]) -> str:
    if x is None or not np.isfinite(x):
        return "—"
    return ("−$" if x < 0 else "$") + f"{abs(x):,.0f}"


def _gr_d2(x: Optional[float]) -> str:
    return "—" if x is None or not np.isfinite(_n(x, np.nan)) else f"${float(x):,.2f}"


def _gr_pct(x: Optional[float], d: int = 0) -> str:
    return pct(x, d)


def _gr_verdict_html(r: Dict[str, Any]) -> str:
    c = GR_LETTER_COLOR.get(r["letter"], C_MUTED)
    sz = r["size"]
    lim = {"kelly": "half-Kelly cap", "overlap": "cut for open same-theme risk", "heat": "open-risk cap"}.get(
        sz["limited_by"], f"{sz['mult'] * sz['regime_mult'] * 100:.0f}% of base")
    size = (f"<b>{sz['contracts']}</b> contract{'s' if sz['contracts'] != 1 else ''} · <b>{_gr_money(sz['contracts'] * sz['per_contract'])}</b> at risk"
            f"<br/>Budget {_gr_money(sz['risk_dollars'])} ({_esc(lim)})" + (f" · regime ×{sz['regime_mult']:.2g}" if sz["regime_mult"] < 1 else "")
            + (f" · {_esc(sz['cap_note'])}" if sz.get("cap_note") else "")) if sz["mult"] > 0 else "Size: none"
    return (f"<div class='gr-verdict' style='--vc:{c}'><div class='gr-letter'>{_esc(r['letter'])}</div><div>"
            f"<div class='gr-vt'>{_esc(r['verdict'])}</div><div class='gr-vs'>{r['score']:.0f} / 100 · {_esc(r['struct_label'])}</div>"
            f"<div class='gr-vs' style='color:var(--text)'>{size}</div></div></div>")


def _gr_pillars_html(r: Dict[str, Any]) -> str:
    names = {"edge": "Edge", "entry": "Entry", "price": "Price", "odds": "Odds"}
    h = "".join(f"<div class='gr-pil'><div class='gr-pil-top'><span>{names[k]}</span><span>{v['pts']:.1f} / {v['max']}</span></div>"
                f"<div class='gr-track'><div class='gr-fill' style='width:{v['pts'] / v['max'] * 100:.1f}%'></div></div>"
                f"<div class='gr-pn'>{_esc(' · '.join(v['notes']))}</div></div>" for k, v in r["pillars"].items())
    if r.get("adj"):
        h += f"<div class='gr-pn'>Regime adjustment {r['adj']:+.0f}</div>"
    return h


def _gr_line_html(r: Dict[str, Any]) -> str:
    def cell(lbl, big, sub, col="var(--text)"):
        return f"<div><div class='l'>{_esc(lbl)}</div><div class='b' style='color:{col}'>{_esc(big)}</div><div class='s'>{_esc(sub)}</div></div>"
    if r.get("vert"):
        v = r["vert"]
        side = "above" if v["bullish"] else "below"
        good = (v["p_you_mid"] or 0) > v["p_mkt_mid"]
        return ("<div class='gr-line'>" + cell("Market's line", pct(v["p_mkt_mid"]), f"to finish {side} ${v['mid']:.2f} · pays {v['odds']:.2f} to 1")
                + cell("Your line", pct(v["p_you_mid"]), "same bet, from your target and probability", C_GREEN if good else C_RED) + "</div>")
    if r["mode"] == "dir" and r.get("p_mkt") is not None:
        return ("<div class='gr-line'>" + cell("Market's line", pct(r["p_mkt"]), f"to reach ${r['target']:.2f} by exit day")
                + cell("Your line", pct(r["p_user"]), "your stated probability", C_GREEN if r["p_user"] > r["p_mkt"] else C_RED) + "</div>")
    if r["mode"] == "vol" and r.get("two"):
        col = C_TEXT if abs(r["ivx"] - r["iv_fwd"]) < 0.0005 else (C_GREEN if r["ivx"] > r["iv_fwd"] else C_RED)
        return ("<div class='gr-line'>" + cell("Front month", pct(r["iv"], 1), f"you sell · your realized {r['vol_f']:.1f}%" if r.get("vol_f") is not None else "you sell")
                + cell("Back month later", pct(r["ivx"], 1), f"your IV at the front expiry vs forward {r['iv_fwd'] * 100:.1f}%", col) + "</div>")
    if r["mode"] == "vol" and r.get("vol_f") is not None:
        good = (r["dir"] == "long_vol") == (r["vol_f"] > r["iv"] * 100)
        return ("<div class='gr-line'>" + cell("Market's vol", pct(r["iv"], 1), "implied for this expiry")
                + cell("Your vol", f"{r['vol_f']:.1f}%", "expected realized over the hold", C_GREEN if good else C_RED) + "</div>")
    return ""


def _gr_stats_df(r: Dict[str, Any], vals: Dict[str, Any]) -> pd.DataFrame:
    sz = r["size"]
    rows = [("Expected value", f"{'+' if (r['ev_r'] or 0) >= 0 else '−'}{abs((r['ev_r'] or 0) * 100):.0f}¢ per $1 risked" if r.get("ev_r") is not None else "—",
             f"{_gr_money(r['ev'] * 100)} per contract" if r.get("ev") is not None else ""),
            ("Max loss / max gain", f"{_gr_money(r['max_loss'] * 100)} / {_gr_money(r['max_gain'] * 100) if (r['max_gain'] is not None and np.isfinite(r['max_gain'])) else 'open'}", "per contract"),
            ("Win chance at the front expiry" if r.get("two") else "Win chance at expiry", pct(r.get("p_win")), "on your view")]
    if r.get("two"):
        rows.append(("Front / back IV", f"{r['iv'] * 100:.1f}% / {r['iv2'] * 100:.1f}%", f"forward vol between them {r['iv_fwd'] * 100:.1f}%"))
    if r.get("chase"):
        cc = r["chase"]
        rows.append(("Chase cost", f"{'+' if cc['per_contract'] >= 0 else '−'}{_gr_money(abs(cc['per_contract']))}", f"{pct(abs(cc['of_risk']))} of max loss vs at the trigger"))
    if r.get("be_move"):
        rows.append(("Breakeven at expiry", f"{r['be_move']['pct']:+.1f}%", f"{r['be_move']['sd']:.2f} expected moves"))
    if r["mode"] == "vol":
        rows.append(("Breakevens at the front expiry" if r.get("two") else "Breakevens", " / ".join(f"${b:.2f}" for b in r["bes"]) or "—",
                     f"expected move ±${r['em']:.2f}"))
    rows.append(("Paid over flat-vol value", f"{'+' if r['fair_gap_r'] >= 0 else '−'}{abs(r['fair_gap_r']) * 100:.1f}%", "of max loss (skew + spread)"))
    rows.append(("Half-Kelly", pct(sz["kelly_half"], 1), "of sleeve, capped at 25%"))
    bh = sz.get("book")
    if bh and bh["items"]:
        sl = _gnum(vals.get("sleeve")) or 0
        rows.append(("Open book", f"{len(bh['items'])} trades · {_gr_money(bh['total'])}",
                     f"{pct(bh['total'] / sl) + ' of sleeve · ' if sl else ''}{'this trade cut ' + _gr_money(sz['book_cut']) if sz['book_cut'] > 0 else 'no overlap'} · {bh['eff_bets']:.1f} independent bets"))
    return pd.DataFrame(rows, columns=["", "value", "note"])


def _gr_payoff_chart(r: Dict[str, Any]):
    d = r.get("dist")
    if not d:
        return None
    S = r["S"]
    s_max = max(d["sT"], d["sRN"])
    marks = [S, *r["bes"], *[l_[1] for l_ in r["legs"]]] + ([r["target"]] if r.get("target") else [])
    lo = min(S * math.exp(-3 * s_max), *[x * 0.97 for x in marks])
    hi = max(S * math.exp(3 * s_max), *[x * 1.03 for x in marks])
    xs = np.linspace(lo, hi, 180)

    def dens(m, s):
        return np.exp(-0.5 * ((np.log(xs / S) - m) / s) ** 2) / (xs * s * math.sqrt(2 * math.pi))
    pnl = (np.asarray(_gpos(r["legs"], xs, 0.0, r["iv"], r.get("ivx")), dtype=float) - r["cost"]) * 100
    df = pd.DataFrame({"price": xs, "Market (implied)": dens(d["mRN"], d["sRN"]), "Your view": dens(d["mT"], d["sT"]), "pnl": pnl})
    dl = df.melt("price", ["Market (implied)", "Your view"], var_name="distribution", value_name="density")
    area = alt.Chart(dl).mark_area(opacity=0.32).encode(
        x=alt.X("price:Q", title=None, scale=alt.Scale(domain=[lo, hi])), y=alt.Y("density:Q", axis=None, stack=None),
        color=alt.Color("distribution:N", scale=alt.Scale(domain=["Market (implied)", "Your view"], range=[C_MUTED, C_ACCENT]),
                        legend=alt.Legend(orient="top", title=None)))
    df["side"] = np.where(df["pnl"] > 0, "profit", "loss")
    pl = alt.Chart(df).mark_line(strokeWidth=2).encode(
        x=alt.X("price:Q", scale=alt.Scale(domain=[lo, hi])), y=alt.Y("pnl:Q", title="$ per contract"),
        color=alt.Color("side:N", scale=alt.Scale(domain=["profit", "loss"], range=[C_GREEN, C_RED]), legend=None),
        detail="side:N", tooltip=[alt.Tooltip("price:Q", format=",.2f"), alt.Tooltip("pnl:Q", format="+,.0f")])
    rules = pd.DataFrame([{"x": S, "what": "spot"}] + [{"x": b, "what": "breakeven"} for b in r["bes"]]
                         + ([{"x": r["target"], "what": "target"}] if r.get("target") else []))
    rl = alt.Chart(rules).mark_rule(strokeDash=[4, 3], strokeWidth=1.5).encode(
        x="x:Q", color=alt.Color("what:N", scale=alt.Scale(domain=["spot", "breakeven", "target"], range=[C_TEXT, C_MUTED, C_BLUE]), legend=None),
        tooltip=["what", alt.Tooltip("x:Q", format=",.2f")])
    zero = alt.Chart(pd.DataFrame({"y": [0]})).mark_rule(color=C_MUTED).encode(y="y:Q")
    top = alt.layer(area, rl).resolve_scale(color="independent").properties(title="Where each side thinks it lands")
    bot = alt.layer(pl, zero).properties(title=f"P&L per contract at {'the front expiry' if r.get('two') else 'expiry'}")
    # Streamlit fits title, legend and axes inside the height, so these need room
    return [_alt(top, 250), _alt(bot, 230)]


def _gr_ladder(marks: List[Tuple[float, str, str]], band: Tuple[float, float], zone: Optional[Tuple[float, float]] = None, height: int = 170):
    """Price ladder: a tick per level, labels staggered in rows so they don't overlap, the market's (or your) move band,
    and the buy zone. marks = (price, label, color)."""
    marks = [(float(p_), l_, c_) for p_, l_, c_ in marks if p_ is not None and np.isfinite(p_)]
    xs = [m_[0] for m_ in marks] + list(band) + (list(zone) if zone else [])
    lo, hi = min(xs), max(xs)
    pad = (hi - lo) * 0.06 or lo * 0.02
    lo, hi = lo - pad, hi + pad
    per_px = (hi - lo) / 900.0
    ends = [-1e18] * 4
    rows = []
    for p_, l_, c_ in sorted(marks):
        txt = f"{l_} {p_:,.2f}"
        half = len(txt) * 3.6 * per_px
        row = next((j for j, e in enumerate(ends) if e < p_ - half), 3)
        ends[row] = p_ + half
        rows.append({"price": p_, "txt": txt, "color": c_, "y": 0.0, "y2": 1.2, "ty": 1.7 + row * 0.85})
    dm = pd.DataFrame(rows)
    ys = alt.Scale(domain=[0, 5.0])
    layers = [alt.Chart(pd.DataFrame({"x0": [band[0]], "x1": [band[1]], "y": [0.0], "y2": [1.2]})).mark_rect(opacity=0.2, color=C_MUTED).encode(
        x=alt.X("x0:Q", scale=alt.Scale(domain=[lo, hi], zero=False), title=None), x2="x1:Q", y=alt.Y("y:Q", scale=ys, axis=None), y2="y2:Q")]
    if zone:
        layers.append(alt.Chart(pd.DataFrame({"x0": [min(zone)], "x1": [max(zone)], "y": [0.0], "y2": [1.2]})).mark_rect(opacity=0.4, color=C_ACCENT).encode(
            x="x0:Q", x2="x1:Q", y=alt.Y("y:Q", scale=ys, axis=None), y2="y2:Q"))
    cs = alt.Scale(domain=list(dm["txt"]), range=list(dm["color"]))
    layers.append(alt.Chart(dm).mark_rule(strokeWidth=2).encode(x="price:Q", y=alt.Y("y:Q", scale=ys, axis=None), y2="y2:Q",
                                                                 color=alt.Color("txt:N", scale=cs, legend=None), tooltip=["txt"]))
    layers.append(alt.Chart(dm).mark_text(fontSize=10, baseline="middle").encode(x="price:Q", y=alt.Y("ty:Q", scale=ys, axis=None), text="txt:N",
                                                                                  color=alt.Color("txt:N", scale=cs, legend=None)))
    return _alt(alt.layer(*layers), height)


def _gr_li(k: str, main: str, sub: str = "") -> str:
    return f"<li><b style='color:var(--muted);font-family:var(--display);font-size:.55rem;letter-spacing:.12em'>{_esc(k.upper())}</b> &nbsp;{main}" + (f"<small>{sub}</small>" if sub else "") + "</li>"


# ---------- tabs ----------
def _gr_tab_regime(cfg, uni, bars, bench_bars, hvs, clim, vals, r) -> None:
    rg = gr_regime_state(vals)
    d = Path(vals.get("wrdir") or GR_WARROOM_DIR)
    m, _ = gr_warroom(d)
    c_main, c_side = st.columns([2.2, 1])
    with c_side:
        sec("Regime inputs")
        a, b = st.columns(2)
        gw_sel(a, "Posture", "posture", ["", "BUY_RIP", "BUY_DIP", "NEUTRAL", "AVOID"], fmt=lambda x: x or "Not set")
        gw_sel(b, "Entry mode", "mode", ["", "CONTINUATION", "TIGHT_MA", "ANTICIPATION_ONLY", "CASH"], fmt=lambda x: x or "Not set")
        gw_num(a, "VIX", "vix", 0.1, "%.2f")
        gw_num(b, "VIX 5-year percentile", "vixPct", 1.0, "%.0f", minv=0, maxv=100)
        gw_num(a, "VIX / VIX3M", "vixRatio", 0.01, "%.3f", help="1.0 or more = backwardation")
        gw_num(b, "SPY HV20 %", "spyHv", 0.1, "%.1f", help="For the variance premium")
        gw_sel(a, "Carry (USDJPY)", "carry", ["", "STABLE", "EXPANSION", "UNWIND"], fmt=lambda x: x or "Not set")
        gw_sel(b, "Curve regime", "curve", ["", "NEUTRAL", "FLATTENING", "BULL_STEEPENER", "BEAR_STEEPENER", "INVERTED"], fmt=lambda x: x or "Not set")
        st.button("Reset to War Room / lab data", key="gr_rg_reset", on_click=_gr_cb_regime_reset, args=(cfg, clim, bench_bars, hvs),
                  help="Reads the War Room files in the folder below; without them, the lab's climate and a SPY chain read.")
        gw_txt(st, "War Room data folder", "wrdir", placeholder=str(GR_WARROOM_DIR),
               help="Your pivot-scanner data/ folder (narrative_regime.parquet, tactical_macro_state.parquet, vol_compression.json, "
                    "index_read.json, daily_watchlist.json, latest_triggers.json). Set WARROOM_DATA to change the default.")
        src = st.session_state.get("gr_regime_src") or []
        note(("Sources: " + "; ".join(src) + ".") if src else "No War Room files found: set the inputs by hand, or point the folder at your pivot-scanner data.")
        if m:
            ctx_rows = []
            if m.get("current_state_name"):
                ctx_rows.append(("Narrative state", f"{m['current_state_name']} ({m.get('current_class') or ''})"))
            if m.get("tactical_label"):
                ctx_rows.append(("Tactical read", m["tactical_label"]))
            if m.get("spy"):
                sp = m["spy"]
                ctx_rows.append(("SPY", f"{'above' if sp.get('above_50') else 'below'} 50-day, {'above' if sp.get('above_200') else 'below'} 200-day"
                                 + (f", {sp['pct_from_52w_high']:.1f}% from the 52w high" if sp.get("pct_from_52w_high") is not None else "")))
            if m.get("credit_impulse"):
                ctx_rows.append(("Credit impulse", str(m["credit_impulse"])))
            if m.get("real_rate_10y") is not None:
                ctx_rows.append(("Real rate 10y", f"{m['real_rate_10y']:.2f}% {m.get('real_rate_label') or ''}"))
            if m.get("fed_stance"):
                ctx_rows.append(("Fed", str(m["fed_stance"])))
            if m.get("entry_mode_reason"):
                ctx_rows.append(("Entry mode", str(m["entry_mode_reason"])))
            show_df(pd.DataFrame(ctx_rows, columns=["War Room", "now"]), height=min(320, 38 + 35 * len(ctx_rows)))
            for w in m.get("warnings") or []:
                warnbox(w)
    with c_main:
        if not rg:
            warnbox("Set the posture (right) to see the playbook. With the War Room files in the folder it fills itself.")
            return
        keys = ["today"] + [f"{dd}|{vv}" for dd in GR_DIRS for vv in GR_VOLS]
        pv = st.session_state.get("gr_preview", "today")
        pv = pv if pv in keys else "today"
        key_ = (rg["dir"], rg["vol"]) if pv == "today" else tuple(pv.split("|"))
        is_now = key_ == (rg["dir"], rg["vol"])
        cell = GR_PLAYBOOK[key_[0]][key_[1]]
        view = rg if is_now else {**rg, "dir": key_[0], "vol": key_[1], "cell": cell,
                                  "label": f"{GR_DIRS[key_[0]]['label']} · {GR_VOLS[key_[1]]['label']}",
                                  "size": cell["size"] * (0.6 if rg["carry_unwind"] else 1.0)}
        md(hero_html(rg["label"].upper(), GR_VOL_COLOR[rg["vol"]],
                     f"Posture {rg['posture']} · entry mode {rg['mode'] or '—'} · size ×{rg['size']:.2g} of what the grade allows",
                     GR_PLAYBOOK[rg["dir"]][rg["vol"]]["head"]))
        vix_lbl = "VIX" if m.get("vix") is not None else "VIX (or SPY IV30)"
        kpi_row([kpi_html(vix_lbl, f"{_gnum(vals.get('vix')):.1f}" if _gnum(vals.get("vix")) is not None else "—", "level"),
                 kpi_html("5-year percentile", f"{_gnum(vals.get('vixPct')):.0f}" if _gnum(vals.get("vixPct")) is not None else "—",
                          "cheap ≤ 35, rich ≥ 65"),
                 kpi_html("VIX / VIX3M", f"{_gnum(vals.get('vixRatio')):.2f}" if _gnum(vals.get("vixRatio")) is not None else "—",
                          "1.0+ = backwardation", "bad" if (_gnum(vals.get("vixRatio")) or 0) >= 1 else ""),
                 kpi_html("Variance premium", f"{rg['vrp']:+.2f}" if rg.get("vrp") is not None else "—", "ln(VIX / SPY HV20)",
                          "info" if (rg.get("vrp") or 0) < 0 else ""),
                 kpi_html("Size", f"×{rg['size']:.2g}", "carry unwind cuts 40%" if rg["carry_unwind"] else "of the graded size")])
        lbl = {"today": f"Today: {rg['label']}"}
        lbl.update({f"{dd}|{vv}": f"{GR_DIRS[dd]['label']} · {GR_VOLS[vv]['label']}" for dd in GR_DIRS for vv in GR_VOLS})
        if st.session_state.get("gr_preview") not in keys:
            st.session_state["gr_preview"] = "today"
        st.selectbox("Playbook for", keys, key="gr_preview", format_func=lambda k: lbl[k],
                     help="Preview any cell: what you would trade if the regime moved there.")
        if not is_now:
            warnbox(f"Previewing {view['label']}. Today is {rg['label']}.")
        sec(f"{'Today' if is_now else 'Preview'}: {cell['head']}")
        cA, cB = st.columns([1.2, 1])
        prim_html = []
        for sid, why in cell["primary"]:
            role = gr_role_of(view, sid)["role"] if sid in GR_STRUCTS else "primary"
            blocked = rg.get("mode") == "CASH" and sid in GR_STRUCTS and GR_STRUCTS[sid]["dir"] == "bull"
            tag = (" <span class='gr-role avoid'>CASH: no longs</span>" if blocked else
                   (" <span class='gr-role ok'>downgraded</span>" if role != "primary" else ""))
            prim_html.append((sid, f"<div class='gr-pick' style='--pc:{C_GREEN}'><div class='n'>{_esc(GR_SNAME[sid])}{tag}</div><div class='w'>{_esc(why)}</div></div>", blocked))
        extra_html = [f"<div class='gr-pick' style='--pc:{C_BLUE}'><div class='n'>{_esc(GR_SNAME[sid])} <span class='gr-role'>if you hold longs</span></div>"
                      f"<div class='w'>{_esc(why)}</div></div>" for sid, why in cell.get("extra", [])]
        ok_html = "".join(f"<li>{_esc(GR_SNAME[s_])}<small>{_esc(w_)}</small></li>" for s_, w_ in cell["ok"]) or "<li>Nothing else.</li>"
        gen = [("long_call", "Posture AVOID: no new longs (every bull structure).")] if view["dir"] == "risk_off" else \
              ([("debit_put", "Shorts fight the tape (every bear structure not listed above).")] if view["dir"] in ("risk_on", "recovery") else [])
        listed = {x[0] for x in cell["primary"] + cell["ok"] + cell["avoid"]}
        av_html = "".join(f"<li>{_esc(GR_SNAME[s_])}<small>{_esc(w_)}</small></li>" for s_, w_ in cell["avoid"] + [g for g in gen if g[0] not in listed])
        tk = _clean_ticker(vals.get("ticker"))
        with cA:
            md("<div class='sec' style='margin-top:.2rem'>First choice</div>")
            for sid, h, blocked in prim_html:
                md(h)
                if sid in GR_STRUCTS and not blocked:
                    st.button(f"Grade {GR_SNAME[sid].lower()}{' on ' + tk if tk and tk != 'DEMO' else ''}", key=f"gr_use_p_{sid}",
                              on_click=_gr_cb_use, args=(sid, None, cfg, uni, bars, bench_bars))
            for h in extra_html:
                md(h)
        with cB:
            md(f"<div class='sec' style='margin-top:.2rem'>Allowed</div><ul class='gr-steps'>{ok_html}</ul>"
               f"<div class='sec'>Avoid</div><ul class='gr-steps'>{av_html}</ul>")
        why = rg["why"] + rg["notes"] if is_now else [f"{GR_DIRS[key_[0]]['label']}: posture {GR_DIRS[key_[0]]['posture']}",
                                                       f"{GR_VOLS[key_[1]]['label']}: {GR_VOLS[key_[1]]['def']}"] + ([cell["note"]] if cell.get("note") else [])
        if is_now and rg.get("mode") == "CASH":
            why = why + ["Entry mode CASH blocks new longs in the grade. Bear and vol structures are graded against this cell, at its size."]
        md("<div class='sec'>Why this cell</div><ul class='gr-steps'>" + "".join(f"<li>{_esc(x)}</li>" for x in why) + "</ul>")

        # this ticker
        sec(f"For {tk}" if tk else "This ticker")
        T = (st.session_state.get("gr_tk") or {}).get(tk) if tk else None
        src_ = T or ({"iv": vals.get("iv"), "iv2": vals.get("iv2") if GR_STRUCTS[vals["structure"]].get("two") else None, "hv": vals.get("hv"),
                      "ivr": vals.get("ivr"), "callSkew": vals.get("callSkew"), "putSkew": vals.get("putSkew")} if _gnum(vals.get("iv")) else None)
        if not tk or not src_:
            note("Type a ticker on the Grade tab and load its chain: the name's own IV, term structure and skew pick from this cell's menu.")
        else:
            nv = gr_name_vol(src_)
            w = (T or {}).get("warroom") or {}
            e_days = (pd.Timestamp(T["earnings"]) - pd.Timestamp(date.today())).days if (T and T.get("earnings")) else None
            adv = gr_name_advice(view, nv, {"dir_hint": (w.get("trigger") or {}).get("direction"),
                                            "bbuw": w.get("daily_bbuw") if w.get("daily_bbuw") is not None else _gnum(vals.get("bbuw")),
                                            "earnings_days": e_days})
            good = [x for x in adv if x["score"] > 0 and x["role"] != "avoid"][:3]
            bits = [f"IV30 {nv['iv30'] * 100:.1f}%" if nv.get("iv30") else "", f"HV20 {nv['hv']:.1f}%" if nv.get("hv") else "",
                    f"IV rank {_jr(nv['ivr'])}" if nv.get("ivr") is not None else "", f"front {nv['slope'] * 100:+.0f}% vs back" if nv.get("slope") is not None else "",
                    f"put skew {nv['p25']:.0f}%" if nv.get("p25") is not None else ""]
            note(" · ".join(b_ for b_ in bits if b_) + (f". Name vol reads {nv['level']}" if nv.get("level") else "")
                 + (f", term structure {nv['term']}." if nv.get("term") else ".") + ("" if T else " (from the Grade tab inputs; load the chain for term structure)"))
            if not good:
                note("Nothing in this cell suits this name. Passing is a position.")
            for x in good:
                md(f"<div class='gr-pick' style='--pc:{C_GREEN if x['role'] == 'primary' else C_ACCENT}'><div class='n'>{_esc(x['label'])}"
                   f" <span class='gr-role {x['role']}'>{GR_ROLE_TXT[x['role']]}</span></div><div class='w'>{_esc(' · '.join(x['why']))}</div></div>")
                st.button(f"Grade {x['label'].lower()} on {tk}", key=f"gr_use_n_{x['sid']}", on_click=_gr_cb_use, args=(x["sid"], tk, cfg, uni, bars, bench_bars))

        # grid
        sec("Every regime")
        hdr = "<tr><th></th>" + "".join(f"<th>{_esc(GR_VOLS[v_]['label'])}</th>" for v_ in GR_VOLS) + "</tr>"
        body = ""
        for dd in GR_DIRS:
            body += f"<tr><th>{_esc(GR_DIRS[dd]['label'])}<br/><span style='font-family:var(--mono)'>{GR_DIRS[dd]['posture']}</span></th>"
            for vv in GR_VOLS:
                now_ = (dd, vv) == (rg["dir"], rg["vol"])
                sel_ = (dd, vv) == key_ and not now_
                names = "<br/>".join(_esc(GR_GRID_NAME[x[0]]) for x in GR_PLAYBOOK[dd][vv]["primary"])
                body += f"<td class='{'now' if now_ else ''}{' sel' if sel_ else ''}'>{'<i>TODAY</i>' if now_ else ''}{names}</td>"
            body += "</tr>"
        md(f"<table class='gr-grid'>{hdr}{body}</table>")
        note("Rows are your posture. Columns: cheap = VIX in the bottom 35% of five years, rich = top 35%, stressed = VIX at or above "
             "VIX3M at any level. Pick a cell in 'Playbook for' above to read it.")

        # scan from the vol desk
        sec("Scan: best structure per name")
        vd = (st.session_state.get("vd_res") or {}).get("rows") or []
        loaded = st.session_state.get("gr_tk") or {}
        rows = []
        for rr in vd:
            curve = rr.get("curve")
            exps = [{"dte": int(a_), "atm": float(b_)} for a_, b_ in zip(curve["dte"], curve["atm_iv"])] if isinstance(curve, pd.DataFrame) and len(curve) else []
            rk = iv_rank(rr["sym"], rr.get("iv1m", np.nan))[0]
            src_r = {"expiries": exps, "iv30": rr.get("iv1m"), "hv20": (rr.get("rv21") or 0) * 100 or None,
                     "ivr": rk * 100 if rk is not None else None}
            nv = gr_name_vol(src_r)
            if nv and rr.get("put_skew") is not None:
                nv["p25"] = rr["put_skew"] * 100
            if nv and rr.get("call_skew") is not None:
                nv["c25"] = rr["call_skew"] * 100
            rows.append((rr["sym"], nv))
        for t_, T_ in loaded.items():
            if t_ not in {x[0] for x in rows}:
                rows.append((t_, gr_name_vol(T_)))
        out = []
        for t_, nv in rows:
            adv = [x for x in gr_name_advice(view, nv, {}) if x["score"] > 0 and x["role"] != "avoid"]
            out.append({"ticker": t_, "IV/HV": math.exp(nv["vr"]) if (nv and nv.get("vr") is not None) else np.nan,
                        "IV rank": nv.get("ivr") if nv else np.nan, "front vs back": nv.get("slope") if nv else np.nan,
                        "best fit": (adv[0]["label"] + f" ({GR_ROLE_TXT[adv[0]['role']]})") if adv else "pass",
                        "next": adv[1]["label"] if len(adv) > 1 else "", "score": adv[0]["score"] if adv else -99.0})
        if out:
            df = pd.DataFrame(out).sort_values("score", ascending=False)
            P_ = st.column_config.NumberColumn
            show_df(df.drop(columns="score"), height=min(420, 40 + 35 * len(df)), column_config={
                "IV/HV": P_(format="%.2f"), "IV rank": P_(format="%.0f"), "front vs back": P_(format="percent")})
            note("Names from your last Options > Vol desk scan plus any chain loaded here. The cell sets the menu; each name's "
                 "own IV against realized, IV rank, term slope and skew pick from it.")
        else:
            note("Run Options > Vol desk to scan names; they are ranked here by fit to today's cell.")


def _gr_tab_grade(cfg, uni, bars, bench_bars, vals, r, ctx, log) -> None:
    ex_cols = st.columns([1.5, 0.9, 1.6, 1.5, 0.9, 1.6])
    for j, name in enumerate(GR_EXAMPLES):
        ex_cols[j].button(name, key=f"gr_ex_{j}", on_click=_gr_cb_example, args=(name,))
    ex_cols[4].button("Clear", key="gr_clear", on_click=_gr_cb_clear)
    if st.session_state.get("gr_example"):
        ex_cols[5].caption(f"EXAMPLE INPUTS: {st.session_state['gr_example']}")
    msg = st.session_state.pop("gr_msg", None)
    if msg:
        st.info(msg)
    # chain loader
    c = st.columns([1, 2, 1])
    gw_txt(c[0], "Ticker", "ticker", placeholder="NVDA")
    tk = _clean_ticker(vals.get("ticker"))
    T = (st.session_state.get("gr_tk") or {}).get(tk) if tk else None
    if T:
        opts = [e["exp"] for e in T["expiries"]]
        lab = {e["exp"]: f"{e['exp']} · {e['dte']}d · IV {e['atm'] * 100:.1f}%" if e.get("atm") else f"{e['exp']} · {e['dte']}d" for e in T["expiries"]}
        if st.session_state.get("gr_exp_pick") not in opts:
            want = _gnum(vals.get("dte")) or 35
            st.session_state["gr_exp_pick"] = min(T["expiries"], key=lambda e: abs(e["dte"] - want))["exp"] if opts else None
        c[1].selectbox("Expiry from the chain", opts, key="gr_exp_pick", format_func=lambda x: lab.get(x, x))
    else:
        c[1].caption("Load the chain to pick an expiry. In Demo the chain is synthetic.")
    c[2].button("Load chain & fill" if not T else "Fill from chain", key="gr_fill", on_click=_gr_cb_fill, args=(cfg, uni, bars, bench_bars),
                help="Pulls the option chain (Massive or Demo), then fills price, IV, skew, HV20, ADR, strikes and quotes, plus "
                     "conviction and the trigger when the War Room files are present.")
    if T:
        w = T.get("warroom") or {}
        theme = T.get("theme") or w.get("theme")
        st.caption(f"{tk}: spot {T['spot']:.2f} · HV20 {T['hv20']:.1f}% · ADR {T['adr']:.2f}% · {T['n_contracts']} contracts "
                   f"({'quotes' if T['quotes'] else 'no quotes: IV-implied mids'}) · loaded {T['asof'][11:16]}"
                   + (f" · theme {theme}" if theme else "") + (f" · earnings {T['earnings']}" if T.get("earnings") else ""))
    # regime line
    rg = gr_regime_state(vals)
    if rg:
        fit = gr_role_of(rg, vals["structure"])
        md(f"<div class='gr-regline'>Regime <b>{_esc(rg['label'])}</b>{' · ' + _esc(rg['mode']) if rg.get('mode') else ''} → "
           f"{_esc(GR_STRUCTS[vals['structure']]['label'])}: <span class='gr-role {fit['role']}'>{GR_ROLE_TXT[fit['role']]}</span></div>")
    else:
        md("<div class='gr-regline'>Regime not set: no macro check on this trade. Set it on the Regime tab.</div>")

    left, right = st.columns([1.25, 1])
    with left:
        sec("The trade")
        a, b, c3 = st.columns([2, 1, 1])
        s = gw_sel(a, "Structure", "structure", list(GR_STRUCTS), fmt=lambda k: GR_STRUCTS[k]["label"])
        meta = GR_STRUCTS[s]
        gw_num(b, "Stock price", "spot", 0.01)
        gw_num(c3, "Debit you pay" if meta["kind"] == "debit" else "Credit you collect", "price", 0.01,
               help=st.session_state.get("gr_hint") or "Your limit, per share")
        a, b, c3, d4 = st.columns(4)
        if len(meta["strikes"]) == 2:
            gw_num(a, "Long call strike (back month)" if s == "diagonal" else "Lower strike", "lo", 0.5)
            gw_num(b, "Short call strike (front month)" if s == "diagonal" else "Upper strike", "hi", 0.5)
        elif len(meta["strikes"]) == 4:
            gw_num(a, "Long put", "pl", 0.5)
            gw_num(b, "Short put", "ps", 0.5)
            gw_num(c3, "Short call", "cs", 0.5)
            gw_num(d4, "Long call", "cl", 0.5)
        else:
            gw_num(a, "Strike", "k", 0.5)
        a, b, c3, d4 = st.columns(4)
        gw_num(a, "Package bid", "bid", 0.01)
        gw_num(b, "Package ask", "ask", 0.01)
        gw_num(c3, "Front-month DTE" if meta.get("two") else "Days to expiry", "dte", 1.0, "%.0f")
        if meta.get("two"):
            gw_num(d4, "Back-month DTE", "dte2", 1.0, "%.0f")
        gw_num(st.columns(4)[0], "Planned hold (trading days)", "hold", 1.0, "%.0f")

        sec("Edge")
        gw_sel(st, "Setup: name the edge in one sentence", "setup", _gr_setups_for(s), fmt=lambda k: GR_SETUPS[k]["label"])
        a, b, c3 = st.columns(3)
        if meta["mode"] == "dir":
            gw_num(a, "Conviction score", "conv", 1.0, "%.0f", help="0–10+ from the screener")
            gw_num(b, "Theme rank", "themeRank", 1.0, "%.0f")
        if vals.get("setup") == "compress":
            gw_num(c3, "Daily BBUW", "bbuw", 1.0, "%.0f")
        if vals.get("setup") == "event":
            gw_num(c3, "Avg past earnings move %", "histMove", 0.1, "%.1f")

        if meta["mode"] == "dir":
            sec("Entry")
            a, b, c3 = st.columns([1, 1, 2])
            gw_num(a, "Trigger / pivot price" if meta["dir"] == "bull" else "Breakdown level", "pivot", 0.01)
            gw_num(b, "ADR %", "adr", 0.1, "%.2f")
            gw_sel(c3, "Day of the move", "burstDay", [0, 1, 2, 3], fmt=lambda x: {0: "Pre", 1: "1", 2: "2", 3: "3+"}[x], radio=True, horizontal=True)
            if r.get("ext"):
                note(f"Price is {r['ext']['pct']:+.1f}% from the {'trigger' if meta['dir'] == 'bull' else 'breakdown'} = {r['ext']['adr']:.2f} ADR"
                     + (f" · this position costs {_gr_money(r['chase']['per_contract'])} more per contract than at the trigger" if r.get("chase") and r["chase"]["per_contract"] >= 0
                        else (f" · {_gr_money(-r['chase']['per_contract'])} less than at the trigger (early)" if r.get("chase") else "")))

        sec("Volatility")
        a, b, c3, d4 = st.columns(4)
        gw_num(a, "Front-month IV %" if meta.get("two") else "IV for this expiry %", "iv", 0.1, "%.1f")
        if meta.get("two"):
            gw_num(b, "Back-month IV %", "iv2", 0.1, "%.1f")
        gw_num(c3, "HV20 %", "hv", 0.1, "%.1f")
        gw_num(d4, "IV rank", "ivr", 1.0, "%.0f", minv=0, maxv=100)
        if meta.get("two"):
            gw_num(a, "Back-month IV when the front expires %", "ivx", 0.1, "%.1f",
                   help="Blank = the forward vol, the market's own answer (no term-structure view).")
            if r.get("iv_fwd") is not None:
                D1, D2 = _gnum(vals.get("dte")), _gnum(vals.get("dte2"))
                roll = gr_iv_at(T["expiries"], max(D2 - D1, 1)) if T else None
                if roll is None:
                    Dg = D2 - D1
                    roll = r["iv"] if Dg <= D1 else math.sqrt(max(r["iv"] ** 2 * D1 + (r["iv2"] ** 2 * D2 - r["iv"] ** 2 * D1) * (Dg - D1) / (D2 - D1), 1e-6) / Dg)
                bc = st.columns(3)
                bc[0].button(f"Forward {r['iv_fwd'] * 100:.1f}%", key="gr_ivx_f", on_click=_gr_cb_ivx, args=(None,),
                             help="The market's implied vol between the two expiries: no term-structure view")
                bc[1].button(f"Flat back {r['iv2'] * 100:.1f}%", key="gr_ivx_u", on_click=_gr_cb_ivx, args=(r["iv2"] * 100,),
                             help="The back month keeps today's IV")
                bc[2].button(f"Roll-down {roll * 100:.1f}%", key="gr_ivx_r", on_click=_gr_cb_ivx, args=(roll * 100,),
                             help="The curve keeps its shape: the back month rolls to today's IV at its remaining tenor")
        a, b = st.columns(2)
        gw_chk(a, "Earnings before expiry", "earnings")
        gw_chk(b, "This is a deliberate event trade", "deliberate", disabled=not vals.get("earnings"))
        iv_, hv_ = _gnum(vals.get("iv")), _gnum(vals.get("hv"))
        if iv_ and hv_:
            note(f"IV/HV = {iv_ / hv_:.2f} (log {math.log(iv_ / hv_):.2f}). Above 1.0 you pay more than the stock has been moving.")

        sec("Your view")
        if meta["mode"] == "dir":
            a, b = st.columns(2)
            gw_num(a, "Target price", "target", 0.01, help="Where the stock closes on your exit day")
            gw_num(b, f"Your probability it closes at or {'above' if meta['dir'] == 'bull' else 'below'} target, %", "p", 1.0, "%.0f", minv=1, maxv=99)
            if r.get("p_mkt") is not None:
                note(f"Market: {pct(r['p_mkt'])} in {r['hold_cal']} calendar days" + (f" · your number after calibration: {pct(r['p_user'])}" if r.get("cal_applied") is not None else ""))
            pl0 = gr_plan(vals, r, ctx, False) if not r.get("errs") else None
            if pl0 and not pl0.get("err") and pl0.get("levels"):
                lv = [L for L in pl0["levels"] if L["k"] != "you"]
                cols = st.columns(len(lv))
                for j, L in enumerate(lv):
                    cols[j].button(f"{'1σ' if L['k'] == 'imp' else L['label']} {L['price']:.2f}", key=f"gr_tgt_{L['k']}", on_click=_gr_cb_target, args=(L["price"],),
                                   help=f"{L['note']}: the market gives {pct(L['p_close'])} to close past it on exit day")
        else:
            gw_num(st.columns(3)[0], "Vol forecast % (realized over the hold)", "volf", 0.1, "%.1f", help="Defaults to HV20")

        with st.expander("Book and sizing"):
            a, b, c3 = st.columns(3)
            gw_num(a, "Options sleeve $", "sleeve", 100.0, "%.0f")
            gw_num(b, "Premium per trade, % of sleeve", "baseRisk", 0.5, "%.1f", help="An A-grade trade risks this much")
            gw_num(c3, "Max open option risk, % of sleeve", "heatCap", 5.0, "%.0f")
            gw_num(a, "Same-theme correlation", "rhoSame", 0.05, "%.2f", minv=0, maxv=1)
            gw_num(b, "Cross-theme correlation", "rhoCross", 0.05, "%.2f", minv=0, maxv=1)
            gw_chk(a, "Starter size until 20 graded trades are resolved", "capCal")
            gw_chk(b, "Shrink my probability by my track record (after 20)", "useCal")

    with right:
        if r.get("errs"):
            md(f"<div class='gr-verdict' style='--vc:{C_MUTED}'><div class='gr-letter'>–</div><div><div class='gr-vt'>Incomplete</div>"
               f"<div class='gr-vs'>{'<br/>'.join(_esc(e) for e in r['errs'])}</div></div></div>")
            return
        md(_gr_verdict_html(r))
        if r["gates"]:
            md("<div class='sec' style='margin-top:.2rem'>Hard stops</div>" + "".join(f"<div class='gr-gate'><b>{_esc(g['t'])}</b>{_esc(g['d'])}</div>" for g in r["gates"]))
        md("<div class='sec' style='margin-top:.4rem'>Four pillars</div>" + _gr_pillars_html(r))
        lh = _gr_line_html(r)
        if lh:
            md("<div class='sec'>The line</div>" + lh)
        sec("Numbers")
        show_df(_gr_stats_df(r, vals), height=38 + 35 * len(_gr_stats_df(r, vals)))
        ch = _gr_payoff_chart(r)
        if ch is not None:
            for c_ in ch:
                show_chart(c_)
            note("Dashed lines: spot (light), breakevens (grey), your target (blue). Hover for prices.")
        else:
            note("Add your view to see the distributions.")
        if r["flags"]:
            md("<div class='sec'>Flags</div>" + "".join(f"<div class='gr-flag {f_['s']}'>{_esc(f_['t'])}</div>" for f_ in r["flags"]))
        sec("Log it")
        gw_txt(st, "The edge in one sentence (saved with the grade)", "why")
        if st.button("Save grade to log", key="gr_save", disabled=bool(st.session_state.get("gr_example"))):
            pl = gr_plan(vals, r, ctx, True)
            plan_s = None
            if pl and not pl.get("err"):
                plan_s = json.dumps({"style": pl.get("style"), "entry": pl.get("E"), "stop": pl.get("stop"), "T1": pl.get("T1"), "T2": pl.get("T2"),
                                     "time_stop": pl.get("time_stop"), "limit": pl.get("limit"), "tp": pl.get("tp")}, default=str)
            row = {"id": f"{datetime.now():%Y%m%d%H%M%S}-{zlib.crc32(json.dumps(vals, default=str).encode()) % 10000:04d}",
                   "created": datetime.now().isoformat(timespec="seconds"), "ticker": _clean_ticker(vals.get("ticker")) or "",
                   "structure": vals["structure"], "setup": vals.get("setup"), "letter": r["letter"], "score": round(r["score"], 1),
                   "verdict": r["verdict"], "gates": "; ".join(g["t"] for g in r["gates"]),
                   "edge": round(r["pillars"]["edge"]["pts"], 1), "entry": round(r["pillars"]["entry"]["pts"], 1),
                   "price_pts": round(r["pillars"]["price"]["pts"], 1), "odds": round(r["pillars"]["odds"]["pts"], 1),
                   "p_user_raw": r.get("p_user_raw"), "p_user": r.get("p_user"), "p_mkt": r.get("p_mkt"), "ev_r": r.get("ev_r"),
                   "ext_adr": (r.get("ext") or {}).get("adr"), "chase_r": (r.get("chase") or {}).get("of_risk"),
                   "contracts": r["size"]["contracts"], "risk": r["size"]["risk_dollars"], "max_loss": r["max_loss"], "price": r["price"],
                   "kind": r["meta"]["kind"], "mode": r["mode"], "regime": (r.get("regime") or {}).get("label"), "fit": (r.get("regime") or {}).get("role"),
                   "why": vals.get("why") or "", "status": "passed" if r["letter"] in ("D", "F") else "open",
                   "plan": plan_s, "inputs": json.dumps({k: v for k, v in vals.items() if not k.startswith("h_")}, default=str)}
            log2 = pd.concat([log, pd.DataFrame([row])], ignore_index=True)
            try:
                gr_save_log(log2)
                st.success(f"Saved {row['ticker'] or 'trade'} as {r['letter']} ({row['status']}) to {GR_LOG.name}. Add the outcome on the Log tab.")
            except Exception as e:
                st.error(f"Could not save: {type(e).__name__}: {e}")
        if st.session_state.get("gr_example"):
            st.caption("These are example inputs. Change them to a real trade before saving.")


def _gr_tab_strikes(cfg, vals, r, ctx) -> None:
    if r.get("errs"):
        note("Finish the trade on the Grade tab first.")
        return
    if r["mode"] != "dir":
        note("The strike picker covers directional spreads. Vol trades are priced on the Grade tab.")
        return
    if r.get("two"):
        note("The strike picker covers single-expiry spreads. A diagonal is priced on the Grade tab from both months.")
        return
    if not r.get("dist"):
        note("Add a target and your probability on the Grade tab; the picker ranks strikes against that view.")
        return
    tk = _clean_ticker(vals.get("ticker"))
    T = (st.session_state.get("gr_tk") or {}).get(tk) if tk else None
    E = next((e for e in T["expiries"] if e["dte"] == _gnum(vals.get("dte"))), None) if T else None
    c = st.columns(4)
    gw_num(c[0], "Strike step $", "skStep", 0.5, "%.2f", help=f"Auto {gr_auto_step(r['S'])}")
    gw_num(c[1], "25Δ call skew %", "callSkew", 1.0, "%.1f", help="vs ATM IV; −5 = calls cheaper")
    gw_num(c[2], "25Δ put skew %", "putSkew", 1.0, "%.1f", help="Moontower shows both")
    sleeve = _gnum(vals.get("sleeve")) or 0
    fB = max(r["size"]["risk_dollars"] or 0, sleeve * ((_gnum(vals.get("baseRisk")) or 5) / 100) * 0.4) / sleeve if sleeve > 0 else 0.03
    opt = {"step": vals.get("skStep"), "call_skew": vals.get("callSkew"), "put_skew": vals.get("putSkew"), "f_budget": fB,
           "chain": E["strikes"] if E else None, "expiries": T["expiries"] if T else None}
    m_ = gr_strike_matrix(vals, r, opt)
    c[3].caption(("Prices: " + (f"{E['exp']} chain" + (" (quote mids)" if T["quotes"] else " (IV-implied mids)") if m_["src"] == "chain" else "model (IV plus skew)"))
                 + f" · sized at {pct(fB, 1)} of the sleeve")
    kind = "call" if m_["bull"] else "put"
    nm = (lambda c_: f"{c_['L']:g} / {c_['H']:g}") if m_["bull"] else (lambda c_: f"{c_['H']:g} / {c_['L']:g}")
    sec(f"Three picks for {_gr_d2(r['target'])} · you {pct(r['p_user'])} vs market {pct(r['p_mkt'])} by day {_gnum(vals.get('hold')) or 5:g}")
    seen: Dict[Tuple[float, float], Dict[str, Any]] = {}
    for p_ in m_["picks"]:
        key = (p_["c"]["L"], p_["c"]["H"])
        if key in seen:
            seen[key]["why"] += " · " + p_["why"]
        else:
            seen[key] = {**p_}
    if not seen:
        note("No spread clears zero EV with at least a 15% win chance" + (f" and {m_['min_oi']:.0f}+ open interest" if m_["src"] == "chain" else "")
             + " on your view. That is an answer too: pass, or rethink the target.")
    else:
        cols = st.columns(len(seen))
        for j, p_ in enumerate(seen.values()):
            c_ = p_["c"]
            q = gr_quote(T, E, "debit_call" if m_["bull"] else "debit_put", {"lo": c_["L"], "hi": c_["H"]}) if (m_["src"] == "chain" and E) else None
            h = (f"<div class='gr-pick' style='--pc:{C_ACCENT}'><div class='w' style='color:var(--accent);font-family:var(--display);font-size:.55rem;letter-spacing:.12em;text-transform:uppercase'>{_esc(p_['why'])}</div>"
                 f"<div class='n' style='font-size:1rem'>{nm(c_)} {kind}s</div><div class='w'>{'Mid' if m_['src'] == 'chain' else 'Model cost'} ${c_['cost']:.2f}"
                 + (f" · natural ${c_['natural']:.2f}" if c_.get("natural") is not None else "") + (f" · OI {c_['oi_min']:,.0f}+" if c_.get("oi_min") is not None else "")
                 + f"<br/>Market line {pct(c_['p_mid'])} · your line {pct(c_['p_you_mid'])}<br/>Pays {c_['odds']:.2f} to 1 · EV {c_['ev_r'] * 100:+.0f}¢ per $1 · wins {pct(c_['p_win'])}</div></div>")
            cols[j].markdown(h, unsafe_allow_html=True)
            cols[j].button("Use these strikes", key=f"gr_pair_{j}", on_click=_gr_cb_pair, args=(c_["L"], c_["H"], c_["cost"], q))
    sec("Every strike pair: cents of EV per $1 risked")
    if m_["cells"]:
        dfc = pd.DataFrame(m_["cells"])
        dfc["buy"] = dfc["L"] if m_["bull"] else dfc["H"]
        dfc["sell"] = dfc["H"] if m_["bull"] else dfc["L"]
        dfc["ev_c"] = (dfc["ev_r"] * 100).round(0)
        dfc["faded"] = (dfc["p_win"] < 0.15) | (dfc["oi_min"].notna() & (dfc["oi_min"] < m_["min_oi"]))
        cur = (_gnum(vals.get("lo")), _gnum(vals.get("hi")))
        dfc["yours"] = (dfc["L"] == cur[0]) & (dfc["H"] == cur[1])
        base = alt.Chart(dfc).encode(x=alt.X("sell:O", title="sell strike", sort="ascending" if m_["bull"] else "descending"),
                                     y=alt.Y("buy:O", title="buy strike", sort="ascending" if m_["bull"] else "descending"))
        heat = base.mark_rect().encode(
            color=alt.Color("ev_r:Q", scale=alt.Scale(domain=[-0.3, 0, 0.3], range=[C_RED, C_PANEL, C_BLUE], clamp=True),
                            legend=alt.Legend(title="EV per $1", format="+.0%")),
            opacity=alt.condition("datum.faded", alt.value(0.35), alt.value(1.0)),
            tooltip=[alt.Tooltip("buy:Q"), alt.Tooltip("sell:Q"), alt.Tooltip("cost:Q", format=".2f", title="cost"),
                     alt.Tooltip("p_mid:Q", format=".0%", title="market line"), alt.Tooltip("p_you_mid:Q", format=".0%", title="your line"),
                     alt.Tooltip("odds:Q", format=".2f", title="pays x:1"), alt.Tooltip("ev_r:Q", format="+.0%", title="EV per $1"),
                     alt.Tooltip("p_win:Q", format=".0%", title="win chance")])
        txt = base.mark_text(fontSize=9, color=C_TEXT).encode(text=alt.Text("ev_c:Q", format="+.0f"))
        mine = base.transform_filter("datum.yours").mark_rect(fill=None, stroke=C_ACCENT, strokeWidth=2)
        show_chart(_alt(alt.layer(heat, txt, mine), max(260, 22 * len(m_["strikes"]))))
        note("Blue pays, red loses, on your view. Faded cells win under 15% of the time" + (" or have thin open interest" if m_["src"] == "chain" else "")
             + ". The amber box is the spread on the Grade tab. Moontower: cost ÷ width is the market's line; width ÷ cost − 1 is the payout.")
    a, b = st.columns(2)
    with a:
        sec("Outright vs spread")
        if m_["outright"]:
            ot = pd.DataFrame(m_["outright"])
            show_df(ot[["K", "cost", "ev_r", "p_win"]].rename(columns={"K": f"{kind} strike"}), height=min(320, 40 + 35 * len(ot)), column_config={
                "cost": st.column_config.NumberColumn(format="%.2f"), "ev_r": st.column_config.NumberColumn("EV per $1", format="percent"),
                "p_win": st.column_config.NumberColumn("win chance", format="percent")})
            best_o = max(m_["outright"], key=lambda x: x["ev_r"])
            best_s = m_["picks"][0]["c"] if m_["picks"] else None
            if best_s:
                note(f"Best outright {best_o['K']:g} {kind} at {best_o['ev_r'] * 100:+.0f}¢ per $1; best spread {nm(best_s)} at {best_s['ev_r'] * 100:+.0f}¢. "
                     + ("The outright wins on EV because your view lifts the whole distribution, tail included. If you only believe in the move to "
                        "the target, the spread is the cleaner bet. Far OTM options carry a lottery premium this model cannot see (Boyer & Vorkink)."
                        if best_o["ev_r"] > best_s["ev_r"] else "The spread wins: an outright keeps paying past your target, and you pay for that."))
    with b:
        sec("Which expiry")
        ex = gr_expiry_table(vals, r, opt) or []
        if ex:
            df = pd.DataFrame(ex)
            df["DTE"] = df["D"].astype(int).astype(str) + np.where(df["current"], " (now)", "")
            cols_ = ["DTE"] + (["exp"] if df["exp"].notna().any() else []) + ["atm", "cost", "ev_r", "late_ev_r", "flat_r"]
            show_df(df[cols_], height=min(360, 40 + 35 * len(df)), column_config={
                "exp": "expiry", "atm": st.column_config.NumberColumn("ATM IV", format="percent"), "cost": st.column_config.NumberColumn(format="%.2f"),
                "ev_r": st.column_config.NumberColumn("EV per $1", format="percent"),
                "late_ev_r": st.column_config.NumberColumn("move 2× slower", format="percent"),
                "flat_r": st.column_config.NumberColumn("flat through hold", format="percent")})
            note(("Each expiry priced from its own chain where your strikes are listed, otherwise its own ATM IV and skew. " if T else
                  "Same IV for every expiry: load the chain for each expiry's real IV. ") + "Short expiries pay most on time and lose most when late.")


def _gr_tab_plan(cfg, vals, r, ctx) -> None:
    if r.get("errs"):
        note("Finish the trade on the Grade tab first.")
        return
    meta = r["meta"]
    c = st.columns(5)
    if r["mode"] == "dir":
        auto = gr_default_style(vals.get("setup"))
        gw_sel(c[0], "Exit style", "style", ["", "burst", "leader"],
               fmt=lambda x: {"": f"Auto ({auto})", "burst": "Burst", "leader": "Leader"}[x], help="Burst: out in 3–5 days. Leader: a runner tranche.")
        gw_num(c[1], "Stop (stock price)" if meta["dir"] == "bull" else "Stop (stock price, above)", "stop", 0.01)
        gw_num(c[2], "Resistance / prior high" if meta["dir"] == "bull" else "Support / prior low", "resist", 0.01, help="Optional")
        gw_num(c[4], "Hurst exponent", "hurst", 0.01, "%.2f", minv=0.3, maxv=0.9, help="Your SPY work: about 0.6")
    gw_num(c[3], "Time stop (trading days)", "timeStop", 1.0, "%.0f", help="Blank = planned hold")
    i = {**vals, "style": vals.get("style") or None}
    pl = gr_plan(i, r, ctx, True)
    if not pl:
        return
    if pl.get("err"):
        warnbox(pl["err"])
        return
    debit = meta["kind"] == "debit"
    kv = []
    if pl["mode"] == "dir":
        kv = [("Buy-stop" if pl["pre"] else "Entry", _gr_d2(pl["E"]))] + ([("OK to", _gr_d2(pl["zone"]["max"]))] if pl.get("zone") else []) + [
            ("Pay ≤" if debit else "Collect ≥", _gr_d2(pl["limit"])), ("Stop", _gr_d2(pl["stop"])), ("T1", _gr_d2(pl["T1"])), ("T2", _gr_d2(pl["T2"])),
            ("Out by", f"day {pl['time_stop']:g}")]
    elif r["dir"] == "term":
        kv = [("Pay ≤", _gr_d2(pl["limit"])), ("Take profit", _gr_d2(pl["tp"])), ("Stop", _gr_d2(_jr(r["price"] * 10) / 20))] + \
             ([("Range", f"{_gr_d2(r['bes'][0])}–{_gr_d2(r['bes'][1])}")] if len(r["bes"]) == 2 else []) + [("Out by", f"day {pl['exit_day']}")]
    else:
        kv = [("Pay ≤" if debit else "Collect ≥", _gr_d2(pl["limit"]))] + [(e["name"], _gr_d2(e["limit"]) if e["limit"] is not None else e["rule"].split(" (")[0]) for e in pl["exits"]]
    kpi_row([kpi_html(k, v, "") for k, v in kv[:7]])
    if pl["mode"] == "dir":
        if not _gnum(vals.get("stop")):
            note(f"Suggested stop {_gr_d2(pl['stop_suggested'])} (1 ADR past entry) is in use.")
        sec("Price ladder")
        cmap = {"t1": C_GREEN, "t2": C_GREEN, "res": C_MUTED, "you": C_BLUE}
        mk = [(pl["stop"], "stop", C_RED), (r["S"], "now", C_TEXT)]
        if pl.get("zone"):
            mk += [(pl["zone"]["trigger"], "trigger", C_ACCENT), (pl["zone"]["chase"], "chase", C_ACCENT2)]
        mk += [(L["price"], "target" if L["k"] == "you" else L["label"], cmap.get(L["k"], C_MUTED)) for L in pl["levels"] if L["k"] != "imp"]
        show_chart(_gr_ladder(mk, (r["S"] * math.exp(-pl["sigI"]), r["S"] * math.exp(pl["sigI"])),
                              (pl["zone"]["trigger"], pl["zone"]["max"]) if pl.get("zone") else None))
        note(f"Grey band: the market's ±1σ over the hold. Amber: the buy zone. 1 hold-move = {pl['sigH'] * 100:.1f}% (HV20 × {pl['hold']:g}^{pl['H']:.2f}); "
             f"the market's = {pl['sigI'] * 100:.1f}%." + (f" {pl['resist_note']}." if pl.get("resist_note") else ""))
        lv = pd.DataFrame([{"level": L["label"], "note": L["note"], "price": L["price"], "move": L["pct"] / 100, "R": L["R"], "mkt close": L["p_close"],
                            "mkt touch": 1.0 if L["passed"] else L["p_touch"], "you": L.get("p_you"), "spread there": L["limitH"]} for L in pl["levels"]])
        P_ = st.column_config.NumberColumn
        show_df(lv, column_config={"price": P_(format="%.2f"), "move": P_(format="percent"), "R": P_(format="%.1f"), "mkt close": P_(format="percent"),
                                   "mkt touch": P_(format="percent"), "you": P_(format="percent"), "spread there": P_(format="%.2f")})
        note(f"Mkt close: chance the stock closes past the level on day {pl['hold']:g}. Touch: chance it trades there at all, about twice the close "
             "odds (Moontower's one-touch rule). Spread there: its value if the level is reached on the last day of the hold, IV unchanged.")
    else:
        sec("Range")
        mk = [(b_, "BE", C_MUTED) for b_ in r["bes"]] + [(r["S"], "now", C_TEXT)]
        if pl.get("strike_line"):
            mk.append((pl["strike_line"], "strike", C_ACCENT))
        if pl.get("ranges"):
            mk += [(pl["ranges"]["lo"], "short put", C_RED), (pl["ranges"]["hi"], "short call", C_RED)]
        show_chart(_gr_ladder(mk, (r["S"] * math.exp(-pl["sigV"]), r["S"] * math.exp(pl["sigV"]))))
        note(f"Grey band: your forecast move over the hold, ±{pl['sigV'] * 100:.1f}%.")

    sz = r["size"]
    ent, hold_l, ex_l = [], [], []
    if pl["mode"] == "dir":
        if pl.get("zone"):
            z = pl["zone"]
            ent.append(_gr_li("Where", f"{'Buy-stop at' if pl['pre'] else 'Trigger'} <b>{_gr_d2(z['trigger'])}</b> · ideal ≤ <b>{_gr_d2(z['ideal'])}</b> · OK ≤ <b>{_gr_d2(z['max'])}</b>",
                              f"Stop chasing at {_gr_d2(z['chase'])} (2 ADR or 10%). O'Neil's buy zone ends 5% past the pivot; Stockbee buys at the start of the move, never after two up days."))
        else:
            ent.append(_gr_li("Where", "Enter a trigger and ADR on the Grade tab to get a buy zone."))
    ent.append(_gr_li("Price", (f"{'Pay up to' if debit else 'Collect at least'} <b>{_gr_d2(pl['limit'])}</b>" if pl["limit"] is not None else "<b>No price works</b>"),
                      (f"Start at mid ({_gr_d2(r['price'])} entered) and work toward it. Past {_gr_d2(pl['limit'])} the trade earns less than +10¢ per $1 risked on your view."
                       if pl["limit"] is not None else "No price clears +10¢ per $1 risked on your view. Pass.")))
    ent.append(_gr_li("Size", f"<b>{sz['contracts']}</b> contracts · <b>{_gr_money(sz['contracts'] * sz['per_contract'])}</b> at risk" if sz["contracts"] > 0 else "<b>0 contracts</b>",
                      ("Max loss is the premium; the stop usually exits well before that." if debit else "Max loss is the width minus the credit; the stop exits before that.")
                      if sz["contracts"] > 0 else ("A hard stop is failing on the Grade tab." if r["gates"] else "The grade or the budget does not fit one contract.")))
    if r["gates"]:
        ent.append(_gr_li("Blocked", f"<b>{_esc(', '.join(g['t'] for g in r['gates']))}</b>", "Fix these before any entry."))
    if pl["mode"] == "dir":
        hold_l.append(_gr_li("Stop", f"Daily close {'below' if pl['s'] == 1 else 'above'} <b>{_gr_d2(pl['stop'])}</b>",
                             f"Stopped out on day 1, you lose about {_gr_money(-pl['stop_pnl'])} per contract ({pct(pl['stop_of_risk'])} of max loss) instead of the full {_gr_money(r['max_loss'] * 100)}."))
        hold_l.append(_gr_li("Time", f"Day <b>{pl['time_stop']:g}</b>: exit unless past <b>{_gr_d2(pl['progress'])}</b>",
                             f"That is 1 ADR in your favor. Sitting flat until then costs about {_gr_money(-pl['flat_pnl'])} per contract in decay."))
        hold_l.append(_gr_li("After T1", f"Stop on the rest moves to <b>{_gr_d2(pl['E'])}</b>", "Kullamägi sells a third to half within 3–5 days and holds the rest risk-free."))
    elif r["dir"] == "term":
        if len(r["bes"]) == 2:
            hold_l.append(_gr_li("Range", f"Exit on a daily close outside <b>{_gr_d2(r['bes'][0])}</b>–<b>{_gr_d2(r['bes'][1])}</b>",
                                 "Those are the breakevens at the front expiry. A calendar pays only near its strike."))
        hold_l.append(_gr_li("Time", f"Day <b>{pl['exit_day']}</b> at the latest", "A week before the front month expires: close, or roll the short leg out. Its gamma dominates the last week (Moontower)."))
        hold_l.append(_gr_li("Vol", "Watch the back month's IV", f"You are long the back month's vega. Your plan assumes {r['ivx'] * 100:.1f}% at the front expiry; a broad drop in vol hurts even with the stock at the strike."))
    else:
        hold_l.append(_gr_li("Time", f"Day <b>{pl['time_stop']:g}</b>", "If the move has not come by then, theta has won. Exit." if r["dir"] == "long_vol" else "Short premium: also exit with 21 days left."))
    hold_l.append(_gr_li("Daily", "Re-grade at today's price (panel below)", "Sinclair and Mack argue against 'taking profits' or 'letting it run': each day the only question is whether you would buy this position now."))
    if vals.get("earnings"):
        hold_l.append(_gr_li("Event", "This is an event trade" if vals.get("deliberate") else "<b>Exit before earnings</b>",
                             "Vol drops right after the print. Sell soon after it." if vals.get("deliberate") else "Earnings land before expiry. Holding through turns a setup into a coin flip on the print."))
    if pl["mode"] == "dir":
        if pl.get("capture"):
            ex_l.append(_gr_li("Cap", f"{'Close or roll at a mark of' if debit else 'Buy back at'} <b>{_gr_d2(pl['capture']['mark'])}</b>",
                               f"{pl['capture']['note']}, near {_gr_d2(pl['capture']['price'])} on the stock. Past that you risk most of the value to win the last sliver."))
        if pl.get("rr_flag"):
            ex_l.append(_gr_li("Check", f"<b>{_esc(pl['rr_flag'])}</b>"))
        ex_l.append(_gr_li("Limits", "Place the T1 and T2 sells as GTC limits right after the fill", "Prices assume the level is reached on the last day of the hold with IV unchanged."))
    ent_h = "<div class='sec'>1 · Entry</div><ul class='gr-steps'>" + "".join(ent) + "</ul>"
    hold_h = "<div class='sec'>2 · Hold</div><ul class='gr-steps'>" + "".join(hold_l) + "</ul>"
    a, b = st.columns(2)
    a.markdown(ent_h, unsafe_allow_html=True)
    b.markdown(hold_h, unsafe_allow_html=True)
    sec("3 · Exit")
    show_df(pd.DataFrame([{"tranche": e["name"], "qty": str(e["qty"]) if e["qty"] else "—", "trigger": e["rule"],
                           "GTC limit": "—" if e["limit"] is None else f"{e['limit']:.2f}", "then": e["then"]} for e in pl["exits"]]),
            column_config={"trigger": st.column_config.TextColumn(width="large"), "then": st.column_config.TextColumn(width="large")})
    if ex_l:
        md("<ul class='gr-steps'>" + "".join(ex_l) + "</ul>")
    sec("Check an open position")
    note("Holding is a new decision each day. Enter today's numbers: the plan's rules run first, then the trade is re-graded at today's price.")
    c = st.columns(6)
    gw_num(c[0], "Stock price now", "h_spot", 0.01)
    gw_num(c[1], "Spread mark now" if debit else "Cost to close now", "h_mark", 0.01)
    gw_num(c[2], "Trading days held", "h_days", 1.0, "%.0f")
    if pl["mode"] == "dir":
        gw_sel(c[3], "Trims done", "h_trims", [0, 1, 2], radio=True, horizontal=True)
        gw_num(c[4], "Today's target", "h_target", 0.01, help=f"e.g. T1 {pl['T1']:.2f}")
        gw_num(c[5], "Today's probability %", "h_p", 1.0, "%.0f", minv=1, maxv=99)
    now = {"spot": vals.get("h_spot"), "mark": vals.get("h_mark"), "days": vals.get("h_days"), "trims": vals.get("h_trims") or 0,
           "target": vals.get("h_target"), "p": vals.get("h_p")}
    hc = gr_hold_check(i, r, pl, now, ctx)
    if hc.get("need"):
        note("Enter today's stock price and mark to get a call: hold, trim, close or exit.")
    else:
        line = (f" · market line now {pct(hc['vert']['p_mkt_mid'])} past ${hc['vert']['mid']:.2f} vs you {pct(hc['vert']['p_you_mid'])}" if hc.get("vert") else
                (f" · market {pct(hc['p_mkt'])} vs you {pct(hc['p_user'])} to reach today's target" if hc.get("p_mkt") is not None else ""))
        md(hero_html(hc["call"], GR_CALL_COLOR[hc["call"]], f"Open P&L {hc['pnl_r']:+.2f}R of max loss{line}", hc["why"]))


def _gr_tab_log(log: pd.DataFrame, uni: pd.DataFrame, vals: Dict[str, Any]) -> None:
    rows = log.to_dict("records")
    closed = [x for x in rows if x.get("status") == "closed" and _gr_r(x) is not None]
    Rs = [_gr_r(x) for x in closed]
    s = gr_tstat(Rs)
    resolved = [x for x in rows if _gr_bool(x.get("target_hit")) is not None]
    hits = sum(1 for x in resolved if _gr_bool(x.get("target_hit")))
    clvs = [v for v in (_gr_clv(x) for x in rows) if v is not None]
    kpi_row([kpi_html("Graded", len(rows), f"{sum(1 for x in rows if x.get('status') == 'passed')} passed"),
             kpi_html("Closed", len(closed), f"{sum(1 for x in rows if x.get('status') == 'open')} open"),
             kpi_html("Avg R", f"{s['m']:+.2f}" if s else "—", f"p ≈ {s['p']:.2f} (n {s['n']})" if (s and s.get("p") is not None) else "needs 2+ closed"),
             kpi_html("Target hit", pct(hits / len(resolved)) if resolved else "—", f"{len(resolved)} resolved"),
             kpi_html("3-day CLV", f"{sum(clvs) / len(clvs):+.2f}R" if clvs else "—", f"{len(clvs)} marked")])
    if not rows:
        note(f"No graded trades yet. Grade a trade and Save it; the log is {GR_LOG}.")
        return
    a, b = st.columns(2)
    with a:
        sec("Grades vs results")
        g = []
        for L in ("A", "B", "C", "D"):
            xs = [_gr_r(x) for x in closed if x.get("letter") == L]
            ts = gr_tstat(xs)
            g.append({"grade": L, "n": len(xs), "avg_R": float(np.mean(xs)) if xs else np.nan,
                      "lo": (ts["m"] - 1.96 * ts["se"]) if ts else np.nan, "hi": (ts["m"] + 1.96 * ts["se"]) if ts else np.nan})
        gd = pd.DataFrame(g)
        if closed:
            bars_ = alt.Chart(gd).mark_bar(color=C_ACCENT).encode(x=alt.X("grade:N", title=None), y=alt.Y("avg_R:Q", title="avg R per closed trade"),
                                                                tooltip=["grade", "n", alt.Tooltip("avg_R:Q", format="+.2f")])
            err = alt.Chart(gd.dropna(subset=["lo"])).mark_rule(color=C_TEXT).encode(x="grade:N", y="lo:Q", y2="hi:Q")
            show_chart(_alt(alt.layer(bars_, err), 220))
        note(f"{len(closed)} closed so far. Read this after 30+; the 95% ranges are wide until then. If A's don't beat C's, the rubric needs work.")
    with b:
        sec("Your probabilities")
        rr_ = [x for x in resolved if _gnum(x.get("p_user_raw")) is not None]
        if rr_:
            bins = []
            for lo_, hi_ in ((0, .2), (.2, .35), (.35, .5), (.5, .65), (.65, 1.01)):
                xs = [x for x in rr_ if lo_ <= _gnum(x["p_user_raw"]) < hi_]
                if xs:
                    bins.append({"you said": np.mean([_gnum(x["p_user_raw"]) for x in xs]), "hit": np.mean([1.0 if _gr_bool(x["target_hit"]) else 0.0 for x in xs]),
                                 "market": np.mean([_gnum(x.get("p_mkt")) or 0 for x in xs]), "n": len(xs)})
            bd = pd.DataFrame(bins)
            diag = alt.Chart(pd.DataFrame({"x": [0, 1], "y": [0, 1]})).mark_line(strokeDash=[4, 4], color=C_MUTED).encode(x="x:Q", y="y:Q")
            pts = alt.Chart(bd).mark_circle(color=C_ACCENT, opacity=0.9).encode(
                x=alt.X("you said:Q", scale=alt.Scale(domain=[0, 1]), axis=alt.Axis(format="%")), y=alt.Y("hit:Q", scale=alt.Scale(domain=[0, 1]), axis=alt.Axis(format="%")),
                size=alt.Size("n:Q", legend=None), tooltip=[alt.Tooltip("you said:Q", format=".0%"), alt.Tooltip("market:Q", format=".0%"), alt.Tooltip("hit:Q", format=".0%"), "n"])
            show_chart(_alt(alt.layer(diag, pts), 220))
        cal = gr_calibration([{"target_hit": _gr_bool(x.get("target_hit")), "p_user_raw": _gnum(x.get("p_user_raw")), "p_mkt": _gnum(x.get("p_mkt"))}
                              for x in resolved if x.get("status") in ("closed", "passed")])
        note(f"{cal['n']} of 20 resolved needed before the grader adjusts your probabilities." if cal["k"] is None else
             f"You keep {cal['k'] * 100:.0f}% of the edge you claim over the market (said {pct(cal['pu'])}, market {pct(cal['pm'])}, hit {pct(cal['hit'])}).")
    sec("Book heat")
    themes = dict(zip(uni["ticker"], uni["theme"])) if len(uni) else {}
    open_ = []
    for x in rows:
        if x.get("status") == "open" and _gnum(x.get("max_loss")):
            cf = _gnum(x.get("contracts_filled"))
            cf = cf if cf is not None else (_gnum(x.get("contracts")) or 0)
            tk = str(x.get("ticker") or "").upper()
            open_.append({"ticker": tk, "theme": themes.get(tk) or "Unclassified", "risk": cf * _gnum(x["max_loss"]) * 100})
    if open_:
        bh = gr_book_heat(open_, None, {"rho_same": _gnum(vals.get("rhoSame")) or 0.6, "rho_cross": _gnum(vals.get("rhoCross")) or 0.2})
        sleeve = _gnum(vals.get("sleeve")) or 0
        cap = (_gnum(vals.get("heatCap")) or 30) / 100 * sleeve
        kpi_row([kpi_html("Open option risk", _gr_money(bh["total"]), f"of {_gr_money(cap)} cap", "bad" if bh["total"] > cap else ""),
                 kpi_html("Of sleeve", pct(bh["total"] / sleeve) if sleeve else "—", f"cap {(_gnum(vals.get('heatCap')) or 30):.0f}%"),
                 kpi_html("Independent bets", f"{bh['eff_bets']:.1f}", f"{len(open_)} open trades at the book correlations")])
        bt = pd.DataFrame([{"theme": k, "risk": v, "names": ", ".join(o["ticker"] for o in open_ if o["theme"] == k)} for k, v in bh["by_theme"].items()]).sort_values("risk", ascending=False)
        show_df(bt, column_config={"risk": st.column_config.NumberColumn(format="$%.0f")})
    else:
        note("No open trades. Open trades are log rows with status 'open'; their risk is contracts × max loss.")
    near = [_gr_r(x) for x in closed if _gnum(x.get("ext_adr")) is not None and _gnum(x["ext_adr"]) <= 0.5]
    far = [_gr_r(x) for x in closed if _gnum(x.get("ext_adr")) is not None and _gnum(x["ext_adr"]) > 0.5]
    note(f"Chasing check: within 0.5 ADR of the trigger {len(near)} trades, avg {np.mean(near):+.2f}R · beyond 0.5 ADR {len(far)} trades, avg {np.mean(far):+.2f}R."
         if (near and far) else f"Chasing check: {len(near)} closed trades within 0.5 ADR of the trigger, {len(far)} beyond. Needs some of each.")
    sec("Trades: add outcomes")
    view = log.copy()
    yn = lambda v: {True: "yes", False: "no"}.get(_gr_bool(v), "")  # noqa: E731
    view["target_hit"] = view["target_hit"].map(yn)
    view["followed_plan"] = view["followed_plan"].map(yn)
    view["R"] = [_gr_r(x) for x in view.to_dict("records")]
    for c_ in ("note", "why", "status", "regime", "fit", "ticker", "structure", "letter"):
        view[c_] = view[c_].fillna("").astype(str).replace({"nan": ""})
    view = view.sort_values("created", ascending=False)
    cols = ["created", "ticker", "structure", "letter", "score", "regime", "fit", "status", "contracts", "contracts_filled", "pnl", "mark3",
            "target_hit", "followed_plan", "R", "note", "why", "id"]
    ed = st.data_editor(view[cols], key="gr_log_ed", hide_index=True, disabled=[c_ for c_ in cols if c_ not in
                        ("status", "contracts_filled", "pnl", "mark3", "target_hit", "followed_plan", "note")],
                        column_config={"status": st.column_config.SelectboxColumn(options=["open", "closed", "passed"]),
                                       "target_hit": st.column_config.SelectboxColumn("target there on exit day", options=["", "yes", "no"]),
                                       "followed_plan": st.column_config.SelectboxColumn("followed plan", options=["", "yes", "no"]),
                                       "pnl": st.column_config.NumberColumn("P&L $", format="%.0f"),
                                       "mark3": st.column_config.NumberColumn("mark 3 sessions in", format="%.2f"),
                                       "R": st.column_config.NumberColumn(format="%+.2f"), "score": st.column_config.NumberColumn(format="%.0f")})
    a, b, _ = st.columns([1, 1, 3])
    if a.button("Save outcomes", key="gr_log_save"):
        upd = log.set_index("id")
        for rec in ed.to_dict("records"):
            if rec["id"] in upd.index:
                for c_ in ("status", "contracts_filled", "pnl", "mark3", "target_hit", "followed_plan", "note"):
                    upd.at[rec["id"], c_] = rec[c_]
        gr_save_log(upd.reset_index()[GR_LOG_COLS])
        st.success("Outcomes saved.")
    b.download_button("Download log (CSV)", log.to_csv(index=False), "grader_log.csv", "text/csv")
    note("3-day CLV is the spread's mark three sessions after entry, in R: whether the market moved toward your bet long before the trade "
         "resolves, which needs far fewer trades to read than P&L (Mack). Delete rows by editing the CSV.")


def _gr_tab_rubric() -> None:
    sec("How a grade is built")
    md("""<ul class='gr-steps'>
<li><b>Hard stops.</b> Any one makes it "No trade": no named edge, no specific view, chasing past the trigger, earnings inside the expiry (unless a deliberate event trade), a market wider than 30% of mid, entry mode CASH on a long (or ANTICIPATION_ONLY once price is through the trigger), negative expected value at your own odds.</li>
<li><b>Four pillars, 25 points each.</b> Edge (War Room conviction and theme rank; or the vol edge's evidence), Entry (distance past the trigger in ADRs, day of the move, expiry fit; IV rank for vol trades), Price (bid-ask as % of mid, and IV vs HV20 and IV rank weighted by how much vol the structure owns), Odds (expected value per $1 risked on your view: +30¢ or more is full marks).</li>
<li><b>Size.</b> A (80+) risks the full per-trade premium, B 70%, C 40%, D passes. The regime cell scales it, ANTICIPATION_ONLY halves longs, a carry unwind cuts 40%, an avoided structure halves it. Half-Kelly on your own odds caps it, open same-theme risk cuts it (first-order Kelly with correlation), and until 20 grades are resolved every trade is starter size.</li>
</ul>""")
    sec("Regime playbook")
    md("""<ul class='gr-steps'>
<li><b>Direction</b> comes from the War Room posture: BUY_RIP risk-on, BUY_DIP recovery, NEUTRAL chop, AVOID risk-off. Without the War Room files, the lab's climate chip suggests one.</li>
<li><b>Vol</b> comes from VIX against its five-year history and VIX/VIX3M. Without the War Room files, SPY's 30-day ATM IV stands in for VIX and its 30/90-day ratio for VIX/VIX3M.</li>
<li><b>No new short vol in backwardation.</b> The VIX curve's slope predicts variance-asset returns; the flatter or more inverted, the worse for short vol (Johnson).</li>
<li><b>Own vol when cheap, sell it when rich.</b> A wide variance premium pays sellers and has preceded better index returns (Bollerslev, Tauchen &amp; Zhou); options where IV is far above realized have the worst returns (Goyal &amp; Saretto).</li>
<li><b>Calendars when the front month is rich.</b> Short-dated IV well above longer-dated IV is overpriced in the cross-section (Vasquez); a calendar is a bet on forward vol (Moontower), and an ORATS backtest improved SPY calendars by entering only with the curve flat or inverted.</li>
<li><b>Put credit spreads in rich bull markets</b>: OTM puts are priced above OTM calls by more than their risk justifies (Hull &amp; Sinclair, index options).</li>
<li><b>Small and fast after a panic</b>: momentum crashes come at the rebound, led by the losers (Daniel &amp; Moskowitz).</li>
</ul>""")
    sec("Calendars and diagonals")
    note("Valued at the front expiry. The back month then prices at the IV you choose: the forward vol by default (the market's own answer, "
         "so with no view the trade is worth what it costs), back IV unchanged, or the curve keeping its shape. The edge comes from realized "
         "vol below the front month's IV and from the back month holding its IV above the forward. Exits: about +25% of the debit, a stop at "
         "half the debit or a close outside the breakevens, and out a week before the front expires.")
    sec("Plan, strikes, log")
    note("Targets are hold-moves: HV20 scaled by days^H with H about 0.6 from your SPY work; T1 = 1, T2 = 2, pulled in by resistance. Burst "
         "trades take half at T1 and the rest at T2 or the time stop; leaders a third, a third and a runner on the 21 EMA. Debit spreads close or "
         "roll at 80% of width; short premium at 50% of the credit or 21 DTE (tastylive). The strike picker scores every vertical up to your "
         "target (Moontower's Blaster): most edge per $1, best log growth at your bet size, and highest hit rate above +10¢. The log tracks "
         "grades against R, your stated probabilities against hit rates, and 3-day closing line value; after 20 resolved trades it shrinks your "
         "probability toward the market's by your real hit rate.")
    sec("Limits")
    note("Black-Scholes with flat vol per expiry, no rates or dividends; skew enters through the price you pay and the chain. Thresholds are "
         "starting points from the sources, not fitted to your trades. The log is how you fit them.")


def render_grader(cfg: Dict[str, Any], uni: pd.DataFrame, bars: Dict[str, pd.DataFrame], bench_bars: Dict[str, pd.DataFrame],
                  hvs: Dict[str, float], clim: Optional[Dict[str, Any]]) -> None:
    vals = _gr_init(cfg, clim, bench_bars, hvs)
    log = gr_load_log()
    ctx = _gr_ctx(vals, log, uni)
    r = gr_grade(vals, ctx)
    T = st.tabs(["Regime", "Grade", "Strikes", "Plan", "Log", "Rubric"])
    with T[1]:
        _gr_tab_grade(cfg, uni, bars, bench_bars, vals, r, ctx, log)
    with T[0]:
        _gr_tab_regime(cfg, uni, bars, bench_bars, hvs, clim, vals, r)
    with T[2]:
        _gr_tab_strikes(cfg, vals, r, ctx)
    with T[3]:
        _gr_tab_plan(cfg, vals, r, ctx)
    with T[4]:
        _gr_tab_log(log, uni, vals)
    with T[5]:
        _gr_tab_rubric()


# ═══════════════════════════════════════════════════════════════════════════
#  MACD STRATEGIES  (Stocks > Screener)
#  MACD (Gerald Appel, late 1970s): fast EMA - slow EMA of the close. Signal: EMA of MACD.
#    Histogram: MACD - signal (Thomas Aspray, 1986). MACD is a smoothed estimate of trend
#    velocity; the histogram estimates its acceleration. 12/26/9 dates from the six-day week
#    (two weeks, a month, a week and a half). Appel used 8/17/9 for buys and 12/25(26)/9 for sells.
#  MACD-V (Alex Spiroglou, 2022; NAAIM Founders Award, CMT Charles H. Dow Award):
#    (EMA12 - EMA26) / ATR26 x 100, signal = EMA9 of MACD-V. Volatility-normalized, so the same
#    levels mean the same thing on every name. Lifecycle states (StockCharts ChartSchool):
#      Risk (oversold) below -150            Rebounding  -150..+50, above signal
#      Rallying  +50..+150, above signal     Risk (overbought) above +150, above signal
#      Retracing above -50, below signal     Reversing  -150..-50, below signal
#      Ranging   inside +/-50 for 20+ sessions (checked first)
#  Elder (Trading for a Living, 1993; Come Into My Trading Room, 2002):
#    Triple Screen: the weekly MACD-histogram slope is the tide; trade the daily pullback against
#      it; enter on a buy stop above the prior day's high.
#    Impulse: green = 13 EMA rising and histogram rising; red = both falling; blue = mixed.
#      A censor, not a signal: red forbids new longs, green forbids new shorts.
#    Bullish divergence: price makes a lower low, the histogram's second trough is shallower, and
#      the histogram crossed above zero between the troughs. The signal is the first uptick.
#  Rabil (StockCharts TV, "Mastering MACD: The Fly-By Pattern", 1 Feb 2024): treat MACD as an
#    oscillator. After a stretched run it pulls back toward zero; the zero-line reversal is the turn
#    back up. Fly-by = turns before reaching zero ("you get close to it but you don't actually
#    reach it"), his strongest version; kiss and go = touches zero; slight overrun = the MACD line
#    dips a little under zero while the signal line stays above. A pullback with ADX back to 25 or
#    lower (under both DI lines) strengthens it. Check the higher time frame first.
#  Evidence: a signal-line cross alone predicts little (Chong, Ng & Liew 2014: 4 of 5 indexes;
#    Hill 2017: S&P 100 long-short lost ~4%/yr). The zero-line cross and trend filters do better.
#    Volatility-normalized MACD over several time scales is a standard CTA trend signal
#    (Baz, Granger, Harvey, Le Roux & Rattray 2015).
#  No look-ahead: weekly values are computed as of each day (the forming week uses that day's
#  close), so the event study only uses what was known on the signal day.
# ═══════════════════════════════════════════════════════════════════════════

MC_SETTINGS = {"12/26/9": (12, 26, 9, "ema"), "8/17/9": (8, 17, 9, "ema"), "3/10/16": (3, 10, 16, "sma")}
MC_SETTING_LABEL = {"12/26/9": "12/26/9 (standard)", "8/17/9": "8/17/9 (Appel's faster buy setting)",
                    "3/10/16": "3/10/16 SMA (Raschke's 3/10 oscillator)"}
MC_SETUPS = {
    "pullback": "Pullback hook",
    "zero": "Zero-line cross",
    "cross": "Bull cross above zero",
    "rally": "Rallying thrust",
    "impulse": "Impulse value buy",
    "bulldiv": "Bullish divergence",
    "flyby_adx": "Fly-by + ADX reset",
    "flyby": "Fly-by (zero-line reversal)",
    "kiss": "Kiss and go (zero line)",
    "overrun": "Slight overrun (zero line)",
}
MC_ZLR = ["flyby_adx", "flyby", "kiss", "overrun"]          # Rabil's zero-line reversal family
FB_LOOK = 40              # sessions back to find the run's MACD peak
FB_STRETCH = 50.0         # MACD-V the run must have reached first ("stretched away from the zero line")
FB_BANDS = {"flyby": (0.05, 0.35), "kiss": (-0.05, 0.05), "overrun": (-0.30, -0.05)}   # trough as a share of the peak
FB_ADX = 25.0
MC_SETUP_HELP = {
    "pullback": "Weekly MACD above zero and weekly impulse not red; close above the 50-day; daily MACD-V above -50 "
                "(retracing, not reversing); histogram below zero ticks up for the first time.",
    "zero": "MACD crosses above zero (the 12 EMA crosses the 26 EMA) with the close above the 200-day and the weekly "
            "histogram rising.",
    "cross": "MACD crosses above its signal line while MACD is above zero, weekly MACD is above zero and MACD-V is "
             "below +150.",
    "rally": "MACD-V crosses above +50 while above its signal line, weekly MACD above zero, MACD-V not above +150.",
    "impulse": "Weekly impulse green; daily impulse flips from red to blue or green; the 3-day low reached the 13-day "
               "EMA and the close is above 97% of the 26-day EMA (Elder's value zone).",
    "bulldiv": "Lower low in price, shallower second histogram trough, histogram above zero between the troughs "
               "(troughs at most 60 sessions apart, the first at least 0.1 ATR deep); fires on the first uptick.",
    "flyby": "Joe Rabil's strongest zero-line reversal. In the last 40 sessions MACD-V reached +50 or more; MACD then "
             "pulled back to between 5% and 35% of that peak without touching zero, and today is its first uptick off "
             "the lowest point since the peak. Weekly MACD above zero.",
    "flyby_adx": "A fly-by where ADX(14) fell to 25 or lower at some point during the pullback: Rabil's 'low ADX "
                 "condition', the trend resting before it resumes.",
    "kiss": "Zero-line reversal where the MACD line comes back to zero (within 5% of the peak either side) and turns "
            "up: Rabil's 'kiss and go'. Same stretch, uptick and weekly rules as the fly-by.",
    "overrun": "Zero-line reversal where the MACD line dips slightly under zero (down to -30% of the peak) while the "
               "signal line stays above zero, then turns up. If both lines go under zero it isn't counted: Rabil says "
               "that takes longer to repair.",
}
MC_FILTER_OPTS = ["off", "regime", "any", "zlr"] + list(MC_SETUPS)
MC_FILTER_LABEL = {"off": "off", "regime": "Setups today's regime favors", "any": "Any bullish MACD setup",
                   "zlr": "Any zero-line reversal (Rabil: fly-by, kiss, overrun)", **MC_SETUPS}
MC_STATES = ["Ranging", "Rebounding", "Rallying", "Risk (overbought)", "Retracing", "Reversing", "Risk (oversold)"]
MC_SHAPES = {"pullback": ("triangle-up", C_GREEN), "zero": ("diamond", C_ACCENT), "cross": ("circle", C_BLUE),
             "rally": ("square", "#c084fc"), "impulse": ("triangle-right", "#2dd4bf"), "bulldiv": ("cross", "#f0abfc"),
             "beardiv": ("triangle-down", C_RED), "flyby_adx": ("wedge", "#a3e635"), "flyby": ("arrow", "#38bdf8"),
             "kiss": ("triangle-left", "#fb923c"), "overrun": ("triangle", "#facc15")}
MC_STOP_KIND = {"pullback": "wave", "bulldiv": "wave", "impulse": "low10", "zero": "low10", "cross": "low10", "rally": "low10",
                "flyby_adx": "pull", "flyby": "pull", "kiss": "pull", "overrun": "pull"}
MC_STOP_TXT = {"wave": "pullback low", "low10": "10-day low", "pull": "pullback low after the run's high"}
MC_REGIME = {
    "BUY_RIP": (["cross", "rally", "pullback", "zero", "flyby_adx", "flyby"],
                "Trend is paying: continuation first (bull cross above zero, rallying thrust, fly-bys); pullback hooks for adds."),
    "BUY_DIP": (["pullback", "impulse", "bulldiv", "flyby_adx", "flyby", "kiss", "overrun"],
                "Buy weakness inside uptrends: pullback hooks, Elder value buys and Rabil's zero-line reversals; divergences "
                "only in names holding the 200-day."),
    "NEUTRAL": (["pullback", "flyby_adx"],
                "Pullback hooks and fly-bys after an ADX reset only, in names whose weekly tide is up, at reduced size. Skip "
                "crosses inside the +/-50 band."),
    "AVOID": ([], "No new MACD longs. Use MACD for exits: bearish divergence, daily impulse red, weekly tide down."),
}
MC_MODE = {
    "TIGHT_MA": (["pullback", "impulse", "flyby_adx", "flyby", "kiss"],
                 "TIGHT_MA: entries near the averages only, so pullback hooks, value buys and zero-line reversals."),
    "ANTICIPATION_ONLY": (["pullback", "bulldiv", "flyby_adx", "flyby"],
                          "ANTICIPATION_ONLY: act on hooks, fly-bys and divergences before the cross, half size; "
                          "don't chase crosses."),
    "CASH": ([], "CASH: no new longs. MACD is for exits today."),
}
MC_MAX_ROWS = 1500        # sessions kept for MACD panels (about six years)


def _mc_ma(x: pd.DataFrame, n: int, kind: str) -> pd.DataFrame:
    if kind == "sma":
        return x.rolling(n, min_periods=n).mean()
    return x.ewm(span=n, adjust=False, min_periods=n).mean()


def _mc_atr(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, n: int) -> pd.DataFrame:
    pc = c.shift(1)
    tr = np.fmax(np.fmax((h - l).to_numpy(float), (h - pc).abs().to_numpy(float)), (l - pc).abs().to_numpy(float))
    tr = pd.DataFrame(tr, index=c.index, columns=c.columns)
    return tr.ewm(alpha=1.0 / n, adjust=False, min_periods=n).mean()


def mc_week_live(c: pd.DataFrame, h: pd.DataFrame, l: pd.DataFrame, n_fast: int = 12, n_slow: int = 26,
                 n_sig: int = 9, n_imp: int = 13) -> Dict[str, pd.DataFrame]:
    """Weekly MACD, MACD-V and 13-week EMA as of each day. The forming week's close is that day's close, so a
    Friday value equals the completed weekly bar and a Tuesday value is what a weekly chart showed on Tuesday."""
    wid = c.index.to_period("W-FRI")
    wk_c = c.groupby(wid).last()
    wk_h, wk_l = h.groupby(wid).max(), l.groupby(wid).min()

    def ema(x, n):
        return x.ewm(span=n, adjust=False).mean()

    def prev(x):                                    # last completed week's value, on every day of the next week
        return x.shift(1).reindex(wid).set_axis(c.index)

    def live(prev_val, today, n):
        a = 2.0 / (n + 1)
        return a * today + (1 - a) * prev_val

    ef, es, e13 = ema(wk_c, n_fast), ema(wk_c, n_slow), ema(wk_c, n_imp)
    mw = ef - es
    sw = ema(mw, n_sig)
    macd = live(prev(ef), c, n_fast) - live(prev(es), c, n_slow)
    sig = live(prev(sw), macd, n_sig)
    hist = macd - sig
    hist_prev = prev(mw - sw)
    e13_live, e13_prev = live(prev(e13), c, n_imp), prev(e13)
    hi_sofar = h.groupby(wid).cummax()
    lo_sofar = l.groupby(wid).cummin()
    pc = prev(wk_c)
    tr_live = np.fmax(np.fmax((hi_sofar - lo_sofar).to_numpy(float), (hi_sofar - pc).abs().to_numpy(float)),
                      (lo_sofar - pc).abs().to_numpy(float))
    tr_live = pd.DataFrame(tr_live, index=c.index, columns=c.columns)
    wtr = np.fmax(np.fmax((wk_h - wk_l).to_numpy(float), (wk_h - wk_c.shift(1)).abs().to_numpy(float)),
                  (wk_l - wk_c.shift(1)).abs().to_numpy(float))
    watr = pd.DataFrame(wtr, index=wk_c.index, columns=c.columns).ewm(alpha=1.0 / n_slow, adjust=False).mean()
    atr_live = tr_live / n_slow + prev(watr) * (1 - 1.0 / n_slow)
    up_h, dn_h = hist > hist_prev, hist < hist_prev
    up_e, dn_e = e13_live > e13_prev, e13_live < e13_prev
    imp = pd.DataFrame(np.where(up_h & up_e, 1, np.where(dn_h & dn_e, -1, 0)), index=c.index, columns=c.columns)
    imp = imp.where(hist_prev.notna() & e13_prev.notna())
    atr_ok = atr_live.replace(0, np.nan)
    f32 = lambda x: x.astype("float32")
    return {"macd": macd, "hist": hist, "hist_up": up_h, "macdv": f32(macd / atr_ok * 100),
            "histv": f32(hist / atr_ok * 100), "imp": f32(imp)}


def mc_divergences(low: pd.DataFrame, high: pd.DataFrame, hist: pd.DataFrame, atr: pd.DataFrame, max_gap: int = 60,
                   min_depth: float = 10.0) -> Dict[str, Any]:
    """Elder's histogram divergences, scanned bar by bar across all names at once.
    A wave is a run of same-sign histogram bars. Bullish: inside a negative wave, price's low so far is below the
    previous negative wave's low, the histogram's trough so far is shallower than that wave's trough, the troughs are
    at most max_gap sessions apart, and the histogram ticks up (first time only). Bearish mirrors it.
    The first trough must be at least min_depth deep in MACD-V units (0.1 ATR at 10), so the small wiggles of a
    steady trend, where the histogram hugs zero, don't count as divergences."""
    L, Hh, X = low.to_numpy(float), high.to_numpy(float), hist.to_numpy(float)
    A = (hist / atr.replace(0, np.nan) * 100).to_numpy(float)
    n, k = X.shape
    bull, bear = np.zeros((n, k), bool), np.zeros((n, k), bool)
    wave_low = np.full((n, k), np.nan)
    nan = np.full(k, np.nan)
    in_neg, in_pos = np.zeros(k, bool), np.zeros(k, bool)
    c_lo, c_hmin, c_imin, p_lo, p_hmin, p_imin, c_amin, p_amin = (nan.copy() for _ in range(8))
    c_hi, c_hmax, c_imax, q_hi, q_hmax, q_imax, c_amax, q_amax = (nan.copy() for _ in range(8))
    fired_b, fired_s = np.zeros(k, bool), np.zeros(k, bool)
    last_lo, prev_x = nan.copy(), nan.copy()
    for i in range(n):
        x = X[i]
        ok = np.isfinite(x)
        neg, pos = ok & (x < 0), ok & (x > 0)
        end_n, end_p = in_neg & ok & ~neg, in_pos & ok & ~pos
        p_lo, p_hmin, p_imin, p_amin = (np.where(end_n, a, b) for a, b in ((c_lo, p_lo), (c_hmin, p_hmin),
                                                                            (c_imin, p_imin), (c_amin, p_amin)))
        q_hi, q_hmax, q_imax, q_amax = (np.where(end_p, a, b) for a, b in ((c_hi, q_hi), (c_hmax, q_hmax),
                                                                            (c_imax, q_imax), (c_amax, q_amax)))
        st_n, st_p = neg & ~in_neg, pos & ~in_pos
        c_lo = np.where(st_n, L[i], np.where(neg, np.fmin(c_lo, L[i]), c_lo))
        c_hi = np.where(st_p, Hh[i], np.where(pos, np.fmax(c_hi, Hh[i]), c_hi))
        nm = neg & (st_n | (x < c_hmin))
        c_hmin, c_imin, c_amin = np.where(nm, x, c_hmin), np.where(nm, i, c_imin), np.where(nm, A[i], c_amin)
        nx = pos & (st_p | (x > c_hmax))
        c_hmax, c_imax, c_amax = np.where(nx, x, c_hmax), np.where(nx, i, c_imax), np.where(nx, A[i], c_amax)
        fired_b, fired_s = fired_b & ~st_n, fired_s & ~st_p
        have = np.isfinite(prev_x)
        tb = (neg & ~fired_b & np.isfinite(p_hmin) & (c_lo < p_lo) & (c_hmin > p_hmin) & have & (x > prev_x)
              & ((c_imin - p_imin) <= max_gap) & (p_amin <= -min_depth))
        ts = (pos & ~fired_s & np.isfinite(q_hmax) & (c_hi > q_hi) & (c_hmax < q_hmax) & have & (x < prev_x)
              & ((c_imax - q_imax) <= max_gap) & (q_amax >= min_depth))
        bull[i], bear[i] = tb, ts
        fired_b, fired_s = fired_b | tb, fired_s | ts
        in_neg, in_pos = np.where(ok, neg, in_neg), np.where(ok, pos, in_pos)
        last_lo = np.where(neg, c_lo, last_lo)
        wave_low[i] = last_lo
        prev_x = np.where(ok, x, prev_x)
    forming_b = (in_neg & ~fired_b & np.isfinite(p_hmin) & (c_lo < p_lo) & (c_hmin > p_hmin)
                 & ((c_imin - p_imin) <= max_gap) & (p_amin <= -min_depth))
    forming_s = (in_pos & ~fired_s & np.isfinite(q_hmax) & (c_hi > q_hi) & (c_hmax < q_hmax)
                 & ((c_imax - q_imax) <= max_gap) & (q_amax >= min_depth))
    idx, cols = low.index, low.columns
    return {"bull": pd.DataFrame(bull, index=idx, columns=cols), "bear": pd.DataFrame(bear, index=idx, columns=cols),
            "wave_low": pd.DataFrame(wave_low, index=idx, columns=cols),
            "forming_bull": pd.Series(forming_b, index=cols), "forming_bear": pd.Series(forming_s, index=cols)}


def mc_states(mv: pd.DataFrame, mvs: pd.DataFrame) -> pd.DataFrame:
    """MACD-V lifecycle code per day (index into MC_STATES; -1 = not enough data)."""
    above = mv > mvs
    ranging = (mv.abs() < 50).astype(float).rolling(20, min_periods=20).sum() >= 20
    conds = [ranging, mv < -150, (mv > 150) & above, (mv > 50) & above, (mv >= -150) & above,
             (mv > -50) & ~above, (mv >= -150) & ~above]
    codes = [0, 6, 3, 2, 1, 4, 5]
    out = np.select([cd.to_numpy() for cd in conds], codes, default=-1)
    out = np.where(mv.notna().to_numpy() & mvs.notna().to_numpy(), out, -1)
    return pd.DataFrame(out, index=mv.index, columns=mv.columns)


def _adx_wilder(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, n: int = 14) -> Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """Wilder ADX, +DI and -DI for every name at once (same arithmetic as the LBR desk)."""
    have = h.notna()
    up, dn = h.diff(), -l.diff()
    pdm = pd.DataFrame(np.where((up > dn) & (up > 0), up, 0.0), index=c.index, columns=c.columns).where(have)
    mdm = pd.DataFrame(np.where((dn > up) & (dn > 0), dn, 0.0), index=c.index, columns=c.columns).where(have)
    pc = c.shift(1)
    tr = np.fmax(np.fmax((h - l).to_numpy(float), (h - pc).abs().to_numpy(float)), (l - pc).abs().to_numpy(float))
    tr = pd.DataFrame(tr, index=c.index, columns=c.columns).where(have)
    wil = lambda s: s.ewm(alpha=1.0 / n, adjust=False).mean()
    atr = wil(tr).replace(0, np.nan)
    pdi, mdi = 100 * wil(pdm) / atr, 100 * wil(mdm) / atr
    adx = wil(100 * (pdi - mdi).abs() / (pdi + mdi).replace(0, np.nan))
    return adx, pdi, mdi


def _sh(a: np.ndarray, k: int) -> np.ndarray:
    """Rows shifted down by k (row t holds row t-k), NaN-filled."""
    if k == 0:
        return a
    out = np.full_like(a, np.nan)
    out[k:] = a[:-k]
    return out


def mc_zero_reversals(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, macd: pd.DataFrame, sig: pd.DataFrame,
                      mv: pd.DataFrame, w_macd: pd.DataFrame, look: int = FB_LOOK, stretch: float = FB_STRETCH,
                      bands: Optional[Dict[str, Tuple[float, float]]] = None, adx_max: float = FB_ADX) -> Dict[str, Any]:
    """Joe Rabil's MACD zero-line reversals, as of each day for every name.
    The run: MACD's highest point in the last `look` sessions, at least 4 sessions back, with MACD-V >= `stretch` there.
    The pullback: MACD falls from that peak; yesterday was its lowest point since the peak and today MACD ticks up.
    The trough as a share of the peak sorts it: fly-by (stays above zero, within 35% of the peak), kiss and go (back to
    zero), slight overrun (MACD line a little under zero, signal line still above). Weekly MACD must be above zero."""
    bands = bands or FB_BANDS
    M_, V_ = macd.to_numpy(float), mv.to_numpy(float)
    L_ = l.to_numpy(float)
    adx = _adx_wilder(h, l, c)[0].to_numpy(float)
    trough = _sh(M_, 1)
    pk, pk_v = np.full_like(M_, -np.inf), np.full_like(M_, np.nan)
    pk_age = np.zeros(M_.shape, dtype=np.int16)
    n_fin = np.zeros(M_.shape, dtype=np.int16)
    for k in range(1, look + 1):                          # the run's peak, lags 1..look (ties keep the older one)
        mk = _sh(M_, k)
        n_fin += np.isfinite(mk)
        upd = np.isfinite(mk) & (mk >= pk)
        pk, pk_v, pk_age = np.where(upd, mk, pk), np.where(upd, _sh(V_, k), pk_v), np.where(upd, k, pk_age)
    n_, k_ = M_.shape                                     # the peak must be a swing high, not the window's edge on a slide
    r_ = np.arange(n_)[:, None] - pk_age.astype(np.int64) - 1
    pre = M_[np.clip(r_, 0, n_ - 1), np.arange(k_)[None, :]]
    peak_ok = (r_ >= 0) & np.isfinite(pre) & (pre <= pk)
    low_ok = np.ones(M_.shape, bool)
    adx_min = adx.copy()
    H_ = h.to_numpy(float)
    hh, hh_age = H_.copy(), np.zeros(M_.shape, dtype=np.int16)
    for k in range(1, look + 1):                          # yesterday must be the MACD low since the peak; ADX low; price high
        inside = k <= pk_age
        mk = _sh(M_, k)
        low_ok &= ~(inside & (k >= 2) & np.isfinite(mk) & (mk < trough))
        adx_min = np.where(inside, np.fmin(adx_min, _sh(adx, k)), adx_min)
        hk = _sh(H_, k)
        up_ = inside & np.isfinite(hk) & ~(hk <= hh)      # strictly higher (or today's high missing): ties keep the recent one
        hh, hh_age = np.where(up_, hk, hh), np.where(up_, k, hh_age)
    pull_low = L_.copy()                                  # stop: the pullback's low, counted from the price high after the MACD peak
    for k in range(1, look + 1):
        pull_low = np.where(k <= hh_age, np.fmin(pull_low, _sh(L_, k)), pull_low)
    with np.errstate(invalid="ignore", divide="ignore"):
        ratio = trough / pk
    turn = (M_ > trough) & (trough <= _sh(M_, 2))
    w_up = (w_macd > 0).to_numpy()
    base = (turn & low_ok & peak_ok & (n_fin == look) & (pk_age >= 4) & np.isfinite(pk) & (pk > 0) & (pk_v >= stretch) & np.isfinite(ratio) & w_up)
    sig_t = _sh(sig.to_numpy(float), 1)
    lo, hi = bands["flyby"]
    fly = base & (ratio > lo) & (ratio <= hi)
    lo, hi = bands["kiss"]
    kiss = base & (ratio >= lo) & (ratio <= hi)
    lo, hi = bands["overrun"]
    over = base & (ratio >= lo) & (ratio < hi) & (sig_t > 0)
    fly_adx = fly & (adx_min <= adx_max)
    df = lambda a: pd.DataFrame(a, index=c.index, columns=c.columns)
    return {"flyby": df(fly), "flyby_adx": df(fly_adx), "kiss": df(kiss), "overrun": df(over),
            "pull_low": df(pull_low).astype("float32"),
            "zlr_ratio": df(np.where(base, ratio, np.nan)).astype("float32"),
            "adx_min": df(np.where(base, adx_min, np.nan)).astype("float32")}


def mc_panels(P: Dict[str, pd.DataFrame], setting: str = "12/26/9") -> Dict[str, Any]:
    fast, slow, nsig, kind = MC_SETTINGS.get(setting, MC_SETTINGS["12/26/9"])
    o, h, l, c = (P[k].iloc[-MC_MAX_ROWS:].astype(float) for k in ("open", "high", "low", "close"))
    macd = _mc_ma(c, fast, kind) - _mc_ma(c, slow, kind)
    sig = _mc_ma(macd, nsig, kind)
    hist = macd - sig
    atr = _mc_atr(h, l, c, slow)
    mv = macd / atr.replace(0, np.nan) * 100
    mvs = mv.ewm(span=nsig, adjust=False, min_periods=nsig).mean() if kind == "ema" else mv.rolling(nsig, min_periods=nsig).mean()
    ppo = macd / _mc_ma(c, slow, kind) * 100
    state = mc_states(mv, mvs)
    e13, e26 = c.ewm(span=13, adjust=False).mean(), c.ewm(span=26, adjust=False).mean()
    s50, s200 = c.rolling(50, min_periods=50).mean(), c.rolling(200, min_periods=200).mean()
    h1, h2 = hist.shift(1), hist.shift(2)
    hist_up, hist_dn = hist > h1, hist < h1
    imp = pd.DataFrame(np.where((e13 > e13.shift(1)) & hist_up, 1, np.where((e13 < e13.shift(1)) & hist_dn, -1, 0)),
                       index=c.index, columns=c.columns).where(hist.notna() & h1.notna())
    W = mc_week_live(c, h, l)
    D = mc_divergences(l, h, hist, atr)
    bull_x = (hist > 0) & (h1 <= 0)
    bear_x = (hist < 0) & (h1 >= 0)
    zero_up = (macd > 0) & (macd.shift(1) <= 0)
    hook = (hist < 0) & (hist > h1) & (h1 <= h2)
    w_up = W["macd"] > 0
    w_imp = W["imp"]
    S = {
        "pullback": hook & (mv > -50) & w_up & (w_imp != -1) & w_imp.notna() & (c > s50),
        "zero": zero_up & (c > s200) & W["hist_up"],
        "cross": bull_x & (macd > 0) & w_up & (mv < 150),
        "rally": (mv > 50) & (mv.shift(1) <= 50) & (mv > mvs) & (mv <= 150) & w_up,
        "impulse": (imp.notna() & (imp != -1) & (imp.shift(1) == -1) & (w_imp == 1) & (l.rolling(3).min() <= e13) & (c >= 0.97 * e26)),
        "bulldiv": D["bull"],
    }
    Z = mc_zero_reversals(h, l, c, macd, sig, mv, W["macd"])
    S.update({k_: Z[k_] for k_ in MC_ZLR})
    S = {k_: v.fillna(False).astype(bool) for k_, v in S.items()}
    f32 = lambda x: x.astype("float32")
    D["wave_low"] = f32(D["wave_low"])
    return {"setting": setting, "open": o, "high": h, "low": l, "close": c, "macd": macd, "sig": sig, "hist": hist,
            "mv": f32(mv), "mvs": f32(mvs), "ppo_last": ppo.iloc[-1], "state": state.astype("int8"), "imp": f32(imp),
            "e13": f32(e13), "e26": f32(e26), "s50": f32(s50), "W": W, "D": D, "S": S,
            "pull_low": Z["pull_low"], "zlr_ratio": Z["zlr_ratio"], "zlr_adx": Z["adx_min"],
            "bull_x": bull_x.fillna(False), "bear_x": bear_x.fillna(False), "zero_up": zero_up.fillna(False),
            "beardiv": D["bear"]}


def _mc_streak(x: pd.DataFrame, look: int = 30) -> pd.Series:
    """Signed run of the histogram's direction at the last bar: +3 = rising three sessions in a row."""
    d = np.sign(x.diff().iloc[-look:].to_numpy(float))
    out = np.zeros(d.shape[1])
    for j in range(d.shape[1]):
        col = d[::-1, j]
        if not len(col) or not np.isfinite(col[0]) or col[0] == 0:
            continue
        s = col[0]
        run = 0
        for v in col:
            if v == s:
                run += 1
            else:
                break
        out[j] = s * run
    return pd.Series(out, index=x.columns)


def _mc_plan(M: Dict[str, Any], tk: str, key: str, age: float) -> Tuple[float, float, str]:
    """Trigger (buy stop above the signal day's high), protective stop and whether it has already triggered."""
    if not np.isfinite(age):
        return np.nan, np.nan, ""
    i = len(M["close"]) - 1 - int(age)
    hi = float(M["high"][tk].iloc[i])
    low10 = float(M["low"][tk].iloc[max(0, i - 9):i + 1].min())
    kind = MC_STOP_KIND.get(key)
    stop = (float(M["D"]["wave_low"][tk].iloc[i]) if kind == "wave" else
            float(M["pull_low"][tk].iloc[i]) if kind == "pull" else low10)
    if not np.isfinite(stop) or stop >= hi:
        stop = low10
    after = M["high"][tk].iloc[i + 1:]
    trig = ""
    if len(after) and float(after.max()) > hi:
        trig = f"triggered {str(after.index[int(np.argmax(after.to_numpy() > hi))])[:10]}"
    return hi, stop, trig


def mc_snapshot(M: Dict[str, Any], recent: int = 5) -> pd.DataFrame:
    c = M["close"]
    cols = c.columns
    out = pd.DataFrame(index=cols)
    last = lambda x: x.iloc[-1]
    out["mc_macd"], out["mc_signal"], out["mc_hist"] = last(M["macd"]), last(M["sig"]), last(M["hist"])
    out["mc_ppo"], out["mc_macdv"] = M["ppo_last"], last(M["mv"]).astype(float)
    out["mc_macdv_sig"] = last(M["mvs"]).astype(float)
    out["mc_hist_v"] = out["mc_macdv"] - out["mc_macdv_sig"]
    code = last(M["state"]).astype(int)
    out["mc_state"] = [MC_STATES[k] if k >= 0 else "" for k in code]
    run = _mc_streak(M["hist"])
    out["mc_hist_run"] = run
    out["mc_hist_dir"] = np.where(run > 0, "rising", np.where(run < 0, "falling", "flat"))
    out["mc_zero"] = np.where(out["mc_macd"] > 0, "above", "below")
    imp = last(M["imp"])
    out["mc_imp"] = np.where(imp == 1, "green", np.where(imp == -1, "red", np.where(imp == 0, "blue", "")))
    W = M["W"]
    out["mc_w_macdv"] = last(W["macdv"]).astype(float)
    w_up, w_hist_up, w_imp = last(W["macd"]) > 0, last(W["hist_up"]).astype(bool), last(W["imp"])
    out["mc_w_imp"] = np.where(w_imp == 1, "green", np.where(w_imp == -1, "red", np.where(w_imp == 0, "blue", "")))
    out["mc_tide"] = np.where(last(W["macd"]).isna(), "", np.where(w_up & w_hist_up, "UP",
                              np.where(~w_up & ~w_hist_up, "DOWN", "MIXED")))
    out["mc_ext"] = out["mc_macdv"] > 150
    for k_, sig in list(M["S"].items()) + [("bullx", M["bull_x"]), ("zerox", M["zero_up"]), ("beardiv", M["beardiv"]),
                                           ("bearx", M["bear_x"])]:
        out[f"mc_{k_}_age"] = _age(sig)
    mm = M["macd"].iloc[-FB_LOOK:].to_numpy(float)
    if len(mm) >= 6:                                     # fly-by watchlist: MACD falling toward zero after a stretched run
        pos = np.where(np.isfinite(mm), mm, -np.inf).argmax(axis=0)
        jj = np.arange(mm.shape[1])
        pk, pk_v = mm[pos, jj], M["mv"].iloc[-FB_LOOK:].to_numpy(float)[pos, jj]
        now, prev = mm[-1], mm[-2]
        with np.errstate(invalid="ignore", divide="ignore"):
            ratio = now / pk
        out["mc_zlr_forming"] = ((now < prev) & (pk > 0) & (pk_v >= FB_STRETCH) & (ratio >= -0.05) & (ratio <= 0.5)
                                 & (len(mm) - 1 - pos >= 3) & (last(W["macd"]).to_numpy(float) > 0))
    else:
        out["mc_zlr_forming"] = False
    out["mc_div_forming"] = M["D"]["forming_bull"].reindex(cols).fillna(False).astype(bool)
    out["mc_bdiv_forming"] = M["D"]["forming_bear"].reindex(cols).fillna(False).astype(bool)
    ages = out[[f"mc_{k_}_age" for k_ in MC_SETUPS]].to_numpy(float)
    ages = np.where(ages <= recent, ages, np.nan)
    best = np.full(len(out), "", dtype=object)
    best_age = np.full(len(out), np.nan)
    keys = list(MC_SETUPS)
    for j in range(len(out)):
        row = ages[j]
        if np.isfinite(row).any():
            kk = int(np.nanargmin(row))         # freshest; ties go to the earlier key in MC_SETUPS
            best[j], best_age[j] = keys[kk], row[kk]
    out["mc_setup_key"] = best
    out["mc_setup"] = [MC_SETUPS.get(k_, "") for k_ in best]
    out["mc_setup_age"] = best_age
    trig, stop, done = [], [], []
    for tk, k_, a_ in zip(out.index, best, best_age):
        t_, s_, d_ = _mc_plan(M, tk, k_, a_) if k_ else (np.nan, np.nan, "")
        trig.append(t_), stop.append(s_), done.append(d_)
    out["mc_trigger"], out["mc_stop"], out["mc_triggered"] = trig, stop, done
    out["mc_risk_pct"] = (out["mc_trigger"] - out["mc_stop"]) / out["mc_trigger"] * 100
    return out


def mc_block(ab: Dict[str, Any], setting: str) -> Dict[str, Any]:
    P = ab["P"]
    key = ("mc_block", tuple(P["close"].columns), str(ab["asof"]), setting)

    def run():
        M = mc_panels(P, setting)
        return {"M": M, "snap": mc_snapshot(M)}
    return memo(key, run, capacity=300)


def mc_posture(clim: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    """Posture and entry mode from the War Room files (as the Grader reads them), else the lab's climate suggestion."""
    out = {"posture": None, "mode": "", "src": ""}
    try:
        d = Path((st.session_state.get("gr_vals") or {}).get("wrdir") or GR_WARROOM_DIR)
        m, _ = gr_warroom(d)
        if m.get("posture"):
            return {"posture": str(m["posture"]), "mode": str(m.get("entry_mode") or ""), "src": "War Room"}
    except Exception:
        pass
    try:
        p, why = gr_posture_from_climate(clim)
        if p:
            out.update(posture=p, src="climate (suggested)")
    except Exception:
        pass
    return out


def mc_favored(post: Dict[str, Any]) -> Tuple[List[str], str]:
    p = post.get("posture")
    if not p or p not in MC_REGIME:
        return list(MC_SETUPS), "No posture available: every setup is shown. Add the War Room files for a regime read."
    keys, why = MC_REGIME[p]
    mode = post.get("mode") or ""
    if mode in MC_MODE:
        mk, mwhy = MC_MODE[mode]
        keys = [k_ for k_ in keys if k_ in mk]
        why = f"{why} {mwhy}"
    return keys, why


def mc_sentence(tk: str, r: pd.Series) -> str:
    f = lambda x, fmt="+.0f": "—" if not np.isfinite(_n(x, np.nan)) else format(float(x), fmt)
    tide = {"UP": "weekly tide UP", "DOWN": "weekly tide DOWN", "MIXED": "weekly tide mixed"}.get(str(r.get("mc_tide")), "weekly tide —")
    bits = [f"{tk}: {tide} (weekly MACD-V {f(r.get('mc_w_macdv'))}, weekly impulse {r.get('mc_w_imp') or '—'})",
            f"daily MACD-V {f(r.get('mc_macdv'))}, {r.get('mc_state') or '—'}",
            f"histogram {r.get('mc_hist_dir')} {abs(int(_n(r.get('mc_hist_run'), 0)))} session(s), impulse {r.get('mc_imp') or '—'}"]
    s = "; ".join(bits) + "."
    k_ = r.get("mc_setup_key") or ""
    if k_:
        a_ = int(_n(r.get("mc_setup_age"), 0))
        when = "today" if a_ == 0 else f"{a_} session{'s' if a_ > 1 else ''} ago"
        s += f" {MC_SETUPS[k_]} {when}."
        if np.isfinite(_n(r.get("mc_trigger"), np.nan)):
            adr = _n(r.get("adr20"), np.nan)
            in_adr = f" = {r['mc_risk_pct'] / adr:.1f} ADR" if np.isfinite(adr) and adr > 0 else ""
            s += (f" Plan: buy stop above {r['mc_trigger']:.2f} (signal-day high), stop under {r['mc_stop']:.2f} "
                  f"({MC_STOP_TXT.get(MC_STOP_KIND[k_], '10-day low')}), risk {r['mc_risk_pct']:.1f}%{in_adr}.")
            if np.isfinite(adr) and adr > 0 and r["mc_risk_pct"] > 1.5 * adr:
                s += " Wide: wait for a tighter hook or size down."
            if r.get("mc_triggered"):
                s += f" Already {r['mc_triggered']}: don't chase a stale trigger."
    elif bool(r.get("mc_zlr_forming")):
        s += (" Zero-line pullback forming: MACD is falling back toward zero after a stretched run. A fly-by is the "
              "first uptick while MACD is still above zero.")
    elif bool(r.get("mc_div_forming")):
        s += " Bullish divergence forming: waiting for the histogram's first uptick."
    else:
        s += " No bullish MACD setup in the last 5 sessions."
    warn = []
    if bool(r.get("mc_ext")):
        warn.append("MACD-V above +150 (stretched: trim or tighten, don't add)")
    if _n(r.get("mc_beardiv_age"), 99) <= 10:
        warn.append(f"bearish divergence {int(r['mc_beardiv_age'])} session(s) ago")
    elif bool(r.get("mc_bdiv_forming")):
        warn.append("bearish divergence forming")
    if r.get("mc_imp") == "red":
        warn.append("daily impulse red (no new longs)")
    if r.get("mc_tide") == "DOWN":
        warn.append("weekly tide down")
    if warn:
        s += " Exit cues: " + "; ".join(warn) + "."
    return s


def mc_event_study(M: Dict[str, Any], horizons=(5, 10, 21), warmup: int = 260, cooldown: int = 10) -> pd.DataFrame:
    """Forward return from the next open to the close h sessions later after each setup's first day, against every
    day and every uptrend day (close above a rising 50-day) on the same names. Same method as the TraderLion test."""
    c, o = M["close"], M["open"]
    s50 = M["s50"]
    uptrend = (c > s50) & (s50 > s50.shift(5))
    valid = pd.DataFrame(False, index=c.index, columns=c.columns)
    valid.iloc[warmup:] = True
    sigs = {**{MC_SETUPS[k_]: v for k_, v in M["S"].items()},
            "Bull cross, no filters (reference)": M["bull_x"], "Zero-line cross, no filters (reference)": M["zero_up"],
            "Bearish divergence (exit cue)": M["beardiv"]}
    rows = []
    for h in horizons:
        fwd = c.shift(-h) / o.shift(-1) - 1
        base_all = fwd.where(valid).stack().dropna()
        base_up = fwd.where(valid & uptrend).stack().dropna()
        for name, sig in sigs.items():
            sig = sig.astype(bool)
            recent = sig.astype(int).rolling(cooldown, min_periods=1).sum().shift(1).fillna(0)
            ev = sig & (recent == 0) & valid
            x = fwd.where(ev).stack().dropna()
            if len(x) < 5:
                rows.append({"setup": name, "horizon": h, "events": len(x)})
                continue
            lo, hi = wilson(int((x > 0).sum()), len(x))
            se = math.sqrt(x.var() / len(x) + base_up.var() / len(base_up))
            rows.append({"setup": name, "horizon": h, "events": len(x), "mean": float(x.mean()),
                         "median": float(x.median()), "hit": float((x > 0).mean()), "hit_lo": lo, "hit_hi": hi,
                         "base_all_mean": float(base_all.mean()), "base_up_mean": float(base_up.mean()),
                         "base_up_hit": float((base_up > 0).mean()), "excess_vs_up": float(x.mean() - base_up.mean()),
                         "t_vs_up": float((x.mean() - base_up.mean()) / se) if se > 0 else np.nan})
    return pd.DataFrame(rows)


