def lg_time_limits(prm: Dict[str, Any]) -> Dict[str, int]:
    """Time limit per family in sessions (0 = none). Settings saved before the time limit became optional (no
    'tl_mode') keep the old rule: the edge window doubles as the time limit for every setup."""
    fams = list(LG_TL_SEED)
    mode = prm.get("tl_mode")
    if mode is None:
        return {f: int(prm["horizon"]) for f in fams}
    if mode == "off":
        return {f: 0 for f in fams}
    if mode == "all":
        return {f: int(prm.get("tl", prm["horizon"])) for f in fams}
    per = dict(prm.get("tl_fam") or ())
    return {f: int(per.get(f, LG_TL_SEED[f])) for f in fams}


def lg_exit_rules(prm: Dict[str, Any]) -> Dict[str, str]:
    """'target' or 'trail' per family. Settings saved before exits became a choice keep the fixed R target."""
    mode = prm.get("exit_mode")
    if mode in (None, "target"):
        return {f: "target" for f in LG_EXIT_SEED}
    if mode == "trail":
        return {f: "trail" for f in LG_EXIT_SEED}
    per = dict(prm.get("exit_fam") or ())
    return {f: str(per.get(f, LG_EXIT_SEED[f])) for f in LG_EXIT_SEED}


def lg_trail_txt(prm: Dict[str, Any]) -> str:
    kind = prm.get("trail", "chandelier")
    if kind == "ma":
        return f"close under the {int(prm.get('trail_ma', 21))}-day average"
    return f"{'highest high' if kind == 'chandelier' else 'highest close'} - {float(prm.get('trail_k', 3.0)):g} ATR"


def lg_rules_txt(prm: Dict[str, Any]) -> str:
    """'2R / no time limit', 'Trail / 10d', 'Exits per family / per family' for the Rules tiles."""
    ex = prm.get("exit_mode")
    ex_txt = ("Trailing stop" if ex == "trail" else "Exits per family" if ex == "family" else f"{float(prm['tgt']):g}R")
    mode = prm.get("tl_mode")
    if mode == "off":
        tl = "no time limit"
    elif mode == "family":
        tl = "time limit per family"
    else:
        tl = f"{int(prm.get('tl', prm['horizon']))}d"
    return f"{ex_txt} / {tl}"


def lg_first(sig: pd.DataFrame, cooldown: int) -> pd.DataFrame:
    """First day of a signal, then no new event for the same name until `cooldown` sessions pass without one."""
    s = sig.fillna(False).astype(bool)
    first = s & ~s.shift(1, fill_value=False)
    if cooldown > 1:
        prior = first.astype(np.int8).rolling(cooldown, min_periods=1).sum().shift(1).fillna(0)
        first = first & (prior == 0)
    return first


def lg_rs8_signals(c: pd.DataFrame, h: pd.DataFrame, spy: pd.Series, near_band: float = 4.5,
                   pocket: Tuple[float, float] = (-3.0, 6.0)) -> Dict[str, pd.DataFrame]:
    """The RS 8-week tab's setups as of every day (no look-ahead: the forming week uses that day's close),
    matching rs8_one on the last day."""
    idx = c.index
    sp = spy.reindex(idx).ffill()
    rs = c.div(sp, axis=0)
    nh252 = rs >= rs.rolling(252, min_periods=200).max() * 0.99999
    wid = idx.to_period("W-FRI")

    def asof(x):
        return x.reindex(wid).set_axis(idx)

    rs_w = rs.groupby(wid).last()
    nh_forming = rs >= asof(rs_w.shift(1).rolling(52, min_periods=52).max())
    wk_nh = (rs_w >= rs_w.rolling(53, min_periods=53).max()).astype(float)
    nh_prevwk = (asof(wk_nh.shift(1)) == 1.0) & (idx.weekday != 4)[:, None]   # on a Friday the week itself is complete
    wk_c = c.groupby(wid).last()
    prev_e8 = asof(wk_c.ewm(span=8, adjust=False).mean().shift(1))
    a = 2.0 / 9.0
    e8 = a * c + (1 - a) * prev_e8
    ext8 = (c / e8 - 1) * 100
    in_pocket = (ext8 >= pocket[0]) & (ext8 <= pocket[1]) & (e8 > prev_e8)
    s10, s20, s50 = (c.rolling(n, min_periods=n).mean() for n in (10, 20, 50))
    dist = np.minimum(np.minimum(((c / s10 - 1) * 100).abs().to_numpy(float), ((c / s20 - 1) * 100).abs().to_numpy(float)),
                      ((c / s50 - 1) * 100).abs().to_numpy(float))
    near = pd.DataFrame(dist <= near_band, index=idx, columns=c.columns)
    trig = (c > h.shift(1)) | (c > c.shift(1))
    price_nh = c >= c.rolling(252, min_periods=252).max() * 0.99999
    return {"rs8:pocket": in_pocket & (nh252 | nh_forming | nh_prevwk), "rs8:box": near & (s10 > s20) & trig,
            "rs8:rsnh_brk": nh252 & price_nh, "_e8": e8}


def _lg_age_extreme(x: pd.DataFrame, n: int, lag0: int, want_max: bool) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """Over the window x.shift(lag0) .. x.shift(lag0+n-1): the extreme and how many sessions ago it was
    (ties go to the oldest, like np.argmax on the window). NaN unless the window is full."""
    best = x.shift(lag0)
    age = pd.DataFrame(np.where(best.notna(), float(lag0), np.nan), index=x.index, columns=x.columns)
    for k in range(lag0 + 1, lag0 + n):
        xk = x.shift(k)
        upd = (xk >= best) if want_max else (xk <= best)
        best = best.where(~upd, xk)
        age = age.where(~upd, float(k))
    full = x.shift(lag0).rolling(n, min_periods=n).count() == n
    return best.where(full), age.where(full)


def lg_lbr_signals(o: pd.DataFrame, h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame) -> Dict[str, pd.DataFrame]:
    """Long side of the LBR desk's setups for every name at once (same rules as lbr_frame / lbr_events)."""
    have = h.notna()
    up, dn = h.diff(), -l.diff()
    pdm = pd.DataFrame(np.where((up > dn) & (up > 0), up, 0.0), index=c.index, columns=c.columns).where(have)
    mdm = pd.DataFrame(np.where((dn > up) & (dn > 0), dn, 0.0), index=c.index, columns=c.columns).where(have)
    pc = c.shift(1)
    tr = np.fmax(np.fmax((h - l).to_numpy(float), (h - pc).abs().to_numpy(float)), (l - pc).abs().to_numpy(float))
    tr = pd.DataFrame(tr, index=c.index, columns=c.columns).where(have)
    wil = lambda s: s.ewm(alpha=1.0 / 14, adjust=False).mean()
    atr = wil(tr)
    pdi = 100 * wil(pdm) / atr.replace(0, np.nan)
    mdi = 100 * wil(mdm) / atr.replace(0, np.nan)
    dx = 100 * (pdi - mdi).abs() / (pdi + mdi).replace(0, np.nan)
    adx = wil(dx)
    adx_up = adx > adx.shift()
    ema20 = c.ewm(span=20, adjust=False).mean()
    touch = ((l <= ema20) & (ema20 <= h)) | ((c - ema20).abs() <= 0.25 * atr)
    trend_up = (adx >= 30) & adx_up & (pdi > mdi) & (c > ema20)
    l20, l20_age = _lg_age_extreme(l, 20, 1, want_max=False)
    rng = (h - l).replace(0, np.nan)
    body, clv = (c - o).abs() / rng * 100, (c - l) / rng
    sma5 = c.rolling(5).mean()
    strong_up = (adx >= 32) & adx_up & (c > ema20)
    # confirmed fractal swings (wing 2): a swing at j is known at j+2
    sh = (h == h.rolling(5, center=True).max()) & (h > h.shift(1)) & (h > h.shift(-1))
    sl = (l == l.rolling(5, center=True).min()) & (l < l.shift(1)) & (l < l.shift(-1))
    pos = np.arange(len(c), dtype=float)[:, None]
    last_sh = pd.DataFrame(np.where(sh.to_numpy(), pos, np.nan), index=c.index, columns=c.columns).ffill().shift(2)
    last_sl = pd.DataFrame(np.where(sl.to_numpy(), pos, np.nan), index=c.index, columns=c.columns).ffill().shift(2)
    age_hi = pd.DataFrame(pos - last_sh.to_numpy(), index=c.index, columns=c.columns)
    age_lo = pd.DataFrame(pos - last_sl.to_numpy(), index=c.index, columns=c.columns)
    buy_age = pd.DataFrame(np.where(strong_up, age_hi.isin([1, 2]), age_hi.isin([2, 3])), index=c.index, columns=c.columns)
    taylor = buy_age & (age_hi <= age_lo.fillna(99))
    _, hi5 = _lg_age_extreme(h, 5, 0, want_max=True)
    c_at_hi = pd.DataFrame(np.nan, index=c.index, columns=c.columns)
    for k in range(5):
        c_at_hi = c_at_hi.where(hi5 != k, c.shift(k))
    dip = hi5.isin([2, 3, 4]) & (c < c_at_hi)
    return {"lbr:holy_grail": trend_up & touch,
            "lbr:turtle_soup": (l < l20) & (c > l20) & (l20_age >= 4),
            "lbr:eighty_twenty": (body.shift() >= 80) & (clv.shift() <= 0.20) & (l < l.shift()) & (c > l.shift()),
            "lbr:sma5_flip": (c.shift() <= sma5.shift()) & (c > sma5),
            "lbr:taylor": taylor, "lbr:wizard_rhythm": dip}


def lg_label(O: np.ndarray, Hh: np.ndarray, L: np.ndarray, C: np.ndarray, ATR: np.ndarray, ii: np.ndarray,
             jj: np.ndarray, lvl: np.ndarray, mode: str = "next_open", win: int = 1, tgt_r: Any = 2.0,
             horizon: Any = 10, cap_atr: float = 3.0, floor_atr: float = 0.5, cost_bp: Any = 10.0,
             trail: Any = False, trail_kind: str = "chandelier", trail_k: float = 3.0, ma: Optional[np.ndarray] = None,
             mark_open: bool = False, trim_frac: Any = 0.0, trim_stop_r: float = 0.0, trail_from: str = "entry",
             ma_closes: int = 1, fail_n: int = 0, fail_r: float = 0.0, be_r: float = 0.0,
             runner_horizon: Any = 0, fail_once: bool = False,
             exit_sig: Optional[np.ndarray] = None) -> Dict[str, np.ndarray]:
    """Triple-barrier label for each event (row ii, column jj, protective stop level lvl), all events at once.
    Arrays are dates x names. Returns per-event status (LG_STATUS), entry/stop/target/exit, outcome
    (LG_OUTCOME), R multiple after round-trip costs, % return, MFE/MAE in R and sessions held.
    tgt_r, horizon and trail may be one value or one per event: a target of inf or 0 means none, a horizon of 0 means
    no time limit. A trailing stop only ratchets up from the initial stop, from the close of each bar for the next
    one: 'chandelier' = highest high since entry - trail_k x ATR, 'atr_close' = highest close - trail_k x ATR, 'ma' =
    exit at the close when it ends under `ma` (the moving average panel). With no time limit, a trade still open when
    the data ends is marked at the last close (outcome 'open') when mark_open, else left unresolved (status 3).
    Trim and trail (all off by default, which leaves every result above unchanged):
    * trim_frac (0-1, one value or one per event): reaching the target sells that share instead of the whole trade.
      The rest runs on with no target; its stop moves up to entry + trim_stop_r x R (0 = breakeven, nan = leave it)
      and its time limit becomes runner_horizon (0 = none), so winners are held longer.
    * trail_from='trim': the trailing stop or moving-average exit applies only to what is left after the trim.
    * ma_closes: closes in a row under the average before the average exit fires (TraderLion's two-close rule = 2).
    * fail_n, fail_r: a trade not yet trimmed that closes under entry + fail_r x R at session fail_n or later is cut
      at that close (outcome 'cut: not working'), so losers are held shorter. fail_once: check session fail_n only.
    * be_r: before the trim, a high of entry + be_r x R moves the stop to breakeven (0 = off).
    * exit_sig: a dates x names panel of exit-signal codes (0 = none; see sim_sig_panel). Where the trailing rule is
      live, a close on a signal day ends the trade at that close (outcome 'exit signal'); 'sig_code' says which.
    A raised stop applies from the next bar. R and the return blend the trimmed share (at the target, or the open if
    it gapped over) with the rest (at its exit)."""
    n = O.shape[0]
    m = len(ii)
    ii, jj = np.asarray(ii, np.int64), np.asarray(jj, np.int64)
    status = np.zeros(m, np.int8)
    e = np.full(m, -1, np.int64)
    entry = np.full(m, np.nan)
    full_bar = np.ones(m, bool)                       # the whole entry bar is in the trade
    post = np.zeros(m, bool)                          # bought before the first bar opened (close mode): its open can gap
    stop0 = np.asarray(lvl, float)
    atr = ATR[ii, jj].astype(float)
    if mode == "close":                               # bought at the signal day's close; the trade's first bar is the next
        d = ii + 1
        ok = d < n
        px = C[ii, jj].astype(float)
        good = ok & np.isfinite(px) & (px > 0)
        e = np.where(good, d, -1)
        entry = np.where(good, px, np.nan)
        post[:] = True
        status[~ok] = 3
        status[ok & ~good] = 4
    elif mode == "next_open":
        d = ii + 1
        ok = d < n
        px = O[np.minimum(d, n - 1), jj].astype(float)
        good = ok & np.isfinite(px) & (px > 0)
        e = np.where(good, d, -1)
        entry = np.where(good, px, np.nan)
        status[~ok] = 3
        status[ok & ~good] = 4
    else:
        trig = Hh[ii, jj].astype(float)
        alive = np.isfinite(trig)
        status[~alive] = 4
        full_bar[:] = False
        for w in range(1, int(win) + 1):
            d = ii + w
            ok = alive & (e < 0) & (d < n)
            dc = np.minimum(d, n - 1)
            oo, hh, cc = O[dc, jj].astype(float), Hh[dc, jj].astype(float), C[dc, jj].astype(float)
            fill = ok & np.isfinite(hh) & (hh >= trig)
            gap = np.isfinite(oo) & (oo >= trig)
            e = np.where(fill, d, e)
            entry = np.where(fill, np.where(gap, oo, trig), entry)
            full_bar = np.where(fill, gap, full_bar)
            alive = alive & ~(ok & ~fill & np.isfinite(cc) & (cc < stop0))   # closed under the stop: cancel the order
        unfilled = (e < 0) & (status == 0)
        status[unfilled & (ii + int(win) >= n)] = 3
        status[unfilled & (ii + int(win) < n)] = 1
    R = entry - stop0
    status[(status == 0) & (e >= 0) & np.isfinite(R) & (R <= 0)] = 2     # opened at or under the stop: no trade
    capR, floorR = cap_atr * atr, floor_atr * atr
    capped = (status == 0) & np.isfinite(capR) & (R > capR)
    R = np.where(capped, capR, R)
    R = np.where((R > 0) & np.isfinite(floorR) & (R < floorR), floorR, R)
    status[(status == 0) & ~(np.isfinite(R) & (R > 0))] = 4
    tg_r = np.broadcast_to(np.asarray(tgt_r, float), (m,)).astype(float)
    tg_r = np.where(np.isfinite(tg_r) & (tg_r > 0), tg_r, np.inf)        # 0 or inf = no target
    stop, tgt = entry - R, entry + tg_r * R
    stop_init, tgt0 = stop.copy(), tgt.copy()
    tf = np.broadcast_to(np.asarray(trim_frac, float), (m,)).astype(float)
    tf = np.clip(np.where(np.isfinite(tf), tf, 0.0), 0.0, 1.0)
    scale = (tf > 0) & (tf < 1)                                         # 1 = the whole trade at the target, as before
    trimmed, trim_px, trim_i = np.zeros(m, bool), np.full(m, np.nan), np.full(m, -1, np.int64)
    hz_run = np.broadcast_to(np.asarray(runner_horizon, float), (m,)).astype(float)
    hz_run = np.where(np.isfinite(hz_run) & (hz_run > 0), hz_run, np.inf)
    from_trim = str(trail_from) == "trim"
    under = np.zeros(m, np.int64)                                       # closes in a row under the average
    sig_code = np.zeros(m, np.int8)                                     # which exit signal ended the trade
    ma_need = max(1, int(ma_closes))
    tr_on = np.broadcast_to(np.asarray(trail, bool), (m,)).copy()
    hi_run = np.full(m, -np.inf)                                         # highest high (or close) since entry
    hz = np.broadcast_to(np.asarray(horizon, float), (m,)).astype(float)
    hz = np.where(np.isfinite(hz) & (hz > 0), hz, np.inf)                # 0 or less = no time limit
    status[(status == 0) & np.isfinite(hz) & (e + hz - 1 >= n)] = 3       # the full window isn't in the data yet
    live = status == 0
    exit_px, exit_i = np.full(m, np.nan), np.full(m, -1, np.int64)
    outcome = np.full(m, -1, np.int8)
    mfe, mae = np.full(m, -np.inf), np.full(m, np.inf)
    last_c, last_i = np.full(m, np.nan), np.full(m, -1, np.int64)
    open_ = live.copy()
    ran_out = np.zeros(m, bool)                       # no time limit and no exit before the data ends: unresolved
    ec = np.where(e >= 0, e, 0)
    k = 0
    while True:                                       # one bar at a time, only over the trades still open
        idx = np.flatnonzero(open_)
        if not len(idx):
            break
        d = ec[idx] + k
        past = d >= n
        if past.any():
            ran_out[idx[past]] = True
            open_[idx[past]] = False
            idx, d = idx[~past], d[~past]
            if not len(idx):
                break
        j_ = jj[idx]
        oo, hh, ll, cc = (A[d, j_].astype(float) for A in (O, Hh, L, C))
        st_, tg_ = stop[idx], tgt[idx]
        act = np.isfinite(cc) & np.isfinite(hh) & np.isfinite(ll)
        if k == 0:
            fb, ps = full_bar[idx], post[idx]
            lo_hit = np.where(fb | ps, ll <= st_, cc <= st_)
            g_dn = ps & np.isfinite(oo) & (oo <= st_)            # close mode: the first bar's open can gap either way
            g_up = ps & np.isfinite(oo) & (oo >= tg_)
            lo_ref = np.where(fb | ps, ll, np.fmin(entry[idx], cc))
        else:
            lo_hit = ll <= st_
            g_dn, g_up = np.isfinite(oo) & (oo <= st_), np.isfinite(oo) & (oo >= tg_)
            lo_ref = ll
        hi_hit = hh >= tg_
        mfe[idx] = np.where(act, np.fmax(mfe[idx], hh), mfe[idx])
        mae[idx] = np.where(act, np.fmin(mae[idx], lo_ref), mae[idx])
        x_gd = act & g_dn
        x_gu = act & ~g_dn & g_up
        x_st = act & ~g_dn & ~g_up & lo_hit                 # both barriers in one bar: assume the stop came first
        x_tg = act & ~g_dn & ~g_up & ~lo_hit & hi_hit
        sc_ = scale[idx]
        was_trim = trimmed[idx]
        gap_trim = x_gu & sc_                               # opened over the target: the trim fills at the open
        trim_now = (x_gu | x_tg) & sc_                      # sell the trim share; the rest keeps going
        x_gu, x_tg = x_gu & ~sc_, x_tg & ~sc_
        trailed = st_ > stop_init[idx] + 1e-12                              # the stop had already moved up
        trail_ok = tr_on[idx] & (was_trim | (not from_trim))                # the trailing rule is live on this bar
        x_ma = np.zeros(len(idx), bool)
        if trail_kind == "ma" and ma is not None:
            mv = ma[d, j_].astype(float)
            cnt = np.where(act & trail_ok & np.isfinite(mv) & (cc < mv), under[idx] + 1, 0)
            under[idx] = cnt
            x_ma = act & trail_ok & ~(x_gd | x_gu | x_st | x_tg | trim_now) & (cnt >= ma_need)
        x_sg = np.zeros(len(idx), bool)
        if exit_sig is not None:                            # a signal day (distribution, climax): out at the close
            sv = exit_sig[d, j_]
            x_sg = act & trail_ok & ~(x_gd | x_gu | x_st | x_tg | trim_now) & (sv > 0)
            x_ma = x_ma & ~x_sg
            sig_code[idx[x_sg]] = sv[x_sg]
        x_fail = np.zeros(len(idx), bool)
        if int(fail_n) > 0:                                 # not working by session fail_n: cut at the close
            on_day = (k + 1 == int(fail_n)) if fail_once else (k + 1 >= int(fail_n))
            x_fail = (act & ~(x_gd | x_gu | x_st | x_tg | x_ma | x_sg | trim_now) & ~was_trim & on_day
                      & (cc < entry[idx] + float(fail_r) * R[idx]))
        done = x_gd | x_gu | x_st | x_tg | x_ma | x_sg | x_fail
        px_ = np.where(x_gd | x_gu, oo, np.where(x_st, st_, np.where(x_tg, tg_, np.where(x_ma | x_sg | x_fail, cc, np.nan))))
        exit_px[idx[done]] = px_[done]
        exit_i[idx[done]] = d[done]
        oc_ = np.where(x_gd | x_st, np.where(trailed, 3, 1),
                       np.where(x_ma, 3, np.where(x_sg, 6, np.where(x_fail, 5, 0))))
        outcome[idx[done]] = oc_[done]
        last_c[idx[act]], last_i[idx[act]] = cc[act], d[act]
        open_[idx[done]] = False
        if trim_now.any():                                  # record the trim; raise the stop and lift the limits
            t_ = idx[trim_now]
            trimmed[t_] = True
            trim_px[t_] = np.where(gap_trim[trim_now], oo[trim_now], tg_[trim_now])
            trim_i[t_] = d[trim_now]
            tgt[t_] = np.inf
            hz[t_] = hz_run[t_]
            if np.isfinite(float(trim_stop_r)):
                stop[t_] = np.fmax(stop[t_], entry[t_] + float(trim_stop_r) * R[t_])
        if float(be_r) > 0:                                 # follow-through before the trim: stop to breakeven
            b_ = act & ~done & ~trimmed[idx] & (hh >= entry[idx] + float(be_r) * R[idx])
            if b_.any():
                stop[idx[b_]] = np.fmax(stop[idx[b_]], entry[idx[b_]])
        up_ = act & ~done & tr_on[idx]                                      # ratchet the trailing stop for the next bar
        if up_.any() and trail_kind in ("chandelier", "atr_close"):
            u = idx[up_]
            ref = hh[up_] if trail_kind == "chandelier" else cc[up_]
            hi_run[u] = np.fmax(hi_run[u], ref)
            lv_ = hi_run[u] - float(trail_k) * ATR[d[up_], j_[up_]].astype(float)
            live_ = trimmed[u] | (not from_trim)
            stop[u] = np.where(np.isfinite(lv_) & live_, np.fmax(stop[u], lv_), stop[u])
        tl = open_[idx] & (k + 1 >= hz[idx])                # the time limit ends the trade at this bar's close
        if tl.any():
            t_ = idx[tl]
            ok_ = np.isfinite(last_c[t_])
            exit_px[t_[ok_]], exit_i[t_[ok_]] = last_c[t_[ok_]], last_i[t_[ok_]]
            outcome[t_[ok_]] = 2
            status[t_[~ok_]] = 4
            open_[t_] = False
        k += 1
    if mark_open:                                     # still open when the data ends: marked at the last close
        mk = ran_out & np.isfinite(last_c)
        exit_px[mk], exit_i[mk], outcome[mk] = last_c[mk], last_i[mk], 4
        status[ran_out & ~mk] = 3
    else:
        status[ran_out] = 3
    traded = status == 0
    cost = 2.0 * np.broadcast_to(np.asarray(cost_bp, float), (m,)).astype(float) / 1e4   # one value or one per event
    tm = traded & trimmed
    f_ = np.where(tm, tf, 0.0)
    with np.errstate(invalid="ignore", divide="ignore"):
        gross = np.where(tm, f_ * (trim_px - entry) + (1 - f_) * (exit_px - entry), exit_px - entry)
        r = np.where(traded, np.where(tm, gross, exit_px - entry) / R - cost * entry / R, np.nan)
        ret = np.where(traded, np.where(tm, gross / entry, exit_px / entry - 1) - cost, np.nan)
        mfe_r = np.where(traded, (mfe - entry) / R, np.nan)
        mae_r = np.where(traded, (mae - entry) / R, np.nan)
    return {"status": status, "e": e, "entry": entry, "stop": np.where(traded, stop_init, np.nan),
            "target": np.where(traded & np.isfinite(tgt0), tgt0, np.nan), "exit": exit_px, "exit_i": exit_i,
            "outcome": np.where(traded, outcome, -1).astype(np.int8), "risk": np.where(traded, R, np.nan),
            "r": r, "ret": ret, "mfe_r": mfe_r, "mae_r": mae_r,
            "hold": np.where(traded, exit_i - e + 1, -1), "capped": capped & traded,
            "trimmed": tm, "trim_px": np.where(tm, trim_px, np.nan), "trim_i": np.where(tm, trim_i, -1),
            "sig_code": np.where(traded & (outcome == 6), sig_code, 0).astype(np.int8)}


def lg_oversold(o, h, l, c) -> Dict[str, pd.DataFrame]:
    """Short-term stretch readings: IBS = (close - low) / (high - low), the close's place in the day's range (NaN on a
    zero-range day); RSI(2), Wilder's smoothing (alpha 1/2), as Connors uses it."""
    with np.errstate(invalid="ignore", divide="ignore"):
        ibs = (c - l) / (h - l).where(h > l)
        d = c.diff()
        up_ = d.clip(lower=0).ewm(alpha=0.5, adjust=False, min_periods=2).mean()
        dn_ = (-d).clip(lower=0).ewm(alpha=0.5, adjust=False, min_periods=2).mean()
        rsi2 = 100 - 100 / (1 + up_ / dn_.where(dn_ > 0))
        rsi2 = rsi2.where(dn_ > 0, 100.0).where(d.notna() & up_.notna())
    return {"ibs": ibs, "rsi2": rsi2}


def zg_signals(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, v: pd.DataFrame, s50: Optional[pd.DataFrame] = None,
               atr: Optional[pd.DataFrame] = None) -> Dict[str, pd.DataFrame]:
    """Zanger's base breakout, from each day's close. The base is the ZG_BASE sessions before today: its high is the
    line, and it qualifies when it is no deeper than ZG_DEPTH (high to low), its high is within 15% of the prior
    52-week high, and the name closes over a 50-day that is higher than 10 sessions ago. A breakout is a close over the
    line and no more than ZG_CHASE past it. 'vol' = on ZG_VOL x the prior 30 sessions' average volume or more;
    'quiet' = the same breakout on less. Also the line, the volume ratio and the stop (the line less 1 ATR)."""
    s50 = c.rolling(50, min_periods=50).mean() if s50 is None else s50
    atr = _mc_atr(h, l, c, 14) if atr is None else atr
    line = h.rolling(ZG_BASE, min_periods=ZG_BASE).max().shift(1)
    floor = l.rolling(ZG_BASE, min_periods=ZG_BASE).min().shift(1)
    with np.errstate(invalid="ignore", divide="ignore"):
        tight = (line / floor - 1) <= ZG_DEPTH
        near_hi = line >= h.rolling(252, min_periods=120).max().shift(1) * 0.85
        vr = v / v.rolling(30, min_periods=20).mean().shift(1)
    up = (c > s50) & (s50 > s50.shift(10))
    brk = (c > line) & (c <= line * (1 + ZG_CHASE)) & tight & near_hi & up
    return {"vol": brk & (vr >= ZG_VOL), "quiet": brk & (vr < ZG_VOL), "line": line, "vr": vr, "stop": line - atr}


# ══════════════════════════════════════════════════════════════════
#  ANCHORED VWAP  (Stocks > VWAP; the Setup ledger's VWAP family; a Brief > Setups scan; Screener columns)
#  Brian Shannon (*Maximum Trading Gains with Anchored VWAP*, 2023; *Technical Analysis Using Multiple Timeframes*,
#  2008): a VWAP started at a meaningful event is the average price paid by everyone who bought since then. Over it,
#  that whole group is in profit and has little reason to sell; under it, they are under water and supply sits
#  overhead. Anchored lines are read the way the lab reads the 8-week EMA: where price sits against them, and what
#  happens when it crosses or tests them. Three anchors, each found point-in-time from data up to that day:
#    the high:  the last session that made a new 52-week high, over every high of the prior 252 sessions (its
#               buyers are the overhead supply in a pullback or base);
#    the low:   the last session that made a new 63-day low, under every low of the prior 63 (the swing low under the
#               move: support in an uptrend). Strict, so a flat base doesn't move the anchor every day.
#    the event: the last gap up of AW_EV_GAP+ on AW_EV_VOL x the 50-day volume, within AW_EV_LB sessions (an
#               earnings or news day: Shannon's and Stockbee's episodic pivot anchor).
#  Each bar's price is its own VWAP on Massive and demo bars and the typical price (H+L+C)/3 on Yahoo bars, so the
#  lines are close to, not exactly, a charting package's anchored VWAP from that day's open.
#  Setups (all long): the reclaim of the line from the high, a pullback that holds the line from the low or the
#  event, and the pinch (the lines from the high and the low converge in a base, then price closes over both).
#  The anchors are this lab's testable stand-ins for anchors Shannon picks by eye.
# ══════════════════════════════════════════════════════════════════
def aw_typical(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, vw: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    """Each bar's price for the anchored VWAP: the bar's own VWAP where it is known and inside the bar's range, else
    the typical price (H+L+C)/3."""
    tp = (h + l + c) / 3.0
    if vw is None:
        return tp
    vw = vw.reindex(index=c.index, columns=c.columns).astype(float)
    ok = vw.notna() & (vw > 0) & (vw >= l * 0.999) & (vw <= h * 1.001)
    return vw.where(ok, tp)


def _aw_anchor(flag: pd.DataFrame) -> np.ndarray:
    """Row of the last True at or before each row (-1 before the first)."""
    n = len(flag)
    ar = np.where(flag.to_numpy(bool), np.arange(n)[:, None], -1)
    return np.maximum.accumulate(ar, axis=0) if n else ar


def _aw_line(cpv: np.ndarray, cv: np.ndarray, anc: np.ndarray) -> np.ndarray:
    """The VWAP from each row's anchor to that row: sum(price x volume) / sum(volume), anchor bar included."""
    a1 = np.clip(anc - 1, 0, None)
    before_pv = np.where(anc > 0, np.take_along_axis(cpv, a1, 0), 0.0)
    before_v = np.where(anc > 0, np.take_along_axis(cv, a1, 0), 0.0)
    num, den = cpv - before_pv, cv - before_v
    with np.errstate(invalid="ignore", divide="ignore"):
        out = num / den
    return np.where((anc >= 0) & (den > 0), out, np.nan)


def aw_panels(o: pd.DataFrame, h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, v: pd.DataFrame,
              tp: Optional[pd.DataFrame] = None, atr: Optional[pd.DataFrame] = None,
              s50: Optional[pd.DataFrame] = None, s200: Optional[pd.DataFrame] = None) -> Dict[str, Any]:
    """The three anchored VWAPs per name per day (point-in-time), their anchors' ages, the close's position against
    them, the AVWAP state, the four setups plus a no-filter reference cross, and their stops."""
    idx, cols = c.index, c.columns
    n = len(idx)
    tp = (h + l + c) / 3.0 if tp is None else tp
    atr = _mc_atr(h, l, c, 14) if atr is None else atr
    s50 = c.rolling(50, min_periods=50).mean() if s50 is None else s50
    s200 = c.rolling(200, min_periods=200).mean() if s200 is None else s200
    pv = (tp * v).to_numpy(float)
    vv = v.to_numpy(float)
    bad = ~(np.isfinite(pv) & np.isfinite(vv) & (vv > 0))
    cpv, cv = np.cumsum(np.where(bad, 0.0, pv), axis=0), np.cumsum(np.where(bad, 0.0, vv), axis=0)
    with np.errstate(invalid="ignore", divide="ignore"):
        p_hi = h.rolling(AW_HI_LB, min_periods=1).max().shift(1)      # a new high / low must beat the prior window
        p_lo = l.rolling(AW_LO_LB, min_periods=1).min().shift(1)      # strictly, so a flat base doesn't re-anchor daily
        f_hi = h.notna() & ((h > p_hi) | p_hi.isna())
        f_lo = l.notna() & ((l < p_lo) | p_lo.isna())
        vavg = v.rolling(50, min_periods=20).mean().shift(1)
        f_ev = (o / c.shift(1) - 1 >= AW_EV_GAP) & (v >= AW_EV_VOL * vavg) & (c > c.shift(1))
    rows = np.arange(n)[:, None]
    A_hi, A_lo, A_ev = _aw_anchor(f_hi), _aw_anchor(f_lo), _aw_anchor(f_ev)
    age = lambda a_: np.where(a_ >= 0, rows - a_, np.nan).astype(float)
    g_hi, g_lo, g_ev = age(A_hi), age(A_lo), age(A_ev)
    hi_np, lo_np, ev_np = _aw_line(cpv, cv, A_hi), _aw_line(cpv, cv, A_lo), _aw_line(cpv, cv, A_ev)
    ev_np = np.where(g_ev <= AW_EV_LB, ev_np, np.nan)
    ev_low = np.where((A_ev >= 0) & (g_ev <= AW_EV_LB), np.take_along_axis(l.to_numpy(float), np.clip(A_ev, 0, None), 0), np.nan)
    D = lambda x: pd.DataFrame(x, index=idx, columns=cols)
    a_hi, a_lo, a_ev = D(hi_np), D(lo_np), D(ev_np)
    with np.errstate(invalid="ignore", divide="ignore"):
        pos_hi, pos_lo, pos_ev = (c / a_hi - 1) * 100, (c / a_lo - 1) * 100, (c / a_ev - 1) * 100
        clv = (c - l) / (h - l).where(h > l)
        off_hi = c / h.rolling(AW_HI_LB, min_periods=120).max() - 1
    above_h, above_l = (c > a_hi), (c > a_lo)
    state = D(np.where(a_hi.isna() | a_lo.isna(), np.nan, above_h.astype(float) + above_l.astype(float)))
    c1 = c.shift(1)
    cross = (c > a_hi) & (c1 <= a_hi.shift(1)) & (D(A_hi) == D(A_hi).shift(1))   # same anchor yesterday
    trend_ok = (s50 > s50.shift(10)) & (c > s200) & (off_hi >= AW_OFF_HI)

    def held(line: pd.DataFrame) -> pd.DataFrame:
        return (l <= line + AW_TOUCH * atr) & (c > line) & (c <= line + AW_HOLD_MAX * atr) & (clv >= AW_HOLD_CLV)
    S = {"reclaim": cross & (D(g_hi) >= AW_RECLAIM_AGE) & (c > s50),
         "pull_lo": held(a_lo) & (D(g_lo) >= AW_MIN_AGE) & trend_ok,
         "pull_ev": held(a_ev) & (D(g_ev) >= 3) & (c > D(ev_low)),
         "cross_raw": cross}
    top, bot = np.fmax(hi_np, lo_np), np.fmin(hi_np, lo_np)
    with np.errstate(invalid="ignore"):
        pinched = (np.abs(hi_np - lo_np) <= AW_PINCH * atr.to_numpy(float)) & (A_hi < A_lo) & (g_lo >= AW_MIN_AGE)
    topD = D(top)
    S["pinch"] = D(pinched) & (c > topD) & (c1 <= topD.shift(1))
    S = {k: x.fillna(False).astype(bool) for k, x in S.items()}
    stops = {"avh": a_hi - AW_STOP_ATR * atr, "avl": a_lo - AW_STOP_ATR * atr, "ave": a_ev - AW_STOP_ATR * atr,
             "avp": D(bot) - AW_STOP_ATR * atr}
    return {"hi": a_hi, "lo": a_lo, "ev": a_ev, "age_hi": D(g_hi), "age_lo": D(g_lo), "age_ev": D(g_ev),
            "pos_hi": pos_hi, "pos_lo": pos_lo, "pos_ev": pos_ev, "state": state, "S": S, "stops": stops,
            "pinch_w": D(np.abs(hi_np - lo_np)) / atr, "ev_low": D(ev_low)}


def aw_state_label(code: Any) -> str:
    x = _n(code, np.nan)
    return AW_STATES[int(x)] if np.isfinite(x) and 0 <= x < len(AW_STATES) else ""


def aw_snapshot(A: Dict[str, Any], P: Dict[str, pd.DataFrame], recent: int = AW_RECENT) -> pd.DataFrame:
    """One row per name: the three lines, the close against each, anchor ages, the AVWAP state, and the freshest
    setup within `recent` sessions with its plan (buy stop over the signal day's high, the setup's stop)."""
    c, h = P["close"], P["high"]
    cols = c.columns
    last = lambda x: x.iloc[-1].reindex(cols)
    out = pd.DataFrame(index=cols)
    for k_ in ("hi", "lo", "ev", "pos_hi", "pos_lo", "pos_ev", "age_hi", "age_lo", "age_ev", "pinch_w"):
        out[f"vw_{k_}"] = last(A[k_]).astype(float)
    out["vw_state_code"] = last(A["state"]).astype(float)
    out["vw_state"] = [aw_state_label(x) for x in out["vw_state_code"]]
    keys = list(AW_SETUPS)
    ages = np.column_stack([_age(A["S"][k_]).reindex(cols).to_numpy(float) for k_ in keys]) if len(cols) else np.empty((0, len(keys)))
    for j_, k_ in enumerate(keys):
        out[f"vw_{k_}_age"] = ages[:, j_] if len(cols) else []
    ages = np.where(ages <= recent, ages, np.nan)
    best, best_age, trig, stop, done = [], [], [], [], []
    n = len(c)
    for j, tk in enumerate(cols):
        row = ages[j] if len(cols) else np.array([])
        if not np.isfinite(row).any():
            best.append(""), best_age.append(np.nan), trig.append(np.nan), stop.append(np.nan), done.append("")
            continue
        kk = int(np.nanargmin(row))
        k_, a_ = keys[kk], float(row[kk])
        i = n - 1 - int(a_)
        hi_ = float(h[tk].iloc[i])
        s_ = float(A["stops"][AW_STOP_OF[k_]][tk].iloc[i])
        if not np.isfinite(s_) or s_ >= hi_:
            s_ = float(P["low"][tk].iloc[max(0, i - 9):i + 1].min())
        after = h[tk].iloc[i + 1:]
        d_ = ""
        if len(after) and float(after.max()) > hi_:
            d_ = f"triggered {str(after.index[int(np.argmax(after.to_numpy() > hi_))])[:10]}"
        best.append(k_), best_age.append(a_), trig.append(hi_), stop.append(s_), done.append(d_)
    out["vw_setup_key"], out["vw_setup_age"] = best, best_age
    out["vw_setup"] = [AW_SETUPS.get(k_, "") for k_ in best]
    out["vw_trigger"], out["vw_stop"], out["vw_triggered"] = trig, stop, done
    with np.errstate(invalid="ignore", divide="ignore"):
        out["vw_risk_pct"] = (out["vw_trigger"] - out["vw_stop"]) / out["vw_trigger"] * 100
    out["vw_failed"] = (out["vw_setup_key"] != "") & (last(c).astype(float) <= out["vw_stop"])   # closed under its stop since
    return out


def aw_block(ab: Dict[str, Any]) -> Dict[str, Any]:
    """The anchored-VWAP panels and snapshot for the loaded universe, cached once per data load."""
    P = ab["P"]
    key = ("aw_block", tuple(P["close"].columns), str(ab["asof"]), P["close"].shape)

    def run():
        Q = {k: P[k].iloc[-MC_MAX_ROWS:].astype(float) for k in ("open", "high", "low", "close", "volume")}
        tp = aw_typical(Q["high"], Q["low"], Q["close"], P["vwap"].iloc[-MC_MAX_ROWS:] if "vwap" in P else None)
        A = aw_panels(Q["open"], Q["high"], Q["low"], Q["close"], Q["volume"], tp)
        return {"A": A, "Q": Q, "tp": tp, "snap": aw_snapshot(A, Q)}
    return memo(key, run, capacity=300)


def aw_breadth(A: Dict[str, Any]) -> pd.DataFrame:
    """Share of names over the AVWAP from their own 52-week high, and under both lines, each day: a breadth read of
    how much of the list has its overhead supply cleared."""
    s = A["state"]
    n = s.notna().sum(axis=1)
    with np.errstate(invalid="ignore", divide="ignore"):
        out = pd.DataFrame({"above_hi": (A["pos_hi"] > 0).sum(axis=1) / A["pos_hi"].notna().sum(axis=1),
                            "above_both": (s == 2).sum(axis=1) / n, "below_both": (s == 0).sum(axis=1) / n,
                            "names": n})
    return out[out["names"] >= 5]


def aw_chart_frame(Q: Dict[str, pd.DataFrame], tp: pd.DataFrame, A: Dict[str, Any], sym: str,
                   look: int = 252) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """Price and the three lines as a chart draws them: each one anchored at today's anchor and run forward from it
    (the ledger reads them point-in-time). Also each anchor's date."""
    c, v = Q["close"][sym], Q["volume"][sym].fillna(0.0)
    p = tp[sym]
    n = len(c)
    out = pd.DataFrame({"date": c.index, "close": c.to_numpy(float)})
    anchors = {}
    for k_, lab_ in AW_LINE_LAB.items():
        g_ = _n(A[f"age_{k_}"][sym].iloc[-1], np.nan)
        if not np.isfinite(g_) or (k_ == "ev" and g_ > AW_EV_LB):
            out[lab_] = np.nan
            continue
        a_ = n - 1 - int(g_)
        pv_, v_ = (p * v).to_numpy(float), v.to_numpy(float)
        ok = np.isfinite(pv_) & (v_ > 0)
        cpv, cv = np.cumsum(np.where(ok, pv_, 0.0)), np.cumsum(np.where(ok, v_, 0.0))
        b_pv, b_v = (cpv[a_ - 1], cv[a_ - 1]) if a_ > 0 else (0.0, 0.0)
        with np.errstate(invalid="ignore", divide="ignore"):
            line = (cpv - b_pv) / (cv - b_v)
        line[:a_] = np.nan
        out[lab_] = line
        anchors[lab_] = c.index[a_]
    sig = {k_: A["S"][k_][sym] for k_ in AW_SETUPS}
    for k_, s_ in sig.items():
        out[f"sig_{k_}"] = s_.to_numpy(bool)
    return out.iloc[-look:].reset_index(drop=True), anchors


def aw_ledger_read(ev: Optional[pd.DataFrame], horizon: int = 10) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """From a built ledger: the VWAP family's setups (E[R] by date with a Newey-West t), and every long family's
    trades split by the AVWAP state on the signal day."""
    if ev is None or not len(ev):
        return pd.DataFrame(), pd.DataFrame()
    d = ev[ev["status"] == 0]

    def stat(g):
        x = g.groupby("date")["r"].mean().sort_index().to_numpy()
        mu, se = lg_nw(x, horizon)
        return {"trades": len(g), "dates": len(x), "er": mu, "t": mu / se if se and np.isfinite(se) and se > 0 else np.nan,
                "win": float((g["r"] > 0).mean())}
    rows = []
    for sid in [k_ for k_, v_ in LG_SETUPS.items() if v_[0] == "VWAP"] + ["base:uptrend"]:
        g = d[d["setup"] == sid]
        if len(g) >= 5:
            rows.append({"setup": LG_SETUPS[sid][1], "id": sid, **stat(g)})
    T1 = pd.DataFrame(rows)
    rows = []
    if "aw_state" in d:
        fam = d["setup"].map(lambda s_: LG_SETUPS.get(str(s_), ("",))[0])
        lab = d["aw_state"].map(lambda x: aw_state_label(x))
        for f_ in [f_ for f_ in LG_FAMILIES if (fam == f_).any()] + ["All long setups"]:
            sel = (fam == f_) if f_ != "All long setups" else (fam != "Baseline")
            for s_ in AW_STATES[::-1]:
                g = d[sel & (lab == s_)]
                if len(g) >= 5:
                    rows.append({"family": f_, "state": s_, **stat(g)})
    return T1, pd.DataFrame(rows)


AW_GUIDE = f"""
**Where it comes from.** Brian Shannon's anchored VWAP (*Maximum Trading Gains with Anchored VWAP*, 2023). A VWAP
started at a meaningful bar is the average price paid by everyone who has bought since. When price is over it, that
whole group is in profit and calm; under it, they are losing and many will sell to get out even. So the line works
as support or resistance, and a cross of it changes who is in control. Shannon pairs it with stage analysis: lines
sloping up under price in Stage 2, price stuck under a falling line from the high in Stage 4.

**The three lines.** Each is anchored point-in-time, from data up to that day, so the Setup ledger can test them:
- *From the 52-week high*: the last session that set a 52-week high. In a pullback or a base, its buyers are the
  supply overhead.
- *From the 63-day low*: the last session that set a 63-day low. In an uptrend that is the swing low under the move,
  and its line is where the average buyer since the low breaks even.
- *From a gap-up day*: the last open {AW_EV_GAP:.0%}+ over the prior close on {AW_EV_VOL:g}x+ the 50-day volume and an
  up close, within {AW_EV_LB} sessions (an earnings or news day: the episodic pivot's anchor).

**The state.** ABOVE BOTH: over the lines from the high and the low (no trapped buyers above). BETWEEN: over one,
under the other, usually under the high's line in a base or pullback. BELOW BOTH: everyone since the high and the
low is losing.

**The setups (Setup ledger family VWAP).**
- *Reclaim*: the first close over the line from the high, with the high at least {AW_RECLAIM_AGE} sessions old and the
  close over the 50-day. The supply since the high has been absorbed.
- *Pullback to the low's line*: in an uptrend (rising 50-day, over the 200-day, within 25% of the high), the low comes
  within {AW_TOUCH} ATR of the line from the swing low (or through it) and the close is back over it, in the top half
  of the day's range and no more than {AW_HOLD_MAX} ATR above the line (so the stop is near).
- *Pullback to the gap's line*: the same test of the line from a gap-up day, at least 3 sessions after it, with the
  close still over the gap day's low.
- *Pinch*: after a decline (the high came before the low), the lines from the high and the low come within
  {AW_PINCH:g} ATR of each other, and price closes over both for the first time. Shannon's AVWAP "pinch".
- *Close over the high's line, no filters*: the reference, like the MACD family's raw crosses.
- Stops: the line the setup leaned on, less {AW_STOP_ATR} ATR. Exits seed to a trailing stop.

**What the lab adds.** Every setup in the ledger carries its AVWAP state and its distance from the high's line, so any
family (MACD, 8-week, Zanger...) can be split by them (split list: "AVWAP state" and "Close vs the AVWAP from the
high"). The table at the end of this page does that for you once the ledger is built.

**Limits.** Daily bars only: Shannon times entries on intraday charts against the session's VWAP. Each day's price is
that day's VWAP on Massive and demo bars, the typical price on Yahoo bars. The anchors are rules standing in for
anchors he picks by eye (a specific earnings day, an IPO, a major low), so the lines can differ from a hand-drawn
chart's.
"""

AW_PRESETS = {"all": "Everything", "setup": f"A VWAP setup in the last {AW_RECENT} sessions", "above": "Above both lines",
              "between": "Between the lines", "below": "Below both lines",
              "pinch": f"Pinched (lines within {AW_PINCH:g} ATR, high before low)", "event": "Gap-up anchor live"}


def aw_preset_mask(T: pd.DataFrame, k: str) -> pd.Series:
    if k == "setup":
        return T["vw_setup_key"].fillna("").astype(str) != ""
    if k in ("above", "between", "below"):
        return T["vw_state"] == {"above": "ABOVE BOTH", "between": "BETWEEN", "below": "BELOW BOTH"}[k]
    if k == "pinch":
        return (T["vw_pinch_w"] <= AW_PINCH) & (T["vw_age_hi"] > T["vw_age_lo"])
    if k == "event":
        return T["vw_ev"].notna()
    return pd.Series(True, index=T.index)


def render_aw(cfg, ab: Optional[Dict[str, Any]]) -> None:
    ss = st.session_state
    P_ = st.column_config.NumberColumn
    sec("Anchored VWAP: who is in profit since the high, the low and the last gap (Shannon)")
    if ab is None:
        warnbox("Needs the universe's daily bars (at least 10 names).")
        return
    B = aw_block(ab)
    A, Q, snap = B["A"], B["Q"], B["snap"].copy()
    snap = snap[~snap.index.isin(list(cfg.get("refuse") or []))]
    snap["close"] = Q["close"].iloc[-1].reindex(snap.index)
    snap = snap[snap["vw_state"] != ""]
    if snap.empty:
        warnbox("No name has the history the lines need (a 52-week high and a 63-day low in the loaded bars).")
        return
    vwc = float(ab.get("vwap_cov", 0.0))
    st_cnt = snap["vw_state"].value_counts()
    fresh = snap["vw_setup_key"].fillna("").astype(str) != ""
    kpi_row([kpi_html("Above both", int(st_cnt.get("ABOVE BOTH", 0)), f"{st_cnt.get('ABOVE BOTH', 0) / len(snap):.0%} of {len(snap)} names", "good"),
             kpi_html("Between", int(st_cnt.get("BETWEEN", 0)), "usually under the high's line: supply overhead", "warn"),
             kpi_html("Below both", int(st_cnt.get("BELOW BOTH", 0)), "buyers since the high and the low are losing", "bad"),
             kpi_html("Setups today", int((snap["vw_setup_age"] == 0).sum()), "reclaims, pullbacks that held, pinches"),
             kpi_html(f"Setups in {AW_RECENT} sessions", int(fresh.sum()), "the Brief's VWAP scan reads these"),
             kpi_html("Bar prices", f"{vwc:.0%} VWAP", "the rest use (H+L+C)/3 (Yahoo bars)", "" if vwc >= 0.9 else "warn")])
    Bd = aw_breadth(A).iloc[-504:]
    if len(Bd):
        g = Bd[["above_hi", "above_both", "below_both"]].reset_index()
        g = g.rename(columns={g.columns[0]: "date"}).melt("date", var_name="read", value_name="share")
        g["read"] = g["read"].map({"above_hi": "over the AVWAP from its 52-week high", "above_both": "above both lines",
                                   "below_both": "below both lines"})
        show_chart(_alt(alt.Chart(g).mark_line(strokeWidth=1.5).encode(
            x=alt.X("date:T", title=None), y=alt.Y("share:Q", title=None, axis=alt.Axis(format="%")),
            color=alt.Color("read:N", scale=alt.Scale(range=[C_ACCENT, C_GREEN, C_RED]), legend=alt.Legend(orient="top", title=None, labelLimit=320)),
            tooltip=[alt.Tooltip("date:T"), "read", alt.Tooltip("share:Q", format=".0%")]).properties(
            title="Your list's breadth on its anchored VWAPs, last two years"), 220))
        note("A breadth read: how much of the list has cleared the supply since its own high. A rising share over the "
             "high's line is the market absorbing overhead supply; a falling one, rallies running into trapped buyers.")
    counts = {k_: int(aw_preset_mask(snap, k_).sum()) for k_ in AW_PRESETS}
    pre = st.radio("Show", list(AW_PRESETS), horizontal=True, key="aw_preset", format_func=lambda k_: f"{AW_PRESETS[k_]} ({counts[k_]})")
    view = snap[aw_preset_mask(snap, pre).fillna(False).astype(bool)]
    if view.empty:
        note("No names match.")
    else:
        c = st.columns([1, 1])
        with c[0]:
            d = view.reset_index().rename(columns={"index": "ticker"})
            d["group"] = np.where(d["vw_setup_key"] != "", d["vw_setup_key"].map(AW_SHORT).fillna(""), d["vw_state"].str.lower())
            pts = alt.Chart(d, title="Close vs the AVWAP from the high (x) and from the low (y)").mark_circle(size=60, opacity=0.85).encode(
                x=alt.X("vw_pos_hi:Q", title="% vs the AVWAP from the 52-week high"),
                y=alt.Y("vw_pos_lo:Q", title="% vs the AVWAP from the 63-day low"),
                color=alt.Color("group:N", scale=alt.Scale(domain=["above both", "between", "below both"] + list(AW_SHORT.values()),
                                                           range=[C_GREEN, C_ACCENT, C_MUTED, C_BLUE, "#2dd4bf", "#a77bf3", C_RED]),
                                legend=alt.Legend(orient="top", title=None, columns=4, labelLimit=240)),
                tooltip=["ticker", "vw_state", "vw_setup", alt.Tooltip("vw_pos_hi:Q", format="+.1f"), alt.Tooltip("vw_pos_lo:Q", format="+.1f")])
            zero = alt.Chart(pd.DataFrame({"x": [0.0]})).mark_rule(strokeDash=[4, 3], color=C_MUTED).encode(x="x:Q")
            lbl = alt.Chart(d[d["vw_setup"] != ""]).mark_text(dx=7, dy=-7, color=C_TEXT, fontSize=10).encode(
                x="vw_pos_hi:Q", y="vw_pos_lo:Q", text="ticker")
            show_chart(_alt(pts + zero + lbl, 330))
        with c[1]:
            order = list(view.sort_values(["vw_setup_age", "vw_pos_hi"], ascending=[True, False], na_position="last").index)
            pick = st.selectbox("Name", order, key="aw_pick")
            ch, anch = aw_chart_frame(Q, B["tp"], A, pick)
            dom = ["close"] + list(AW_LINE_LAB.values())
            lines = [k_ for k_ in dom if k_ in ch and ch[k_].notna().any()]
            long = ch.melt("date", lines, var_name="line", value_name="price").dropna()
            ln = alt.Chart(long).mark_line(strokeWidth=1.4).encode(
                x=alt.X("date:T", title=None), y=alt.Y("price:Q", title=None, scale=alt.Scale(zero=False)),
                color=alt.Color("line:N", scale=alt.Scale(domain=dom, range=[C_TEXT, C_RED, C_GREEN, C_ACCENT]),
                                legend=alt.Legend(orient="top", title=None, columns=2, labelLimit=260)))
            sg = ch.melt(["date", "close"], [f"sig_{k_}" for k_ in AW_SETUPS], var_name="setup", value_name="on")
            sg = sg[sg["on"]].assign(setup=lambda x: x["setup"].str[4:].map(AW_SETUPS))
            dots = alt.Chart(sg).mark_point(shape="triangle-up", size=70, filled=True, color=C_ACCENT2).encode(
                x="date:T", y="close:Q", tooltip=["date:T", "setup"])
            show_chart(_alt(ln + dots, 300))
            r = snap.loc[pick]
            bits = [f"{pick} is {r['vw_state'].lower()}"]
            for k_, w_ in (("hi", "52-week high"), ("lo", "63-day low"), ("ev", "gap-up day")):
                if np.isfinite(_n(r.get(f"vw_{k_}"), np.nan)):
                    bits.append(f"{_n(r[f'vw_pos_{k_}'], 0):+.1f}% vs the line from the {w_} ({int(_n(r[f'vw_age_{k_}'], 0))} sessions back)")
            if r["vw_setup"]:
                bits.append(f"{r['vw_setup'][0].lower() + r['vw_setup'][1:]} {_su_when(r['vw_setup_age'])}"
                            + (" (it has closed under its stop since: failed)" if bool(r.get("vw_failed")) else "") + f": buy stop {_n(r['vw_trigger'], np.nan):.2f}, "
                            f"stop {_n(r['vw_stop'], np.nan):.2f} ({_n(r['vw_risk_pct'], np.nan):.1f}% risk)"
                            + (f", {r['vw_triggered']}" if r["vw_triggered"] else ""))
            note("; ".join(bits) + ". Triangles: the VWAP setups on this name (point-in-time anchors, so a line drawn "
                 "from today's anchor can sit differently from the one the signal saw).")
        cols = ["close", "vw_state", "vw_setup", "vw_setup_age", "vw_failed", "vw_trigger", "vw_stop", "vw_risk_pct", "vw_triggered",
                "vw_pos_hi", "vw_age_hi", "vw_pos_lo", "vw_age_lo", "vw_pos_ev", "vw_age_ev", "vw_pinch_w"]
        T = view.sort_values(["vw_setup_age", "vw_pos_hi"], ascending=[True, False], na_position="last")[cols].reset_index()
        T = T.rename(columns={T.columns[0]: "ticker"})
        show_df(T, height=min(460, 40 + 35 * len(T)),
                column_config={"close": P_(format="%.2f"), "vw_state": st.column_config.TextColumn("state"),
                               "vw_setup": st.column_config.TextColumn("setup", width="medium"), "vw_setup_age": P_("age", format="%.0f"),
                               "vw_failed": st.column_config.CheckboxColumn("failed", help="Closed under the setup's stop since it fired."),
                               "vw_trigger": P_("buy stop", format="%.2f"), "vw_stop": P_("stop", format="%.2f"),
                               "vw_risk_pct": P_("risk %", format="%.1f"), "vw_triggered": st.column_config.TextColumn("triggered"),
                               "vw_pos_hi": P_("vs high's line %", format="%+.1f"), "vw_age_hi": P_("high, sessions ago", format="%.0f"),
                               "vw_pos_lo": P_("vs low's line %", format="%+.1f"), "vw_age_lo": P_("low, sessions ago", format="%.0f"),
                               "vw_pos_ev": P_("vs gap's line %", format="%+.1f"), "vw_age_ev": P_("gap, sessions ago", format="%.0f"),
                               "vw_pinch_w": P_("high-low lines apart, ATR", format="%.1f")})
        st.download_button("Download table (CSV)", T.to_csv(index=False), "anchored_vwap.csv", "text/csv", key="aw_dl")
    res = ss.get("lg_res")
    run = (res or {}).get("runs", {}).get("list") if res else None
    in_cloud = lab_cloud()                 # the hosted dashboard builds no ledger, so there is nothing to read
    if not in_cloud:
        sec("Does it matter for your setups?")
    if in_cloud:
        pass
    elif run is None or run.get("ev") is None or not len(run["ev"]):
        note("Build the Setup ledger (Stocks > Setup ledger) with the VWAP family on, and this reads its setups, then "
             "every family's trades by the AVWAP state on the signal day.")
    else:
        T1, T2 = aw_ledger_read(run["ev"], int(run.get("prm", {}).get("horizon", 10)))
        cfg_ = {"trades": P_("trades", format="%d"), "dates": P_("dates", format="%d"), "er": P_("E[R]", format="%+.2f"),
                "t": P_("t", format="%+.1f"), "win": P_("win rate", format="percent")}
        if len(T1):
            show_df(T1, column_config={"setup": st.column_config.TextColumn("setup", width="large"), **cfg_})
        else:
            note("The ledger has no VWAP trades: add the VWAP family and rebuild.")
        if len(T2):
            show_df(T2, height=min(520, 40 + 35 * len(T2)), column_config={"family": st.column_config.TextColumn("family"),
                                                                       "state": st.column_config.TextColumn("AVWAP state at the signal"), **cfg_})
            note("E[R] averaged by date with a Newey-West t. If a family's E[R] changes with the state by more than "
                 "noise, the state is a filter for it; test it properly with the ledger's split 'AVWAP state'.")
        elif "aw_state" not in run["ev"]:
            note("This ledger was built before the AVWAP state existed: rebuild it to split every family by it.")
    with st.expander("How the anchored VWAP tab works"):
        st.markdown(AW_GUIDE)


# ══════════════════════════════════════════════════════════════════
#  LEVERAGED FUNDS  (Stocks > Leveraged; a line on the Brief's setup cards; a Screener column and filter)
#  Daily-reset leveraged and inverse ETFs / ETNs: index and sector funds (TQQQ, SOXL, LABU...) and single-stock funds
#  (NVDL, TSLL, MUU...). The catalogue is parsed from fund names, so it stays current without a hand-kept list:
#    - Massive: every active ETF and ETN from /v3/reference/tickers, with the last session's dollar volume from the
#      grouped daily bars; cached in data/lev_funds.csv and refreshed on demand (a week old = stale);
#    - otherwise the built-in seed below (the most traded ~270 as of 2026-11-10), plus any CSV you load (a
#      financecharts.com or other screener export with a symbol and a name column).
#  A fund's return over one day is L x the underlying's; over longer it drifts by the variance drag. For a
#  daily-reset fund the log return over t days is about L x (underlying log return) - (L^2 - L) / 2 x sigma^2 x t
#  (Cheng & Madhavan 2009, "The Dynamics of Leveraged and Inverse Exchange-Traded Funds"; Avellaneda & Zhang 2010,
#  "Path-dependence of leveraged ETF returns"). So: fine for a swing of days to a few weeks in a trending name, costly
#  held through chop.
# ══════════════════════════════════════════════════════════════════
