def lev_parse(ticker: str, name: str) -> Optional[Dict[str, Any]]:
    """A fund's leverage (signed: -2 = 2x inverse), side, what it levers and how, from its ticker and name. None when
    the name doesn't describe a leveraged or inverse fund."""
    t, nm = str(ticker or "").strip().upper(), " ".join(str(name or "").split())
    if not t or not nm:
        return None
    low = nm.lower()
    low2 = low.replace("short-term", "shortterm").replace("short term", "shortterm")   # "short-term" isn't a side
    m = re.search(r"(-?\d+(?:\.\d+)?)\s*x\b", low)
    is_pro = "proshares" in low
    if m:
        L = abs(float(m.group(1)))
    elif is_pro and re.search(r"\bultrapro\b", low):
        L = 3.0
    elif is_pro and re.search(r"\bultra(?:short)?\b", low):
        L = 2.0
    elif is_pro and re.search(r"\bshort\b", low2):
        L = 1.0
    else:
        return None
    if not m and re.search(LEV_NOT_LEV, low):
        return None
    if m and re.search(r"duration|income fund|buffer|maturity", low):
        return None
    short = bool(re.search(r"\bbear\b|\binverse\b|ultrashort|\bshort\b|-\d+(?:\.\d+)?\s*x", low2))
    if t in LEV_OVERRIDE:
        L, short = abs(LEV_OVERRIDE[t]), LEV_OVERRIDE[t] < 0
    if L <= 1.0 and not short:
        return None                                      # a 1x long product isn't leveraged
    lev = -L if short else L
    reset = "monthly" if "monthly" in low else ("quarterly" if "quarterly" in low else ("weekly" if "weekly" in low else "daily"))
    issuer = next((i_ for i_ in LEV_ISSUERS if i_.lower() in low), "")
    under, label, kind = "", "", ""
    for pat in LEV_SINGLE_PATS:
        mm = re.search(pat, nm, flags=re.I)
        if not mm:
            continue
        tok = mm.group(1).strip()
        key = tok.upper()
        if key in LEV_ALIAS:
            under, label, kind = LEV_ALIAS[key], tok, "single stock"
            if "(" in under:                             # a foreign stock with no US listing
                under, label = "", LEV_ALIAS[key]
        elif re.fullmatch(r"[A-Z]{1,5}(?:\.[A-Z])?", tok) and not re.search(r"^(SPY|QQQ|DRAM|XNDU|AI|US|USA|GOLD|OIL|MSCI|FTSE|CSI)$", tok):
            under, label, kind = tok, tok, "single stock"
        break
    if not kind:
        for pat, proxy, lab_, k_ in LEV_INDEX_MAP:
            if re.search(pat, low):
                under, label, kind = proxy, lab_, k_
                break
    if not kind:
        kind, label = "other", nm
    return {"ticker": t, "name": nm, "issuer": issuer, "lev": float(lev), "side": "short" if lev < 0 else "long",
            "under": under, "under_label": label, "kind": kind, "reset": reset}


def lev_frame(rows: Sequence[Dict[str, Any]], src: str, asof: str) -> pd.DataFrame:
    """Parse ticker / name / dollar-volume rows into the catalogue (leveraged and inverse funds only)."""
    out = []
    for r in rows:
        p = lev_parse(r.get("ticker", ""), r.get("name", ""))
        if p:
            p.update({"dv_m": _n(r.get("dv_m"), np.nan), "asof": asof, "src": src})
            out.append(p)
    df = pd.DataFrame(out, columns=LEV_COLS)
    if len(df):
        df = df.sort_values("dv_m", ascending=False, na_position="last").drop_duplicates("ticker").reset_index(drop=True)
    return df


def lev_seed() -> pd.DataFrame:
    rows = []
    for line in LEV_SEED.splitlines():
        p = line.split("|")
        if len(p) >= 2:
            rows.append({"ticker": p[0], "name": p[1], "dv_m": float(p[2]) if len(p) > 2 and p[2] else np.nan})
    return lev_frame(rows, "built-in list", LEV_SEED_ASOF)


def lev_from_csv(df: pd.DataFrame) -> pd.DataFrame:
    """A screener export (financecharts.com, Barchart, ETFdb...): a symbol column and a name column; a dollar-volume
    or volume x price column when there is one."""
    cols = {c_.lower().strip(): c_ for c_ in df.columns}
    tk = next((cols[k] for k in ("symbol", "ticker", "etf", "fund") if k in cols), None)
    nm = next((cols[k] for k in ("name", "fund name", "etf name", "description", "security name") if k in cols), None)
    if tk is None or nm is None:
        return pd.DataFrame(columns=LEV_COLS)
    dvc = next((cols[k] for k in cols if "dollar" in k and "vol" in k), None)
    rows = [{"ticker": r[tk], "name": r[nm], "dv_m": (_n(r[dvc], np.nan) / 1e6 if dvc else np.nan)} for _, r in df.iterrows()]
    return lev_frame(rows, "your CSV", date.today().isoformat())


def lev_refresh_massive(key: str) -> pd.DataFrame:
    """Every active ETF and ETN from Massive, parsed, with the last session's dollar volume."""
    rows = []
    for typ in ("ETF", "ETN"):
        rows += massive_get_all("/v3/reference/tickers", {"market": "stocks", "type": typ, "active": "true", "limit": 1000},
                                key, max_pages=12)
    d = last_completed_session()
    try:
        g = grouped_day(d, key)
        dv = (g.set_index("ticker")["close"] * g.set_index("ticker")["volume"] / 1e6).to_dict()
    except Exception:
        dv = {}
    recs = [{"ticker": r.get("ticker"), "name": r.get("name"), "dv_m": dv.get(r.get("ticker"), np.nan)} for r in rows]
    return lev_frame(recs, "Massive", d.isoformat())


def lev_save(df: pd.DataFrame) -> None:
    LEV_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = LEV_FILE.with_suffix(".tmp")
    df[LEV_COLS].to_csv(tmp, index=False)
    os.replace(tmp, LEV_FILE)


def lev_catalog() -> pd.DataFrame:
    """The saved catalogue (Massive refresh or your CSV merged over the seed), else the built-in seed."""
    try:
        if LEV_FILE.exists():
            df = pd.read_csv(LEV_FILE, dtype={"ticker": str, "under": str})
            if len(df) and set(LEV_COLS) <= set(df.columns):
                df["under"] = df["under"].fillna("")
                return df[LEV_COLS]
    except Exception:
        pass
    return memo(("lev_seed", LEV_SEED_ASOF), lev_seed)


def lev_prefs() -> Dict[str, Any]:
    out = dict(LEV_DEFAULTS)
    try:
        out.update({k: v for k, v in disk_json(LEV_PREFS_FILE, {}).items() if k in LEV_DEFAULTS})
    except Exception:
        pass
    try:
        out.update({k: st.session_state[k] for k in LEV_DEFAULTS if k in st.session_state})
    except Exception:
        pass
    return out


def lev_pick(cat: pd.DataFrame, under: str, side: str = "long", min_dv: float = 5.0, max_lev: float = 3.0,
             single_max: float = 2.0) -> Optional[pd.Series]:
    """The fund to use for one underlying and side: daily reset, leverage at most max_lev (single stocks at most
    single_max), at least min_dv $M a day; the most traded among those at the highest such leverage, unless a lower
    leverage of 2x or more trades over 3x as much (liquidity wins, but never down to 1x)."""
    if cat is None or not len(cat) or not under:
        return None
    d = cat[(cat["under"] == under) & (cat["side"] == side) & (cat["reset"] == "daily")]
    cap = np.where(d["kind"] == "single stock", single_max, max_lev)
    d = d[(d["lev"].abs() <= cap + 1e-9) & (d["lev"].abs() >= 1.0) & (d["dv_m"].fillna(0) >= min_dv)]
    if not len(d):
        return None
    d = d.assign(L=d["lev"].abs()).sort_values(["L", "dv_m"], ascending=[False, False])
    best = d.iloc[0]
    alt_ = d[(d["L"] < best["L"]) & (d["L"] >= 2.0)].sort_values("dv_m", ascending=False)   # still leveraged
    if len(alt_) and _n(alt_.iloc[0]["dv_m"], 0) > 3 * _n(best["dv_m"], 0):
        best = alt_.iloc[0]
    return best


def lev_map(cat: pd.DataFrame, names: Sequence[str], prefs: Optional[Dict[str, Any]] = None) -> pd.DataFrame:
    """Per name: the long fund and the short fund to use (or none), with leverage and dollar volume."""
    p = {**LEV_DEFAULTS, **(prefs or {})}
    rows = []
    for t in names:
        r = {"ticker": t}
        for side in ("long", "short"):
            b = lev_pick(cat, t, side, float(p["lev_min_dv"]), float(p["lev_max"]), float(p["lev_single_max"]))
            r[f"lev_{side}"] = "" if b is None else str(b["ticker"])
            r[f"lev_{side}_x"] = np.nan if b is None else float(b["lev"])
            r[f"lev_{side}_dv"] = np.nan if b is None else _n(b["dv_m"], np.nan)
        n_all = cat[cat["under"] == t] if len(cat) else cat
        r["lev_n"] = int(len(n_all))
        r["lev_txt"] = (f"{r['lev_long']} {abs(r['lev_long_x']):g}x" if r["lev_long"] else "")
        rows.append(r)
    return pd.DataFrame(rows).set_index("ticker") if rows else pd.DataFrame()


def lev_drag(L: float, sigma_d: float, days: float) -> float:
    """Expected variance drag of a daily-reset L-x fund over `days`, as a fraction (negative): exp(-(L^2 - L)/2 x
    sigma^2 x days) - 1, with sigma the underlying's daily volatility."""
    if not (np.isfinite(L) and np.isfinite(sigma_d) and np.isfinite(days)):
        return np.nan
    return float(np.exp(-(L * L - L) / 2.0 * sigma_d ** 2 * days) - 1.0)


def lev_plan(entry: float, stop: float, L: float, fund_px: Optional[float], risk_dollars: float) -> Dict[str, float]:
    """The stock's plan carried to the fund: the same move to the stop is L x as large in the fund (one day; over
    several days it drifts, so watch the stock's level). Shares sized for the same dollar risk need 1/L of the capital."""
    if not (np.isfinite(entry) and np.isfinite(stop) and entry > stop > 0 and np.isfinite(L) and L != 0):
        return {}
    d = stop / entry - 1.0
    fd = max(-0.95, L * d) if L > 0 else -min(0.95, abs(L * d))
    out = {"stock_risk_pct": -d * 100, "fund_risk_pct": -fd * 100, "capital_frac": 1.0 / abs(L)}
    if fund_px is not None and np.isfinite(fund_px) and fund_px > 0:
        out["fund_stop"] = fund_px * (1.0 + fd)
        out["fund_shares"] = int(np.floor(risk_dollars / (fund_px * -fd) + 1e-9)) if risk_dollars > 0 and fd < 0 else 0
        out["fund_capital"] = out["fund_shares"] * fund_px
    out["stock_shares"] = int(np.floor(risk_dollars / (entry - stop) + 1e-9)) if risk_dollars > 0 else 0
    out["stock_capital"] = out["stock_shares"] * entry
    return out


def lev_tracking(fund: pd.Series, under: pd.Series, L: float, look: int = 60) -> Dict[str, float]:
    """How a fund tracked L x its underlying over the last `look` sessions: the daily beta, the yearly tracking error
    of its daily returns against L x the underlying's, and the realized gap over the window against L x the
    underlying's return (the drag plus fees and financing), next to the drag the volatility predicts."""
    j = pd.concat([fund.rename("f"), under.rename("u")], axis=1).dropna()
    if len(j) < 21:
        return {}
    r = j.pct_change().dropna().iloc[-look:]
    if len(r) < 20:
        return {}
    var = float(r["u"].var())
    beta = float(r["f"].cov(r["u"]) / var) if var > 0 else np.nan
    te = float((r["f"] - L * r["u"]).std() * np.sqrt(252))
    w = j.iloc[-len(r) - 1:]
    fund_ret = float(w["f"].iloc[-1] / w["f"].iloc[0] - 1)
    under_ret = float(w["u"].iloc[-1] / w["u"].iloc[0] - 1)
    sig = float(np.log1p(r["u"]).std())
    return {"beta": beta, "te": te, "fund_ret": fund_ret, "under_ret": under_ret, "naive": L * under_ret,
            "gap": fund_ret - L * under_ret, "drag_model": lev_drag(L, sig, len(r)), "sigma_d": sig, "days": len(r)}


def lev_demo_fund(under: pd.Series, L: float, seed: int = 3, fee: float = 0.0095) -> pd.Series:
    """Demo bars for a fund: L x the underlying's daily return, less a daily fee and a little noise, compounded."""
    r = under.pct_change().fillna(0.0)
    rng = np.random.default_rng(seed + int(abs(L) * 10))
    fr = L * r - fee / 252 + rng.normal(0, 0.0005, len(r))
    return (1 + fr).cumprod() * 20.0


def lev_line(t: str, trig: float, stop: float, risk_dollars: float, adr: float, prefs: Optional[Dict[str, Any]] = None,
             side: str = "long") -> str:
    """One line for a Brief card: the fund to use, the plan in its terms and the drag over the planned hold."""
    p = {**LEV_DEFAULTS, **(prefs or {})}
    try:
        cat = lev_catalog()
        b = lev_pick(cat, t, side, float(p["lev_min_dv"]), float(p["lev_max"]), float(p["lev_single_max"]))
    except Exception:
        return ""
    if b is None:
        return ""
    L = float(b["lev"])
    pl = lev_plan(trig, stop, abs(L), None, risk_dollars)
    sig = (adr / 100) * 0.6 if np.isfinite(_n(adr, np.nan)) else np.nan    # a day's range ~ 1.66 daily sigmas
    dr = lev_drag(abs(L), sig, int(p["lev_hold"]))
    if not pl:
        return ""
    return (f"Leveraged: {b['ticker']} ({abs(L):g}x {b['under_label']}, ${_n(b['dv_m'], 0):,.0f}M a day). The stop is "
            f"{pl['fund_risk_pct']:.1f}% in the fund (vs {pl['stock_risk_pct']:.1f}% in the stock), so the same risk takes "
            f"{pl['capital_frac']:.0%} of the capital"
            + (f"; expected drag over {int(p['lev_hold'])} sessions about {dr:+.1%} at this name's volatility" if np.isfinite(dr) else "")
            + ". Keep the stop on the stock's price: the fund's level drifts after the first day.")


LEV_GUIDE = """
**What a leveraged fund is.** A fund that aims for L times its underlying's return **each day** (L = 2 or 3; -1 to -3
for inverse funds), rebalanced every close. Index and sector funds (TQQQ, SOXL, LABU...) lever an index; single-stock
funds (NVDL, TSLL, MUU...) lever one stock, mostly at 2x.

**Why use one on a swing.** The same dollar risk takes 1/L of the capital: a 2x fund with the stop at the same place
on the stock risks the same dollars with half the money tied up. It also gives leverage in an account that can't
use margin or options, and a sector fund lets you trade a whole leading group at once.

**What it costs.**
- *Variance drag.* Over more than a day the fund drifts below L x the underlying's return. For a daily-reset fund the
  log return over t days is about L x the underlying's log return - (L^2 - L)/2 x sigma^2 x t (Cheng & Madhavan 2009;
  Avellaneda & Zhang 2010). A 2x fund on a stock moving 3% a day loses about 0.09% a day to drag, about 0.9% over
  10 sessions; a 3x fund at the same volatility loses three times that. In a strong trend, compounding can go the
  other way (the fund beats L x); in chop it always loses. So: short holds in trending names, not buy-and-hold.
- *Fees and financing.* About 1% a year in expenses, and single-stock funds pay swap financing. The tracking check
  below measures the real gap against L x the underlying.
- *Gaps.* A 30% gap down in the stock is a 60% loss in a 2x fund, and the stop doesn't help through a gap. Size
  for that around earnings.
- *Liquidity.* Single-stock funds can trade thinly. The default floor is $5M a day.

**How the lab picks a fund.** Daily reset; at most 3x for index and sector funds and 2x for single stocks (your
settings); at least the dollar volume you set. Among those it takes the highest leverage, unless a 2x-or-more fund with
lower leverage trades over 3x as much. A 1x inverse fund is used only when no leveraged one passes.

**Stops.** Keep the stop on the stock's price (an alert, or the fund's level re-set each day). On the first day the fund
moves L x the stock, so its stop is L x as far in percent. After that the fund's level drifts from L x, so a fixed fund
stop slowly stops matching the stock's.

**Where it shows.** Each Brief > Setups card adds a line with the fund, its stop distance, the capital needed for the
same risk and the drag over your planned hold. The Screener has a "Leveraged fund" column and filter, and this tab
covers your list, the index and sector funds by trend, a tracking check and the full catalogue.

**The list.** It is parsed from the funds' names. With a Massive key, "Refresh from Massive" reads every active ETF
and ETN plus the last session's dollar volume. Otherwise the built-in list holds the ~270 most-traded funds as of
2026-11-10. Any screener export with a symbol and a name column (financecharts.com's leveraged category, ETFdb,
Barchart) can be loaded on top.
"""


def render_lev(cfg, ab: Optional[Dict[str, Any]], bars: Dict[str, pd.DataFrame], bench_bars: Dict[str, pd.DataFrame]) -> None:
    ss = st.session_state
    P_ = st.column_config.NumberColumn
    sec("Leveraged funds: the same setup with less capital, when a fund exists")
    for k_, v_ in lev_prefs().items():
        ss.setdefault(k_, v_)
    c = st.columns([1.3, 1, 1, 1, 1, 0.9])
    c[0].checkbox("Use leveraged funds when available", key="lev_prefer",
                  help="On: the Brief's setup cards add the fund plan, and the Screener shows the fund column.")
    c[1].number_input("Min fund $M a day", 0.0, 1000.0, step=1.0, key="lev_min_dv")
    c[2].selectbox("Max leverage (index, sector)", [2.0, 3.0], key="lev_max", format_func=lambda x: f"{x:g}x")
    c[3].selectbox("Max leverage (single stock)", [1.5, 2.0], key="lev_single_max", format_func=lambda x: f"{x:g}x")
    c[4].number_input("Planned hold, sessions", 1, 120, step=1, key="lev_hold", help="For the drag estimate.")
    if c[5].button("Save as default", key="lev_save_prefs"):
        try:
            atomic_write_json(LEV_PREFS_FILE, {k: (float(ss[k]) if isinstance(ss[k], (int, float)) and not isinstance(ss[k], bool) else ss[k])
                                               for k in LEV_DEFAULTS})
            st.toast("Saved.")
        except Exception as e:
            warnbox(f"Couldn't save: {type(e).__name__}: {e}")
    prefs = lev_prefs()
    cat = lev_catalog()
    src = str(cat["src"].iloc[0]) if len(cat) else "none"
    asof = str(cat["asof"].max()) if len(cat) else ""
    c = st.columns([2.2, 1.2, 1.6])
    stale = bool(asof) and (date.today() - date.fromisoformat(asof[:10])).days > LEV_STALE_DAYS
    c[0].caption(f"Fund list: {len(cat):,} funds from the {src}, as of {asof}" + (" (over a week old)" if stale else "") + ".")
    if cfg.get("source") == "massive" and cfg.get("key"):
        if c[1].button("Refresh from Massive", key="lev_refresh"):
            with st.spinner("Reading every ETF and ETN, and the last session's volume"):
                try:
                    new = lev_refresh_massive(cfg["key"])
                    if len(new):
                        lev_save(new)
                        st.rerun()
                    else:
                        warnbox("Massive returned no leveraged funds; the list is unchanged.")
                except Exception as e:
                    warnbox(f"Refresh failed: {type(e).__name__}: {e}")
    else:
        c[1].caption("A Massive key refreshes the list.")
    up = c[2].file_uploader("Load a fund list (CSV)", type=["csv"], key="lev_csv",
                            help="A screener export with a symbol and a name column, e.g. financecharts.com's leveraged category.")
    if up is not None and ss.get("_lev_csv_done") != up.name:
        try:
            add = lev_from_csv(pd.read_csv(up))
            if len(add):
                merged = pd.concat([add, cat]).drop_duplicates("ticker", keep="first")
                merged["dv_m"] = merged.groupby("ticker")["dv_m"].transform("max")
                lev_save(merged)
                ss["_lev_csv_done"] = up.name
                st.rerun()
            else:
                warnbox("No leveraged or inverse funds found in that file (it needs a symbol and a name column).")
        except Exception as e:
            warnbox(f"Couldn't read the file: {type(e).__name__}: {e}")
    if not len(cat):
        warnbox("No fund list.")
        return
    names = list(ab["P"]["close"].columns) if ab is not None else list(bars)
    M = lev_map(cat, names, prefs)
    have = M[M["lev_long"] != ""] if len(M) else M
    single = cat[cat["kind"] == "single stock"]
    kpi_row([kpi_html("Funds", f"{len(cat):,}", f"{int((cat['side'] == 'long').sum())} long, {int((cat['side'] == 'short').sum())} inverse"),
             kpi_html("Single-stock funds", f"{len(single):,}", f"on {single['under'].replace('', np.nan).nunique()} stocks"),
             kpi_html("Your names with a fund", len(have), f"of {len(names)}, at ${prefs['lev_min_dv']:g}M+ a day", "good" if len(have) else ""),
             kpi_html("Using funds", "ON" if prefs["lev_prefer"] else "OFF", "Brief cards and the Screener", "good" if prefs["lev_prefer"] else "")])
    sec("1 · Your names that have a fund")
    if not len(have):
        note("None of the names loaded has a fund that passes your liquidity floor. Lower it, or load a fuller list.")
    else:
        Q = ab["P"] if ab is not None else None
        T = have.copy()
        if Q is not None:
            cl = Q["close"]
            T["close"] = cl.iloc[-1].reindex(T.index)
            rv = np.log(cl).diff().iloc[-21:].std()
            T["sigma_d"] = rv.reindex(T.index)
            T["drag"] = [lev_drag(abs(_n(x, np.nan)), _n(s_, np.nan), int(prefs["lev_hold"])) for x, s_ in zip(T["lev_long_x"], T["sigma_d"])]
        try:
            awS = aw_block(ab)["snap"] if ab is not None else None
            if awS is not None:
                T = T.join(awS[["vw_state", "vw_setup"]], how="left")
        except Exception:
            pass
        T = T.sort_values("lev_long_dv", ascending=False).reset_index()
        cols = [c_ for c_ in ("ticker", "close", "lev_long", "lev_long_x", "lev_long_dv", "lev_short", "lev_short_x", "lev_short_dv",
                              "lev_n", "sigma_d", "drag", "vw_state", "vw_setup") if c_ in T]
        show_df(T[cols], height=min(420, 40 + 35 * len(T)),
                column_config={"close": P_(format="%.2f"), "lev_long": st.column_config.TextColumn("long fund"),
                               "lev_long_x": P_("x", format="%.2g"), "lev_long_dv": P_("$M a day", format="%.0f"),
                               "lev_short": st.column_config.TextColumn("inverse fund"), "lev_short_x": P_("x", format="%.2g"),
                               "lev_short_dv": P_("$M a day ", format="%.0f"), "lev_n": P_("funds on it", format="%d"),
                               "sigma_d": P_("daily vol", format="percent"),
                               "drag": P_(f"drag, {int(prefs['lev_hold'])} sessions", format="percent",
                                          help="Expected variance drag of the long fund over your planned hold at the stock's 20-day volatility."),
                               "vw_state": st.column_config.TextColumn("AVWAP state"), "vw_setup": st.column_config.TextColumn("VWAP setup")})
        note("The long fund is what the Brief's cards use. Drag assumes the stock keeps its last month's volatility.")
    sec("2 · Index and sector funds, by the trend of what they lever")
    idx = cat[cat["kind"].isin(["index", "sector", "intl", "rates", "commodity", "crypto"]) & (cat["under"] != "")]
    rows = []
    for u, g in idx.groupby("under"):
        lo = lev_pick(cat, u, "long", float(prefs["lev_min_dv"]), float(prefs["lev_max"]), float(prefs["lev_single_max"]))
        sh = lev_pick(cat, u, "short", float(prefs["lev_min_dv"]), float(prefs["lev_max"]), float(prefs["lev_single_max"]))
        if lo is None and sh is None:
            continue
        b = bench_bars.get(u) if bench_bars else None
        if b is None and bars:
            b = bars.get(u)
        tr = r63 = np.nan
        if b is not None and len(b) > 260:
            try:
                tr = float(imk_trend(b["close"]).iloc[-1])
                r63 = float(b["close"].iloc[-1] / b["close"].iloc[-64] - 1)
            except Exception:
                pass
        rows.append({"levers": str(g["under_label"].iloc[0]), "etf": u, "kind": str(g["kind"].iloc[0]), "trend": tr, "r_3m": r63,
                     "long_fund": "" if lo is None else f"{lo['ticker']} {abs(lo['lev']):g}x",
                     "long_dv": np.nan if lo is None else _n(lo["dv_m"], np.nan),
                     "inverse_fund": "" if sh is None else f"{sh['ticker']} {abs(sh['lev']):g}x",
                     "inverse_dv": np.nan if sh is None else _n(sh["dv_m"], np.nan)})
    if rows:
        G = pd.DataFrame(rows).sort_values(["trend", "long_dv"], ascending=[False, False], na_position="last")
        show_df(G, height=min(520, 40 + 35 * len(G)),
                column_config={"levers": st.column_config.TextColumn("levers", width="medium"),
                               "trend": P_("trend (-1 to +1)", format="%+.2f", help="The trend score of Market > Intermarket on the ETF it levers."),
                               "r_3m": P_("3 months", format="percent"), "long_dv": P_("$M a day", format="%.0f"),
                               "long_fund": st.column_config.TextColumn("long fund"), "inverse_fund": st.column_config.TextColumn("inverse fund"),
                               "inverse_dv": P_("$M a day ", format="%.0f")})
        note("Trend is blank where the lab doesn't load that ETF. A 3x fund on the strongest groups is the leveraged way "
             "to trade a sector move; the inverse fund on the weakest is the short side.")
    sec("3 · Tracking check: has the fund delivered L x?")
    opts = list(cat[(cat["reset"] == "daily") & (cat["under"] != "") & (cat["dv_m"].fillna(0) >= float(prefs["lev_min_dv"]))]
                .sort_values("dv_m", ascending=False)["ticker"])
    if not opts:
        note("No fund passes the liquidity floor.")
    else:
        default = next((o for o in opts if o in set(have["lev_long"])), opts[0]) if len(have) else opts[0]
        ss.setdefault("lev_pick", default)
        if ss["lev_pick"] not in opts:
            ss["lev_pick"] = default
        pick = st.selectbox("Fund", opts, key="lev_pick",
                            format_func=lambda t: f"{t}: {cat.set_index('ticker').at[t, 'lev']:+g}x {cat.set_index('ticker').at[t, 'under_label']}")
        f_ = cat.set_index("ticker").loc[pick]
        u, L = str(f_["under"]), float(f_["lev"])
        ub = (bars or {}).get(u) if bars else None
        if ub is None:
            ub = (bench_bars or {}).get(u)
        try:
            if ub is None:
                got, _ = get_bars([u], 400, cfg["source"], cfg["key"], cfg["drop_partial"])
                ub = got.get(u)
            if cfg.get("source") == "demo":
                fund_c = lev_demo_fund(ub["close"], L) if ub is not None else None
            else:
                got, _ = get_bars([pick], 400, cfg["source"], cfg["key"], cfg["drop_partial"])
                fund_c = got[pick]["close"] if pick in got else None
        except Exception as e:
            fund_c = None
            note(f"Couldn't load the bars: {type(e).__name__}.")
        if ub is None or fund_c is None:
            note(f"No bars for {pick} or {u} from {cfg.get('source')}.")
        else:
            rows = []
            for look in (20, 60, 120):
                tk_ = lev_tracking(fund_c, ub["close"], L, look)
                if tk_:
                    rows.append({"window": f"{tk_['days']} sessions", **{k: tk_[k] for k in ("beta", "te", "under_ret", "naive", "fund_ret", "gap", "drag_model")}})
            if rows:
                show_df(pd.DataFrame(rows), column_config={
                    "beta": P_("daily beta", format="%+.2f", help=f"Should be close to {L:+g}."),
                    "te": P_("tracking error a year", format="percent"), "under_ret": P_(f"{u}", format="percent"),
                    "naive": P_(f"{L:+g}x {u}", format="percent"), "fund_ret": P_(f"{pick}", format="percent"),
                    "gap": P_("gap vs L x", format="percent", help="The fund's return less L x the underlying's: drag, fees and financing."),
                    "drag_model": P_("drag the volatility predicts", format="percent")})
            j = pd.concat([fund_c.rename("f"), ub["close"].rename("u")], axis=1).dropna().iloc[-121:]
            if len(j) > 20:
                ch = pd.DataFrame({"date": j.index, pick: j["f"] / j["f"].iloc[0] - 1,
                                   f"{L:+g}x {u}, held": L * (j["u"] / j["u"].iloc[0] - 1)})
                ch = ch.melt("date", var_name="line", value_name="ret")
                show_chart(_alt(alt.Chart(ch).mark_line(strokeWidth=1.6).encode(
                    x=alt.X("date:T", title=None), y=alt.Y("ret:Q", title=None, axis=alt.Axis(format="%")),
                    color=alt.Color("line:N", scale=alt.Scale(range=[C_ACCENT, C_BLUE]), legend=alt.Legend(orient="top", title=None, labelLimit=300)),
                    tooltip=["date:T", "line", alt.Tooltip("ret:Q", format="+.1%")]).properties(title="The fund against L x its underlying, last 120 sessions"), 240))
            note("The gap is what using the fund cost (or paid) against L x the stock over each window. Beta near L "
                 "and a small tracking error mean it does its daily job; a large negative gap in a choppy stretch is the drag."
                 + (" Demo: the fund's bars are simulated from the underlying." if cfg.get("source") == "demo" else ""))
    sec("4 · The plan in the fund")
    c = st.columns(5)
    e_ = c[0].number_input("Entry on the stock", 0.01, 1e6, 100.0, key="lev_pe")
    s_ = c[1].number_input("Stop on the stock", 0.01, 1e6, 95.0, key="lev_ps")
    L_ = c[2].selectbox("Fund leverage", [1.5, 2.0, 3.0], index=1, key="lev_pl", format_func=lambda x: f"{x:g}x")
    acct = c[3].number_input("Account", 0.0, 1e9, 100000.0, step=1000.0, key="lev_acct")
    rk = c[4].number_input("Risk per trade %", 0.05, 5.0, 0.5, step=0.05, key="lev_rk")
    pl = lev_plan(e_, s_, L_, 20.0, acct * rk / 100)
    if pl:
        sig_ = c[0].number_input("Stock's daily vol %", 0.2, 15.0, 3.0, step=0.1, key="lev_sig") / 100
        dr = {h: lev_drag(L_, sig_, h) for h in (5, 10, 20, 40, 60)}
        kpi_row([kpi_html("Stop in the stock", f"{pl['stock_risk_pct']:.1f}%", f"{pl['stock_shares']:,} shares = ${pl['stock_capital']:,.0f}"),
                 kpi_html("Stop in the fund", f"{pl['fund_risk_pct']:.1f}%", f"{L_:g}x the stock's on day one"),
                 kpi_html("Capital for the same risk", f"{pl['capital_frac']:.0%}", f"about ${pl['stock_capital'] * pl['capital_frac']:,.0f}", "good"),
                 kpi_html("Drag", f"{dr[10]:+.1%} / 10 sessions", f"{dr[20]:+.1%} / 20, {dr[60]:+.1%} / 60 at {sig_:.1%} a day", "warn" if dr[20] < -0.03 else "")])
        note("Fund shares = your dollar risk / (fund price x its stop distance). Past about 20 sessions in a volatile name, the drag eats a real part of a 2R target.")
    else:
        note("The stop must be under the entry.")
    sec("5 · The full list")
    c = st.columns([1.4, 1, 1, 1.4])
    kinds = c[0].multiselect("Kind", sorted(cat["kind"].unique()), key="lev_kinds")
    side = c[1].radio("Side", ["both", "long", "short"], horizontal=True, key="lev_side")
    mdv = c[2].number_input("Min $M a day", 0.0, 1e5, 0.0, key="lev_cat_dv")
    q = c[3].text_input("Search (ticker, name, what it levers)", key="lev_q")
    V = cat.copy()
    if kinds:
        V = V[V["kind"].isin(kinds)]
    if side != "both":
        V = V[V["side"] == side]
    if mdv > 0:
        V = V[V["dv_m"].fillna(0) >= mdv]
    if q:
        ql = q.lower()
        V = V[V.apply(lambda r: ql in f"{r['ticker']} {r['name']} {r['under']} {r['under_label']}".lower(), axis=1)]
    show_df(V[["ticker", "lev", "under", "under_label", "kind", "issuer", "reset", "dv_m", "name"]], height=min(520, 40 + 35 * len(V)),
            column_config={"lev": P_("x", format="%+.2g"), "under": st.column_config.TextColumn("levers"),
                           "under_label": st.column_config.TextColumn("what"), "dv_m": P_("$M a day", format="%.1f"),
                           "name": st.column_config.TextColumn("name", width="large")})
    st.download_button("Download the list (CSV)", V.to_csv(index=False), "leveraged_funds.csv", "text/csv", key="lev_dl")
    with st.expander("How leveraged funds work, and how the lab uses them"):
        st.markdown(LEV_GUIDE)


def lg_chunk(P: Dict[str, pd.DataFrame], spy: Optional[pd.Series], fams: Tuple[str, ...], setting: str,
             prm: Dict[str, Any]) -> Dict[str, Any]:
    """Events, labels and entry features for one block of names. Panels must share one date index."""
    o, h, l, c, v = (P[k].iloc[-MC_MAX_ROWS:].astype(float) for k in ("open", "high", "low", "close", "volume"))
    idx, cols = c.index, c.columns
    n = len(idx)
    H, cd, warm = int(prm["horizon"]), int(prm["cooldown"]), int(prm.get("warmup", LG_WARMUP))
    atr = _mc_atr(h, l, c, 14)
    s50, s200 = c.rolling(50, min_periods=50).mean(), c.rolling(200, min_periods=200).mean()
    low10 = l.rolling(10, min_periods=5).min()
    dv20 = (c * v).rolling(20, min_periods=15).mean()
    elig = (c >= float(prm["min_price"])) & (dv20 >= float(prm["min_dv"]) * 1e6)
    elig.iloc[:warm] = False
    elig_np = elig.to_numpy()
    stops: Dict[str, pd.DataFrame] = {"low10": low10, "day": l,
                                      "low2": pd.DataFrame(np.fmin(l.to_numpy(float), l.shift(1).to_numpy(float)),
                                                           index=idx, columns=cols)}
    sigs: Dict[str, pd.DataFrame] = {}
    nanf = pd.DataFrame(np.nan, index=idx, columns=cols)
    mfeat = {"mv": nanf, "mv_state": nanf, "imp": nanf, "w_macdv": nanf, "w_imp": nanf, "zlr_ratio": nanf, "zlr_adx": nanf}
    if "MACD" in fams:
        M = mc_panels({"open": o, "high": h, "low": l, "close": c}, setting)
        for key in MC_SETUPS:
            sigs[f"macd:{key}"] = M["S"][key]
        sigs["macd:bullx_raw"], sigs["macd:zerox_raw"] = M["bull_x"], M["zero_up"]
        stops["wave"] = M["D"]["wave_low"].astype(float)
        stops["pull"] = M["pull_low"].astype(float)
        mfeat = {"mv": M["mv"], "mv_state": M["state"].astype(float), "imp": M["imp"], "w_macdv": M["W"]["macdv"],
                 "w_imp": M["W"]["imp"], "zlr_ratio": M["zlr_ratio"], "zlr_adx": M["zlr_adx"]}
        del M
    T = tl_panels({"close": c, "volume": v})                # also feeds the ranker's LaunchPad features
    if "TraderLion" in fams:
        for key in ("full", "short", "deepvue", "power3"):
            sigs[f"tl:{key}"] = T[key]
    mas = T["mas"]
    stops["pad"] = pd.DataFrame(np.fmin(np.fmin(mas["SMA10"].to_numpy(float), mas["SMA21"].to_numpy(float)),
                                        mas["EMA23"].to_numpy(float)), index=idx, columns=cols)
    lp_on = (T["full"] | T["short"] | T["deepvue"]).astype(float)
    lp_spread = T["spread6"] * 100
    del T, mas
    wid = idx.to_period("W-FRI")                           # weekly 8 EMA as of each day (forming week = today's close)
    prev_e8 = c.groupby(wid).last().ewm(span=8, adjust=False).mean().shift(1).reindex(wid).set_axis(idx)
    e8 = 2.0 / 9.0 * c + 7.0 / 9.0 * prev_e8
    rs_nh = nanf
    if spy is not None and len(spy):
        rs_ = c.div(spy.reindex(idx).ffill(), axis=0)
        rs_nh = (rs_ >= rs_.rolling(252, min_periods=200).max() * 0.99999).astype(float).where(rs_.notna())
    if "RS 8-week" in fams and spy is not None and len(spy):
        R8 = lg_rs8_signals(c, h, spy)
        stops["e8w"] = R8.pop("_e8")
        sigs.update(R8)
    if "LBR" in fams:
        sigs.update(lg_lbr_signals(o, h, l, c))
    if "Trend" in fams:                                    # Market > Price action > Trend systems, entries only
        sigs["trend:dc20"] = h > h.rolling(20, min_periods=20).max().shift(1)
        sigs["trend:dc55"] = h > h.rolling(55, min_periods=55).max().shift(1)
        ef, es = c.ewm(span=20, adjust=False).mean(), c.ewm(span=200, adjust=False, min_periods=200).mean()
        sigs["trend:ema_x"] = (ef > es) & (ef.shift(1) <= es.shift(1)) & es.shift(1).notna()
        n20 = _mc_atr(h, l, c, 20)
        stops["n2"] = c - 2.0 * n20
        stops["atr3"] = c - 3.0 * atr
        del ef, es, n20
    with np.errstate(invalid="ignore", divide="ignore"):    # the 101 Alphas' raw inputs (Top scans on the Brief)
        pc1, ph1, pl1 = c.shift(1), h.shift(1), l.shift(1)
        gp = o / pc1 - 1
        body101 = ((c - o) / (h - l).where(h > l)).clip(-1.0, 1.0)
        zone = pd.DataFrame(np.select([(o > ph1) & (gp > 0), (o < pl1) & (gp < 0), gp >= LG_GAP_FLAT, gp <= -LG_GAP_FLAT,
                                       gp.notna()], [2.0, -2.0, 1.0, -1.0, 0.0], np.nan), index=idx, columns=cols)
        vw = P["vwap"].iloc[-MC_MAX_ROWS:].astype(float).reindex(index=idx, columns=cols) if "vwap" in P else None
        vwap_pos = ((c / vw.where(vw > 0) - 1) * 100) if vw is not None else nanf
    AW = aw_panels(o, h, l, c, v, aw_typical(h, l, c, vw), atr, s50, s200)   # anchored VWAPs: features for every setup
    if "VWAP" in fams:
        for k_ in ("reclaim", "pull_lo", "pull_ev", "pinch", "cross_raw"):
            sigs[f"vw:{k_}"] = AW["S"][k_]
    stops.update(AW["stops"])
    aw_feat = {"aw_hi_pos": AW["pos_hi"], "aw_lo_pos": AW["pos_lo"], "aw_state": AW["state"]}
    del AW
    if "Pullback" in fams:                                # short-term oversold inside an uptrend (Quantified Strategies)
        ind = lg_oversold(o, h, l, c)
        upt = (c > s200) & (c > s50) & (s50 > s50.shift(10))
        sigs["pb:ibs"] = upt & (ind["ibs"] < LG_IBS_LO)
        sigs["pb:rsi2"] = upt & (ind["rsi2"] < LG_RSI2_LO)
        sigs["pb:down3"] = upt & (c < c.shift(1)) & (c.shift(1) < c.shift(2)) & (c.shift(2) < c.shift(3))
        sigs["pb:low5"] = upt & (c <= c.rolling(5, min_periods=5).min())
        if "n2" not in stops:
            stops["n2"] = c - 2.0 * _mc_atr(h, l, c, 20)
        del ind, upt
    if "Zanger" in fams:                                   # a base breakout with (and, as the control, without) volume
        Z = zg_signals(h, l, c, v, s50, atr)
        sigs["zg:vol"], sigs["zg:quiet"] = Z["vol"], Z["quiet"]
        stops["zgb"] = Z["stop"]
        del Z
    if "EP" in fams:                                       # Stockbee's EP 9 million, stop at the EP day's low
        E9 = ep9m_panels({"high": h, "low": l, "close": c, "volume": v})
        sigs["ep:9m"], sigs["ep:9m_dcr"] = E9["sig"], E9["strong"]
        del E9
    if "Gap" in fams:
        big = gp >= LG_GAP_MIN
        hi_, in_ = big & (o > ph1), big & (o <= ph1)
        sigs.update({"gap:hi_any": hi_, "gap:hi_strong": hi_ & (body101 >= 0.5), "gap:hi_faded": hi_ & (body101 < 0),
                     "gap:in_any": in_, "gap:in_strong": in_ & (body101 >= 0.5), "gap:in_faded": in_ & (body101 < 0)})
    # entry features (as of the signal day's close)
    spy_al = spy.reindex(idx).ffill() if spy is not None else None
    with np.errstate(invalid="ignore", divide="ignore"):
        feats = {
            "atr_pct": atr / c * 100, "ext50": (c / s50 - 1) * 100, "ext200": (c / s200 - 1) * 100,
            "rs63": ((c / c.shift(63) - 1).sub(spy_al / spy_al.shift(63) - 1, axis=0) * 100) if spy_al is not None else nanf,
            "dist_hi252": (c / h.rolling(252, min_periods=120).max() - 1) * 100,
            "vol_ratio": v / v.rolling(50, min_periods=20).mean().shift(1),
            "adr20": (h / l - 1).rolling(20, min_periods=15).mean() * 100,
            "gap": (o / c.shift(1) - 1) * 100, "clv": (c - l) / (h - l).replace(0, np.nan), "dv20_m": dv20 / 1e6,
            "above200": (c > s200).astype(float).where(s200.notna()), "ext8w": (c / e8 - 1) * 100,
            "lp_spread6": lp_spread, "lp_on": lp_on.where(lp_spread.notna()), "rs_nh": rs_nh,
            "gap_hi": (o / ph1 - 1) * 100, "body101": body101, "gap_zone": zone, "vwap_pos": vwap_pos, **aw_feat, **mfeat}
    F = {k: x.to_numpy(np.float32) for k, x in feats.items()}
    O, Hh, L, C, A = (x.to_numpy(np.float32) for x in (o, h, l, c, atr))
    S = {k: x.to_numpy(float) for k, x in stops.items()}
    ids, II, JJ, LV = [], [], [], []
    for sid, sig in sigs.items():
        ev = lg_first(sig, cd).to_numpy() & elig_np
        ii, jj = np.nonzero(ev)
        if not len(ii):
            continue
        lvl = S.get(LG_SETUPS[sid][2], S["low10"])[ii, jj]
        ids.append(np.full(len(ii), sid, dtype=object))
        II.append(ii)
        JJ.append(jj)
        LV.append(lvl)
    # baseline: every uptrend name (close above a rising 50-day), every base_step-th session
    up = ((c > s50) & (s50 > s50.shift(5))).to_numpy() & elig_np
    step = max(1, int(prm.get("base_step", 5)))
    rows_ok = np.zeros(n, bool)
    rows_ok[warm::step] = True
    bi, bj = np.nonzero(up & rows_ok[:, None])
    if len(bi):
        ids.append(np.full(len(bi), "base:uptrend", dtype=object))
        II.append(bi)
        JJ.append(bj)
        LV.append(S["low10"][bi, bj])
    # same-date uptrend average of the next-open -> close-at-i+H return, for the edge (xs) column
    fwd = (c.shift(-H) / o.shift(-1) - 1).to_numpy(float)
    fu = np.where(up & np.isfinite(fwd), fwd, np.nan)
    base_sum, base_cnt = np.nansum(fu, axis=1), np.isfinite(fu).sum(axis=1)
    if not II:
        return {"ev": pd.DataFrame(), "base_sum": base_sum, "base_cnt": base_cnt}
    sid_a, ii, jj, lvl = np.concatenate(ids), np.concatenate(II), np.concatenate(JJ), np.concatenate(LV)
    ref = C[ii, jj].astype(float)
    bad = ~np.isfinite(lvl) | (lvl >= ref)
    lvl = np.where(bad, S["low10"][ii, jj], lvl)                       # fallback 1: 10-day low
    bad = ~np.isfinite(lvl) | (lvl >= ref)
    lvl = np.where(bad, ref - A[ii, jj], lvl)                          # fallback 2: one ATR under the close
    with np.errstate(invalid="ignore", divide="ignore"):
        plan_risk = ((ref - lvl) / A[ii, jj]).astype(np.float32)       # risk known at the signal close (no entry price yet)
    tlm = lg_time_limits(prm)
    tl_sid = {s_: tlm.get(LG_SETUPS[s_][0], int(prm["horizon"])) for s_ in set(sid_a)}
    hz_ev = np.array([tl_sid[s_] for s_ in sid_a], float)
    exr = lg_exit_rules(prm)
    ex_sid = {s_: exr.get(LG_SETUPS[s_][0], "target") for s_ in set(sid_a)}
    tr_ev = np.array([ex_sid[s_] == "trail" for s_ in sid_a], bool)
    tg_ev = np.where(tr_ev, np.inf, float(prm["tgt"]))
    kind = str(prm.get("trail", "chandelier"))
    ma_np = (c.rolling(int(prm.get("trail_ma", 21)), min_periods=int(prm.get("trail_ma", 21))).mean().to_numpy(np.float32)
             if kind == "ma" and tr_ev.any() else None)
    sp_np = spread_panel({"high": h, "low": l, "close": c}, str(prm.get("spread_m", "ar"))).to_numpy(float)
    spread_ev = sp_np[ii, jj]                                          # estimated at the signal close: known then
    cost_ev = float(prm["cost"])
    if prm.get("cost_mode", "flat") == "spread":
        cost_ev = float(prm["cost"]) + np.where(np.isfinite(spread_ev), spread_ev, np.nanmedian(spread_ev)) / 2 * 1e4
    lab = lg_label(O, Hh, L, C, A, ii, jj, lvl, prm["mode"], int(prm["win"]), tg_ev, hz_ev,
                   float(prm["cap"]), 0.5, cost_ev, trail=tr_ev, trail_kind=kind,
                   trail_k=float(prm.get("trail_k", 3.0)), ma=ma_np, mark_open=bool(prm.get("mark_open", False)))
    out = pd.DataFrame({"setup": sid_a, "ticker": np.asarray(cols)[jj], "i": ii, "date": idx[ii],
                        "status": lab["status"], "outcome": lab["outcome"], "entry": lab["entry"], "stop": lab["stop"],
                        "target": lab["target"], "exit_px": lab["exit"], "risk": lab["risk"], "r": lab["r"],
                        "ret": lab["ret"], "mfe_r": lab["mfe_r"], "mae_r": lab["mae_r"], "hold": lab["hold"],
                        "capped": lab["capped"], "fwd": fwd[ii, jj],
                        "exit_date": pd.DatetimeIndex(idx[np.clip(lab["exit_i"], 0, n - 1)]).where(lab["exit_i"] >= 0)})
    with np.errstate(invalid="ignore", divide="ignore"):
        out["risk_atr"] = (lab["risk"] / A[ii, jj]).astype(np.float32)
    out["plan_risk_atr"] = plan_risk
    out["spread_bp"] = (spread_ev * 1e4).astype(np.float32)
    out["cost_bp"] = (np.broadcast_to(np.asarray(cost_ev, float), (len(ii),)) * 1.0).astype(np.float32)
    out["tlimit"] = hz_ev.astype(np.int16)
    out["exit_rule"] = np.where(tr_ev, "trail", "target")
    for k, arr in F.items():
        out[k] = arr[ii, jj]
    return {"ev": out, "base_sum": base_sum, "base_cnt": base_cnt}


def lg_spy_context(spy: Optional[pd.Series], clim: Optional[Dict[str, Any]], dates: pd.DatetimeIndex) -> pd.DataFrame:
    """SPY cycle (50/200-day), SPY 20-day return and the climate chip on each date."""
    out = pd.DataFrame(index=dates)
    if spy is not None and len(spy):
        s50, s200 = spy.rolling(50, min_periods=50).mean(), spy.rolling(200, min_periods=200).mean()
        a200, a50 = spy > s200, spy > s50
        code = np.select([a200 & a50, a200 & ~a50, ~a200 & ~a50, ~a200 & a50], [0, 1, 2, 3], default=-1)
        cyc = pd.Series(np.where(s200.notna(), code, -1), index=spy.index)
        out["spy_cycle"] = [LG_CYCLE[k] if k >= 0 else "" for k in cyc.reindex(dates, method="ffill").fillna(-1).astype(int)]
        out["spy_r20"] = ((spy / spy.shift(20) - 1) * 100).reindex(dates, method="ffill").to_numpy()
    else:
        out["spy_cycle"], out["spy_r20"] = "", np.nan
    try:
        st_ = clim["hist"]["sticky"] if clim else None
        out["climate"] = st_.reindex(dates, method="ffill").fillna("").astype(str).to_numpy() if st_ is not None else ""
    except Exception:
        out["climate"] = ""
    f = (clim or {}).get("f")                              # the Market > Climate inputs, as of each date
    for k_ in LG_CLIM_COLS:
        try:
            out[k_] = f[k_].reindex(dates, method="ffill").to_numpy(float) if f is not None and k_ in f else np.nan
        except Exception:
            out[k_] = np.nan
    try:
        hv = clim["lab"]["hmm_vol"] if clim and "lab" in clim else None
        out["hmm_vol"] = hv.reindex(dates, method="ffill").fillna("").astype(str).to_numpy() if hv is not None else ""
    except Exception:
        out["hmm_vol"] = ""
    gf = (clim or {}).get("ilm")                           # Market > Climate, Ilmanen lens, as of each date
    for k_ in ILM_LEDGER_NUM:
        try:
            out[k_] = gf[k_].reindex(dates, method="ffill").to_numpy(float) if gf is not None and k_ in gf else np.nan
        except Exception:
            out[k_] = np.nan
    for k_ in ILM_LEDGER_CAT:
        try:
            out[k_] = gf[k_].reindex(dates, method="ffill").fillna("").astype(str).to_numpy() if gf is not None and k_ in gf else ""
        except Exception:
            out[k_] = ""
    kf = (clim or {}).get("imk")                           # Market > Intermarket, as of each date
    for k_ in IMK_LEDGER_NUM:
        try:
            out[k_] = kf[k_].reindex(dates, method="ffill").to_numpy(float) if kf is not None and k_ in kf else np.nan
        except Exception:
            out[k_] = np.nan
    for k_ in IMK_LEDGER_CAT:
        try:
            out[k_] = kf[k_].reindex(dates, method="ffill").fillna("").astype(str).to_numpy() if kf is not None and k_ in kf else ""
        except Exception:
            out[k_] = ""
    nf = (clim or {}).get("nar")                           # Market > Narratives, as of each date
    for k_ in NAR_LEDGER_NUM:
        try:
            out[k_] = nf[k_].reindex(dates, method="ffill").to_numpy(float) if nf is not None and k_ in nf else np.nan
        except Exception:
            out[k_] = np.nan
    for k_ in NAR_LEDGER_CAT:
        try:
            out[k_] = nf[k_].reindex(dates, method="ffill").fillna("").astype(str).to_numpy() if nf is not None and k_ in nf else ""
        except Exception:
            out[k_] = ""
    return out


def lg_confluence(ev: pd.DataFrame, look: int = 3) -> np.ndarray:
    """For each event: how many distinct setups fired on the same name over the last `look` sessions, itself included
    (reference rows and the ADX duplicate of the fly-by don't count). Only past and same-day signals are used."""
    if not len(ev):
        return np.zeros(0)
    base = ev.loc[~ev["setup"].isin(LG_CONFLUENCE_SKIP), ["ticker", "i", "setup"]]
    active = pd.concat([base.assign(i=base["i"] + w) for w in range(look + 1)], ignore_index=True)
    cnt = active.drop_duplicates().groupby(["ticker", "i"]).size()
    key = pd.MultiIndex.from_arrays([ev["ticker"].to_numpy(), ev["i"].to_numpy()])
    return cnt.reindex(key).fillna(0).to_numpy(np.float32)


def lg_rs_rating(c: pd.DataFrame) -> pd.DataFrame:
    """IBD-style RS rating, 1-99: 0.4*C/C63 + 0.2*C/C126 + 0.2*C/C189 + 0.2*C/C252, ranked across the universe each day."""
    raw = 0.4 * (c / c.shift(63)) + 0.2 * (c / c.shift(126)) + 0.2 * (c / c.shift(189)) + 0.2 * (c / c.shift(252))
    return (raw.rank(axis=1, pct=True) * 98 + 1).astype("float32")


def industry_rs_panels(c: pd.DataFrame, groups: Dict[str, str]) -> Dict[str, pd.DataFrame]:
    """Moskowitz & Grinblatt (1999): industry momentum explains much of stock momentum. For each name and date: its
    group's average IBD-style RS rating ranked across groups (1-99), and the name's own RS rating minus its group's
    average (a leader in a leading group scores high on both). Groups come from resolve_groups (industry, or the theme
    for small industries); names without a group are NaN."""
    rs = lg_rs_rating(c.astype(float))
    g = pd.Series(groups).reindex(c.columns)
    if g.notna().sum() < 10:
        nan_ = pd.DataFrame(np.nan, index=c.index, columns=c.columns)
        return {"ind_rs": nan_, "rs_vs_ind": nan_}
    member = rs.loc[:, g.notna().to_numpy()]
    gm = member.T.groupby(g[g.notna()].to_numpy()).mean().T                     # dates x groups
    size = g.value_counts()
    gm = gm.loc[:, [k for k in gm.columns if size.get(k, 0) >= 3]]
    grank = gm.rank(axis=1, pct=True) * 98 + 1
    keys = g.fillna("__none__").to_numpy()
    ind_rs = grank.reindex(columns=keys)
    ind_rs.columns = c.columns
    gmean = gm.reindex(columns=keys)
    gmean.columns = c.columns
    return {"ind_rs": ind_rs.astype("float32"), "rs_vs_ind": (rs - gmean).astype("float32")}


def lg_run(P: Dict[str, pd.DataFrame], spy: Optional[pd.Series], clim: Optional[Dict[str, Any]], fams: Tuple[str, ...],
           setting: str, prm: Dict[str, Any], label: str, progress=None, chunk: int = LG_CHUNK,
           extra: Optional[Dict[str, pd.DataFrame]] = None) -> Dict[str, Any]:
    """The ledger for one universe: names processed in blocks so a whole-market panel fits in memory.
    `extra` adds name-by-date panels as event features (the list universe passes its alpha composite)."""
    t0 = time.time()
    P = {k: P[k].iloc[-MC_MAX_ROWS:] for k in ("open", "high", "low", "close", "volume", "vwap") if k in P}
    idx = P["close"].index
    cols = list(P["close"].columns)
    cfull = P["close"].astype(float)
    rs_rating = lg_rs_rating(cfull)                        # cross-sectional: needs every name at once
    rs_tf = rs_tf_count(rs_rank_panels(cfull))             # Stocks > RS leaders: time frames in the top 20%
    res_alpha = ((resilience_panels(cfull, spy)["down_alpha"].rank(axis=1, pct=True) * 98 + 1).astype("float32")
                 if spy is not None else None)               # resilience, ranked across the universe that day
    s50 = cfull.rolling(50, min_periods=50).mean()
    with np.errstate(invalid="ignore"):
        breadth50 = ((cfull > s50).sum(axis=1) / s50.notna().sum(axis=1).replace(0, np.nan)).to_numpy(float)
    try:                                                   # the Brief's market condition, with this universe's breadth
        bcond = (brief_cond_series(spy, cfull, P["volume"].astype(float)).to_numpy(object)
                 if spy is not None and len(spy) else np.full(len(idx), "", dtype=object))
    except Exception:
        bcond = np.full(len(idx), "", dtype=object)
    del cfull, s50
    base_sum, base_cnt = np.zeros(len(idx)), np.zeros(len(idx))
    parts = []
    nb = max(1, math.ceil(len(cols) / chunk))
    for b in range(nb):
        cc = cols[b * chunk:(b + 1) * chunk]
        if progress is not None:
            progress.progress(b / nb, text=f"{label}: names {b * chunk + 1}-{b * chunk + len(cc)} of {len(cols)}")
        res = lg_chunk({k: P[k][cc] for k in P}, spy, fams, setting, prm)
        base_sum += res["base_sum"]
        base_cnt += res["base_cnt"]
        if len(res["ev"]):
            parts.append(res["ev"])
    if progress is not None:
        progress.progress(1.0, text=f"{label}: scoring")
    ev = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame()
    base_up = pd.Series(np.where(base_cnt > 0, base_sum / np.maximum(base_cnt, 1), np.nan), index=idx)
    if len(ev):
        ev["xs"] = (ev["fwd"].to_numpy() - base_up.to_numpy()[ev["i"].to_numpy()]).astype(float)
        ctx = lg_spy_context(spy, clim, idx)
        for k_ in ctx.columns:
            ev[k_] = ctx[k_].to_numpy()[ev["i"].to_numpy()]
        ev["family"] = ev["setup"].map(lambda s: LG_SETUPS[s][0])
        ev["outcome_txt"] = ev["outcome"].map(LG_OUTCOME).fillna("")
        ev["status_txt"] = ev["status"].map(LG_STATUS)
        ii_ = ev["i"].to_numpy()
        jj_ = pd.Index(cols).get_indexer(ev["ticker"].to_numpy())
        ev["rs_rating"] = rs_rating.to_numpy()[ii_, jj_]
        ev["rs_tf"] = rs_tf.to_numpy()[ii_, jj_]
        ev["res_alpha"] = res_alpha.to_numpy()[ii_, jj_] if res_alpha is not None else np.nan
        ev["breadth50"] = breadth50[ii_].astype(np.float32)
        ev["bcond"] = bcond[ii_]
        ev["n_setups"] = lg_confluence(ev)
        ev["log_dv"] = np.log10(ev["dv20_m"].clip(lower=0.01)).astype(np.float32)
        for k_, pan in (extra or {}).items():
            try:
                pa = pan.reindex(index=idx, columns=cols).to_numpy(float)
                ev[k_] = pa[ii_, jj_].astype(np.float32)
            except Exception:
                ev[k_] = np.nan
    return {"ev": ev, "base_up": base_up, "label": label, "n_names": len(cols), "first": idx[0], "last": idx[-1],
            "secs": time.time() - t0, "prm": dict(prm), "fams": tuple(fams), "setting": setting}


def lg_nw(x: np.ndarray, lags: int) -> Tuple[float, float]:
    """Mean and Newey-West (Bartlett) standard error of a series."""
    x = np.asarray(x, float)
    x = x[np.isfinite(x)]
    n = len(x)
    if n < 3:
        return (float(x.mean()) if n else np.nan), np.nan
    mu = float(x.mean())
    e = x - mu
    s = float(e @ e) / n
    L = int(min(max(lags, 0), n - 1))
    for k in range(1, L + 1):
        s += 2.0 * (1.0 - k / (L + 1.0)) * float(e[k:] @ e[:-k]) / n
    return mu, math.sqrt(max(s, 1e-18) / n)


def lg_bh(p: np.ndarray) -> np.ndarray:
    """Benjamini-Hochberg q-values (NaN p stays NaN and doesn't count toward the family)."""
    p = np.asarray(p, float)
    q = np.full(p.shape, np.nan)
    ok = np.isfinite(p)
    m = int(ok.sum())
    if not m:
        return q
    pv = p[ok]
    order = np.argsort(pv)
    ranked = pv[order] * m / np.arange(1, m + 1)
    ranked = np.minimum.accumulate(ranked[::-1])[::-1]
    out = np.empty(m)
    out[order] = np.minimum(ranked, 1.0)
    q[ok] = out
    return q


def nyse_holidays(start, end) -> pd.DatetimeIndex:
    """NYSE full-day holidays (rules, not a list): New Year's (Sunday to Monday), MLK, Presidents, Good Friday,
    Memorial, Juneteenth (from 2022), Independence, Labor, Thanksgiving, Christmas (nearest weekday)."""
    from pandas.tseries.holiday import (AbstractHolidayCalendar, GoodFriday, Holiday, USLaborDay, USMartinLutherKingJr,
                                        USMemorialDay, USPresidentsDay, USThanksgivingDay, nearest_workday, sunday_to_monday)

    class _NYSE(AbstractHolidayCalendar):
        rules = [Holiday("NewYear", month=1, day=1, observance=sunday_to_monday), USMartinLutherKingJr, USPresidentsDay,
                 GoodFriday, USMemorialDay, Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01",
                                                    observance=nearest_workday),
                 Holiday("July4", month=7, day=4, observance=nearest_workday), USLaborDay, USThanksgivingDay,
                 Holiday("Christmas", month=12, day=25, observance=nearest_workday)]
    return _NYSE().holidays(pd.Timestamp(start), pd.Timestamp(end))


def lg_calendar(dates) -> pd.DataFrame:
    """For each signal date, the entry session (the next trading day) and where it sits: its place in the month
    from the start and from the end, its weekday, and whether it falls in an options-expiration week."""
    d = pd.DatetimeIndex(pd.to_datetime(dates)).normalize()
    if not len(d):
        return pd.DataFrame(index=d)
    lo, hi = d.min() - pd.Timedelta(days=40), d.max() + pd.Timedelta(days=40)
    days = pd.bdate_range(lo, hi)
    days = days[~days.isin(nyse_holidays(lo, hi))]
    pos = days.searchsorted(d, side="right")                       # the next trading day after the signal
    ent = days[np.clip(pos, 0, len(days) - 1)]
    s_ = pd.Series(np.arange(len(days)), index=days)
    per = days.to_period("M")
    first = s_.groupby(per).transform("min")
    last = s_.groupby(per).transform("max")
    from_start = (s_ - first + 1).reindex(ent).to_numpy()
    from_end = (last - s_ + 1).reindex(ent).to_numpy()
    third_fri = pd.DatetimeIndex([pd.Timestamp(y, m_, 15) + pd.Timedelta(days=(4 - pd.Timestamp(y, m_, 15).weekday()) % 7)
                                  for y, m_ in zip(ent.year, ent.month)])
    wk = ent.to_period("W-FRI")
    return pd.DataFrame({"entry_day": ent, "from_start": from_start, "from_end": from_end, "weekday": ent.day_name(),
                         "opex_week": wk == third_fri.to_period("W-FRI")}, index=range(len(d)))


def lg_split_col(ev: pd.DataFrame, split: str) -> Optional[pd.Series]:
    if split in ("tom", "opex", "weekday"):
        K = lg_calendar(ev["date"])
        if split == "tom":
            v = np.where((K["from_end"] <= 4) | (K["from_start"] <= 3), "turn of the month", "rest of the month")
        elif split == "opex":
            v = np.where(K["opex_week"], "options-expiration week", "other weeks")
        else:
            v = K["weekday"].to_numpy()
        return pd.Series(v, index=ev.index)
    if split == "cycle":
        return ev["spy_cycle"].replace("", "n/a")
    if split == "climate":
        return ev["climate"].replace("", "n/a")
    if split == "bcond":
        return (ev["bcond"].astype(str).replace("", "n/a") if "bcond" in ev else pd.Series("n/a", index=ev.index))
    if split in ("gate_parker", "gate_recent"):
        return pd.Series(gate_labels(ev, split.split("_")[1]), index=ev.index)
    col = {"narrative": "nar_tag", "quad": "nar_quad", "curve": "curve_regime", "jump": "nar_jump", "style": "style_tape",
           "imk_confirm": "imk_confirm", "imk_dow": "imk_dow", "imk_flow": "imk_flow", "imk_quad_tape": "imk_quad_tape", "imk_def": "imk_def",
           "signature": "ilm_confirm"}.get(split)
    if col:
        return (ev[col].replace("", "n/a") if col in ev else pd.Series("n/a", index=ev.index))
    if split == "rstf":
        v = ev["rs_tf"] if "rs_tf" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v >= 4, v >= 2, v >= 0], ["4-5 of 5", "2-3 of 5", "0-1 of 5"], "n/a"), index=ev.index)
    if split == "resil":
        v = ev["res_alpha"] if "res_alpha" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v > 67, v > 34, v >= 0], ["most resilient third", "middle third", "least resilient third"],
                                   "n/a"), index=ev.index)
    if split == "indrs":
        v = ev["ind_rs"] if "ind_rs" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v > 67, v > 34, v >= 0], ["leading groups (top third)", "middle third", "lagging groups"],
                                   "n/a"), index=ev.index)
    if split in ("lead_conc", "ga_rule_lead"):
        if "lead_conc_pct" not in ev:
            return pd.Series("n/a (rebuild the ledger)", index=ev.index)
        if split == "lead_conc":
            return ga_entropy_regime(ev["lead_conc_pct"]).set_axis(ev.index)
        top = float(st.session_state.get("lg_ga_top", 0.2))
        rl = ga_rule_labels(ev["ga_gpct"], ev["ga_bucket"], ev["ga_leader"], top)
        short = rl.map({"The rule: RS leader, leading group, R:R 3+": "The rule", "RS leader, other": "Other RS leaders",
                        "Not an RS leader": "Not an RS leader"}).fillna("n/a")
        v = ev["lead_conc_pct"].astype(float)
        half = np.where(v >= 0.5, "narrower leadership than usual", np.where(v < 0.5, "broader leadership than usual", ""))
        lab = short.to_numpy(object) + " · " + half
        return pd.Series(np.where((short.to_numpy() == "n/a") | ~np.isfinite(v.to_numpy()), "n/a", lab), index=ev.index)
    if split in ("ga_rule", "ga_group", "ga_rr"):
        if "ga_gpct" not in ev:
            return pd.Series("n/a (rebuild the ledger)", index=ev.index)
        top = float(st.session_state.get("lg_ga_top", 0.2))
        if split == "ga_rule":
            return ga_rule_labels(ev["ga_gpct"], ev["ga_bucket"], ev["ga_leader"], top)
        if split == "ga_group":
            return ga_group_labels(ev["ga_gpct"], top)
        return ga_rr_labels(ev["ga_bucket"])
    if split == "gapzone":
        v = ev["gap_zone"] if "gap_zone" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v == 2, v == 1, v == 0, v == -1, v == -2], LG_GAPZONE_LABELS, "n/a"), index=ev.index)
    if split == "body":
        v = ev["body101"] if "body101" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v >= 0.5, v >= 0, v > -0.5, v >= -1], ["+0.5 to +1: strong close", "0 to +0.5",
                                                                           "-0.5 to 0", "-1 to -0.5: weak close"], "n/a"),
                         index=ev.index)
    if split == "vwap":
        v = ev["vwap_pos"] if "vwap_pos" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v > 0, v <= 0], ["close above VWAP", "close at or below VWAP"], "n/a"), index=ev.index)
    if split == "aw_state":
        v = ev["aw_state"] if "aw_state" in ev else None
        if v is None:
            return pd.Series("n/a (rebuild the ledger)", index=ev.index)
        return v.map(lambda x: aw_state_label(x) or "n/a")
    if split == "aw_hi":
        if "aw_hi_pos" not in ev:
            return pd.Series("n/a (rebuild the ledger)", index=ev.index)
        v = ev["aw_hi_pos"]
        return pd.Series(np.select([v < -10, v < 0, v < 5, v < 15, v >= 15], ["10%+ under it", "0-10% under it", "0-5% over it",
                                                                            "5-15% over it", "15%+ over it"], "n/a"), index=ev.index)
    if split == "spread":
        v = ev["spread_bp"] if "spread_bp" in ev else pd.Series(np.nan, index=ev.index)
        return pd.Series(np.select([v < 10, v < 30, v < 80, v >= 80], ["under 10 bp", "10-30 bp", "30-80 bp", "80 bp or more"],
                                   "n/a"), index=ev.index)
    if split == "above200":
        return pd.Series(np.where(ev["above200"] == 1, "above 200-day", np.where(ev["above200"] == 0, "below 200-day", "n/a")),
                         index=ev.index)
    if split == "state":
        return ev["mv_state"].map(lambda k: MC_STATES[int(k)] if np.isfinite(k) and 0 <= k < len(MC_STATES) else "n/a")
    if split == "year":
        return ev["date"].dt.year.astype(str)
    return None


# ---- Deflated Sharpe, spreads from daily bars, excursions (MAE / MFE) ------------------------------------------
# Deflated Sharpe Ratio: Bailey & Lopez de Prado (2014), "The Deflated Sharpe Ratio: Correcting for Selection Bias,
# Backtest Overfitting and Non-Normality". The Probabilistic Sharpe Ratio (Bailey & Lopez de Prado 2012) is the chance
# the true Sharpe beats a benchmark, given the sample's length, skew and kurtosis; the deflated version sets that
# benchmark to the Sharpe the best of N unskilled trials would show by luck.
# Spreads: Corwin & Schultz (2012) from two days' highs and lows; Abdi & Ranaldo (2017) from the close against the
# day's and the next day's mid-range. Both estimate the stock's bid-ask spread from daily bars alone.
# Excursions: Sweeney's MAE / MFE study ("Maximum Adverse Excursion", 1997) and Faith's edge ratio ("Way of the
# Turtle", 2007), read from the ledger's own trades.

DSR_GAMMA = 0.5772156649015329                     # Euler-Mascheroni
SPREAD_W = 21                                      # trailing sessions for the spread estimate
SPREAD_CAP = 0.05                                  # estimates above 5% of price are treated as noise and capped
SPREAD_METHODS = {"ar": "Abdi-Ranaldo (close vs mid-range)", "cs": "Corwin-Schultz (two-day high-low)",
                  "avg": "Average of the two"}
LG_COST_MODES = {"flat": "Flat bp per side", "spread": "Half the estimated spread + flat bp, per side"}


def sharpe_stats(x: np.ndarray, se_nw: Optional[float] = None) -> Dict[str, float]:
    """Per-observation Sharpe ratio of a return series, its skew and (non-excess) kurtosis, and the effective number
    of independent observations: sample variance over the Newey-West variance of the mean when that is given, so
    overlapping trades are not counted as independent."""
    x = np.asarray(x, float)
    x = x[np.isfinite(x)]
    n = len(x)
    if n < 3:
        return {"sr": np.nan, "skew": np.nan, "kurt": np.nan, "n_obs": n, "n_eff": np.nan}
    mu, sd = float(x.mean()), float(x.std(ddof=1))
    if not sd > 0:
        return {"sr": np.nan, "skew": np.nan, "kurt": np.nan, "n_obs": n, "n_eff": np.nan}
    z = (x - mu) / sd
    skew = float(np.mean(z ** 3))
    kurt = float(np.mean(z ** 4))
    n_eff = float(n)
    if se_nw is not None and np.isfinite(se_nw) and se_nw > 0:
        n_eff = float(np.clip(sd ** 2 / se_nw ** 2, 2.0, n))
    return {"sr": mu / sd, "skew": skew, "kurt": kurt, "n_obs": n, "n_eff": n_eff}


def psr(sr: float, sr_star: float, n_eff: float, skew: float, kurt: float) -> float:
    """Probabilistic Sharpe Ratio: P(true SR > sr_star) = Phi((SR - SR*) sqrt(n - 1) / sqrt(1 - g3 SR + (g4 - 1)/4 SR^2))."""
    if not all(np.isfinite(v) for v in (sr, sr_star, n_eff, skew, kurt)) or n_eff < 2:
        return np.nan
    den = 1.0 - skew * sr + (kurt - 1.0) / 4.0 * sr * sr
    if den <= 0:
        return np.nan
    return float(_ncdf((sr - sr_star) * math.sqrt(n_eff - 1.0) / math.sqrt(den)))


def expected_max_sr(n_trials: int, var_sr: float) -> float:
    """E[max SR] over n_trials unskilled trials with cross-trial variance var_sr (Bailey & Lopez de Prado 2014, eq. 2):
    sqrt(V) ((1 - g) Phi^-1(1 - 1/N) + g Phi^-1(1 - 1/(N e)))."""
    if n_trials <= 1 or not np.isfinite(var_sr) or var_sr <= 0:
        return 0.0
    from statistics import NormalDist
    inv = NormalDist().inv_cdf
    n = float(n_trials)
    return float(math.sqrt(var_sr) * ((1 - DSR_GAMMA) * inv(1 - 1 / n) + DSR_GAMMA * inv(1 - 1 / (n * math.e))))


def deflate_table(sb: pd.DataFrame, extra_trials: int = 0, test_mask: Optional[np.ndarray] = None) -> pd.DataFrame:
    """Adds psr (vs zero) and dsr (vs the best-of-N luck benchmark) to a scoreboard with sr / skew / kurt / n_eff.
    N = the tested cells on the board (every setup x split row, not the baseline) plus extra_trials; the cross-trial
    variance of SR comes from those same rows."""
    sb = sb.copy()
    for c_ in ("sr", "skew", "kurt", "n_eff"):
        if c_ not in sb:
            sb[c_] = np.nan
    test = np.ones(len(sb), bool) if test_mask is None else np.asarray(test_mask, bool)
    ok = test & np.isfinite(sb["sr"].to_numpy(float))
    n_tr = int(ok.sum()) + int(max(0, extra_trials))
    v = float(np.var(sb.loc[ok, "sr"].to_numpy(float), ddof=1)) if ok.sum() >= 2 else np.nan
    sr_star = expected_max_sr(n_tr, v)
    sb["psr"] = [psr(a, 0.0, n, s, k) for a, n, s, k in zip(sb["sr"], sb["n_eff"], sb["skew"], sb["kurt"])]
    sb["dsr"] = [psr(a, sr_star, n, s, k) if t else np.nan
                 for a, n, s, k, t in zip(sb["sr"], sb["n_eff"], sb["skew"], sb["kurt"], test)]
    sb.attrs["dsr_trials"], sb.attrs["dsr_sr_star"], sb.attrs["dsr_var"] = n_tr, sr_star, v
    return sb


def spread_corwin_schultz(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, w: int = SPREAD_W) -> pd.DataFrame:
    """Corwin-Schultz (2012) high-low spread, as a fraction of price, averaged over the last w two-day pairs ending at
    each date (pairs (t-1, t), so nothing after t is used). Overnight adjustment: when day t's range sits wholly above
    or below the prior close, it is shifted to touch it. Negative two-day estimates count as zero (the paper's rule)."""
    h, l, c = (x.astype(float) for x in (h, l, c))
    pc = c.shift(1)
    up = (l - pc).clip(lower=0)                         # gap up: the whole day above the prior close
    dn = (pc - h).clip(lower=0)                         # gap down
    h2, l2 = h - up + dn, l - up + dn                   # only the second day of each pair is shifted (the paper's rule)
    h1, l1 = h.shift(1), l.shift(1)
    with np.errstate(invalid="ignore", divide="ignore"):
        beta = np.log(h2 / l2) ** 2 + np.log(h1 / l1) ** 2
        gam = np.log(np.maximum(h2, h1) / np.minimum(l2, l1)) ** 2
        k = 3 - 2 * math.sqrt(2)
        alpha = (np.sqrt(2 * beta) - np.sqrt(beta)) / k - np.sqrt(gam / k)
        s = 2 * (np.exp(alpha) - 1) / (1 + np.exp(alpha))
    s = s.where(np.isfinite(s)).clip(lower=0)
    return s.rolling(w, min_periods=max(5, w // 2)).mean().clip(upper=SPREAD_CAP)


def spread_abdi_ranaldo(h: pd.DataFrame, l: pd.DataFrame, c: pd.DataFrame, w: int = SPREAD_W) -> pd.DataFrame:
    """Abdi-Ranaldo (2017) close-high-low spread, as a fraction of price: S^2 = 4 E[(c_t - eta_t)(c_t - eta_t+1)], with
    c the log close and eta the log mid-range. Pairs (t-1, t) over the last w sessions ending at each date; a negative
    window average gives zero."""
    with np.errstate(invalid="ignore", divide="ignore"):
        lc = np.log(c.astype(float))
        eta = (np.log(h.astype(float)) + np.log(l.astype(float))) / 2
        prod = (lc.shift(1) - eta.shift(1)) * (lc.shift(1) - eta)
        s2 = 4 * prod.rolling(w, min_periods=max(5, w // 2)).mean()
    return np.sqrt(s2.clip(lower=0)).clip(upper=SPREAD_CAP)


def spread_panel(P: Dict[str, pd.DataFrame], method: str = "ar", w: int = SPREAD_W) -> pd.DataFrame:
    h, l, c = P["high"], P["low"], P["close"]
    if method == "cs":
        return spread_corwin_schultz(h, l, c, w)
    if method == "avg":
        return (spread_corwin_schultz(h, l, c, w) + spread_abdi_ranaldo(h, l, c, w)) / 2
    return spread_abdi_ranaldo(h, l, c, w)


def exc_stop_curve(g: pd.DataFrame, ks: Sequence[float]) -> pd.DataFrame:
    """Tighter stops, from the trades' own MAE: a trade whose MAE reached -k R would have been stopped at -k (a gap
    through the new level would be worse, so this flatters a little); the rest keep their result. Exact otherwise,
    because the path up to that point is the same. Wider stops can't be tested this way: those trades ended at the stop.
    er is in R of today's stop distance; er_risk is per unit of the new, smaller risk (the same dollar risk buys 1/k as
    many shares more), which is the fair comparison for a trader who sizes every trade to a fixed loss."""
    r, mae = g["r"].to_numpy(float), g["mae_r"].to_numpy(float)
    rows = []
    for k in ks:
        hit = mae <= -k
        rr = np.where(hit, -k, r)
        er_k = float(np.nanmean(rr))
        rows.append({"stop_r": k, "er": er_k, "er_risk": er_k / k, "win": float(np.nanmean(rr > 0)),
                     "stopped": float(np.nanmean(hit | (g["outcome"].to_numpy() == 1))),
                     "winners_lost": float(np.nanmean(hit[r > 0])) if (r > 0).any() else np.nan})
    return pd.DataFrame(rows)


def exc_target_curve(g: pd.DataFrame, ks: Sequence[float]) -> pd.DataFrame:
    """A fixed target at k R, from the trades' own MFE: a trade whose MFE reached k R before it ended would have
    exited there (it touched k before whatever ended it); the rest keep their result. Exact for a target at or
    below the trade's own target, which is every k for trailing-stop trades."""
    r, mfe = g["r"].to_numpy(float), g["mfe_r"].to_numpy(float)
    rows = []
    for k in ks:
        hit = mfe >= k
        rr = np.where(hit, k, r)
        rows.append({"target_r": k, "er": float(np.nanmean(rr)), "p_reach": float(np.nanmean(hit)),
                     "win": float(np.nanmean(rr > 0))})
    return pd.DataFrame(rows)


def exc_scale_out(g: pd.DataFrame, ks: Sequence[float], frac: float = 0.5) -> pd.DataFrame:
    """Sell `frac` at k R, hold the rest to the original exit: trades whose MFE reached k get frac * k + (1 - frac) * R;
    the rest keep R. Exact (the partial fill happens on the way, before the original exit)."""
    r, mfe = g["r"].to_numpy(float), g["mfe_r"].to_numpy(float)
    rows = []
    for k in ks:
        hit = mfe >= k
        rr = np.where(hit, frac * k + (1 - frac) * r, r)
        rows.append({"scale_r": k, "er": float(np.nanmean(rr)), "p_reach": float(np.nanmean(hit)),
                     "sd": float(np.nanstd(rr)), "worst": float(np.nanmin(rr)), "p10": float(np.nanpercentile(rr, 10))})
    return pd.DataFrame(rows)


def exc_summary(g: pd.DataFrame) -> Dict[str, float]:
    """Sweeney's reads: how deep winners went against you (the stop you could have used) and how far losers ran for
    you before they turned (the give-back)."""
    r, mae, mfe = (g[k].to_numpy(float) for k in ("r", "mae_r", "mfe_r"))
    w, lz = r > 0, r <= 0
    q = lambda a, p: float(np.nanpercentile(a, p)) if np.isfinite(a).any() else np.nan
    return {"n": int(len(r)), "n_win": int(w.sum()), "n_loss": int(lz.sum()),
            "win_mae_med": q(mae[w], 50) if w.any() else np.nan, "win_mae_p90": q(mae[w], 10) if w.any() else np.nan,
            "loss_mfe_med": q(mfe[lz], 50) if lz.any() else np.nan,
            "loss_mfe_ge1": float(np.nanmean(mfe[lz] >= 1.0)) if lz.any() else np.nan,
            "mfe_p50": q(mfe, 50), "mfe_p75": q(mfe, 75), "mfe_p90": q(mfe, 90),
            "capture": float(np.nanmean(r[w]) / np.nanmean(mfe[w])) if w.any() and np.nanmean(mfe[w]) > 0 else np.nan}


def edge_ratio_curve(P: Dict[str, pd.DataFrame], g: pd.DataFrame, max_d: int = 30, atr_n: int = 14) -> pd.DataFrame:
    """Faith's edge ratio by sessions since entry: mean MFE / mean MAE over the first d sessions, both in ATRs at the
    signal, entry at the trade's own entry price. Reads the price path regardless of how the trade exited, so it shows
    what the entry alone is worth at each holding period (above 1 = the entry has an edge at that horizon)."""
    if g.empty or ("i" not in g and "date" not in g):
        return pd.DataFrame()
    H, L, C = (P[k].to_numpy(float) for k in ("high", "low", "close"))
    cols = pd.Index(P["close"].columns)
    pc = np.vstack([np.full((1, C.shape[1]), np.nan), C[:-1]])
    tr = np.nanmax(np.stack([H - L, np.abs(H - pc), np.abs(L - pc)]), axis=0)
    atr_ = pd.DataFrame(tr).rolling(atr_n, min_periods=atr_n).mean().to_numpy()
    jj = cols.get_indexer(g["ticker"].to_numpy())
    if "date" in g:                                    # by date, so a ledger built on a different window still lines up
        ii = pd.DatetimeIndex(P["close"].index).get_indexer(pd.DatetimeIndex(g["date"]))
    else:
        ii = g["i"].to_numpy(int)
    ok = (jj >= 0) & (ii >= 0) & np.isfinite(g["entry"].to_numpy(float))
    ii, jj, entry = ii[ok], jj[ok], g["entry"].to_numpy(float)[ok]
    a0 = atr_[ii, jj]
    n = H.shape[0]
    run_hi = np.full(len(ii), -np.inf)
    run_lo = np.full(len(ii), np.inf)
    rows = []
    for d in range(1, max_d + 1):
        t = ii + d
        live = t < n
        tt = np.minimum(t, n - 1)
        hh, ll = H[tt, jj], L[tt, jj]
        run_hi = np.where(live & np.isfinite(hh), np.fmax(run_hi, hh), run_hi)
        run_lo = np.where(live & np.isfinite(ll), np.fmin(run_lo, ll), run_lo)
        m = live & np.isfinite(a0) & (a0 > 0) & np.isfinite(run_hi) & np.isfinite(run_lo)
        if m.sum() < 20:
            break
        mfe = np.maximum(run_hi[m] - entry[m], 0) / a0[m]
        mae = np.maximum(entry[m] - run_lo[m], 0) / a0[m]
        rows.append({"day": d, "mfe_atr": float(mfe.mean()), "mae_atr": float(mae.mean()),
                     "edge_ratio": float(mfe.mean() / mae.mean()) if mae.mean() > 0 else np.nan, "n": int(m.sum())})
    return pd.DataFrame(rows)


def lg_cell(sid: str, lab: str, g: pd.DataFrame, horizon: int, cutoff: pd.Timestamp) -> Dict[str, Any]:
    done = g[g["status"] == 0]
    tried = int(g["status"].isin([0, 1, 2]).sum())
    row = {"setup_id": sid, "family": LG_SETUPS[sid][0], "setup": LG_SETUPS[sid][1], "split": lab,
           "events": len(done), "fill": len(done) / tried if tried else np.nan}
    if not len(done):
        return {**row, "dates": 0}
    dm = done.groupby("date")[["r", "xs"]].mean().sort_index()
    hold75 = int(np.nanpercentile(done["hold"], 75)) if "hold" in done and done["hold"].notna().any() else horizon
    mu_r, se_r = lg_nw(dm["r"].to_numpy(), max(int(horizon), hold75))       # trades overlap for as long as they are held
    mu_x, se_x = lg_nw(dm["xs"].to_numpy(), horizon)
    disc, hold = dm[dm.index < cutoff], dm[dm.index >= cutoff]
    md_, sd_ = lg_nw(disc["xs"].to_numpy(), horizon)
    mh_, sh_ = lg_nw(hold["xs"].to_numpy(), horizon)
    r = done["r"].to_numpy(float)
    top = np.sort(r)[::-1][:max(1, int(math.ceil(0.05 * len(r))))]
    tot = float(np.nansum(r))
    oc = done["outcome"].to_numpy()
    shp = sharpe_stats(dm["r"].to_numpy(), se_r)          # se_r: Newey-West s.e. of the mean, so n_eff counts overlap
    return {**row, "dates": len(dm), "sr": shp["sr"], "skew": shp["skew"], "kurt": shp["kurt"], "n_eff": shp["n_eff"],
            "hit": float((oc == 0).mean()), "stop_rate": float((oc == 1).mean()),
            "time_rate": float((oc == 2).mean()), "trail_rate": float((oc == 3).mean()), "open_rate": float((oc == 4).mean()),
            "er": float(np.nanmean(r)), "er_date": mu_r, "se_r": se_r,
            "t_r": mu_r / se_r if se_r and np.isfinite(se_r) and se_r > 0 else np.nan,
            "xs": mu_x, "se_xs": se_x, "t_xs": mu_x / se_x if se_x and np.isfinite(se_x) and se_x > 0 else np.nan,
            "xs_disc": md_, "t_disc": md_ / sd_ if sd_ and np.isfinite(sd_) and sd_ > 0 else np.nan,
            "xs_hold": mh_, "t_hold": mh_ / sh_ if sh_ and np.isfinite(sh_) and sh_ > 0 else np.nan,
            "n_hold": len(hold), "tail5": float(top.sum() / tot) if tot > 0 else np.nan,
            "med_ret": float(np.nanmedian(done["ret"])), "hold_med": float(np.median(done["hold"])),
            "capped": float(done["capped"].mean())}


def lg_verdict(r: pd.Series, min_dates: int = 30, min_events: int = 40) -> Tuple[str, str]:
    if r["setup_id"] == "base:uptrend":
        return "BASELINE", "What any uptrend name earned with the same stop, target and time limit."
    if _n(r.get("dates"), 0) < min_dates or _n(r.get("events"), 0) < min_events:
        return "THIN", f"{int(_n(r.get('events'), 0))} trades on {int(_n(r.get('dates'), 0))} dates: too few to judge."
    t, q = _n(r.get("t_xs"), np.nan), _n(r.get("q"), np.nan)
    er, xh = _n(r.get("er_date"), np.nan), _n(r.get("xs_hold"), np.nan)
    bits = [f"edge t {t:+.1f}", f"q {q:.2f}" if np.isfinite(q) else "q n/a", f"E[R] {er:+.2f} after costs",
            f"holdout edge {xh * 100:+.2f}%" if np.isfinite(xh) else "no holdout trades"]
    qn = _n(r.get("q_neg"), np.nan)
    if np.isfinite(t) and t <= -2.0 and np.isfinite(qn) and qn <= 0.10 and np.isfinite(xh) and xh < 0:
        return "NEGATIVE", ("Reliably worse than a random uptrend name (lower-tail q {:.2f}, holdout agrees): ".format(qn)
                            + ", ".join(bits) + ".")
    pos_hold = np.isfinite(xh) and xh > 0
    if np.isfinite(t) and t >= 3.0 and np.isfinite(q) and q <= 0.10 and pos_hold and er > 0:
        return "PROVEN", "Clears t >= 3, q <= 0.10, the holdout agrees and it pays after costs: " + ", ".join(bits) + "."
    if np.isfinite(t) and t >= 2.0 and pos_hold and er > 0:
        return "PROMISING", "Positive edge that hasn't cleared the t >= 3 / q <= 0.10 bar: " + ", ".join(bits) + "."
    return "NOISE", "No edge over the uptrend baseline that survives the checks: " + ", ".join(bits) + "."


def lg_score(ev: pd.DataFrame, split: str, hold_frac: float, horizon: int,
             extra_trials: int = 0) -> Tuple[pd.DataFrame, Optional[pd.Timestamp]]:
    if ev is None or not len(ev) or not (ev["status"] == 0).any():
        return pd.DataFrame(), None
    done = ev[ev["status"] == 0]
    ud = np.sort(done["date"].unique())
    cutoff = pd.Timestamp(ud[min(len(ud) - 1, int(len(ud) * (1 - hold_frac)))])
    sc = lg_split_col(ev, split)
    sc_np = sc.to_numpy(object) if sc is not None else None
    gi = ev.groupby("setup", sort=False).indices
    rows = []
    for sid in [s for s in LG_SETUPS if s in gi]:
        pos = gi[sid]
        g = ev.iloc[pos]
        rows.append(lg_cell(sid, "all", g, horizon, cutoff))
        if sc_np is not None:
            labs = sc_np[pos]
            for lab in sorted(set(labs)):
                rows.append(lg_cell(sid, str(lab), g[labs == lab], horizon, cutoff))
    sb = pd.DataFrame(rows)
    for col_ in ("t_xs", "er_date", "xs_hold", "dates", "events", "se_xs"):
        if col_ not in sb:
            sb[col_] = np.nan
    test = (sb["setup_id"] != "base:uptrend").to_numpy()
    tx = sb["t_xs"].to_numpy(float)
    p = np.where(test & np.isfinite(tx), 1.0 - _ncdf(tx), np.nan)
    sb["p"] = p
    sb["q"] = lg_bh(p)                                      # one-sided: the setup beats the uptrend baseline
    sb["q_neg"] = lg_bh(np.where(test & np.isfinite(tx), _ncdf(tx), np.nan))   # ...or reliably trails it
    for col_ in ("xs", "se_xs", "t_xs", "xs_disc", "t_disc", "xs_hold", "t_hold"):
        if col_ in sb:                                      # the baseline's edge over itself is zero by construction
            sb.loc[~test, col_] = np.nan
    base = sb[sb["setup_id"] == "base:uptrend"].set_index("split")["er_date"]
    sb["er_vs_base"] = sb["er_date"] - sb["split"].map(base)
    sb = deflate_table(sb, extra_trials, test)              # Deflated Sharpe: every tested cell on the board is a trial
    vv = [lg_verdict(r) for _, r in sb.iterrows()]
    sb["verdict"], sb["why"] = [a for a, _ in vv], [b for _, b in vv]
    return sb, cutoff


def lg_verdict_map(sb: pd.DataFrame, setting: str, label: str, prm: Dict[str, Any]) -> Dict[str, Any]:
    allr = sb[sb["split"] == "all"]
    return {"asof": date.today().isoformat(), "universe": label, "setting": setting,
            "params": {**{k: prm[k] for k in ("mode", "tgt", "horizon", "cost", "cooldown")},
                       "time_limits": lg_time_limits(prm)},
            "verdicts": {r["setup_id"]: {"verdict": r["verdict"], "events": int(_n(r.get("events"), 0)),
                                         "er": _n(r.get("er_date"), np.nan), "xs": _n(r.get("xs"), np.nan),
                                         "t": _n(r.get("t_xs"), np.nan), "q": _n(r.get("q"), np.nan)}
                         for _, r in allr.iterrows()}}


def lg_verdicts() -> Dict[str, Any]:
    v = st.session_state.get("ledger_verdicts")
    if v:
        return v
    v = disk_json(LG_VERDICT_FILE, {}) or {}
    if v:
        st.session_state["ledger_verdicts"] = v
    return v


def lg_save(runs: Dict[str, Dict[str, Any]], vmap: Dict[str, Any]) -> str:
    """Write the ledger (every event, both universes) for the meta-label model, and the verdicts. Atomic."""
    parts = [r["ev"].assign(universe=k) for k, r in runs.items() if r and len(r["ev"])]
    msg = []
    if parts:
        df = pd.concat(parts, ignore_index=True).drop(columns=["outcome_txt", "status_txt"], errors="ignore")
        LG_FILE.parent.mkdir(parents=True, exist_ok=True)
        try:
            tmp = LG_FILE.with_suffix(".parquet.tmp")
            df.to_parquet(tmp, index=False)
            os.replace(tmp, LG_FILE)
            msg.append(f"{len(df):,} events to {LG_FILE.name}")
        except Exception:
            f = LG_FILE.with_suffix(".csv.gz")
            tmp = f.with_suffix(".tmp")
            df.to_csv(tmp, index=False, compression="gzip")
            os.replace(tmp, f)
            msg.append(f"{len(df):,} events to {f.name} (no pyarrow, so CSV)")
    atomic_write_json(LG_VERDICT_FILE, vmap)
    msg.append(f"verdicts to {LG_VERDICT_FILE.name}")
    return "Saved " + " and ".join(msg) + " in data/."


# ---- survivorship-free market universe -----------------------------------------

def lg_cs_all(key: str) -> Tuple[set, set]:
    """Active and delisted US common stocks (type CS) from /v3/reference/tickers; cached a week."""
    path = CACHE_DIR / "cs_tickers_all.json"
    cached = disk_json(path, {}) or {}
    if (cached.get("date") and (date.today() - date.fromisoformat(cached["date"])).days < 7
            and cached.get("active")):
        return set(cached["active"]), set(cached.get("inactive") or [])
    act = common_stock_set(key)
    rows = massive_get_all("/v3/reference/tickers", {"market": "stocks", "type": "CS", "active": "false", "limit": 1000},
                           key, max_pages=80)
    ina = sorted({r.get("ticker") for r in rows if r.get("ticker")})
    if act:
        atomic_write_json(path, {"date": date.today().isoformat(), "active": sorted(act), "inactive": ina})
    return set(act), set(ina)


def lg_split_reused(P: Dict[str, pd.DataFrame], max_gap: int = 20, min_len: int = 120) -> Dict[str, pd.DataFrame]:
    """A ticker that disappears for more than max_gap sessions and comes back is usually a reused symbol (a new
    company). Keep the latest run under the ticker and earlier runs as TICKER~1, ~2 so indicators don't splice
    two companies together."""
    c = P["close"].to_numpy()
    extra = {k: {} for k in P}
    blank = []
    for j, tk in enumerate(P["close"].columns):
        iv = np.flatnonzero(np.isfinite(c[:, j]))
        if len(iv) < 2:
            continue
        br = np.flatnonzero(np.diff(iv) > max_gap)
        if not len(br):
            continue
        starts = np.r_[iv[0], iv[br + 1]]
        ends = np.r_[iv[br], iv[-1]]
        for s_no, (a, b) in enumerate(zip(starts[:-1], ends[:-1]), 1):
            if b - a + 1 >= min_len:
                for k in P:
                    col = np.full(len(c), np.nan, dtype=np.float32)
                    col[a:b + 1] = P[k].iloc[a:b + 1, j].to_numpy(np.float32)
                    extra[k][f"{tk}~{s_no}"] = col
        blank.append((j, starts[-1]))
    out = {}
    for k in P:
        arr = P[k].to_numpy(np.float32, copy=True)
        for j, s0 in blank:
            arr[:s0, j] = np.nan
        df = pd.DataFrame(arr, index=P[k].index, columns=P[k].columns)
        if extra[k]:
            df = pd.concat([df, pd.DataFrame(extra[k], index=P[k].index)], axis=1)
        out[k] = df
    return out


def lg_market_panel(n_sessions: int, key: str, min_price: float, min_dv_m: float, progress=None) -> Optional[Dict[str, Any]]:
    """Every US common stock, delisted names included, from Massive grouped daily bars (cached on disk, shared
    with Market > Breadth). Names that never reach the price or dollar-volume floor are dropped up front; the
    floors are applied again per event, on data known at the time."""
    try:
        act, ina = lg_cs_all(key)
    except Exception:
        act, ina = set(), set()
    cs = act | ina
    end = last_completed_session()
    days = _session_days(int(n_sessions * 1.05) + 10, end)
    tid: Dict[str, int] = {}
    per_day: Dict[date, Tuple[np.ndarray, np.ndarray]] = {}
    with ThreadPoolExecutor(max_workers=6) as ex:
        futs = {ex.submit(grouped_day, d, key): d for d in days}
        for i, f in enumerate(as_completed(futs), 1):
            d = futs[f]
            try:
                df = f.result()
            except Exception:
                df = pd.DataFrame()
            if len(df) and {"open", "high", "low", "close", "volume"} <= set(df.columns):
                if cs:
                    df = df[df["ticker"].isin(cs)]
                else:
                    df = df[df["ticker"].astype(str).str.fullmatch(r"[A-Z]{1,5}")]
                tks = df["ticker"].astype(str).to_numpy()
                codes = np.fromiter((tid.setdefault(t, len(tid)) for t in tks), dtype=np.int64, count=len(tks))
                per_day[d] = (codes, df[["open", "high", "low", "close", "volume"]].to_numpy(np.float32))
            if progress is not None and i % 20 == 0:
                progress.progress(i / len(days), text=f"Grouped daily bars {i}/{len(days)}")
    dts = sorted(per_day)[-int(n_sessions):]
    if len(dts) < LG_WARMUP + 60:
        return None
    nt = len(tid)
    mx_px, mx_dv, cnt = np.zeros(nt), np.zeros(nt), np.zeros(nt)
    for d in dts:
        codes, a = per_day[d]
        np.maximum.at(mx_px, codes, np.nan_to_num(a[:, 3]))
        np.maximum.at(mx_dv, codes, np.nan_to_num(a[:, 3] * a[:, 4]))
        np.add.at(cnt, codes, 1)
    keep = np.flatnonzero((mx_px >= min_price) & (mx_dv >= min_dv_m * 1e6) & (cnt >= 120))
    names = np.array(sorted(tid, key=tid.get), dtype=object)[keep]
    pos = np.full(nt, -1)
    pos[keep] = np.arange(len(keep))
    arr = np.full((5, len(dts), len(keep)), np.nan, dtype=np.float32)
    for r, d in enumerate(dts):
        codes, a = per_day[d]
        m = pos[codes] >= 0
        arr[:, r, pos[codes[m]]] = a[m].T
    per_day.clear()
    idx = pd.DatetimeIndex([pd.Timestamp(d) for d in dts])
    P = {k: pd.DataFrame(arr[n_], index=idx, columns=names) for n_, k in enumerate(("open", "high", "low", "close", "volume"))}
    del arr
    P = lg_split_reused(P)
    lastv = P["close"].notna().to_numpy()[::-1].argmax(axis=0)
    gone = set(P["close"].columns[lastv > 5])
    return {"P": P, "gone": gone, "n_cs": len(cs), "n_inactive": len(ina),
            "label": f"Whole market: {P['close'].shape[1]:,} US common stocks, {len(gone):,} delisted or gone"}


def lg_demo_market(bars: Dict[str, pd.DataFrame], n_extra: int = 120, seed: int = 11) -> Dict[str, Any]:
    """Demo stand-in for the whole market: your demo names plus synthetic names that fail (slide 55-85% and
    delist) or get bought out, so the survivorship comparison has something to show."""
    rng = np.random.default_rng(seed)
    out = {tk: df for tk, df in bars.items()}
    gone = set()
    for k in range(n_extra):
        tk = f"ZD{k:03d}"
        df = _demo_daily(tk, UNIVERSE_DAYS).copy()
        n = len(df)
        cut = int(rng.uniform(0.45, 0.97) * n)
        path = np.ones(n)
        if rng.random() < 0.7:
            span = int(rng.integers(60, 200))
            s0 = max(1, cut - span)
            path[s0:cut] = np.exp(np.linspace(0, np.log(1 - rng.uniform(0.55, 0.85)), cut - s0))
        else:
            path[cut - 1:] = 1 + rng.uniform(0.25, 0.45)
        for col in ("open", "high", "low", "close", "vwap"):
            df[col] = df[col].to_numpy() * path
        out[tk] = df.iloc[:cut]
        gone.add(tk)
    P = panel_from_bars(out)
    return {"P": {k: P[k] for k in ("open", "high", "low", "close", "volume")}, "gone": gone, "n_cs": len(out),
            "n_inactive": len(gone), "label": f"Demo market: {len(out)} names, {len(gone)} synthetic delistings"}


# ---- Setup ledger UI -----------------------------------------------------------

LG_UNI_LABEL = {"list": "Your list", "market": "Whole market (survivorship-free)", "both": "Both, side by side"}
LG_COLS = {"verdict": "Verdict", "family": "Family", "setup": "Setup", "split": "Split", "events": "Trades", "dates": "Dates",
           "fill": "Fill", "hit": "Target hit", "stop_rate": "Stopped", "trail_rate": "Trailed out", "open_rate": "Still open",
           "er_date": "E[R]", "t_r": "t (R)",
           "er_vs_base": "E[R] vs baseline", "xs": "Edge vs uptrend", "t_xs": "t (edge)", "q": "q",
           "psr": "P(Sharpe > 0)", "dsr": "Deflated Sharpe", "xs_disc": "Edge, discovery",
           "xs_hold": "Edge, holdout", "t_hold": "t (holdout)", "tail5": "Top 5% of trades / net R", "hold_med": "Median hold",
           "capped": "Stop capped", "why": "Why"}


def _lg_market_ok(cfg) -> Tuple[bool, str]:
    if cfg["source"] == "massive" and cfg["key"]:
        return True, "massive"
    if cfg["source"] == "demo":
        return True, "demo"
    return False, ("The whole-market universe needs Massive grouped daily bars (or Demo for a synthetic stand-in). "
                   "Yahoo can't list delisted names, so it would just rebuild the survivorship bias.")


def lg_build(cfg, ab, bench_bars, clim, bars, fams: Tuple[str, ...], setting: str, prm: Dict[str, Any],
             which: str) -> Dict[str, Any]:
    spy = bench_bars["SPY"]["close"] if "SPY" in bench_bars else None
    ptup = tuple(sorted(prm.items()))
    clim_tag = ((str(clim["hist"].index[-1]) if clim and "hist" in clim else "none") + "|" +
                (str(clim["nar"].index[-1]) if clim and "nar" in clim else "no-nar") + "|" +
                ("ilm" if clim and "ilm" in clim else "no-ilm"))
    runs, notes, gone = {}, [], set()
    prog = st.progress(0.0, text="Setup ledger")
    try:
        if which in ("list", "both"):
            cols = tuple(ab["P"]["close"].columns)
            rid = f"list-{zlib.crc32(','.join(cols).encode())}-{ab['asof']}-{zlib.crc32(repr((fams, setting, ptup, clim_tag)).encode())}"
            extra = {"alpha_pct": ab["composite"]} if ab.get("composite") is not None else {}
            try:                                            # industry RS (Moskowitz & Grinblatt) from the universe's groups
                grp, _ = resolve_groups(cfg["uni"], int(cfg.get("min_group", 5)))
                extra.update(memo(("ind_rs", zlib.crc32(','.join(cols).encode()), ab["asof"], len(grp)),
                                  lambda: industry_rs_panels(ab["P"]["close"], grp)))
            except Exception:
                pass
            ga_tag = "no-ga"
            try:                                            # Stocks > Group leaders, read on each signal date
                S_ga = ga_lab_state(cfg, ab)
                if S_ga is not None:
                    extra.update(ga_ledger_panels(S_ga))
                    ga_tag = repr((st.session_state.get("ga_by", GA_MAP_LABELS[0]), sorted(ga_params(st.session_state).items())))
                    st.session_state["lg_ga_top"] = float(S_ga["top_pct"])
            except Exception:
                pass
            rid += f"-{zlib.crc32(ga_tag.encode())}"
            extra = extra or None
            runs["list"] = memo(("lg_run", rid), lambda: {**lg_run(ab["P"], spy, clim, fams, setting, prm, "Your list", prog,
                                                                   extra=extra),
                                                           "rid": rid, "gone": set()}, capacity=300)
        if which in ("market", "both"):
            ok, how = _lg_market_ok(cfg)
            if not ok:
                notes.append(how)
            else:
                n_sess = int(st.session_state.get("lg_nsess", 1000))
                mkey = ("lg_mkt", how, date.today().isoformat(), session_phase(), n_sess, prm["min_price"], prm["min_dv"],
                        len(bars) if how == "demo" else 0)
                if how == "massive":
                    mk = memo(mkey, lambda: lg_market_panel(n_sess, cfg["key"], prm["min_price"], prm["min_dv"], prog))
                else:
                    mk = memo(mkey, lambda: lg_demo_market(bars))
                if mk is None:
                    notes.append("Not enough grouped daily bars came back to build the market panel.")
                else:
                    rid = f"mkt-{zlib.crc32(repr(mkey).encode())}-{zlib.crc32(repr((fams, setting, ptup, clim_tag)).encode())}"
                    runs["market"] = memo(("lg_run", rid), lambda: {**lg_run(mk["P"], spy, clim, fams, setting, prm,
                                                                             "Whole market", prog),
                                                                     "rid": rid, "gone": mk["gone"], "mlabel": mk["label"]})
                    gone = mk["gone"]
    finally:
        prog.empty()
    for k, r in runs.items():
        if len(r["ev"]):
            r["ev"]["gone"] = r["ev"]["ticker"].isin(r.get("gone") or set())
    return {"runs": runs, "notes": notes, "gone_n": len(gone)}


def lg_state_params() -> Tuple[List[str], str, Dict[str, Any], str, Tuple]:
    """The Setup ledger tab's current settings (session state), so other tabs can build the same ledger."""
    for k_, v_ in LG_DEFAULTS.items():
        st.session_state.setdefault(k_, v_)
    for f_, v_ in LG_TL_SEED.items():
        st.session_state.setdefault(f"lg_tl_f_{f_}", v_)
    for f_, v_ in LG_EXIT_SEED.items():
        st.session_state.setdefault(f"lg_ex_f_{f_}", v_)
    ss = st.session_state
    fams = [f for f in LG_FAMILIES if f in (ss["lg_fams"] or [])]
    fam_tl = {f: int(ss.get(f"lg_tl_f_{f}", LG_TL_SEED[f])) for f in LG_TL_SEED}
    fam_ex = {f: str(ss.get(f"lg_ex_f_{f}", LG_EXIT_SEED[f])) for f in LG_EXIT_SEED}
    prm = {"mode": ss["lg_mode"], "win": int(ss["lg_win"]), "tgt": float(ss["lg_tgt"]), "horizon": int(ss["lg_h"]),
           "cost": float(ss["lg_cost"]), "cost_mode": str(ss["lg_cost_mode"]), "spread_m": str(ss["lg_spread_m"]),
           "cooldown": int(ss["lg_cd"]), "cap": float(ss["lg_cap"]),
           "min_price": float(ss["lg_px"]), "min_dv": float(ss["lg_dv"]), "base_step": int(ss["lg_base_step"]),
           "warmup": LG_WARMUP, "tl_mode": ss["lg_tl_mode"], "tl": int(ss["lg_tl"]),
           "tl_fam": tuple(sorted((str(k), int(v)) for k, v in fam_tl.items())),
           "exit_mode": ss["lg_exit_mode"], "trail": ss["lg_trail"], "trail_k": float(ss["lg_trail_k"]),
           "trail_ma": int(ss["lg_trail_ma"]), "mark_open": bool(ss["lg_open"]),
           "exit_fam": tuple(sorted((str(k), str(v)) for k, v in fam_ex.items()))}
    sig = (tuple(fams), ss["lg_mset"], ss["lg_uni"], tuple(sorted(prm.items())), int(ss["lg_nsess"]))
    return fams, ss["lg_mset"], prm, ss["lg_uni"], sig


def lg_build_store(cfg, ab, bench_bars, clim, bars, fams, mset: str, prm: Dict[str, Any], which: str, sig) -> None:
    """Build the ledger, keep it in the session, publish the verdicts to the Screener and save it to disk."""
    out = lg_build(cfg, ab, bench_bars, clim, bars, tuple(f for f in LG_FAMILIES if f in fams), mset, prm, which)
    st.session_state["lg_res"] = {"sig": sig, **out}
    runs_ = out["runs"]
    main_k = "market" if "market" in runs_ else ("list" if "list" in runs_ else None)
    if not main_k:
        return
    st.session_state["lg_view_next"] = main_k
    sb0, _ = lg_score(runs_[main_k]["ev"], "none", float(st.session_state.get("lg_hold", 0.4)), int(prm["horizon"]))
    if len(sb0):
        vmap = lg_verdict_map(sb0, mset, LG_UNI_LABEL[main_k], prm)
        vmap["source"] = cfg["source"]                       # playbook.py warns when the saved ledger is synthetic
        vmap["prm_full"] = {k: (list(v) if isinstance(v, tuple) else v) for k, v in prm.items()}
        st.session_state["ledger_verdicts"] = vmap
        try:
            st.session_state["lg_saved"] = lg_save(runs_, vmap)
        except Exception as e:
            st.session_state["lg_saved"] = f"Couldn't save the ledger: {type(e).__name__}: {e}"


def _lg_ci_chart(sb: pd.DataFrame, val: str, se: str, title: str, fmt: str, rule: Optional[float] = None,
                 by_split: bool = False):
    d = sb.dropna(subset=[val]).copy()
    if d.empty:
        return None
    d["lo"] = d[val] - 1.96 * d[se].fillna(0)
    d["hi"] = d[val] + 1.96 * d[se].fillna(0)
    order = list(d[d["split"] == "all"].sort_values(val, ascending=False)["setup"]) if (d["split"] == "all").any() else None
    order = order or list(d.sort_values(val, ascending=False)["setup"].unique())
    dom = [v for v in LG_VERDICTS if v in set(d["verdict"])]
    y = alt.Y("setup:N", sort=order, title=None, axis=alt.Axis(labelLimit=280, labelOverlap=False))
    enc = {"yOffset": alt.YOffset("split:N")} if by_split else {}
    known = {"Bull": C_GREEN, "Correction": C_ACCENT, "Bear": C_RED, "Rebound": C_BLUE, "above 200-day": C_GREEN,
             "below 200-day": C_RED, "STEADY": C_GREEN, "WOI": C_ACCENT, "CRISIS": C_RED, "INFLATION": C_BLUE,
             "MIXED": C_MUTED, "n/a": "#4a4a5a"}
    spare = iter([C_BLUE, C_GREEN, C_ACCENT, C_RED, "#c084fc", "#2dd4bf", C_ACCENT2, C_MUTED, "#f0abfc", "#7aa2f7"])
    sdom = sorted(d["split"].unique())
    srng = [known.get(s_) or next(spare, C_MUTED) for s_ in sdom]
    col = (alt.Color("split:N", scale=alt.Scale(domain=sdom, range=srng), legend=alt.Legend(orient="top", title=None))
           if by_split else
           alt.Color("verdict:N", scale=alt.Scale(domain=dom, range=[LG_VERDICT_COLOR[v] for v in dom]),
                     legend=alt.Legend(orient="top", title=None)))
    tip = ["setup", "split", "verdict", "events", alt.Tooltip(f"{val}:Q", format=fmt), alt.Tooltip("lo:Q", format=fmt),
           alt.Tooltip("hi:Q", format=fmt)]
    bars_ = alt.Chart(d).mark_rule(strokeWidth=2, opacity=0.7).encode(
        y=y, x=alt.X("lo:Q", title=None, axis=alt.Axis(format=fmt.replace("+", ""))), x2="hi:Q", color=col, tooltip=tip, **enc)
    pts = alt.Chart(d).mark_point(filled=True, size=70, opacity=1).encode(
        y=y, x=f"{val}:Q", color=col, tooltip=tip, **enc)
    layers = [bars_, pts, alt.Chart(pd.DataFrame({"x": [0.0]})).mark_rule(color=C_MUTED).encode(x="x:Q")]
    if rule is not None and np.isfinite(rule):
        layers.append(alt.Chart(pd.DataFrame({"x": [rule]})).mark_rule(color=C_BLUE, strokeDash=[4, 3]).encode(x="x:Q"))
    step = 11 if by_split else 24                           # with yOffset the step sizes each sub-row
    return _alt(alt.layer(*layers).properties(title=title), alt.Step(step))


def _lg_scoreboard_df(sb: pd.DataFrame, show_splits: bool) -> pd.DataFrame:
    d = sb if show_splits else sb[sb["split"] == "all"]
    if show_splits:                                         # group each setup's rows: "all" first, then its splits
        d = d.assign(_s=d["setup_id"].map({s: i for i, s in enumerate(LG_SETUPS)}), _a=(d["split"] != "all").astype(int))
        d = d.sort_values(["_s", "_a", "split"])
    else:
        d = d.assign(_v=d["verdict"].map({v: i for i, v in enumerate(LG_VERDICTS)}))
        d = d.sort_values(["_v", "t_xs"], ascending=[True, False], na_position="last")
    keep = [c for c in LG_COLS if c in d.columns and (show_splits or c != "split")]
    return d[keep].rename(columns=LG_COLS)


def lg_overlap(ev: pd.DataFrame, sid: str, win: int = 3) -> pd.DataFrame:
    """For one setup's trades: the share where each other setup also fired on the same name within +/- win sessions.
    High overlap means the setup mostly re-labels trades another one already takes."""
    keep = ev["setup"] != "base:uptrend"
    b = ev.loc[(ev["setup"] == sid) & (ev["status"] == 0), ["ticker", "i"]].reset_index(drop=True)
    if b.empty:
        return pd.DataFrame(columns=["setup", "share"])
    b["k"] = np.arange(len(b))
    rows = []
    for s2, g in ev.loc[keep & (ev["setup"] != sid), ["setup", "ticker", "i"]].groupby("setup", sort=False):
        mm = b.merge(g[["ticker", "i"]], on="ticker", suffixes=("", "_o"))
        n_hit = mm.loc[(mm["i_o"] - mm["i"]).abs() <= win, "k"].nunique()
        rows.append({"setup": LG_SETUPS.get(str(s2), ("", str(s2)))[1], "share": n_hit / len(b)})
    return pd.DataFrame(rows).sort_values("share", ascending=False)


def _lg_drill(run: Dict[str, Any], sb: pd.DataFrame, cutoff: Optional[pd.Timestamp], ukey: str,
              P: Optional[Dict[str, pd.DataFrame]] = None) -> None:
    ev = run["ev"]
    allr = sb[sb["split"] == "all"]
    if allr.empty:
        return
    opts = list(allr["setup_id"])
    sid = st.selectbox("Look inside one setup", opts, key=f"lg_drill_{ukey}", format_func=lambda s: LG_SETUPS[s][1])
    r = allr[allr["setup_id"] == sid].iloc[0]
    g = ev[(ev["setup"] == sid) & (ev["status"] == 0)].copy()
    if g.empty:
        note("No completed trades for this setup.")
        return
    fam, lab, stop_kind = LG_SETUPS[sid]
    md(f"<div class='note' style='color:var(--text)'>{_esc(lab)} ({_esc(fam)}): stop under the {_esc(LG_STOP_LABEL[stop_kind])}. "
       f"{_esc(r['why'])}</div>")
    gone_n = int(g["gone"].sum()) if "gone" in g else 0
    kp = [kpi_html("Trades", f"{len(g):,}", f"{int(_n(r.get('dates'), 0))} signal dates; fill {pct(r.get('fill'))}"),
          kpi_html("E[R] after costs", f"{_n(r.get('er_date'), np.nan):+.2f}", f"t {_n(r.get('t_r'), np.nan):+.1f} (per-date, Newey-West)",
                   "good" if _n(r.get("er_date")) > 0 else "bad"),
          kpi_html("Target / stop / trail / time", f"{pct(r.get('hit'))} / {pct(r.get('stop_rate'))} / "
                   f"{pct(r.get('trail_rate'))} / {pct(r.get('time_rate'))}",
                   f"median hold {int(_n(r.get('hold_med'), 0))} sessions; {pct(r.get('open_rate'))} still open"),
          kpi_html("Edge vs uptrend names", pct(r.get("xs"), 2), f"holdout {pct(r.get('xs_hold'), 2)}",
                   "good" if _n(r.get("xs")) > 0 else "bad"),
          kpi_html("Top 5% of trades", "n/a" if not np.isfinite(_n(r.get("tail5"), np.nan)) else f"{_n(r.get('tail5')):.0%}",
                   "share of the net R", "warn" if _n(r.get("tail5"), 0) > 1 else ""),
          kpi_html("Trades in names later delisted", f"{gone_n:,}",
                   f"E[R] {g.loc[g['gone'], 'r'].mean():+.2f}" if gone_n else "none in this universe", "warn" if gone_n else "")]
    kpi_row(kp)
    c1, c2 = st.columns(2)
    with c1:
        h = g.assign(R=g["r"].clip(-3, 6))
        ch = alt.Chart(h, title="R multiple per trade (clipped at -3 and +6)").mark_bar(color=C_ACCENT, opacity=0.85).encode(
            x=alt.X("R:Q", bin=alt.Bin(step=0.25), title=None), y=alt.Y("count():Q", title=None),
            tooltip=[alt.Tooltip("count():Q", title="trades")])
        show_chart(_alt(ch, 240))
    with c2:
        dm = g.groupby("date")["r"].mean().sort_index()
        cum = pd.DataFrame({"date": dm.index, "cum": dm.cumsum().to_numpy()})
        layers = [alt.Chart(cum).mark_line(color=C_ACCENT, strokeWidth=1.6).encode(
            x=alt.X("date:T", title=None), y=alt.Y("cum:Q", title=None), tooltip=["date:T", alt.Tooltip("cum:Q", format="+.1f")])]
        if cutoff is not None:
            layers.append(alt.Chart(pd.DataFrame({"date": [cutoff]})).mark_rule(color=C_BLUE, strokeDash=[4, 3]).encode(x="date:T"))
        show_chart(_alt(alt.layer(*layers).properties(
            title="Running sum of each date's average R (holdout starts at the dashed line)"), 240))
    yr = g.assign(year=g["date"].dt.year).groupby("year").agg(trades=("r", "size"), er=("r", "mean"),
                                                             hit=("outcome", lambda x: float((x == 0).mean())),
                                                             edge=("xs", "mean"), med_ret=("ret", "median")).reset_index()
    P_ = st.column_config.NumberColumn
    c3, c4 = st.columns([2, 3])
    with c3:
        show_df(yr, column_config={"er": P_("E[R]", format="%+.2f"), "hit": P_("target hit", format="percent"),
                                   "edge": P_("edge", format="percent"), "med_ret": P_("median return", format="percent")})
    with c4:
        last = g.sort_values("date", ascending=False).head(60)
        show_df(last[["date", "ticker", "entry", "stop", "target", "exit_px", "outcome_txt", "r", "hold", "xs"]]
                .assign(date=lambda x: x["date"].dt.date), height=300,
                column_config={"entry": P_(format="%.2f"), "stop": P_(format="%.2f"), "target": P_(format="%.2f"),
                               "exit_px": P_("exit", format="%.2f"), "outcome_txt": "outcome", "r": P_("R", format="%+.2f"),
                               "xs": P_("edge", format="percent")})
    ov = memo(("lg_overlap", run.get("rid"), sid), lambda: lg_overlap(ev, sid))
    if len(ov):
        top = ov.head(10)
        ch = alt.Chart(top, title=f"Other setups that fired on the same name within 3 sessions of a {lab} trade").mark_bar(
            color=C_BLUE, opacity=0.85).encode(
            y=alt.Y("setup:N", sort=list(top["setup"]), title=None, axis=alt.Axis(labelLimit=300, labelOverlap=False)),
            x=alt.X("share:Q", title=None, axis=alt.Axis(format="%"), scale=alt.Scale(domain=[0, 1])),
            tooltip=["setup", alt.Tooltip("share:Q", format=".0%")])
        show_chart(_alt(ch, alt.Step(22)))
        note("A setup that complements the others shows low bars here: its trades are ones the other setups don't "
             "already take. Above about 60% it is mostly a re-label, and its edge should be judged together with the "
             "setup it overlaps.")
    st.download_button(f"Download the {len(g):,} trades for this setup (CSV)",
                       g.drop(columns=["i"], errors="ignore").to_csv(index=False).encode(),
                       file_name=f"ledger_{sid.replace(':', '_')}_{ukey}.csv", mime="text/csv", key=f"lg_dl_ev_{ukey}")
    _lg_excursions(run, g, lab, ukey, sid, P)


def _lg_excursions(run: Dict[str, Any], g: pd.DataFrame, lab: str, ukey: str, sid: str,
                   P: Optional[Dict[str, pd.DataFrame]]) -> None:
    """Inside one setup: MAE / MFE of winners and losers, what a tighter stop, a fixed target or a scale-out would
    have done to these same trades, and Faith's edge ratio by days held."""
    g = g[np.isfinite(g["mae_r"]) & np.isfinite(g["mfe_r"]) & np.isfinite(g["r"])]
    sec(f"Excursions: how far {lab} trades went against you and for you")
    if len(g) < 30:
        note("Excursions need at least 30 completed trades for this setup.")
        return
    xs_ = exc_summary(g)
    P_ = st.column_config.NumberColumn
    kpi_row([kpi_html("Winners' worst dip, median", f"{xs_['win_mae_med']:+.2f}R",
                      f"90% of winners stayed above {xs_['win_mae_p90']:+.2f}R", "info"),
             kpi_html("Losers that were up 1R first", pct(xs_["loss_mfe_ge1"]),
                      f"median loser ran {xs_['loss_mfe_med']:+.2f}R before turning", "warn" if _n(xs_["loss_mfe_ge1"]) > 0.25 else ""),
             kpi_html("Run-up (MFE), all trades", f"{xs_['mfe_p50']:+.2f}R median",
                      f"75th {xs_['mfe_p75']:+.2f}R · 90th {xs_['mfe_p90']:+.2f}R"),
             kpi_html("Winners keep of their run-up", pct(xs_["capture"]), "average R banked / average MFE, winners")])
    c1, c2 = st.columns(2)
    with c1:
        d = g.assign(result=np.where(g["r"] > 0, "winner", "loser"), R=g["r"].clip(-3, 8),
                     MAE=g["mae_r"].clip(-1.5, 0.5))
        if len(d) > 4000:
            d = d.sample(4000, random_state=3)
        pts = alt.Chart(d).mark_circle(size=14, opacity=0.45).encode(
            x=alt.X("MAE:Q", title="Worst point during the trade (MAE, R)"),
            y=alt.Y("R:Q", title="Final R (clipped at -3 and +8)"),
            color=alt.Color("result:N", scale=alt.Scale(domain=["winner", "loser"], range=[C_GREEN, C_RED]),
                            legend=alt.Legend(orient="top", title=None)),
            tooltip=["ticker", alt.Tooltip("date:T"), alt.Tooltip("mae_r:Q", format="+.2f", title="MAE"),
                     alt.Tooltip("r:Q", format="+.2f", title="R")])
        rule = alt.Chart(pd.DataFrame({"x": [xs_["win_mae_p90"]]})).mark_rule(color=C_ACCENT, strokeDash=[4, 3]).encode(x="x:Q")
        show_chart(_alt(alt.layer(pts, rule).properties(
            title="Sweeney's MAE plot (dashed: 90% of winners stayed right of it)"), 300))
    with c2:
        d = g.assign(result=np.where(g["r"] > 0, "winner", "loser"), MFE=g["mfe_r"].clip(0, 8))
        show_chart(_alt(alt.Chart(d).mark_bar(opacity=0.7).encode(
            x=alt.X("MFE:Q", bin=alt.Bin(step=0.25), title="Best point during the trade (MFE, R; clipped at 8)"),
            y=alt.Y("count():Q", title=None, stack=True),
            color=alt.Color("result:N", scale=alt.Scale(domain=["winner", "loser"], range=[C_GREEN, C_RED]),
                            legend=alt.Legend(orient="top", title=None))).properties(
            title="Run-up before the exit (red past 1R: profit given back)"), 300))
    ks_s = [round(x, 2) for x in np.arange(0.3, 1.01, 0.1)]
    ks_t = [0.5, 1, 1.5, 2, 2.5, 3, 4, 5, 6, 8]
    sc_ = exc_stop_curve(g, ks_s)
    tc_ = exc_target_curve(g, ks_t)
    so_ = exc_scale_out(g, [0.5, 1, 1.5, 2, 3, 4])
    base_er = float(g["r"].mean())
    c3, c4, c5 = st.columns([5, 3, 4])
    with c3:
        st.markdown("**A tighter stop** (fraction of today's stop distance)")
        show_df(sc_, column_config={"stop_r": P_("stop at -R", format="%.1f"), "er": P_("E[R]", format="%+.2f"),
                                    "er_risk": P_("E[R] per new risk", format="%+.2f",
                                                  help="E[R] divided by the new stop distance: what each trade earns "
                                                       "per unit risked when you size to the same dollar loss."),
                                    "win": P_("win rate", format="percent"), "stopped": P_("stopped", format="percent"),
                                    "winners_lost": P_("winners cut short", format="percent")})
    with c4:
        st.markdown("**A fixed target**")
        show_df(tc_, column_config={"target_r": P_("target R", format="%.1f"), "er": P_("E[R]", format="%+.2f"),
                                    "p_reach": P_("reached", format="percent"), "win": P_("win rate", format="percent")})
    with c5:
        st.markdown("**Sell half at a level**, hold the rest")
        show_df(so_, column_config={"scale_r": P_("sell half at R", format="%.1f"), "er": P_("E[R]", format="%+.2f"),
                                    "p_reach": P_("reached", format="percent"), "sd": P_("s.d. of R", format="%.2f"),
                                    "p10": P_("10th pct R", format="%+.2f"), "worst": P_("worst R", format="%+.2f")})
    sc_t = sc_[sc_["stop_r"] < 0.999]                  # 1.0 is today's stop: the reference row
    best_s = sc_t.loc[sc_t["er_risk"].idxmax()] if len(sc_t) else None
    best_t = tc_.loc[tc_["er"].idxmax()] if len(tc_) else None
    best_o = so_.loc[so_["er"].idxmax()] if len(so_) else None
    bits = [f"As traded: E[R] {base_er:+.2f}."]
    if best_s is not None:
        bits.append(f"Best tighter stop {best_s['stop_r']:.1f}R: E[R] {best_s['er']:+.2f} of today's risk, "
                    f"{best_s['er_risk']:+.2f} per unit of the new risk, cutting {pct(best_s['winners_lost'])} of winners short.")
    if best_t is not None:
        bits.append(f"Best fixed target {best_t['target_r']:g}R: E[R] {best_t['er']:+.2f}.")
    if best_o is not None:
        bits.append(f"Best half-off level {best_o['scale_r']:g}R: E[R] {best_o['er']:+.2f} with a 10th-percentile trade of {best_o['p10']:+.2f}R.")
    note(" ".join(bits) + " These replay the same trades with a different exit, read from each trade's own MAE and MFE, so "
         "they can only test exits inside what happened: a tighter stop (a gap through it would cost a little more) or "
         "an earlier exit. A wider stop or a later target needs the ledger rebuilt with those rules. Picking the best "
         "row here is another search: treat a gain of a few hundredths of an R as noise.")
    if P is None:
        note("The edge ratio by day reads the price path, which is kept for your list only. Switch the ledger view to "
             "your list to see it.")
        return
    er_ = memo(("lg_edge_ratio", run.get("rid"), sid), lambda: edge_ratio_curve(P, g))
    if len(er_):
        long = er_.melt("day", value_vars=["mfe_atr", "mae_atr"], var_name="what", value_name="atr")
        long["what"] = long["what"].map({"mfe_atr": "average run-up (MFE)", "mae_atr": "average drawdown (MAE)"})
        c6, c7 = st.columns(2)
        with c6:
            line_ = alt.Chart(er_).mark_line(color=C_ACCENT, strokeWidth=2,
                                             point=alt.OverlayMarkDef(color=C_ACCENT, size=22)).encode(
                x=alt.X("day:Q", title="Sessions after the signal"), y=alt.Y("edge_ratio:Q", title="Edge ratio (MFE / MAE)"),
                tooltip=["day", alt.Tooltip("edge_ratio:Q", format=".2f"), "n"])
            one_ = alt.Chart(pd.DataFrame({"y": [1.0]})).mark_rule(color=C_MUTED, strokeDash=[4, 3]).encode(y="y:Q")
            show_chart(_alt(alt.layer(line_, one_).properties(
                title="Faith's edge ratio: above 1, the entry has moved more for you than against you"), 260))
        with c7:
            show_chart(_alt(alt.Chart(long).mark_line(strokeWidth=2).encode(
                x=alt.X("day:Q", title="Sessions after the signal"), y=alt.Y("atr:Q", title="ATRs at the signal"),
                color=alt.Color("what:N", scale=alt.Scale(domain=["average run-up (MFE)", "average drawdown (MAE)"],
                                                          range=[C_GREEN, C_RED]),
                                legend=alt.Legend(orient="top", title=None, labelLimit=240)),
                tooltip=["day", "what", alt.Tooltip("atr:Q", format=".2f")]).properties(
                title="Average best and worst point so far, every trade held to that day"), 260))
        pk = er_.loc[er_["edge_ratio"].idxmax()]
        note(f"The edge ratio peaks at {pk['edge_ratio']:.2f} after {int(pk['day'])} sessions. It ignores the exit rule: "
             "every trade is followed for the full window from its entry, so it shows how long the entry itself keeps "
             "paying, which is a guide to the holding period (Faith, Way of the Turtle).")


def _lg_compare(runs: Dict[str, Any], scores: Dict[str, Tuple[pd.DataFrame, Any]]) -> None:
    a = scores["list"][0]
    b = scores["market"][0]
    if a.empty or b.empty:
        return
    a, b = a[a["split"] == "all"].set_index("setup_id"), b[b["split"] == "all"].set_index("setup_id")
    ids = [s for s in LG_SETUPS if s in a.index and s in b.index]
    cmp_ = pd.DataFrame({"setup": [LG_SETUPS[s][1] for s in ids],
                         "list_er": a.loc[ids, "er_date"].to_numpy(), "market_er": b.loc[ids, "er_date"].to_numpy(),
                         "list_edge": a.loc[ids, "xs"].to_numpy(), "market_edge": b.loc[ids, "xs"].to_numpy(),
                         "list_verdict": a.loc[ids, "verdict"].to_numpy(), "market_verdict": b.loc[ids, "verdict"].to_numpy(),
                         "list_n": a.loc[ids, "events"].to_numpy(), "market_n": b.loc[ids, "events"].to_numpy()})
    cmp_["gap_er"] = cmp_["list_er"] - cmp_["market_er"]
    ev_m = runs["market"]["ev"]
    dm = ev_m[(ev_m["status"] == 0) & (ev_m["setup"] != "base:uptrend")]
    g_er = dm.loc[dm["gone"], "r"].mean() if dm["gone"].any() else np.nan
    s_er = dm.loc[~dm["gone"], "r"].mean()
    flips = int((cmp_["list_verdict"].isin(["PROVEN", "PROMISING"]) & ~cmp_["market_verdict"].isin(["PROVEN", "PROMISING"])).sum())
    kpi_row([kpi_html("Average E[R] gap (list - market)", f"{cmp_['gap_er'].mean():+.2f}",
                      "what today's list adds to every setup", "warn" if cmp_["gap_er"].mean() > 0 else ""),
             kpi_html("Setups that lose their verdict", flips, "PROVEN/PROMISING on the list, not on the market",
                      "bad" if flips else "good"),
             kpi_html("E[R] in names later delisted", "n/a" if not np.isfinite(g_er) else f"{g_er:+.2f}",
                      f"{int(dm['gone'].sum()):,} trades; survivors {s_er:+.2f}", "bad" if _n(g_er) < s_er else ""),
             kpi_html("Market universe", f"{runs['market']['n_names']:,} names", runs["market"].get("mlabel", ""))])
    long = pd.concat([cmp_[["setup", "list_er"]].rename(columns={"list_er": "er"}).assign(universe="Your list"),
                      cmp_[["setup", "market_er"]].rename(columns={"market_er": "er"}).assign(universe="Whole market")])
    order = list(cmp_.sort_values("gap_er", ascending=False)["setup"])
    rule = alt.Chart(cmp_).mark_rule(color=C_MUTED, strokeWidth=2).encode(
        y=alt.Y("setup:N", sort=order, title=None, axis=alt.Axis(labelLimit=280, labelOverlap=False)),
        x=alt.X("list_er:Q", title=None), x2="market_er:Q")
    pts = alt.Chart(long).mark_point(filled=True, size=80, opacity=1).encode(
        y=alt.Y("setup:N", sort=order), x="er:Q",
        color=alt.Color("universe:N", scale=alt.Scale(domain=["Your list", "Whole market"], range=[C_ACCENT, C_BLUE]),
                        legend=alt.Legend(orient="top", title=None)),
        tooltip=["setup", "universe", alt.Tooltip("er:Q", format="+.2f")])
    zero = alt.Chart(pd.DataFrame({"x": [0.0]})).mark_rule(color=C_MUTED, strokeDash=[2, 2]).encode(x="x:Q")
    show_chart(_alt(alt.layer(rule, pts, zero).properties(
        title="E[R] per setup: your list vs the whole market (the gap is survivorship plus list selection)"), alt.Step(24)))
    P_ = st.column_config.NumberColumn
    show_df(cmp_.sort_values("gap_er", ascending=False), column_config={
        "list_er": P_("E[R] list", format="%+.2f"), "market_er": P_("E[R] market", format="%+.2f"),
        "gap_er": P_("gap", format="%+.2f"), "list_edge": P_("edge list", format="percent"),
        "market_edge": P_("edge market", format="percent"), "list_n": P_("trades list", format="%d"),
        "market_n": P_("trades market", format="%d")})
    note("Your list is today's names, picked partly because they went up: every setup looks better on it. The whole "
         "market keeps the names that failed and delisted. A setup worth trading should keep its verdict on the market "
         "universe. Daily bars stop at the last trade, so the loss on the delisting itself (Shumway 1997 put it near "
         "-30% for performance delistings) is missing: trades open at a delisting are closed at the last price, which "
         "still flatters the market numbers a little.")


LG_GUIDE = """
#### What the ledger does
Every time one of the long setups fires (first day, then a cooldown per name), the ledger takes the trade the way you
would: **entry** at the next open, or a **buy stop** above the signal-day high (filled at the open if it gaps over);
a **stop** under the setup's own level (wave low for MACD pullbacks and divergences, the pad for LaunchPads, the
weekly 8 EMA for the 8-week pocket, a 2-day or signal-day low for LBR, the gap day's low for the Gap family, the EP
day's low for the EP family, 2N or 3 ATR for the Trend family, the 10-day low otherwise), kept between
0.5 and 3 ATR; a **target** at a multiple of the risk; and, if you want one, a **time limit**. Whichever barrier comes
first ends the trade. Results are in **R** (profit divided by the risk you took) after round-trip costs.

The **exit** can be a fixed R target, a trailing stop with no target, or a choice per family. The trailing stop
starts at the setup's own stop and only ratchets up, from each close for the next session: the chandelier version
trails the highest high since entry by k ATR (LeBeau uses 3; the all-time-high study used 10), the close version
trails the highest close, and the moving-average version exits on a close under the chosen average. Results stay in R
of the initial risk, so a trailed winner can be worth 5R or 20R instead of being capped at the target. Outcomes read
target, stop (the initial one), trailing exit (a stop that had moved up, or the average), time, or open.

The time limit is optional and can differ by family. Off, a trade runs until its exit rule closes it. Per family, each family gets its own limit: short
swing setups can keep 10 sessions while breakouts and trend entries run free. With no time limit, trades still open
when the data ends can be marked at the last close and counted (outcome open), which keeps today's running winners in
the sample; switch that off to drop them as unresolved. The **edge window** is separate: it is
the span over which each trade's forward return is compared with every uptrend name's on the same date, and it never
closes a trade.

#### Why the scores look harsher than an event study
* **Edge, not return.** Each trade's forward return is compared with the average of every uptrend name (close above
  a rising 50-day) on the same date. A setup that only made money because the market went up has no edge.
* **One vote per date.** Twenty names firing on one strong day are one observation, not twenty. Neighbouring dates'
  trades overlap in time, so the t-stats use Newey-West errors: lags equal to the edge window for the edge, and to the
  longer of that window and the 75th-percentile holding time for E[R].
* **Many tests.** The scoreboard tests every setup (and every split). Benjamini-Hochberg q-values control the share
  of false discoveries; PROVEN also needs t >= 3, the hurdle Harvey, Liu & Zhu (2016) argue for after decades of
  factor mining.
* **Holdout.** The last part of the sample (40% of dates by default) must show the same sign.
* **Tail share.** If the best 5% of trades are more than 100% of the net R, the setup lives on rare big winners:
  sizing and patience matter more than hit rate.

#### The Gap family and the alpha splits
The Gap family tests the Brief's Top scans as trades. Each setup fires at the close of a day that opened at least 1%
over the prior close, split two ways from Kakushadze's *101 Formulaic Alphas*: where the open landed (*#20*: above
yesterday's high, or still inside yesterday's range) and how the day closed (*#101*, (close - open) / (high - low):
0.5 or more is a strong close in the top of the range, under 0 closed below the open). The "any close" rows are the
base rate for each zone. Entry follows the ledger's entry rule (next open or a buy stop over the gap day's high), with
the stop under the gap day's low. Three splits carry the same inputs to every family: *gap zone* (the signal day's open
against yesterday's range), *body* (#101 in four bins) and *VWAP* (*#42*: the close above or below the day's VWAP,
from Massive or demo bars; Yahoo bars have no VWAP). The paper's #20 has a negative sign (big gaps over the prior range
tended to fade in WorldQuant's sample); the scoreboard says whether that holds on your list.

#### The EP family (Stockbee's EP 9 million)
Pradeep Bonde (Stockbee) scans for **EP 9 million**: a day trading at least 9 million shares, which he treats as an
episodic pivot read from volume alone, usually on news. The ledger's version fires on a day with 9M+ shares, at least
3x the stock's 50-day average volume (so names that always trade 9M don't count), a close above the prior close and a
price of \\$3+. *EP 9 million, strong close* is the subset that closed in the top 30% of the day's range. The stop is the
EP day's low (his low-of-day stop), still held to the ATR band above, so a very wide EP day gets a tighter stop than
his. The family's default is a trailing exit with a 5-session limit, because he expects most of an EP's move in 3 to 5
days; set the limit off to see the longer runs. Two settings matter more here than elsewhere: the ledger's minimum
price and dollar volume (\\$10 and \\$10M by default) leave out the \\$3-10 names where many EP 9M days happen, so lower
them to test those, and the costs bite harder on cheap names. Stocks > Brief > Setups shows tonight's EP 9M names and
the Screener has an *EP 9M (sessions ago)* column.

#### Leadership concentration
Two splits read Stocks > Group leaders > Leadership entropy on each signal date (your list only): **Leadership
concentration** puts every trade in narrow, middle or broad leadership (the concentration's percentile against its
own trailing year: top third, middle, bottom third), and **Group leaders rule x leadership** crosses the rule with
narrower or broader leadership than usual. If the rule's PROVEN or PROMISING rows sit in the narrow cells and fade in
the broad ones, the rule depends on concentrated leadership. The same readings are event features
(`lead_conc`, `lead_conc_pct`, `lead_eff_groups`, and `ga_x_lead`, group strength times concentration) for the ranker
and the Simulation tab's model. Rebuild the ledger after changing the Group leaders settings.

#### Verdicts
**PROVEN**: t >= 3, q <= 0.10, holdout edge > 0, E[R] > 0. **PROMISING**: t >= 2, holdout > 0, E[R] > 0, but not the
full bar. **NEGATIVE**: reliably worse than a random uptrend name (lower-tail q <= 0.10, holdout agrees).
**NOISE**: none of these. **THIN**: fewer than 40 trades or 30 signal dates. The verdict for each MACD setup also
appears on the Screener's MACD panel.

#### Costs: flat or estimated spread
**Flat** charges the same cost in bp per side on every trade. **Estimated spread** adds half of each name's
estimated bid-ask spread on the signal date (per side, on top of the flat cost for commission and slippage), so a thin
small cap pays more than a mega cap. The spread comes from daily bars, using only the 21 sessions up to the signal:
*Abdi & Ranaldo (2017)* compares each close with the mid of the high-low range on that day and the next;
*Corwin & Schultz (2012)* compares the two-day high-low range with the one-day ranges (volatility grows with time,
the spread doesn't). Both are noisy name by name and good at ranking; on a name moving 2% a day they can't tell
spreads under about 30 bp apart (they read a floor of roughly that much even at zero), and estimates above 5% are
capped. The *spread*
split shows whether a setup's edge survives in the names that cost the most to trade.

#### Deflated Sharpe
The Sharpe ratio here is per signal date (each date's trades averaged into one R, as everywhere on the scoreboard):
the mean over its standard deviation. **P(Sharpe > 0)** is Bailey & Lopez de Prado's
probabilistic Sharpe, which corrects the confidence for skew and fat tails (a few huge winners make a high Sharpe
less certain). The **Deflated Sharpe** asks for more: the Sharpe has to beat the best one you'd expect by luck from
all the variants tested. That expected maximum grows with the number of trials, which counts every setup on the
scoreboard plus **Other variants tried**: the stop, exit and filter combinations you looked at before settling on
these settings. Be honest with that number; it is the main lever. The luck benchmark also grows with how spread
out the Sharpes on the board are, so one strong setup among many weak ones is held to a higher bar. A Deflated Sharpe of 0.95 or more means the
setup still clears the bar after all that searching. The effective sample size comes from the Newey-West error, so
overlapping trades don't count twice.

#### Excursions (MAE and MFE)
Open a setup's trades in the drill-down to see how far each one went against you (**MAE**, in R) and in your favour
(**MFE**) before it closed. Sweeney's test: if the winners rarely dipped below -0.5R, a tighter stop would have kept
nearly all of them and cut the losers sooner. The tables replay the same trades exactly: a tighter stop at -k R
(any trade whose MAE reached it; *E[R] per new risk* divides by k, because the same dollar risk buys more shares
behind a tighter stop), a fixed target at +k R (any trade whose MFE reached it), and selling half at +k R
with the rest left to the original exit. Wider stops and larger targets can't be replayed (those trades already ended
at the stop or the target), so build the ledger again for those. The **edge ratio** (Faith) is the average MFE over
the average MAE for 1 to 30 sessions after entry, in ATR; above 1 the entries tend to go your way first, and a
random entry sits near 1. All of this is fitted to the sample, so a stop chosen from these tables counts as another
variant tried.

#### Limits
Daily bars can't say whether the high or the low came first, so a bar touching both barriers counts as a stop.
Your list carries survivorship and selection bias; the whole-market universe removes most of it but still misses the
delisting loss itself. Five years of history covers few regimes; read split rows as hints. The saved ledger
(`data/setup_ledger.parquet`) carries entry features for the next step, a meta-label model that predicts which
signals of a setup to take.
"""


def render_ledger(cfg, ab, bench_bars, clim, bars) -> None:
    sec("Setup ledger: every setup traded with a stop, a target and an optional time limit, then scored honestly")
    if ab is None:
        warnbox("The ledger needs the price panel. Load a universe of at least 10 names.")
        return
    for k_, v_ in LG_DEFAULTS.items():
        st.session_state.setdefault(k_, v_)
    mk_ok, mk_why = _lg_market_ok(cfg)
    c = st.columns([3, 2, 2, 1])
    c[0].multiselect("Setup families", LG_FAMILIES, key="lg_fams")
    c[1].selectbox("MACD setting", list(MC_SETTINGS), key="lg_mset", format_func=MC_SETTING_LABEL.get)
    mode = c[2].radio("Entry", ["next_open", "buy_stop", "close"], key="lg_mode", horizontal=True,
                      format_func={"next_open": "Next open", "buy_stop": "Buy stop over the signal high",
                                   "close": "Signal-day close"}.get,
                      help="Signal-day close: bought in the last minutes on a signal that is visible then (the daily "
                           "signals are read at the close, so this assumes you act a few minutes before 4:00 on near-final "
                           "values). It keeps the overnight move that the next-open entry gives away.")
    c[3].number_input("Buy-stop days", 1, 5, step=1, key="lg_win", disabled=mode != "buy_stop",
                            help="How many sessions the buy stop stays working before it's cancelled.")
    for f_, v_ in LG_TL_SEED.items():
        st.session_state.setdefault(f"lg_tl_f_{f_}", v_)
    c = st.columns(5)
    c[0].number_input("Target (R)", 0.5, 20.0, step=0.5, key="lg_tgt", help="Used by setups whose exit is a fixed target.")
    c[1].number_input("Costs (bp per side)", 0.0, 100.0, step=1.0, key="lg_cost",
                      help="Commission plus slippage, charged on entry and exit.")
    c[2].number_input("Cooldown (sessions)", 1, 60, step=1, key="lg_cd",
                      help="After an event, the same setup on the same name is ignored for this many sessions.")
    c[3].number_input("Widest stop (ATR)", 1.0, 10.0, step=0.5, key="lg_cap")
    c[4].number_input("Edge window (sessions)", 2, 60, step=1, key="lg_h",
                      help="Each trade's forward return over this window (next open to the close N sessions later) is "
                           "compared with every uptrend name's on the same date: the edge column and its t-stat. It is "
                           "a measuring window, not an exit.")
    c = st.columns([3.3, 2.4, 3.3])
    cmode = c[0].radio("Cost model", list(LG_COST_MODES), key="lg_cost_mode", horizontal=True, format_func=LG_COST_MODES.get,
                       help="Flat: the bp above on entry and exit. Spread: each trade also pays half of its own estimated "
                            "bid-ask spread on entry and on exit, estimated from daily bars over the 21 sessions before the "
                            "signal (known at the time). The flat bp then stands for commission and slippage.")
    c[1].selectbox("Spread estimator", list(SPREAD_METHODS), key="lg_spread_m", format_func=SPREAD_METHODS.get,
                   disabled=cmode == "flat")
    c[2].caption("Every build records each trade's estimated spread, so the scoreboard can also be split by it "
                 "(Split: Estimated bid-ask spread) whichever cost model you pick.")
    c = st.columns([3.3, 1, 2.7])
    tl_mode = c[0].radio("Time limit", list(LG_TL_MODES), key="lg_tl_mode", horizontal=True, format_func=LG_TL_MODES.get,
                         help="Off: a trade ends only at its exit rule (stop, target or trailing stop). Per family: each "
                              "family gets its own limit (0 = none).")
    c[1].number_input("Sessions", 2, 250, step=1, key="lg_tl", disabled=tl_mode != "all")
    if tl_mode == "family":
        fc = st.columns(len(LG_TL_SEED))
        for col_, f_ in zip(fc, LG_TL_SEED):
            col_.number_input(f_, 0, 250, step=1, key=f"lg_tl_f_{f_}", help="Sessions; 0 = no time limit.")
        note("Seeded from the strategy research: breakout, trend and gap families (TraderLion LaunchPads, RS 8-week, Trend, "
             "Gap) have no limit; MACD, LBR and the baseline get 10 sessions. 0 means no limit.")
    else:
        c[2].caption("With the time limit off, every trade runs until its exit rule below closes it." if tl_mode == "off"
                     else "One limit for every setup.")
    for f_, v_ in LG_EXIT_SEED.items():
        st.session_state.setdefault(f"lg_ex_f_{f_}", v_)
    c = st.columns([3.3, 2.2, 0.9, 0.9, 2.2])
    ex_mode = c[0].radio("Exit", list(LG_EXIT_MODES), key="lg_exit_mode", horizontal=True, format_func=LG_EXIT_MODES.get,
                         help="Fixed target: the R target above. Trailing stop: no target; the stop ratchets up behind the "
                              "trade so big winners run. Per family: pick target or trail for each family.")
    trail_kind = c[1].selectbox("Trailing stop", list(LG_TRAIL_KINDS), key="lg_trail", format_func=LG_TRAIL_KINDS.get,
                                disabled=ex_mode == "target")
