def am_alpha_cat(col: str) -> str:
    """The category an alpha input belongs to (the engine's map: selected and reference alphas), or the category
    score's own; 'ALL' for the composite."""
    if col.startswith("al_cat_"):
        return col[7:]
    if col.startswith("al_a"):
        return ID_TO_CAT.get(int(col[4:]), "")
    return "ALL"


def am_side_text(col: str, better: str) -> str:
    """What the better side of an input means, in words."""
    if col.startswith("al_a"):
        hi, lo = AM_ALPHA_SIDES.get(int(col[4:]), ("high", "low"))
    elif col.startswith("al_cat_"):
        hi, lo = AM_CAT_SIDES.get(col[7:], ("high", "low"))
    else:
        hi, lo = "the composite's favourites", "the composite's least favoured"
    return hi if better == "high" else lo


def am_collect(ss, orb_rows: Optional[pd.DataFrame] = None, saved_ledger: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    """Every scored trade the session has, one row each: source, setup, trade type, side (long or short), ticker,
    signal date, R after costs, and lag (0: the alphas at the signal's own close; 1: the gap trades, at the prior
    close). Reads the Setup ledger (whole market first, then your list; the saved file when nothing was built), Bull
    and Bear spreads, and the breakout model's trades (which carry their alpha inputs already). A trade in both
    Setup ledger runs counts once."""
    parts = []

    def add(ev, source, base_type):
        if ev is None or not len(ev) or not {"setup", "ticker", "date", "r"} <= set(ev.columns):
            return
        d = ev[(ev["status"] == 0) if "status" in ev else slice(None)]
        d = d[np.isfinite(d["r"].to_numpy(float))]
        if not len(d):
            return
        typ = d["setup"].map(lambda s: base_type if str(s).startswith("base:") else AM_TYPES.get(str(s), ""))
        parts.append(pd.DataFrame({"source": source, "setup": d["setup"].astype(str).to_numpy(), "type": typ.to_numpy(),
                                   "ticker": d["ticker"].astype(str).to_numpy(), "date": pd.to_datetime(d["date"]).to_numpy(),
                                   "r": d["r"].to_numpy(float), "lag": 0}))
    lg = ss.get("lg_res") if hasattr(ss, "get") else None
    if lg and lg.get("runs"):
        for k in ("market", "list"):
            if k in lg["runs"]:
                add(lg["runs"][k].get("ev"), f"Setup ledger ({'whole market' if k == 'market' else 'your list'})",
                    "Baseline: long ledger")
    elif saved_ledger is not None:
        add(saved_ledger, "Setup ledger (saved)", "Baseline: long ledger")
    for key_, src_, base_ in (("bls_res", "Bull spreads", "Baseline: bull spreads"),
                              ("bsp_res", "Bear spreads", "Baseline: bear spreads")):
        r_ = ss.get(key_) if hasattr(ss, "get") else None
        if r_ and r_.get("run"):
            add(r_["run"].get("ev"), src_, base_)
    out = pd.concat(parts, ignore_index=True) if parts else pd.DataFrame(
        columns=["source", "setup", "type", "ticker", "date", "r", "lag"])
    if len(out):
        led = out["source"].str.startswith("Setup ledger")
        dup = led & out.duplicated(["setup", "ticker", "date"], keep="first") & led
        out = out[~dup]
        out = out[out["type"] != ""]
    if orb_rows is not None and len(orb_rows):
        o = orb_rows
        for h, typ in (("intra", "Gap-up ORB, intraday"), ("swing", "Gap-up ORB, swing")):
            col = f"{h}_R"
            if col not in o:
                continue
            k_ = o[np.isfinite(o[col].to_numpy(float))]
            add_ = pd.DataFrame({"source": "Breakout model", "setup": "orb:" + k_["m"].astype(int).astype(str) + "m",
                                 "type": typ, "ticker": k_["ticker"].astype(str).to_numpy(),
                                 "date": pd.to_datetime(k_["date"]).to_numpy(), "r": k_[col].to_numpy(float), "lag": 1})
            for c_ in OB_ALPHA_COLS:
                if c_ in k_:
                    add_[c_] = k_[c_].to_numpy(np.float32)
            out = pd.concat([out, add_], ignore_index=True)
    out["side"] = np.where(out["type"].astype(str).str.startswith(("Short", "Baseline: bear")), "short", "long")
    base_ = out["setup"].astype(str).str.startswith("base:")          # the same baseline id means different things
    out["setup_key"] = np.where(base_, out["setup"].astype(str) + " · " + out["source"].astype(str), out["setup"].astype(str))
    return out.reset_index(drop=True)


def am_attach(P: Dict[str, pd.DataFrame], ev: pd.DataFrame, top_n: int = OB_ALPHA_TOPN, progress=None) -> pd.DataFrame:
    """The alpha inputs at each trade's signal close (lag 0) for the trades that don't carry them yet."""
    ev = ev.copy()
    for c_ in OB_ALPHA_COLS:
        if c_ not in ev:
            ev[c_] = np.nan
    need = ev[ev["lag"] == 0] if "lag" in ev else ev
    if not len(need):
        return ev
    pairs = need[["ticker", "date"]].drop_duplicates()
    al = ob_alpha_inputs(P, pairs, top_n, progress, lag=0)
    if not len(al):
        return ev
    al = al.drop_duplicates(["ticker", "date"]).set_index(["ticker", "date"])
    key = pd.MultiIndex.from_arrays([need["ticker"], pd.to_datetime(need["date"])])
    vals = al.reindex(key)[list(OB_ALPHA_COLS)].to_numpy(np.float32)
    ev.loc[need.index, list(OB_ALPHA_COLS)] = vals
    return ev


def am_cluster_ols(X: np.ndarray, y: np.ndarray, g: np.ndarray) -> Tuple[np.ndarray, np.ndarray]:
    """OLS with standard errors clustered by g (Liang-Zeger sandwich, small-sample factor)."""
    n, k = X.shape
    inv = np.linalg.pinv(X.T @ X)
    b = inv @ (X.T @ y)
    e = y - X @ b
    codes = np.unique(g, return_inverse=True)[1]
    G = int(codes.max()) + 1 if len(codes) else 0
    if G < 2 or n <= k:
        return b, np.full(k, np.nan)
    S = np.stack([np.bincount(codes, weights=X[:, j] * e, minlength=G) for j in range(k)], axis=1)
    V = inv @ (S.T @ S) @ inv * (G / (G - 1)) * ((n - 1) / (n - k))
    return b, np.sqrt(np.clip(np.diag(V), 0, None))


def am_profile(ev: pd.DataFrame, group_col: str = "type", inputs: Sequence[str] = OB_ALPHA_COLS) -> pd.DataFrame:
    """For each trade type (or setup) and alpha input: the within-setup slope of R from the bottom of the crowd to the
    top (each setup's average R removed; t clustered by date), the same slope in each half of the history, the
    average R in the crowd's bottom and top fifths, a U-shape test (the squared term), BH q across every row.
    Status: MATTERS (|t| >= 2.5, showing in both halves: the same sign and t of 1+ in each, q <= 0.10), MAYBE
    (|t| >= 2), NO EFFECT, THIN (under 100 trades or 30 dates)."""
    out = []
    for gname, d in ev.groupby(group_col, sort=False):
        d = d[np.isfinite(d["r"].to_numpy(float))]
        side = d["side"].iloc[0] if "side" in d and len(d) else "long"
        r = d["r"].to_numpy(float)
        dem = r - d.groupby("setup")["r"].transform("mean").to_numpy(float)
        dates = pd.to_datetime(d["date"]).to_numpy()
        mid = np.sort(np.unique(dates))[len(np.unique(dates)) // 2] if len(d) else None
        for col in inputs:
            if col not in d:
                continue
            x = d[col].to_numpy(float)
            ok = np.isfinite(x)
            rec = {group_col: gname, "side": side, "input": col, "category": am_alpha_cat(col), "label": ob_alpha_label(col),
                   "n": int(ok.sum()), "dates": int(len(np.unique(dates[ok]))) if ok.any() else 0,
                   "setups": int(d.loc[ok, "setup"].nunique()) if ok.any() else 0}
            if rec["n"] < AM_MIN_TRADES or rec["dates"] < AM_MIN_DATES:
                out.append({**rec, "status": "THIN"})
                continue
            xo, yo, go = x[ok], dem[ok], dates[ok]
            ro = r[ok]
            xc = xo - xo.mean()
            b, se = am_cluster_ols(np.column_stack([np.ones(len(xo)), xc]), yo, go)
            z = xc ** 2 - (xc ** 2).mean()
            b2, se2 = am_cluster_ols(np.column_stack([np.ones(len(xo)), xc, z]), yo, go)
            h1 = go < mid
            sl, th = [], []
            for part in (h1, ~h1):
                if part.sum() >= 30 and np.var(xo[part]) > 0:
                    xp = xo[part] - xo[part].mean()
                    bh, seh = am_cluster_ols(np.column_stack([np.ones(len(xp)), xp]), yo[part], go[part])
                    sl.append(float(bh[1]))
                    th.append(float(bh[1] / seh[1]) if np.isfinite(seh[1]) and seh[1] > 0 else np.nan)
                else:
                    sl.append(np.nan)
                    th.append(np.nan)
            fifth = np.clip(np.floor((xo + 0.5) * 5), 0, 4).astype(int)
            lo, hi = ro[fifth == 0], ro[fifth == 4]
            dlo, dhi = yo[fifth == 0], yo[fifth == 4]
            t = b[1] / se[1] if np.isfinite(se[1]) and se[1] > 0 else np.nan
            t2 = b2[2] / se2[2] if np.isfinite(se2[2]) and se2[2] > 0 else np.nan
            rec.update({"slope": float(b[1]), "t": float(t), "slope_h1": sl[0], "slope_h2": sl[1],
                        "halves": bool(all(np.isfinite(v_) for v_ in th) and np.sign(th[0]) == np.sign(th[1]) == np.sign(b[1])
                                       and min(abs(th[0]), abs(th[1])) >= 1.0),
                        "R_lo": float(lo.mean()) if len(lo) >= 10 else np.nan, "n_lo": int(len(lo)),
                        "R_hi": float(hi.mean()) if len(hi) >= 10 else np.nan, "n_hi": int(len(hi)),
                        "effect": float(dhi.mean() - dlo.mean()) if min(len(dlo), len(dhi)) >= 10 else np.nan,
                        "t_curve": float(t2), "p": math.erfc(abs(t) / math.sqrt(2)) if np.isfinite(t) else np.nan})
            out.append(rec)
    T = pd.DataFrame(out)
    if not len(T):
        return T
    for c_ in ("slope", "t", "p", "halves", "R_lo", "R_hi", "effect", "t_curve", "slope_h1", "slope_h2"):
        if c_ not in T:
            T[c_] = np.nan
    T["q"] = lg_bh(T["p"].to_numpy(float))

    def status(r_):
        if r_.get("status") == "THIN":
            return "THIN"
        t_ = _n(r_.get("t"), np.nan)
        if not np.isfinite(t_):
            return "NO EFFECT"
        if abs(t_) >= ML_T_USE and bool(r_.get("halves")) and _n(r_.get("q"), 1) <= 0.10:
            return "MATTERS"
        if abs(t_) >= 2.0:
            return "MAYBE"
        return "NO EFFECT"
    T["status"] = [status(r_) for r_ in T.to_dict("records")]
    T["better"] = np.where(T["slope"].to_numpy(float) > 0, "high", "low")
    T["shape"] = np.where(T["t_curve"].to_numpy(float) >= ML_T_USE, "U (both extremes better)",
                          np.where(T["t_curve"].to_numpy(float) <= -ML_T_USE, "∩ (the middle better)", ""))
    return T


def am_why(typ: str, side: str, cat: str, row: Dict[str, Any], lead: Optional[Dict[str, Any]]) -> str:
    """One category's reading for one trade type: which way it cuts and by how much (within setups), what that side
    means, the alpha that leads it, what that says about the trade, and the usual reading where there is one."""
    st_ = row.get("status", "")
    prior = AM_PRIOR.get((typ, cat))
    if st_ == "THIN":
        return "Too few trades to say."
    better = row.get("better", "high")
    t = _n(row.get("t"), np.nan)
    hi, lo = AM_CAT_SIDES.get(cat, ("high", "low"))
    eff = _n(row.get("effect"), np.nan)
    if st_ in ("MATTERS", "MAYBE"):
        txt = f"Better when {better} ({hi if better == 'high' else lo})."
        if np.isfinite(eff):
            txt += (f" Trades in the crowd's top fifth did {abs(eff):.2f}R {'better' if eff > 0 else 'worse'} than the "
                    f"bottom fifth, within setups (t {t:+.1f}).")
        else:
            txt += f" Within-setup t {t:+.1f}."
        if lead is not None and lead.get("input") != row.get("input"):
            lb = lead.get("better", better)
            txt += (f" Led by {ob_alpha_label(lead['input'])}: better when {am_side_text(lead['input'], lb)} "
                    f"(t {_n(lead.get('t'), np.nan):+.1f}).")
        rd = AM_READ.get((side, cat, better))
        if rd:
            txt += f" Reading: {rd}."
        if row.get("shape"):
            txt += f" Shape: {row['shape']}."
        if prior:
            txt += (f" The usual reading ({prior[0]} is better: {prior[1]}) "
                    + ("agrees." if prior[0] == better else "is the opposite of what these trades did."))
        return txt
    txt = f"No reliable difference between the top and bottom of the crowd (t {t:+.1f})."
    if lead is not None and lead.get("status") in ("MATTERS", "MAYBE"):
        txt += (f" One alpha in it stands out: {ob_alpha_label(lead['input'])}, better when "
                f"{am_side_text(lead['input'], lead.get('better', 'high'))} (t {_n(lead.get('t'), np.nan):+.1f}, "
                f"{lead['status'].lower()}).")
    if prior:
        txt += f" The usual reading ({prior[0]} is better: {prior[1]}) isn't borne out here."
    return txt


def am_summary(T: pd.DataFrame, group_col: str = "type") -> pd.DataFrame:
    """Per trade type and category: the category score's own result, the alpha in the category with the strongest
    result, and the reading. Sorted within each type by how strongly the category separates winners from losers."""
    if T is None or not len(T):
        return pd.DataFrame()
    rows = []
    rank_st = {"MATTERS": 0, "MAYBE": 1, "NO EFFECT": 2, "THIN": 3}
    for g, d in T.groupby(group_col, sort=False):
        side = d["side"].iloc[0]
        for cat in OB_ALPHA_CATS:
            rc = d[d["input"] == f"al_cat_{cat}"]
            if not len(rc):
                continue
            rc = rc.iloc[0].to_dict()
            al = d[(d["category"] == cat) & d["input"].str.startswith("al_a")].copy()
            lead = None
            if len(al):
                al["_k"] = al["status"].map(rank_st).fillna(9)
                al["_a"] = -al["t"].abs().fillna(0)
                lead = al.sort_values(["_k", "_a"]).iloc[0].to_dict()
            strength = max(abs(_n(rc.get("t"), 0)), abs(_n((lead or {}).get("t"), 0)) if lead and lead.get("status") in ("MATTERS", "MAYBE") else 0)
            best_st = min([rank_st.get(rc.get("status"), 9)] + ([rank_st.get(lead.get("status"), 9)] if lead else []))
            prior = AM_PRIOR.get((g, cat))
            rows.append({group_col: g, "side": side, "category": cat, "cat_label": AM_CAT_LABEL.get(cat, cat),
                         "status": rc.get("status"), "better": rc.get("better") if rc.get("status") != "THIN" else "",
                         "effect": rc.get("effect"), "t": rc.get("t"), "q": rc.get("q"), "n": rc.get("n"),
                         "lead": ob_alpha_label(lead["input"]) if lead else "", "lead_status": (lead or {}).get("status", ""),
                         "lead_better": (lead or {}).get("better", ""), "lead_t": (lead or {}).get("t", np.nan),
                         "best_status": [k for k, v in rank_st.items() if v == best_st][0] if best_st < 9 else "",
                         "strength": strength,
                         "prior": f"{prior[0]} ({prior[1]})" if prior else "",
                         "prior_check": ("" if not prior or rc.get("status") == "THIN" else
                                         ("agrees" if rc.get("status") in ("MATTERS", "MAYBE") and prior[0] == rc.get("better")
                                          else ("opposite" if rc.get("status") in ("MATTERS", "MAYBE") else "not seen"))),
                         "why": am_why(g, side, cat, rc, lead)})
    S = pd.DataFrame(rows)
    if not len(S):
        return S
    for c_ in ("effect", "t", "q", "n", "lead_t", "strength"):
        S[c_] = pd.to_numeric(S[c_], errors="coerce")
    S["_o"] = S["best_status"].map(rank_st).fillna(9)
    return S.sort_values([group_col, "_o", "strength"], ascending=[True, True, False],
                         key=lambda s: s.map({t: i for i, t in enumerate(AM_TYPE_ORDER)}).fillna(99) if s.name == group_col else s
                         ).drop(columns=["_o"]).reset_index(drop=True)


AM_GUIDE = """
**What it answers.** Whether the alpha engine's categories separate winners from losers differently for different
kinds of trade: mean reversion for shorts and rebounds, VWAP and coils for breakouts, and so on. It reads the trades
the lab has already scored: build the Setup ledger (Stocks), Bull spreads or Bear spreads (Options), or the breakout
model's trades (Stocks > Breakout model) first.

**The inputs.** At each trade's signal close (the gap trades: the close before the gap), the engine's 27 alphas
(the three industry-neutral ones need an industry map), the six category scores (each the average of its selected
alphas' percentiles) and the composite, each placed among that day's 1,000 most-traded names as a percentile. On
Massive and Demo the crowd is the whole market; on Yahoo, your list. VWAP is the day's typical price on daily bars,
so the VWAP alphas read the close against the day's range.

**The test, per trade type and input.**
- *Within setups:* each setup's own average R is taken out first, so a type that mixes setups with different
  averages and different alpha profiles can't show a false effect.
- *Slope:* R from the bottom of the crowd to the top (a straight line through every trade), with standard errors
  clustered by date (trades on the same day move together).
- *Both halves:* the slope has to show in the first and the second half of the history (the same sign, a t of
  1+ in each), so one good stretch can't carry it.
- *Many tests:* 34 inputs x every trade type is a lot of tries, so Benjamini-Hochberg q (the false discovery
  rate) across all of them.
- *MATTERS:* |t| of 2.5+, both halves, q of 0.10 or less. MAYBE: |t| of 2+. THIN: under 100 trades or 30 dates.
- *Shape:* a squared term catches U-shapes (both extremes better) a straight line misses.
- *Fifths:* the trades in the crowd's top fifth less those in the bottom fifth, within setups, as the effect in R
  (the drill-down also shows each fifth's plain average R).

**The reading.** For each category: what high and low mean for its alphas, the alpha in it with the strongest
result (categories mix alphas that don't all point the same way, so the leader says what actually drove it), what
that implies about the trade, and the usual reading where there is one. "Opposite" is worth a look: either the
intuition is wrong for these trades or the setup already selects on it.

**Traps.** It's an association in the ledger's own history, not a tested prediction; the breakout model's section 3
tests prediction out of sample. Setups picked by an alpha (the mean-reversion dips and fades) have that alpha cut
short, so its effect inside them is muted. A busy baseline (every uptrend day) has the power to make small effects
significant: read the size in R, not just the t.

**Sources.** Kakushadze (2016), "101 formulaic alphas". Cameron, Gelbach and Miller (2011), "Robust inference with
multiway clustering", *JBES* 29 (clustered errors). Benjamini and Hochberg (1995), *JRSS B* 57. Harvey, Liu and Zhu
(2016), "...and the cross-section of expected returns", *RFS* 29 (why many tests need a higher bar).
"""


def am_heatmap(S: pd.DataFrame):
    """Trade types x categories: colour = the category score's t (green: better when high; red: better when low),
    text = top fifth minus bottom fifth in R, * where it matters."""
    d = S[S["status"] != "THIN"].copy()
    if not len(d):
        return None
    d["tc"] = d["t"].clip(-4, 4)
    d["txt"] = [(f"{e:+.2f}" if np.isfinite(e) else "") + ("*" if s_ == "MATTERS" else "") for e, s_ in zip(d["effect"], d["status"])]
    order = [t for t in AM_TYPE_ORDER if t in set(d["type"])]
    cats = [AM_CAT_LABEL.get(c, c) for c in OB_ALPHA_CATS]
    base = alt.Chart(d).encode(x=alt.X("cat_label:N", sort=cats, title=None, axis=alt.Axis(labelAngle=0)),
                               y=alt.Y("type:N", sort=order, title=None))
    rect = base.mark_rect(stroke="#09090e", strokeWidth=2).encode(
        color=alt.Color("tc:Q", scale=alt.Scale(domain=[-4, 0, 4], range=[C_RED, "#1b1b24", C_GREEN]),
                        legend=alt.Legend(title="t (better when high: green)", orient="top")),
        tooltip=["type", "cat_label", "status", alt.Tooltip("effect:Q", format="+.3f", title="top - bottom fifth (R)"),
                 alt.Tooltip("t:Q", format="+.1f"), alt.Tooltip("q:Q", format=".3f"), "n", "lead", "lead_status"])
    text = base.mark_text(fontSize=12).encode(text="txt:N", color=alt.value(C_TEXT))
    return (rect + text).properties(height=34 * len(order) + 40)


def render_am(cfg, ab, bars: Dict[str, pd.DataFrame]) -> None:
    ss = st.session_state
    sec("Alphas by trade: which alpha categories matter for which kind of trade, and why")
    src = cfg["source"]
    orb = ss.get("obx_trades") or (ml_load("orb_trades.pkl") if src == "massive" else None)
    saved = None
    if not ss.get("lg_res") and LG_FILE.exists():
        try:
            saved = memo(("am_lg_file", LG_FILE.stat().st_mtime), lambda: pd.read_parquet(LG_FILE))
        except Exception:
            saved = None
    ev_all = am_collect(ss, orb["rows"] if orb else None, saved)
    if not len(ev_all):
        note("No scored trades yet. This tab reads the trades the lab has built: the Setup ledger (Stocks > Setup "
             "ledger), Bull spreads and Bear spreads (Options) and the breakout model's gap-up trades (Stocks > "
             "Breakout model). Build one or more, then come back.")
        with st.expander("How the alpha map works, and the sources"):
            st.markdown(AM_GUIDE)
        return
    cnt = ev_all.groupby("source").size()
    srcs = list(cnt.index)
    c = st.columns([3, 1])
    pick = c[0].multiselect("Trades from", srcs, default=srcs, key=f"amx_src_{zlib.crc32('|'.join(srcs).encode())}",
                            format_func=lambda s_: f"{s_} ({int(cnt[s_]):,} trades)",
                            help="Every ledger built this session (a new one shows up here, selected, the next time the "
                                 "page reruns or you press Map the alphas).")
    go = c[1].button("Map the alphas", key="amx_go", type="primary")
    sig = (tuple(sorted(pick)), len(ev_all), str(ev_all["date"].max()))
    if go and pick:
        ev = ev_all[ev_all["source"].isin(pick)]
        prog = st.progress(0.0, text="Daily panel for the alphas")
        need0 = ev["lag"] == 0
        if need0.any():
            span = (pd.to_datetime(ev["date"]).max() - pd.to_datetime(ev["date"]).min()).days / 365.25
            years = int(min(max(math.ceil(span) + 1, 2), 6))
            P, lab = (ml_panel(cfg, bars, years, prog) if src in ("massive", "demo") else (None, ""))
            crowd = "the 1,000 most-traded names in the whole market"
            if P is None and ab is not None and ab.get("P") is not None:
                P, lab, crowd = ab["P"], "your universe", "your list"
            if P is None:
                warnbox(f"Alphas by trade: no daily panel to compute the alphas on ({lab}).")
                prog.empty()
                return
            prog.progress(0.3, text=f"Alpha inputs at {int(need0.sum()):,} signal closes ({lab})")
            key_ = ("am_attach", lab, P["close"].shape, str(P["close"].index[-1]),
                    zlib.crc32(pd.util.hash_pandas_object(ev.loc[need0, ["ticker", "date"]], index=False).values.tobytes()))
            ev = memo(key_, lambda: am_attach(P, ev), capacity=4)
        else:
            crowd = "the 1,000 most-traded names"
        prog.progress(0.85, text="Per trade type and alpha")
        T = am_profile(ev)
        Tset = am_profile(ev, "setup_key")
        ss["amx_res"] = {"sig": sig, "T": T, "S": am_summary(T), "Tset": Tset, "n": len(ev),
                         "coverage": float(ev["al_composite"].notna().mean()) if "al_composite" in ev else 0.0,
                         "crowd": crowd, "types": ev.groupby("type").agg(trades=("r", "size"), setups=("setup", "nunique"),
                                                                         R=("r", "mean"), side=("side", "first")).reset_index()}
        prog.empty()
    res = ss.get("amx_res")
    if res is None:
        note("Pick the trades to read and press Map the alphas. Each trade gets the engine's alphas at its signal close, "
             "and each trade type is tested for which categories separate its winners from its losers.")
        with st.expander("How the alpha map works, and the sources"):
            st.markdown(AM_GUIDE)
        return
    if res["sig"] != sig:
        note("The trades changed since this map was made (a ledger was rebuilt or the sources changed): press Map the "
             "alphas to refresh it.")
    T, S = res["T"], res["S"]
    mat = S[S["status"] == "MATTERS"] if len(S) else S
    nb = S[~S["type"].str.startswith("Baseline") & S["t"].notna()].copy() if len(S) else S
    if len(nb):
        nb["_k"] = nb["status"].map({"MATTERS": 0, "MAYBE": 1}).fillna(2)
        nb["_a"] = -nb["t"].abs()
    top = nb.sort_values(["_k", "_a"]).iloc[0] if len(nb) else None
    kpi_row([kpi_html("Trades mapped", f"{res['n']:,}", f"{res['coverage']:.0%} with alpha inputs; crowd: {res['crowd']}"),
             kpi_html("Trade types", int(S["type"].nunique()) if len(S) else 0, "with enough trades to test"),
             kpi_html("Categories that matter", len(mat), "type x category cells passing the bar", "good" if len(mat) else ""),
             kpi_html("Strongest", f"{top['cat_label']}" if top is not None else "none",
                      f"{top['type']}: better when {top['better']}, t {_n(top['t'], np.nan):+.1f}" if top is not None else "")])
    sec("1 · The map: trade types x alpha categories")
    hm = am_heatmap(S) if len(S) else None
    if hm is not None:
        try:
            show_chart(hm.configure_view(strokeWidth=0).configure_axis(labelColor=C_MUTED, titleColor=C_MUTED, gridColor="rgba(0,0,0,0)",
                                                                      labelLimit=260)
                       .configure_legend(labelColor=C_MUTED, titleColor=C_MUTED))
        except Exception:
            show_df(S.pivot_table(index="type", columns="cat_label", values="t"))
    note("Each cell: does the trade do better when the category is high in the crowd (green) or low (red), within "
         "setups, with t clustered by date (colour, capped at 4). The number is the effect in R: trades in the crowd's top "
         "fifth less the bottom fifth, within setups. * = MATTERS (|t| 2.5+, showing in both halves of the history, "
         "BH q 0.10 or less across every cell and alpha). For shorts, better means the short made more.")
    sec("2 · What matters and why, by trade type")
    types = [t for t in AM_TYPE_ORDER if t in set(S["type"])] if len(S) else []
    if not types:
        note("No trade type has enough trades (100 and 30 dates) to test.")
    else:
        default = next((t for t in types if (S[(S["type"] == t)]["status"] == "MATTERS").any()), types[0])
        tsel = st.selectbox("Trade type", types, index=types.index(default), key="amx_type",
                            format_func=lambda t: f"{t} ({int(res['types'].set_index('type').at[t, 'trades']):,} trades)"
                            if t in set(res["types"]["type"]) else t)
        info = res["types"].set_index("type").loc[tsel] if tsel in set(res["types"]["type"]) else None
        side_ = (info["side"] if info is not None else "long")
        note(f"{tsel}: {AM_TYPE_DESC.get(tsel, '')}. {int(info['setups']) if info is not None else 0} setup(s), "
             f"{int(info['trades']) if info is not None else 0:,} trades, average {_n(info['R'] if info is not None else np.nan, np.nan):+.2f}R "
             f"({side_})." + "".join(
                 f" Some of its setups are picked by the {AM_CAT_LABEL[c_].lower()} alphas themselves, so that category's "
                 "range inside them is cut short and its effect there understated."
                 for c_ in sorted({AM_ALPHA_DEFINED[s_] for s_ in AM_ALPHA_DEFINED if AM_TYPES.get(s_) == tsel})))
        St = S[S["type"] == tsel]
        lines = []
        for r_ in St.to_dict("records"):
            mark = {"MATTERS": "**", "MAYBE": ""}.get(r_["best_status"], "")
            lines.append(f"- {mark}{r_['cat_label']}{mark} · *{r_['status'].lower()}*. {_esc(r_['why'])}")
        st.markdown("\n".join(lines))
        P_ = st.column_config.NumberColumn
        drill = T[T["type"] == tsel].copy()
        drill["_a"] = -drill["t"].abs().fillna(0)
        drill = drill.sort_values(["_a"]).drop(columns=["_a"])
        drill["category"] = drill["category"].map(lambda c_: AM_CAT_LABEL.get(c_, c_) if c_ != "ALL" else "Composite")
        drill["better_means"] = [am_side_text(i_, b_) if s_ in ("MATTERS", "MAYBE") else "" for i_, b_, s_ in
                                 zip(drill["input"], drill["better"], drill["status"])]
        cols = [c_ for c_ in ("label", "category", "status", "better", "better_means", "R_hi", "R_lo", "effect", "slope", "t",
                              "q", "halves", "shape", "n", "dates") if c_ in drill]
        with st.expander(f"Every alpha input for {tsel}"):
            show_df(drill[cols], column_config={
                "label": st.column_config.TextColumn("alpha input"), "better": st.column_config.TextColumn("better when"),
                "better_means": st.column_config.TextColumn("which means"),
                "R_hi": P_("avg R, top fifth", format="%+.3f"), "R_lo": P_("avg R, bottom fifth", format="%+.3f"),
                "effect": P_("top less bottom, within setups (R)", format="%+.3f"), "slope": P_("within-setup slope (R)", format="%+.3f"),
                "t": P_("t (by date)", format="%+.1f"), "q": P_("BH q", format="%.3f"),
                "halves": st.column_config.CheckboxColumn("shows in both halves"), "n": P_("trades")})
        Ts = res["Tset"]
        if Ts is not None and len(Ts):
            sets = [s_ for s_, t_ in AM_TYPES.items() if t_ == tsel] + (["orb:5m", "orb:15m", "orb:30m"] if tsel.startswith("Gap-up ORB") else [])
            Tc = Ts[Ts["setup_key"].isin(sets) & Ts["input"].str.startswith("al_cat_")].copy()
            if tsel.startswith("Baseline"):
                src_b = {"Baseline: long ledger": "Setup ledger", "Baseline: bull spreads": "Bull spreads",
                         "Baseline: bear spreads": "Bear spreads"}[tsel]
                Tc = Ts[Ts["setup_key"].str.startswith("base:") & Ts["setup_key"].str.contains(src_b, regex=False)
                        & Ts["input"].str.startswith("al_cat_")].copy()
            if len(Tc):
                Tc["cat"] = Tc["category"].map(lambda c_: AM_CAT_LABEL.get(c_, c_))
                Tc["cell"] = [("" if s_ == "THIN" else f"{t_:+.1f}" + ("*" if s_ == "MATTERS" else "")) for t_, s_ in zip(Tc["t"], Tc["status"])]
                pv = Tc.pivot_table(index="setup_key", columns="cat", values="cell", aggfunc="first").fillna("thin")
                pv.index = [(LG_SETUPS.get(k_.split(" · ")[0], BL_SETUPS.get(k_.split(" · ")[0], BR_SETUPS.get(k_.split(" · ")[0], ("", k_))))[1] or k_)
                            + (f" ({k_.split(' · ')[1]})" if " · " in k_ else "") for k_ in pv.index]
                with st.expander(f"Setup by setup inside {tsel} (t per category; * = matters)"):
                    show_df(pv.reset_index().rename(columns={"index": "setup"}))
    sec("3 · Each category, across every trade")
    if len(S):
        cs = st.radio("Category", [AM_CAT_LABEL.get(c_, c_) for c_ in OB_ALPHA_CATS], horizontal=True, key="amx_cat")
        cc = S[S["cat_label"] == cs].copy()
        cc["_k"] = cc["type"].map({t: i for i, t in enumerate(AM_TYPE_ORDER)})
        cc = cc.sort_values("_k")
        cat_code = cc["category"].iloc[0] if len(cc) else ""
        hi_m, lo_m = AM_CAT_SIDES.get(cat_code, ("", ""))
        note(f"{cs}. High: {hi_m}. Low: {lo_m}.")
        P_ = st.column_config.NumberColumn
        show_df(cc[["type", "side", "status", "better", "effect", "t", "q", "lead", "lead_status", "prior", "prior_check"]],
                column_config={"type": st.column_config.TextColumn("trade type"), "better": st.column_config.TextColumn("better when"),
                               "effect": P_("top less bottom fifth, within setups (R)", format="%+.3f"), "t": P_("t", format="%+.1f"),
                               "q": P_("BH q", format="%.3f"), "lead": st.column_config.TextColumn("leading alpha"),
                               "lead_status": st.column_config.TextColumn("leader"),
                               "prior": st.column_config.TextColumn("the usual reading"),
                               "prior_check": st.column_config.TextColumn("here")})
    note("Descriptive: how each trade's R lined up with the alphas in the ledger's own history, within setups, with the "
         "bar raised for the number of tests. It's not a tested prediction: the breakout model's section 3 runs the "
         "alphas out of sample. A category matters for a trade type when it reliably sorts its winners from its losers; "
         "the reading says which way and what the leading alpha measures.")
    with st.expander("How the alpha map works, and the sources"):
        st.markdown(AM_GUIDE)


# ═══════════════════════════════════════════════════════════════════════════
#  TRADE RANKER  (Stocks > Trade ranker)
#  One ranked list from every screen. The screens propose candidates (every setup in the ledger); a gradient-
#  boosted tree model decides which to take: meta-labeling (López de Prado 2018, ch. 3). Inputs are each name's
#  screen readings on the signal day (RS rating, alpha composite, 8-week EMA distance, LaunchPad, MACD-V, setups
#  firing together, stop distance...) plus the Market tab's context on that date (climate, SPY cycle, breadth,
#  factor z-scores, turbulence). Label: did the ledger trade make money after costs.
#  Trees, not a deep net: on tabular data of this size boosted trees beat neural nets (Grinsztajn et al. 2022),
#  and even with 60 years of every US stock nets only edged trees and shallow beat deep (Gu, Kelly & Xiu 2020).
#  Honesty rules:
#    - walk-forward: each test block is scored by a model trained only on trades that had closed before it began
#    - probabilities are calibrated on those out-of-sample scores (isotonic), so 60% means about 60%
#    - the bar: an equal-weight consensus rank of the same screens. Each method picks its top K names per day and
#      takes the average R of that name's setups that day; the model must beat the consensus (paired per date,
#      Newey-West t >= 2.5, positive in both halves of the test period) and the best single setup chosen on
#      training data. Otherwise the tab says to use the
#      consensus rank.
#    - reasons: each input's push on a name's score, measured by resetting that input to its typical value
# ═══════════════════════════════════════════════════════════════════════════

RK_FEATURES: Dict[str, str] = {
    "rs_rating": "RS rating", "alpha_pct": "Alpha composite", "ext8w": "Distance to 8-week EMA", "lp_spread6": "LaunchPad spread",
    "lp_on": "LaunchPad today", "rs_nh": "RS line at a 52-week high", "n_setups": "Setups firing together", "mv": "MACD-V",
    "w_macdv": "Weekly MACD-V", "imp": "Daily impulse", "w_imp": "Weekly impulse", "zlr_ratio": "Fly-by depth",
    "ext50": "Distance to 50-day", "ext200": "Distance to 200-day", "rs63": "3-month return vs SPY",
    "dist_hi252": "Distance from 52-week high", "vol_ratio": "Volume vs 50-day avg", "adr20": "ADR", "atr_pct": "ATR % of price",
    "gap": "Signal-day gap", "clv": "Close in day's range", "plan_risk_atr": "Stop distance (ATR)", "above200": "Above 200-day",
    "log_dv": "Dollar volume (log)", "breadth50": "Breadth (share above 50-day)", "spy_r20": "SPY 20-day return",
    "z_equity": "Climate: equity", "z_size": "Climate: small caps", "z_growth": "Climate: growth", "z_credit": "Climate: credit",
    "z_rates": "Climate: rates", "z_vol": "Climate: volatility", "z_mom": "Climate: momentum factor",
    "turb_pct": "Turbulence percentile", "cons_in": "Consensus rank that day",
    "nar_growth": "Narrative: growth news", "nar_monetary": "Narrative: policy news", "nar_premium": "Narrative: risk premium",
    "nar_hedging": "Narrative: flight to safety", "sb_corr": "Stock-bond correlation", "roro_20": "Risk appetite (RORO)",
    "roro_acc": "RORO acceleration", "usd_20": "Dollar momentum", "usd_acc": "Dollar acceleration", "carry_5": "Yen 5-day move",
    "credit_div": "Equity minus credit", "cg_20": "Copper / gold", "be_20": "Breakevens", "rr_20": "Real yields",
    "lvl_20": "Yield level change", "slope_20": "Curve slope change", "lead_spec": "Speculative pairs leading",
    "lead_cyc": "Cyclical pairs leading", "lead_comm": "Commodity pairs leading", "lead_idio": "Idiosyncratic pairs leading",
    "lead_all": "Leadership pairs leading",
    "z_qmj": "Style: quality vs junk", "z_vm": "Style: value vs momentum", "z_def": "Style: defensive", "z_carry": "Style: yen carry",
    "spy_dd": "SPY drawdown from 52-week high", "trend_pct": "SPY vs 5-year trend (pct)", "credit_pct": "Credit level (pct)",
    "vm_pct": "Value vs momentum, 3 years (pct)",
    "rs_tf": "RS time frames in the top 20%", "res_alpha": "Resilience rank on SPY down days",
    "ind_rs": "Industry RS rank (group, 1-99)", "rs_vs_ind": "RS rating minus its group's",
    "ga_gpct": "Group strength percentile (Group leaders)", "ga_rr": "R:R at the signal (Group leaders)",
    "lead_conc": "Leadership concentration (entropy vs group sizes)", "lead_conc_pct": "Leadership concentration, 1-year percentile",
    "lead_eff_groups": "Effective number of leading groups", "ga_x_lead": "Group strength x leadership concentration",
    "gap_hi": "Open vs yesterday's high (alpha #20)", "gap_zone": "Gap zone vs yesterday's range (alpha #20)",
    "body101": "Intraday body / range (alpha #101)", "vwap_pos": "Close vs VWAP (alpha #42)",
    "aw_hi_pos": "Close vs the AVWAP from the 52-week high", "aw_lo_pos": "Close vs the AVWAP from the 63-day low",
    "aw_state": "AVWAP state (below both, between, above both)"}
RK_CATS: Dict[str, str] = {"setup": "Setup", "climate": "Climate regime", "spy_cycle": "SPY cycle", "state_txt": "MACD-V state",
                           "hmm_vol": "Volatility regime", "nar_tag": "Cross-asset narrative", "nar_quad": "Growth/inflation quadrant",
                           "curve_regime": "Curve regime", "nar_jump": "Jump-model regime", "style_tape": "Style tape (Ilmanen)",
                           "ilm_confirm": "Ilmanen signature vs chip", "bcond": "Brief market condition"}
RK_MARKET = ({"lead_conc", "lead_conc_pct", "lead_eff_groups", "breadth50", "spy_r20", "z_equity", "z_size", "z_growth", "z_credit", "z_rates", "z_vol", "z_mom", "turb_pct",
              "climate", "spy_cycle", "hmm_vol"} | set(NAR_LEDGER_NUM) | set(NAR_LEDGER_CAT) | set(ILM_LEDGER_NUM)
             | {"style_tape", "ilm_confirm", "bcond"})
# Market inputs are the same for every name on a date, and five years is only ~1,200 dates, so many of them let the trees
# memorize dates. The compact set keeps the coarse regime labels and four summary numbers.
RK_MARKET_COMPACT = {"climate", "spy_cycle", "nar_tag", "nar_quad", "curve_regime", "nar_jump", "roro_20", "sb_corr",
                     "breadth50", "z_vol", "bcond"}
RK_MARKET_MODES = {"compact": "Compact (regime labels + 4 numbers)", "full": "Full (every climate and narrative input)",
                   "none": "None (the name's screens only)"}
RK_CONSENSUS = {"rs_rating": 1, "alpha_pct": 1, "ext8w": 0, "lp_spread6": -1, "w_macdv": 1, "n_setups": 1}   # 0 = closer is better
RK_SKIP = {"base:uptrend", "macd:bullx_raw", "macd:zerox_raw", "vw:cross_raw"}
RK_VERDICT_COLOR = {"USE THE MODEL": C_GREEN, "USE THE CONSENSUS RANK": C_ACCENT, "NO RANKING HELPS": C_RED, "TOO LITTLE DATA": C_MUTED}
RK_DEFAULTS = {"rk_recent": 3, "rk_k": 5, "rk_only_list": True, "rk_folds": 5}
RK_T = 2.5                # t a ranking must clear, paired per date, and it must hold in both halves of the test period


def _rk_sklearn() -> bool:
    try:
        import importlib.util
        return importlib.util.find_spec("sklearn") is not None
    except Exception:
        return False


def rk_prepare(ev: pd.DataFrame) -> pd.DataFrame:
    d = ev[~ev["setup"].isin(RK_SKIP)].copy()
    for k in RK_FEATURES:
        if k not in d:
            d[k] = np.nan
    st_ = d["mv_state"] if "mv_state" in d else pd.Series(np.nan, index=d.index)
    d["state_txt"] = [MC_STATES[int(x)] if np.isfinite(x) and 0 <= x < len(MC_STATES) else "" for x in st_.to_numpy(float)]
    for k in RK_CATS:
        d[k] = d[k].astype(str).replace({"nan": "", "None": ""}) if k in d else ""
    d["y"] = (d["r"] > 0).astype(float).where(d["status"] == 0)
    d["cons_in"] = rk_consensus(d, by="date")             # where the name sits among that day's candidates
    return d


def rk_encode(d: pd.DataFrame, feats: List[str], vocab: Optional[Dict[str, List[str]]] = None,
              cats: Optional[List[str]] = None) -> Tuple[pd.DataFrame, Dict[str, List[str]]]:
    """Numeric inputs as float; categories as small integer codes (unknown = missing), which the trees split on directly.
    The categories used are the vocabulary's keys (or `cats`, or every RK_CATS column)."""
    X = d[feats].astype(float).copy()
    if vocab is None:
        vocab = {k: [v for v in d[k].value_counts().index if v != ""][:250] for k in (cats if cats is not None else RK_CATS)}
    for k in vocab:
        X[k] = d[k].map({v: i for i, v in enumerate(vocab[k])}).astype(float)
    return X, vocab


def rk_model(n_rows: int, n_num: int, n_cat: int = len(RK_CATS)):
    from sklearn.ensemble import HistGradientBoostingClassifier
    mask = np.array([False] * n_num + [True] * n_cat)
    return HistGradientBoostingClassifier(max_iter=200, learning_rate=0.05, max_leaf_nodes=15,
                                          min_samples_leaf=int(min(200, max(20, n_rows // 300))), l2_regularization=1.0,
                                          early_stopping=False, categorical_features=mask, random_state=7)


def rk_consensus(N: pd.DataFrame, by: Optional[str] = "date") -> np.ndarray:
    """Equal-weight average of each screen's percentile within the day's candidates (0-100)."""
    parts = []
    for k, sgn in RK_CONSENSUS.items():
        if k not in N or not N[k].notna().any():
            continue
        x = N[k].astype(float)
        x = -x.abs() if sgn == 0 else x * sgn
        parts.append((x.groupby(N[by]).rank(pct=True) if by else x.rank(pct=True)).to_numpy(float))
    if not parts:
        return np.full(len(N), np.nan)
    with np.errstate(all="ignore"):
        return np.nanmean(np.vstack(parts), axis=0) * 100


def _auc_within(E: pd.DataFrame, min_rows: int = 10) -> float:
    """AUC computed inside each signal date (who to pick among that day's candidates), averaged over dates.
    Market inputs are constant within a day, so they can only help here through interactions."""
    g = E[["date", "y", "score"]].dropna()
    rk = g.groupby("date")["score"].rank()
    t = pd.DataFrame({"date": g["date"], "y": g["y"], "rk": rk})
    agg = t.groupby("date").agg(n=("y", "size"), npos=("y", "sum"), rpos=("rk", lambda x: 0.0))
    agg["rpos"] = t[t["y"] == 1].groupby("date")["rk"].sum().reindex(agg.index).fillna(0.0)
    agg["nneg"] = agg["n"] - agg["npos"]
    agg = agg[(agg["n"] >= min_rows) & (agg["npos"] > 0) & (agg["nneg"] > 0)]
    if agg.empty:
        return np.nan
    auc = (agg["rpos"] - agg["npos"] * (agg["npos"] + 1) / 2) / (agg["npos"] * agg["nneg"])
    return float(auc.mean())


def _rk_names(E: pd.DataFrame, score_col: Optional[str]) -> pd.DataFrame:
    """One row per name per signal date: the average R of that name's setups, the best model score, the screens."""
    agg = {"r": ("r", "mean"), "y": ("y", "mean")}
    if score_col:
        agg["score"] = (score_col, "max")
    if "fold" in E:
        agg["fold"] = ("fold", "first")
    for k in RK_CONSENSUS:
        agg[k] = (k, "first")
    return E.groupby(["date", "ticker"], sort=False).agg(**agg).reset_index()


def _rk_topk(N: pd.DataFrame, col: str, K: int) -> pd.Series:
    t = N.sort_values(["date", col], ascending=[True, False], na_position="last").groupby("date", sort=False).head(K)
    return t.groupby("date")["r"].mean().sort_index()


def rk_train(ev: pd.DataFrame, horizon: int, K: int = 5, folds: int = 5, progress=None, market: str = "compact") -> Dict[str, Any]:
    """Walk-forward test, calibration and the final model. Returns everything the tab shows.
    market: "full" uses every Climate and Narratives input, "compact" only RK_MARKET_COMPACT, "none" no market input."""
    from sklearn.isotonic import IsotonicRegression
    from sklearn.metrics import roc_auc_score
    d = rk_prepare(ev)
    D = d[d["status"] == 0].reset_index(drop=True)
    keep = lambda k: k not in RK_MARKET or market == "full" or (market == "compact" and k in RK_MARKET_COMPACT)
    feats = [k for k in RK_FEATURES if D[k].notna().any() and keep(k)]
    cats = [k for k in RK_CATS if keep(k)]
    out: Dict[str, Any] = {"feats": feats, "cats": cats, "n_train": len(D), "dates": D["date"].nunique() if len(D) else 0,
                           "market": market}
    if len(D) < 2000 or out["dates"] < 150:
        out["verdict"] = "TOO LITTLE DATA"
        out["why"] = f"{len(D):,} trades on {out['dates']} dates; the ranker wants at least 2,000 trades over 150 dates."
        return out
    X, vocab = rk_encode(D, feats, cats=cats)
    y = D["y"].to_numpy()
    dates = np.sort(D["date"].unique())
    blocks = np.array_split(dates, folds)
    oos = np.full(len(D), np.nan)
    fold_of = np.full(len(D), -1)
    best = {}
    last = None
    for b in range(1, folds):
        if progress is not None:
            progress.progress(b / (folds + 1), text=f"Walk-forward block {b} of {folds - 1}")
        t0, t1 = blocks[b][0], blocks[b][-1]
        trn = (D["exit_date"] < t0).to_numpy()                 # purged: only trades closed before the block starts
        tst = ((D["date"] >= t0) & (D["date"] <= t1)).to_numpy()
        if trn.sum() < 1000 or tst.sum() < 100 or len(np.unique(y[trn])) < 2:
            continue
        m = rk_model(int(trn.sum()), len(feats), len(cats))
        m.fit(X[trn], y[trn])
        oos[tst] = m.predict_proba(X[tst])[:, 1]
        fold_of[tst] = b
        mr = D[trn].groupby("setup")["r"].agg(["mean", "size"])
        mr = mr[mr["size"] >= 50]
        best[b] = str(mr["mean"].idxmax()) if len(mr) else None
        last = (m, tst)
    ok = np.isfinite(oos)
    if ok.sum() < 500:
        out["verdict"] = "TOO LITTLE DATA"
        out["why"] = "Not enough out-of-sample trades to judge the model."
        return out
    E = D.loc[ok].assign(score=oos[ok], fold=fold_of[ok])
    out["auc"] = float(roc_auc_score(E["y"], E["score"])) if E["y"].nunique() > 1 else np.nan
    out["auc_day"] = _auc_within(E)
    iso_p = IsotonicRegression(out_of_bounds="clip", y_min=0, y_max=1).fit(E["score"], E["y"])
    iso_r = IsotonicRegression(out_of_bounds="clip").fit(E["score"], E["r"])
    E["p_cal"] = iso_p.predict(E["score"])
    N = _rk_names(E, "score")
    N["cons"] = rk_consensus(N)
    m_ser, c_ser = _rk_topk(N, "score", K), _rk_topk(N, "cons", K)
    a_ser = N.groupby("date")["r"].mean().sort_index()
    bsel = E[[best.get(f) == s for f, s in zip(E["fold"], E["setup"])]]
    b_ser = _rk_names(bsel, None).groupby("date")["r"].mean().sort_index() if len(bsel) else pd.Series(dtype=float)
    diff = (m_ser - c_ser).dropna()
    mu, se = lg_nw(diff.to_numpy(), horizon)
    t_mc = mu / se if se and np.isfinite(se) and se > 0 else np.nan
    common = m_ser.index.intersection(b_ser.index)
    mb, sb_ = lg_nw((m_ser.reindex(common) - b_ser.reindex(common)).to_numpy(), horizon) if len(common) > 10 else (np.nan, np.nan)
    stats = {}
    for name, s_ in (("model", m_ser), ("consensus", c_ser), ("best setup", b_ser), ("all candidates", a_ser)):
        mm, ss = lg_nw(s_.to_numpy(), horizon)
        stats[name] = {"er": mm, "t": mm / ss if ss and np.isfinite(ss) and ss > 0 else np.nan, "dates": len(s_)}
    # board strength: the day's top-K model score, and what the top K went on to earn on weak / middle / strong days
    board = N.sort_values(["date", "score"], ascending=[True, False]).groupby("date").head(K).groupby("date")["score"].mean()
    terc = pd.qcut(board.rank(method="first"), 3, labels=["weak", "middle", "strong"])
    board_tbl = m_ser.groupby(terc.reindex(m_ser.index)).agg(["mean", "size"]).rename(columns={"mean": "er", "size": "dates"})
    # calibration table: the map fitted on the earlier test blocks, read on the last one (which it never saw). With one
    # block only, the fit itself is shown and flagged.
    fl_ = np.sort(E["fold"].unique())
    calib_oos = len(fl_) >= 2 and (E["fold"] == fl_[-1]).sum() >= 200 and E.loc[E["fold"] != fl_[-1], "y"].nunique() > 1
    if calib_oos:
        tr_c, te_c = E[E["fold"] != fl_[-1]], E[E["fold"] == fl_[-1]].copy()
        te_c["p_c"] = IsotonicRegression(out_of_bounds="clip", y_min=0, y_max=1).fit(tr_c["score"], tr_c["y"]).predict(te_c["score"])
    else:
        te_c = E.assign(p_c=E["p_cal"])
    te_c["bin"] = pd.qcut(te_c["p_c"].rank(method="first"), 10, labels=False)
    calib = te_c.groupby("bin").agg(pred=("p_c", "mean"), actual=("y", "mean"), er=("r", "mean"), n=("y", "size")).reset_index()
    # importance on the last block, with the model that never saw it
    imp = pd.DataFrame(columns=["feature", "drop_auc"])
    if last is not None:
        try:
            from sklearn.inspection import permutation_importance
            m_, tst_ = last
            Xi, yi = X[tst_], y[tst_]
            if len(Xi) > 8000:
                pick = np.random.default_rng(0).choice(len(Xi), 8000, replace=False)
                Xi, yi = Xi.iloc[pick], yi[pick]
            pi = permutation_importance(m_, Xi, yi, scoring="roc_auc", n_repeats=2, random_state=0)
            names = [RK_FEATURES.get(c_, RK_CATS.get(c_, c_)) for c_ in Xi.columns]
            imp = pd.DataFrame({"feature": names, "drop_auc": pi.importances_mean,
                                "market": [c_ in RK_MARKET for c_ in Xi.columns]}).sort_values("drop_auc", ascending=False)
        except Exception:
            pass
    if progress is not None:
        progress.progress(folds / (folds + 1), text="Final model on every closed trade")
    final = rk_model(len(D), len(feats), len(cats))
    final.fit(X, y)
    base_vals = {c_: (float(np.nanmedian(X[c_])) if c_ not in RK_CATS else (X[c_].mode().iloc[0] if X[c_].notna().any() else np.nan))
                 for c_ in X.columns}
    # verdict: every comparison is paired by date with Newey-West errors; each needs t >= RK_T and both halves positive
    sm, sc, sa = stats["model"]["er"], stats["consensus"]["er"], stats["all candidates"]["er"]
    sbest = stats["best setup"]["er"]

    def _pt(a_, b_):
        x_ = (a_ - b_.reindex(a_.index)).dropna()
        m_, s_ = lg_nw(x_.to_numpy(), horizon)
        h_ = len(x_) // 2
        both = bool(h_ >= 20 and x_.iloc[:h_].mean() > 0 and x_.iloc[h_:].mean() > 0)
        return (m_ / s_ if s_ and np.isfinite(s_) and s_ > 0 else np.nan), both
    (t_mc, h_mc), (t_ma, h_ma), (t_ca, h_ca) = _pt(m_ser, c_ser), _pt(m_ser, a_ser), _pt(c_ser, a_ser)
    passes = lambda t_, h_: bool(np.isfinite(t_) and t_ >= RK_T and h_)
    beats_best = not np.isfinite(sbest) or sm > sbest
    if passes(t_mc, h_mc) and beats_best:
        verdict, why = "USE THE MODEL", (f"Out of sample, the model's top {K} a day beat the consensus rank by {mu:+.2f}R per "
                                         f"trade (t {t_mc:+.1f}, both halves of the test period agree) and the best single "
                                         f"setup ({sm:+.2f}R vs {sbest:+.2f}R).")
    elif passes(t_ca, h_ca):
        verdict, why = "USE THE CONSENSUS RANK", (f"The simple consensus's top {K} beat taking every candidate ({sc:+.2f}R vs "
                                                  f"{sa:+.2f}R, t {t_ca:+.1f}), and the model didn't add enough on top "
                                                  f"(difference {mu:+.2f}R, t {t_mc:+.1f}; it needs t >= {RK_T:g} with both "
                                                  "halves of the test period agreeing).")
    elif passes(t_ma, h_ma) and beats_best:
        verdict, why = "USE THE MODEL", (f"The consensus rank doesn't help here, but the model's top {K} beat taking every "
                                         f"candidate ({sm:+.2f}R vs {sa:+.2f}R, t {t_ma:+.1f}) and the best single setup.")
    else:
        verdict, why = "NO RANKING HELPS", (f"Neither the model ({sm:+.2f}R, t {t_ma:+.1f} vs everything) nor the consensus "
                                            f"({sc:+.2f}R, t {t_ca:+.1f}) reliably beat taking every candidate ({sa:+.2f}R) "
                                            "out of sample. The order of the screens carries no proven edge here; lean on the "
                                            "Setup ledger verdicts instead.")
    out.update({"verdict": verdict, "why": why, "t_mc": t_mc, "t_ma": t_ma, "t_ca": t_ca, "diff": mu, "t_mb": mb / sb_ if sb_ and np.isfinite(sb_) and sb_ > 0 else np.nan,
                "stats": stats, "series": pd.DataFrame({"Model top K": m_ser, "Consensus top K": c_ser, "Every candidate": a_ser}),
                "board": board, "board_tbl": board_tbl, "calib": calib, "calib_oos": bool(calib_oos), "imp": imp, "model": final, "iso_p": iso_p, "iso_r": iso_r,
                "vocab": vocab, "base_vals": base_vals, "K": K, "best": best, "oos_from": pd.Timestamp(E["date"].min())})
    return out


def rk_alive(C: pd.DataFrame, P: Optional[Dict[str, pd.DataFrame]], cap: float = 3.0) -> np.ndarray:
    """Which candidates are still worth a look: False where a session after the signal has already traded down to the
    setup's stop (the planned level: the signal close less plan_risk_atr ATRs, held to 0.5-cap ATR, as the ledger sizes
    it). A recent signal has no label yet, so its status alone can't say this. Unknown names or levels count as alive."""
    out = np.ones(len(C), bool)
    if P is None or not len(C) or not {"plan_risk_atr", "atr_pct", "date", "ticker"} <= set(C.columns):
        return out
    idx, cols = P["close"].index, P["close"].columns
    ri, cj = idx.get_indexer(pd.DatetimeIndex(C["date"])), cols.get_indexer(C["ticker"].to_numpy())
    Cl, Lo = P["close"].to_numpy(float), P["low"].to_numpy(float)
    pr, ap = C["plan_risk_atr"].to_numpy(float), C["atr_pct"].to_numpy(float)
    for k in range(len(C)):
        if ri[k] < 0 or cj[k] < 0 or ri[k] + 1 >= len(idx) or not (np.isfinite(pr[k]) and np.isfinite(ap[k])):
            continue
        stop = Cl[ri[k], cj[k]] * (1 - float(np.clip(pr[k], 0.5, cap)) * ap[k] / 100)
        lows = Lo[ri[k] + 1:, cj[k]]
        if np.isfinite(stop) and np.isfinite(lows).any() and np.nanmin(lows) <= stop:
            out[k] = False
    return out


def rk_today(ev: pd.DataFrame, R: Dict[str, Any], recent: int, only: Optional[set] = None, n_reasons: int = 60,
             P: Optional[Dict[str, pd.DataFrame]] = None) -> pd.DataFrame:
    """Score today's candidates (setups that fired in the last `recent` sessions and, when the price panel P is given,
    whose stop hasn't traded since), one row per name."""
    d = rk_prepare(ev)
    last_i = int(ev["i"].max())
    C = d[(d["status"] == 3) & (d["i"] >= last_i - int(recent))]
    if only:
        C = C[C["ticker"].isin(only)]
    C = C[rk_alive(C, P)]
    if C.empty:
        return pd.DataFrame()
    C = C.reset_index(drop=True)
    feats = R["feats"]
    X, _ = rk_encode(C, feats, R["vocab"])
    model = R["model"]
    raw = model.predict_proba(X)[:, 1]
    C["score"], C["p"], C["er"] = raw, R["iso_p"].predict(raw), R["iso_r"].predict(raw)
    C["age"] = last_i - C["i"]
    best = C.sort_values("score", ascending=False).drop_duplicates("ticker")
    setups = C.groupby("ticker")["setup"].apply(lambda s: ", ".join(LG_SETUPS[x][1] for x in dict.fromkeys(s)))
    T = best.set_index("ticker")
    T["setups"] = setups
    N = T.reset_index()
    N["cons"] = rk_consensus(N, by=None)
    N = N.sort_values("score", ascending=False).reset_index(drop=True)
    # reasons: reset one input at a time to its typical value and see how far the score moves
    top = N.head(n_reasons)
    Xt, _ = rk_encode(top, feats, R["vocab"])
    s0 = model.predict_proba(Xt)[:, 1]
    contrib = np.zeros((len(Xt), Xt.shape[1]))
    for j, col in enumerate(Xt.columns):
        X2 = Xt.copy()
        X2[col] = R["base_vals"][col]
        contrib[:, j] = s0 - model.predict_proba(X2)[:, 1]
    why = []
    for r_i in range(len(Xt)):
        order = np.argsort(-np.abs(contrib[r_i]))[:3]
        bits = []
        for j in order:
            col = Xt.columns[j]
            if abs(contrib[r_i, j]) < 0.005:
                continue
            v = top.iloc[r_i][col]
            vtxt = (str(v) if col in RK_CATS else "n/a" if not np.isfinite(_n(v, np.nan)) else
                    f"{float(v):.0f}" if col in ("rs_rating", "alpha_pct", "n_setups") else f"{float(v):+.1f}"
                    if col in ("ext8w", "ext50", "ext200", "rs63", "dist_hi252", "gap", "mv", "w_macdv", "spy_r20") else f"{float(v):.2f}")
            bits.append(f"{RK_FEATURES.get(col, RK_CATS.get(col, col))} {vtxt} ({contrib[r_i, j] * 100:+.0f})")
        why.append("; ".join(bits))
    N["why"] = why + [""] * (len(N) - len(why))
    return N


# ---- Trade ranker UI ----------------------------------------------------------------

RK_GUIDE = """
#### What the ranker does
Every setup in the Setup ledger is a candidate trade. The ranker learns, from thousands of past candidates and what
became of them, which combination of screen readings and market context made a candidate worth taking. Today it scores
every setup that fired in the last few sessions and returns one list: the chance the trade makes money after costs,
its expected R, and the three readings that moved its score most.

#### Why trust it (or not)
* **Tested forward only.** History is cut into blocks. Each block is scored by a model trained only on trades that had
  closed before the block began, so no outcome leaks into its own prediction.
* **The bar is a simple consensus.** Each screen (RS rating, alpha composite, distance to the 8-week EMA, LaunchPad
  spread, weekly MACD-V, setups firing together) is turned into a percentile among the day's candidates and averaged
  with equal weights. Simple averages are hard to beat out of sample. The model must beat it, paired day by day, with
  t >= 2.5 and in both halves of the test period, and must also beat the best single setup chosen on training data.
  The consensus has to clear the same bar against taking every candidate. If neither does, the tab tells you to sort
  by the consensus instead.
* **Calibrated.** Probabilities are mapped onto what actually happened out of sample, so 60% means about 60%.
* **Board strength.** The market inputs can't pick a name (they're the same for everyone that day), but they move every
  score up or down together. When the day's best scores are weak, the top names have historically earned less: take
  fewer or smaller trades.

#### Limits
Five years of daily bars is a small, overlapping sample with few regimes. Expect a few points of hit rate, not a
crystal ball. Retrain after each ledger rebuild. Train on the whole market when you can: your list's history is
survivorship-biased, and the model will learn that bias too.

Sources: Gu, Kelly & Xiu (2020), *Empirical Asset Pricing via Machine Learning*; Grinsztajn, Oyallon & Varoquaux
(2022), *Why do tree-based models still outperform deep learning on tabular data?*; López de Prado (2018), *Advances
in Financial Machine Learning* (meta-labeling, purged cross-validation); Poh, Lim, Zohren & Roberts (2021),
*Building Cross-Sectional Systematic Strategies by Learning to Rank*.
"""


def render_ranker(cfg, ab, bench_bars, clim, bars, uni) -> None:
    sec("Trade ranker: every screen in one list, trained on your setup ledger")
    if ab is None:
        warnbox("The ranker needs the price panel. Load a universe of at least 10 names.")
        return
    for k_, v_ in RK_DEFAULTS.items():
        st.session_state.setdefault(k_, v_)
    have_sk = _rk_sklearn()
    if not have_sk:
        warnbox("scikit-learn isn't installed, so only the consensus rank is available. Add scikit-learn to "
                "requirements.txt (Streamlit Cloud) or run: pip install scikit-learn")
    res = st.session_state.get("lg_res")
    runs = (res or {}).get("runs") or {}
    if not runs:
        note("The ranker learns from the Setup ledger. Build the ledger first (Stocks > Setup ledger), or build it here "
             "with the ledger tab's current settings.")
        if st.button("Build the ledger now", key="rk_build_lg"):
            fams, mset, prm, which, sig_now = lg_state_params()
            lg_build_store(cfg, ab, bench_bars, clim, bars, fams, mset, prm, which, sig_now)
            st.rerun()
        with st.expander("How the ranker works"):
            st.markdown(RK_GUIDE)
        return
    keys = [k for k in ("market", "list") if k in runs]
    c = st.columns([2, 1, 1, 1, 1])
    if len(keys) > 1:
        tk_ = c[0].radio("Train on", keys, horizontal=True, key="rk_train_on",
                         format_func={"market": "Whole market (recommended)", "list": "Your list"}.get)
    else:
        tk_ = keys[0]
        c[0].caption(f"Training on {'the whole market' if tk_ == 'market' else 'your list'} from the Setup ledger. Build the "
                     "ledger with 'Both' to train on the survivorship-free market.")
    recent = c[1].number_input("Candidates: fired within N sessions", 0, 10, step=1, key="rk_recent")
    K = int(c[2].number_input("Top K per day (test)", 1, 20, step=1, key="rk_k"))
    folds = int(c[3].number_input("Walk-forward blocks", 3, 8, step=1, key="rk_folds"))
    only = c[4].checkbox("Only my list", key="rk_only_list", disabled=tk_ != "market",
                         help="Training on the whole market can still rank only the names in your universe.")
    run = runs[tk_]
    ev = run["ev"]
    hz = int(run["prm"]["horizon"])
    st.session_state.setdefault("rk_market", "compact")
    mmode = st.radio("Market context in the model", list(RK_MARKET_MODES), key="rk_market", horizontal=True,
                     format_func=RK_MARKET_MODES.get,
                     help="Market inputs are the same for every name on a date. With only a few years of dates, the full set "
                          "lets the trees memorize days; the compact set keeps the regime labels and four summary numbers. "
                          "The market-context test below compares all three on your data.")
    rkey = ("rk", run["rid"], K, folds, mmode)
    go = st.button("Train the ranker", key="rk_go", disabled=not have_sk)
    st.caption("Trains one model per walk-forward block plus a final one: about 15-60 seconds for your list, longer for "
               "the whole market. The result is kept until the ledger is rebuilt.")
    if go and have_sk:
        prog = st.progress(0.0, text="Training")
        try:
            st.session_state["rk_res"] = {"key": rkey, "R": memo(rkey, lambda: rk_train(ev, hz, K, folds, prog, market=mmode),
                                                                 capacity=300)}
        finally:
            prog.empty()
    R_ = (st.session_state.get("rk_res") or {})
    R = R_.get("R") if R_.get("key") == rkey else None
    only_set = set(uni["ticker"]) if (tk_ == "market" and only) else None
    if R is None or "model" not in R:
        if R is not None:
            md(hero_html(R["verdict"], RK_VERDICT_COLOR[R["verdict"]], "Ranker", R["why"]))
        # consensus-only list, always available
        d = rk_prepare(ev)
        C = d[(d["status"] == 3) & (d["i"] >= int(ev["i"].max()) - int(recent))]
        if only_set:
            C = C[C["ticker"].isin(only_set)]
        C = C[rk_alive(C, ab["P"])]
        if len(C):
            N = C.drop_duplicates("ticker").copy()
            N["cons"] = rk_consensus(N, by=None)
            N["setups"] = N["ticker"].map(C.groupby("ticker")["setup"].apply(lambda s: ", ".join(LG_SETUPS[x][1] for x in dict.fromkeys(s))))
            note("Consensus rank of today's candidates (train the model to compare):")
            show_df(N.sort_values("cons", ascending=False)[["ticker", "cons", "setups", "rs_rating", "alpha_pct", "ext8w",
                                                            "lp_spread6", "w_macdv", "n_setups"]].round(1), height=420,
                    column_config={"cons": st.column_config.ProgressColumn("Consensus", min_value=0, max_value=100, format="%.0f")})
        with st.expander("How the ranker works"):
            st.markdown(RK_GUIDE)
        return
    md(hero_html(R["verdict"], RK_VERDICT_COLOR[R["verdict"]],
                 f"Trained on {R['n_train']:,} {'whole-market' if tk_ == 'market' else 'list'} trades; out-of-sample from "
                 f"{R['oos_from'].date()}", R["why"]))
    stt = R["stats"]
    T = rk_today(ev, R, int(recent), only_set, P=ab["P"])
    board_now = float(T.head(K)["score"].mean()) if len(T) else np.nan
    pct_now = float((R["board"] < board_now).mean()) if np.isfinite(board_now) else np.nan
    bt = R["board_tbl"]
    weak_er = float(bt.loc["weak", "er"]) if "weak" in bt.index else np.nan
    strong_er = float(bt.loc["strong", "er"]) if "strong" in bt.index else np.nan
    btxt = "n/a" if not np.isfinite(pct_now) else ("strong" if pct_now >= 2 / 3 else "weak" if pct_now < 1 / 3 else "middling")
    kpi_row([kpi_html("Within-day AUC (picking names)", f"{_n(R.get('auc_day'), np.nan):.3f}",
                      f"pooled {_n(R.get('auc'), np.nan):.3f}; 0.50 = coin flip, 0.53+ is useful in markets",
                      "good" if _n(R.get("auc_day"), 0) >= 0.53 else ""),
             kpi_html(f"Model top {K} a day", f"{stt['model']['er']:+.2f}R", f"t {stt['model']['t']:+.1f} per trade, after costs",
                      "good" if stt["model"]["er"] > stt["consensus"]["er"] else ""),
             kpi_html(f"Consensus top {K}", f"{stt['consensus']['er']:+.2f}R", f"model minus consensus {R['diff']:+.2f}R, t {R['t_mc']:+.1f}"),
             kpi_html("Best single setup", f"{stt['best setup']['er']:+.2f}R" if np.isfinite(stt["best setup"]["er"]) else "n/a",
                      "picked on each block's training data"),
             kpi_html("Every candidate", f"{stt['all candidates']['er']:+.2f}R", "take everything the screens flag"),
             kpi_html("Today's board", btxt.upper(), f"{pct_now:.0%} percentile of past days; top {K} earned {weak_er:+.2f}R on weak "
                      f"days, {strong_er:+.2f}R on strong" if np.isfinite(pct_now) else "no candidates today",
                      "good" if btxt == "strong" else "bad" if btxt == "weak" else "warn")])
    sec(f"Today's candidates ({len(T)} names, setups from the last {int(recent) + 1} sessions)")
    if T.empty:
        note("No setups fired in the window. Widen it, or wait for the next session.")
    else:
        sort_by = "cons" if R["verdict"] == "USE THE CONSENSUS RANK" else "score"
        T = T.sort_values(sort_by, ascending=False).reset_index(drop=True)
        T.insert(0, "rank", np.arange(1, len(T) + 1))
        view = T[["rank", "ticker", "p", "er", "cons", "why", "setups", "age", "rs_rating", "alpha_pct", "ext8w", "lp_spread6",
                  "w_macdv", "plan_risk_atr"]]
        P_ = st.column_config.NumberColumn
        show_df(view, height=min(640, 38 + 35 * len(view)), column_config={
            "p": st.column_config.ProgressColumn("P(win)", min_value=0.0, max_value=1.0, format="%.2f"),
            "er": P_("E[R]", format="%+.2f"), "cons": P_("Consensus", format="%.0f"), "age": P_("Days since signal", format="%d"),
            "rs_rating": P_("RS", format="%.0f"), "alpha_pct": P_("Alpha", format="%.0f"), "ext8w": P_("vs 8-wk EMA %", format="%+.1f"),
            "lp_spread6": P_("LP spread %", format="%.1f"), "w_macdv": P_("Wkly MACD-V", format="%+.0f"),
            "plan_risk_atr": P_("Stop (ATR)", format="%.1f"), "why": st.column_config.TextColumn("Why (points of P(win))", width="large")})
        note(("Sorted by the consensus rank, as the verdict says. " if sort_by == "cons" else "Sorted by the model. ")
             + "P(win) is the calibrated chance the ledger trade made money after costs; E[R] its expected R. "
             "'Why' lists the three readings that moved this name's score most, in points of probability.")
        st.download_button("Download today's ranking (CSV)", view.to_csv(index=False).encode(),
                           file_name=f"trade_ranker_{date.today().isoformat()}.csv", mime="text/csv", key="rk_dl")
        st.session_state["ranker_today"] = T.set_index("ticker")[["p", "er", "cons"]].to_dict("index")
    c1, c2 = st.columns(2)
    with c1:
        s_ = R["series"].dropna(how="all").fillna(0).cumsum().reset_index().rename(columns={"index": "date"})
        s_ = s_.rename(columns={s_.columns[0]: "date"})
        line_chart(s_, "date", ["Model top K", "Consensus top K", "Every candidate"], 260,
                   f"Out of sample: running sum of each day's average R (top {K})", colors=[C_GREEN, C_ACCENT, C_MUTED])
    with c2:
        cal = R["calib"]
        pts = alt.Chart(cal).mark_circle(size=70, color=C_ACCENT).encode(
            x=alt.X("pred:Q", title="predicted P(win)", scale=alt.Scale(domain=[0, 1])),
            y=alt.Y("actual:Q", title="actual share that made money", scale=alt.Scale(domain=[0, 1])),
            tooltip=[alt.Tooltip("pred:Q", format=".2f"), alt.Tooltip("actual:Q", format=".2f"), alt.Tooltip("er:Q", format="+.2f"), "n"])
        diag = alt.Chart(pd.DataFrame({"x": [0, 1], "y": [0, 1]})).mark_line(color=C_MUTED, strokeDash=[4, 3]).encode(x="x:Q", y="y:Q")
        show_chart(_alt(alt.layer(diag, pts).properties(
            title=("Calibration on the last test block, mapped from the earlier ones (on the dashed line = honest)"
                   if R.get("calib_oos") else "Calibration: the fit itself (one test block, so not a test)")), 260))
    imp = R["imp"]
    if len(imp):
        top = imp.head(15).copy()
        top["kind"] = np.where(top["market"], "market context", "the name's screens")
        ch = alt.Chart(top, title="What the model leans on: AUC lost when one input is scrambled (last test block)").mark_bar().encode(
            y=alt.Y("feature:N", sort=list(top["feature"]), title=None, axis=alt.Axis(labelLimit=260, labelOverlap=False)),
            x=alt.X("drop_auc:Q", title=None),
            color=alt.Color("kind:N", scale=alt.Scale(domain=["the name's screens", "market context"], range=[C_ACCENT, C_BLUE]),
                            legend=alt.Legend(orient="top", title=None)),
            tooltip=["feature", alt.Tooltip("drop_auc:Q", format=".4f")])
        show_chart(_alt(ch, alt.Step(20)))
    sec("Does market context help? (Climate + Narratives)")
    note("Trains the same model with no market input, with the compact set and with the full set, on the same "
         "walk-forward blocks, then compares their top picks day by day. Real information should improve the within-day "
         "AUC and the top picks out of sample; if only the pooled AUC moves, the inputs are judging days, not names.")
    akey = ("rk_abl", run["rid"], K, folds)
    if st.button("Run the market-context test", key="rk_ablate", disabled=not have_sk):
        prog = st.progress(0.0, text="Market-context test")
        try:
            modes = {}
            for m in RK_MARKET_MODES:
                modes[m] = R if m == mmode else memo(("rk", run["rid"], K, folds, m), lambda m=m: rk_train(ev, hz, K, folds, prog, market=m),
                                                     capacity=300)
            st.session_state["rk_abl"] = {"key": akey, "modes": modes}
        finally:
            prog.empty()
    A_ = st.session_state.get("rk_abl") or {}
    if A_.get("key") == akey and all("series" in r_ for r_ in A_["modes"].values()):
        base_ = A_["modes"]["none"]
        rows = []
        for m, r_ in A_["modes"].items():
            ab_ = rk_ablation(r_, base_, hz) if m != "none" else None
            rows.append({"market context": RK_MARKET_MODES[m], "inputs": len(r_["feats"]) + len(r_["cats"]),
                         "within-day AUC": _n(r_.get("auc_day"), np.nan), "pooled AUC": _n(r_.get("auc"), np.nan),
                         f"top {K} E[R]": r_["stats"]["model"]["er"], "vs none": ab_["diff"] if ab_ else np.nan,
                         "t vs none": ab_["t"] if ab_ else np.nan, "verdict": r_["verdict"]})
        P_ = st.column_config.NumberColumn
        show_df(pd.DataFrame(rows), column_config={"within-day AUC": P_(format="%.3f"), "pooled AUC": P_(format="%.3f"),
                                                   f"top {K} E[R]": P_(format="%+.3f"), "vs none": P_(format="%+.3f"),
                                                   "t vs none": P_(format="%+.1f")})
        pick = "compact" if mmode == "none" else mmode
        md(f"<div class='note' style='color:var(--text)'>{_esc(rk_ablation(A_['modes'][pick], base_, hz)['text'])}</div>")
    with st.expander("How the ranker works, and its limits"):
        st.markdown(RK_GUIDE)


def rk_ablation(R1: Dict[str, Any], R0: Dict[str, Any], horizon: int) -> Dict[str, Any]:
    """Model with market context vs without: top-K R per date, paired, Newey-West, both halves."""
    a, b = R1["series"]["Model top K"], R0["series"]["Model top K"]
    x = (a - b.reindex(a.index)).dropna()
    mu, se = lg_nw(x.to_numpy(), horizon)
    t = mu / se if se and np.isfinite(se) and se > 0 else np.nan
    h = len(x) // 2
    halves = bool(h >= 20 and x.iloc[:h].mean() > 0 and x.iloc[h:].mean() > 0)
    helps = bool(np.isfinite(t) and t >= RK_T and halves)
    er1, er0 = lg_nw(a.to_numpy(), horizon)[0], lg_nw(b.to_numpy(), horizon)[0]
    if helps:
        text = (f"Market context earns its place: with it the top picks made {mu:+.2f}R more per trade out of sample "
                f"(t {t:+.1f}, both halves agree). Keep the Climate and Narratives inputs on.")
    elif np.isfinite(t) and t <= -RK_T:
        text = (f"Market context hurts the picks out of sample ({mu:+.2f}R, t {t:+.1f}): the model is fitting noise in the "
                "date-level inputs. Use the regime layers for sizing and the board-strength gate, not for picking names.")
    else:
        text = (f"No provable difference ({mu:+.2f}R, t {t:+.1f}; it needs t >= {RK_T:g} with both halves agreeing). The market "
                "layers move every name's score together, so they matter for how much to trade today (board strength), "
                "not which name. Five years holds few regimes; re-run this as the history grows.")
    return {"diff": mu, "t": t, "halves": halves, "helps": helps, "er_with": er1, "er_without": er0, "text": text}


# ═══════════════════════════════════════════════════════════════════════════
#  GROUP LEADERS: group strength x asymmetric R:R in RS names, and burst odds
#  (was group_asym.py; inlined so the lab stays one file; names carry a ga_ prefix)
# ═══════════════════════════════════════════════════════════════════════════
# Neil's rule: "Seek out group strength and search for asymmetric risk-to-reward spots in RS names."
# Compute functions take the wide panels (one DataFrame per field, index = dates, columns = tickers,
# as built by panel_from_bars) and a ticker -> group map. No Streamlit in the compute functions;
# ga_render_group_asym() is the one UI entry point (wired up in render_group_leaders below).
#
# Three reads, each using only data through day t (no look-ahead):
#
# 1. Group strength (0-100 per industry or theme, groups of at least GA_MIN_GROUP members)
#      40%  group RS: the members' median IBD-style RS rating, ranked across groups
#      20%  momentum: the 20-session change in that rank (catches groups that are improving)
#      20%  breadth: share of members above their 50-day average
#      20%  depth: share of members with RS >= 80
#    Each piece is a percentile across groups that day. Leading = top GA_TOP_PCT of groups.
#
# 2. RS leader: RS rating >= GA_RS_MIN and above its own group's median RS.
#    RS rating = 0.4*C/C63 + 0.2*C/C126 + 0.2*C/C189 + 0.2*C/C252, ranked 1-99 across the universe.
#
# 3. Asymmetry, in ATR(14):
#      risk    distance from the close to the nearest support below it that is at least
#              GA_MIN_STOP_ATR away: 5-day low, 10-day low, 21 EMA, 50-day, each less a
#              GA_STOP_BUFFER_ATR buffer. Closer supports are skipped (noise).
#      reward  the name's own 75th-percentile 20-session run-up (MFE, in ATR) over the past
#              year, from completed windows only. Optional: cap at the 52-week high (overhead).
#      R:R     reward / risk. Asymmetric = R:R >= GA_RR_MIN, risk <= GA_MAX_RISK_ATR, and
#              not extended (close no more than GA_EXT_MAX ATR above the 21 EMA).
#      Buy-below: the highest price at which the same stop and target still give the minimum
#              R:R and the risk cap, so a name that is not asymmetric yet shows where it would be.
#
# Does it pay? ga_event_study() replays weekly signals: enter at the next open, stop at the
# logical stop (gaps fill at the open), exit at the close after h sessions. Cells: leading group
# or not x R:R bucket, by year, with a Newey-West t on the date-averaged R. The lab's Setup ledger
# (with its own exits) is the fuller test: ga_split_labels() supplies the two splits for it.
#
# Burst odds (gamma-Poisson) are further down: ga_burst_state, ga_burst_odds, ga_burst_calibration.
#
# Wiring in this file:
#   - Stocks > Group leaders:           render_group_leaders -> ga_render_group_asym(P, group_maps=..., state_fn=...)
#   - Shared state for other pages:     ga_lab_state (memo), reading the tab's settings via ga_params
#   - Brief > Setups ranking:           su_group_read -> ga_brief_points (points and card badges)
#   - Setup ledger splits / ranker:     ga_ledger_panels in lg_build; ga_rule / ga_group / ga_rr in lg_split_col
#   - Command KPI:                      st.session_state["ga_last"] set by the tab

# ─────────────────────────────────────────────────────────────────────────────
# Defaults (all exposed as controls in the UI)
# ─────────────────────────────────────────────────────────────────────────────
GA_MIN_GROUP = 3            # members with data needed for a group read
GA_TOP_PCT = 0.20           # leading = top 20% of groups by strength
GA_RS_MIN = 80              # RS leader threshold
GA_RR_MIN = 3.0             # asymmetric R:R
GA_MAX_RISK_ATR = 1.5       # widest stop that still counts as asymmetric
GA_EXT_MAX = 3.0            # ATR above the 21 EMA before a name is "extended"
GA_MIN_STOP_ATR = 0.5       # supports closer than this are skipped
GA_STOP_BUFFER_ATR = 0.1    # stop sits this far under the support level
GA_MFE_H = 20               # run-up window for the reward estimate (sessions)
GA_MFE_Q = 0.75             # reward = this quantile of the name's past run-ups
GA_MFE_LOOKBACK = 252
GA_MOM_N = 20               # group-rank momentum window
GA_MIN_PX = 5.0
GA_MIN_DV = 5e6             # 20-day median dollar volume
GA_WEIGHTS = {"rs": 0.40, "mom": 0.20, "breadth": 0.20, "depth": 0.20}
GA_STOP_KINDS = ["5-day low", "10-day low", "21 EMA", "50-day"]
GA_STATUS = ["Asymmetric now", "Wait for pullback", "Extended", "No clean stop"]
GA_RR_BUCKETS = ["R:R 3+", "R:R 2-3", "R:R < 2", "Extended", "No clean stop"]
GA_NAME_COLS = ["ticker", "group", "group_rank", "group_strength", "rs", "rs_vs_group", "close", "status", "stop",
                "stop_kind", "risk_atr", "risk_pct", "target", "reward_atr", "rr", "ext_atr", "buy_below",
                "to_buy_below", "atr_pct", "lead_group"]
GA_QUADS = ["Leading", "Weakening", "Improving", "Lagging"]
GA_QUAD_COLOR = {"Leading": "#5b8dee", "Weakening": "#c97d1e", "Improving": "#199e70", "Lagging": "#7a7060"}
GA_STATUS_COLOR = {"Asymmetric now": "#4caf7d", "Wait for pullback": "#f5a623", "Extended": "#e05c5c",
                   "No clean stop": "#7a7060"}


# ─────────────────────────────────────────────────────────────────────────────
# Building blocks
# ─────────────────────────────────────────────────────────────────────────────
def ga_rs_rating(close: pd.DataFrame) -> pd.DataFrame:
    """IBD-style RS rating, 1-99 across the universe each day (NaN until 252 sessions of history)."""
    c = close
    raw = 0.4 * c / c.shift(63) + 0.2 * c / c.shift(126) + 0.2 * c / c.shift(189) + 0.2 * c / c.shift(252)
    pct = raw.rank(axis=1, pct=True)
    return np.ceil(pct * 99).clip(1, 99).where(raw.notna())


def ga_atr(P: Dict[str, pd.DataFrame], n: int = 14) -> pd.DataFrame:
    h, l, c = P["high"], P["low"], P["close"]
    pc = c.shift(1)
    tr = np.maximum(h - l, np.maximum((h - pc).abs(), (l - pc).abs()))
    tr = tr.where(pc.notna(), h - l)
    return tr.rolling(n, min_periods=n).mean()


def ga_ema(df: pd.DataFrame, n: int) -> pd.DataFrame:
    return df.ewm(span=n, adjust=False, min_periods=n).mean()


def ga_clean_groups(groups: pd.Series, columns: Sequence[str]) -> pd.Series:
    """ticker -> group for the panel's columns; blanks and 'Unclassified' dropped."""
    g = pd.Series(groups).reindex(list(columns))
    g = g.astype("object").where(g.notna(), None)
    bad = {"", "nan", "none", "unclassified", "other"}
    return g[[isinstance(v, str) and v.strip().lower() not in bad for v in g.values]].astype(str)


def _ga_group_stat(df: pd.DataFrame, groups: pd.Series, how: str) -> pd.DataFrame:
    sub = df[groups.index]
    gb = sub.T.groupby(groups.values)
    out = gb.median() if how == "median" else (gb.mean() if how == "mean" else gb.count())
    return out.T


def _ga_to_names(gpanel: pd.DataFrame, groups: pd.Series, columns: Sequence[str]) -> pd.DataFrame:
    """Broadcast a dates x groups panel to dates x tickers (NaN for names without a group)."""
    cols = list(columns)
    gmap = groups.reindex(cols)
    out = pd.DataFrame(np.nan, index=gpanel.index, columns=cols)
    has = gmap.notna()
    if has.any():
        vals = gpanel.reindex(columns=gmap[has].values).to_numpy()
        out.loc[:, has[has].index] = vals
    return out


# ─────────────────────────────────────────────────────────────────────────────
# 1. Group strength
# ─────────────────────────────────────────────────────────────────────────────
def ga_group_strength(P: Dict[str, pd.DataFrame], groups: pd.Series, rs: Optional[pd.DataFrame] = None,
                   min_group: int = GA_MIN_GROUP, mom_n: int = GA_MOM_N, rs_min: float = GA_RS_MIN,
                   weights: Dict[str, float] = GA_WEIGHTS) -> Dict[str, pd.DataFrame]:
    """Dates x groups panels: med_rs, rank (pct across groups), mom (rank change), breadth, depth,
    count, score (0-100) and score_pct (pct across groups)."""
    close = P["close"]
    g = ga_clean_groups(groups, close.columns)
    if rs is None:
        rs = ga_rs_rating(close)
    rs = rs[g.index]
    count = _ga_group_stat(rs.notna().astype(float).where(rs.notna()), g, "count")
    ok = count >= min_group
    med_rs = _ga_group_stat(rs, g, "median").where(ok)
    sma50 = close[g.index].rolling(50, min_periods=50).mean()
    above = (close[g.index] > sma50).astype(float).where(sma50.notna() & rs.notna())
    breadth = _ga_group_stat(above, g, "mean").where(ok)
    depth = _ga_group_stat((rs >= rs_min).astype(float).where(rs.notna()), g, "mean").where(ok)
    rank = med_rs.rank(axis=1, pct=True)
    mom = rank - rank.shift(mom_n)

    def xs(df):
        return df.rank(axis=1, pct=True)

    parts = {"rs": xs(med_rs), "mom": xs(mom), "breadth": xs(breadth), "depth": xs(depth)}
    num = sum(weights[k] * parts[k].fillna(0) for k in parts)
    den = sum(weights[k] * parts[k].notna() for k in parts)
    score = (100 * num / den.where(den > 0)).where(ok & med_rs.notna())
    return {"med_rs": med_rs, "rank": rank, "mom": mom, "breadth": breadth, "depth": depth,
            "count": count.where(ok), "score": score, "score_pct": score.rank(axis=1, pct=True)}


def ga_quadrant(level: float, change: float) -> str:
    if not (np.isfinite(level) and np.isfinite(change)):
        return "—"
    if level >= 0.5:
        return "Leading" if change >= 0 else "Weakening"
    return "Improving" if change >= 0 else "Lagging"


# ─────────────────────────────────────────────────────────────────────────────
# 3. Asymmetry
# ─────────────────────────────────────────────────────────────────────────────
def ga_forward_mfe_atr(P: Dict[str, pd.DataFrame], a: pd.DataFrame, h: int = GA_MFE_H) -> pd.DataFrame:
    """Run-up over the next h sessions from the close, in ATR at t. Known only at t + h."""
    fut_hi = P["high"][::-1].rolling(h, min_periods=h).max()[::-1].shift(-1)
    return (fut_hi - P["close"]) / a


def ga_asymmetry(P: Dict[str, pd.DataFrame], a: Optional[pd.DataFrame] = None, *,
              min_stop_atr: float = GA_MIN_STOP_ATR, buffer_atr: float = GA_STOP_BUFFER_ATR,
              mfe_h: int = GA_MFE_H, mfe_q: float = GA_MFE_Q, lookback: int = GA_MFE_LOOKBACK,
              rr_min: float = GA_RR_MIN, max_risk: float = GA_MAX_RISK_ATR, ext_max: float = GA_EXT_MAX,
              cap_overhead: bool = False) -> Dict[str, pd.DataFrame]:
    """Dates x tickers panels: stop, stop_kind (index into GA_STOP_KINDS), risk_atr, reward_atr,
    target, rr, ext_atr, asym, buy_below, status code, rr_bucket code."""
    c, lo = P["close"], P["low"]
    a = ga_atr(P) if a is None else a
    e21 = ga_ema(c, 21)
    cands = [lo.rolling(5, min_periods=5).min(), lo.rolling(10, min_periods=10).min(), e21,
             c.rolling(50, min_periods=50).mean()]
    C, A = c.to_numpy(float), a.to_numpy(float)
    best = np.full(C.shape, np.inf)
    kind = np.full(C.shape, -1, dtype=int)
    with np.errstate(invalid="ignore", divide="ignore"):
        for k, lev in enumerate(cands):
            stop_k = lev.to_numpy(float) - buffer_atr * A
            d = (C - stop_k) / A
            ok = np.isfinite(d) & (d >= min_stop_atr) & (lev.to_numpy(float) < C)
            better = ok & (d < best)
            best = np.where(better, d, best)
            kind = np.where(better, k, kind)
    risk = np.where(np.isfinite(best), best, np.nan)
    stop = C - risk * A
    # reward: past completed run-ups only (the window that started h sessions ago ended today)
    mfe = ga_forward_mfe_atr(P, a, mfe_h).shift(mfe_h)
    reward = mfe.rolling(lookback, min_periods=60).quantile(mfe_q).to_numpy(float)
    if cap_overhead:
        hi = P["high"].rolling(252, min_periods=120).max().to_numpy(float)
        over = (hi - C) / A
        reward = np.where(np.isfinite(over) & (hi > C * 1.02), np.minimum(reward, over), reward)
    target = C + reward * A
    with np.errstate(invalid="ignore", divide="ignore"):
        rr = reward / risk
        ext = (C - e21.to_numpy(float)) / A
    asym = (rr >= rr_min) & (risk <= max_risk) & (ext <= ext_max)
    # buy-below: price p with (target - p) / (p - stop) >= rr_min and (p - stop) <= max_risk * ATR
    with np.errstate(invalid="ignore"):
        p_rr = (target + rr_min * stop) / (1 + rr_min)
        buy_below = np.minimum(p_rr, stop + max_risk * A)
        buy_below = np.where(buy_below > stop, buy_below, np.nan)
    status = np.where(~np.isfinite(risk), 3, np.where(ext > ext_max, 2, np.where(asym, 0, 1)))
    bucket = np.where(~np.isfinite(risk), 4, np.where(ext > ext_max, 3,
                      np.where(rr >= 3, 0, np.where(rr >= 2, 1, 2))))
    idx, cols = c.index, c.columns
    mk = lambda x: pd.DataFrame(x, index=idx, columns=cols)
    return {"stop": mk(stop), "stop_kind": mk(kind), "risk_atr": mk(risk), "reward_atr": mk(reward),
            "target": mk(target), "rr": mk(rr), "ext_atr": mk(ext), "asym": mk(asym),
            "buy_below": mk(buy_below), "status": mk(status), "rr_bucket": mk(bucket), "atr": a}


# ─────────────────────────────────────────────────────────────────────────────
# Everything at once
# ─────────────────────────────────────────────────────────────────────────────
def ga_state(P: Dict[str, pd.DataFrame], groups: pd.Series, *, min_group: int = GA_MIN_GROUP,
             rs_min: float = GA_RS_MIN, top_pct: float = GA_TOP_PCT, **asym_kw) -> Dict[str, Any]:
    """All panels in one dict. Name-level: rs, rs_vs_group, group_score, group_pct, lead_group,
    leader, liquid, plus the asymmetry panels. Group-level under 'G'."""
    close = P["close"]
    g = ga_clean_groups(groups, close.columns)
    rs = ga_rs_rating(close)
    G = ga_group_strength(P, g, rs, min_group=min_group, rs_min=rs_min)
    cols = close.columns
    grp_med = _ga_to_names(G["med_rs"], g, cols)
    grp_pct = _ga_to_names(G["score_pct"], g, cols)
    grp_score = _ga_to_names(G["score"], g, cols)
    AS = ga_asymmetry(P, **asym_kw)
    dv = (close * P["volume"]).rolling(20, min_periods=10).median() if "volume" in P else None
    liquid = (close >= GA_MIN_PX) & ((dv >= GA_MIN_DV) if dv is not None else True)
    lead_group = grp_pct > (1 - top_pct) + 1e-12   # strict: top 20% of 90 groups = 18, of 4 = 0.8 -> 1
    leader = (rs >= rs_min) & (rs > grp_med)
    return {"P": P, "groups": g, "rs": rs, "G": G, "rs_vs_group": rs - grp_med, "group_score": grp_score,
            "group_pct": grp_pct, "lead_group": lead_group, "leader": leader, "liquid": liquid,
            "top_pct": top_pct, "rs_min": rs_min, **AS}


def ga_group_table(state: Dict[str, Any], date: Optional[pd.Timestamp] = None) -> pd.DataFrame:
    """One row per group on a date: strength, parts, quadrant, leaders and asymmetric names."""
    G = state["G"]
    d = G["score"].index[-1] if date is None else date
    s = G["score"].loc[d].dropna()
    if s.empty:
        return pd.DataFrame()
    g = state["groups"]
    lead_names = state["leader"].loc[d] & state["liquid"].loc[d]
    asym = state["asym"].loc[d] & lead_names
    rows = []
    for grp in s.index:
        mem = g[g == grp].index
        rs_now = state["rs"].loc[d, mem]
        L = [t for t in mem if lead_names.get(t, False)]
        Aq = [t for t in mem if asym.get(t, False)]
        L = sorted(L, key=lambda t: -_ga_f(rs_now.get(t)))
        rows.append({"group": grp, "strength": s[grp], "strength_pct": G["score_pct"].at[d, grp],
                     "median_rs": G["med_rs"].at[d, grp], "rank_change": G["mom"].at[d, grp],
                     "breadth": G["breadth"].at[d, grp], "depth": G["depth"].at[d, grp],
                     "members": int(G["count"].at[d, grp]), "rs_leaders": len(L), "asymmetric": len(Aq),
                     "quadrant": ga_quadrant(G["rank"].at[d, grp], G["mom"].at[d, grp]),
                     "leaders": ", ".join(L[:8]), "asymmetric_names": ", ".join(Aq[:8])})
    t = pd.DataFrame(rows).sort_values("strength", ascending=False).reset_index(drop=True)
    t.insert(0, "rank", np.arange(1, len(t) + 1))
    t["leading"] = t["strength_pct"] > (1 - state["top_pct"]) + 1e-12
    return t


def _ga_f(x) -> float:
    try:
        v = float(x)
        return v if np.isfinite(v) else -1e9
    except Exception:
        return -1e9


def ga_name_table(state: Dict[str, Any], date: Optional[pd.Timestamp] = None, only_leading: bool = True) -> pd.DataFrame:
    """RS leaders (liquid) on a date with their group read and asymmetry. Status order:
    Asymmetric now, Wait for pullback, Extended, No clean stop."""
    d = state["rs"].index[-1] if date is None else date
    m = state["leader"].loc[d] & state["liquid"].loc[d]
    if only_leading:
        m &= state["lead_group"].loc[d]
    tick = m[m].index
    if len(tick) == 0:
        return pd.DataFrame(columns=GA_NAME_COLS)
    P = state["P"]
    gt = ga_group_table(state, d)
    grank = dict(zip(gt["group"], gt["rank"])) if len(gt) else {}
    c = P["close"].loc[d, tick]
    a = state["atr"].loc[d, tick]
    get = lambda k: state[k].loc[d, tick]
    st_code = get("status").astype(int)
    kind = get("stop_kind").astype(int)
    df = pd.DataFrame({
        "ticker": tick, "group": state["groups"].reindex(tick).values,
        "group_rank": [grank.get(x) for x in state["groups"].reindex(tick).values],
        "group_strength": get("group_score").values, "rs": get("rs").values,
        "rs_vs_group": get("rs_vs_group").values, "close": c.values,
        "status": [GA_STATUS[i] for i in st_code.values],
        "stop": get("stop").values, "stop_kind": [GA_STOP_KINDS[i] if i >= 0 else "—" for i in kind.values],
        "risk_atr": get("risk_atr").values, "risk_pct": (get("risk_atr") * a / c).values,
        "target": get("target").values, "reward_atr": get("reward_atr").values, "rr": get("rr").values,
        "ext_atr": get("ext_atr").values, "buy_below": get("buy_below").values,
        "to_buy_below": (get("buy_below") / c - 1).values, "atr_pct": (a / c).values,
        "lead_group": state["lead_group"].loc[d, tick].values,
    })
    order = {s: i for i, s in enumerate(GA_STATUS)}
    df["_o"] = df["status"].map(order)
    df = df.sort_values(["_o", "group_rank", "rr"], ascending=[True, True, False], na_position="last")
    return df.drop(columns="_o").reset_index(drop=True)


def ga_kpis(state: Dict[str, Any], date: Optional[pd.Timestamp] = None) -> Dict[str, Any]:
    d = state["rs"].index[-1] if date is None else date
    gt = ga_group_table(state, d)
    nt = ga_name_table(state, d, True)
    return {"date": d, "groups": len(gt), "leading_groups": int(gt["leading"].sum()) if len(gt) else 0,
            "leaders_in_leading": len(nt),
            "asymmetric": int((nt["status"] == "Asymmetric now").sum()) if len(nt) else 0,
            "extended": int((nt["status"] == "Extended").sum()) if len(nt) else 0,
            "top_groups": gt["group"].head(5).tolist() if len(gt) else []}


# ─────────────────────────────────────────────────────────────────────────────
# Does it pay? Weekly replay
# ─────────────────────────────────────────────────────────────────────────────
def ga_newey_west_t(x: Sequence[float], lags: int) -> float:
    x = np.asarray([v for v in x if np.isfinite(v)], float)
    n = len(x)
    if n < 5:
        return np.nan
    e = x - x.mean()
    lags = max(0, min(lags, n - 1))
    s = e @ e / n
    for L in range(1, lags + 1):
        s += 2 * (1 - L / (lags + 1)) * (e[L:] @ e[:-L]) / n
    return float(x.mean() / math.sqrt(max(s, 1e-18) / n))


def ga_event_study(state: Dict[str, Any], h: int = 20, step: int = 5, start: Optional[str] = None,
                   leaders_only: bool = True) -> pd.DataFrame:
    """One row per (signal date, RS leader): next-open entry, logical stop, exit at the stop (gap
    fills at the open) or at the close h sessions later. Columns: date, ticker, lead_group,
    group_pct, rr_bucket, rr, R, mfe_R, stopped, year."""
    P = state["P"]
    O, H, L, C = (P[k].to_numpy(float) for k in ("open", "high", "low", "close"))
    stop = state["stop"].to_numpy(float)
    ready = state["rs"].notna().sum(axis=1) > 0
    ready &= state["group_pct"].notna().sum(axis=1) > 0
    ready &= state["reward_atr"].notna().sum(axis=1) > 0
    dates = state["rs"].index
    first = int(np.argmax(ready.to_numpy())) if ready.any() else len(dates)
    if start is not None:
        first = max(first, int(dates.searchsorted(pd.Timestamp(start))))
    mask_all = (state["leader"] if leaders_only else state["rs"].notna()) & state["liquid"]
    out = []
    cols = state["rs"].columns.to_numpy()
    for i in range(first, len(dates) - h - 1, step):
        m = mask_all.iloc[i].to_numpy() & np.isfinite(stop[i])
        if not m.any():
            continue
        j = np.where(m)[0]
        entry, s = O[i + 1, j], stop[i, j]
        good = np.isfinite(entry) & (entry > s)
        j, entry, s = j[good], entry[good], s[good]
        if len(j) == 0:
            continue
        Lw, Ow, Hw = L[i + 1:i + h + 1, j], O[i + 1:i + h + 1, j], H[i + 1:i + h + 1, j]
        hit = Lw <= s
        anyhit = hit.any(axis=0)
        fh = np.argmax(hit, axis=0)
        ex_stop = np.minimum(Ow[fh, np.arange(len(j))], s)
        exit_ = np.where(anyhit, ex_stop, C[i + h, j])
        risk = entry - s
        # MFE only up to the stop-out day
        upto = np.where(anyhit, fh, h - 1)
        mfe = np.array([np.nanmax(Hw[:k + 1, n]) for n, k in enumerate(upto)])
        out.append(pd.DataFrame({
            "date": dates[i], "ticker": cols[j], "lead_group": state["lead_group"].iloc[i].to_numpy()[j],
            "group_pct": state["group_pct"].iloc[i].to_numpy()[j],
            "rr_bucket": [GA_RR_BUCKETS[int(b)] for b in state["rr_bucket"].iloc[i].to_numpy()[j]],
            "rr": state["rr"].iloc[i].to_numpy()[j], "R": (exit_ - entry) / risk,
            "mfe_R": (mfe - entry) / risk, "stopped": anyhit}))
    if not out:
        return pd.DataFrame(columns=["date", "ticker", "lead_group", "group_pct", "rr_bucket", "rr", "R",
                                     "mfe_R", "stopped", "year"])
    ev = pd.concat(out, ignore_index=True)
    ev["year"] = pd.to_datetime(ev["date"]).dt.year
    ev["group"] = np.where(ev["lead_group"], "Leading group", "Other groups")
    return ev


def ga_cells(ev: pd.DataFrame, by: Sequence[str] = ("group", "rr_bucket"), h: int = 20) -> pd.DataFrame:
    """Mean / median R, win rate, stop-out rate, mean MFE in R and a Newey-West t per cell."""
    if ev.empty:
        return pd.DataFrame()
    lags = max(0, h // 5 - 1)   # weekly signals with an h-session hold overlap h/5 - 1 neighbours
    rows = []
    for k, g in ev.groupby(list(by)):
        k = k if isinstance(k, tuple) else (k,)
        daily = g.groupby("date")["R"].mean()
        rows.append({**dict(zip(by, k)), "trades": len(g), "dates": daily.size, "mean_R": g["R"].mean(),
                     "median_R": g["R"].median(), "win": (g["R"] > 0).mean(), "stopped": g["stopped"].mean(),
                     "mean_mfe_R": g["mfe_R"].mean(), "nw_t": ga_newey_west_t(daily.to_numpy(), lags)})
    t = pd.DataFrame(rows)
    if "rr_bucket" in by:
        t["_o"] = t["rr_bucket"].map({b: i for i, b in enumerate(GA_RR_BUCKETS)})
        t = t.sort_values([c for c in by if c != "rr_bucket"] + ["_o"]).drop(columns="_o")
    return t.reset_index(drop=True)


def ga_edge_summary(ev: pd.DataFrame, h: int = 20) -> Dict[str, Any]:
    """The rule's cell (leading group AND R:R 3+) against every other RS-leader trade."""
    if ev.empty:
        return {}
    rule = ev["lead_group"] & (ev["rr_bucket"] == "R:R 3+")
    a, b = ev[rule], ev[~rule]
    diff = (a.groupby("date")["R"].mean() - b.groupby("date")["R"].mean()).dropna()
    return {"rule_trades": len(a), "rest_trades": len(b), "rule_mean_R": a["R"].mean() if len(a) else np.nan,
            "rest_mean_R": b["R"].mean() if len(b) else np.nan, "diff_dates": diff.size,
            "diff_mean": diff.mean() if diff.size else np.nan,
            "diff_t": ga_newey_west_t(diff.to_numpy(), max(0, h // 5 - 1))}


# ─────────────────────────────────────────────────────────────────────────────
# Leadership entropy: how concentrated the RS leaders are across groups
# ─────────────────────────────────────────────────────────────────────────────
# Each date, the RS leaders (RS rating at or above the tab's "RS at least") are counted by group and compared with how
# all names are spread across the same groups. Shannon entropy H of the leaders' group shares gives the effective
# number of leading groups, exp(H), with the Miller-Madow small-sample correction (+ (groups with leaders - 1) / 2N).
# Relative entropy (KL divergence) of the leaders' shares from the groups' size shares is the concentration: 0 when
# leaders are spread like the names, large when a few groups hold more than their size. Random allocation alone
# gives KL near (groups - 1) / 2N (2N KL is the G-statistic, about chi-square with groups - 1 degrees of freedom), so
# that is subtracted. Both are averaged over GA_ENT_SMOOTH sessions; the percentile is against the trailing year only.
GA_ENT_SMOOTH = 5
GA_ENT_PCT_WIN = 252
GA_ENT_MIN_LEADERS = 10
GA_ENT_NARROW, GA_ENT_BROAD = 2 / 3, 1 / 3
GA_ENT_REGIMES = ("Narrow leadership", "Middle", "Broad leadership")


def ga_leadership_entropy(state: Dict[str, Any], smooth: int = GA_ENT_SMOOTH, win: int = GA_ENT_PCT_WIN,
                          min_leaders: int = GA_ENT_MIN_LEADERS) -> Dict[str, Any]:
    """Dates-indexed series: leaders N, groups with leaders, effective leading groups (raw and smoothed), the same
    if leaders were spread like the names, bias-corrected concentration (raw and smoothed), its trailing-year
    percentile, and the share of leaders in the top three groups; plus dates x groups leader and name counts."""
    g = state["groups"]
    R = state["rs"][g.index]
    valid = R.notna()
    lead = (R >= float(state["rs_min"])) & valid
    n = lead.T.groupby(g.values).sum().T.astype(float)
    m = valid.T.groupby(g.values).sum().T.astype(float)
    N, M = n.sum(axis=1), m.sum(axis=1)
    ok = N >= min_leaders
    with np.errstate(divide="ignore", invalid="ignore"):
        p = n.div(N.where(ok), axis=0)
        q = m.div(M.where(M > 0), axis=0)
        H = -(p * np.log(p)).where(p > 0, 0.0).sum(axis=1)
        Hq = -(q * np.log(q)).where(q > 0, 0.0).sum(axis=1)
        kl = (p * np.log(p / q)).where(p > 0, 0.0).sum(axis=1)
    k_nz, g_act = (n > 0).sum(axis=1), (m > 0).sum(axis=1)
    H_mm = (H + (k_nz - 1) / (2 * N)).where(ok)
    conc = (kl - (g_act - 1) / (2 * N)).where(ok)
    eff = np.exp(H_mm)
    top3 = p.apply(lambda r: np.sort(r.dropna().to_numpy())[::-1][:3].sum() if r.notna().any() else np.nan, axis=1).where(ok)
    conc_s = conc.rolling(smooth, min_periods=1).mean().where(ok)
    eff_s = eff.rolling(smooth, min_periods=1).mean().where(ok)

    def _pct(x):
        if not np.isfinite(x[-1]):
            return np.nan
        f = x[np.isfinite(x)]
        return float(np.mean(f <= x[-1])) if len(f) else np.nan
    pct = conc_s.rolling(win, min_periods=min(60, win)).apply(_pct, raw=True)
    return {"N": N.where(ok), "groups_with": k_nz.where(ok), "groups": g_act, "eff": eff, "eff_s": eff_s,
            "eff_names": np.exp(Hq), "conc": conc, "conc_s": conc_s, "pct": pct, "top3": top3, "n": n, "m": m,
            "rs_min": float(state["rs_min"])}


def ga_entropy_cached(state: Dict[str, Any]) -> Dict[str, Any]:
    """ga_leadership_entropy memoized by the state's data, not its id (ids get reused once a state is dropped)."""
    rs = state["rs"]
    key = ("ga_ent", rs.shape, str(rs.index[-1]), float(state["rs_min"]),
           zlib.crc32(repr(sorted(state["groups"].items())).encode()), float(np.nansum(rs.iloc[-1].to_numpy())))
    return memo(key, lambda: ga_leadership_entropy(state), capacity=300)


def ga_entropy_regime(pct: pd.Series) -> pd.Series:
    v = pd.Series(pct, dtype=float)
    return pd.Series(np.select([v >= GA_ENT_NARROW, v <= GA_ENT_BROAD, v.notna()],
                               [GA_ENT_REGIMES[0], GA_ENT_REGIMES[2], GA_ENT_REGIMES[1]], "n/a"), index=v.index)


def ga_entropy_table(ent: Dict[str, Any], date: Optional[pd.Timestamp] = None) -> pd.DataFrame:
    """One row per group on a date (default: the last with enough leaders): leaders, names, their shares, how
    over-represented the group is among leaders (share of leaders / share of names) and its part of the concentration."""
    N = ent["N"].dropna()
    if N.empty:
        return pd.DataFrame()
    d = N.index[-1] if date is None else N.index[N.index.get_indexer([pd.Timestamp(date)], method="pad")[0]]
    nl, nm = ent["n"].loc[d], ent["m"].loc[d]
    p, q = nl / nl.sum(), nm / nm.sum()
    with np.errstate(divide="ignore", invalid="ignore"):
        contrib = np.where(p > 0, p * np.log(p / q), 0.0)
    T = pd.DataFrame({"group": nl.index, "leaders": nl.to_numpy(int), "names": nm.to_numpy(int), "share_leaders": p.to_numpy(),
                      "share_names": q.to_numpy(), "over": (p / q).to_numpy(), "contrib": contrib})
    T = T[T["names"] > 0].sort_values(["leaders", "over"], ascending=False).reset_index(drop=True)
    T.attrs["date"] = d
    return T


def ga_entropy_edge(ev: pd.DataFrame, ent: Dict[str, Any], h: int = 20) -> Tuple[pd.DataFrame, Dict[str, float]]:
    """The rule (leading group and R:R 3+) minus every other RS leader, per weekly date, split by the leadership
    regime on that date, with Newey-West t's, and narrow minus broad with its own t."""
    if ev is None or ev.empty:
        return pd.DataFrame(), {}
    dts = pd.DatetimeIndex(pd.to_datetime(ev["date"]).unique())
    reg = ga_entropy_regime(ent["pct"].reindex(dts))
    rule = ev["lead_group"].astype(bool) & (ev["rr_bucket"] == "R:R 3+")
    daily = pd.DataFrame({"rule": ev[rule].groupby("date")["R"].mean(), "rest": ev[~rule].groupby("date")["R"].mean()})
    daily.index = pd.DatetimeIndex(daily.index)
    daily["diff"] = daily["rule"] - daily["rest"]
    daily["regime"] = reg.reindex(daily.index).fillna("n/a").to_numpy()
    ev_reg = pd.Series(pd.to_datetime(ev["date"])).map(reg).fillna("n/a").to_numpy()
    lags = max(0, h // 5 - 1)
    rows, ser = [], {}
    for r_ in GA_ENT_REGIMES:
        d = daily[daily["regime"] == r_]
        x = d["diff"].dropna().to_numpy()
        mu, se = lg_nw(x, lags) if len(x) >= 3 else (np.nan, np.nan)
        ser[r_] = (mu, se)
        rows.append({"regime": r_, "dates": int(len(d)), "rule_trades": int((rule.to_numpy() & (ev_reg == r_)).sum()),
                     "rule_R": float(d["rule"].mean()) if len(d) else np.nan, "rest_R": float(d["rest"].mean()) if len(d) else np.nan,
                     "diff": mu, "t": mu / se if np.isfinite(se) and se > 0 else np.nan})
    (mn, sn), (mb, sb) = ser[GA_ENT_REGIMES[0]], ser[GA_ENT_REGIMES[2]]
    gap = mn - mb if np.isfinite(mn) and np.isfinite(mb) else np.nan
    se_g = math.sqrt(sn ** 2 + sb ** 2) if np.isfinite(sn) and np.isfinite(sb) else np.nan
    return pd.DataFrame(rows), {"gap": gap, "gap_t": gap / se_g if np.isfinite(se_g) and se_g > 0 else np.nan}


# ─────────────────────────────────────────────────────────────────────────────
# Burst odds: P(target before stop by a date), from a gamma-Poisson burst model
# ─────────────────────────────────────────────────────────────────────────────
# A burst is a day whose close-to-close move is at least GA_BURST_K ATRs (prior day's ATR), up or down.
# Bursts arrive as a Poisson process with rate lambda; lambda has a gamma prior centred on the name's group
# (GA_PRIOR_SESS sessions of the group's rate), so a thin record is shrunk toward its group and the burst count
# over the next t sessions is negative binomial (the gamma-Poisson predictive). Each burst is up with probability
# p (beta prior from the group, GA_PRIOR_BURSTS bursts of weight) and moves the average up / down burst size.
# The walk from today's close is absorbed at the target (reward) or the stop (risk), on a 0.25 ATR grid.
# Time to the target follows: the k-th burst arrives after a Gamma(k, lambda) wait, mixed over lambda.
# Moves between bursts are ignored, which is the model's main simplification (calibration checks it).
GA_BURST_K = 1.0
GA_BURST_W = 126
GA_PRIOR_SESS = 63.0
GA_PRIOR_BURSTS = 10.0
GA_SIZE_PRIOR = 5.0
GA_GRID_ATR = 0.25
GA_PGRID = 9
GA_TMAX = 120
GA_TOUCH = 0.5826           # Broadie-Glasserman-Kou: a daily-close model sees an intraday touch this many daily s.d.s early


def ga_burst_state(P: Dict[str, pd.DataFrame], a: pd.DataFrame, groups: pd.Series, k: float = GA_BURST_K,
                w: int = GA_BURST_W) -> Dict[str, Any]:
    """Name x date panels of trailing burst counts and sizes, with group (else universe) averages as priors.
    Everything at t uses moves through t only."""
    c = P["close"]
    d = c.diff() / a.shift(1)                       # move in ATRs of the day before
    valid = d.notna()
    up, dn = (d >= k) & valid, (d <= -k) & valid
    mp = max(20, w // 2)
    nobs = valid.astype(float).rolling(w, min_periods=mp).sum()
    nu = up.astype(float).rolling(w, min_periods=mp).sum().where(nobs.notna())
    nd = dn.astype(float).rolling(w, min_periods=mp).sum().where(nobs.notna())
    su = d.where(up).rolling(w, min_periods=1).sum().fillna(0.0).where(nobs.notna())
    sd = (-d).where(dn).rolling(w, min_periods=1).sum().fillna(0.0).where(nobs.notna())
    sig = d.rolling(63, min_periods=30).std()
    with np.errstate(invalid="ignore", divide="ignore"):
        rate = (nu + nd) / nobs
        pup = nu / (nu + nd)
        mu = su / nu
        md = sd / nd
    g = ga_clean_groups(groups, c.columns)
    cols = c.columns

    def prior(x: pd.DataFrame) -> pd.DataFrame:
        gx = _ga_to_names(_ga_group_stat(x, g, "mean"), g, cols) if len(g) else pd.DataFrame(np.nan, index=x.index, columns=cols)
        uni = x.mean(axis=1).to_numpy()[:, None]
        return pd.DataFrame(np.where(np.isfinite(gx.to_numpy(float)), gx.to_numpy(float), uni), index=x.index, columns=cols)

    return {"k": k, "w": w, "d": d, "nobs": nobs, "nu": nu, "nd": nd, "su": su, "sd": sd, "sig": sig,
            "g_rate": prior(rate), "g_pup": prior(pup), "g_mu": prior(mu.where(np.isfinite(mu))),
            "g_md": prior(md.where(np.isfinite(md)))}


def ga_burst_params(B: Dict[str, Any], i: int, j: int) -> Optional[Dict[str, float]]:
    """Posterior for one name on one date (row i, column j): gamma(alpha, beta) on the burst rate per session,
    beta(ap, bp) on the up share, shrunk mean burst sizes in ATR, and the daily move s.d. in ATR."""
    g = lambda key: float(B[key].iat[i, j])
    nobs, nu, nd = g("nobs"), g("nu"), g("nd")
    if not np.isfinite(nobs) or nobs <= 0:
        return None
    gr, gp, gmu, gmd = g("g_rate"), g("g_pup"), g("g_mu"), g("g_md")
    if not all(np.isfinite(v) for v in (gr, gp, gmu, gmd)) or gr <= 0:
        return None
    gp = min(max(gp, 0.02), 0.98)
    alpha = GA_PRIOR_SESS * gr + nu + nd
    beta = GA_PRIOR_SESS + nobs
    ap, bp = GA_PRIOR_BURSTS * gp + nu, GA_PRIOR_BURSTS * (1 - gp) + nd
    s_up = (g("su") + GA_SIZE_PRIOR * gmu) / (nu + GA_SIZE_PRIOR)
    s_dn = (g("sd") + GA_SIZE_PRIOR * gmd) / (nd + GA_SIZE_PRIOR)
    return {"alpha": alpha, "beta": beta, "ap": ap, "bp": bp, "s_up": max(s_up, B["k"]), "s_dn": max(s_dn, B["k"]),
            "sig": g("sig"), "nu": nu, "nd": nd, "nobs": nobs, "rate": alpha / beta, "p_up": ap / (ap + bp)}


def _ga_beta_grid(ap: float, bp: float, n: int = GA_PGRID) -> np.ndarray:
    q = (np.arange(n) + 0.5) / n
    try:
        from scipy.stats import beta as _b
        return np.clip(_b.ppf(q, ap, bp), 1e-4, 1 - 1e-4)
    except Exception:                                # normal approximation
        m = ap / (ap + bp)
        s = math.sqrt(m * (1 - m) / (ap + bp + 1))
        z = np.array([_ga_norm_ppf(x) for x in q])
        return np.clip(m + s * z, 1e-4, 1 - 1e-4)


def _ga_norm_ppf(p: float) -> float:
    # Acklam's rational approximation
    a = [-39.6968302866538, 220.946098424521, -275.928510446969, 138.357751867269, -30.6647980661472, 2.50662827745924]
    b = [-54.4760987982241, 161.585836858041, -155.698979859887, 66.8013118877197, -13.2806815528857]
    c = [-0.00778489400243029, -0.322396458041136, -2.40075827716184, -2.54973253934373, 4.37466414146497, 2.93816398269878]
    d = [0.00778469570904146, 0.32246712907004, 2.445134137143, 3.75440866190742]
    if p < 0.02425:
        q = math.sqrt(-2 * math.log(p))
        return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1)
    if p > 1 - 0.02425:
        return -_ga_norm_ppf(1 - p)
    q = p - 0.5
    r = q * q
    return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / \
           (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1)


def ga_burst_walk(p_grid: np.ndarray, up_step: int, dn_step: int, U: int, L: int, kmax: int):
    """Two-barrier walk on a grid: start at 0, each burst +up_step with prob p, else -dn_step; absorbed at >= U
    (target) or <= -L (stop). Returns, averaged over p_grid, the mass absorbed at the target and at the stop on
    burst n (n = 0..kmax) and the surviving mass's summed position after n bursts."""
    G, S = len(p_grid), U + L - 1
    dist = np.zeros((G, S))
    dist[:, L - 1] = 1.0
    pos = np.arange(S) - (L - 1)
    pg = p_grid[:, None]
    hu, hd, mark = np.zeros((G, kmax + 1)), np.zeros((G, kmax + 1)), np.zeros((G, kmax + 1))
    idx = np.arange(S)
    ui, di = idx + up_step, idx - dn_step
    ku, kd = ui < S, di >= 0
    for n in range(1, kmax + 1):
        new = np.zeros_like(dist)
        new[:, ui[ku]] += pg * dist[:, ku]
        new[:, di[kd]] += (1 - pg) * dist[:, kd]
        hu[:, n] = (pg * dist[:, ~ku]).sum(axis=1)
        hd[:, n] = ((1 - pg) * dist[:, ~kd]).sum(axis=1)
        dist = new
        mark[:, n] = (dist * pos).sum(axis=1)
    return hu.mean(axis=0), hd.mean(axis=0), mark.mean(axis=0)


def _ga_lgamma(x):
    try:
        from scipy.special import gammaln
        return gammaln(x)
    except Exception:
        return np.vectorize(math.lgamma)(x)


def ga_nb_pmf_matrix(alpha: float, beta: float, t: np.ndarray, kmax: int) -> np.ndarray:
    """Gamma-Poisson predictive: P(N_t = k) for each horizon t (rows) and k = 0..kmax (columns),
    N_t ~ NegBin(r = alpha, q = beta / (beta + t))."""
    t = np.asarray(t, float)[:, None]
    k = np.arange(kmax + 1, dtype=float)[None, :]
    q = beta / (beta + t)
    lp = _ga_lgamma(k + alpha) - _ga_lgamma(alpha) - _ga_lgamma(k + 1) + alpha * np.log(q) + k * np.log1p(-q)
    return np.exp(lp)


def ga_touch_shift(sig_atr: float, on: bool = True) -> float:
    """Barrier shift (in ATR) that turns a daily-close model into an intraday-touch one (BGK continuity correction)."""
    return GA_TOUCH * sig_atr if (on and np.isfinite(sig_atr) and sig_atr > 0) else 0.0


def ga_burst_odds(prm: Dict[str, float], risk_atr: float, reward_atr: float, t: Sequence[int],
               grid: float = GA_GRID_ATR, touch: float = 0.0) -> Dict[str, np.ndarray]:
    """For each horizon in t (sessions): P(target first by t), P(stop first by t), and the model's E[R] by t
    (target = reward/risk R, stop = -1R, still open = its expected position in R). touch (ATR) moves both barriers
    toward the start so an intraday touch counts (see touch_shift); the payoffs keep the true distances."""
    t = np.asarray(list(t), float)
    U = max(1, int(math.ceil(max(reward_atr - touch, grid) / grid - 1e-9)))
    L = max(1, int(math.ceil(max(risk_atr - touch, grid) / grid - 1e-9)))
    us = max(1, int(round(prm["s_up"] / grid)))
    ds = max(1, int(round(prm["s_dn"] / grid)))
    lam = prm["alpha"] / prm["beta"]
    tm = float(t.max())
    mean = lam * tm
    var = mean * (1 + tm / prm["beta"])
    kmax = int(min(600, math.ceil(mean + 7 * math.sqrt(max(var, 1e-9)) + 8)))
    hu, hd, mark = ga_burst_walk(_ga_beta_grid(prm["ap"], prm["bp"]), us, ds, U, L, kmax)
    pm = ga_nb_pmf_matrix(prm["alpha"], prm["beta"], t, kmax)          # T x (kmax + 1)
    surv = 1.0 - np.cumsum(pm, axis=1) + pm                         # P(N_t >= k)
    p_t = surv @ hu
    p_s = surv @ hd
    rew_r = reward_atr / risk_atr
    open_r = pm @ (mark * grid / risk_atr)
    return {"t": t, "p_target": np.clip(p_t, 0, 1), "p_stop": np.clip(p_s, 0, 1),
            "e_r": p_t * rew_r - p_s + open_r, "U": U, "L": L, "up_step": us, "dn_step": ds}


def ga_burst_timing(odds: Dict[str, np.ndarray]) -> Dict[str, float]:
    """Sessions to the target among the paths that reach it within the horizon: median and middle half."""
    p, t = odds["p_target"], odds["t"]
    if len(p) == 0 or p[-1] <= 1e-6:
        return {"median": np.nan, "q25": np.nan, "q75": np.nan, "p_max": float(p[-1]) if len(p) else np.nan}
    f = p / p[-1]
    q = lambda x: float(t[np.argmax(f >= x)])
    return {"median": q(0.5), "q25": q(0.25), "q75": q(0.75), "p_max": float(p[-1])}


def ga_gauss_odds(sig_atr: float, risk_atr: float, reward_atr: float, h: int, grid: float = GA_GRID_ATR,
               touch: float = 0.0) -> Tuple[float, float]:
    """Comparison model: driftless Gaussian daily closes with the name's daily s.d. in ATRs, same two barriers
    (and the same touch shift). Returns P(target first within h), P(stop first within h)."""
    if not (np.isfinite(sig_atr) and sig_atr > 0):
        return np.nan, np.nan
    U = max(1, int(math.ceil(max(reward_atr - touch, grid) / grid - 1e-9)))
    L = max(1, int(math.ceil(max(risk_atr - touch, grid) / grid - 1e-9)))
    S = U + L - 1
    s = sig_atr / grid
    m = max(1, int(math.ceil(4 * s)))
    o = np.arange(-m, m + 1)
    kern = np.exp(-0.5 * (o / s) ** 2)
    kern /= kern.sum()
    dist = np.zeros(S)
    dist[L - 1] = 1.0
    pu = pd_ = 0.0
    for _ in range(int(h)):
        full = np.convolve(dist, kern)               # index f = i + (o + m)
        pd_ += full[:m].sum()
        pu += full[S + m:].sum()
        dist = full[m:S + m]
    return float(pu), float(pd_)


def ga_barrier_outcome(P: Dict[str, pd.DataFrame], i: int, j: np.ndarray, stop: np.ndarray, target: np.ndarray,
                    h: int) -> Tuple[np.ndarray, np.ndarray]:
    """What happened from the close of row i: target first (high >= target) or stop first (low <= stop) within h
    sessions. Both on the same day counts as the stop (we can't tell the order inside a daily bar)."""
    Hh = P["high"].to_numpy(float)[i + 1:i + h + 1][:, j]
    Ll = P["low"].to_numpy(float)[i + 1:i + h + 1][:, j]
    ht, hs = Hh >= target, Ll <= stop
    big = Hh.shape[0] + 1
    ft = np.where(ht.any(axis=0), np.argmax(ht, axis=0), big)
    fs = np.where(hs.any(axis=0), np.argmax(hs, axis=0), big)
    tgt = (ft < big) & (ft < fs)
    stp = (fs < big) & (fs <= ft)
    return tgt, stp


def ga_burst_table(state: Dict[str, Any], B: Dict[str, Any], tickers: Sequence[str], h: int = GA_MFE_H,
                   touch_on: bool = True) -> pd.DataFrame:
    """Burst odds for named tickers on the last date: P(target first), P(stop first), E[R], median sessions."""
    i = len(state["rs"].index) - 1
    cols = state["rs"].columns
    rows = []
    for t in tickers:
        if t not in cols:
            continue
        j = cols.get_loc(t)
        risk, rew = state["risk_atr"].iat[i, j], state["reward_atr"].iat[i, j]
        prm = ga_burst_params(B, i, j)
        if prm is None or not (np.isfinite(risk) and np.isfinite(rew)) or risk <= 0 or rew <= 0:
            rows.append({"ticker": t})
            continue
        o = ga_burst_odds(prm, risk, rew, np.arange(1, max(h, GA_TMAX) + 1), touch=ga_touch_shift(prm["sig"], touch_on))
        tm = ga_burst_timing(o)
        rows.append({"ticker": t, "p_target": float(o["p_target"][h - 1]), "p_stop": float(o["p_stop"][h - 1]),
                     "burst_er": float(o["e_r"][h - 1]), "days_median": tm["median"],
                     "bursts_per_month": prm["rate"] * 21, "up_share": prm["p_up"]})
    return pd.DataFrame(rows)


def ga_burst_calibration(state: Dict[str, Any], B: Dict[str, Any], h: int = GA_MFE_H, start: Optional[str] = None,
                         step: int = 5, max_n: int = 3000, seed: int = 7) -> pd.DataFrame:
    """Weekly RS-leader signals: the burst model's and the Gaussian model's P(target before stop within h) from the
    close, against what happened (high / low path). One row per (date, name)."""
    P = state["P"]
    idx = state["rs"].index
    ok = state["leader"] & state["liquid"] & state["stop"].notna() & state["target"].notna()
    ok &= state["risk_atr"] > 0
    first = int(np.argmax(state["reward_atr"].notna().any(axis=1).to_numpy())) if state["reward_atr"].notna().any().any() else len(idx)
    first = max(first, int(B["nobs"].notna().any(axis=1).to_numpy().argmax()))
    if start is not None:
        first = max(first, int(idx.searchsorted(pd.Timestamp(start))))
    pairs = []
    for i in range(first, len(idx) - h - 1, step):
        js = np.where(ok.iloc[i].to_numpy())[0]
        pairs += [(i, j) for j in js]
    if not pairs:
        return pd.DataFrame()
    rng = np.random.default_rng(seed)
    if len(pairs) > max_n:
        pairs = [pairs[k] for k in sorted(rng.choice(len(pairs), max_n, replace=False))]
    out = []
    by_i: Dict[int, List[int]] = {}
    for i, j in pairs:
        by_i.setdefault(i, []).append(j)
    cols = state["rs"].columns
    Cn, An = P["close"].to_numpy(float), state["atr"].to_numpy(float)
    for i, js in by_i.items():
        js = np.array(js)
        tgt, stp = ga_barrier_outcome(P, i, js, state["stop"].iloc[i].to_numpy(float)[js],
                                   state["target"].iloc[i].to_numpy(float)[js], h)
        for n, j in enumerate(js):
            mark_r = (Cn[i + h, j] - Cn[i, j]) / (state["risk_atr"].iat[i, j] * An[i, j])
            risk, rew = state["risk_atr"].iat[i, j], state["reward_atr"].iat[i, j]
            prm = ga_burst_params(B, i, j)
            if prm is None:
                continue
            tch = ga_touch_shift(prm["sig"])
            o = ga_burst_odds(prm, risk, rew, [h], touch=tch)
            o0 = ga_burst_odds(prm, risk, rew, [h])
            pg, sg = ga_gauss_odds(prm["sig"], risk, rew, h, touch=tch)
            out.append({"date": idx[i], "ticker": cols[j], "risk_atr": risk, "reward_atr": rew,
                        "p_burst": float(o["p_target"][0]), "p_burst_stop": float(o["p_stop"][0]),
                        "p_burst_raw": float(o0["p_target"][0]),
                        "er_burst": float(o["e_r"][0]), "p_gauss": pg, "p_gauss_stop": sg,
                        "y": int(tgt[n]), "y_stop": int(stp[n]),
                        "r_real": float(rew / risk if tgt[n] else (-1.0 if stp[n] else mark_r)),
                        "lead_group": bool(state["lead_group"].iat[i, j])})
    return pd.DataFrame(out)


def ga_calibration_scores(cal: pd.DataFrame, y: str = "y", models: Sequence[str] = ("p_burst", "p_gauss")) -> pd.DataFrame:
    """Brier score, log loss and Brier skill against the base rate (the base rate is in-sample, which flatters it)."""
    if cal.empty:
        return pd.DataFrame()
    yv = cal[y].to_numpy(float)
    base = float(yv.mean())
    bs0 = float(np.mean((base - yv) ** 2))
    rows = [{"model": "Base rate (every signal gets the average)", "mean_p": base, "brier": bs0,
             "log_loss": float(-np.mean(yv * np.log(max(base, 1e-6)) + (1 - yv) * np.log(max(1 - base, 1e-6)))),
             "skill": 0.0}]
    names = {"p_burst": "Burst model (gamma-Poisson)", "p_gauss": "Random walk (Gaussian closes)",
             "p_burst_raw": "Burst model, closes only (no touch correction)",
             "p_burst_stop": "Burst model (gamma-Poisson)", "p_gauss_stop": "Random walk (Gaussian closes)"}
    for m in models:
        p = np.clip(cal[m].to_numpy(float), 1e-6, 1 - 1e-6)
        okm = np.isfinite(p)
        bs = float(np.mean((p[okm] - yv[okm]) ** 2))
        rows.append({"model": names.get(m, m), "mean_p": float(p[okm].mean()), "brier": bs,
                     "log_loss": float(-np.mean(yv[okm] * np.log(p[okm]) + (1 - yv[okm]) * np.log(1 - p[okm]))),
                     "skill": 1 - bs / bs0 if bs0 > 0 else np.nan})
    return pd.DataFrame(rows)


def ga_reliability(cal: pd.DataFrame, col: str, y: str = "y", bins: int = 10) -> pd.DataFrame:
    """Predicted vs realized by bins of the prediction (quantile bins, so each holds the same count)."""
    if cal.empty or cal[col].nunique() < 3:
        return pd.DataFrame()
    q = pd.qcut(cal[col].rank(method="first"), bins, labels=False)
    g = cal.assign(_b=q).groupby("_b")
    return pd.DataFrame({"predicted": g[col].mean(), "realized": g[y].mean(), "n": g.size()}).reset_index(drop=True)


# ─────────────────────────────────────────────────────────────────────────────
# Lab hooks
# ─────────────────────────────────────────────────────────────────────────────
def ga_brief_points(ticker: str, latest: pd.DataFrame) -> Tuple[int, List[str]]:
    """Points and badges for Brief > Setups (su_rank): +1 leading group, +1 asymmetric now,
    -1 extended. latest = name_table(state, only_leading=False)."""
    if latest is None or latest.empty or ticker not in set(latest["ticker"]):
        return 0, []
    r = latest[latest["ticker"] == ticker].iloc[0]
    pts, badges = 0, []
    if bool(r["lead_group"]):
        pts += 1
        badges.append(f"Leading group #{int(r['group_rank'])}" if pd.notna(r["group_rank"]) else "Leading group")
    if r["status"] == "Asymmetric now":
        pts += 1
        badges.append(f"Asymmetric {r['rr']:.1f}:1")
    elif r["status"] == "Extended":
        pts -= 1
        badges.append(f"Extended {r['ext_atr']:.1f} ATR")
    return pts, badges


def ga_split_labels(events: pd.DataFrame, state: Dict[str, Any], date_col: str = "date",
                    ticker_col: str = "ticker") -> pd.DataFrame:
    """Setup ledger splits, read on each event's signal date: ga_group (Leading group / Middle /
    Lagging group by group-strength percentile, top_pct and bottom third) and ga_rr (R:R bucket)."""
    ev = events.copy()
    gp, bk = state["group_pct"], state["rr_bucket"]
    di = gp.index.get_indexer(pd.to_datetime(ev[date_col]), method="ffill")
    ci = gp.columns.get_indexer(ev[ticker_col])
    ok = (di >= 0) & (ci >= 0)
    g = np.full(len(ev), np.nan)
    b = np.full(len(ev), -1)
    g[ok] = gp.to_numpy()[di[ok], ci[ok]]
    b[ok] = bk.to_numpy()[di[ok], ci[ok]]
    top = 1 - state["top_pct"]
    ev["ga_group"] = np.where(~np.isfinite(g), "No group read", np.where(g > top + 1e-12, "Leading group",
                              np.where(g <= 1 / 3, "Lagging group", "Middle")))
    ev["ga_rr"] = [GA_RR_BUCKETS[int(x)] if x >= 0 else "—" for x in b]
    return ev


def ga_params(ss: Any = None, key: str = "ga") -> Dict[str, Any]:
    """The tab's control values (from st.session_state or any dict), with defaults, as ga_state keywords.
    Lets the Brief, the ledger and the Command tab read exactly what the Group leaders tab shows."""
    ss = ss if ss is not None else {}
    g = lambda k, d: ss.get(f"{key}_{k}", d) if hasattr(ss, "get") else d
    return {"min_group": int(g("ming", GA_MIN_GROUP)), "top_pct": float(g("top", int(GA_TOP_PCT * 100))) / 100,
            "rs_min": float(g("rs", GA_RS_MIN)), "rr_min": float(g("rr", GA_RR_MIN)),
            "max_risk": float(g("risk", GA_MAX_RISK_ATR)), "ext_max": float(g("ext", GA_EXT_MAX)),
            "cap_overhead": bool(g("cap", False))}


def ga_ledger_panels(state: Dict[str, Any]) -> Dict[str, pd.DataFrame]:
    """Name x date panels for the Setup ledger's event features (all read on the signal date)."""
    f32 = lambda df: df.astype("float32")
    out = {"ga_gpct": f32(state["group_pct"]), "ga_rr": f32(state["rr"].where(np.isfinite(state["rr"]))),
           "ga_bucket": f32(state["rr_bucket"].astype(float)),
           "ga_leader": f32((state["leader"] & state["liquid"]).astype(float).where(state["rs"].notna()))}
    try:                                               # leadership entropy: one value per date, broadcast to every name
        ent = ga_entropy_cached(state)
        idx, cols = state["rs"].index, state["rs"].columns
        wide = lambda s_: pd.DataFrame(np.repeat(s_.reindex(idx).to_numpy(float)[:, None], len(cols), axis=1),
                                       index=idx, columns=cols).astype("float32")
        out.update({"lead_conc": wide(ent["conc_s"]), "lead_conc_pct": wide(ent["pct"]), "lead_eff_groups": wide(ent["eff_s"])})
        # +1 for a top-group name while leadership is narrow, -1 for a bottom-group name while it's narrow (and the
        # reverse when broad): a positive coefficient means group strength matters more when leadership is narrow
        out["ga_x_lead"] = f32((state["group_pct"] - 0.5) * (out["lead_conc_pct"].astype(float) - 0.5) * 4)
    except Exception:
        pass
    return out


def ga_rule_labels(gpct: pd.Series, bucket: pd.Series, leader: pd.Series, top_pct: float) -> pd.Series:
    """Setup ledger split for the rule itself."""
    lead = gpct > (1 - top_pct) + 1e-12
    rule = lead & (bucket == 0) & (leader == 1)
    return pd.Series(np.where(rule, "The rule: RS leader, leading group, R:R 3+",
                              np.where(leader == 1, "RS leader, other", np.where(leader == 0, "Not an RS leader", "n/a"))),
                     index=gpct.index)


def ga_group_labels(gpct: pd.Series, top_pct: float) -> pd.Series:
    return pd.Series(np.where(~np.isfinite(gpct), "n/a", np.where(gpct > (1 - top_pct) + 1e-12, "Leading groups",
                              np.where(gpct <= 1 / 3, "Lagging groups (bottom third)", "Middle groups"))), index=gpct.index)


def ga_rr_labels(bucket: pd.Series) -> pd.Series:
    b = bucket.to_numpy(float)
    return pd.Series([GA_RR_BUCKETS[int(x)] if np.isfinite(x) and 0 <= x < len(GA_RR_BUCKETS) else "n/a" for x in b],
                     index=bucket.index)


# ─────────────────────────────────────────────────────────────────────────────
# Demo panel (group factors, so the demo has groups worth finding)
# ─────────────────────────────────────────────────────────────────────────────
def ga_demo_panel(groups: pd.Series, n: int = 900, seed: int = 11, end=None) -> Dict[str, pd.DataFrame]:
    """Synthetic OHLCV with a market factor, a persistent group factor whose drift wanders, and
    idiosyncratic noise. Groups really do take turns leading."""
    rng = np.random.default_rng(seed)
    g = pd.Series(groups).dropna().astype(str)
    names = list(g.index)
    grp = sorted(set(g.values))
    idx = pd.bdate_range(end=pd.Timestamp(end) if end is not None else pd.Timestamp.today().normalize(), periods=n)
    mkt = rng.normal(0.0003, 0.009, n)
    gdrift = {k: np.cumsum(rng.normal(0, 0.00006, n)) + rng.normal(0, 0.0004) for k in grp}
    gret = {k: gdrift[k] + rng.normal(0, 0.008, n) for k in grp}
    O, H, L, C, V = {}, {}, {}, {}, {}
    for t in names:
        beta = rng.uniform(0.7, 1.4)
        vol = rng.uniform(0.012, 0.03)
        r = beta * mkt + gret[g[t]] + rng.normal(0, vol, n)
        c = 30 * math.exp(rng.normal(0, 0.6)) * np.exp(np.cumsum(r))
        pc = np.r_[c[0], c[:-1]]
        o = pc * np.exp(rng.normal(0, vol * 0.3, n))
        span = np.abs(rng.normal(0, vol * 0.7, n))
        H[t] = np.maximum(o, c) * np.exp(span * rng.random(n))
        L[t] = np.minimum(o, c) * np.exp(-span * rng.random(n))
        O[t], C[t] = o, c
        V[t] = rng.integers(300_000, 3_000_000, n) * 1.0
    mk = lambda d: pd.DataFrame(d, index=idx)
    return {"open": mk(O), "high": mk(H), "low": mk(L), "close": mk(C), "volume": mk(V)}


# ─────────────────────────────────────────────────────────────────────────────
# UI
# ─────────────────────────────────────────────────────────────────────────────
GA_GUIDE = """
**The rule:** seek out group strength, then look for asymmetric risk-to-reward spots in RS names.

**Group strength** (0–100, per industry or theme with at least the minimum members): 40% the members'
median RS rating ranked across groups, 20% the 20-session change in that rank, 20% breadth (share above
the 50-day), 20% depth (share with RS 80+). Each piece is a percentile across groups that day. Leading =
the top slice of groups. The map puts group RS rank across and its 20-session change up, like a relative
rotation graph: Leading (strong, rising), Weakening (strong, slipping), Improving (weak, rising), Lagging.

**RS leader:** RS rating at the threshold or above and above its own group's median RS. RS rating =
0.4·C/C63 + 0.2·C/C126 + 0.2·C/C189 + 0.2·C/C252, ranked 1–99 across the loaded universe.

**Asymmetry** (in ATR(14)): risk = distance to the nearest support at least 0.5 ATR below the close
(5-day low, 10-day low, 21 EMA, 50-day; stop 0.1 ATR under it). Reward = the name's own 75th-percentile
20-session run-up over the past year, from completed windows only. R:R = reward ÷ risk. Asymmetric = R:R at
the minimum or better, risk within the cap, and not extended above the 21 EMA. **Buy below** = the highest
price at which the same stop and target still give the minimum R:R and the risk cap: the entry to wait for
instead of chasing.

**Does it pay?** Weekly signals on every RS leader: enter at the next open, stop at the logical stop (a gap
through it fills at the open), out at the close after the hold. Split by leading group and R:R bucket, by
year, with Newey-West t on the date-averaged R. The Setup ledger, with its own exits, is the fuller test;
the same two splits are available to it.

**Burst odds** (gamma-Poisson): a burst is a close-to-close move of at least 1 ATR. Bursts arrive as a Poisson
process whose rate has a gamma prior centred on the name's group (63 sessions of weight), so a thin record is shrunk
toward its group and the number of bursts over the next t sessions is negative binomial. Each burst is up with a
probability that has a beta prior from the group, and moves the name's average up or down burst size. The walk is
absorbed at the target or the stop, giving P(target first by a date), the timing (the k-th burst waits Gamma(k, λ)),
and a burst E[R]: target R times its probability, minus the stop's, plus the expected open position. Both levels move
0.58 daily s.d.s closer so intraday touches count (Broadie-Glasserman-Kou). Does it pay? scores these odds against
what happened, next to a plain random walk on the same levels.

**Leadership entropy:** where the RS leaders (RS at the threshold or above) sit across groups each day, against
how all names are spread across the same groups. *Effective leading groups* is exp(entropy) of the leaders' group
shares (Miller-Madow corrected): 3 means leadership behaves like three equal groups. *Concentration* is the relative
entropy of the leaders' shares from the groups' size shares, minus what random spreading alone would give (about
(groups - 1) / 2N for N leaders), so 0 means leaders are spread like the names and anything above means a few groups
hold more than their size. Both are 5-day averages; the percentile ranks today's concentration against the trailing
year only, so it never uses later data. Narrow leadership = the top third of that year, broad = the bottom third.
The question it answers is whether the rule pays more when leadership is narrow: the replay splits the rule's edge
by regime, and the Setup ledger has the same split (and the regime alone) with its own exits.

**Limits:** RS and breadth use the loaded universe, not every US stock. The reward estimate assumes the
name's past run-ups are a guide; it is a target, not a forecast. Group labels come from the industry or
theme map; unmapped names get no group read.
"""


def _ga_burst_panel(S, BS, pick: str, key: str, touch_on: bool, tile, tiles, show) -> None:
    """One name: P(target before stop) by a date, the timing curve, and burst E[R]."""
    import altair as alt
    import streamlit as st
    st.markdown("**Burst odds:** how likely the target comes before the stop, and how long it takes")
    i = len(S["rs"].index) - 1
    j = S["rs"].columns.get_loc(pick)
    risk, rew = float(S["risk_atr"].iat[i, j]), float(S["reward_atr"].iat[i, j])
    prm = ga_burst_params(BS, i, j)
    if prm is None or not (np.isfinite(risk) and np.isfinite(rew)) or risk <= 0 or rew <= 0:
        st.caption("No burst odds: the name needs a clean stop, a reward estimate and at least "
                   f"{max(20, BS['w'] // 2)} sessions of history.")
        return
    last = S["rs"].index[-1]
    c = st.columns([1, 3])
    lo, hi = (last + pd.offsets.BDay(1)).date(), (last + pd.offsets.BDay(GA_TMAX)).date()
    when = c[0].date_input("By date", (last + pd.offsets.BDay(GA_MFE_H)).date(), min_value=lo, max_value=hi,
                           key=f"{key}_bdate")
    hd = int(min(GA_TMAX, max(1, np.busday_count(last.date(), when))))
    tch = ga_touch_shift(prm["sig"], touch_on)
    o = ga_burst_odds(prm, risk, rew, np.arange(1, GA_TMAX + 1), touch=tch)
    tm = ga_burst_timing(o)
    pg, _ = ga_gauss_odds(prm["sig"], risk, rew, hd, touch=tch)
    pt, ps, er = float(o["p_target"][hd - 1]), float(o["p_stop"][hd - 1]), float(o["e_r"][hd - 1])
    n_up = int(math.ceil(o["U"] / o["up_step"]))
    n_dn = int(math.ceil(o["L"] / o["dn_step"]))
    grate = float(BS["g_rate"].iat[i, j])
    tiles([tile("Bursts on record", f"{int(prm['nu'])} up · {int(prm['nd'])} down",
                f"last {BS['w']} sessions, moves of {BS['k']:g}+ ATR"),
           tile("Burst rate (shrunk to group)", f"{prm['rate'] * 21:.1f} a month",
                f"{prm['p_up']:.0%} up · group {grate * 21:.1f} a month"),
           tile(f"Target first by {when:%b %d}", f"{pt:.0%}", f"stop first {ps:.0%} · random walk {pg:.0%}",
                "#4caf7d" if pt > ps else "#ede8d9"),
           tile("Sessions to target", f"{tm['median']:.0f}" if np.isfinite(tm["median"]) else "—",
                (f"middle half {tm['q25']:.0f}-{tm['q75']:.0f}, if reached within {GA_TMAX}"
                 if np.isfinite(tm["median"]) else f"not reached within {GA_TMAX}")),
           tile(f"Burst E[R] by {when:%b %d}", f"{er:+.2f}R", f"target +{rew / risk:.1f}R · stop -1R · open marked",
                "#4caf7d" if er > 0 else "#e05c5c")])
    cur = pd.DataFrame({"t": np.tile(o["t"], 2), "p": np.r_[o["p_target"], o["p_stop"]],
                        "what": ["target first"] * len(o["t"]) + ["stop first"] * len(o["t"])})
    ch = alt.Chart(cur).mark_line(strokeWidth=2).encode(
        x=alt.X("t:Q", title="Sessions from today"), y=alt.Y("p:Q", title="Probability", axis=alt.Axis(format="%"),
                                                              scale=alt.Scale(domain=[0, 1])),
        color=alt.Color("what:N", scale=alt.Scale(domain=["target first", "stop first"], range=["#4caf7d", "#e05c5c"]),
                        title=None),
        tooltip=["t:Q", "what:N", alt.Tooltip("p:Q", format=".1%")])
    rule = alt.Chart(pd.DataFrame({"t": [hd]})).mark_rule(color="#f5a623", strokeDash=[4, 4]).encode(x="t:Q")
    show(ch + rule, 230)
    st.caption(f"Over the last {BS['w']} sessions {pick} had {int(prm['nu'])} up-bursts and {int(prm['nd'])} down "
               f"(close-to-close moves of {BS['k']:g}+ ATR). Shrunk toward its group, that is about "
               f"{prm['rate'] * 21:.1f} bursts a month, {prm['p_up']:.0%} of them up, averaging +{prm['s_up']:.1f} / "
               f"-{prm['s_dn']:.1f} ATR. The target is about {n_up} net up-bursts away and the stop about {n_dn} down-bursts"
               + (" (both moved closer to count intraday touches)." if tch > 0 else ".")
               + " The random-walk figure uses the same levels with ordinary daily moves, for comparison.")


def _ga_burst_calibration_panel(S, BS, key: str, cache, csig, h: int, start_year, tile, tiles, show) -> None:
    """Does it pay? Were the burst odds right, and does burst E[R] sort realized R?"""
    import altair as alt
    import streamlit as st
    st.markdown("---")
    st.markdown(f"**Do the burst odds hold up?** Each weekly RS-leader signal gets the model's P(target before stop "
                f"within {h} sessions), scored against what the highs and lows did.")
    go = st.button("Score the burst odds", key=f"{key}_cal_go")
    if not (go or cache.get(f"{key}_cal_sig") == csig):
        st.caption("Up to 3,000 signals, sampled evenly; about 10-20 seconds.")
        return
    if cache.get(f"{key}_cal_sig") != csig or f"{key}_cal" not in cache:
        with st.spinner("Scoring"):
            cache[f"{key}_cal"] = ga_burst_calibration(S, BS, h=h, start=f"{start_year}-01-01", max_n=3000)
        cache[f"{key}_cal_sig"] = csig
    cal = cache[f"{key}_cal"]
    if cal.empty or len(cal) < 50:
        st.info("Too few signals to score.")
        return
    sc = ga_calibration_scores(cal, models=("p_burst", "p_burst_raw", "p_gauss")).set_index("model")
    b_, g_ = sc.loc["Burst model (gamma-Poisson)"], sc.loc["Random walk (Gaussian closes)"]
    tiles([tile("Signals scored", f"{len(cal):,}", f"{cal['date'].nunique()} weekly dates"),
           tile("Target came first", f"{cal['y'].mean():.0%}", f"stop first {cal['y_stop'].mean():.0%}"),
           tile("Burst model said", f"{b_['mean_p']:.0%}", f"random walk said {g_['mean_p']:.0%}"),
           tile("Brier skill vs base rate", f"{b_['skill']:+.1%}", f"random walk {g_['skill']:+.1%}",
                "#4caf7d" if b_["skill"] > max(g_["skill"], 0) else "#ede8d9")])
    st.dataframe(sc.reset_index(), hide_index=True, width="stretch", column_config={
        "mean_p": st.column_config.NumberColumn("average prediction", format="percent"),
        "brier": st.column_config.NumberColumn("Brier (lower is better)", format="%.4f"),
        "log_loss": st.column_config.NumberColumn("log loss", format="%.4f"),
        "skill": st.column_config.NumberColumn("skill vs base rate", format="percent")})
    rb, rg = ga_reliability(cal, "p_burst"), ga_reliability(cal, "p_gauss")
    if len(rb) and len(rg):
        rel = pd.concat([rb.assign(model="Burst model"), rg.assign(model="Random walk")])
        mx = float(max(rel["predicted"].max(), rel["realized"].max(), 0.05)) * 1.1
        diag = alt.Chart(pd.DataFrame({"x": [0, mx], "y": [0, mx]})).mark_line(color="#7a7060", strokeDash=[4, 4]).encode(
            x="x:Q", y="y:Q")
        pts = alt.Chart(rel).mark_line(point=True).encode(
            x=alt.X("predicted:Q", title="Predicted P(target first)", axis=alt.Axis(format="%"), scale=alt.Scale(domain=[0, mx])),
            y=alt.Y("realized:Q", title="Realized", axis=alt.Axis(format="%"), scale=alt.Scale(domain=[0, mx])),
            color=alt.Color("model:N", scale=alt.Scale(domain=["Burst model", "Random walk"], range=["#5b8dee", "#c97d1e"]),
                            title=None),
            tooltip=["model", alt.Tooltip("predicted:Q", format=".1%"), alt.Tooltip("realized:Q", format=".1%"), "n"])
        c1, c2 = st.columns(2)
        with c1:
            st.caption("Reliability: ten equal-sized bins of the prediction. On the dashed line = the odds were right.")
            show(diag + pts, 280)
        q = pd.qcut(cal["er_burst"].rank(method="first"), 5, labels=["lowest", "2", "3", "4", "highest"])
        er = cal.assign(quintile=q).groupby("quintile", observed=True).agg(
            burst_er=("er_burst", "mean"), realized_r=("r_real", "mean"), target_first=("y", "mean"),
            stop_first=("y_stop", "mean"), n=("y", "size")).reset_index()
        with c2:
            st.caption("Burst E[R] as an expected return: signals sorted into fifths by the model's E[R], "
                       "against the R they realized (target, stop, or marked at the close after the hold).")
            show(alt.Chart(er).mark_bar(color="#5b8dee").encode(
                x=alt.X("quintile:N", title="Burst E[R] fifth", sort=["lowest", "2", "3", "4", "highest"]),
                y=alt.Y("realized_r:Q", title="Realized mean R"),
                tooltip=["quintile", alt.Tooltip("burst_er:Q", format="+.2f"), alt.Tooltip("realized_r:Q", format="+.2f"),
                         alt.Tooltip("target_first:Q", format=".0%"), alt.Tooltip("stop_first:Q", format=".0%"), "n"]), 280)
        st.dataframe(er, hide_index=True, width="stretch", column_config={
            "burst_er": st.column_config.NumberColumn("model E[R]", format="%+.2f"),
            "realized_r": st.column_config.NumberColumn("realized R", format="%+.2f"),
            "target_first": st.column_config.NumberColumn("target first", format="percent"),
            "stop_first": st.column_config.NumberColumn("stop first", format="percent")})
    st.download_button("Download scored signals (CSV)", cal.to_csv(index=False), "burst_calibration.csv", "text/csv",
                       key=f"{key}_dl_cal")
    st.caption("The base rate is computed on these same signals, which flatters it; beating it is a fair bar. A day where "
               "the high and low hit both levels counts as the stop. The burst model ignores moves smaller than a burst, "
               "so names that grind higher without big days read low here; the reliability chart shows how much that costs.")


def ga_render_group_asym(P: Dict[str, pd.DataFrame], groups: Optional[pd.Series] = None, themes: Optional[pd.Series] = None,
                      key: str = "ga", cache: Optional[dict] = None,
                      group_maps: Optional[Dict[str, pd.Series]] = None, state_fn=None) -> Dict[str, Any]:
    """Stocks > Group leaders. P = wide OHLCV panels; groups = ticker -> industry; themes optional
    ticker -> theme (or pass group_maps = {label: ticker -> group} to offer several). cache: a dict
    that survives reruns (st.session_state works). state_fn(label, params) -> ga_state(...) lets the
    host memoize the state so other pages reuse it. Returns ga_kpis() for the host's summary tiles."""
    import altair as alt
    import streamlit as st

    cache = st.session_state if cache is None else cache
    C_TEXT, C_MUTED, C_PANEL, C_AMBER, C_GREEN, C_RED = "#ede8d9", "#7a7060", "#0f0f17", "#f5a623", "#4caf7d", "#e05c5c"

    def tile(label, value, sub="", tone=C_TEXT):
        return ("<div style='background:" + C_PANEL + ";border:1px solid #1f1f2a;border-radius:8px;padding:10px 12px'>"
                "<div style='color:" + C_MUTED + ";font-size:11px;letter-spacing:.05em'>" + label + "</div>"
                "<div style='font-size:20px;font-weight:600;margin:3px 0;color:" + tone + "'>" + value + "</div>"
                "<div style='color:" + C_MUTED + ";font-size:11px'>" + sub + "</div></div>")

    def tiles(items):
        cols = st.columns(len(items))
        for col, html in zip(cols, items):
            col.markdown(html, unsafe_allow_html=True)

    def show(ch, h=300):
        st.altair_chart(ch.properties(height=h).configure(background="transparent").configure_axis(
            labelColor=C_TEXT, titleColor=C_MUTED, gridColor="#1f1f2a", domainColor="#2a2a35").configure_legend(
            labelColor=C_TEXT, titleColor=C_MUTED).configure_view(stroke=None), width="stretch")

    # controls
    if group_maps is None:
        group_maps = {"Industry": groups}
        if themes is not None:
            group_maps["Theme"] = themes
    c = st.columns([1.4, 1, 1, 1, 1, 1, 1])
    by = c[0].selectbox("Group by", list(group_maps), key=f"{key}_by")
    min_group = c[1].number_input("Min members", 2, 20, GA_MIN_GROUP, key=f"{key}_ming")
    top_pct = c[2].slider("Leading = top %", 5, 50, int(GA_TOP_PCT * 100), 5, key=f"{key}_top") / 100
    rs_min = c[3].slider("RS at least", 50, 95, GA_RS_MIN, 5, key=f"{key}_rs")
    rr_min = c[4].number_input("R:R at least", 1.0, 10.0, GA_RR_MIN, 0.5, key=f"{key}_rr")
    max_risk = c[5].number_input("Max risk (ATR)", 0.5, 4.0, GA_MAX_RISK_ATR, 0.25, key=f"{key}_risk")
    ext_max = c[6].number_input("Extended above (ATR)", 1.0, 8.0, GA_EXT_MAX, 0.5, key=f"{key}_ext")
    cap = st.toggle("Cap reward at the 52-week high (overhead supply)", False, key=f"{key}_cap",
                    help="Off by default: RS names basing just under their highs are the breakout candidates, "
                         "and capping reward at the high would score them as poor R:R.")
    gmap = group_maps[by]
    params = {"min_group": int(min_group), "top_pct": top_pct, "rs_min": float(rs_min), "rr_min": float(rr_min),
              "max_risk": float(max_risk), "ext_max": float(ext_max), "cap_overhead": bool(cap)}
    sig = (id(P["close"]), P["close"].shape, str(P["close"].index[-1]), by) + tuple(sorted(params.items()))
    if cache.get(f"{key}_sig") != sig or f"{key}_state" not in cache:
        with st.spinner("Scoring groups and setups"):
            cache[f"{key}_state"] = (state_fn(by, params) if state_fn is not None else ga_state(P, gmap, **params))
        cache[f"{key}_sig"] = sig
        cache.pop(f"{key}_ev", None)
        cache.pop(f"{key}_ev_sig", None)
    S = cache[f"{key}_state"]
    k = ga_kpis(S)
    gt = ga_group_table(S)
    nt_all = ga_name_table(S, only_leading=False)
    nt = nt_all[nt_all["lead_group"]] if len(nt_all) else nt_all
    if gt.empty:
        st.warning("No group has enough members with a full year of history. Lower the minimum members or "
                   "load more history.")
        return k
    tiles([tile("Groups ranked", str(k["groups"]), f"as of {pd.Timestamp(k['date']).date()}"),
           tile("Leading groups", str(k["leading_groups"]), ", ".join(k["top_groups"][:3])),
           tile("RS leaders in them", str(k["leaders_in_leading"]), f"RS {rs_min}+ and above their group"),
           tile("Asymmetric now", str(k["asymmetric"]), f"R:R {rr_min:g}+ · risk ≤ {max_risk:g} ATR",
                C_GREEN if k["asymmetric"] else C_TEXT),
           tile("Extended (don't chase)", str(k["extended"]), f"> {ext_max:g} ATR over the 21 EMA",
                C_RED if k["extended"] else C_TEXT)])
    if k["asymmetric"] == 0 and k["leaders_in_leading"]:
        st.caption("No asymmetric spot in the leading groups today: the leaders are either extended or their "
                   "nearest clean stop is too far. The buy-below column shows where each would qualify.")

    with st.expander("Burst odds settings"):
        bc = st.columns(3)
        bk = bc[0].slider("Burst = a close-to-close move of at least (ATR)", 0.5, 2.5, GA_BURST_K, 0.25, key=f"{key}_bk")
        bw = bc[1].select_slider("Burst history (sessions)", [63, 126, 252], GA_BURST_W, key=f"{key}_bw")
        btouch = bc[2].toggle("Count intraday touches (barrier correction)", True, key=f"{key}_btouch",
                              help="The model steps from close to close, but a stop or target is hit by the day's low or "
                                   "high. The Broadie-Glasserman-Kou correction moves both levels 0.58 daily s.d.s closer, "
                                   "which turns a close model into a touch model. On by default.")
    bsig = sig + (float(bk), int(bw))
    if cache.get(f"{key}_Bsig") != bsig or f"{key}_B" not in cache:
        cache[f"{key}_B"] = ga_burst_state(S["P"], S["atr"], S["groups"], k=float(bk), w=int(bw))
        cache[f"{key}_Bsig"] = bsig
        cache.pop(f"{key}_cal", None)
    BS = cache[f"{key}_B"]

    t1, t2, t3, t4, t5 = st.tabs(["Groups", "Setups", "One name", "Does it pay?", "Leadership entropy"])

    with t1:
        mp = gt.assign(level=S["G"]["rank"].iloc[-1].reindex(gt["group"]).values,
                       change=S["G"]["mom"].iloc[-1].reindex(gt["group"]).values)
        mp["label"] = np.where(mp["rank"] <= 6, mp["group"].str.slice(0, 28), "")
        mp["right"] = mp["level"] > 0.7
        base = alt.Chart(mp).encode(
            x=alt.X("level:Q", title="Group RS rank (percentile across groups)", scale=alt.Scale(domain=[0, 1])),
            y=alt.Y("change:Q", title=f"Change in rank, {GA_MOM_N} sessions"))
        pts = base.mark_circle(opacity=0.85, stroke="#09090e").encode(
            size=alt.Size("rs_leaders:Q", title="RS leaders", scale=alt.Scale(range=[30, 900]),
                          legend=alt.Legend(symbolFillColor="#7a7060", symbolStrokeColor="#7a7060")),
            color=alt.Color("quadrant:N", scale=alt.Scale(domain=GA_QUADS, range=[GA_QUAD_COLOR[q] for q in GA_QUADS]),
                            title=None),
            tooltip=["group", "rank", alt.Tooltip("strength:Q", format=".0f"), alt.Tooltip("median_rs:Q", format=".0f"),
                     alt.Tooltip("rank_change:Q", format="+.2f"), alt.Tooltip("breadth:Q", format=".0%"),
                     alt.Tooltip("depth:Q", format=".0%"), "members", "rs_leaders", "asymmetric", "leaders"])
        lab = (base.transform_filter("datum.right").mark_text(align="right", dx=-12, dy=-10, fontSize=11, color=C_TEXT)
               .encode(text="label:N")
               + base.transform_filter("!datum.right").mark_text(align="left", dx=10, dy=-10, fontSize=11, color=C_TEXT)
               .encode(text="label:N"))
        rule_x = alt.Chart(pd.DataFrame({"x": [0.5]})).mark_rule(color="#2a2a35").encode(x="x:Q")
        rule_y = alt.Chart(pd.DataFrame({"y": [0]})).mark_rule(color="#2a2a35").encode(y="y:Q")
        show(rule_x + rule_y + pts + lab, 420)
        st.dataframe(gt[["rank", "group", "leading", "strength", "median_rs", "rank_change", "breadth", "depth",
                         "members", "rs_leaders", "asymmetric", "quadrant", "asymmetric_names", "leaders"]],
                     hide_index=True, width="stretch", column_config={
                         "strength": st.column_config.ProgressColumn(min_value=0, max_value=100, format="%.0f"),
                         "median_rs": st.column_config.NumberColumn("median RS", format="%.0f"),
                         "rank_change": st.column_config.NumberColumn(f"Δ rank {GA_MOM_N}d", format="%+.2f"),
                         "breadth": st.column_config.NumberColumn("% > 50d", format="percent"),
                         "depth": st.column_config.NumberColumn("% RS 80+", format="percent"),
                         "asymmetric_names": "asymmetric now", "leaders": "RS leaders"})
        st.download_button("Download groups (CSV)", gt.to_csv(index=False), "group_strength.csv", "text/csv",
                           key=f"{key}_dl_g")

    with t2:
        scope = st.radio("Show", ["Leading groups only", "All RS leaders"], horizontal=True, key=f"{key}_scope")
        view = nt if scope.startswith("Leading") else nt_all
        stat = st.multiselect("Status", GA_STATUS, default=GA_STATUS[:3], key=f"{key}_stat")
        view = view[view["status"].isin(stat)] if len(view) else view
        if view.empty:
            st.info("No RS leaders match.")
        else:
            bt = ga_burst_table(S, BS, view["ticker"].head(200).tolist(), GA_MFE_H, btouch)
            view = view.merge(bt[[c_ for c_ in ("ticker", "p_target", "burst_er", "days_median") if c_ in bt]],
                              on="ticker", how="left")
            st.dataframe(view[["ticker", "status", "group", "group_rank", "rs", "rs_vs_group", "close", "buy_below",
                               "to_buy_below", "stop", "stop_kind", "risk_atr", "risk_pct", "target", "rr", "p_target",
                               "burst_er", "days_median", "ext_atr", "atr_pct"]], hide_index=True, width="stretch", column_config={
                "p_target": st.column_config.NumberColumn(f"P(target first, {GA_MFE_H}d)", format="percent"),
                "burst_er": st.column_config.NumberColumn(f"burst E[R] {GA_MFE_H}d", format="%+.2f"),
                "days_median": st.column_config.NumberColumn("days to target (median)", format="%.0f"),
                "status": st.column_config.TextColumn(), "group_rank": st.column_config.NumberColumn("group #"),
                "rs": st.column_config.NumberColumn("RS", format="%.0f"),
                "rs_vs_group": st.column_config.NumberColumn("RS vs group", format="%+.0f"),
                "close": st.column_config.NumberColumn(format="%.2f"),
                "buy_below": st.column_config.NumberColumn("buy below", format="%.2f"),
                "to_buy_below": st.column_config.NumberColumn("to buy-below", format="percent"),
                "stop": st.column_config.NumberColumn(format="%.2f"), "stop_kind": "stop at",
                "risk_atr": st.column_config.NumberColumn("risk (ATR)", format="%.2f"),
                "risk_pct": st.column_config.NumberColumn("risk %", format="percent"),
                "target": st.column_config.NumberColumn(format="%.2f"),
                "rr": st.column_config.NumberColumn("R:R", format="%.1f"),
                "ext_atr": st.column_config.NumberColumn("over 21 EMA (ATR)", format="%+.1f"),
                "atr_pct": st.column_config.NumberColumn("ATR %", format="percent")})
            st.download_button("Download setups (CSV)", view.to_csv(index=False), "group_asym_setups.csv", "text/csv",
                               key=f"{key}_dl_s")
            st.download_button("Watchlist: asymmetric now", "\n".join(view.loc[view["status"] == "Asymmetric now",
                               "ticker"]), "asymmetric_now.txt", "text/plain", key=f"{key}_dl_w")
        st.caption("Asymmetric now: R:R and risk inside the limits at today's close. Wait for pullback: a leader in a "
                   "leading group whose R:R is too thin at today's price; buy below is where it would qualify with the "
                   "same stop and target. Extended: too far above the 21 EMA; the stop is far and the target close. "
                   f"P(target first) and burst E[R] come from the burst model over {GA_MFE_H} sessions (One name has the "
                   "full curve; Does it pay? checks whether these odds have been right).")

    with t3:
        pool = nt_all["ticker"].tolist() if len(nt_all) else list(S["rs"].columns)
        pick = st.selectbox("Name", pool, key=f"{key}_pick")
        d = S["rs"].index[-1]
        cl = S["P"]["close"][pick].iloc[-160:]
        lines = {"close": cl, "21 EMA": ga_ema(S["P"]["close"][[pick]], 21)[pick].iloc[-160:]}
        df = pd.DataFrame(lines).rename_axis("date").reset_index().melt("date", var_name="series", value_name="px").dropna()
        lv = []
        for nm, col in (("stop", "stop"), ("buy below", "buy_below"), ("target", "target")):
            v = S[col].at[d, pick]
            if np.isfinite(v):
                lv.append({"level": nm, "px": float(v)})
        line = alt.Chart(df).mark_line().encode(
            x=alt.X("date:T", title=None), y=alt.Y("px:Q", title="Price", scale=alt.Scale(zero=False)),
            color=alt.Color("series:N", scale=alt.Scale(domain=["close", "21 EMA"], range=[C_TEXT, "#5b8dee"]), title=None))
        layers = line
        lv_color = {"stop": C_RED, "buy below": C_AMBER, "target": C_GREEN}
        x_end = df["date"].min()
        for item in lv:
            one = pd.DataFrame([{**item, "date": x_end, "label": f"{item['level']} {item['px']:.2f}"}])
            col = lv_color[item["level"]]
            layers = layers + alt.Chart(one).mark_rule(strokeDash=[5, 4], size=1.5, color=col).encode(
                y="px:Q", tooltip=["level", alt.Tooltip("px:Q", format=".2f")])
            layers = layers + alt.Chart(one).mark_text(align="left", dx=4, dy=-7, fontSize=11, color=col).encode(
                x="date:T", y="px:Q", text="label:N")
        show(layers, 320)
        row = nt_all[nt_all["ticker"] == pick]
        grp = S["groups"].get(pick, "—")
        if len(row):
            r = row.iloc[0]
            st.markdown(
                f"**{pick}** · {grp} (group #{int(r['group_rank']) if pd.notna(r['group_rank']) else '—'}, "
                f"{'leading' if r['lead_group'] else 'not leading'}) · RS {r['rs']:.0f} ({r['rs_vs_group']:+.0f} vs group) · "
                f"**{r['status']}**. Stop {r['stop']:.2f} at the {r['stop_kind']} ({r['risk_atr']:.2f} ATR, "
                f"{r['risk_pct']:.1%}); target {r['target']:.2f} ({r['reward_atr']:.1f} ATR); R:R {r['rr']:.1f}; "
                f"{r['ext_atr']:+.1f} ATR over the 21 EMA."
                + (f" Qualifies at or below {r['buy_below']:.2f} ({r['to_buy_below']:+.1%})." if np.isfinite(r['buy_below']) else ""))
        else:
            st.caption(f"{pick} is not an RS leader today (RS {S['rs'].at[d, pick]:.0f}).")
        _ga_burst_panel(S, BS, pick, key, btouch, tile, tiles, show)
        gs = S["G"]["score"][grp].dropna().iloc[-250:] if grp in S["G"]["score"] else pd.Series(dtype=float)
        if len(gs):
            gdf = pd.DataFrame({"date": gs.index, "strength": gs.to_numpy()})
            st.caption(f"{grp}: group strength, last 250 sessions (0-100; the dashed line marks the leading cutoff "
                       f"today, {S['G']['score'].iloc[-1].quantile(1 - S['top_pct']):.0f})")
            cut = float(S["G"]["score"].iloc[-1].quantile(1 - S["top_pct"]))
            show(alt.Chart(gdf).mark_line(color="#5b8dee", strokeWidth=2).encode(
                x=alt.X("date:T", title=None, axis=alt.Axis(format="%b %y", labelOverlap=True)),
                y=alt.Y("strength:Q", title="Strength", scale=alt.Scale(domain=[0, 100])),
                tooltip=["date:T", alt.Tooltip("strength:Q", format=".0f")])
                + alt.Chart(pd.DataFrame({"y": [cut]})).mark_rule(strokeDash=[4, 4], color=C_MUTED).encode(y="y:Q"), 180)

    with t4:
        c = st.columns([1, 1, 2])
        h = c[0].slider("Hold (sessions)", 5, 40, 20, 5, key=f"{key}_h")
        yrs = sorted(S["rs"].index.year.unique())
        start_year = c[1].selectbox("From year", yrs, index=0, key=f"{key}_y0")
        if c[2].button("Replay weekly signals", key=f"{key}_run") or cache.get(f"{key}_ev_sig") == (sig, h, start_year):
            if cache.get(f"{key}_ev_sig") != (sig, h, start_year) or f"{key}_ev" not in cache:
                with st.spinner("Replaying"):
                    cache[f"{key}_ev"] = ga_event_study(S, h=h, start=f"{start_year}-01-01")
                cache[f"{key}_ev_sig"] = (sig, h, start_year)
            ev = cache[f"{key}_ev"]
            if ev.empty:
                st.info("No signals in the window.")
            else:
                es = ga_edge_summary(ev, h)
                tiles([tile("RS-leader trades", f"{len(ev):,}", f"{ev['date'].nunique()} weekly dates"),
                       tile("The rule's cell", f"{es['rule_mean_R']:+.2f}R", f"{es['rule_trades']:,} trades: leading group, R:R 3+"),
                       tile("Every other leader", f"{es['rest_mean_R']:+.2f}R", f"{es['rest_trades']:,} trades"),
                       tile("Rule minus rest", f"{es['diff_mean']:+.2f}R", f"Newey-West t {es['diff_t']:+.1f} on "
                            f"{es['diff_dates']} dates", C_GREEN if (np.isfinite(es['diff_t']) and es['diff_t'] > 2) else C_TEXT)])
                fmt = {"mean_R": st.column_config.NumberColumn("mean R", format="%+.2f"),
                       "median_R": st.column_config.NumberColumn("median R", format="%+.2f"),
                       "win": st.column_config.NumberColumn(format="percent"),
                       "stopped": st.column_config.NumberColumn("stopped out", format="percent"),
                       "mean_mfe_R": st.column_config.NumberColumn("mean MFE (R)", format="%+.2f"),
                       "nw_t": st.column_config.NumberColumn("NW t", format="%+.1f")}
                st.markdown("**Group × R:R at the signal**")
                st.dataframe(ga_cells(ev, ("group", "rr_bucket"), h), hide_index=True, width="stretch", column_config=fmt)
                st.markdown("**By year** (the rule's cell vs the rest)")
                ev2 = ev.assign(cell=np.where(ev["lead_group"] & (ev["rr_bucket"] == "R:R 3+"), "Rule: leading + R:R 3+",
                                              "Other RS leaders"))
                st.dataframe(ga_cells(ev2, ("year", "cell"), h), hide_index=True, width="stretch", column_config=fmt)
                cum = ev2.groupby(["date", "cell"])["R"].mean().unstack().fillna(0).cumsum().reset_index().melt(
                    "date", var_name="cell", value_name="cumR")
                show(alt.Chart(cum).mark_line().encode(
                    x=alt.X("date:T", title=None), y=alt.Y("cumR:Q", title="Cumulative mean R per weekly date"),
                    color=alt.Color("cell:N", scale=alt.Scale(range=[C_GREEN, "#7a7060"]), title=None)), 260)
                st.download_button("Download trades (CSV)", ev.to_csv(index=False), "group_asym_trades.csv", "text/csv",
                                   key=f"{key}_dl_ev")
                st.caption(f"Each weekly date, every liquid RS leader: entry at the next open, stop at its logical stop "
                           f"(a gap through it fills at the open), out at the close after {h} sessions. Weekly signals "
                           f"overlap when the hold is longer than a week, so the t-stat uses Newey-West lags. Group and "
                           f"R:R are read at the signal date with data through that day only.")
        else:
            st.caption("Press the button to replay. About a second per year of history at 1,800 names.")
        _ga_burst_calibration_panel(S, BS, key, cache, (bsig, h, start_year), h, start_year, tile, tiles, show)

    with t5:
        _ga_entropy_panel(S, key, cache, sig, h, start_year, tile, tiles, show)

    with st.expander("How this works"):
        st.markdown(GA_GUIDE)
    return k


def _ga_entropy_panel(S: Dict[str, Any], key: str, cache, sig, h: int, start_year: int, tile, tiles, show) -> None:
    """Group leaders > Leadership entropy: today's reading, its history, which groups hold the leaders, and whether
    the rule's edge depends on how concentrated leadership is."""
    import altair as alt
    import streamlit as st
    C_TEXT, C_MUTED, C_AMBER, C_GREEN, C_RED, C_BLUE = "#ede8d9", "#7a7060", "#f5a623", "#4caf7d", "#e05c5c", "#5b8dee"
    ent = ga_entropy_cached(S)
    N = ent["N"].dropna()
    if N.empty:
        st.info(f"Fewer than {GA_ENT_MIN_LEADERS} RS leaders on every date. Lower 'RS at least' to read leadership.")
        return
    d = N.index[-1]
    eff, effn, conc, pc = (float(ent[k_].loc[d]) for k_ in ("eff_s", "eff_names", "conc_s", "pct"))
    reg = ga_entropy_regime(pd.Series([pc])).iloc[0]
    T = ga_entropy_table(ent)
    top3, top3_names = float(T["share_leaders"].head(3).sum()), float(T["share_names"].head(3).sum())
    tone = C_AMBER if reg == GA_ENT_REGIMES[0] else (C_BLUE if reg == GA_ENT_REGIMES[2] else C_TEXT)
    pct_txt = (f"concentration in the {pc * 100:.0f}th percentile of its last year" if np.isfinite(pc)
               else "under a year of history for the percentile")
    tiles([tile("Effective leading groups", f"{eff:.1f}", f"{effn:.1f} if leaders were spread like the names"),
           tile("Leadership", reg if reg != "n/a" else "—", pct_txt, tone),
           tile("RS leaders", f"{int(N.loc[d])}", f"RS {ent['rs_min']:g}+ in {int(ent['groups_with'].loc[d])} of "
                f"{int(ent['groups'].loc[d])} groups"),
           tile("Top 3 groups hold", f"{top3:.0%}", f"of the leaders, vs {top3_names:.0%} of the names"),
           tile("Concentration", f"{conc:+.3f}", "nats above a random spread; 0 = spread like the names")])
    span = N.index[-min(len(N), 756):]
    hist = pd.DataFrame({"date": span, "Effective leading groups": ent["eff_s"].reindex(span).to_numpy(),
                         "If leaders were spread like the names": ent["eff_names"].reindex(span).to_numpy()})
    hl = hist.melt("date", var_name="series", value_name="groups").dropna()
    c1, c2 = st.columns(2)
    with c1:
        show(alt.Chart(hl).mark_line(strokeWidth=1.6).encode(
            x=alt.X("date:T", title=None), y=alt.Y("groups:Q", title="Effective number of groups"),
            color=alt.Color("series:N", scale=alt.Scale(range=[C_AMBER, C_MUTED]), title=None,
                            legend=alt.Legend(orient="top", labelLimit=320)),
            tooltip=[alt.Tooltip("date:T"), "series", alt.Tooltip("groups:Q", format=".1f")]).properties(
            title="How many groups the leadership behaves like (5-day average)"), 280)
    with c2:
        pp = pd.DataFrame({"date": span, "pct": ent["pct"].reindex(span).to_numpy()}).dropna()
        band = alt.Chart(pd.DataFrame({"y": [GA_ENT_BROAD, GA_ENT_NARROW]})).mark_rule(color=C_MUTED, strokeDash=[4, 3]).encode(y="y:Q")
        area = alt.Chart(pp).mark_area(color=C_AMBER, opacity=0.35, line={"color": C_AMBER}).encode(
            x=alt.X("date:T", title=None), y=alt.Y("pct:Q", title="Percentile of its trailing year", axis=alt.Axis(format="%"),
                                                  scale=alt.Scale(domain=[0, 1])),
            tooltip=[alt.Tooltip("date:T"), alt.Tooltip("pct:Q", format=".0%")])
        show(alt.layer(area, band).properties(
            title="Concentration percentile (narrow above the top line, broad below)"), 280)
    st.markdown(f"**Where the leaders sit** ({pd.Timestamp(T.attrs.get('date', d)).date()}): groups with the most "
                "leaders first; *over-represented* is the group's share of leaders over its share of names.")
    NC = st.column_config.NumberColumn
    st.dataframe(T.head(25), hide_index=True, width="stretch", height=min(560, 40 + 35 * min(len(T), 25)), column_config={
        "group": st.column_config.TextColumn(width="medium"), "leaders": NC(format="%d"), "names": NC(format="%d"),
        "share_leaders": NC("share of leaders", format="percent"), "share_names": NC("share of names", format="percent"),
        "over": NC("over-represented", format="%.1fx"), "contrib": NC("part of the concentration (nats)", format="%+.3f")})
    st.markdown("**Does the rule pay more when leadership is narrow?** The rule's weekly edge (leading group and "
                "R:R 3+, minus every other RS leader) split by the leadership regime on the signal date.")
    evk = (sig, h, start_year)
    ev = cache[f"{key}_ev"] if cache.get(f"{key}_ev_sig") == evk and f"{key}_ev" in cache else None
    if ev is None:
        if st.button("Replay weekly signals", key=f"{key}_run_ent"):
            with st.spinner("Replaying"):
                ev = ga_event_study(S, h=h, start=f"{start_year}-01-01")
            cache[f"{key}_ev"], cache[f"{key}_ev_sig"] = ev, evk
        else:
            st.caption(f"Uses the same replay as Does it pay? ({h}-session hold, from {start_year}). Press the button, "
                       "or run it there.")
    if ev is not None:
        if ev.empty:
            st.info("No signals in the window.")
            return
        tab, gap = ga_entropy_edge(ev, ent, h)
        tn = tab.set_index("regime")
        row = lambda r_: tn.loc[r_] if r_ in tn.index else None
        items = []
        for r_ in GA_ENT_REGIMES:
            x = row(r_)
            if x is None or not np.isfinite(_n(x["diff"], np.nan)):
                items.append(tile(r_, "—", "too few dates"))
                continue
            items.append(tile(r_, f"{x['diff']:+.2f}R", f"rule minus rest · NW t {x['t']:+.1f} · {int(x['dates'])} dates",
                              C_GREEN if _n(x["t"], 0) > 2 else (C_RED if _n(x["t"], 0) < -2 else C_TEXT)))
        items.append(tile("Narrow minus broad", f"{gap.get('gap', np.nan):+.2f}R" if np.isfinite(gap.get("gap", np.nan)) else "—",
                          f"t {gap.get('gap_t', np.nan):+.1f}" if np.isfinite(gap.get("gap_t", np.nan)) else "",
                          C_GREEN if _n(gap.get("gap_t"), 0) > 2 else C_TEXT))
        tiles(items)
        st.dataframe(tab, hide_index=True, width="stretch", column_config={
            "dates": NC("weekly dates", format="%d"), "rule_trades": NC("rule trades", format="%d"),
            "rule_R": NC("rule mean R", format="%+.2f"), "rest_R": NC("other leaders mean R", format="%+.2f"),
            "diff": NC("rule minus rest", format="%+.2f"), "t": NC("NW t", format="%+.1f")})
        st.caption("A t above 2 in the narrow row and a positive narrow-minus-broad gap would say the rule earns its keep "
                   "mostly when a few groups lead. The regime is read on the signal date from the trailing year only. "
                   "Each regime holds about a third of the dates, so the t's are wider than the full-sample one. The "
                   "Setup ledger tests the same question with its own exits (split: Group leaders rule x leadership), "
                   "and the Simulation tab can use the concentration as an indicator.")



# ═══════════════════════════════════════════════════════════════════════════
#  GROUP LEADERS: shared state for the tab, the Brief, the ledger and Command
# ═══════════════════════════════════════════════════════════════════════════

GA_MAP_LABELS = ("Lab groups (industry, Theme for small ones)", "Industry", "Theme")


def ga_lab_maps(cfg) -> Dict[str, pd.Series]:
    """Group maps offered on the tab. The first is resolve_groups, the same map the Alphas, industry RS split and ranker use."""
    uni = cfg["uni"]
    grp, _ = resolve_groups(uni, int(cfg.get("min_group", 5)))
    u = uni.set_index("ticker")
    return {GA_MAP_LABELS[0]: pd.Series(grp, dtype=object).map(lambda g: g.replace("theme:", "Theme: ")),
            GA_MAP_LABELS[1]: u["industry"].replace("", np.nan),
            GA_MAP_LABELS[2]: u["theme"].replace("", np.nan)}


def ga_lab_state(cfg, ab, label: Optional[str] = None, params: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
    """ga_state on the universe panel, memoized by data, group map and settings. With no label / params it uses what the
    Group leaders tab is set to (session state), so the Brief, the ledger and Command read the same thing the tab shows."""
    if ab is None:
        return None
    ss = st.session_state
    label = label or ss.get("ga_by", GA_MAP_LABELS[0])
    params = params or ga_params(ss, "ga")
    maps = ga_lab_maps(cfg)
    gmap = maps.get(label, maps[GA_MAP_LABELS[0]])
    cols = ab["P"]["close"].columns
    gsig = zlib.crc32(repr(sorted(gmap.dropna().items())).encode())
    key = ("ga_state", str(ab["asof"]), zlib.crc32(",".join(cols).encode()), label, gsig) + tuple(sorted(params.items()))
    return memo(key, lambda: ga_state(ab["P"], gmap, **params), capacity=300)


def render_group_leaders(cfg, ab) -> None:
    if ab is None:
        warnbox("Group leaders needs the universe panel. Load at least 10 names.")
        return
    maps = ga_lab_maps(cfg)
    k = ga_render_group_asym(ab["P"], key="ga", group_maps=maps,
                             state_fn=lambda label, params: ga_lab_state(cfg, ab, label, params))
    if k:
        st.session_state["ga_last"] = {kk: k[kk] for kk in ("leading_groups", "leaders_in_leading", "asymmetric",
                                                             "extended", "top_groups", "groups")}


def su_group_read(cfg, ab, Rk: pd.DataFrame) -> Tuple[pd.Series, pd.Series, pd.Series]:
    """Brief > Setups: points (+1 leading group, +1 asymmetric now, -1 extended), card badges and a short table text."""
    pts = pd.Series(0, index=Rk.index, dtype=float)
    badges = pd.Series([[] for _ in range(len(Rk))], index=Rk.index, dtype=object)
    txt = pd.Series("", index=Rk.index, dtype=object)
    S_ = ga_lab_state(cfg, ab)
    if S_ is None or Rk.empty:
        return pts, badges, txt
    latest = memo(("ga_latest", id(S_)), lambda: ga_name_table(S_, only_leading=False))
    gt = memo(("ga_gt", id(S_)), lambda: ga_group_table(S_))
    grank = dict(zip(gt["group"], gt["rank"])) if len(gt) else {}
    gpct = S_["group_pct"].iloc[-1]
    for t in Rk.index:
        p_, b_ = ga_brief_points(t, latest)
        if t not in set(latest["ticker"]):                 # not an RS leader: still credit a leading group
            g_ = S_["groups"].get(t)
            if g_ is not None and np.isfinite(_n(gpct.get(t), np.nan)) and gpct.get(t) > 1 - S_["top_pct"] + 1e-12:
                p_, b_ = 1, [f"Leading group #{grank.get(g_, 0)}"]
        pts[t], badges[t] = p_, b_
        txt[t] = " · ".join(b_)
    return pts, badges, txt


# ═══════════════════════════════════════════════════════════════════════════
#  SIMULATION
#  Three ways to look forward from the Setup ledger, each honest about what it knows.
#  1. Forward paths (Monte Carlo): the price paths that followed look-alike past signals,
#     rescaled to today's volatility, traded with today's stop, target and trail through
#     lg_label, so the path matters and not just where it ends. A Bayesian bootstrap over
#     the look-alikes gives the uncertainty. Compared with all of the setup's past signals
#     and with random uptrend names under the same rules.
#  2. Indicator model (MCMC): a hierarchical Student-t regression of each signal date's
#     mean R on the indicators, setups pooled within their family, fitted by Gibbs
#     sampling in numpy. The likelihood is tempered by an overlap factor from Newey-West,
#     so overlapping trades don't count as independent evidence.
#  3. Posterior predictive (Bayesian Monte Carlo): the draws from 2 run forward as trades:
#     the chance the edge is real, a Bayesian Kelly that pays for the uncertainty, and an
#     equity fan for the next N trades in which each path keeps its own draw of the edge.
# ═══════════════════════════════════════════════════════════════════════════

SIM_FEATS_DEFAULT = ["rs_rating", "ga_gpct", "ga_rr", "ext8w", "plan_risk_atr", "atr_pct", "n_setups", "breadth50"]
SIM_EXTRA_FEATS = {"spread_bp": "Estimated spread (bp)"}
SIM_NU_GRID = np.array([2.1, 2.5, 3.0, 4.0, 5.0, 6.0, 8.0, 10.0, 15.0, 20.0, 30.0, 50.0, 100.0])
SIM_PRIOR = {"beta_sd": 0.25, "mu_sd": 0.5, "tau_A": 0.25, "s_a0": 1e-3, "s_b0": 1e-3}
SIM_HIST = 260                  # real bars kept ahead of each simulated path (ATR, moving-average trail)
SIM_POOL_MIN = 40               # fewer same-setup look-alikes than this: borrow the family's
SIM_SET_MAX = 2000              # paths per comparison set
SIM_VOL_CLIP = (0.33, 3.0)      # limits on rescaling a past path to today's volatility
SIM_FILE = HERE / "data" / "sim_posterior.parquet"
# Exit plans. "trim" follows the TraderLion school: sell part into strength at the target, raise the stop on the
# rest (breakeven), let it run on a moving-average close (10/21-day EMA, or the 50-day), and cut trades that aren't
# working. Kullamaggie: 1/3 to 1/2 off after 3-5 days, stop to breakeven, trail the 10 or 20-day. Kell (TraderLion
# webinar): 1/4 to 1/2 off at 3-5R in the first 3-5 days, breakeven on follow-through, trail the 10/20 EMA.
SIM_PLANS = {"trim": "Trim at the target, raise the stop, trail the rest (TraderLion)", "ledger": "The ledger's exits"}
SIM_TRIM_FRACS = {"1/4": 0.25, "1/3": 1.0 / 3.0, "1/2": 0.5}
SIM_TRIM_STOPS = {"be": "breakeven", "lock": "+0.5R", "keep": "the initial stop"}
SIM_TRIM_STOP_R = {"be": 0.0, "lock": 0.5, "keep": np.nan}
SIM_RUNNERS = {"ema10": "Close under the 10-day EMA", "ema21": "Close under the 21-day EMA",
               "sma50": "Close under the 50-day SMA", "chandelier": "Chandelier (high - k ATR, the ledger's k)",
               "signals": "Exit signals: a close under the 10-day EMA, a distribution day or a climax"}
SIM_RUNNER_SHORT = {"ema10": "10-day EMA", "ema21": "21-day EMA", "sma50": "50-day SMA", "chandelier": "chandelier",
                    "signals": "exit signals"}
SIM_RUNNER_SPEC = {"ema10": ("ma", 10, "ema"), "ema21": ("ma", 21, "ema"), "sma50": ("ma", 50, "sma"),
                   "chandelier": ("chandelier", 21, "sma"), "signals": ("ma", 10, "ema")}
# Exit signals (the "signals" runner): the first of a close under the 10-day EMA (ma_closes in a row), a distribution
# day (down at least dist_drop % on at least dist_vol x the average volume of the 50 sessions before it) or a climax
# (a close at least climax_ext % over the 50-day SMA). Each ends the trade at that close.
SIM_SIG_DEFAULT = {"dist_drop": 3.0, "dist_vol": 1.5, "climax_ext": 20.0}
SIM_SIG_CODES = {1: "distribution day", 2: "climax", 3: "distribution day and climax"}
SIM_FAIL_MODES = {"once": "at that close only", "every": "at any close from then on"}
